INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tutturdum Hüzünleri Tenime', 'tutturdum-huzunleri-tenime-kamil-soylemez-jyrnw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Tutturdum hüzünleri 

Sevda teri rüzgarına

Koyverdim kilimin dört ucunu 

Sen aşk,sevda azgın sularına

Yalvardım, yakardım 

Çıkıp,dağbaşlarına

Gel ver istedim elini

Ver geri dönüşsüz bana

Sen kurudu gülüm,soldu

Çıkamam ki dedin,çıkamam

Sen sevda sokağına 

Ne çare sensiz geçen ömüre 

Acılar,işkenceler vurmuş

Bedenim yanıp,kavrulmuş

Senden bana bir acı 

Bir sızı haykırış kalmış

Yalvarsam,yakarsamda ne çare

Sen yıkık dökük harabe

Bense altında kalmış kör aşık 

Dön desende dönemem 

Çıkmışım yunus gibi sen sevdan seferine', 'Tutturdum hüzünleri  Sevda teri rüzgarına Koyverdim kilimin dört ucunu  Sen aşk,sevda azgın sularına Yalvardım, yakardım  Çıkıp,dağbaşlarına...', ARRAY['Türk Edebiyatı','Şiir','Kamil Söylemez']::text[], 8.5, '{"poet":"Kamil Söylemez","poet_slug":"kamil-soylemez","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/tutturdum-huzunleri-tenime-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mevsimler', 'mevsimler-tunahan-ermihan-5h6m6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben her bahar çiçek açarım

Hasretin kara kış olur

Bağrımda hep ayaz

Ben her yaz meyve veririm

Sözlerin haşarat olur

Ziyan olur hayallerim

Ben her sonbahar yaprak dökerim

Ateş olur bakışların

İçten içe kor gibi yanar tüm emeklerim

Ben her kış beyazlara boyanırım

Kara bir kabus olur gidişin

Kana bulanır beyaz yüreğim', 'Ben her bahar çiçek açarım Hasretin kara kış olur Bağrımda hep ayaz Ben her yaz meyve veririm Sözlerin haşarat olur Ziyan olur hayallerim Be...', ARRAY['Türk Edebiyatı','Şiir','Tunahan Ermihan']::text[], 8.5, '{"poet":"Tunahan Ermihan","poet_slug":"tunahan-ermihan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/mevsimler-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Dal', 'bir-dal-ozan-ozel-8iiwk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yüreğim bir dala kondu 

Dosdoğru ve sağlam 

Yaprakları dört mevsim yeşil 

Çiçekleri aşk kokan 

O dal sensin... 

Hopladım, zıpladım 

Kırılmadın... 

Beni taşımayı bildin 

Sağol sevgilim...', 'Yüreğim bir dala kondu  Dosdoğru ve sağlam  Yaprakları dört mevsim yeşil  Çiçekleri aşk kokan  O dal sensin...  Hopladım, zıpladım  Kırılmad...', ARRAY['Türk Edebiyatı','Şiir','Ozan Özel']::text[], 8.5, '{"poet":"Ozan Özel","poet_slug":"ozan-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/bir-dal-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevin Arkadaşlar', 'sevin-arkadaslar-seyhan-sevgili-tmtik', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sevin arkadaşlar,sevin,''''korkmayın! ''''.

Öyle rastgele değil tabi, herkes için herşey feda edilmez.

Kaçmayın! Acısıda güzeldir sevdanın.

İnanın ben yaşadığımı ölümü istediğimde bildim.

Öyle ısındımki yaşamaya,acı çekmeye...

Bir şeyler öğrendim hep,her aşkta biraz daha hafifledi ayrılıklar.

Boşver demeyi,şükür etmeyi öğrendim.

Sevin arkadaşlar,sevin,''''korkmayın! ''''.', 'Sevin arkadaşlar,sevin,''''korkmayın! ''''. Öyle rastgele değil tabi, herkes için herşey feda edilmez. Kaçmayın! Acısıda güzeldir sevdanın. İnan...', ARRAY['Türk Edebiyatı','Şiir','Seyhan Sevgili']::text[], 8.5, '{"poet":"Seyhan Sevgili","poet_slug":"seyhan-sevgili","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sevin-arkadaslar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öyle Bir Şey', 'oyle-bir-sey-mustafa-sami-mjavk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Aşk öyle bir şey ki 

Tutkusu insanı boğar 

İnsan aşık oldu mu 

İçi içine sığmaz 

Arzusu insanı kamçılar 

Gözü hep onu arar 

Dili hep onu sorar 

İnsan aşık oldu mu 

Irmak olur çağlar 

Serap görür ağlar', 'Aşk öyle bir şey ki  Tutkusu insanı boğar  İnsan aşık oldu mu  İçi içine sığmaz  Arzusu insanı kamçılar  Gözü hep onu arar  Dili hep onu sor...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Sami']::text[], 8.5, '{"poet":"Mustafa Sami","poet_slug":"mustafa-sami","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/oyle-bir-sey-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahar Gibi Bir Şey', 'bahar-gibi-bir-sey-mustafa-sami-6z56k', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çimen yeşil

Çiçekler çeşit çeşit

Kuşlar ötüyor

Gökyüzünde güneş de var

Çocuklar çimenlerde yuvarlanıyor

Kalpleri sevgiyle coşuyor

Ne güzel! 

Biz çocukların hayatı böyle işte

Bahar gibi bir şey…', 'Çimen yeşil Çiçekler çeşit çeşit Kuşlar ötüyor Gökyüzünde güneş de var Çocuklar çimenlerde yuvarlanıyor Kalpleri sevgiyle coşuyor Ne güzel! ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Sami']::text[], 8.5, '{"poet":"Mustafa Sami","poet_slug":"mustafa-sami","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/bahar-gibi-bir-sey-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hep Böyleyim…', 'hep-boyleyim-muammer-celik-9413g', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'öyle biriktim, 

öyle çoğaldim ki seninle

öyle yoğunlaştım

öyle doldum ki seninle

dökülmek istiyorum sana...

öyle özledim

öyle hasretim ki 

öyle vurgunum

öyle durgunum ki şimdi

yıkılmış barajlar gibi 

akmak istiyorum sana...

öyle ısındım

öyle yandım ki 

öyle sıcağım

öyle lavlaştım ki

tüm varlığımla

erimek istiyorum sana...

öyle bağlandım

öyle ağladım ki

öyle darlandım

öyle terledim ki

tek tek damlamak istiyorum şimdi sana…

öyle harlandım

öyle hırslandım ki

öyle alevlendim

öyle ateşlendim ki

kor olup içinde yanmak istiyorum şimdi...

öyle mayalandım

öyle hazırım ki sana

fırınında pişip, 

kendime gelmek istiyorum şimdi! ...

BirDeli

26.09.2005', 'öyle biriktim,  öyle çoğaldim ki seninle öyle yoğunlaştım öyle doldum ki seninle dökülmek istiyorum sana... öyle özledim öyle hasretim ki  ö...', ARRAY['Türk Edebiyatı','Şiir','Muammer Çelik']::text[], 8.5, '{"poet":"Muammer Çelik","poet_slug":"muammer-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/hep-boyleyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O An', 'o-an-oguz-bekar-4cvhl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ne cesaretim vardı, yüzün görecek kadar

Ne de dermanım vardı, sesin duyacak kadar

O an, ne ölüm anı ne de bir dirilişti,

O an öyle bir andı, bir meçhule gidişti.

Saatler, dakikalar saniyenin içinde.

Aylar, yıllar, asırlar bir tek günün içinde.

Hevesler, beklentiler hepsi başka biçimde.

O an, öyle bir andı, bir mezara girişti.

Söylenecek çok şey var, söyleyemez susardım.

Sessiz çığlıklarıma bir tercüman arardım.

Ellerim kenetlenir, hep yerlere bakardım.

O an, öyle bir andı, var iken bir bitişti.

Tabip dindiremezdi benim yaman sızımı.

Çaldım da duyulmadı, kırık gönül sazımı.

Anlamaya başladım aşıkların sırrını

O an, öyle bir andı, bir kapıdan geçişti.

Oysa ne hayallerim vardı geçen zamanda.

Keder, tasa bilmezdim yaz yaşardım hazanda.

Ümitlerim savruldu, bir kış vakti, boranda.

O an, işte o andı, sanki bir can verişti.', 'Ne cesaretim vardı, yüzün görecek kadar Ne de dermanım vardı, sesin duyacak kadar O an, ne ölüm anı ne de bir dirilişti, O an öyle bir andı,...', ARRAY['Türk Edebiyatı','Şiir','Oğuz Bekar']::text[], 8.5, '{"poet":"Oğuz Bekar","poet_slug":"oguz-bekar","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/o-an-32-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstasyon', 'i-stasyon-hilal-sakar-eadg4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir gece vakti geldim bu istasyona,

Şehre yağmur yağıyordu.

Sevindi beni görenler,

Oysa ben ağlıyordum.

Beni bekliyordu istasyon,

Kucakladı beni.

Bense çekildim köşeye.

Yabancı gibi.

Sevdim zamanla onu,

Gecem günüm onla.

Hep gitmek istedimde,

Bırakıp gidemedim.

Doldu boşaldı istasyon,

Bende izledim.

Kavuşanlarla sevindim,

Kalanlarla özledim.

Üşüdüm istasyonun soğuğunda,

Herkes kendi kovuğunda.

Gelip giden olduda,

Onlarla gitmedim.

Güzel bir güz günü açtım gözlerimi istasyonda,

Issızlığa inat atılıyordu adımlar.

Sarsıldı istasyon,irkildim,

Şaşırıp:Bu kim dedim.

Aydınlandı tüm istasyon,

Gözlerinin ışığı vurdu.

Dökülen yapraklara,soğuk kaldırımlara,

Ordan bana.

Isındı istasyon,

Isındı ruhum.

Yanına geldimde,

Konuşamıyordum.

Söz veremedim,

Kalbine giremedim.

Sustum sen giderken,

Kal diyemedim.

Senle uğurladım bu istasyondan,

Umutları,aramaları,sevdaları.

Sen yoksan eğer,

Onlarda olmasınlar dedim.

Hala biri varda istasyonda,

Ben diyemedim.

Güzle geldin ama,

Onla gitmedin.

Güz ayrıldığımız gündür,

Gözyaşlarımın hepsi sende.

Eğer beni sevseydin,

Gitmezdin sende.

Bekliyorum bu istasyonda,

Beni alıp geleceğin günü.

Görürmüyüm dersin,

İstasyonun güldüğünü.

     yağmurmah 2005', 'Bir gece vakti geldim bu istasyona, Şehre yağmur yağıyordu. Sevindi beni görenler, Oysa ben ağlıyordum. Beni bekliyordu istasyon, Kucakladı ...', ARRAY['Türk Edebiyatı','Şiir','Hilal Şakar']::text[], 8.5, '{"poet":"Hilal Şakar","poet_slug":"hilal-sakar","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/istasyon-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arınma', 'arinma-zati-erbas-q19b6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'saman sarısı.

telefon direkleri.

kuşlar.

şarkılar.

yol,yol kazılmış toprak.

yaprak,

yaprak

bulut.

havada,

ayrılık kırmızısı.

tellerde güneş

ufuk çizgisiydi yüzün; 

göz yaşınla yıka 

beni', 'saman sarısı. telefon direkleri. kuşlar. şarkılar. yol,yol kazılmış toprak. yaprak, yaprak bulut. havada, ayrılık kırmızısı. tellerde güneş ...', ARRAY['Türk Edebiyatı','Şiir','Zati Erbaş']::text[], 8.5, '{"poet":"Zati Erbaş","poet_slug":"zati-erbas","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/arinma-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oğulcan” a Masal', 'ogulcan-a-masal-kadircan-keskinbora-9wwmf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Atalarımın izinden

Dağ, tepe, kayalar aştım

Ab – i hayat çeşmesinden

Kana kana sular ictim.

Keçi yolları, patika, 

Soşe, asfalt, otobanlar

Tünel, viyadük, geçcitler

Sürüyle köprüler geçtim.

Ağri Daği’nı tam yedi

Kaf’ı on adımda aştım,

Düzlükte duran çakıla

Ayağım takıldı uçtum.

Yedi başlı ejderhayı,

Üç darbede yere serip

Kaf’ın arkasından suyu 

Fiskiyeye sürüp saçtım.

Yorgun argın eve geldim.

“Oğul”dan geldi bir soru:

“Insan nasıl adam olur? ”

Zoru gördüm, hemen kaçtım.', 'Atalarımın izinden Dağ, tepe, kayalar aştım Ab – i hayat çeşmesinden Kana kana sular ictim. Keçi yolları, patika,  Soşe, asfalt, otobanlar T...', ARRAY['Türk Edebiyatı','Şiir','Kadircan Keskinbora']::text[], 8.5, '{"poet":"Kadircan Keskinbora","poet_slug":"kadircan-keskinbora","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ogulcan-a-masal-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece ve Özlem', 'gece-ve-ozlem-oguz-bekar-agmwa', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gecenin karanlığı çökmüş yine odama

Hasret, kasvet birleşmiş, sinmiş bacaya, dama

Buğusunda yazarım güzel ismini cama

Gözlerim yıldızlarda, yar yolunu bekliyor.

Anılar gelir geçer zihnimin köşesinden

Dilimde yanık türkü, kan damlar hecesinden.

Beni biçare koyan dertlerin cümlesinden

Yanmış zavallı gönlüm, bir damla su bekliyor.

Karşı dağ yamacında gezer ayın ışığı.

Uzaktaki sevgili, kahredermiş aşığı.

Mevlam kavuşturmuyor aşık ile maşuğu

Gözlerim yorgun düşmüş, düşte onu bekliyor.

Bir muma benzer ömür, bir anda biter söner.

Ne fırtına, boranlar durgun bir suya döner

Hem ağlar hem gülersin, adına denmiş kader

Karakış ortasında gönlüm bahar bekliyor.

İnandım ve bildim ki beni bir ben anlarım.

Şu geçen yıllarıma gençliğime yanarım.

Sanmam ki bir gün gelir hayalinden bıkarım

Ruh bedenden çıksa da Oğuz onu bekliyor.', 'Gecenin karanlığı çökmüş yine odama Hasret, kasvet birleşmiş, sinmiş bacaya, dama Buğusunda yazarım güzel ismini cama Gözlerim yıldızlarda, ...', ARRAY['Türk Edebiyatı','Şiir','Oğuz Bekar']::text[], 8.5, '{"poet":"Oğuz Bekar","poet_slug":"oguz-bekar","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gece-ve-ozlem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Aşk Hikâyesi', 'bir-ask-hik-yesi-ozgur-kokturk-crxj5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir aşk hikâyesi bu

Bütün aşklar gibi sıradan

Bütün aşklar gibi ayrıcalıklı...

Köprüler var bu hikâyede

Düşerken serin sulara

Denizlere sıkılan limonlar...

Ve kurtlar çeşit çeşit

Leş kokulu nefesiyle 

Enseleri yakan...

Bütün isimler var öykümüzde

Kol kanat geren melekler

Quasimodo, Esmeralda; çan kulesinde

Ferhat, Şirin; Amasya yücelerinde

Tristan, İzolde; beyaz elleriyle

Hansel, Gretel; fırk fırk

Koca ağızlı büyükanne bile...

Her masaldan izler taşıyan

Her destandan parçalar

Duyanlar, duymayanlara anlatsınlar...', 'Bir aşk hikâyesi bu Bütün aşklar gibi sıradan Bütün aşklar gibi ayrıcalıklı... Köprüler var bu hikâyede Düşerken serin sulara Denizlere sıkı...', ARRAY['Türk Edebiyatı','Şiir','Özgür Köktürk']::text[], 8.5, '{"poet":"Özgür Köktürk","poet_slug":"ozgur-kokturk","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/bir-ask-hikayesi-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendine İsyan', 'kendine-i-syan-oguz-bekar-7pkw6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hey gidi salak adam, ey aptalın aptalı 

Aklın evvel nerdeydi, kestin bindiğin dalı.

Yıllar yıllar ardından su misali akınca

'' Eyvah ne eşekmişim '' üzülmüşsün aklınca

Bırak bunları bırak, sana pek güzel oldu.

Mutluluğun yerine kadehlere dert doldu.

Şimdi iç o kadehi, bir damlası kalmasın.

Anılarınla ağla, gözyaşın kurumasın.

Hepsi müstehak sana, kendin ettin de buldun.

Amma da erkekmişsin, azcık zor''a mat oldun.

Uykusuz gecelerde dön şimdi sağa sola

Senin işin zor dostum, yakın sonun, hayr''ola

Hayır şerrin içinde seç birinden birini

Ama seçim yaparken ölçüver dirhemini.

Terazi denk olmalı, dirhem okka olmasın

Sonra okkalar bir bir kafana vurulmasın.

En iyisi mi otur bir kayanın dibine.

O taştan kafanı da vur kayanın birine.

Öyle kuvvetli vur ki kıvılcımlar parlasın

Bir kere vur, hızlı vur, o taş kafan patlasın', 'Hey gidi salak adam, ey aptalın aptalı  Aklın evvel nerdeydi, kestin bindiğin dalı. Yıllar yıllar ardından su misali akınca '' Eyvah ne eşekm...', ARRAY['Türk Edebiyatı','Şiir','Oğuz Bekar']::text[], 8.5, '{"poet":"Oğuz Bekar","poet_slug":"oguz-bekar","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kendine-isyan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiir ve Şair', 'siir-ve-sair-oguz-bekar-9fhdg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şiir berrak bir sudur, o suyu içmelisin.

Geçmişinle bugünü, hoşça düşünmelisin.

Kan olup ta, damarda, dolaşmazsa bedende

Ot olur ot yaşarsın, hem dünde hem bugünde.

Önce bağrın yanmalı, dökülmeli gözden yaş.

Kan mürekkep olmalı, akmalı yavaş yavaş

Her hecede bir hissin saklı değilse eğer,

Söyle bana ey şair; Yazdığın neye değer?', 'Şiir berrak bir sudur, o suyu içmelisin. Geçmişinle bugünü, hoşça düşünmelisin. Kan olup ta, damarda, dolaşmazsa bedende Ot olur ot yaşarsın...', ARRAY['Türk Edebiyatı','Şiir','Oğuz Bekar']::text[], 8.5, '{"poet":"Oğuz Bekar","poet_slug":"oguz-bekar","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/siir-ve-sair-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Devrik Kral...', 'devrik-kral-i-brahim-ethem-bingul-lj4pe', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çağlıyorsun her gün içimde

Kendinden emin ve derinden

Sevgin taştıkça kalbimden

Farkında mısın bilmem

Uzaklaşıyorum bedenen senden...

Sanki dokunsam benli yanağına

Bozulacak bu büyülü rüya

Kök saldıkça bende aşk ağacı

Dallarımda yapraklarım korkudan sarardı...

Biter mi hülyam okşasam kömür saçlarını

Devam etsin mahşere aşkınla yoğrulmam

Direnmem artık

Sevgin olmadan yaşayamam...

Sevdanın yüz ölçümü gönül sınırlarımı aştı

Ecesi sensin, sen

Ve ne mutlu bana

Aşkına yenik düşmüş

Devrik kralım ben...

www.iebingül.com', 'Çağlıyorsun her gün içimde Kendinden emin ve derinden Sevgin taştıkça kalbimden Farkında mısın bilmem Uzaklaşıyorum bedenen senden... Sanki ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/devrik-kral-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayata Dair', 'hayata-dair-oguz-bekar-wp5ji', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hayat dediğimiz şey, yalan arkadaş yalan.

Güzellikler bakidir, şu gökkubbede kalan

'' Keşke '' demeden önce yat çimenin üstüne.

Yoksa çok geç kalırsın çimen gelir üstüne.

Yeni doğmuş bir bebek, tutsun parmaklarından

Vücudun sarhoş olsun, büyülü kokusundan.

Gururla sar yavrunu, öp ballı dudağından

Ben seyredeyim sizi, uzağın uzağından', 'Hayat dediğimiz şey, yalan arkadaş yalan. Güzellikler bakidir, şu gökkubbede kalan '' Keşke '' demeden önce yat çimenin üstüne. Yoksa çok geç ...', ARRAY['Türk Edebiyatı','Şiir','Oğuz Bekar']::text[], 8.5, '{"poet":"Oğuz Bekar","poet_slug":"oguz-bekar","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/hayata-dair-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece', 'gece-kemal-varol-kigili-2vrvr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bulutlarımın ardına sakladım onu

Parlak kızıl renklerini verecek bana

Renk renk kuşakların

Topraktan, sudan, yeşilden

Ve belki bir çift gözden geleni

Koynuma çekerim bunları

Açarım, sessiz sedasız döl yatağımı

Ne zamanki alsam bunları koynuma

Uykuya yatarım gibi yatarım yaşamaya

Düşlerle yoğurur,sevgiyle paylaşırım

Çok iyi sır saklarım hani

Nereye kime? 

Yarına, yarınlara,insana

Gizleri,düşleri,utopyaları dolar koynuma

Perde perde olur yanım, yörem

Her biri bir dünya

Hazırım bunları sevgiyle taşımaya

Biliyorum.

Bu gün ne çok verirsen yarının daha güleç olur.

Açarım kollarımı

Tepeden tırnağa çekerim acıları,küskünlükleri

Karanlık,loş,üretkensiz,yosunlaşmış yürekleri.

Onlara bir damla

   Evet bir damla

   Güneş vereceğim

        Aydınlık,

          Berrak 

             Ve sıcak', 'Bulutlarımın ardına sakladım onu Parlak kızıl renklerini verecek bana Renk renk kuşakların Topraktan, sudan, yeşilden Ve belki bir çift gözd...', ARRAY['Türk Edebiyatı','Şiir','Kemal Varol Kiğılı']::text[], 8.5, '{"poet":"Kemal Varol Kiğılı","poet_slug":"kemal-varol-kigili","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/gece-172-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Hüzün Bir Çocuk ve Kurdela', 'bir-huzun-bir-cocuk-ve-kurdela-kemal-varol-kigili-d0yal', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Alışık olmayan bir sesle uyandı

Kendi çocuk rüyalarında

Yüzü koyun yattığı yatağından bir esneme

Belli belirsiz bir şaşkınlık

Bir tanıdık arayan gözlerle

Kollarını usulca doladı boynuna

Sevgiyle sarıp kucaklayanın

Bir genç kız edasıyla kapattı odanın kapısını

Giyinip kuşanmaya ilk heyecanını

Belli belirsiz tatilden koparamayan giysiyi red etti usulca

Alışık olmadığı bir çabuklukla yöneldi dolabına

Bir kopuşun simgesini kuşandı

Minicik ellerine alarak sabunu

Bu kopuşu taçlandırdı sanki açılan muslukla

Tüm telaşını sıyırıp alan sular serpti suratına

Uyanmaya durdu gözkapaklarını ovarak

Yeni bir ilki yaşamanın heyecanı kalbini titretti

Boğazına düğümlenen bir tonla konuşuyor

Şaşkınlığını gizlemeye çalışırken

Belli belirsiz bir isteksizlikle yudumladı çayını

Minik parmakları arasındaki ekmeği 

Tahinli helvaya bandırırken

Gözleri ilişti tabaktaki beyaz peynire

Hiç yemediğini ve tadını dahi bilmediğini

Dillendirdi gülümseyerek

Yanlış bir bilgilendirmenin farkına vararak

Tadını bilmediğini tanımlamaya çalışarak

Küçücük adımlarla yol alırken 

Heyecanın gizleyemiyor

Soru soracakken yanı başındaki araçlara bakarak 

Yol almaya çalışıyordu

Vedalaşma ile karıştı kalabalığa

 Hiç kimseyi aramıyormuş gibi ve

Gideceği yerin farkında olarak 

Kalabalığın ortasında bir yerde 

Durdu etrafına bakındı

Aralarında konuşan anne ve çocuğa 

Belli belirsiz göz atarak çantasına 

Ve üstünü başını yoklamaya koyuldu

Kendi küçük elleriyle,taranmamış saçlarına 

Taktığı tokasını düzeltmeye çalıştı

Yalnızlığını gidermek için yanına gittiğimde

Kafasında anlayamadığım düşüncelerle 

Etrafına bakışları, derin nefes alışları hatırlattı

Özlemli bekleyiş anlarının

Beni görünce törenin başlayacağını belirterek 

Benim gidebileceğimi söyledi

Küçük adımlarla yanından ayrılırken 

Düşüncelerini ne çok öğrenmek istedim.

                                                         (12/09/2005)', 'Alışık olmayan bir sesle uyandı Kendi çocuk rüyalarında Yüzü koyun yattığı yatağından bir esneme Belli belirsiz bir şaşkınlık Bir tanıdık ar...', ARRAY['Türk Edebiyatı','Şiir','Kemal Varol Kiğılı']::text[], 8.5, '{"poet":"Kemal Varol Kiğılı","poet_slug":"kemal-varol-kigili","theme":"Türk Şiiri","is_hero":false,"total_lines":50,"source_url":"https://www.antoloji.com/bir-huzun-bir-cocuk-ve-kurdela-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanak Gamzesi Gülüşün', 'yanak-gamzesi-gulusun-necmi-unsal-vx9qn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bana attığın bir anlık bakışın.

Öyle güzel, öyle bir hoş  zaman ki! 

Tarifi imkansız beni yakışın.

Öyle özel, öyle müthiş;  yaman ki! 

Bir yanak gamzesi tatlı gülüşün.

Benim için öyle kutlu değer ki! 

Sevgi sözlerime dudak büküşün.

Saf düşlerime sis katmış meğer ki! 



6 Temmuz 2004 Salı, Danimarka-Køge 18.24 *6+5', 'Bana attığın bir anlık bakışın. Öyle güzel, öyle bir hoş  zaman ki!  Tarifi imkansız beni yakışın. Öyle özel, öyle müthiş;  yaman ki!  Bir y...', ARRAY['Türk Edebiyatı','Şiir','Necmi Ünsal']::text[], 8.5, '{"poet":"Necmi Ünsal","poet_slug":"necmi-unsal","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yanak-gamzesi-gulusun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalmak', 'kalmak-kemal-varol-kigili-arx2m', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Uçarı bir istekle yol alıyor

Çarka döner düşüncelerin berrak yönleri

Bir yol alır dokunuşlarla inceden

Çınlatır mekanik sesin yankısını

Parçalanmış düşünceler birikir,

Tanımsızlaşır bakışlar.

Ses tonları değişir,

Yakını görmeyen gözler uzaktakine kitlenir

Bir kulağı yüreğinde 

Onulmaz yarayı kaşır sinsice

Çınlayan kahkahalar,uzun konuşmalar

Nefessiz bir pıhtı olur yürek

Ertelenen dokunuşlar özlenir sözcüklerde

Bir yalana dolanır dişilikler ve erkeklikler

Öfke üreten sevgide kristalleşir,dokunuşlar.

Gizil kalmış duygular tutar su başlarını

Ten kokusuna karışır susan dudaklarda,

İçleri ürperten,

şarabın kırmızısı renk olur tendeki dokunuşlara

Bir dokunuş inletir,

Titrer el ayak, tırnaklar

Uzun konuşmanın yankısı kalır cevapsız sorularda.

Ocaktaki sütün ılıklığı yayılır bedenlere 

Her yudumda bir kılçık misali takılır beyinlere

Mekanik sesin tınısı bir bozguna dönmüş,

Gecikmiş sarılmalar yaşanır, doyumsuz dokunuşlar

Yangın yerinde  nefesler tükenir

Bırakır kendini bedenler,küllere bulaşır bakışlar.

Silinir tüm kokular, hazzın gemi azıya aldığı anlar

Bir zelzele yaşatır titreyen bedenlere

Çarka döner ay,yıldızlar

Dakikalarla yarışır dokunuşlar tepeden tırnağa,

Şafağın ışığında gerçeğin perdesi açılır.

Yol alır yürek çarpmaları

İhaneti başlar ayakların

Gergin bedenlerde bir sızı kalır.

                                                                                                                                     (27/05/2005)', 'Uçarı bir istekle yol alıyor Çarka döner düşüncelerin berrak yönleri Bir yol alır dokunuşlarla inceden Çınlatır mekanik sesin yankısını Parç...', ARRAY['Türk Edebiyatı','Şiir','Kemal Varol Kiğılı']::text[], 8.5, '{"poet":"Kemal Varol Kiğılı","poet_slug":"kemal-varol-kigili","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/kalmak-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Buhran', 'buhran-oguz-bekar-vpfsx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ah sigaram nerede, nere koydum paketi? 

Hah işte buradaymış, gel gönlümün illeti

Sihirli dumanınla kapla tüm benliğimi

Unuttur sahte aşkı, unuttur sevdiğimi.', 'Ah sigaram nerede, nere koydum paketi?  Hah işte buradaymış, gel gönlümün illeti Sihirli dumanınla kapla tüm benliğimi Unuttur sahte aşkı, u...', ARRAY['Türk Edebiyatı','Şiir','Oğuz Bekar']::text[], 8.5, '{"poet":"Oğuz Bekar","poet_slug":"oguz-bekar","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/buhran-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizlik', 'sensizlik-serdar-acar-oxkc0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sensizlik denizinde kaybolmuş bir sandalım ben

Hırçın dalgalar alıyor içine acımasızca

Ne zaman dinecek bu fırtına? Nerede bitecek bu yollar? 

Eşlik eden vefakar gözyaşlarım

Gecenin sessizliğinde yoldaşım ay ışığı sadece

Bir de dudaklarımdan dökülen hüzünlü şarkı

Yıldızlar bile yalnız değiller, gülümsüyorlar birbirlerine

Bense bekliyorum aşkı çaresiz sürgünlerde', 'Sensizlik denizinde kaybolmuş bir sandalım ben Hırçın dalgalar alıyor içine acımasızca Ne zaman dinecek bu fırtına? Nerede bitecek bu yollar...', ARRAY['Türk Edebiyatı','Şiir','Serdar Acar']::text[], 8.5, '{"poet":"Serdar Acar","poet_slug":"serdar-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sensizlik-208-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duygu Rüzgarı', 'duygu-ruzgari-yasar-yilmaz-i3cfu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bir şiir yazıyorum sana

hiç bitmesini istemediğim

işyerimdeyim ve boşum

birden sen geldin aklıma

o

ilk tanıştığımız günlerden

hangi gündü bilemiyorum

dalgınımdır ya

aman canım ne önemi var

söylesene ya

güneşli ılık ılık esen bir gündü

benim içimdeyse bir duyguydu esen

rüzgar gibi

fakat sessiz

fakat sakin

derin 

derin

ama ya sen

bilemiyorum neler duyduğunu

dudaklarında 

bir ''ağabi'' sözcüğü

üzülüyorum

içimde biraz sevinç

biraz tedirginlik

sonra

Kordon''a uzanan yoldayız

beraberliğimizin kısa başlangıcı

yürüyüş,bira ve ezan

hiç bitmesin istiyorum

hiç

dinmesin içimdeki rüzgar

ne olur

yalvarıyorum duygularıma

bir aynanın karşısındayım

aynadaki ben daha güçlü

karşısındaki

hayatından memnun bir köle

........ve

ayrılıyoruz baışladığımız yerde

derse gidiyorsun

ah bir bilebilsem neler hissettin

o ilk dersinde

bir şaşkınlık mı? 

yoksa bir yakınlık mı? 

yoksa hiçbir şey duymadın 

ders mi dinledin? 

düşünüyorum

boğazın sularına bakarak

dalgın

dalgın

biraz sonra ise

yaşadığımız yerde

sen sihirli kürede

hep yanımda 

hep içimde

böyle başladı beraberliğimiz

günler, haftalar geçti

herşey yolunda

karşımdasın ama 

gene de sana uzağım

belki fazla şey istiyorum

bilemiyorum

bildiğim tek şey

sensiz olmayı istemiyorum', 'bir şiir yazıyorum sana hiç bitmesini istemediğim işyerimdeyim ve boşum birden sen geldin aklıma o ilk tanıştığımız günlerden hangi gündü bi...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Yılmaz']::text[], 8.5, '{"poet":"Yaşar Yılmaz","poet_slug":"yasar-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":64,"source_url":"https://www.antoloji.com/duygu-ruzgari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarım Kalan Şiir', 'yarim-kalan-siir-oguz-bekar-7v5y4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Zemheri ayazında üşüyen şu ellerim,

Sevdanın defterine yeni bir ağıt yazar.

Ümitsizce nazlanır kalemim, mürekkebim

Nefsine yenik beden yağız toprakta yatar.

Üstünde kartal uçan gönül dağı dumanlı.

Ardında bekleyen yar, ayrılığa dert yanar.

Sanmam biter bu sızı, yıllar geçer sancılı

Gecenin karanlığı gündüze keder saçar

Leyla ve Mecnun gibi aşkı çilede buldum

Yıllardır çekiyorum, Leyla'' larım sahtekar

Medet dedim, dilendim, nice dergaha kondum

Sevdanın tılsımını erenler bana sorar

Oy anam oy yanmışım, sevmişim işte seni

Ateş bir boy yükselmiş, kaynamakta kazanlar

Başlamışım çıkmaya sevda merdivenini

Sırtımda beyaz kefen, kayacak bu ayaklar

Halden anlayanım yok, çaresizim, yalnızım

Gece voltalarımdan usanmış kaldırımlar

Sanırım olacaktır, tez vakit, son durağım,

İsimsiz, kırık taşlı, yol üstünde bir mezar', 'Zemheri ayazında üşüyen şu ellerim, Sevdanın defterine yeni bir ağıt yazar. Ümitsizce nazlanır kalemim, mürekkebim Nefsine yenik beden yağız...', ARRAY['Türk Edebiyatı','Şiir','Oğuz Bekar']::text[], 8.5, '{"poet":"Oğuz Bekar","poet_slug":"oguz-bekar","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yarim-kalan-siir-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık İçin', 'ayrilik-i-cin-yasar-yilmaz-t9x4m', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bazen ayrılıyorsun

haber de vermiyorsun

içim

için için

seni arıyorum

gözümün önünde

hayalinle avunuyorum

düşünceden yorgunum

korkuyorum

geçip giden zamandan

sevgimiz için

zaman çok güçlü

herşeyden güçlü

o

herşeyi yutan

direnelim ona

sevgimizin gücüyle

mutluluğa ermek için', 'bazen ayrılıyorsun haber de vermiyorsun içim için için seni arıyorum gözümün önünde hayalinle avunuyorum düşünceden yorgunum korkuyorum geçi...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Yılmaz']::text[], 8.5, '{"poet":"Yaşar Yılmaz","poet_slug":"yasar-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ayrilik-icin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalbimde Sızlayacaksın Senelerce', 'kalbimde-sizlayacaksin-senelerce-i-lknur-cekici-vvew7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gözlerimden geçtin usul usul

Hücrelerime yayıldın

Sessiz sessiz kalbime aktın

Yaşam buldun bedenimde

Beynimi esir ettin kendine

Tepeden tırnağa sen oldum

Yokluğunda seninle doldum

Nefes alışımda seni soluyor

Baktığım yerde seni görüyorum

Ellerimde her an sıcağını hissediyor

Kulaklarımda yıllardır seni duyuyorum

Yüzüme seni vuruyor

Her öğün sevginle besleniyorum

Hüznünle solan yüzüme

Makyaj diye seni sürüyorum

Ve aslında biliyorum

Kavuşamayacağız gecelerde

Yaşayamayacağız,aşk dan sarhoş cümlelerde

Kalbimde sızlayacaksın senelerce

Hissetsen de beni her zerrende

Gül yüzüne hasret öleceğim

Sensiz geçen günlerimde', 'Gözlerimden geçtin usul usul Hücrelerime yayıldın Sessiz sessiz kalbime aktın Yaşam buldun bedenimde Beynimi esir ettin kendine Tepeden tırn...', ARRAY['Türk Edebiyatı','Şiir','İlknur Çekici']::text[], 8.5, '{"poet":"İlknur Çekici","poet_slug":"i-lknur-cekici","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/kalbimde-sizlayacaksin-senelerce-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dolmuşçunun Günlüğü', 'dolmuscunun-gunlugu-oguz-bekar-zoefe', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yine dellendim bugün, artık gülemiyorum.

Canım sıkkın arkadaş sohbet çekemiyorum.

Gündüzün ortasında geceyi yaşıyorum.

Nedir bu halim bilmem, hiç hoşuma gitmiyor.

İnat verirmiş gibi herkes neşe içinde

Anlamsız kahkahalar, patlar beynim içinde

Şeytan diyor, herkesi, kes pişir tas içinde 

O tasta yahni yapsam, canım yahni çekmiyor.

Saatlerdir arkamda korna çalan şu adam

Eceline susamış, artık atıyor kafam

Levyeyi alsam ele, o beynini dağıtsam

Elbisem kan olacak, kan lekesi çıkmıyor.

Lan terbiyesize bak, nasıl kıza yapışmış

Belli, ailesinden hiç terbiye almamış

Ya da adamakıllı bir dayak atılmamış.

Öldürsem hergeleyi, kodesler çekilmiyor

Bir siz eksiktiniz be, ah ulan aynasızlar

Ne halt edecez şimdi eksik bütün evraklar

Eğer fark edilirse yandı keten helvalar

Kafayı yiyeceğim, sabır bana gelmiyor

Şükür yine atlattık, çakmadılar köfteyi

'' Oğlum muavin topla mangırlarla sikkeyi ''

'' Paralar bozuk olsun, almayayım levyeyi ''

Yolcuları dövecem, velinimet, olmuyor

Kazasız ve belasız bugünü de atlattık.

Nihat'' ın kahvesinde okey atılır artık.

Anam o ses de neydi! Eyvah lastik patlattık.

Ulan yoksam kendimi, kokusu çekilmiyor.

Hırsımı çıkaracak bir tek karım var evde.

İsmi '' Ayı Neriman '' namı vardır her yerde.

Saçlarından tutup ta sürüklesem yerlerde

Allah kahretsin yahu, ona gücüm yetmiyor.', 'Yine dellendim bugün, artık gülemiyorum. Canım sıkkın arkadaş sohbet çekemiyorum. Gündüzün ortasında geceyi yaşıyorum. Nedir bu halim bilmem...', ARRAY['Türk Edebiyatı','Şiir','Oğuz Bekar']::text[], 8.5, '{"poet":"Oğuz Bekar","poet_slug":"oguz-bekar","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/dolmuscunun-gunlugu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hafta Sonu', 'hafta-sonu-musa-oz-vwxl0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Eksilttik birbirimizi aşk ile

Çoğalttık kan ter içinde

Kaşlarımız eğildi, kirpiklerimiz kırıldı

Bir heybe taş döktük

Gül devşirdik bir de yonca

Aylardan aralıktır. Ya da 

Turunç ayı

Yıldız aya çarpa çarpa kırılır büyür

Çocuk çocuğa 

Şiir şiire çarpar büyür

Kalkıp gittik pazar yerine

Toprak doldurduk çantamıza

Biraz deniz, biraz gökyüzü ve bir kızın

Yorgun edalarını 

Ela düşlerini bir çocuğun

Sonra tutup bir şarkı söyledik

Taşlardaki peri kokularına

Yürüyorduk ahmak ıslatan

Bir ıslandı yağmur

Akıp geçtik turuncu anılarla

Üstümüz başımız

Saçak ucu, kuş kanadı

Yüzümüzde hafta sonundan kalma

Bir gülümseme', 'Eksilttik birbirimizi aşk ile Çoğalttık kan ter içinde Kaşlarımız eğildi, kirpiklerimiz kırıldı Bir heybe taş döktük Gül devşirdik bir de yo...', ARRAY['Türk Edebiyatı','Şiir','Musa Öz']::text[], 8.5, '{"poet":"Musa Öz","poet_slug":"musa-oz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/hafta-sonu-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Mektup Kadar...', 'bir-mektup-kadar-ruya-deniz-demir-5g0hk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir mektup kadar yakın

Ve bir ayrılık kadar uzak

Bir güneş kadar sıcak hatta

Hatta bir o kadar ağlamaklı

Yağmur kadar gözlerim…

Bir mektup kadar uzak

Belki bir ayrılık kadar yakın

Zamansız sevişmelerin

Vazgeçilmez hasadında

Sevdaya yazılan bir şiir gibisin

Bir şarkı gibi belki dudaklarımda…

Bir mektup kadar ağlamaklı

Bir gözyaşı gibi iz bırakmış kağıtlara

Belki bir öpücük kondurulmuş ucuna

Rujunun lekesi bulaşmış gibi dudaklarıma

Belki bir o kadar ısrarlı…

Unut gitsin diyeceğim yanlış anlayacaksın

Oysa ki vazgeçemem senden bilirsin

Her şeyde sen varsın

Kalbimin her bir köşesinde

Ağlamaklı, sevgi dolu, ısrarlı…

Bir mektup kadar yazılmış

Bir sevda kadar silinmez

Bir aşk kadar taşkın ve coşkun

Öyle sevgi dolu

Öyle sarmaşık

Belki bir o kadar ayrılmazımsı…

Bildiğin gibi

Mektuplar asla atılmaz

Sen atılmayacak bir mektupsun

İçimde asla solmayacak

Öpücüklerinin izi dudaklarımdan

Bakışların gözlerimden asla silinmeyecek…', 'Bir mektup kadar yakın Ve bir ayrılık kadar uzak Bir güneş kadar sıcak hatta Hatta bir o kadar ağlamaklı Yağmur kadar gözlerim… Bir mektup k...', ARRAY['Türk Edebiyatı','Şiir','Rüya Deniz Demir']::text[], 8.5, '{"poet":"Rüya Deniz Demir","poet_slug":"ruya-deniz-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/bir-mektup-kadar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırmızı akşamlar…', 'kirmizi-aksamlar-ahmet-toper-moxg7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir gün geri dönersem eğer

Elimde güllerden bir demet

Gözlerimde Kırmızı akşamlardan kurtulma bakışlarla

Kabul eder misin tekrar beni? 

Açar mısın aşka mühürlenmiş kalbini

Aralar mısın çürümüş tahta kapılarını? 

Sorgusuz sualsiz

Saklar mısın beni derinliğinde okyanusunun 

Ortak eder misin beni

Eksik kalmış, yarım kalmış sevgine

Yeni bir düzenle 

Yeni bir sevgiyle

Tamamen arınmış 

Yorgun kalbimle…

Kabul eder misin beni?', 'Bir gün geri dönersem eğer Elimde güllerden bir demet Gözlerimde Kırmızı akşamlardan kurtulma bakışlarla Kabul eder misin tekrar beni?  Açar...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Toper']::text[], 8.5, '{"poet":"Ahmet Toper","poet_slug":"ahmet-toper","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kirmizi-aksamlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Veda…', 'veda-ahmet-toper-ndys5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ağlayan zamanın donduğu yerde

Ümidimin, yalnızlığında kaybolduğun anda

Gideceğin yer rüyalarım olmamalıydı

İçimde yarım kalmış kucaklamaların tadı

Gözlerimde ışıltısını arayan dalgın arzular

Hiçbir acı seni kaybetmek kadar zor değil

Hiçbir gözyaşı sana akan ahımdan az değil

Borcum vardı kadere biliyorum

Bana yaşattığını, yaşattıklarımdan ödüyorum

Ümidimin çiçek veremediği kuru toprakta

Yağmursuz bahçelerde soluyorum

Böyle miydi veda edişler…

Böyle miydi sessiz gidişler…', 'Ağlayan zamanın donduğu yerde Ümidimin, yalnızlığında kaybolduğun anda Gideceğin yer rüyalarım olmamalıydı İçimde yarım kalmış kucaklamaları...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Toper']::text[], 8.5, '{"poet":"Ahmet Toper","poet_slug":"ahmet-toper","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/veda-171-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hoşça kal…', 'hosca-kal-ahmet-toper-68ris', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gönlümde tutuklu kaldı adın

Gecelere bırakılmış, saklanmış tadın

Hapsim oldu, zincirlere vuruldu

Garipliğe soyundu bendeki ahın…

Hoşça kal bebeğim

Hoşça kal yaz gecesi

Hoşça kal

Göğsümde bıraktığın boşluğun adı 

Sen oldu…

Aşkım yollara dağıldı…

Yeni bir başlangıcın

Hoşça kal denen sonu

Ela gözlerini 

Düşlerimde kilitli bıraktı

Kaderimin çizdiği karalamalara 

Gücüm yetmez oldu…

Hoşça kal bebeğim

Hoşça kal yaz gecesi

Hoşça kal…', 'Gönlümde tutuklu kaldı adın Gecelere bırakılmış, saklanmış tadın Hapsim oldu, zincirlere vuruldu Garipliğe soyundu bendeki ahın… Hoşça kal b...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Toper']::text[], 8.5, '{"poet":"Ahmet Toper","poet_slug":"ahmet-toper","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/hosca-kal-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sır...', 'sir-neslihan-i-sler-b6tud', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yağmur gecedeydi,,

Gece koynumda

Ben ürperdim

Gök gürlüyordu

Korktum

Sarılacak sığınacak

Liman yoktu

Titredim

Sımsıkı kapadım gözlerimi

Bitmesi için dua ettim

Yokluk 

Gözyaşı olarak aktı 

Ben üşüdüm

Sıcaklık aradım

Buz gibiydi sessizlik

Tir tir titredim

Sonra yağmur

Dindi 

Sır oldu', 'Yağmur gecedeydi,, Gece koynumda Ben ürperdim Gök gürlüyordu Korktum Sarılacak sığınacak Liman yoktu Titredim Sımsıkı kapadım gözlerimi Bitm...', ARRAY['Türk Edebiyatı','Şiir','Neslihan İşler']::text[], 8.5, '{"poet":"Neslihan İşler","poet_slug":"neslihan-i-sler","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sir-74-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevginin çemberinde…', 'sevginin-cemberinde-ahmet-toper-arrem', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir bakmışsın  ki sevgilim

O küçük damlalar gözlerinde okyanus oluvermiş

Sevginin çemberinde

Dalgalara bıraktığım aşkım

Vurmuş kalbinin kıyılarına bir sabah sessizce 

Etrafında telaşlı dolaşan bakışlar sinsice

Göz kırpan uzak yıldızlar

Keskin ve tarafsız suratlar

Suratlar ki anlamsız 

Hiç tatmamışlar…

Elini tutan eller düğüm

Çözülmesi zor olan…

Aşkını izleyen gözler düşman

Yenilmesi güç olan…

Kendisini kandıran dudaklar kor 

Konuşması kırıcı olan…

Ve bir sabah… 

Bir bakmışsın ki sevgilim

O küçük damlalar gözlerinde

Aşkın gözyaşı olmuş

Sevginin çemberinde….

Geri dönmesi imkansız olan…', 'Bir bakmışsın  ki sevgilim O küçük damlalar gözlerinde okyanus oluvermiş Sevginin çemberinde Dalgalara bıraktığım aşkım Vurmuş kalbinin kıyı...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Toper']::text[], 8.5, '{"poet":"Ahmet Toper","poet_slug":"ahmet-toper","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sevginin-cemberinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MEKTUBUMDUR - Anne''me…', 'mektubumdur-anne-me-olgun-ekinci-9oesx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sevgili Anneciğim,						

						

Hani henüz okula başlamadığım,						

Dallarından, gövdesinden inmediğim ve bugün						

Her biri katliama uğrayan DUT ağaçların da						

Daldan dala uzandığım, sıçradığım günlerdi...						

Kendimi tarzan zannettiğim o anlarda sen,						

*Oğlum büyüdüğünde subay olacak* derken						

Bir tarzanın asla subay olamayacağını düşünür,						

Gördüğüm her üniformalıya  -asker -polis-zabıta						

Seni etkiliyorlar diye gizlice kızardım…						

Oysa ilkokula başladığım üçüncü yılda						

En çok yeşil parkalı ağabeyi sevmiştim...						

Gazetelerde gördüğüm o heybetli duruşu						

Deniz''ler gibi kocaman yüreği, Aslan''lar gibi bakışıyla						

İnan''dığı özgürlük türkülerini haykırıyor(lar)  dı…						

Öylesi yeşil parkayı yıllar sonra giyip						

Ve *Üniversiteler Bizimdir* diye haykırırken						

Ve asla bizim olamayan o bilim yuvalarında						

Saldıran, dipçikleyen askerlerin başındaki						

Üniformalınin ben olabileceğimi düşündüğüm de						

Kalem kırdım… Hiçbir üniforma bana yakışmazdı...						

						

Yeşil gözlerine bakarken salaklaşıp						

Dünyanın durduğunu zannettiğim,  aşkım						

Ayşe öğretmenim, Deniz yürekli ağabeye yazdığım						

O şiire neden kızmış, kulağımı çekmişti de						

Yıllar sonra vatan hainliğine devam ettiğini okuduğum						

Nazım duruşuyla şiirleri sevdiren sarı saçlı						

O büyük ustanın sözünü bana yapıştırmıştı…

İşte benim güzel annem

Ben hiçbir üniformayı sevmedim bugüne kadar

Beyaz gelinliğe kavalye olan kravatlı lacilere kadar

Özgürlüğün önündeki en büyük engeldi yüreğime…

Şimdi kırk altılı yaşımda

Üzerimde taşıdığım ve bana yakışmayan

Kenarından, sağından, solundan, ortasından

Velhasıl her yerinden deformasyona başladığını

Koktuğunu, çürüdüğünü, paramparça olduğunu

Görmezden gelmeniz çözümsüzlük üretirken, ama sizce

Ben geceden sabaha ayışığına, yıldızlara tutunmuş

Taşıyamıyorken bu yüklediğiniz anlamsız yükü

Bedenimi tutarken gecenin lacivertinde tutuklu

Yollarken o layık gördüğüz üniformayı size, kızmayın

Bilirim dilin suskun, gözlerin kızar bana en çok

Ve gözlerin konuştuğunda çocuk yüreğim dağlanır...

Dilin kızmaz belki ama ben en çok

Önce senin gözlerinin sıcak sertliğinden

Sonra da Ayşe öğretmenimin çimen yeşili gözlerinin

Sararan çimenlere dönmesinden korkardım,

Bakışlarınızın kızmaya başladığı çocuk anlarımda…

Uzak kentin balkonundan, bakarken ayışığındaki bana

O yürek yarım, el sallarken siluetime

Hüznünü akıtırken gözyaşlarının sessizliğinde içine

Yıldızlar devrederken yerlerini birazdan doğacak güneşe

O ay ışığı hep gökyüzünde…Ve

Ben ona asılı ve tutsaklığım onda özgürleşecek

Aynı ayışığının şavkında buluşacağız

Aşkımızın emekçisi, firari kadınımla…

Aykırı ve göçebe aşkımıza, 

Evsahipliği onurluğunda kuşattığım ülkemde,

Özgürleşerek…

Biliyorum ki içinde hiç nefret olmaz, kıyamazsan ki

Belki biraz üzüleceksin ilk an, deli oğlum diyeceksin

Yaptı yine yapacağını diyerek, ama

Dinledikçe kendini sen

Dinlendirdikçe yüreğini, benden yana seninle 

Atlattıktan sonra içindeki fırtınaları, yanındalığımla

Seni, anne sıcaklığındaki sesini bekleyeceğiz

Yani bekliyor olacağız... Hüzün gözlümle

Hep beklentilerim de yanımda, yüreğimdeydin sorgusuz

Mahallenin en yaramazlarından olup ta

Komşu kadın ve çocukları korkuttuğum da

Nasılda gülerdin o anne gözlerinin bana desteğiyle

Ve o melek gülüşündeki kıvılcımlar

Haşarı çocukluğumu hiç büyütmedi bu yaşıma 

Bazen kendimi bile affetmeyeceğim yaramazlıklarım da

Nasıl da korkardım akşam babama söylersin diye, ama

Bilirdim söylemezdin, ürkerken çocuksu yüreğim

Sen benim ilk aşkım, ilk kadınım ve annemsin 

Canım sende can bulurken, düştüğümde rahmine o gece

Ve dünyaya küfrederek koca ağzımla doğduğum da

Ebe Mediha''nın babama *oğlan çocuk* diye müjdeleyip

Yüklü bahşiş sunduğunda, kızışını çok sonra öğrendim…

İlk meleğim değil miydin, beni senin kadar seven var mıydı,

Bebekliğimden çocukluğuma uzanırken bahçeli evimizde? 

Beni en çok sen sevdin…

___En çok sen sevdin

Sevdin… Şımarttın beni… İyi ki şımartmışsın be annem 

Ve sen beni yıllar sonra ilk kez

Böyle mutlu, 

Böylesi gözleri aşka, yaşama ilk kez gülümsüyorken

Ve hep güleceğime inancın çoğalarak gördüğünde

O en zor anlarımda yaptığın gibi

* Ah benim deli oğlum* diye

Sıcak, bırakmamacasına sarılacaksın, 

Bırakmadan beni... Bırakmadan bizi…

Sarılınca anne sıcaklığında ağlatmalısın mutluluktan

Artık yanımda sevgini korkmadan ve çıkarsız ve beklentisiz

Paylaşacağın bir melek, bir sevda kadını

Bir yürek, gönül kadını var, 

Beni senin sevdiğin biçimde ve senin

Sevginden çok sevmeye yeminli…

Eğer severse beni senden çok, bilirim yufka yüreğini senin

Kıskanmaz, alkışlarsın, dimdik, onurla… Ağlarsın…

Sen beni rahmine düştüğümde, o ise

Henüz doğmadan seviyordu…

Hadi o zaman… Benim güzel annem

Kıskançlığını - ki varsa - Seyhan nehrine at

/Her anne kıskançtır oğluna bu ülkede nedense/

Ve çirkinliklerde eksilmeyen yüzümün,

Ellerini öpmesine izin ver

Ver ki öperken kutsal ellerini yüreğim,

Kadınım,

Dünya güzelim,

Sırada şimdi seninle kucaklaşmak için…

O da bir güzel anne, o da  melek, delikanlıma

Sizin sarılmanız dünyanın en güzel sarılması olmalı

İki kadınım, iki aşkım, iki meleğim...

Gözpınarlarım boşalmalı bu sahneyi izlerken

Ki…. Bu ağlayışımın anlamını taşımalıyım yüreğimde

Sonra; 

Bizi baharat kokan sofrana davet etmelisin

Hünerli ellerinden çıkan yemeklerini tattırmak için…

Yıllardır hasret kaldığım DUL AVRAT çorbasını özledim en çok

Ardından öyle bir besiye çekmelisinki bizi annem…

Usta, marifetli ellerinde bahar kokmalı sofran

İÇLİ KÖFTE''ni, ANALI-KIZLI'' nı tatmalıyız

SARMISAKLI KÖFTE''nin salça sosuna ekmeğimi banmalıyım,

Birde çiğden yaptığın o KISIR''ı tattırmalısın bize

Tatmalıyız dünya gözüyle, kentimin tatlarını 

Korkma ağır gelmez yemeklerin çokluğu

Tadımlık alırken her birinden elbet

Yaptığım ev şalgamından yudumlarken, yeniden acıkmalıyız

Sindirerek yediklerimizi

Sindirerek sevdamızı…

İşte benim güzel annem anladınki

Ben...  Biz... Böyle mutluyuz, mutlanacağız…

Giysilerimin emek verilmiş sevdalı çizgilerini

Yüreğimde özgürce taşımalıyım…

Şimdi sen çay demlerken bir solukluk izin ver,

Doğduğum, doyduğum, dövüştüğüm bu kentin

Çocukluğumdaki izbe, toprak, şimdilerde asfalt 

Sokaklarında, caddelerinde, meydanlarında 

Kısa bir kent turu yapalım yürek yarımla

Sevgi kıvamında çayına yetişiriz

Çocukluğumdan sevdiğim KOL BÖREĞİ eşlik ederken...

Ben sende…

Ben sevdiğimde…

Çocukluğumu, sevginizi, sevmelerinizi özledim...

23.09.2005 - Adana', 'Sevgili Anneciğim,						 						 Hani henüz okula başlamadığım,						 Dallarından, gövdesinden inmediğim ve bugün						 Her biri katliama uğr...', ARRAY['Türk Edebiyatı','Şiir','Olgun Ekinci']::text[], 8.5, '{"poet":"Olgun Ekinci","poet_slug":"olgun-ekinci","theme":"Türk Şiiri","is_hero":false,"total_lines":149,"source_url":"https://www.antoloji.com/mektubumdur-anne-me-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın Geçmişi Olur Mu', 'askin-gecmisi-olur-mu-atilla-guler-a5hub', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'hayatlar koydum

ta en derinlerine yüreğimin 

aklıma her geldikçe sızlarım inceden

yağmurlara inat süzülür yaşlarım derinden

rast makamında bir aşk çalar kapımı

…durmaksızın

uykuların utancı gözümün ucunda

nihayetine yol alan bir geminin son limanı

kıyılarım

ne kadar benimsin benden uzakta

ilk günkü gibi olmuyor aşk

yeniden başlayınca

ses ver…ruhum/içim yanıyor

anneme söyleyecek gücüm kalmadı hüzünlerimi

kış gecelerinin yıldızsız gökyüzünde yüreğim

aşk bir buluta saklanmış…kayıp bir yıldızdayım

yağmurlara inat süzülür yaşlarım

inceden

sindirilmiş seslerimde uçuşur martılar

eklenmiş her yama

kanar yüreğimde kızıl bir yangınla 

rengarenk boyalı bir düşten uyanır eskiler

ismine yazılmış bir şiirde canlanır sensizliğim

laternaların çaldığı bir şarkıda dans ediyorum şimdi

…ıssızlığımla

ilencine tutulmuş dün

tütüyor bugünde 

oltanın ucunda hayaller/dere kurumuş

dolar mı kuyular ağlasam/çağlar mı nehirler

localarında sinemaların kuytu kaçamaklarım

uzakta…çok uzakta/ruhuma sardığım her aşk

aşk geçmiyor/geçmişi olmuyor…', 'hayatlar koydum ta en derinlerine yüreğimin  aklıma her geldikçe sızlarım inceden yağmurlara inat süzülür yaşlarım derinden rast makamında b...', ARRAY['Türk Edebiyatı','Şiir','Atilla Güler']::text[], 8.5, '{"poet":"Atilla Güler","poet_slug":"atilla-guler","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/askin-gecmisi-olur-mu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerde Uyumak...Düş...', 'gozlerde-uyumak-dus-bahtiyar-arslan-apl3o', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'akşamları kıvrılır yatardım

üstü açık, ellerinin içine...

yağmur yağardı üstüme

üşümezdim

ellerin ısıtırdı beni...

akşamları başımı gömerdim,göğsüne

düşler kurardım,senli-benli...

ayrı ayrı düşlere koyardım seni

yanardık hasretten...

kanatırdım her yanımı,acılar bırakırdım sana

hiç gocunmazdın...

bir gül olur yanağımda açardın...

akşamları düşlerimi gömerdim düşlerine...

süzülen bir uçurtma olurdum

ipin ucunda çocuk...

gülerdim 

dudağımın kıvrımında yanık bir haz olurdu

sen gülerdin...ben uçardım...

akşamları gözlerimi gözlerine gömerdim

sen ağlardın,ben mutlu olurdum...

atlayıp

bana ait,beni seven gözyaşına

mutluluktan mest olurdum...

akşamları gözlerini gözlerime gömerdin

ben ağlardım....

sen...sen...sen...gülerdin...

---gülerdik...', 'akşamları kıvrılır yatardım üstü açık, ellerinin içine... yağmur yağardı üstüme üşümezdim ellerin ısıtırdı beni... akşamları başımı gömerdim...', ARRAY['Türk Edebiyatı','Şiir','Bahtiyar Arslan']::text[], 8.5, '{"poet":"Bahtiyar Arslan","poet_slug":"bahtiyar-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/gozlerde-uyumak-dus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dargınım', 'darginim-saim-bastik-1m5lt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gülmedim dünyaya geldim geleli

Mahsundur şu gönlüm bildim bileli

Şu dilim yüzünden başım belalı

Ben; gönüller kıran dile dargınım.

Bülbül oldum gelip dalına kondum

Yıllarca ben onun aşkına yandım

Vuslata ermeden yıkıldım öldüm

Ben; kadir bilmeyen güle dargınım.

Yeminler etmiştik, akmayacaktı

Beni, ateşlere yakmayacaktı

Akıp da gönlümü yıkmayacaktı

Ben; gözümden akan sele dargınım.

Şu benim sevdamı yâre götürmez

Götürüpte hasretimi bitirmez

Kendi yoksa kokusunu getirmez

Ben; sevdasız esen yele dargınım.

23/09/2005', 'Gülmedim dünyaya geldim geleli Mahsundur şu gönlüm bildim bileli Şu dilim yüzünden başım belalı Ben; gönüller kıran dile dargınım. Bülbül ol...', ARRAY['Türk Edebiyatı','Şiir','Saim Bastık']::text[], 8.5, '{"poet":"Saim Bastık","poet_slug":"saim-bastik","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/darginim-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kanatsız Kuş', 'kanatsiz-kus-i-sa-tekin-oo9u9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Topluyorum eşyalarımı

Sigaramı çakmağımı

Yastığımı battaniyemi kitaplarımı 

Hoşçakal ranzam 

Hoşça kalın komşularım

Yeni ranzama gidiyorum,

Hey gidi koca dünya

''İnsanoğlu kanatsız kuş''

Dün gece nerede yatıyordum 

Bu gece Mehmet''in yerinde

Amma da uzağa gitmişim

İnsanoğlu kanatsız kuş!', 'Topluyorum eşyalarımı Sigaramı çakmağımı Yastığımı battaniyemi kitaplarımı  Hoşçakal ranzam  Hoşça kalın komşularım Yeni ranzama gidiyorum, ...', ARRAY['Türk Edebiyatı','Şiir','İsa Tekin']::text[], 8.5, '{"poet":"İsa Tekin","poet_slug":"i-sa-tekin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kanatsiz-kus-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neden Unutamıyorum', 'neden-unutamiyorum-dilek-hokkaomeroglu-noyyf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bitir geceyi

anılar toplanmışlar etrafımda

bir kadeh

dudaklarımı yakıyor

ağlıyorum

bir kadehte

dünyanın anasını satıyor gülüyorum

sarhoşum ya! 

ne yaptığımı bilmiyorum

ellerime bakıyorum 

ellerim ellerim yok

kadehleri tutamıyorum

gözlerim fel fecir bakıyor

dünya''ya

unutamıyorum...

demek ki sarhoş olmadım daha

dünya 

dönüyor gözlerimde

yıldızlar....yıldızlar,

parlak bir kadeh içinde

pespembe bir ay

gözlerimin önünde

kadehler doldu taştı

boşaldı bitti

ben yine sarhoş yığılıyorum

peki ben sarhoş olmuşsam

neden unutamıyorum.', 'bitir geceyi anılar toplanmışlar etrafımda bir kadeh dudaklarımı yakıyor ağlıyorum bir kadehte dünyanın anasını satıyor gülüyorum sarhoşum y...', ARRAY['Türk Edebiyatı','Şiir','Dilek Hokkaömeroğlu']::text[], 8.5, '{"poet":"Dilek Hokkaömeroğlu","poet_slug":"dilek-hokkaomeroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/neden-unutamiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ruhumdan Çıkartamam Aşkını', 'ruhumdan-cikartamam-askini-kamil-soylemez-juh8a', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bıraktım 

Tüm mektupları bıraktım dün gece

Sessizce evinizin bahçesine

Bıraktım

Bir sigara yaktım

İki nefes çekmek değildi amacım 

Sadece şaşkınlık 

Kendimden sakık inandığım düş

Kırdığım çıldırmışlığın zinciri yokluğun

Tüm sayfalarda göz bıraktım

Bir iki damla yaş 

Çimenlerin üstünde

Mektuplarla birlikte iki tel de saç

Hani bana bıraktığın iki tel

Yüreğim üstünde sakladığım iki tel

Gömleğimde sakladığım ruj boyan

Biliyorsun çıkartamam 

Saçını çıkartım gömleğimin cebinden ama 

Rujunu çıkartamam

Yinede kalsın istemedim

Onu da bıraktım umarım yırtıp atmazsın

Beni paçavra yaptığın gibi

Onu da yırtmazsın

Ruhumdan atamam bilirsin atamam

Söylemiştim sana atamam

Daha fazla ısrar etme lütfen

Sen çıksanda hayatımdan

Ruhumdan çıkartamam

Sen sonsuzluk abidesi aşksın içimde

Bunu asla yapamam

Asla asla yapamam', 'Bıraktım  Tüm mektupları bıraktım dün gece Sessizce evinizin bahçesine Bıraktım Bir sigara yaktım İki nefes çekmek değildi amacım  Sadece şa...', ARRAY['Türk Edebiyatı','Şiir','Kamil Söylemez']::text[], 8.5, '{"poet":"Kamil Söylemez","poet_slug":"kamil-soylemez","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/ruhumdan-cikartamam-askini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kedim', 'kedim-koray-feyiz-1imnw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ne haddinden fazla yakınım sana,

Ne de haddinden fazla uzak.

Tek kusurun e harfine takılmış kuyruğunla 

Kusursuz bir dost olmak.

Kusursuz dediysem mükemmel değilsin

Yaşlanmışsın,fakat yine de

Güngörmüş asilzadeler gibi vakarlı…

Sen sabahçısın,erken kalkanlardan.

Kayığın rüzgarın keyfine tabi değil.

Kuşkusuz bu evlerde senden daha genç

Daha albenili olan başka kediler var,

Ancak seni biricik kılan:benim!', 'Ne haddinden fazla yakınım sana, Ne de haddinden fazla uzak. Tek kusurun e harfine takılmış kuyruğunla  Kusursuz bir dost olmak. Kusursuz de...', ARRAY['Türk Edebiyatı','Şiir','Koray Feyiz']::text[], 8.5, '{"poet":"Koray Feyiz","poet_slug":"koray-feyiz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kedim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kör Karanlık', 'kor-karanlik-dilek-hokkaomeroglu-uwwn8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'acılar sürerken gecede

çıkaramadı kimse

kör karanlıkta

kör kurşunu...', 'acılar sürerken gecede çıkaramadı kimse kör karanlıkta kör kurşunu......', ARRAY['Türk Edebiyatı','Şiir','Dilek Hokkaömeroğlu']::text[], 8.5, '{"poet":"Dilek Hokkaömeroğlu","poet_slug":"dilek-hokkaomeroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kor-karanlik-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey Dünyâ Milletleri ! ...', 'ey-duny-milletleri-ulvi-ziya-2tllg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yiğitseniz,ben sizden daha yiğitim; dostum...

Uygarlık yolunda aslâ olmaz suikastım...

Gerçek târih şâhit,mertçe yürüdüm her zaman; 

Ne suçsuz insan kestim; ne kadın,çocuk astım...

Kıtaların üstüne adâlet  mührü bastım...

Her tür kötülükle olacaksa savaşınız

Ey çılgın dünyâ,benim sizin çeri başınız...

Eller tertemiz olsun,temizlensin yürekler; 

Şeytanlığı bırakıp,samîmi yaklaşınız...

Mâzî orada kalsın,yeni duyguyla coşalım...

Sevgide buluşup güzelliklere koşalım...

Toplumunuza bakın,zengin ama huzursuz; 

Gelin,hep birlikte mevcut kâbusu aşalım...

Sizden yâr olmaz,lâkin ümitli olmam gerek...

Yılan bile hak yola iletilir severek...

Düşmanlıktan ne çıkar,dost olmak en iyisi; 

Desinler,bir dervişle yoldaş olmuş engerek...', 'Yiğitseniz,ben sizden daha yiğitim; dostum... Uygarlık yolunda aslâ olmaz suikastım... Gerçek târih şâhit,mertçe yürüdüm her zaman;  Ne suçs...', ARRAY['Türk Edebiyatı','Şiir','Ulvi Ziya']::text[], 8.5, '{"poet":"Ulvi Ziya","poet_slug":"ulvi-ziya","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ey-dunya-milletleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Görüş Mesafesi', 'ask-gorus-mesafesi-koray-feyiz-y0o46', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben zaten senin gibi bir ölüm için,

Ne anlama gelirdim ki? temkinliyim.

Bir elim kapının tokmağında durur,

Diğeriyse bir ağacın kavruk silüeti

Dışarıda,ben yürüyen bir felcim…

Unut gitsin ve sen ne için gelmiştin? 

Beni al,kalbimi,beyaz bulutlar içinde

Geçen trenleri gurbetimden,demiştim

Kendime üzülmüyorum,tecrit edildim! 

Gitmem gereken yere giderek şimdi.

Aşk görüş mesafesinden uzaktayım,

Her tarafından ıstırap terleyen büyük

Bir hastaneyim artık,çocuklar için bak,

Bir gün evet,ama bugün değil,asla! 

Verdiğin sözü unutma,eğil,biraz daha.', 'Ben zaten senin gibi bir ölüm için, Ne anlama gelirdim ki? temkinliyim. Bir elim kapının tokmağında durur, Diğeriyse bir ağacın kavruk silüe...', ARRAY['Türk Edebiyatı','Şiir','Koray Feyiz']::text[], 8.5, '{"poet":"Koray Feyiz","poet_slug":"koray-feyiz","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ask-gorus-mesafesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kime Ne', 'kime-ne-dilek-hokkaomeroglu-ts5r1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'el salladı ılık  yağmurla

gelen hayatıma.

fırtınalar kopmuş yüreğimde

ona ne.

çareler tükenmiş ellerimde

bana ne

ayaklarım basmasa da

geçmişte iz bırakmazlar ya! 

öylece..

ılık bir rüzgar

okşdı hayatımı

son kalan dalında

bir yaprak  gibi

hazanda solan.

hiç sezdirmeden

düşürdü toprağa

sinsice bir yalanla

alçakça..

KİME''NE', 'el salladı ılık  yağmurla gelen hayatıma. fırtınalar kopmuş yüreğimde ona ne. çareler tükenmiş ellerimde bana ne ayaklarım basmasa da geçmiş...', ARRAY['Türk Edebiyatı','Şiir','Dilek Hokkaömeroğlu']::text[], 8.5, '{"poet":"Dilek Hokkaömeroğlu","poet_slug":"dilek-hokkaomeroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/kime-ne-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevenin Gelmişine Geçmişine...Ayıpsa Ayıp!', 'sevenin-gelmisine-gecmisine-ayipsa-ayip-abdulkadir-karaca-8m5fz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sevenin gelmişine geçmişine...

Ayıpsa ayıp! 

Böyle söylemiyordu Sezen ama

Ben hep  dinlediğimde böyle derdim

Beni vuran her gidişin ardından

Kurşuni bir sevda öldürecekti beni

Onurlu bir son,feryattan uzak,sukutu kutsal

Korkak bir gidişin arkada bıraktıkları olmayacaktı kefenim

Yapraklarım dökülmeyecekti sonbaharda

Bilmiyorum

Kimin ahı hayatımı ayrılıklara çiğneten

Hangi günahımın vebali sensizliğim

Ezbere tekrarlanan nakarat aşklar

Uğramasın isterdim kalbime

Gidişin doğru yanımıda yanına aldı

Ortada kalmış bir günahkarım

Birde gençliğim ortada kaldı

Seni görmediğim her an 

Bunu gözlerime söylemene gerek yok,

Biliyorum beni yanına istemeyen sensin

Fakat yanında olamamak en büyük günahım

Simsar zaman sattı beni üç kuruşa efsanelere

Zindanda Yusuf oldum,dağda Ferhat,çölde Mecnun

Ben pandoranın kutuda bıraktığı umudum

Gül dikeninin kalbini deldiği bülbül

Mutluluk düşlerimizi çoktan unuttum

Senin gözlerine bakmak bana yeterdi

Ama gittin yüreğimde sana tabi sevdamla

O günden sonra ellerim bomboş

Yarınım kayıp

Sevenin gelmişine geçmişine...

Ayıpsa ayıp! 

(25.09.2005)', 'Sevenin gelmişine geçmişine... Ayıpsa ayıp!  Böyle söylemiyordu Sezen ama Ben hep  dinlediğimde böyle derdim Beni vuran her gidişin ardından...', ARRAY['Türk Edebiyatı','Şiir','Abdülkadir Karaca']::text[], 8.5, '{"poet":"Abdülkadir Karaca","poet_slug":"abdulkadir-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/sevenin-gelmisine-gecmisine-ayipsa-ayip-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fener', 'fener-koray-feyiz-ech39', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'gözkırparım sis fenerlerine,uzak,yalnız,

hep birini arayıp duran ve çocuklara,

saçlarına yakamoz takarak,ıssız

rıhtımların orda gurbetini getirip bırakan; 

ve denizde pırlayan martılara,

dalgalara batıp batıp da çıkan; 

bana şiirler taşıyan günlere sonra; 

ve gecelere yıldızlarla dolup taşan.', 'gözkırparım sis fenerlerine,uzak,yalnız, hep birini arayıp duran ve çocuklara, saçlarına yakamoz takarak,ıssız rıhtımların orda gurbetini ge...', ARRAY['Türk Edebiyatı','Şiir','Koray Feyiz']::text[], 8.5, '{"poet":"Koray Feyiz","poet_slug":"koray-feyiz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/fener-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şikayet', 'sikayet-dilek-hokkaomeroglu-ih58f', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'kimi zaman; parasızlığından

kimi zaman; geçimsizliğinden karısının

kimi zaman da; yakınırdı oğlunun avareliğinden

onun için herşey ağlamaya değerdi

gökyüzüne baktığında bil

kırmızı görürdü güneşi

özürlüğü elinden alınınca anladı

her şey bir masaldı..', 'kimi zaman; parasızlığından kimi zaman; geçimsizliğinden karısının kimi zaman da; yakınırdı oğlunun avareliğinden onun için herşey ağlamaya ...', ARRAY['Türk Edebiyatı','Şiir','Dilek Hokkaömeroğlu']::text[], 8.5, '{"poet":"Dilek Hokkaömeroğlu","poet_slug":"dilek-hokkaomeroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sikayet-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kurşuna Dizdim', 'kursuna-dizdim-olgun-ekinci-5japv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bütün				

…..Zevklerimi				

……….Kurşuna				

…………..Dizdim				

Bu kentte				

				

Harfleri kısırlaştırdım,				

Kelimelerim doğurgan değil artık…				

				

Kusura bakmayın,				

Mangalımın sevdalıları				

Barbeküm kilitli				

Şişler paslandı et tutmaz artık				

				

Kelimelere şiş-sel şiirler ekleyip				

Pide üzerinde sunamayacağım, çünkü				

				

Bütün				

…..Zevklerimi				

……….Kurşuna				

…………..Dizdim				

				

				

21.9.2005 - Adana', 'Bütün				 …..Zevklerimi				 ……….Kurşuna				 …………..Dizdim				 Bu kentte				 				 Harfleri kısırlaştırdım,				 Kelimelerim doğurgan değil artı...', ARRAY['Türk Edebiyatı','Şiir','Olgun Ekinci']::text[], 8.5, '{"poet":"Olgun Ekinci","poet_slug":"olgun-ekinci","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/kursuna-dizdim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmurla Gelen', 'yagmurla-gelen-dilan-esiroglu-jxk4i', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Uzak yol hikayelerini dinler

Başı anılara yaslı dünler

-Baş yastıkta

         Koyma beni darda

                 Yolda-

Yaşlı ellerinden medet bekler

Çağlara uzanan ellerinden 

Yeni doğan bebekler.

Yumuk yumuk, kardan aktılar

Uçurtmalarına sabrın ipini takıp

Gökyüzüne baktılar

Yasaktı gökyüzü

          Yasaktı gündüzü

                  Sonra; 

Güz zamanıdır günlerden

Umut güneşe gebe,

Güneş ellerine çocukların

Yağmurla gelen! 

-Baş yastıkta 

           Koyma beni darda

                      Yolda..-', 'Uzak yol hikayelerini dinler Başı anılara yaslı dünler -Baş yastıkta          Koyma beni darda                  Yolda- Yaşlı ellerinden mede...', ARRAY['Türk Edebiyatı','Şiir','Dilan Esiroğlu']::text[], 8.5, '{"poet":"Dilan Esiroğlu","poet_slug":"dilan-esiroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yagmurla-gelen-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayna', 'ayna-koray-feyiz-zt460', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bu kırık ayna değildir benim yaşamım,

bu,içinde beni paramparça gördüğün.

ben geri planda bir gökyüzüyüm,

nice yüzümden biriyim ben

bu yüzüm geç açılır diğerlerinden bütün.

kavşağım ben iki yürek yolu sonundaki,

bunlar birbiriyle birleşmezler ki:

ayrılık işi yokuşa sürmek istediğinden-

birleşirler o aydınlık sonda ne var ki,

çırpınarak her ikisi,başlar aşk işte,derken…', 'bu kırık ayna değildir benim yaşamım, bu,içinde beni paramparça gördüğün. ben geri planda bir gökyüzüyüm, nice yüzümden biriyim ben bu yüzüm...', ARRAY['Türk Edebiyatı','Şiir','Koray Feyiz']::text[], 8.5, '{"poet":"Koray Feyiz","poet_slug":"koray-feyiz","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ayna-83-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Ölmeden Önce', 'ben-olmeden-once-selahattin-yetgin-m5bl9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Uğultulu ve çılgın bir kısrak yürüyor içimde

Yeryüzünün tüm kirli sularında yıkanıp

Bir çoban çadırında dinlenmek istiyorum.

Emzirsin cesedimi şimdi yarasalar

Uyandırmasın isterse o masal devleri

Kavaklar hazin bir sevdaya hışırdasın.

Binlerce ışıktı yüreğim, karıştım şarkılara

Maziyi düşleyecek güç arıyorum kendimde

Dudağımdaki izlere seni soruyorum şimdi.

Vedasız dualarla zaman imbiğinden düştük

Serpilecektik yemyeşil bakir ovalara biz

İsimsiz bir mezar yontusunda kaybolduk.

Bil ki; yüreğimdeki her yer taşlık, taşradır

Sevdamı anlatsam, değer mi ki yüreğine

Kaval elde, şarkı dilde, güz yağışındayım şimdi.

Bu zeminsiz yeryüzü atlasında, esmer bir düştüm

Bir çingene sevdanın en mahrem yerinde öpüştüm

Ben ölmeden önce, bir menekşede gözlerini görmüştüm.', 'Uğultulu ve çılgın bir kısrak yürüyor içimde Yeryüzünün tüm kirli sularında yıkanıp Bir çoban çadırında dinlenmek istiyorum. Emzirsin cesedi...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Yetgin']::text[], 8.5, '{"poet":"Selahattin Yetgin","poet_slug":"selahattin-yetgin","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ben-olmeden-once-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mantar', 'mantar-koray-feyiz-ju8ae', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'sensin benim aradığım bütün bu sorularda,

bu umutla,aşkla sevdiklerimde; 

mantar gibi güçlenirsin soğuk yerde,

sıcaktaysa sıcaksın,dokunurum da.

çözülmez bilmecesi bu zamanların işte, 

öyle bir azarlar bağlandıkları yerde ki:

diplerde genişlerken,küçülür sularda

ve ölürler kıyı boylarında sanki.', 'sensin benim aradığım bütün bu sorularda, bu umutla,aşkla sevdiklerimde;  mantar gibi güçlenirsin soğuk yerde, sıcaktaysa sıcaksın,dokunurum...', ARRAY['Türk Edebiyatı','Şiir','Koray Feyiz']::text[], 8.5, '{"poet":"Koray Feyiz","poet_slug":"koray-feyiz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/mantar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıldız Kaydı', 'yildiz-kaydi-dilek-hokkaomeroglu-vi05l', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'gün çoktan ağardı,

çoğalıyor sevdalar yüreğimde

dağlarda çiğdemler yalnız

gökyüzü kör karanlık

denizde yakamoz birlikteliği

çisi,çisil yağan yağmurlar

toprakta açan bir gül

dudaklarında hep aynı şarkılar

geçip giden ömürlere

ağıtlar yaktılar..', 'gün çoktan ağardı, çoğalıyor sevdalar yüreğimde dağlarda çiğdemler yalnız gökyüzü kör karanlık denizde yakamoz birlikteliği çisi,çisil yağan...', ARRAY['Türk Edebiyatı','Şiir','Dilek Hokkaömeroğlu']::text[], 8.5, '{"poet":"Dilek Hokkaömeroğlu","poet_slug":"dilek-hokkaomeroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yildiz-kaydi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Of', 'of-dilek-hokkaomeroglu-werp7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'of...

yine hüzün geldi kapıma

sabah,sabah

ağırlık çöktü yinr içimr..', 'of... yine hüzün geldi kapıma sabah,sabah ağırlık çöktü yinr içimr.....', ARRAY['Türk Edebiyatı','Şiir','Dilek Hokkaömeroğlu']::text[], 8.5, '{"poet":"Dilek Hokkaömeroğlu","poet_slug":"dilek-hokkaomeroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/of-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GözyasımLa', 'gozyasimla-ali-aydogan-z3udz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'kirli sakalımın altına sakladım seni bir anlık gülümseyle içimde solan kardelenin ayak izleri yuregimde cırpınan bir sevda pesinde ben yine pervasızca dolanan eli cebinde bir mecnun ben sana takılı kalmısım bir gece vakti ansızın içimde kalan bir damla gözyasımla kaldım bir basıma bir sensizim içimde kırıldı gözyaslarım bir adım yanlızım bir gece kıyısında yoklugun içimde bir girdap döner dururum sensiz.', 'kirli sakalımın altına sakladım seni bir anlık gülümseyle içimde solan kardelenin ayak izleri yuregimde cırpınan bir sevda pesinde ben yine ...', ARRAY['Türk Edebiyatı','Şiir','Ali Aydogan']::text[], 8.5, '{"poet":"Ali Aydogan","poet_slug":"ali-aydogan","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/gozyasimla-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnci', 'i-nci-koray-feyiz-h54pc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'buradayım,ey inci,bilmez misin

sarılırım bütün kollarımla sana,bak? 

saçının peteğinde bal tutarlar 

ağır aksak ellerim,arı olur da ansızın.

kalbimi duymaz mısın,çarpar içten,derin

sadakate kanatlanmış,göğünde tam? 

birikmez mi kirpiğinde şiir sevdam,

bir bulut da birikircesine? 

sen nice ki acı çekersin,acıyım ben sana.

nice ki sen umutlanırsın,ben dileğinim; 

ve ustasıyım bütün erdemlerin.

ve midye sadakatince beklemekteyim

taa dibinde kutsal zaman denizinin.', 'buradayım,ey inci,bilmez misin sarılırım bütün kollarımla sana,bak?  saçının peteğinde bal tutarlar  ağır aksak ellerim,arı olur da ansızın....', ARRAY['Türk Edebiyatı','Şiir','Koray Feyiz']::text[], 8.5, '{"poet":"Koray Feyiz","poet_slug":"koray-feyiz","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/inci-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umudun Sesi', 'umudun-sesi-dilek-hokkaomeroglu-f5qzi', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'insan! umut ettikçe

yaşamaz mı oysa

bir kıvılcım olsada

dilinin ucunda..', 'insan! umut ettikçe yaşamaz mı oysa bir kıvılcım olsada dilinin ucunda.....', ARRAY['Türk Edebiyatı','Şiir','Dilek Hokkaömeroğlu']::text[], 8.5, '{"poet":"Dilek Hokkaömeroğlu","poet_slug":"dilek-hokkaomeroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/umudun-sesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İkimizde Sokaktaydık Aslında', 'i-kimizde-sokaktaydik-aslinda-ozan-turk-izvec', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İkimizde sokaktaydık aslında

İkimizde öksüz

İkimizde yetim…

Ben yanar dururdum 

Ruzgardan alıp gücümü,

Sen yağar gürlerdin

Göklerden çıkıp gelirdin

İkimizde sokaktaydık aslında

Kimi camlardan

Kimi balkonlardan atılırdım ben,

Dertten,kederden ateşlenirdim ilk.

Sen,en çok

Gözyaşları zamanında gelirdin

Bir sevgilinin, 

En güzel yalanı olurdun gözlerinin…

İkimizde sokaktaydık aslında

Severdik birbirimizi…

Ben yandıkça asfaltta,

Sen söndürürdün…', 'İkimizde sokaktaydık aslında İkimizde öksüz İkimizde yetim… Ben yanar dururdum  Ruzgardan alıp gücümü, Sen yağar gürlerdin Göklerden çıkıp g...', ARRAY['Türk Edebiyatı','Şiir','Ozan Türk']::text[], 8.5, '{"poet":"Ozan Türk","poet_slug":"ozan-turk","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/ikimizde-sokaktaydik-aslinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özledim', 'ozledim-dilek-hokkaomeroglu-xj55p', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'gözlerin konuşmayalı

ellerin ellerimi tutmayalı

en son; 

ne zaman gülümsedi gözlerin

bana baktığında..', 'gözlerin konuşmayalı ellerin ellerimi tutmayalı en son;  ne zaman gülümsedi gözlerin bana baktığında.....', ARRAY['Türk Edebiyatı','Şiir','Dilek Hokkaömeroğlu']::text[], 8.5, '{"poet":"Dilek Hokkaömeroğlu","poet_slug":"dilek-hokkaomeroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ozledim-124-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Işık', 'isik-koray-feyiz-v96cn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'gözlerim,görmekten öylesine kanıksar ki duvarları,

bir şey görmez olmuş artık kör.

binlerce duvar yükselir içimde sanki,

gökyüzü yok başımda,yalnız binlerce duvar.

sert atışı yorgun zayıf kalbimin

en büyük düşler bahçesinde hep yeşeren,

rus ruleti sanki içinde bir yaşamın

ki usta bir yangın başlamış orda inceden.

yalnız tutuşur haresi bazen

usulca-derken bir ışık sızar da,

geçerek hava boşluğu altından kapının,

kalır derinlikte çöker de.', 'gözlerim,görmekten öylesine kanıksar ki duvarları, bir şey görmez olmuş artık kör. binlerce duvar yükselir içimde sanki, gökyüzü yok başımda...', ARRAY['Türk Edebiyatı','Şiir','Koray Feyiz']::text[], 8.5, '{"poet":"Koray Feyiz","poet_slug":"koray-feyiz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/isik-29-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlıktan Korkuyorum', 'yalnizliktan-korkuyorum-dilek-hokkaomeroglu-zlnte', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'gece izin verirse yalnızlara

koynunda saklanmaların''a

ay ışığı çıksada

gün desede merhaba

kalmak istemiyorum

tek başıma

ulu orta..', 'gece izin verirse yalnızlara koynunda saklanmaların''a ay ışığı çıksada gün desede merhaba kalmak istemiyorum tek başıma ulu orta.....', ARRAY['Türk Edebiyatı','Şiir','Dilek Hokkaömeroğlu']::text[], 8.5, '{"poet":"Dilek Hokkaömeroğlu","poet_slug":"dilek-hokkaomeroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/yalnizliktan-korkuyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitmek', 'gitmek-koray-feyiz-qbrra', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ben,ne dersin,sessizce gitmek isterim 

çirkin dünyadan,serviler altında dingin,

nice ölümün sonu değil yalnızca

yaşamın başlangıcı da olduğunu bilirken? 

dilerim öyle yıldızlar,el ayak değmediği kimsenin

tutuşmuş akşam göğünde,uzak-

bir de şu aşk ancak:sen,ne dersin?', 'ben,ne dersin,sessizce gitmek isterim  çirkin dünyadan,serviler altında dingin, nice ölümün sonu değil yalnızca yaşamın başlangıcı da olduğu...', ARRAY['Türk Edebiyatı','Şiir','Koray Feyiz']::text[], 8.5, '{"poet":"Koray Feyiz","poet_slug":"koray-feyiz","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/gitmek-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah Kerem', 'ah-kerem-selahattin-aydemir-6t3bc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yine cıvıl cıvıldı o gün Dombay ovası

Yine harıl harıl çalışıyordu tüm köylü

Elinde çapası, yabası, su kovası

Hepsi buram buram terliyordu 

Masmavi gök

Capcanlı toprak

Hışır hışır yaprak 

Ve kuşlar ötüşüyordu

Tümden hayat fışkırıyordu ovada

Düvende, harmanda, çapada

Ne muhteşem bir tablo bu Allah’ım

Koyunlar meliyor, atlar kişniyordu

On altı yaşında bir delikanlı Kerem

Tarladaydı Kerem

Terliyordu buram buram

Birden peydahlandı bir adam

“Nerde lan baban”

Deli gibi bağırıyordu

Somurtmayı bilmezdi Kerem

Hiç kapanmazdı dudakları

İlk kez ömründe korktu Kerem

Sağır oldu kulakları

Yok burada amca

Köydedir anca

Ben oğluyam

Hayır ola 

Her şey bir anda değişti

Kuşlar dondu havada

Böcekler deliklerine kaçıştı

Ovada çık çıkmıyordu

Allah’ım bu nasıl işti

Tümden koca ova 

İki göz arasına sıkıştı

Çıkamıyordu

Karardı masmavi gök

Sus pus oldu tarla takka

Otlar, ağaçlar, ekinler

Her şey kötüye bürünüyordu

“Baban lazımdı” diye haykırdı

Bağıran insan değil, bir aygırdı

Kerem dedi “Peki emmi

Köye gidem çağırem mi”

Kerem tir tir titriyordu

Kara aklı pis ellerine düşmüş

Kara gözü tersine dönmüş

Kara ses bağırıyordu

Yok öyle yağma, kaçacan mı deyyus 

Eşeğin beyninde çıkmıştı ok yaydan

Ne dese olmayacaktı kolaydan 

Aniden adamın tabancasından

Üç kurşun çıktı

Kerem ilk defa korktu

Kerem ilk defa somurttu

Kerem ilk defa gülmedi

Kerem bir daha hiç gülmedi

Kerem, 16 yaşında kan davasına kurban giden amcamın oğlu idi.', 'Yine cıvıl cıvıldı o gün Dombay ovası Yine harıl harıl çalışıyordu tüm köylü Elinde çapası, yabası, su kovası Hepsi buram buram terliyordu  ...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Aydemir']::text[], 8.5, '{"poet":"Selahattin Aydemir","poet_slug":"selahattin-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":56,"source_url":"https://www.antoloji.com/ah-kerem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zor Olsa Gerek', 'zor-olsa-gerek-dilek-hokkaomeroglu-g7e25', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 've.. 

kırmak, 

yüzünüze bakarak aynaları 

boşu, boşuna toplamak parçaları 

geç olduğunu bile,bile. 

ayaklarının altına fırlatmak, 

kanayan parmakların 

dinmeyen kanını 

içerek yaşamak 

zor olsa gerek.. 

koşmak.koşmak dağlara 

sonra düşmek 

bir uçurum dibine 

sahte bir gülüşle 

toplamak çiçekleri 

dikenleri bata,bata. 

kanatmak, 

sevgilerimizi,yüreğimiz acıyarak 

zor olsa gerek.. 

Dilek Hokkaömeroğlu', 've..  kırmak,  yüzünüze bakarak aynaları  boşu, boşuna toplamak parçaları  geç olduğunu bile,bile.  ayaklarının altına fırlatmak,  kanayan p...', ARRAY['Türk Edebiyatı','Şiir','Dilek Hokkaömeroğlu']::text[], 8.5, '{"poet":"Dilek Hokkaömeroğlu","poet_slug":"dilek-hokkaomeroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/zor-olsa-gerek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Işık', 'isik-cenk-karayazici-g2bz7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yaşarken  ışık saç,

Işığınla aydınlansın dünya.

Seni sevenler  ve isteyenler var bu dünya da! ..

Sen onları değil, kendini beklemelisin

Ereceksin, 

Anlayacaksın, 

Hayatı seveceksin.

Çok daha sonra,

Hayatı anlayacaksın.

Anlayınca, benliğini seveceksin..

Yaşamın anlamını,

Anlamın, 

Ne demek olduğunu öğreneceksin.

Ve,  her zaman vereceksin.

Sonsuz bir şelale gibi  daima akacaksın.

Aktıkça da, çağlayacaksın.', 'Yaşarken  ışık saç, Işığınla aydınlansın dünya. Seni sevenler  ve isteyenler var bu dünya da! .. Sen onları değil, kendini beklemelisin Erec...', ARRAY['Türk Edebiyatı','Şiir','Cenk Karayazıcı']::text[], 8.5, '{"poet":"Cenk Karayazıcı","poet_slug":"cenk-karayazici","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/isik-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıldızlar', 'yildizlar-koray-feyiz-ss2i0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'temiz yüzleri var hepsinin 

ve erişmek zordur o parlak varlıklara.

ve bir düş sanki kavuşmak için yeryüzüne

geçer içlerinden genellikle.

hemen hepsi başlarını aynı tutar; 

sallanıp dururlar gökyüzünün beşiğinde,

nice nice bebekler gibidirler

onun gizinde ve ninnisinde.

ayaklandırandır onlar bir şehri

ancak gözlerini kapattıklarında:

büyük çilingir elleriyle gökyüzü

sanki döndürür gibi günü

hayatın zaman kilidinde.', 'temiz yüzleri var hepsinin  ve erişmek zordur o parlak varlıklara. ve bir düş sanki kavuşmak için yeryüzüne geçer içlerinden genellikle. hem...', ARRAY['Türk Edebiyatı','Şiir','Koray Feyiz']::text[], 8.5, '{"poet":"Koray Feyiz","poet_slug":"koray-feyiz","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yildizlar-41-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ceza', 'ceza-koray-feyiz-l28dk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'aşkolsun o ölüme,beni gerçek kılabilen! 

önceki yaşamım düştedir ancak.

dökülür yapraklar büyük halkalar çizerek

asıl benim olan güze alkış tutarken.

bir bana vergidir,veda üstüne veda,

uzak köprüler atarım kendime.

engelleri aranır durur engel olan 

sonra kör boşluğun bıraktığıysa…

dost yalnızlık.

ey gölgelerin senfonisi! 

bütün çirkinliklere karşı

beni tekdüze şeyler değil mi koruyanlar? 

ne kadar yeşerip göverse de çınar 

başı değemez bulutun 

ilkyaza mendil açtığı maviliklere.

gökyüzündendir cezalar.', 'aşkolsun o ölüme,beni gerçek kılabilen!  önceki yaşamım düştedir ancak. dökülür yapraklar büyük halkalar çizerek asıl benim olan güze alkış ...', ARRAY['Türk Edebiyatı','Şiir','Koray Feyiz']::text[], 8.5, '{"poet":"Koray Feyiz","poet_slug":"koray-feyiz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ceza-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kayboluş', 'kaybolus-dilek-hokkaomeroglu-48q8i', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'gözler gülmekten vazgeçtiğinde

anıların bile ulaşamadığı günlerde

acı oturmuş yüreklere

insanlar insanları yitirdiğinde

kucakların boş kaldığı günlerde

hayat çok zor

yalnız ve çaresiz yaşantılar içinde..', 'gözler gülmekten vazgeçtiğinde anıların bile ulaşamadığı günlerde acı oturmuş yüreklere insanlar insanları yitirdiğinde kucakların boş kaldı...', ARRAY['Türk Edebiyatı','Şiir','Dilek Hokkaömeroğlu']::text[], 8.5, '{"poet":"Dilek Hokkaömeroğlu","poet_slug":"dilek-hokkaomeroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/kaybolus-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaçış', 'kacis-dilek-hokkaomeroglu-gk6en', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'telefon kulübesine her gidişimde

umutsuz bir bekleyişim

mavi suların serinliğinde

mavi gözlerin  bakardı

koşarken yetişmek için

otobüs durağına

umutsuzca bir kaçış vardı

o anda..

yollarımız ayrıdı..', 'telefon kulübesine her gidişimde umutsuz bir bekleyişim mavi suların serinliğinde mavi gözlerin  bakardı koşarken yetişmek için otobüs durağ...', ARRAY['Türk Edebiyatı','Şiir','Dilek Hokkaömeroğlu']::text[], 8.5, '{"poet":"Dilek Hokkaömeroğlu","poet_slug":"dilek-hokkaomeroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/kacis-42-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Susun Ağlayacağım', 'susun-aglayacagim-muammer-hacioglu-nwjkm', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Damarları kesilmiş bir gökyüzünün altında

Gecenin saçlarını tarıyorum

Usumun kırılmış kapılarından yollara düşüp

Kendimi arıyorum

Faytonlar geçiyor sokaklardan

Kurbanlar kesiliyor

Salıncaklar kuruluyor

Bir çocuk karanlık bakıyor annesine

Bir kadın gözlerinden vuruluyor

Tüm bulutları ellerinden tutup

Evime götürüyorum akşamları

İnsanlar ıslanmasın diye sokaklarda

Oysa nerden

Ne zaman

Ve kimlerle

Bu gemi hangi denizlere gidecek kaptan

Bilmiyorum

Yine sonbahar dolacak masallarıma

Yine kaldırım üstlerinde iplik iplik uzayan yalnızlığımı

Güneyli bir rüzgârın kirpiklerine bağlayacağım

Gözlerimden tanklar geçiyor susun

Susun ağlayacağım', 'Damarları kesilmiş bir gökyüzünün altında Gecenin saçlarını tarıyorum Usumun kırılmış kapılarından yollara düşüp Kendimi arıyorum Faytonlar ...', ARRAY['Türk Edebiyatı','Şiir','Muammer Hacıoğlu']::text[], 8.5, '{"poet":"Muammer Hacıoğlu","poet_slug":"muammer-hacioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/susun-aglayacagim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk', 'ask-eray-arik-wseb9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kelimeler yetmez seni sevdiğimi anlatmak için,

Cümleler boğazımda düğümlenir.

Kalbimi çıkarıp sana versem,

O zaman anlarsın seni sevdiğimi.

Gözlerim gözlerinden kaçınır,

Güzelliğine nazar değer diye.

Ellerim ellerinden kaçınır,

Bir daha tutmazsın diye.

Sana bakarken gözlerim,

Kalbim yavru bir kuş gibi çırpınır.

Ellerimi tutacak olursun,

Kalbimden bir kuş havalanır.

Oysa gözlerime baksan,

O zaman görürsün gözlerimdeki seni.

Beni anlarsın,

Seni ne kadar sevdiğimi.', 'Kelimeler yetmez seni sevdiğimi anlatmak için, Cümleler boğazımda düğümlenir. Kalbimi çıkarıp sana versem, O zaman anlarsın seni sevdiğimi. ...', ARRAY['Türk Edebiyatı','Şiir','Eray Arık']::text[], 8.5, '{"poet":"Eray Arık","poet_slug":"eray-arik","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ask-443-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırık sandalye', 'kirik-sandalye-berrak-su-77nv8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sende saklanmış,

Çocukluğumun hınzır gülüşleri.

Sallandıkça,

Takılıp gittiğim uçurtma renkleri gibi,

Canlı henüz,

Törpülenmemiş.

Masallar arası

Gidip gelen,

Altın düşüm,

Fısıldandıkça kulağıma,

Biraz daha küçük,

Biraz daha sağlam,

Saklanmış, kırık ayaklarında....

Berrak Su', 'Sende saklanmış, Çocukluğumun hınzır gülüşleri. Sallandıkça, Takılıp gittiğim uçurtma renkleri gibi, Canlı henüz, Törpülenmemiş. Masallar ar...', ARRAY['Türk Edebiyatı','Şiir','Berrak Su']::text[], 8.5, '{"poet":"Berrak Su","poet_slug":"berrak-su","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kirik-sandalye-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hıdırellez', 'hidirellez-yekta-vural-a2rr7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bir hıdırellezin sona erdiği akşamdayım

içimden hiçbir şey gelmiyor.

nedir hıdırellez? 

umutlarla örülen kaderimizin

yazıldığı gün mü? 

seni dilesem

bir gün kavuşsak

sen bana sığınsan

hayır hayır

ben seni dimdik görmek istiyorum

ayakta,

eğilen başı kaldırmıyorlar burada.

insanlar ne anlarlar! 

sevgiden,

dostluktan,

yücelikten.

bir dostum var

buralarda

bir o anladı zaten

sevgiden,

dostluktan,

yücelikten.

bir sevdiğim var buralarda

bugün yüzüme bile

bakmayan.

herkes sen olmuyor

sevmiyor içten.

bana kırgınsın değil mi

bu satırlar adresini

bilmediğim bir yere

göndersem,

okusam tesadüfen

her gün gittiğimiz

bir kafeye yazsam

eskisi gibi umursamazsın belki de

buna hakkın yok

bir tanem

sensizim buralarda

biliyor musun konuşmadığımı

kırgın olduğum insanlarla

keşke duymasaydım da

diyorum bazen

o insanların sesini; 

o anda sadece

sen ve ben

yaşıyorsun işte

ve

zorunlusun bazı şeylere.

şu anda neredesin bebeğim

yaşıyor musun? 

bir hıdırellezin 

sona erdiği akşamdayım.

içimden hiçbir şey gelmiyor,

seni dilesem

bir gün kavuşsak

değişir mi kaderimiz? 

bahar gelmiş

sen yoksun.', 'bir hıdırellezin sona erdiği akşamdayım içimden hiçbir şey gelmiyor. nedir hıdırellez?  umutlarla örülen kaderimizin yazıldığı gün mü?  seni...', ARRAY['Türk Edebiyatı','Şiir','Yekta Vural']::text[], 8.5, '{"poet":"Yekta Vural","poet_slug":"yekta-vural","theme":"Türk Şiiri","is_hero":false,"total_lines":58,"source_url":"https://www.antoloji.com/hidirellez-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz hayat', 'sensiz-hayat-kamil-boyraz-uuhok', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hiç böylesine düşünmemiştim seni,

      Hep yanımda  olduğundan mı bilmem 

Seni katmıştım ömrümün her zerresine,

     Zaman seninleyken aklıma gelmeyen şey,

     Yaşamsa sende bulduğum huzurdu,

     Tüm hayallerimde  sen vardın

     Umutlarımı seninle oluştururduk, 

Ne benimleydin nede bensiz,

Ne sağımdaydın ne de solumda, 

Sen aynı adımı attığım aynı yöne baktığımdın,

Sen benim yarımım sen benim aynamdın,

     Aynıydık baştan sona,Hep beraberdik seninle,

     Hiç düşünmemiştim seni böyle

Hayatın karmaşık yollarında,

Birbirini en iyi bulan,

     Suskunca anlaşandık seninle,

     Sevgisizlikten yakınan şu dünyada,

     Birbirine bakmayı en iyi becerendik

Etrafı görmeyecek kadar kör,

Birbirini en iyi yansıtacak kadar keskindik

     Aynıydık baştan sona, Hep beraberdik seninle

Hiç düşünmemiştim seni böyle,Seni sessizliğe beni şaşkınlığa iten,Seni esir beni perişan eden,Bu donukluk yoktu hiç hesapta, Ayrılık          yoktu bir an bile, Böyle mecalsiz kalmayacaktım. Hayat ayrılık tuzağı kuramayacaktı bize, Engel girmeyecekti aramıza, Sensizlik bir an bile olmayacaktı Hiç ayrılmayacaktık seninle, Çünkü hep birlikteydik seninle 

Hiç düşünmemiştim seni böyle, Şimdi uzaklaşıyorsun yavaşça, Gözüm seni taşıyan ellere takılmış, Kayıp gidiyor eski günlere,

Yüreğim inim,inim inlemekte, Kalbim haykırmakta peşinden gidişine sessizce

Karanlık bir yarın önümde, Puslu bir hava içimde, Ne olduğunu bilmediğim garip bir his alıyor benliğimi

Ardımda felek olabildiğince yükseltip sesini, Bir çırpıda vuruyor suratıma ayrılık gerçeğini

Ah şu çıkmaz demekten alamıyorum kendimi, Yavaş,yavaş üşüyorum, Her santimetrekaresinde bu diyarın

Tir tir titriyor seni arıyor kollarım, Bu ayrılığın hesabını şimdi kimden sorarım

Sensiz bu cehennemde yapayalnız kaldım 

Yokluğundan yakınıyor kırık kolum kanadım

Sensizliğe mahkum yüreğim

Söyle yokluğuna nasıl katlanacağımı

Biz aynıydık baştan sona,Beraberdik seninle 

hiç düşünmemiştim bizi böyle

Şimdi yapayalnızım bu şehirde, Yokluğunun yasında kalbim, 

     Sensizlikten kör olan gözlerim var artık

Umutlar yırtıldı sensizlikten, Zaten seninleyken güzeldi onlar. Sen varken anlamlıydı umutlar, Anlamını yitirdi hayat yokluğunda, Zaman girdi şimdi yaşamıma,İnatla bekletiyor zorluyor yokluğunda

Darbe üstüne darbe koyuyor hayat, Bekleyişlere sürüklüyor beni,Tek değişmeyen sevgim  o da yorgun sen gideli

Koymamıştık hesaba ayrılık gerçeğini,   Çünkü hep beraberdik seninle

Hiç düşünmemiştik böyle bir sonu, Hiç düşünmemiştim sensizliği, Şimdi kahroluyorum bu şehirde Tükeniyorum yavaş,yavaş, Hiç düşünmemiştim seni böyle,İsyanım yalnızca gidişine

Hatice Kelleli

şiir sahibi ve yazarı', 'Hiç böylesine düşünmemiştim seni,       Hep yanımda  olduğundan mı bilmem  Seni katmıştım ömrümün her zerresine,      Zaman seninleyken aklı...', ARRAY['Türk Edebiyatı','Şiir','Kamil Boyraz']::text[], 8.5, '{"poet":"Kamil Boyraz","poet_slug":"kamil-boyraz","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/sensiz-hayat-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kahkaha', 'kahkaha-dilek-hokkaomeroglu-kaaw4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'candan olmasada

gecenin ilerleyen yüzünde

keşke.. hiç sabah olmasa

rahatladı şimdi düşüncelerim

bir nebze mutluluk olsada

mutlu oldum şimdi

tekrarı olmasada..', 'candan olmasada gecenin ilerleyen yüzünde keşke.. hiç sabah olmasa rahatladı şimdi düşüncelerim bir nebze mutluluk olsada mutlu oldum şimdi ...', ARRAY['Türk Edebiyatı','Şiir','Dilek Hokkaömeroğlu']::text[], 8.5, '{"poet":"Dilek Hokkaömeroğlu","poet_slug":"dilek-hokkaomeroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/kahkaha-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O'' na Özlem', 'o-na-ozlem-oguz-bekar-cmpqa', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Enginlere salmışım bağrımın ateşini

Dalgalar örtemiyor, şu akşam güneşini

Güneşin kızıllığı, yangınıma eşdeğer

Allahım bu ızdırap, bir tebessüme değer

Gözlerim görmez olmuş, artık ne sağı solu

Hayalimde yalnız O, her anım O'' nla dolu

Son hazan mevsimimde yaz güllerim soluyor

Saatim tik tak eder, belli, miat doluyor

Bir gün olsun gülmedim aşktan, sevdadan yana

Sevdim sevilemedim, gülmedim kana kana

İçimdeki fırtına bir melteme dönmedi

Yüreğimin ateşi bir kez olsun sönmedi

Kaderin cilvesi mi bu yalan mutluluğum? 

Boğazımda kördüğüm, kesiliyor soluğum

Haykırsam da boşuna, sesimi gece yutar.

Zincirimi kırsam da, bir sır el, beni tutar

Zaman çabuk geçiyor, ben eski ben değilim.

Mazide yaşıyorum bugünkü ben değilim.

Geçmişimin sırrını yalnızca O biliyor

O'' nunla sohbetimi yalnız Oğuz duyuyor', 'Enginlere salmışım bağrımın ateşini Dalgalar örtemiyor, şu akşam güneşini Güneşin kızıllığı, yangınıma eşdeğer Allahım bu ızdırap, bir tebes...', ARRAY['Türk Edebiyatı','Şiir','Oğuz Bekar']::text[], 8.5, '{"poet":"Oğuz Bekar","poet_slug":"oguz-bekar","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/o-na-ozlem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anne', 'anne-yekta-vural-2krfk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Anne

dalında kuştum

uçtum anne,

gurbet yurdum

uzaklar evim oldu anne.

günlerim mutfakta

esra ağlamazsa

geçiyor anne.

gün ağarmadan uyanıyorum,

omuzlarıma sızı düşüyor artık

senin gibi

anne.

şimdi seni daha iyi anlıyorum

geceleri herkesten geç yatardın

ve her şeyin

en iyisini isterdin bizim için.

bir tercih yapmak gerekseydi

bizi seçerdin.

senin gibi

iyi bir anne olacağım

kızım için

yuvam için anne.

evimiz küçük ama

pek bir şeyimizde yok şimdi

ama en gereklileri

sevgi dolu her köşesinde

saygı ve huzur.

tam istediğim gibi,

hep aradığın gibi.

telefonu kapatmak zorundayım anne

bitmek bilmeyen telaşlarım var şimdi

senin bitirdiğin

benimse henüz yeni başladığım.

sorma beni

iyiyim anne

esra da büyüdü.

dalında kuştum

uçtum anne

gurbet yurdum

uzaklar evim oldu anne.', 'Anne dalında kuştum uçtum anne, gurbet yurdum uzaklar evim oldu anne. günlerim mutfakta esra ağlamazsa geçiyor anne. gün ağarmadan uyanıyoru...', ARRAY['Türk Edebiyatı','Şiir','Yekta Vural']::text[], 8.5, '{"poet":"Yekta Vural","poet_slug":"yekta-vural","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/anne-171-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidiyorum', 'gidiyorum-huseyin-sigirtmac-7kbvd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sevgiden kalmamış eser,

O yar irtibatı keser.

Gelmez haber dilim susar,

Bu diyardan gidiyorum.

Çekti yar setler araya,

Dönüp bakmadan geriye.

Kim bilir göçüm nereye,

Bu diyardan gidiyorum.

Kırıldı arzum hevesim.

Tükendi avazım sesim.

Toparlayıp son nefesim,

Bu diyardan gidiyorum.

Yarsız çekilmez bu diyar.

Ne arayan ne soran var.

Şen olsun ocağın ey yar! 

Bu diyardan gidiyorum.

Sığırtmaç gönlüne taydın,

Yarı yolda koyup caydın.

Ey sevgili gözün aydın.

Bu diyardan gidiyorum.', 'Sevgiden kalmamış eser, O yar irtibatı keser. Gelmez haber dilim susar, Bu diyardan gidiyorum. Çekti yar setler araya, Dönüp bakmadan geriye...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sığırtmaç']::text[], 8.5, '{"poet":"Hüseyin Sığırtmaç","poet_slug":"huseyin-sigirtmac","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gidiyorum-166-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Kadın', 'o-kadin-dilek-hokkaomeroglu-i8s4k', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'dudaklarımın kenarında

tutunuyor geçmişe.

radyo''da,

sevdiğim o şarkı

ben seni ellerin olsun diye mi sevdim

ve

hatırladım 

o kadını

gizem dolu gecede

öldüresiye vurduğum

can çekişen hayatı.

ve asla unutamadığım

göğsü leylak kokulu

o kadını

seneler önce tanıdım

seneler sonra kaybettim

resmi,

tam başucumda,yatağımın

bir çerçeveden ibaret.

bir bardak sevda aldım

bir su gibi içtim,

gözlerinde o kadını.

ağlayan bebek yaygarasıyla

ne kaldıysa elimde

ondan kalan,

bir bir hatırladım.

yine bir yaygarayla

sildim süpürdüm

acımasızca 

o kadını...', 'dudaklarımın kenarında tutunuyor geçmişe. radyo''da, sevdiğim o şarkı ben seni ellerin olsun diye mi sevdim ve hatırladım  o kadını gizem dol...', ARRAY['Türk Edebiyatı','Şiir','Dilek Hokkaömeroğlu']::text[], 8.5, '{"poet":"Dilek Hokkaömeroğlu","poet_slug":"dilek-hokkaomeroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/o-kadin-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ger Çarmıhına', 'ger-carmihina-kamil-soylemez-dt8fz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kaç ışık yılı uzaktayım sana

Dokunup,giderken tenim sıcağına

Kaç adım da sen vardın sakık uzaklıkta

Ben koştukca kokun ardı sıra

Sen hep kaçarmı olucaksın 

Hiçmi durup,duraklamayacaksın bana

Kaçıncı adımda varırım sana 

Bir arpa boyu bile uzaklığında

Dur duraksızım sana

Unuttuğum düşsün çağla dalında deme

Bir mevsimlik değilki sevgim

Kesintisiz bir bulut olurum bir yağmur

Sen topraklarına hasret çiğ tanesi

Gelip,oturmaktır yanaklarına

Tut çıkmadan güneş sabaha

Solmaksızın yıldızsın bağrımda

Bak bu beden terkedilmiş sana

İstersen dipsiz kuyularında yok et

Çıkmayacaksam sen sabahlarına

İstersen çarmıha ger eğilmiş sana bağrım', 'Kaç ışık yılı uzaktayım sana Dokunup,giderken tenim sıcağına Kaç adım da sen vardın sakık uzaklıkta Ben koştukca kokun ardı sıra Sen hep kaç...', ARRAY['Türk Edebiyatı','Şiir','Kamil Söylemez']::text[], 8.5, '{"poet":"Kamil Söylemez","poet_slug":"kamil-soylemez","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ger-carmihina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Demiştim', 'sana-demistim-feride-omur-evlnm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Duyuyorum dostlardan

Çok pişmanmışsın 

Benden ayrıldığın için

Mutsuzmuşsun, ağlıyormuşsun

Gözlerin hep beni arıyormuş...

Sana demiştim

Bensiz olamazsın gitme diye

Yalvarmıştım ardından

Dinlememiştin beni

Gitmiştin...

_____Ne oldu şimdi

_____Çabuk mu yoruldu yüreğin

_____Kimse sevmedimi seni

_____Benim gibi...

Gizlice geliyormuşsun 

Beni görüyormuşsun

Her kahkahamda

Sen ağlıyormuşsun...

Ne bekliyordun

Ardından hala ağlamamı

Sevginden ölmemimi

Bak hayat devam ediyor

Ve...

Ben sensiz gülmeyi öğrendim

_____Ne oldu şimdi

_____Çabuk mu yoruldu yüreğin

_____Kimse sevmedimi seni

_____Benim gibi...

İstemiyorum artık seni

Sensiz nefes almayı

Yaşamayı öğrendim

Gidişinle gömdüm sevgimi

Sana demiştim, gitme diye

Gidersen bir daha dönme diye

Şimdi git! 

Geldiğin yere...', 'Duyuyorum dostlardan Çok pişmanmışsın  Benden ayrıldığın için Mutsuzmuşsun, ağlıyormuşsun Gözlerin hep beni arıyormuş... Sana demiştim Bensi...', ARRAY['Türk Edebiyatı','Şiir','Feride Ömür']::text[], 8.5, '{"poet":"Feride Ömür","poet_slug":"feride-omur","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/sana-demistim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonra', 'sonra-dilek-hokkaomeroglu-b6lbq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'göz yaşlarım damla,damla

toplandı yüreğimde

acımasızca

sonra; 

sokaklarda adımlarım

pencere camlarıda

gözlerim kaldı

sonra; 

o sokaklarda yürürken

bilkmem hatırlamıyuorum

içime çektiğim

kömür kokulu

sevdalarımı..', 'göz yaşlarım damla,damla toplandı yüreğimde acımasızca sonra;  sokaklarda adımlarım pencere camlarıda gözlerim kaldı sonra;  o sokaklarda yü...', ARRAY['Türk Edebiyatı','Şiir','Dilek Hokkaömeroğlu']::text[], 8.5, '{"poet":"Dilek Hokkaömeroğlu","poet_slug":"dilek-hokkaomeroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sonra-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendini Tanı', 'kendini-tani-suleyman-zaman-tdcf5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hezeyan içinde, banalın biri

Gezdim pazarını, duruşu geri

Derbeder yaşıyor, yok mu haberi? 

Öğren çapını da, kendini tanı

Benliğine hakim, olmuş kariyer

Öfke tatlı baldan, ama kendin yer

İkilik gönlünde, var imiş meğer

Öğren yapını da; kendini tanı

Ne ürettin hani, verdin insana

Gelmedik sonsuzca, bu açık hana

İyilik yaparsan, sen de bir cana

Kazan bir dostlukta; kendini tanı

Zorda iken tavrın, yalvarır gibi

Görünmez bulanık, suların  dibi

Bakma yükseklerden, kibir sahibi

Öğren de yerini, kendini tanı

Gururlanma fazla,  bir gün düşersin

Değilsin kalıcı, sende gidersin

Bakınca maziye,  ne idim dersin

Öğren de benini, kendini tanı

Zamanım değer ver, candan dostuna

Kurt isen bürünme, kuzu postuna

Düşünmem kötülük, asla hasmıma

Öğren insanlığı, kendini tanı

                15.06.2005

            Süleyman Zaman', 'Hezeyan içinde, banalın biri Gezdim pazarını, duruşu geri Derbeder yaşıyor, yok mu haberi?  Öğren çapını da, kendini tanı Benliğine hakim, o...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Zaman']::text[], 8.5, '{"poet":"Süleyman Zaman","poet_slug":"suleyman-zaman","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/kendini-tani-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın Şairi,Gönül Evimdesin', 'askin-sairi-gonul-evimdesin-sahin-erturk-6rniw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aylar oldu sen,artık benimlesin

Damarda,beyinde tek düşüncemsin

Kalemde,şiirde düşlerimdesin

Aşkın Şairi,gönül evimdesin

Yalnızlığı bilmem tanımam artık

Acılar uzakta,yabancım artık

Mutluluğu buldum,bırakmam artık

Aşkın Şairi,gönül evimdesin

Haçlı seferleri gelse üstüme

Şovalyen olurum,vermem ellere

Seninle ben düşsem bile dillere

Yılmam savaşırım,bırakmam seni

Güzel sözler seni,anlatmaz oldu

Kalbim seninle,heyecan buldu

Sana bu aşkımı,Türkiye duydu

Aşkın Şairi,gönül evimdesin

(26.09.2005)', 'Aylar oldu sen,artık benimlesin Damarda,beyinde tek düşüncemsin Kalemde,şiirde düşlerimdesin Aşkın Şairi,gönül evimdesin Yalnızlığı bilmem t...', ARRAY['Türk Edebiyatı','Şiir','Şahin Ertürk']::text[], 8.5, '{"poet":"Şahin Ertürk","poet_slug":"sahin-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/askin-sairi-gonul-evimdesin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerine Bakınca', 'gozlerine-bakinca-salim-erben-2j138', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir telaş düşerdi içime

Sarsılırdı yüreğim

Erirdi yok olurdu göz bebeğim

Ne zaman görsem seni

Deniz gözlerine dalardım

Hiç çıkmazdım

Kalırdım alamazdım kendimi

Artık o gözlere bakmıyorum

Baksam da kendimi bulamıyorum

Çünkü o gözlerde beni görmüyor

Artık başkalarına ait

Biliyorum deniz gözlüm

Beni sen unuttun

Bende senin gözlerine bakacak

Ne zaman nede göz kaldı

Artık bir zamanlar 

Aşık olduğum gözlerin sahibi vardı

Hadi git deniz gözlüm

Ankara sana dardı', 'Bir telaş düşerdi içime Sarsılırdı yüreğim Erirdi yok olurdu göz bebeğim Ne zaman görsem seni Deniz gözlerine dalardım Hiç çıkmazdım Kalırdı...', ARRAY['Türk Edebiyatı','Şiir','Salim Erben']::text[], 8.5, '{"poet":"Salim Erben","poet_slug":"salim-erben","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/gozlerine-bakinca-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Günde Sona Eriyor Sensiz', 'bu-gunde-sona-eriyor-sensiz-meram-yalinizoglu-nm3tq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu gün de sona eriyor

Geçiyor ama nasıl  sensiz

Unutmak mümkün değil seni

Hele ki senle geçen saniyeleri

Asla çıkmaz aklımdan, sanma unuturum

O gülüşünü, o bakışını, konuşmalarını.

Neden gittin bilmem ki

Beni bırakıp öksüz.

Bu gün de sona eriyor sensiz.

Nasıl geçecek günler saatler,

Acılarım bilmem sen gelmeden nasıl diner? 

Bir ömür kalsamda bu dünyanın kahrı üzerimde

Çekerim sen varsan yanımda

Yeter ki yokluğunun acısı olmasın

Geri dön sen bana.

Tekrar kollarıma.', 'Bu gün de sona eriyor Geçiyor ama nasıl  sensiz Unutmak mümkün değil seni Hele ki senle geçen saniyeleri Asla çıkmaz aklımdan, sanma unuturu...', ARRAY['Türk Edebiyatı','Şiir','Meram Yalınızoğlu']::text[], 8.5, '{"poet":"Meram Yalınızoğlu","poet_slug":"meram-yalinizoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bu-gunde-sona-eriyor-sensiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öylesine', 'oylesine-dilek-hokkaomeroglu-lkqel', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'kavrulmak,

kavruldukça,

ıslanmak,

aşklarla

nasıldır

acaba

çölde,

serap.

deve,

gemisinde

yolculuk,

güneşe  bakış,

bir yakış

ve kaçış

savaşlardan

nasıldır

acaba? 

gün batımında,

umutlar,

yıldızssı gecelerde

ay,

yağmurlarda,

ıslanmak,

bir öpücük kondurmak,

hayata,

koşmak,koşmak,

umutsuzca umutlara

avuçlarında,

toplamak,

yüreğini,nasıldır acaba? ::', 'kavrulmak, kavruldukça, ıslanmak, aşklarla nasıldır acaba çölde, serap. deve, gemisinde yolculuk, güneşe  bakış, bir yakış ve kaçış savaşlar...', ARRAY['Türk Edebiyatı','Şiir','Dilek Hokkaömeroğlu']::text[], 8.5, '{"poet":"Dilek Hokkaömeroğlu","poet_slug":"dilek-hokkaomeroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/oylesine-55-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz Bırakma', 'sensiz-birakma-meram-yalinizoglu-93756', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gönül telime dokunup 

En güzel nameyi sen çıkardın

Gönül bahçemi sulayıp

Eşsiz çiçekler açtırdın

Gel beni sensiz bırakma

Gönlümü tarumar edip

Tellerini koparma...', 'Gönül telime dokunup  En güzel nameyi sen çıkardın Gönül bahçemi sulayıp Eşsiz çiçekler açtırdın Gel beni sensiz bırakma Gönlümü tarumar edi...', ARRAY['Türk Edebiyatı','Şiir','Meram Yalınızoğlu']::text[], 8.5, '{"poet":"Meram Yalınızoğlu","poet_slug":"meram-yalinizoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sensiz-birakma-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kışa Ekledim', 'kisa-ekledim-yusuf-ter-0fx2f', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bilinmeyen umut 

Yollar var dağ engeli

Çaylar var geçilmez selleri

Kuşun sıcaklığı

Soluk olsun istiyorum

Kafeste ötüşü

Bana cesaret versin

Dalgalı çarpan yüreğime

Bir kıyıda yavaşlasın

Yakamozlar parıldasın

Gece göklerde

Yorgunluğumu bırakayım 

Ey gök ey dağ ey toprak 

Sabır’ı taşa verdim

Göz yaşımı yele verdim

Sevdiğimi elle verdim

Beklediğimi güne ekledim

Taş sabır’a dayanmadı yarıldı

Gözlerimin yaşı kurudu 

Yüreğim bir umut bekledi

Hayallediğim yari düşüme ekledim

Serap güzü, yazı,baharı,kışa ekledi...

Yusuf Ter 26.09.05

Saat 01:06 İsviçre', 'Bilinmeyen umut  Yollar var dağ engeli Çaylar var geçilmez selleri Kuşun sıcaklığı Soluk olsun istiyorum Kafeste ötüşü Bana cesaret versin D...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ter']::text[], 8.5, '{"poet":"Yusuf Ter","poet_slug":"yusuf-ter","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/kisa-ekledim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk;', 'ask-meram-yalinizoglu-ktnfj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gecenin bir yarısı1-3-5 demeden 

Sevdiğinin sesini duymak isteyip

O'' nu uykusundan 

''Seni Seviyorum'' diyerek uyandırmaktır.

Bencilliktir aşk.

Yolda yürürken,gördüğü güzel bir manzarada

Onu düşünüp; 

''En az senin kadar güzel bir manzara,

Paylaşmak istedim, seni hayal ettim''

Diyerek bahanelerle ona ulaşmaktır aşk.

Çok susamışken,

Kana kana su içmenin 

Ne vazgeçilmez olduğunu anlayıp

Sana da böyle tutkunum

Benim için böyle vazgeçilmezsin deyip

O''na gitmektir aşk.

İmkanları zorlamaktan öte

İmkansızlığı zorlamak

İmkan yaratmaktır aşk.

Sesini duymak, yüzünü görmek

Kokusunu duymak,tenine dokunma için..

Aşk; 

Bencillikle düşüncenin karıştığı yerdir.

Aşk; 

O''nu düşündüğünü,özlediğini, sevdiğini

Bencillikle bahanelerle olsa da hissettirmektir 

aşk...

21/09/2005', 'Gecenin bir yarısı1-3-5 demeden  Sevdiğinin sesini duymak isteyip O'' nu uykusundan  ''Seni Seviyorum'' diyerek uyandırmaktır. Bencilliktir aşk...', ARRAY['Türk Edebiyatı','Şiir','Meram Yalınızoğlu']::text[], 8.5, '{"poet":"Meram Yalınızoğlu","poet_slug":"meram-yalinizoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/ask-444-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Helal Olsun', 'helal-olsun-yakup-simsek-jwi4y', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sonunda bunu da yaptın ya bana

Helal olsun

Bir başıma bırakıp gittin

Beni bu odada,

Beni bu evde,

Beni bu şehirde…

Helal olsun sana…

Anahtar taşıyorum cebimde

Kapım açılmıyor eve gelince 

Kaç gündür

Ütümü kendim yapıyorum

Tutturamıyorum senin izinden

Acıkınca, iştahım gelirse eğer

En fazla yumurta kırabiliyorum

Çay da sarmaz oldu ki sorma

İki bardaktan fazla içilmiyor

Akşamların tadı olmuyor

Saat bir türlü vurmuyor on ikiyi 

Helal olsun sana

Yalnız bıraktın beni

Yalnız bıraktın…

Beni hüzünlü şarkılara mahkûm

Tatlı yağmurlarda

Kaldırımda şemsiyemin yarısını 

Boş bıraktın

Helal olsun sana

Helal olsun…

25.9.2005', 'Sonunda bunu da yaptın ya bana Helal olsun Bir başıma bırakıp gittin Beni bu odada, Beni bu evde, Beni bu şehirde… Helal olsun sana… Anahtar...', ARRAY['Türk Edebiyatı','Şiir','Yakup Şimşek']::text[], 8.5, '{"poet":"Yakup Şimşek","poet_slug":"yakup-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/helal-olsun-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgin Yuva Kurdu Gönül Tahtıma...', 'sevgin-yuva-kurdu-gonul-tahtima-dursun-elmas-lkyr0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Merhaba güzelim hoş geldin bana

Çevirme cemalin,bir dön bu yana.

Ne kadar yangınım bilesin sana

Güzümü bahara erdiren güzel...

Ummadık bir anda çıktın bahtıma

Sevgin yuva kurdu,gönül tahtıma.

Öpem yanağını, erem ahtıma

Gecemi gündüze döndüren güzel...

Sevgiler yüklenmiş, nazlı sözüne

Gülün şavkı vurmuş; o mah yüzüne

Gökkuşağı sinmiş; mahur gözüne

Sevdamı dizgine bindiren güzel...', 'Merhaba güzelim hoş geldin bana Çevirme cemalin,bir dön bu yana. Ne kadar yangınım bilesin sana Güzümü bahara erdiren güzel... Ummadık bir a...', ARRAY['Türk Edebiyatı','Şiir','Dursun Elmas']::text[], 8.5, '{"poet":"Dursun Elmas","poet_slug":"dursun-elmas","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sevgin-yuva-kurdu-gonul-tahtima-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '* İki Pare Can *', 'i-ki-pare-can-nevin-kurular-0w58l', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Biçare kalmış  umut, bir hal  çare olmaz mı

Bir anlıksa mutluluk, gayesi  yâr olmaz mı

Bir bedende iki can,iki bedendir o can.

Can ayrılık ardından,  bin bir  pare olmaz mı', 'Biçare kalmış  umut, bir hal  çare olmaz mı Bir anlıksa mutluluk, gayesi  yâr olmaz mı Bir bedende iki can,iki bedendir o can. Can ayrılık a...', ARRAY['Türk Edebiyatı','Şiir','Nevin Kurular']::text[], 8.5, '{"poet":"Nevin Kurular","poet_slug":"nevin-kurular","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/iki-pare-can-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Koftur görüşü', 'koftur-gorusu-suleyman-zaman-hub72', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kendi doğrusunda direten kişi

O her zaman bozar, düzenli işi

Savunma kardeşim, sekte duruşu

Böylesi insanın, koftur görüşü

Bir kişi bilir mi? Hemen her şeyi

Nedir muammanın, bunca cevheri

Akıtma tersine, akan bir nehri

Bağnazca duruşun, boştur görüşü

İçtin mi dünyada, Ab-ı Kevseri

Kıble kılmamışsan, didarı yari

Akar şu gözlerden, yaş zari, zari

Sevgisiz insanın, boştur görüşü

Ar damarı yoksa, eğer birinin

Onda yeri olmaz, asla sevinin

Değer verilmeyen, alın terinin

Böylesi kişinin, koftur görüşü

Kükrer aslan gibi, yoktur pençesi

Her zaman kendine, akar kepçesi

Kupkuru ağacın, olmaz meyvesi

Üretmez kişinin, boştur görüşü

Tanıdım nicesin, kendini bilmez

Cahilce duranlar, özünü görmez

Zamanım çağından, hiç geri kalmaz

Böylesi insanın, gaftır görüşü

                25.08.2005', 'Kendi doğrusunda direten kişi O her zaman bozar, düzenli işi Savunma kardeşim, sekte duruşu Böylesi insanın, koftur görüşü Bir kişi bilir mi...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Zaman']::text[], 8.5, '{"poet":"Süleyman Zaman","poet_slug":"suleyman-zaman","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/koftur-gorusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beş küçük çocuk Bir anne', 'bes-kucuk-cocuk-bir-anne-meram-yalinizoglu-3nln1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Beş küçük çocuk

Bir anne.

Daha anne yirmili yaşlarda.

Gençliğinin baharında

İlk baharı döndü

Kara bir kışa...

Beş küçük çocuk

Bir anne.

Ne yapar ne ederler

Ne yerler ne içerler

Geçen her bir günde

Açlığa yenik düşerler..

Beş küçük çocuk

Bir de anne.

Daha veletler muhtaç sevgiye

Neylesin ama anne? 

Ecel gelmiş,

Alacam seni demiş.

Aç kalan bebelerin

Aç kalsın.

Beş küçük çocuk

Ama yok artık bir anne....', 'Beş küçük çocuk Bir anne. Daha anne yirmili yaşlarda. Gençliğinin baharında İlk baharı döndü Kara bir kışa... Beş küçük çocuk Bir anne. Ne y...', ARRAY['Türk Edebiyatı','Şiir','Meram Yalınızoğlu']::text[], 8.5, '{"poet":"Meram Yalınızoğlu","poet_slug":"meram-yalinizoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/bes-kucuk-cocuk-bir-anne-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hülya Avsar Durumunda Olanlara Ithaf', 'hulya-avsar-durumunda-olanlara-ithaf-huseyin-avdic-ign0p', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yuvalarin Yikilmasini Önlemek Icin

Erkege ikinci e$ alma hakki verilmedikce,

Bo$anmalar eksik olmaz, genelevler hic kapanmaz.

Razi olmalidir kadinlar, Allah''in iznine; 

Erkek kadina, kadin erkege mahkûm edilmez.

******

Erkekler Kadin Haklarini Korumalidir

Malini, canini, irzini milletin emanet bil.

Bu emaneti gözetmemeyi büyük ihanet bil.

******

Sahipsiz Degilsin

Korkma, üzülme ey insan! Sahipsiz degilsin.

Seni gözeten birisi var, Allahca sahiplisin.

Berlin, Eylül 2005.', 'Yuvalarin Yikilmasini Önlemek Icin Erkege ikinci e$ alma hakki verilmedikce, Bo$anmalar eksik olmaz, genelevler hic kapanmaz. Razi olmalidir...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Avdic']::text[], 8.5, '{"poet":"Hüseyin Avdic","poet_slug":"huseyin-avdic","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/hulya-avsar-durumunda-olanlara-ithaf-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seda Sayana özlem', 'seda-sayana-ozlem-hasim-koc-6frlb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Özlemimiz sonsuz  sana

Dünya bir yana sen bir yana

Mutluluk dolarım belki ölürüm

Şöyle bir baksan bu yana

Sen SEDA SAYAN sın özelsin

ALLAHVERMİŞ çok güzelsin

Kanal  D ye çok teşekürler

Program başladı yine bizlerlesin

SEDA SAYAN ı izlemek büyük haz

Özlemekle geçti bütün yaz

Efkarlanıp çalsamda bazan saz

Sadece o an  avutur biraz

Hep özlüyorum hep özlüyorum

26-eylul-2005

pazartesi saat 09-30

istanbul', 'Özlemimiz sonsuz  sana Dünya bir yana sen bir yana Mutluluk dolarım belki ölürüm Şöyle bir baksan bu yana Sen SEDA SAYAN sın özelsin ALLAHVE...', ARRAY['Türk Edebiyatı','Şiir','Haşim Koç']::text[], 8.5, '{"poet":"Haşim Koç","poet_slug":"hasim-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/seda-sayana-ozlem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nejat Birdoğan Anısına', 'nejat-birdogan-anisina-suleyman-zaman-5w9kk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yazdın onca şiirleri

Aydınlattın beyinleri

Savunmuştun evrenseli

Dopdoluydun Nejat hocam

Boyun kadar, eserlerin

Canım dostum der dillerin

Olmadı hiç, ödünlerin

Yiğittin sen, Nejat Hocam

Araştırdın, sorguladın

Yaşam boyu, hiç durmadın

Bak tarihe, geçti adın

Ölümsüzsün, Nejat Hocam

Anadolu bilgesiydin

Gerçeklerin gür sesiydin

Dervişlerin, nefesiydin

Filozoftun, Nejat Hocam

Verdin Cevri Mahlasını

İnsanlığın, en hasını

Kamilliğin manasını

Öğrettin sen, Nejat Hocam

Yol gösterdin, Zamanıma

Sundun hizmet, insanlığa

Dünyada ki, tüm canlara

Değer verdin, Nejat Hocam

              10.04.2004 

 *; Nejat BİRDOĞAN; için yazılmıştır.

      Anısı önünde saygıyla eğiliyorum.', 'Yazdın onca şiirleri Aydınlattın beyinleri Savunmuştun evrenseli Dopdoluydun Nejat hocam Boyun kadar, eserlerin Canım dostum der dillerin Ol...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Zaman']::text[], 8.5, '{"poet":"Süleyman Zaman","poet_slug":"suleyman-zaman","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/nejat-birdogan-anisina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gün(lük)', 'gun-luk-mehmet-bulut-ddzbl', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yolcular,

hep aynı trenlerdeydiler,

trenler hep aynı raylardaydı.

Ve birgün 

yaprak isyan edip

kımıldayıverdi.

Artık gün,

(vedasız)

ayrılıkları yazacak

dokunulmamış

Gün(lük)  lere....', 'Yolcular, hep aynı trenlerdeydiler, trenler hep aynı raylardaydı. Ve birgün  yaprak isyan edip kımıldayıverdi. Artık gün, (vedasız) ayrılıkl...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Bulut']::text[], 8.5, '{"poet":"Mehmet Bulut","poet_slug":"mehmet-bulut","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/gun-luk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'KiRLi SaKaL', 'kirli-sakal-ali-aydogan-4chjf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir Adam gömdüm yanlızlıklara Adına Koydukları Ayaz 

yanlızlardaydı sevmişti bir kızı içten içe kalbini vermişti ona

hayaliydi onunla yasamak umutlarıydı kahve gözleri 

umutları ekmişti gögün gögsüne yar bicmişti gözlerinde

içinde kalan bir tutam sevda kül olmak üzereydi umutları

solmak yasamaya küser olmustu birde kirli sakalı vardı 

ve peşinden ayrılmıyan anlına yazılmıs kara yazısı

hep hayalindemi kalıcaktı sevmeleri özledigi sevgisini 

istedigi kişi hep ruyalarındamı kilitli kalıcaktı yinede isyan etmedi

sıcacık yuregi vardı elinde eskiden kalma bir kırık kalem yuregini yazdı 

yılmadı cabaladı yinede yaranamadı insanlıga kalsın kardeşim dünya ahirete isyan etmekse ben isyankarım', 'Bir Adam gömdüm yanlızlıklara Adına Koydukları Ayaz  yanlızlardaydı sevmişti bir kızı içten içe kalbini vermişti ona hayaliydi onunla yasama...', ARRAY['Türk Edebiyatı','Şiir','Ali Aydogan']::text[], 8.5, '{"poet":"Ali Aydogan","poet_slug":"ali-aydogan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/kirli-sakal-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Büyümek', 'buyumek-kadir-demirel-yqlko', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir bakamadım

Doğmuşum

Bir baktım

Büyümüşüm

Bir baktım

Evlenmişim

Bir baktım

Yaş Elli

Bir bakamadım

Ölmüşüm

(Ankara,26.09.2005)', 'Bir bakamadım Doğmuşum Bir baktım Büyümüşüm Bir baktım Evlenmişim Bir baktım Yaş Elli Bir bakamadım Ölmüşüm (Ankara,26.09.2005)...', ARRAY['Türk Edebiyatı','Şiir','Kadir Demirel']::text[], 8.5, '{"poet":"Kadir Demirel","poet_slug":"kadir-demirel","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/buyumek-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nasıl Ki', 'nasil-ki-meram-yalinizoglu-rw3hr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Nasıl ki

Bir kış günü kimsesiz bir çocuk

Sıcacık bir yuva,

Sıcacık bir tas çorba,

Sımsıcak bir yatak,

Anne kucağı ve

Ta içten kalple hissedilen sevgisini özlerse

Ben de öyle özledim

Arıyorum seni.

Nasıl ki

Yumurtadan çıkmış bir kuş

Annesinin getireceği bir solucanı,

Çırpınarak

Özgürce uçmayı

Sabırsızlıkla bekliyorsa

Ben de öyle bekliyorum seni

Nasıl ki

Gece gündüzü,

Gündüz de geceyi

Asla bırakmaz.

Nasıl ki

Gece gündüzle,

Gündüz de geceyle bitiyorsa

Benim ömrüm de 

Senin yanında

Senin kollarında bitsin.', 'Nasıl ki Bir kış günü kimsesiz bir çocuk Sıcacık bir yuva, Sıcacık bir tas çorba, Sımsıcak bir yatak, Anne kucağı ve Ta içten kalple hissedi...', ARRAY['Türk Edebiyatı','Şiir','Meram Yalınızoğlu']::text[], 8.5, '{"poet":"Meram Yalınızoğlu","poet_slug":"meram-yalinizoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/nasil-ki-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk İklimi 1 (Medine)', 'ask-i-klimi-1-medine-osman-erdogmus-vbr89', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'AŞK İKLİMİ 1

Müminin heyecanı deryaları doldursun,

İman çağlayanları hiç durmasın hep coşsun.

Karıncalar misali Mescid-i Nebevi’ye,

Akan müslümanların hepisi felah bulsun.

Yeşil Kubbe müminin gönlünde bir incidir,

Ya Nebi (s.a.v) Sen,Rabb’imin Habibisin,kulusun.

Yanında arkadaşın Ebubekir ve Ömer,

Hüccacın milyonları size rahmet okusun.

Ravzanda dökülen yaş ve kılınan namazlar,

Bir nefestir cennetten içimizi doldursun.

Ne muhteşem manzara ve o kadar da sade,

Cennet görmek isteyen Cennet Baki’ye koşsun.

Kuba; namazın cemaatle ilk kılınışı,

Ve devlet temelleri üzerine otursun.

İki kıblesi olan kıbleteyni görsün de,

Çeksin iliklerine ciğerleri doldursun.

Dile gelse şu Uhud,ah içini bir dökse,

Sayfaları çevirip hatıralar konuşsun.

Hamza şehitler piri, gökyüzünü ağlattı,

Ve okçular tarihe bir altın sayfa sunsun.

Geldim kapına işte yığın yığın günahla,

Rahmet Peygamberisin Sen affı seviyorsun.

Şefaatin de haktır büyük günahkarlara,

Sancağının altında bize yer bulur musun.

Sokaklarda cezbe var yayılır dalga dalga,

Kalplerde bir rayiha muhammedi kokusun.

Tarih kaynıyor her yer islamdan bir parça var,

Heyben ne kadar ise o kadar alıyorsun.

Anlatılmaz bu iklim yaşanır zerre zerre,

Yaşamak nasip oldu, oldu şükürler olsun. 

(Bu yıl da Hacc`a gidip dönenlerin

Hacc`ı mebrur duaları makbul olması 

dileği ile) 

Osman Erdoğmuş', 'AŞK İKLİMİ 1 Müminin heyecanı deryaları doldursun, İman çağlayanları hiç durmasın hep coşsun. Karıncalar misali Mescid-i Nebevi’ye, Akan müs...', ARRAY['Türk Edebiyatı','Şiir','Osman Erdoğmuş']::text[], 8.5, '{"poet":"Osman Erdoğmuş","poet_slug":"osman-erdogmus","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/ask-iklimi-1-medine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülbene fanlarından', 'gulbene-fanlarindan-hasim-koc-q5isd', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevgi dolu yüreklerle

GÜLBEN ERGEN fanlarıyız

Mutlu olduk her konserde

Fanı değil canlarıyız

Fan başımız GÜLBEN ERGEN

Toplandık her yerden

Yüzler binler olduk bir iken

Mutluluk dolduk 

GÜLBEN ERGEN deki sevgiden

Geçmişimiz mutluluk

Bu günümüz mutluluk

Yarınımız mutluluk

Fan başımız

Sevgili GÜLBEN ERGEN le

26-eylül-2005

pazartesi saat 09-30

istanbul', 'Sevgi dolu yüreklerle GÜLBEN ERGEN fanlarıyız Mutlu olduk her konserde Fanı değil canlarıyız Fan başımız GÜLBEN ERGEN Toplandık her yerden Y...', ARRAY['Türk Edebiyatı','Şiir','Haşim Koç']::text[], 8.5, '{"poet":"Haşim Koç","poet_slug":"hasim-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gulbene-fanlarindan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sigaram İçin', 'sigaram-i-cin-kerem-kayar-0bdm3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bazen neden sigara içtiğimi düşünürüm 

sadece duman için mi? ... 

Aklıma bir soru takılır ansızın,benim için yanan varmı ondan başka... 

Onu da ben yakarım aslında benim için yansın diye... 

Belkide kendimi teselli ediyorum onunla... 

Benim için hayatta yanan tek somut varlık o... 

Sanırımher zaman sigara içeceğim... 

Öyle bir bağlılık ki sonunda onun yüzünden öleceğim...', 'Bazen neden sigara içtiğimi düşünürüm  sadece duman için mi? ...  Aklıma bir soru takılır ansızın,benim için yanan varmı ondan başka...  Onu...', ARRAY['Türk Edebiyatı','Şiir','Kerem Kayar']::text[], 8.5, '{"poet":"Kerem Kayar","poet_slug":"kerem-kayar","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sigaram-icin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünlerdeki gibi sev beni.', 'dunlerdeki-gibi-sev-beni-zeynep-aydinlioglu-lee94', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'yarın yine güneşim ol, 

tıpkı bugünkü gibi 

sorgusuz sualsiz sev beni, 

benim seni sevdigim gibi, 

olurmu canm. 

daima bahar ol mevsim degişsede.. 

saçlarına karda yagsa, 

yagmurlarda yagsa gözlerinden, 

tıpkı dünkü gibi, sorgusuz sualsiz sev beni, 

benim seni sevdigim gibi, 

olurmu canm.', 'yarın yine güneşim ol,  tıpkı bugünkü gibi  sorgusuz sualsiz sev beni,  benim seni sevdigim gibi,  olurmu canm.  daima bahar ol mevsim degiş...', ARRAY['Türk Edebiyatı','Şiir','Zeynep Aydınlıoğlu']::text[], 8.5, '{"poet":"Zeynep Aydınlıoğlu","poet_slug":"zeynep-aydinlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/dunlerdeki-gibi-sev-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Azap', 'azap-mehmet-bulut-2u4az', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu kaçıncı

bekleyiştir yüreğim...? 

Her esir azad olmuşken

bitmiş savaşların seferlerinden...

Hergün aynı heyecan

aynı ümitle

bıkmadınmı beklemekten...? 

Oysa; 

giden dönmüyor gitti yerden.

O yerde bilinmez bir heyecan

kopmuş yüreğinden,

ki dönsede artık

bulamaz seni yerinde...

Çünkü gelen

gideceğini bilerek 

gelecektir seferinden...

..........

....', 'Bu kaçıncı bekleyiştir yüreğim...?  Her esir azad olmuşken bitmiş savaşların seferlerinden... Hergün aynı heyecan aynı ümitle bıkmadınmı bek...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Bulut']::text[], 8.5, '{"poet":"Mehmet Bulut","poet_slug":"mehmet-bulut","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/azap-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk İklimi (Mekke)', 'ask-i-klimi-mekke-osman-erdogmus-94cyj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'AŞK İKLİMİ 2

Peygamberlerin şehri Mekke-i Mükerreme,

Burdan doğdu en büyük medeniyet aleme.

Çırpınıyor yürekler heyecanlar dorukta,

Lebbeyk Allah sesleri yankılanr boşlukta.

O coşku o heyecan hiçbir şeye benzemez,

Hüccacın duyguları asla tarif edilmez.

Kıblegahım kabedir gayrısı artık haram,

Fevelli vecheke şetral mescid-il haram.

Mevlam kutsadı seni,sanadır bu şeref şan,

Seni kıble bilmeyen insanlar çok perişan.

Nedendir bu karalık Allah aşkına söyle,

Ümmetin günahı mı kararttı seni öyle.

Allah’ın izni ile İsmail ayağından,

Zemzem suyu fışkırdı kabenin tam yanından. 

Şifa oldu ümmete on dört asırdan beri,

Serinletti sıcakta tutuşan yürekleri.

Mahşerden bir görünüm sunar sanki Arafat,

Hacılığa ilk adım burda atar cemaat.

Öğle ile ikindi birleşir bir araya,

Vakfeye durulunca eller kalkar semaya.

Veda Hutbesi bir nur,şahit çöller,topraklar,

Ümmetinin andıdır söyler durur dudaklar.

Müzdelife taşların toplanıldığı mekan,

Minada şükrünü kurban ile sunar insan.

Kılınır bir arada akşam yatsı namazı,

Arş-ı alaya çıkar müminlerin niyazı.

Günahlardan arınıp yeni hayata başla,

İçindeki şeytanla cemeratları taşla.

Anadan doğmuş gibi günahsız ve ter temiz,

Yeşillensin kalplerde Resulullah sevgimiz.

Paratoner çekerse nasıl yıldırımları,

Vahyin davetçisidir Hiranın kayaları.

İslam burda başladı ilk emir burda geldi.

Kırk yaşına gelince Peygamberlik verildi.

Şereflendi sevr,çünkü misafirdi peygamber,

Mağara arkadaşı Sıddık ile beraber.

Sakladı sizi üç gün atıldı tehlikeler,

Kuşlar yuva yapmıştı ağ ördü örümcekler.

Yıldızların devranı gibi sende Kabeyi,

Tavaf edip dikkat et incitme hiç kimseyi.

Bu devlet bana kondu dünya bir yana dursun,

Beytullah’a yüz sürdüm,sürdün şükürler olsun.

(Bu sene Hacc`a gidenlerin Haccları mebrur,

Duaları makbul olması dileği ile.)', 'AŞK İKLİMİ 2 Peygamberlerin şehri Mekke-i Mükerreme, Burdan doğdu en büyük medeniyet aleme. Çırpınıyor yürekler heyecanlar dorukta, Lebbeyk ...', ARRAY['Türk Edebiyatı','Şiir','Osman Erdoğmuş']::text[], 8.5, '{"poet":"Osman Erdoğmuş","poet_slug":"osman-erdogmus","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/ask-iklimi-mekke-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçimdeki Çocuk', 'i-cimdeki-cocuk-ahmet-ormanci-9hvvy', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir çocuk var içimde,

İstekleri sınırsız.

Bazen akıllı uslu, adam gibi,

Bazen mız mız mı mız mız.

Bir çocuk var içimde,

Hayalleri toz pembe.

Bazen gider aklı başından,

Bazen gelir kendine.

Bir çocuk vaar içimde,

Herkese sevgi dolu.

Bazen açar havası, günlük güneşlik,

Bazen olur bulutlu.

Bir çocuk var içimde,

Kimseye söyleyemediğim.

Bazen mutluyum onunla,

Bazen söz dinletemediğim.

25.09.2005

Ahmet Ormancı', 'Bir çocuk var içimde, İstekleri sınırsız. Bazen akıllı uslu, adam gibi, Bazen mız mız mı mız mız. Bir çocuk var içimde, Hayalleri toz pembe....', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ormancı']::text[], 8.5, '{"poet":"Ahmet Ormancı","poet_slug":"ahmet-ormanci","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/icimdeki-cocuk-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İzmit ve Ben', 'i-zmit-ve-ben-kerem-kayar-kbmqy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben İzmit’i izliyordum,

İzmit beni...

Yalnız mıydı o da

benim gibi geceleri?

Önce İzmit’i anlatmalıydım

gördüğüm kadarıyla.

Sonra İzmit beni anlatmalıydı

hissettiği kadar...

Masum düşlerimi,

en uç hayallerde sevişlerimi,

soğumaya bıraktığım bir yudum çayı,

titreyen sağ elimin

vazgeçilmezi olan sigarayı...

Bu kadar kısaydı

beni anlatmak.

Ya İzmit?

Hangi aşıkların

yarım kalmış hikâyeleri saklı

hangi köhnelerinde?

Hangi sarhoşlar

köpek öldüren şarabıyla

hangi gecelerinde kaybolur?

Ve o gözkırpan sokak lambaları...

Kaç hayale tanıklık eder

kim bilir?

Biliyor musun İzmit,

sen körsün.

Ben seni

seyri şehir ederken,

sen beni görüyor muydun?

İzmit başka bu gece...

Ağlıyor musun?

Benim kadar vefasız,

benim kadar yalnız...

Belli.

İşte öylesine

Kerem’in

“bir şehir” diyemediği

İzmit’i...

İzmit ve ben

ağlıyoruz bu gece.

Kimsesiz gecelerin

kimsesizliğinde

iki çocuk gibi...

Biri şehre sığınmış,

biri şehrin içine.', 'Ben İzmit’i izliyordum, İzmit beni... Yalnız mıydı o da benim gibi geceleri? Önce İzmit’i anlatmalıydım gördüğüm kadarıyla. Sonra İzmit beni...', ARRAY['Türk Edebiyatı','Şiir','Kerem Kayar']::text[], 8.5, '{"poet":"Kerem Kayar","poet_slug":"kerem-kayar","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/gece-de-izmit-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnat', 'i-nat-fatih-kuyucu-htexp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kah köşeye attım seni

Kah yerden yere vurdum

Kah kaçtım köşe bucak 

Kovaladım bazende çaresiz

İçinden çıkamadım 

Çıktın içimden, atamadım 

İnat ettim sana inat 

Seni kendimle yaşattım...', 'Kah köşeye attım seni Kah yerden yere vurdum Kah kaçtım köşe bucak  Kovaladım bazende çaresiz İçinden çıkamadım  Çıktın içimden, atamadım  İ...', ARRAY['Türk Edebiyatı','Şiir','Fatih Kuyucu']::text[], 8.5, '{"poet":"Fatih Kuyucu","poet_slug":"fatih-kuyucu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/inat-29-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'oyuncaklarim', 'oyuncaklarim-ahmet-ormanci-4vlhf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Oyuncaklarım var benim,

Tıpkı çocuklarınki gibi.

Hiç bozulmadıkları için,

Asla üzmezler beni.

Dertlerim, tasalarım birer oyuncak

Benim için.

Elbet zamanı geldiğinde,

Tek tek oynarım her biriyle.

Sizin de varsa derdiniz,

Ki vardır.

Getirin paylaşalım,

Eğer isterseniz,

Buyrun, beraber oynayalım.', 'Oyuncaklarım var benim, Tıpkı çocuklarınki gibi. Hiç bozulmadıkları için, Asla üzmezler beni. Dertlerim, tasalarım birer oyuncak Benim için....', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ormancı']::text[], 8.5, '{"poet":"Ahmet Ormancı","poet_slug":"ahmet-ormanci","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/oyuncaklarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Dörtlük de Sen Yaz / BETER AKŞAMLAR', 'bir-dortluk-de-sen-yaz-beter-aksamlar-siir-perisi-grubu-uluyx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Şiir Perisi Grubumuzun ''''Bir Dörtlük de Sen Yaz/AKŞAMLAR'''' isimli ortak şiirimize bir dörtlükle katılan herkes bu dörtlüğünün, grubumuzun ŞİİR PERİSİ GRUBU yetkili şairlik sayfasında yayınlanmasına izin vermiş sayılmaktadır. Kendi dörtlüğü dışında, şiirin bir kısmını yada tamamını sayfasında yayınlamak isteyen şairler, diğerlerinden izin almak zorundadır...(Yasal Uyarı)  

Ne zaman başımı yastığa koysam 

Diken olur yatak,BATAR akşamlar... 

Uzaklardan yanık bir hava duysam 

Dertlere dert katar BETER akşamlar...********(Ayak Dörtlüğü)      Dursun Elmas 

1. 

Gündüz aklımdasın, gece düşümde 

Dertler nöbet bekler her an başımda 

Acı okunuyor şu gözyaşımda 

Durmaz, kalbe hasret KATAR akşamlar...********Turan Orak 

2 

Gam gelir tazeler yürekte derdi 

Ara ki bulasın yiğidi, merdi 

Vakit tamam oldu, vuslata erdi 

Hüznümün koynunda YATAR akşamlar*********Zülfikar Yapar Kaleli 

3 

hüzün kokar ufuk, güneş sönerken 

kızıl bir kıyamet yürek kanarken 

kalemim hep ağlar içim yanarken 

sayfalarca şiir SATAR akşamlar.************S.Nizamoğulları 

4. 

Hasrete uzanır derbeder kollar 

Yankılanır sesler, haykırır yollar 

Sevda ateşiyle kavrulur yıllar 

Maziye sarılıp YATAR aşkamlar.**************Feride Özmat 

5 

Aşık hasret çeker, yollara bakar. 

Bakar da aklına vuslatı takar. 

Sevda yollarında gönlünü yakar 

Aşığı geceye ATAR akşamlar. ************Necmi ÜNSAL 

6 

Dostumdur geceler derdime derman 

Her gece hasrettir, vuslata harman 

Saat durur artık işlemez zaman 

Karanlığa hüzün KATAR akşamlar.******* Mehmet TEKECİ 

7 

Maziye takılıp ufka dalınca, 

Her içli türküden yara alınca. 

Anadan, sıladan ayrı kalınca, 

Zehirli ok gibi BATAR akşamlar.**********M.Erkenekli 

8 

Sigara dumanım tüter bu gece 

Kalem aldım ele, tektir bir hece 

Aglamaklı gözler, birer bilmece 

Sığmaz Kandillere, TÜTER aksamlar.*******Yurdagül Kurnaz 

9 

Karanlık çökünce bağ dallarıma 

Hüzün kanatlanır dağ yollarıma. 

Dost olur yıldızlar boş kollarıma, 

Umutlara yelken TUTAR akşamlar.**********Suna Doğanay 

10 

Güneş kaybolunca dağın ardından 

İçimde bir sızı başlar derinden 

Gönül parçalanır binbir yerinden 

En keskin kılıçtan BETER akşamlar.*********Saim BASTIK 

11. 

Bir gülün açması bahara yetmez 

Dikenin dalında bülbüller ötmez 

Gönül sevdalıysa aşk kolay bitmez 

Sevdalı gönüle YETER akşamlar.*************Tuncay Akdeniz 

12. 

Gün bitip de güneş ufka kayınca 

Karanlık rengini göğe yayınca 

Dostluk sundu bana ömrüm boyunca 

Sırrımı sırrına KATAR akşamlar.*****************gül_i_zar 

13. 

Siyah örtülere, bürünür durur, 

Gönlüm, gün batınca, sürünür durur, 

Gözüme, kabuslar,görünür durur, 

Günlerimi bir bir, yutar AKŞAMLAR.***********K.Tahir Özcan 

14. 

Dolanır boyuna, sarılır elim 

Sen diye söyler hep, aşk diye dilim 

Yorganı, döşeği, altında kilim 

Vermez zevk-i fırsat, SATAR akşamlar********Ali AKAR 

15 

Kaç zemheri düşer, yaşlı gözüme 

Kelepçe vurulur, yaslı sözüme 

Karlar yağdırılır, harlı közüme 

Yolcusu Çölümün KATAR akşamlar**************ORKUN IŞIK 

16 

Düşlerim yalandır sözünde durmaz 

Geceler sabaha hayalsiz varmaz 

Sevdadır başımda halimi sormaz 

Bağrıma yaslanıp YAKAR akşamlar.*************Z.Nilgün Gökçeöz 

17 

Amansız bu derdim yoktur çaresi 

Gözlerimden akar hasret haresi 

Dillerin sitemi, taşın yaresi 

Beni sessiz sessiz YUTAR akşamlar.**********Hülya Karaca 

18 

Aşkın nefesiyle dolup taştıysam 

Sevdanın renginde güller açtıysam 

Gönülden gönüle ışık saçtıysam 

Sevginin dumanı TÜTER AKŞAMLAR.************Mustafa Sami 

19 

Beynimde ağrılar arttıkça artar, 

Çıldıran duygular ruhumu yırtar, 

Yiğidi gurbette acıyla tartar, 

Ömürle tükenie BİTERakşamlar*****************Hasan Ulusoy 

20 

Yıldızlar benimle beraber ağlar, 

Ruhumu karanlık kendine bağlar 

Senin hasretin yüreğim dağlar 

Sessizce oturup, YİTER akşamlar.************Fatih Kuşak 

21. 

Görmedi baharı, çağlar Türkmenim, 

Karayı karaya bağlar Türkmenim, 

Şimdi Telafer’de ağlar Türkmenim, 

Hergün darağacı, ÇATAR akşamlar.***********Emin BAYDİL 

Şiir Perisi grubumuzun üyesi olan şairlerin ortak şiiridir hepsine teşekkür ederiz.. :)', 'Şiir Perisi Grubumuzun ''''Bir Dörtlük de Sen Yaz/AKŞAMLAR'''' isimli ortak şiirimize bir dörtlükle katılan herkes bu dörtlüğünün, grubumuzun Şİ...', ARRAY['Türk Edebiyatı','Şiir','Şiir Perisi Grubu']::text[], 8.5, '{"poet":"Şiir Perisi Grubu","poet_slug":"siir-perisi-grubu","theme":"Türk Şiiri","is_hero":false,"total_lines":111,"source_url":"https://www.antoloji.com/bir-dortluk-de-sen-yaz-beter-aksamlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüzünlüyüm Bu Gece', 'huzunluyum-bu-gece-mehmet-sait-akkus-uq1ty', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hüzünlüyüm bu gece

Şarkılar benim olsun

Şerefe diyelim dostlar

Kadehler benim için kalsın

Susmasın şarkılar

Derdimi unutana kadar

Beraberce eğlenelim

Son bulsun bu acılar

Unutalım dostlarım

Sabahları bulalım

İçelim hep bu gece

Taki sarhoş olalım', 'Hüzünlüyüm bu gece Şarkılar benim olsun Şerefe diyelim dostlar Kadehler benim için kalsın Susmasın şarkılar Derdimi unutana kadar Beraberce ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Sait Akkuş']::text[], 8.5, '{"poet":"Mehmet Sait Akkuş","poet_slug":"mehmet-sait-akkus","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/huzunluyum-bu-gece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim Derdim', 'benim-derdim-ahmet-ormanci-zudws', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen benim tek derdim,

Tek yaramdın kalbimde,

Sabah akşam dinlediğim.

Sen benimsin, benim derdim.

Tek yarimdin kalbimde,

gece gündüz düşlediğim.

Sen benim tek derdim,

Ben sana benim derdim.

Bir kerecik gelseydin,

Ah! Ah benim derdim.', 'Sen benim tek derdim, Tek yaramdın kalbimde, Sabah akşam dinlediğim. Sen benimsin, benim derdim. Tek yarimdin kalbimde, gece gündüz düşlediğ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ormancı']::text[], 8.5, '{"poet":"Ahmet Ormancı","poet_slug":"ahmet-ormanci","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/benim-derdim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Merhaba Yalnızlık', 'merhaba-yalnizlik-mehmet-sait-akkus-ubvm0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Belki bir gün unuturuz

Yaşadığımız o günleri

Sus konuşma ne olursun

Arama artık o günleri

Ne olmuşsa geride kaldı

Artık bir daha anmıyalım

Beni dertlere saldı

İstersen bir daha konuşmayalım

Gönül isterdiki bir olaydık

Dünya dönünceye kadar

Böyle ayrı olmamalıydık

Ömrümüzün sonuna kadar

Olan oldu artık unutalım

Demek böyle olmalıydık

Artık ayrı yerde kalalım

En iyisi böyle kalmalıydık', 'Belki bir gün unuturuz Yaşadığımız o günleri Sus konuşma ne olursun Arama artık o günleri Ne olmuşsa geride kaldı Artık bir daha anmıyalım B...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Sait Akkuş']::text[], 8.5, '{"poet":"Mehmet Sait Akkuş","poet_slug":"mehmet-sait-akkus","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/merhaba-yalnizlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece Ve Ben', 'gece-ve-ben-fidan-bulut-tagnx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Her gece sinerim sensizliğe,

Bir geceyi düşünürüm bir de seni.

Güneşi bir de

Kendim gibi. Ukalalık mı ne? 

Işığıyla sıcağıyla

Nasıl da gecenin koynuna dalar

Ancak gece bilir sızılarını

Dinginliği gece de saklı.

Gece sığınağım olur

Issızlığım açlığım arsızlığım

Bir kendime bir sana susamışlığım.

Eski zaman trenleri geçer düşümden

Düşüm uyanık ben uyanık,

Dumanı serilir önüme

Taze yanık yavaş ama sesli.

Kimi ortaçağda dilenirim aşkı

Engizisyon mahkemeleri kurulur ömrüme.

Kimi kafamca Romayı yakar geçerim,

Erosla dostluğa soyunurum

Belki bir ok ucu aşk senden yana.

Kirletirim tenimi hoyratça

Sindiğim gece koynunda

Ve yıkanırım konar nil kıyılarına.

Giyerim geceyi sinsice

Edebli edebsiz hınçlarımın küfrüne

Hapsederim tüm iyi niyetleri fitnelere

Eceli gelen eder derler hacet mabet dibine

Hacetin kendiyim 

Ecelin işi çok bana gelince

Saklanırım yine geceye haince

Güneşi bulmak niyetine

Ne yazık

Sabah olup da çıkınca gecenin koynundan

Tüm dünyaya yetirip gücünü

Görmezden gelir paylaştığı yerde ki beni

Gözlerim kapalı güne

Beklerim geceyi ben yine......', 'Her gece sinerim sensizliğe, Bir geceyi düşünürüm bir de seni. Güneşi bir de Kendim gibi. Ukalalık mı ne?  Işığıyla sıcağıyla Nasıl da gecen...', ARRAY['Türk Edebiyatı','Şiir','Fidan Bulut']::text[], 8.5, '{"poet":"Fidan Bulut","poet_slug":"fidan-bulut","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/gece-ve-ben-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızdım', 'yalnizdim-ahmet-ormanci-ldbhg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu gece sahile indim, yalnız.

Oturdum kumsalda bir süre.

Yakamozlara karışan,

Dalgaların sesini dinledim.

Acaba dedim. kendi kendime.

Dalgalar susar da, dinler mi beni.

Yoksa, güzel bir deniz kızı gelir de,

Sorar mı derdimi.

Boşuna bekledim saatlerce.

Ne dalgalar susup, beni dinledi.

Ne bir deniz kızı,

Sordu derdimi.', 'Bu gece sahile indim, yalnız. Oturdum kumsalda bir süre. Yakamozlara karışan, Dalgaların sesini dinledim. Acaba dedim. kendi kendime. Dalgal...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ormancı']::text[], 8.5, '{"poet":"Ahmet Ormancı","poet_slug":"ahmet-ormanci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yalnizdim-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül Dalı Baki', 'gul-dali-baki-fidan-bulut-jozjb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir sabah kalktığında bitmiş her şey,

Gül yapraklarında çiğ taneleri gibi

Habersiz fark ettirmeden çekilmiş ruhundan

Şimdi elinde gül dalıdır baki

Baharlar gelecek yapraklanacak

Yine tomurcuk, yine çiğ taneleri billur

Dikeni, bülbülü, goncası coşacak.

Kandırmacası serilecek hayatın.

Oysa kanın donacak sıcağında

Boş artık dibine kadar boş

Tek gerçeğin; 

Güldallarında sen,Sende güldalları huzurlu', 'Bir sabah kalktığında bitmiş her şey, Gül yapraklarında çiğ taneleri gibi Habersiz fark ettirmeden çekilmiş ruhundan Şimdi elinde gül dalıdı...', ARRAY['Türk Edebiyatı','Şiir','Fidan Bulut']::text[], 8.5, '{"poet":"Fidan Bulut","poet_slug":"fidan-bulut","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gul-dali-baki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Islak', 'islak-kadir-ucvet-1f2mv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yeşil bir hüzün

 ‘Gök’ün yüzünde.,

“Bulutlar gamze yüzde

nazarlarını değdiren göz pınarları  kaynak

 bıyıklara çağlayan

gözyaşları sağanak..”

olmalıydı...:

Bu soyut yüzde duran ıslak..

olarak.', 'Yeşil bir hüzün  ‘Gök’ün yüzünde., “Bulutlar gamze yüzde nazarlarını değdiren göz pınarları  kaynak  bıyıklara çağlayan gözyaşları sağanak.....', ARRAY['Türk Edebiyatı','Şiir','Kadir Üçvet']::text[], 8.5, '{"poet":"Kadir Üçvet","poet_slug":"kadir-ucvet","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/islak-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Süreğen Kabus', 'suregen-kabus-utku-demir-kzqdo', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne bitmez baş edilmez bir derttir

Gecesi gündüzü olmayan,

Hayatı unutturup zamanı durduran.

Her sabah gözleri yaşartıp,

Kurumasına müsade etmeden hüznü yapıştıran

Kalbimizin ölümcül kesiğini her an yaşatan.

Anılar yüreğimize ok gibi saplandığında,

O, düşlerimize zehir gibi serpildiğinde

Çaresiz soğuk betonların örtülerine muhtacızdır,

Dindirmek için parlamaya hazır korluğunu.

Size yapılsa da yapamazsınız bu ihaneti kendinize.

Suçlu, zavallı, haksız olan duruma düşürülseniz de,

Duramazsınız gerçek sevgisiz.

O sevdiremezdi ki istese de 

Bizdik seven biz...

Bir saniye çıkarmadığınızdır düşüncelerinizden

Yok edemezsiniz sımsıkı sardığınız duygularınızı

Öyle bir sevgi yaratmışsınızdır ki:

Bulamazsınız kökünü devrilmez baltalanmışlığında

Uçsuz bucaksız bir çölde kalsanız da

Başarırsınız hayattaki olağan unutkanlığı bozmayı.

Çalı ateşiyle ısınan bir kulübede

Efkarlanırsınız şarap kokusuyla 

Tattıkça, dudaklarını hatırlar

Ay ışığının hasret yakan büyüsünde

Gözlerinizden yağdırdığınız yağmuru 

Akıtırsınız kanayan damarlara

Onun kasvetli mahrumiyetinde bile

Var edersiniz yakarış yüklü sevgiyi. 

Yıllar önce gökyüzüne çizdiğiniz beyaz kanatlı melek

Söndürür geceyi aydınlatan yıldızları siyah peleriniyle

Atıp boynunuza halatı sürükler sizi geçmişe peşinden

Gittikçe ardından akrepler sokar sizi sol göğsünüzden

Ejderhaların arasından geçerken ateşlerinde yanar bedeniniz

Yılanların tıslamalarında nefessiz kalırsınız boğulurken

Nihayetinde ölüm çağrısı duyulur çanların kutsal sesinden

Gömülerin ürkütücü harıltıları yaklaşır yeraltından.

Mucizevi bir umuttur içinizde kalan,

O yeter çıkarmaya sizi, yaşanan bu süreğen kabustan', 'Ne bitmez baş edilmez bir derttir Gecesi gündüzü olmayan, Hayatı unutturup zamanı durduran. Her sabah gözleri yaşartıp, Kurumasına müsade et...', ARRAY['Türk Edebiyatı','Şiir','Utku Demir']::text[], 8.5, '{"poet":"Utku Demir","poet_slug":"utku-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/suregen-kabus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Farkındalıklar', 'farkindaliklar-kadir-ucvet-j4gc5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir anda

“bir andalık”

mağduriyetler cumhuriyeti ‘idi’

aşkım, sana

darmadağın; 

bir erki diğerine değmez

“o” anları, ile,

FARKINDALIKLAR

Mağruriyeti ‘idi’

Aşkım sana...

Aşkım (dı)  sana..', 'Bir anda “bir andalık” mağduriyetler cumhuriyeti ‘idi’ aşkım, sana darmadağın;  bir erki diğerine değmez “o” anları, ile, FARKINDALIKLAR Mağ...', ARRAY['Türk Edebiyatı','Şiir','Kadir Üçvet']::text[], 8.5, '{"poet":"Kadir Üçvet","poet_slug":"kadir-ucvet","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/farkindaliklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Git….', 'git-ahmet-toper-y4k7l', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gidiyorsun damla pınarım

Git…

Ardında kocaman bir boşluk bıraktığını düşünerek

İçine sonsuzluğun gizlendiği boşluğa küserek

Gözlerimde kıyılarına gizlenmiş

Çarpmasını bilmeyen yüksek bir gerilim

Yüreğime dar gelmiş

Yağmasını bilmeyen sağanak yağmurum

Kendinde kaybolan duygularım

Sahiplerini arar oldu boş ellerde

Bedenimi kamçılayan sivri dillerde

Umursamadığın bir adam

Yalnız bir ev

Kırık bir kalp

Sana kal diyen çaresiz eller

Ardında kalan boşluğu dolduranlar', 'Gidiyorsun damla pınarım Git… Ardında kocaman bir boşluk bıraktığını düşünerek İçine sonsuzluğun gizlendiği boşluğa küserek Gözlerimde kıyıl...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Toper']::text[], 8.5, '{"poet":"Ahmet Toper","poet_slug":"ahmet-toper","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/git-133-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acaba Yıldız Mı?', 'acaba-yildiz-mi-ahmet-ormanci-o7exj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gecenin karanlığında,

Parlayan yıldızlar.

Söyleyin bize; 

Ulaşılmaz olmadığınızı.

Haykırın; insanların yıldızlaşacağını.

Eğer yaşatırsak,

İçimizdeki çocuklarımızı.

Gelin paylaşalım, aşımızı, ekmeğimizi.

En çok da sevgimizi paylaşalım,

Çıkar gözetmeksizin, çocuklar gibi.

İşte o zaman göreceğiz,

Yıldızların yanında

Kendi parıltımızı.

Ve gökyüzüne bakıp ta,

Bizi yıldız zanneden insanları', 'Gecenin karanlığında, Parlayan yıldızlar. Söyleyin bize;  Ulaşılmaz olmadığınızı. Haykırın; insanların yıldızlaşacağını. Eğer yaşatırsak, İç...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ormancı']::text[], 8.5, '{"poet":"Ahmet Ormancı","poet_slug":"ahmet-ormanci","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/acaba-yildiz-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayatı Yaşamak', 'hayati-yasamak-ahmet-ormanci-snbqm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Öyle yaşamalıyım hayatı,

Çalmadığım bir tek kapı kalmamalı,

Öğrenmek için.

Tanımadığım insan kalmamalı,

En uzak diyarlarda bile olsa,

Yardımına koşmak için.

Uzatmadığım el,

Almadığım gönül kalmamalı,

Güldürmediğim yüz,

Duyurmadığım güzel söz de kalmamalı

İnsanlara.

Öyle yaşamalıyım dolu dolu hayatı,

Ve öylece gitmeliyim ötelere,

Gözlerim kapalı.', 'Öyle yaşamalıyım hayatı, Çalmadığım bir tek kapı kalmamalı, Öğrenmek için. Tanımadığım insan kalmamalı, En uzak diyarlarda bile olsa, Yardım...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ormancı']::text[], 8.5, '{"poet":"Ahmet Ormancı","poet_slug":"ahmet-ormanci","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/hayati-yasamak-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece', 'gece-ahmet-ormanci-hul33', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen hey gece,

Söyle bana,

Neşe misin,

Hüzün mü benim için.

Aslında mutluyum,

Yalnızken seninle.

Belki de bu; 

Duygularımı dinlediğin içindir.

Beni en iyi anlayan,

En iyi dostumsun sen.

Kâh neşesin bana,

Kâh hüzün değil mi? 

Ama gerçek hayat,

Senden ayrıldığım zaman başlıyor.

Beni hüzünlendiren de işte bu değil mi?', 'Sen hey gece, Söyle bana, Neşe misin, Hüzün mü benim için. Aslında mutluyum, Yalnızken seninle. Belki de bu;  Duygularımı dinlediğin içindir...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ormancı']::text[], 8.5, '{"poet":"Ahmet Ormancı","poet_slug":"ahmet-ormanci","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/gece-173-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hesabım Var', 'hesabim-var-i-sa-tekin-szo0u', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ey yalnızlık

                 hesabım var

Oturup mahşere kadar

                  bekleyeceğim

Vuracağım on ikiden

Yırtıp atacağım

Karanlık geceleri

Kahır beslemem yüreğimde

Gerekirse hançerlerim

Ey yalnızlık

                hesabım var

Oturup kederlenmeyeceğim

                                  sonsuza dek

Çırpınışın beyhude

Söküp atacağım

Volkan gibi patlayacağım

Beynimde depremler olsa bile

Ey yalnızlık 

                 hesabım var

Üzülüp hüzünlenmeyeceğim

Vurdum sırtıma gidiyorum

Kalbim teklemez ise eğer

Yolum uzun

Güzelliklere gidiyorum

Umuda 

Oraya

Dostlara gidiyorum', 'Ey yalnızlık                  hesabım var Oturup mahşere kadar                   bekleyeceğim Vuracağım on ikiden Yırtıp atacağım Karanlık g...', ARRAY['Türk Edebiyatı','Şiir','İsa Tekin']::text[], 8.5, '{"poet":"İsa Tekin","poet_slug":"i-sa-tekin","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/hesabim-var-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '* Kıbrıs''ta Güzel Kumar Oynanır *', 'kibris-ta-guzel-kumar-oynanir-gulsen-senderin-eelem', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Haydi gel dostum, Kıbrıs için iki biletim var

Kumarın hası orada oynanıyor duydun mu

Haberin yoksa öğren işte, Kıbrıs’ta kumar

Güzel oynanır, hem de en gizli artırmalarla

Lobilerin bu kesifi taşıyamayacağı kadar

Doğu Akdeniz’de lacivert suların prensesini

Görüp tanı,  sen de çok beğeneceksin

Kendine özgü mazisiyle, bakirliğiyle

Cömertliğiyle bu adaya tam gitme zamanı 

Kuzeyinin karamsar iklimlerine aldırma

Yangınları hep sesizce içten, birikimli fay gibi..

Güneyinin erken doğan güneşinden iyidir 

Oyuncakları çok, zengin çocukları şımarıklığında.

Şehvetin masumiyete karışıp dinlendiği gölge

Özgürlüğü çağrıştıran, sanal santral ağlarının

Ada şartlarına, sınırlarına hükmedemediği aşkı

Hürriyet caddelerinin şenliklerinde bulacaksın

Kumar makinelerinin kol, zar sesleri arasında 

Emekli ecnebi maskesi altında, para babalarının

En nefis yağlı tablolarla konakladığıdır bu bölge.

Herkesçe dudak arası beklenen o tek kelime

Yakıp kavururken susuz, suyla çevrili gönülleri

Kurşunlamakta yeni palazlanmış tüm yavru kuşları..

Güzellik tacının devasal ışıltısı mahmurluğunda

Yeşil gelinlikle  davul zurna sesleri arasında

Kına gecesinin uyukusuz ağırlığında beklemekte

Dümen kurmaylarının bitmeyen pazarlıklarında

En tuzlu mavi, en acı yeşil, en kara al burada

Dorukların kar beyazı, bahislerin en kar karı da burada

Ey dostum biz de kumarda  kazanacagız göreceksin

Donelerin hazırlıkları tamamlandı, bekletmeden gel...

En zevkli kumar, ada sularının turkuvaz köpüklerinde...

Çan sesleri, ezan yankıları sesteşirken oynanır

Kıbrıs''ta güzel kumar oynanır...', 'Haydi gel dostum, Kıbrıs için iki biletim var Kumarın hası orada oynanıyor duydun mu Haberin yoksa öğren işte, Kıbrıs’ta kumar Güzel oynanır...', ARRAY['Türk Edebiyatı','Şiir','Gülşen Şenderin']::text[], 8.5, '{"poet":"Gülşen Şenderin","poet_slug":"gulsen-senderin","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/kibris-ta-guzel-kumar-oynanir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasret', 'hasret-herdem-ankara-71g67', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hasret

Hasret sıradağlar gibi yüksek

Özlem yüreğimde kor bir ateş

Ben hasreti ve özlemi seviyorum

Hasret sevgiyi 

Özlem seni unutturmaz bana

Seni çok ama çok özledim

Hasret kaldım kokuna,gülüşüne,

Gözlerinde ki o sıcak sevecen bakışa

Ben hasreti ve özlemi seviyorum

Hasret sevgiyi

Özlem seni unutturmaz bana

20/11/2003

HERDEM

13:20', 'Hasret Hasret sıradağlar gibi yüksek Özlem yüreğimde kor bir ateş Ben hasreti ve özlemi seviyorum Hasret sevgiyi  Özlem seni unutturmaz bana...', ARRAY['Türk Edebiyatı','Şiir','Herdem Ankara']::text[], 8.5, '{"poet":"Herdem Ankara","poet_slug":"herdem-ankara","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/hasret-277-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'S o n r a, ç o k o l d u...', 's-o-n-r-a-c-o-k-o-l-d-u-zafer-zengin-etnika-ap0mt', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '.



kendi bağlamında

kızıl elma ısıran aç çocukla

dünyanın türlü hallerinin karşılaşması

,

kendimi çiziyorum avuçlarıma

ısla

ıssızlıkla

iki yanağım var kafamda

geride bıraktığım anlarda

yüzüm 

eylüle sarılmış hüzün 

yaz demeyin 

yaz içimden geçen gülün 

hüzün içimde açılan düğüm 

bağlı ellerime bakmadan 

gözlerimi çözün 

sever kendini 

siz şimdi gülün 

göğünüzü avucuma sürün 

gözlerim mavi bugün



hayat suyunun akıştığı  insan yüzünün

rüzgara durup yakasını kaldırdığı an

gözlerindeki ıslaklığa vurgusu

,

bilirim çılgın değil rüzgar 

serin tutar bir yerinde 

bir yerinde getirir ölüm 

hayat dilerim 

suya durmuş gül için 

ne ağaç ne çiçek düşleri 

bu yüzden güzel güler 

gülün kahve dallarında gözleri 

buradan başlayın 

hüznün izini sürün 

bir yanı yalnız 

bir yanı hınca hınc insan 

dokunmayın yağsın 

eylül göğünde kalsın 

kendi göğünü sulayan

küçük oz’anın

bir dudak üstünde gezen

kızıl parmakları ve dişinde kalan sızı

,

gömmeyin 

mavi tüner omzuna 

kurda kuşa aç yüreğin 



kendi başına

maviye giden adamın

suya karışan ayakları

yapraklara çıkardığı hüznün gölgesi

,



dallara tutunan yapraklar 

her sonbahar yeniden açar 

sızı değil bu ayrılıklar 

yeşil küpeşte 

yeşil tente 

mavi deniz dibinde 

elden düşer gibi 

toplanır geldiği yerde 

yan yana

sıkı sıkıya 

kader değil bu 

uymak hayata 

hayat düşen yaprakta 

yaprak düşüren damların

yağmur olmadan önce

özledikleri isme yakılan

son sigara

,

tomurcuk kopar bazı 

umutsa su düşer dibe 

rengi kendinde 

kızıl eder gülü 

nasıl bağlanma bu 

yaprağı kat 

anlat meydana 

isim bulalım 

renkli yaprakların dansına 

ateşin var mı! 



aranmaya yakın

utanan ve ağlayan adamın

kadın elinde

yüreğinden yakalanıp

sıkılıp havaya kaldırılan bedeninden

kendine düşen pay

,

ne yaptın anlamadım

ağladığımla kaldım

can fışkırdı dudağımdan

duymasam inanmazdım

iki sigara bırakıp gitmek

içi cebinde tüketmek

anlatılmaz şeyleri

söylemende bilmek

içimle didişme

yüzleşme 

eksilme kendine gülme

ne olduğunu anlamaya çalışan adamın

kendi iç yangıları

,

eskisi gibi kalmayacağım

ne kalan andı alanı

ne alan anda kalandı.

gitmek

yamandan yalandı



sonra güldü

- sizi falanca aktriste benzettim dedi

o gülümsedi

sonra çok oldu

incitmeden gitmek var mıydı

alnına yazdı

denize koşmakta çaresiz

limanlarda talandı

bir kayaya tutunup

gövdesini suya koydu

soyundu

ağsa ağ açıklar

değilim demekte ne var

- o değilim maalesef dedi ve gitti

sonraki günler

şiir yazmayın mavi üstüne

kan rengi görünmüyor

de bao

heval

ya cane

sessiz ölünmüyor

Eylülün ikinci yarısı ‘05 

.', '. kendi bağlamında kızıl elma ısıran aç çocukla dünyanın türlü hallerinin karşılaşması , kendimi çiziyorum avuçlarıma ısla ıssızlıkla iki ya...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":129,"source_url":"https://www.antoloji.com/s-o-n-r-a-c-o-k-o-l-d-u-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gurbette olmaktır benim hasretim', 'gurbette-olmaktir-benim-hasretim-halil-colak-mu5ax', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hasretliktir en kardeş büyük derdim

Sıla özlemidir benim bu hasretim

Vatan Erzurum’dan ayrıda kaldım

Gurbette olmaktır benim hasretim

Geceleri rüyama her zaman girersin

Bu gurbettir kardeş nere gidersin

Erzurum’a hasretim nasıl gülersin

Gurbette olmaktır benim hasretim

Arada dağlar var hep sıra, sıra

Yüreğimde  olmuş hep pare,pare

Arada sırada sılayı özlemle ara

Gurbette olmaktır benim hasretim

Halil Çolak 26.9.2005 Ankara', 'Hasretliktir en kardeş büyük derdim Sıla özlemidir benim bu hasretim Vatan Erzurum’dan ayrıda kaldım Gurbette olmaktır benim hasretim Gecele...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gurbette-olmaktir-benim-hasretim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saatler Durdu', 'saatler-durdu-herdem-ankara-no7qr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Saatler Durdu

Saatler durdu bugün 

Sensizliği söylemiyor dakikalar

Seni anlatmıyor hatıralar

Geçmiyor zaman sensiz bugün

Tik tak sesleri yok artık 

Dakikalar saate akrep yelkovana küsmüş sessizce

Saatler durdu bugün

Geçmiyor zaman sensiz bugün

HERDEM

10/11/2003

17,00', 'Saatler Durdu Saatler durdu bugün  Sensizliği söylemiyor dakikalar Seni anlatmıyor hatıralar Geçmiyor zaman sensiz bugün Tik tak sesleri yok...', ARRAY['Türk Edebiyatı','Şiir','Herdem Ankara']::text[], 8.5, '{"poet":"Herdem Ankara","poet_slug":"herdem-ankara","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/saatler-durdu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzaksın Benden', 'uzaksin-benden-mahya-sultan-tosun-mpfhs', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Birlikteliğimiz dört duvar arasında hep

Güneşin sıcak yüzüyle göremedim seni

Ayın parlaklığını elele seyredemedik seninle

Bir müziği hissedemedik birlikte yüreğimizde 

Ben düşündüğüm gibi yaşayamazken seni

Sen istediğin gibi yaşadın beni

Ben denizin engin ufkunda

Bir dağın zirvesinde

Gökkuşağının yeşilinde

Bir gülün kalbinde 

Bekleyeceğim seni', 'Birlikteliğimiz dört duvar arasında hep Güneşin sıcak yüzüyle göremedim seni Ayın parlaklığını elele seyredemedik seninle Bir müziği hissede...', ARRAY['Türk Edebiyatı','Şiir','Mahya Sultan Tosun']::text[], 8.5, '{"poet":"Mahya Sultan Tosun","poet_slug":"mahya-sultan-tosun","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/uzaksin-benden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstemiyorum', 'i-stemiyorum-herdem-ankara-jtpt5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İstemiyorum

Dertli gecelerimde 

Sabahlara kadar seni düşünüyorum

Beni istemediğini söylediğinde

Bir kez değil bin kez öldürmüştün beni

Tekrar dünyaya gelsem istemem seni

İstemem böyle acı kaderi

Benim kahkahalarım artık sahte

Bu hayatta son oyunumu oynuyorum

Son kez açılıyor perde 

Kalbim ağlıyor bu oyunda

Sonbaharı yaşıyorum 

Sararan yaprak gibi 

Savurmak istiyorum seni rüzgarlara

Tekrar dünyaya gelsem istemem seni

İstemem böyle acı kaderi

Yeni bir gün başlıyor

Sen değil artık ben istemiyorum

Seni yaşamak istemiyorum 

Seni düşünmek istemiyorum

Kendimle kavga etmek istemiyorum artık

Yeni bir sayfa açtım hayatıma

İstemiyorum yalan gülüşler

İstemiyorum seni istemiyorum anla

HERDEM

04/09/2003

09:30', 'İstemiyorum Dertli gecelerimde  Sabahlara kadar seni düşünüyorum Beni istemediğini söylediğinde Bir kez değil bin kez öldürmüştün beni Tekra...', ARRAY['Türk Edebiyatı','Şiir','Herdem Ankara']::text[], 8.5, '{"poet":"Herdem Ankara","poet_slug":"herdem-ankara","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/istemiyorum-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Çoktan Gitmiştim', 'ben-coktan-gitmistim-deniz-yavuz-c0co9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sebepsiz yalnızlıklarımın 

Adres boşluklarında ne geziyorsun 

Beni burada bulabileceğini mi sanıyorsun 

Göz gözü görmez, 

Toz duman içerisinde 

Yalnızlığımı mı arıyorsun 

Sensizliği bulanık deniz sularında aradım 

Yönümü bilmeden 

Soluksuz 

Derinlerde en derinde

İçerde, yaranın tam iyleşmezinde 

Yemsiz oltalara takıldım 

Çırpındım 

Başı boş sevdaların mavilerine koştum 

Tek küreği kırık yüreğimle 

Ve sen geldin 

Ama ben çoktan gitmiştim...', 'Sebepsiz yalnızlıklarımın  Adres boşluklarında ne geziyorsun  Beni burada bulabileceğini mi sanıyorsun  Göz gözü görmez,  Toz duman içerisin...', ARRAY['Türk Edebiyatı','Şiir','Deniz Yavuz']::text[], 8.5, '{"poet":"Deniz Yavuz","poet_slug":"deniz-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ben-coktan-gitmistim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özledim ayrıldığımdan beri', 'ozledim-ayrildigimdan-beri-halil-colak-c8nrm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gözlerinin engin bakışını

Yüreğimi candan yakışını

Tenin gül gibi kokuşunu

Özledim ayrıldığımdan beri

Sarı yaprak gibi sarardı yüzüm

Sen olmayınca açmıyor gülüm

Sensiz olmak en büyük hüzün

Özledim ayrıldığımdan beri

Halil Çolak 26.9.2005 Ankara', 'Gözlerinin engin bakışını Yüreğimi candan yakışını Tenin gül gibi kokuşunu Özledim ayrıldığımdan beri Sarı yaprak gibi sarardı yüzüm Sen olm...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ozledim-ayrildigimdan-beri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmek', 'sevmek-herdem-ankara-k6wpn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sevmek 

Bunca yaşanılanlar yalanmış 

Yalanmış meğer sevgi 

Boşunaymış verilen emek, şefkat

Sevgi üzerine yazılan tüm şiirler 

Başka sevgiler yalanmış

Sevmek sevilmek hata imiş meğer

Bunca yılın ardında bırakılan 

Kendin için yaşamışsın

İnsan kendi için var olmuş

Gururunun esiri olmuşsun

Sen böyle değildin 

Böyle katı olamazsın sen bağırmalısın

Haykırmalısın sevgini 

Sen sevecen bir kalptin

Ne oldu neden küstün 

Neden çürümeye terk ettin kendini

Koca bir çınardın hayatımda

Neden salıverdin kendini 

Hadi dön hayata sarıl iki elinle sevdiklerine

Hevesler gelip geçici oluyormuş

İşte biten sevgimiz de bir heves değil mi? 

Soruyorum şimdi sana cevap ver kalbim

Yüzüne vur hissettiklerini kan ağlama

Bu kadar katı değildin sen ağla, ağla susma 

Dışa vur bağır haykır hatalarını 

Göz yaşlarında gizleme sevgini 

Gurur yapma söyle hissettiklerini

İçin, için yok olma 

Hani sen koca çınardın sen 

Kıyamazdın bana güneşi ışıklarını süzerdin

Hani kanatlarının altında hep kalacaktım

Sen beni hep sevecektin büyütecektin  sevginle

Sıcak kollarında şefkatle kucaklayacaktın hani

Yalanmış sözlerin yalanmış sevgin

HERDEM

07/04/2004', 'Sevmek  Bunca yaşanılanlar yalanmış  Yalanmış meğer sevgi  Boşunaymış verilen emek, şefkat Sevgi üzerine yazılan tüm şiirler  Başka sevgiler...', ARRAY['Türk Edebiyatı','Şiir','Herdem Ankara']::text[], 8.5, '{"poet":"Herdem Ankara","poet_slug":"herdem-ankara","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/sevmek-117-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağaçlara Dair', 'agaclara-dair-babur-pinar-mac3n', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '(E.Gökçe,P.Neruda,N.Hikmet ve diğerleri İçin)        

Ağaçlar da ölür

Çılgınlaşan gökyüzünün altında

ormanın derinliklerinde 

dingin ve yalnız

Kalır kökleri kazanılmış hayatla gür

nehirlere giden toprağın içinde

ıssızlığın ortasında

büyük bir sürgünle buluşarak sayrısız

Ağaçlar da ölür

Üşüşür başına alıcı kuşlar

ateş böcekleri susar 

Bahar gelmeden gelir ölüm

Kavuşmaların en çok olduğu günde

iner şehirlerin aynasına zulüm

Görünmeyen gururun sabrını 

kısa bir ömrün telaşında 

hayatın ipek gömleğine işleyerek

ürperir haziranda

yüreğimdeki sevinçli kelebek

Ağaçlar da ölür

Aydınlık yüzüyle zaman

rüzgarın çığlığı içinde çözülür

Çünkü acılar içindedir orman

                                                        

(BİR UZUN YOLDA-Şiir kit.1996-Saypa y.)', '(E.Gökçe,P.Neruda,N.Hikmet ve diğerleri İçin)         Ağaçlar da ölür Çılgınlaşan gökyüzünün altında ormanın derinliklerinde  dingin ve yaln...', ARRAY['Türk Edebiyatı','Şiir','Babür Pınar']::text[], 8.5, '{"poet":"Babür Pınar","poet_slug":"babur-pinar","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/agaclara-dair-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalın ayak', 'yalin-ayak-gorkem-kaya-y73sb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Cemaaaaaaaaal

Ne çöktün göçmen kuşun başına? 

Seviyorsan 

Seviyorsun

Bırak oğlum kuşu

Gidecek ki

Dönebilsin geri

“seviyor

sevmiyor

seviyor

sevmiyor......”

Cemaaaaaaaaal

Yolunur mu lan hiç göçmen kuşun kanadı

Fötr şapkana süs olsun diye

Boyun devrilsin,

Yalın ayak göçesin Cemal.', 'Cemaaaaaaaaal Ne çöktün göçmen kuşun başına?  Seviyorsan  Seviyorsun Bırak oğlum kuşu Gidecek ki Dönebilsin geri “seviyor sevmiyor seviyor s...', ARRAY['Türk Edebiyatı','Şiir','Görkem Kaya']::text[], 8.5, '{"poet":"Görkem Kaya","poet_slug":"gorkem-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yalin-ayak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni isterim', 'seni-isterim-sinan-karakas-hq0kf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sensiz bir dünyada ölmek isterim 

Seni sevdiğimi bilmen isterim 

Kaplasa ateşler dört bir yanımı 

Söndürmeye suyu seni isterim 

Düşün ki bir kuru toprak olmuşum 

Düşün ki bir gülüm hemen solmuşum 

Susamış bir kuşum dala konmuşum 

Su olarak seni seni isterim 

Sen benim dünyamda bil ki hayatsın 

Hayatıma giren eşsiz bir tadsın 

Gönlümdeki arzum hem de muratsın 

Cenazem altına seni isterim 

Ölmüş diye duysan üzülmeyesin 

Mezarıma gelip bir gül dikesin 

Sanmam ki ahrette günlerim geçsin 

Ahirette bile seni isterim', 'Sensiz bir dünyada ölmek isterim  Seni sevdiğimi bilmen isterim  Kaplasa ateşler dört bir yanımı  Söndürmeye suyu seni isterim  Düşün ki bir...', ARRAY['Türk Edebiyatı','Şiir','Sinan Karakaş']::text[], 8.5, '{"poet":"Sinan Karakaş","poet_slug":"sinan-karakas","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/seni-isterim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk İçin', 'ask-i-cin-hakan-kocaoglu-dr126', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kul cemâli zerre, Cemâlullâh''ı idrak için

Yakar Mecnunu zerreside, Bil hep onun için

Güzeli, Güzellerde aramak suçmu? Ne için

Yanmaya alışa cismim, Taa Cemâlullah için.', 'Kul cemâli zerre, Cemâlullâh''ı idrak için Yakar Mecnunu zerreside, Bil hep onun için Güzeli, Güzellerde aramak suçmu? Ne için Yanmaya alışa ...', ARRAY['Türk Edebiyatı','Şiir','Hakan Kocaoğlu']::text[], 8.5, '{"poet":"Hakan Kocaoğlu","poet_slug":"hakan-kocaoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ask-icin-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutmak', 'unutmak-murat-sezer-8jhe3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Eski sevdaları unutmak zordur

Nefes almayı bile unuttum zaman zaman

Yemek yemek, su içmek

Sadece ihtiyacdan yapılan görev gibiydi

Sensiz  yaşamak, sadece yaşamaktı bedenen

Sevinmeden, gülmeden, eğlenmeden

Günü geçirmek 

Geceyi beklemek ve sana kavuşmak

Rüyalarda

Rüyalarda hep yanımdaydın

Ellerin elimde sıcaklığını hisseder

Mutlu olurdum

Sabah olsun istemez, uyanmaya direnirdi gözlerim

Sen gideceksin diye

Eski sevdaları unutmak zordur

Seni unutmaksa 

Yapamadım be gülüm unutamadım 

Sen unutsan bile

Arayıp sormasan bile

Unutulmayanımsın benim', 'Eski sevdaları unutmak zordur Nefes almayı bile unuttum zaman zaman Yemek yemek, su içmek Sadece ihtiyacdan yapılan görev gibiydi Sensiz  ya...', ARRAY['Türk Edebiyatı','Şiir','Murat Sezer']::text[], 8.5, '{"poet":"Murat Sezer","poet_slug":"murat-sezer","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/unutmak-36-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Belki', 'belki-ridvan-cetin-khiot', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir umuttu yanlızlık,

bir şeyleri paylaşmamaktı belki,

Belki gözler dalıp giderken,

Yaralı bir serçeye ağlayan bir buluttubelkide,

Belki belkilerle dolu bir hayattı bu...', 'Bir umuttu yanlızlık, bir şeyleri paylaşmamaktı belki, Belki gözler dalıp giderken, Yaralı bir serçeye ağlayan bir buluttubelkide, Belki bel...', ARRAY['Türk Edebiyatı','Şiir','Rıdvan Çetin']::text[], 8.5, '{"poet":"Rıdvan Çetin","poet_slug":"ridvan-cetin","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/belki-92-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bizi', 'bizi-osman-taspinar-l2rdc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Görme bizi bu kadar

Aciz ve naciz

Bilmesekte öğreniriz elbet

Medeniyet denen şeyi..

Neyimiz var hor görülecek

Fakir ama mutluyuz,

Tok gezmesekte 

Aç değiliz biz.

Parfüm,deodorant,boya değil

Çiçek kokuyor

Toprak kokuyor vücudumuz.

Tırnaklar çapa değil,

Gözler süpürge

Toprakta büyür

Nasırlı elli gelinlerimiz.', 'Görme bizi bu kadar Aciz ve naciz Bilmesekte öğreniriz elbet Medeniyet denen şeyi.. Neyimiz var hor görülecek Fakir ama mutluyuz, Tok gezmes...', ARRAY['Türk Edebiyatı','Şiir','Osman Taşpınar']::text[], 8.5, '{"poet":"Osman Taşpınar","poet_slug":"osman-taspinar","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/bizi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne de Güzel Sabahın Köründe', 'ne-de-guzel-sabahin-korunde-volkan-yoruc-sb2kr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sabah daha çok erken

Güneşten yoksun

Sokaklar hala ıssız

Seslerden mahsun

Yürüyorum yol kenarından

Çevrem müsait hüzünlenmeye

Herkes uykuda

Kimi mahmurla uğraşmakta

Daha ayaz var burada

Sığınmak lazım şimdi kabana

Sığınacak bişeyim kalmamışcasına

Adım atmak ne de güzel sabahın köründe

Hele düşünmek sessizce

Ne de hoş bu güz mevsiminde

Daha yapraklar ağaçlarda

Daha rüzgarlar meltemlerde

Dolaşmak ne de güzel sabahın köründe

Düşlemek bir başka aşktan yana sabahta

Kalpten başlayıp hayallere inmek

Hüzünden çıkıp sevdaya varmak yürekte

Sonra anılara tutunupta iç geçirmek

Hatırlamak ne de güzel sabahın köründe

Kahvaltıdan yoksun olmak

Çaya, aşka özlem misali hasret kalmak

Kavuşmak hayaliyle dolaşmak

Dolaşıp dolaşıp anları maziyle paylaşmak

Özlemek ne de güzel sabahın köründe', 'Sabah daha çok erken Güneşten yoksun Sokaklar hala ıssız Seslerden mahsun Yürüyorum yol kenarından Çevrem müsait hüzünlenmeye Herkes uykuda ...', ARRAY['Türk Edebiyatı','Şiir','Volkan Yoruç']::text[], 8.5, '{"poet":"Volkan Yoruç","poet_slug":"volkan-yoruc","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/ne-de-guzel-sabahin-korunde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son sözler', 'son-sozler-murat-sezer-5cazz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Uzun zaman olmuştu

Kalbimin hızlı çarpmadığı

Ve uzun zaman olmuştu

Kalbimin hiç çarpmadığı

Her ikisinide senle yaşadım

Gözlerine bakarken yazı

Sözlerinde kışı yaşadım

Uzun  gelmişti dönüş yolu

Sen yanımda uyurken 

Yoldaki 

Bütün tabelalarda senin ismin

Ama aklımda hep 

Son sözlerin', 'Uzun zaman olmuştu Kalbimin hızlı çarpmadığı Ve uzun zaman olmuştu Kalbimin hiç çarpmadığı Her ikisinide senle yaşadım Gözlerine bakarken ya...', ARRAY['Türk Edebiyatı','Şiir','Murat Sezer']::text[], 8.5, '{"poet":"Murat Sezer","poet_slug":"murat-sezer","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/son-sozler-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şu Bizim Yüksel Hanım', 'su-bizim-yuksel-hanim-mehmet-ali-gunes-0ya0h', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hep en iyisini isterdi

Hep en yükseğe çıkmayı

Kuş olmayı dağların tepesinde

İnsanlara yüksekten bakmayı 

Hatta biraz da abartarak

Dürbün olmayı Kız Kulesinde

Ulan ne çok severdik seni biz

Kanatları kibirden olan Baykuş! 

Yükselmek sağlam karakter ister

Aşağıya bakınca korkmayacaksın

Ve sonra kullanmayacaksın 

Sana destek olanları merdiven diye

Hesabını da iyi yapacaksın

Sen yükseğe çıktıkça

Donundaki yamaların

Görünme ihtimalinin!', 'Hep en iyisini isterdi Hep en yükseğe çıkmayı Kuş olmayı dağların tepesinde İnsanlara yüksekten bakmayı  Hatta biraz da abartarak Dürbün olm...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Güneş']::text[], 8.5, '{"poet":"Mehmet Ali Güneş","poet_slug":"mehmet-ali-gunes","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/su-bizim-yuksel-hanim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendimle Söyleşim-3 / Ne Yaparsın Bensiz?', 'kendimle-soylesim-3-ne-yaparsin-bensiz-serap-demirturk-5kkhd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Biliyor musun ey yar...sensizliğin durgun sularında gezdim de dün, bir buruk oldu yüreğim...Seni aradım yüreğimin en mahrem köşelerinde de  bulamadım gölgeni bile...Söyle yar, bunu nasıl başardın? Nakış nakış işlemişken seni ben yüreğime, nasıl ettin de  buz gibi sularla eş ettin sevgini ve söyle yar, şimdi bu boşluğu hak etti mi o güzel sevda? Söyle yar, gözyaşımla suladığım şiirlerimi ben kim için okuyayım şimdi? Söyle yar, ahrette deyip de  sözleştiğimizi ben nasıl unutayım şimdi ve ben, seni bu ıssız yüreğin bir köşesinde oturup anarken sen ne yaparsın bensiz?', 'Biliyor musun ey yar...sensizliğin durgun sularında gezdim de dün, bir buruk oldu yüreğim...Seni aradım yüreğimin en mahrem köşelerinde de  ...', ARRAY['Türk Edebiyatı','Şiir','Serap Demirtürk']::text[], 8.5, '{"poet":"Serap Demirtürk","poet_slug":"serap-demirturk","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/kendimle-soylesim-3-ne-yaparsin-bensiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şaştın zulmünle mezalim', 'sastin-zulmunle-mezalim-i-lhami-arslantas-64h9o', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Neden bu mazlum canıma

Düştün hışmınla mezalim

Sen mi can verdin kanıma

Şaştın zulmünle mezalim

Lokma düğümlendi döşe

Zevkinle oldun dört köşe

Kâbus oldun pembe düşe

Taştın zulmünle mezalim

Nevrin ifrit menfur yüzün

Emaren şer, namert izin

Hep fütursuz lânet sözün

Aştın zulmünle mezalim

Der ilhami  emlik kuzum 

Acı meler heyler  tuzum

Zül melanet ki huysuzum

Deştin zulmünle mezalim', 'Neden bu mazlum canıma Düştün hışmınla mezalim Sen mi can verdin kanıma Şaştın zulmünle mezalim Lokma düğümlendi döşe Zevkinle oldun dört kö...', ARRAY['Türk Edebiyatı','Şiir','İlhami Arslantaş']::text[], 8.5, '{"poet":"İlhami Arslantaş","poet_slug":"i-lhami-arslantas","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sastin-zulmunle-mezalim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öğretmen', 'ogretmen-sinan-karakas-8cucl', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ö  ğretmendir öğreten insanlığı

G  eleceğe ümitle bağlılığı

R  azı olunurmu hiç cehalete

E  rişemeyince aydınlık millete

T  arih boyunca meçhul olan

M  illetinin geleceğini hazırlayan

E  serleriyle anıtlaşan 

N  asıl unutulursun  ey büyük insan', 'Ö  ğretmendir öğreten insanlığı G  eleceğe ümitle bağlılığı R  azı olunurmu hiç cehalete E  rişemeyince aydınlık millete T  arih boyunca meç...', ARRAY['Türk Edebiyatı','Şiir','Sinan Karakaş']::text[], 8.5, '{"poet":"Sinan Karakaş","poet_slug":"sinan-karakas","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ogretmen-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aratırsın', 'aratirsin-sinan-karakas-5p7re', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Verdin bana derdini, dermanı aratırsın,

Dert içinde dermanı, ne güzel yaratırsın,

Bu yürek ayrılığa, asla hiç dayanmadı,

Kerem bile aslıya, benim gibi yanmadı,

Sevgiden uzak kaldım, sevgi nedir bilmedim,

Nedense hep ağladım, hiç bir zaman gülmedim,

Sana ulaşmak için, aşındırdım dağları,

Hazana uğramasın, sevgimizin bağları,

Yanına almasan da, sevdiğini bileyim,

Sevginin sevinciyle, yollarında öleyim.', 'Verdin bana derdini, dermanı aratırsın, Dert içinde dermanı, ne güzel yaratırsın, Bu yürek ayrılığa, asla hiç dayanmadı, Kerem bile aslıya, ...', ARRAY['Türk Edebiyatı','Şiir','Sinan Karakaş']::text[], 8.5, '{"poet":"Sinan Karakaş","poet_slug":"sinan-karakas","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/aratirsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsyan Neye Yarar', 'i-syan-neye-yarar-ozan-rari-093ca', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Terk edilmişliğin verdiği yetimlik

O yalnız günlerin hesabı kime sorulur

Ya o insanın çektikleri! 

Umrunda olmasın hiçbir şey ziyanı yok

Yeni bir hayatın kölesi ol farketmez

Başkasını sev ve kandır artık ilgilendirmez

Bu alınyazısı ise çekeriz merak etme

Neler çekmedik, çekmeyeceğiz şu cihanda

Ben alıştım bütün bu çilelere ve eziyetlere

Senin yaptıkların nefes ve yemek gibi doğal gelir bana

Sen düşün artık başına gelecekleri

Yapacağın yanlışlara, kayıplarına ve gözyaşlarına

Hiç üzülmem,

Hiç ağlamam

Hiç umrumda olmaz çektiklerin

Sen layıksın her türlü kötülüğe

Kendi eden kendi bulur kural budur unutma bunu', 'Terk edilmişliğin verdiği yetimlik O yalnız günlerin hesabı kime sorulur Ya o insanın çektikleri!  Umrunda olmasın hiçbir şey ziyanı yok Yen...', ARRAY['Türk Edebiyatı','Şiir','Ozan Rari']::text[], 8.5, '{"poet":"Ozan Rari","poet_slug":"ozan-rari","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/isyan-neye-yarar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Sevdiğim Kadar', 'seni-sevdigim-kadar-umit-koral-v3n40', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seni sevdiğim kadar

Yalnız başına kalmış köpeği sevseydim eğer 

Yanı başımdan hiç ayrılmazdı 

Seni sevdiğim kadar 

Çaresiz kalmış bir kayayı sevseydim eğer

Sevgime dayanamayıp parçalanıp kum olurdu

Seni sevdiğim kadar

Masum bir kuşu sevseydim eğer

Dile gelip benimle konuşurdu

Ben seni sevdim seni istedim

Nerden bilebilirdim ki

Kalbinin nefret le dolduğunu....', 'Seni sevdiğim kadar Yalnız başına kalmış köpeği sevseydim eğer  Yanı başımdan hiç ayrılmazdı  Seni sevdiğim kadar  Çaresiz kalmış bir kayayı...', ARRAY['Türk Edebiyatı','Şiir','Ümit Koral']::text[], 8.5, '{"poet":"Ümit Koral","poet_slug":"umit-koral","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/seni-sevdigim-kadar-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen, Ben Mevzuları - 2', 'sen-ben-mevzulari-2-selim-bayrak-7lcvr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen beni başka kimliklerde ararken

Ben beni başka kimliklere aratır sorarken

Yalnızlığın bizi çepeçevre sardığını

Çok mu geç sezdik

Elveda demek

Merhaba demekten kolay oldu da

Biz bunu niye fark edemedik

Sen beni başka ovalarda üretir 

Ben seni başka aşklarla haşır neşir sanırken

Birbirimizin bereketi olduğumuzu n’erden bilirdik

Elveda demek

Bizi şimdi daha aşık yaptı da

Bir araya niye gelemedik

1995 - Bolu', 'Sen beni başka kimliklerde ararken Ben beni başka kimliklere aratır sorarken Yalnızlığın bizi çepeçevre sardığını Çok mu geç sezdik Elveda d...', ARRAY['Türk Edebiyatı','Şiir','Selim Bayrak']::text[], 8.5, '{"poet":"Selim Bayrak","poet_slug":"selim-bayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sen-ben-mevzulari-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Irak bir ülke', 'irak-bir-ulke-sair-azeytinli-vpdt0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bembetaz hayalleri küçcük siyah gözleriden taşıyordu.

O kadar büyüktü ki hayalleri sanki dağları aşıyordu.

Ara sıra takılıp düşse de yılmadan koşuyordu.

Düşüp kalktıkça sanki daha fazla coşuyordu.

Kocaman hayalli bu ufaklık neden kimseyle konuşmuyordu? 

Acaba en büyük engelinin yıkılmasını mı bekliyordu.

Sanırım bir şey söylemek için o günü bekliyordu.

Nihayet o büyük gün geldi yumurcak

En büyük engelini yıktı sesten hızlı o uçak

Diktatör dediğin fare kaçıyor köşe bucak

Ama hayallerini de yıktı o uçan oyuncak

Konuşabilirsin artık özcür hissediyorsan kendini

ancak bilmeni isterim ki özgürlüğünün ömrü de hayallerininki kadar olacak.', 'Bembetaz hayalleri küçcük siyah gözleriden taşıyordu. O kadar büyüktü ki hayalleri sanki dağları aşıyordu. Ara sıra takılıp düşse de yılmada...', ARRAY['Türk Edebiyatı','Şiir','Şair Azeytinli']::text[], 8.5, '{"poet":"Şair Azeytinli","poet_slug":"sair-azeytinli","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/irak-bir-ulke-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdân İle Eğler misin?', 'sevd-n-i-le-egler-misin-mehmet-bicik-e8ylc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Haykırsam beni duyar mısın? 

Gelsem yanına sevip sayar mısın? 

Ben gideli gurbet ellere,

Değiştin mi, yoksa aynı yâr mısın? 

Nasıl sevdim seni bilir misin? 

Hadi gel desem koşup gelir misin? 

Benim yerime senin canını,

İsteseler, seve seve verir misin? 

Benim gibi gurbette ağlar mısın? 

Başına duman inmiş dağlar mısın? 

Deli gönlüm dertlere tutulsa,

Sevdân ile eğler misin? ..

25 Mart 1997, Şebinkarahisar', 'Haykırsam beni duyar mısın?  Gelsem yanına sevip sayar mısın?  Ben gideli gurbet ellere, Değiştin mi, yoksa aynı yâr mısın?  Nasıl sevdim se...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Bicik']::text[], 8.5, '{"poet":"Mehmet Bicik","poet_slug":"mehmet-bicik","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sevdan-ile-egler-misin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana kalan...', 'bana-kalan-mustafa-murat-aydogdu-l8tak', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Giderken kapatma gönül kapını

Senden bir hatıra,bir ümit kalsın

Bunu al,şunu al,hatta canımı

Ama sakın dokunma! aşk bende kalsın.

Hüzünler bırakıp gitsende bana

Sakın! dayanamam,ne olur ağlama

Resimler,mektuplar ne varsa al da

Gözlerim hatırına,yaş bende kalsın.

Sanmaki unutur yüreğim seni

Silsemde maziyi kalır izleri

Giderken,yanında götür de yalancı seni

Bırakta hayalin,düş bende kalsın

Benim tanıdığım sen bende kalsın.

Boşuna uğraşıp suçlu arama

Sende biliyorsun,tüm çaban boşa

Haklı çıkmak için kendini yorma

Bütün kabahatler,suç bende kalsın.

Yüreğim tükendi,bitmek üzere

Savaşan son kalem düşmek üzere! 

Giderken ne olur arkanı dönme

Hep güler sandığın,mutlu ben sende

Hiç tanımadığın,ben bende kalsın!', 'Giderken kapatma gönül kapını Senden bir hatıra,bir ümit kalsın Bunu al,şunu al,hatta canımı Ama sakın dokunma! aşk bende kalsın. Hüzünler b...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Murat Aydoğdu']::text[], 8.5, '{"poet":"Mustafa Murat Aydoğdu","poet_slug":"mustafa-murat-aydogdu","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/bana-kalan-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güvercin Gerdanlığı', 'guvercin-gerdanligi-ozgur-celik-fse34', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'sen gülünce, 

güvercinler de gülerdi 

gamzelenirdi yanakların 

ölünce hep oraya gömülmek isterdim.

asılınca yüzün

mevsim hüzne dönerdi

sararırdı içimde alabildiğine fesleğenler

kurumuş dallara dönerdim...', 'sen gülünce,  güvercinler de gülerdi  gamzelenirdi yanakların  ölünce hep oraya gömülmek isterdim. asılınca yüzün mevsim hüzne dönerdi sarar...', ARRAY['Türk Edebiyatı','Şiir','Özgür Çelik']::text[], 8.5, '{"poet":"Özgür Çelik","poet_slug":"ozgur-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/guvercin-gerdanligi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Zehirli kansın**', 'zehirli-kansin-umit-koral-jtwt0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Artık ulaşmam mümkün değil sana 

Sen bir serap bir vahasın artık 

Kimbilir kimler içecek senin kanını

Kimler zehirlenip ölecek...

Zehirli bir kansın artık

Zehirli bir sarmaşık gibisin

Büyüdükce öldürüyorsun 

Aşık Veyselin söylediği gibi 

Bu iki kapılı handan kimler gelip 

kimler geçecek ki kimbilir......', 'Artık ulaşmam mümkün değil sana  Sen bir serap bir vahasın artık  Kimbilir kimler içecek senin kanını Kimler zehirlenip ölecek... Zehirli bi...', ARRAY['Türk Edebiyatı','Şiir','Ümit Koral']::text[], 8.5, '{"poet":"Ümit Koral","poet_slug":"umit-koral","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/zehirli-kansin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mavi üstüne', 'mavi-ustune-ercan-akbay-f20o7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bodrum mavisini görmedim

           bilemem,Akdeniz mavisinden güzel mi

           bir de Karadeniz in mavisi var

           dalgalarında hamsilerin oynaştığı

           sonra Marmara nın mavisi

           İstanbul da her tonuna ulaştığı

           ama bir mavi var ki

           nereye gidersen git

           nerede yaşarsan yaşa

           insanın olduğu her yerde

           insanla iç içe

           bence en güzeli,kardeşçe paylaşılan

           gök mavisi...', 'Bodrum mavisini görmedim            bilemem,Akdeniz mavisinden güzel mi            bir de Karadeniz in mavisi var            dalgalarında ha...', ARRAY['Türk Edebiyatı','Şiir','Ercan Akbay']::text[], 8.5, '{"poet":"Ercan Akbay","poet_slug":"ercan-akbay","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/mavi-ustune-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İşte Gidiyorsun', 'i-ste-gidiyorsun-ahmet-selcuk-i-lkan-e66sg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İşte gidiyorsun

Merdivenlerde bir ölüm sessizliği

Kül rengi yağmurlar sokaklarda

Üzerinde en çok sevdiğim ceketin

En acısı

Unut gitsin der gibi ıpıslak kirpiklerin

Ve ilk defa 

Bu kadar aceleci 

Ellerin ayakların gözlerin

Söylenecek ne varsa bitti -doğrudur-

Artık bu saatler 

Kanadı kesik bir sevdanın

Kalemi kırık bir aşkın

Ve sayfaları yanık bir romanın sonudur….

İşte gidiyorsun

Ellerinle açtığın bütün kapıları kapayarak

Hayat verdiğin odalardan gölgeni de alarak

Ve sürgüne verip bütün düşlerimi 

Dağ gibi bir adamı yakarak

Anlıyorum bu suskunluk

Bir aşkın açılmamış son mektubudur

Geride bıraktığın

Saksıda bir gelin çiçeği

Masada küskün bir anahtar

Yüreğimde parmak izlerin

Ve cevapsız yüzlerce sorudur

İşte gidiyorsun

Dikerek gözlerime o mağrur bakışlarını

Yıllardır düşlediğin zaferi kutlayarak

Ve masum bir veda gibi sokulup 

Ellerinle yüreğimi parçalayarak

Tarihte bugün

Aylardan Eylül

Günlerden hüzün

Saatlerden ondur

Sen kazanmayı 

Ben kaybetmeyi seçtim

Anlıyorum 

Bu ikimiz için artık sondur

İşte gidiyorsun

Ve biliyorsun

Birazdan sol yanıma düşeceğim

Yaramın olduğu yana

Vurduğun yere yani

Ne de olsa ayrılık acıdır zordur

İşte karşında

Ağır yaralı bir adam

Bir avuç gözyaşı

Ve ihanet makamında bir şarkı

Suç mahallinde

Senden kalan son delil budur

Git hadi git vazgeçilmezim

Şunu bil ki

Dünyada bütün mezarlıklar

Senin gibi vazgeçilmezlerle doludur…

                         

(''Erkekler Hep Yalnız Ağlar'' kitabından)

www.erkeklerhepyalnizaglar.com

ww.ahmetselcukilkan.com.tr', 'İşte gidiyorsun Merdivenlerde bir ölüm sessizliği Kül rengi yağmurlar sokaklarda Üzerinde en çok sevdiğim ceketin En acısı Unut gitsin der g...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Selçuk İlkan']::text[], 8.5, '{"poet":"Ahmet Selçuk İlkan","poet_slug":"ahmet-selcuk-i-lkan","theme":"Türk Şiiri","is_hero":false,"total_lines":58,"source_url":"https://www.antoloji.com/iste-gidiyorsun-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kin Dolu Bakışların', 'kin-dolu-bakislarin-umit-koral-w4wxa', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen umutlarımızı son seferine çoktan çıkartmışsın 

Sen ne maviden nede mordan anlarsın

Anladığın tek şey mantıksızlık,olumsuzluk

Kin dolu bakışların o kadar belli ki

Hiç birşey göremez olmuşsun

Şimdi bir tek şey kaldı geriye

Kimsenin dolduramayacağı 

sadece senin doldurabileceğin

Yalnızlık senfonisi....', 'Sen umutlarımızı son seferine çoktan çıkartmışsın  Sen ne maviden nede mordan anlarsın Anladığın tek şey mantıksızlık,olumsuzluk Kin dolu ba...', ARRAY['Türk Edebiyatı','Şiir','Ümit Koral']::text[], 8.5, '{"poet":"Ümit Koral","poet_slug":"umit-koral","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/kin-dolu-bakislarin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutulmuş Hısımlık', 'unutulmus-hisimlik-alper-kuruk-kgsol', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İlk insanla başlayan hısımlığımız

Ki onu yok etti zaman,

Unutmak bastırdı üstünü

Ve doğdu şimdiki aşklarımız.

Düşün,sevişiyoruz habersiz

Sen ve ben,

Oysaki Adem''di ilk babamız

Havva''ydı ilk anamız,

Kalbimizdir bize ihanet eden,

Aşk üstüne aşk tüm günahlarımız 

Ve o denlû saf.

Etimiz,güzelliğimiz her şeyimiz bir yana

Kuru iskeletlerde gerçek eşitliğimiz.

Biz bir kökün dalları

Geçmiş zaman ve unutmak

Ayrılığımıza sebep,

Unutulmuş bir hısımlık içinde 

Aşklarla biz bizi severiz hep...', 'İlk insanla başlayan hısımlığımız Ki onu yok etti zaman, Unutmak bastırdı üstünü Ve doğdu şimdiki aşklarımız. Düşün,sevişiyoruz habersiz Sen...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/unutulmus-hisimlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şarkılar', 'sarkilar-alper-kuruk-16iw2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Şarkılar bitti dedim,aşk bitmedi dediler

Nice aşklara türlü şarkılar söylediler.

Aşkının bittiğine sakın ola üzülme! 

Hayatın cilvesi bu:hem ağlama,hem gülme.

Bitmeyen aşk var mı ki,öylesine ne denir? 

Şarkılar sona ermiş aşklar için söylenir.

Şarkılar arasına senden şarkı girecek

Yeni şarkıya kadar bir süre söylenecek.

Şarkı ağlamak için,şarkı gülmek içindir,

Şarkının memleketi ne Avrupa ne Çin''dir...

Aşk,dünyada oldukça şarkılar hep olacak

Ömürler türkülerle,şarkılarla dolacak...', 'Şarkılar bitti dedim,aşk bitmedi dediler Nice aşklara türlü şarkılar söylediler. Aşkının bittiğine sakın ola üzülme!  Hayatın cilvesi bu:hem...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sarkilar-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitme kal', 'gitme-kal-erol-buker-ww5zq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gitme   kal 

ben sensiz yapamam

yaparım diyorsam 

kahrolası gururum

yalan söyletiyordur bana

ne olur inanma.

Gitme kal

ben bu sevdayı 

tek başıma taşıyamam

ben sensiz 

nefessiz

yaşayamam.', 'Gitme   kal  ben sensiz yapamam yaparım diyorsam  kahrolası gururum yalan söyletiyordur bana ne olur inanma. Gitme kal ben bu sevdayı  tek b...', ARRAY['Türk Edebiyatı','Şiir','Erol Büker']::text[], 8.5, '{"poet":"Erol Büker","poet_slug":"erol-buker","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gitme-kal-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adı Yok Bunun - I', 'adi-yok-bunun-i-ugur-deniz-ulkegul-jynfs', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bundan böyle

Gök/yüzüne bakmam gayrı..

Ne bir yıldız seçerim

Ne beyaz çalarım buluttan...

Başım önde usuldan geçerim

Düşlerimde yer bulan sokağından...

.....

(Sildim masum yüzünü

Bütün günahlarımdan....)

.....

Artık konuşmam gayrı

Doldurup cebime özlemleri

Sigaramda çektiğim nefes olursun..

Arada bir aklıma düşer gözlerin

Keskin bıçak gibi değer de sözlerin

O vakit gelir, yüreğime dokunursun...

Bıraktığım izler kaybolur

Hüznün yağmurda boğulur,

Beni göz yaşında bulursun......

......

Adı yok bunun

Zamansız bir sorgunun

Cevapsız, halsiz, yorgun

Mahkumuyum ben...

Usulca, kayıp düş/tüm gözlerinde(n)

Bulma beni...

Bulduğun gün..

Bende yorulursun................', 'Bundan böyle Gök/yüzüne bakmam gayrı.. Ne bir yıldız seçerim Ne beyaz çalarım buluttan... Başım önde usuldan geçerim Düşlerimde yer bulan so...', ARRAY['Türk Edebiyatı','Şiir','Uğur Deniz Ülkegül']::text[], 8.5, '{"poet":"Uğur Deniz Ülkegül","poet_slug":"ugur-deniz-ulkegul","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/adi-yok-bunun-i-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gün Biterken:', 'gun-biterken-salim-erben-1sw9c', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bırak acıyı gözlerime, 

Sen güneşte kal yeter 

Umuda beş varmış,

Sen boş versene.. 

Yak limanını bu kentin 

Çek kürekleri yalnızlığa... 

Çığlık oldum her nefeste 

Duyulmadı sesim

Oysa gecelere haykırdım

Gelmeyeceğini bile bile

Hatırladığımda gelmeyişlerini 

Sustum acınacak halime... 

Yokluğuna çiçekler bile

Alkış tuttular 

Onlarda gülüşlerime 

Düşman çıktılar....', 'Bırak acıyı gözlerime,  Sen güneşte kal yeter  Umuda beş varmış, Sen boş versene..  Yak limanını bu kentin  Çek kürekleri yalnızlığa...  Çığ...', ARRAY['Türk Edebiyatı','Şiir','Salim Erben']::text[], 8.5, '{"poet":"Salim Erben","poet_slug":"salim-erben","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gun-biterken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bey in Ölümü ve Türlü Türlü Tansık', 'bey-in-olumu-ve-turlu-turlu-tansik-ahmet-ferit-cosan-nf0lh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'kayboldukça 

karaladığım kelimemsin çığlık...

kudreti ile ak kağıda

buram buram yankı yayan...

sol kulağımdaki biçare gamze,

aynadaki yansımda nicedir

bakmayı yek yeğlediğim...

bin dikenli 

bin köklü 

bozkır çalısı,

kopartıp attı 

saklandığı ciğerinden

kanlı gözlerle 

nasırlı ellerinle sökmen ertesi

yürek denen o et parçasını.

kırıldı hokka, 

yayıldı kağıda mavi çığlığın...

toplu yanaklar şöyle bir titredi,

garip! 

dudak komşusu gamzene son nazarın...

sularda zerafetle salınan ise

hayali bir yansısın, gümüşi devliği ile ol hazarın...', 'kayboldukça  karaladığım kelimemsin çığlık... kudreti ile ak kağıda buram buram yankı yayan... sol kulağımdaki biçare gamze, aynadaki yansım...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ferit Coşan']::text[], 8.5, '{"poet":"Ahmet Ferit Coşan","poet_slug":"ahmet-ferit-cosan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/bey-in-olumu-ve-turlu-turlu-tansik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Avuçlarım da bir ter nefesi....', 'avuclarim-da-bir-ter-nefesi-atil-kesmen-w8o81', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yaşam karelerim hareketlenmiş olmalıydı

Anlamsız bir iz bırakıyordu

Çektiğim her nefeste

Düşüncelerim 

Kırılgan cam görüntüsü

Duygularım ise

Esir düşmüş olmalıydı, düşlerime

Gündüzlerim gecelere küsmüş

Yalnızlığımı soluyordum

Boş boş bakan gözlerimle

Avuçlarım da bir ter nefesi

Sevgi diye dökülürken ellerimden

Belki de

Gerçeklerimi yakıyordum

Mevsimlerin yıllanmış ışığın da

Çektiğim nefesin tortusu

Yaşam terim olmuş

Zaman çarkı dilimleri

Beni benden çalıyordu

Bir yokuşun 

Zirvesinden damlar gibiydim

Duygularımla şekillenmiş bedenimle

Sevgi dolu gözlerime

Yaşam gölgesinin, sinsi esintisi

Gizlense de

Bir yerlerimi çizip

Beni ben de eksiltse de 

Bir gün gelecek

Tüm yıldızlar güneş olacak

Belki de

Ay tutulacak

Karanlıklar kaybolacak

Görülmez yaşamım, gerçek olacak

Ve damlayacak

Sessizce

Seven gönlüme

Sevginin tüm renkleri olarak.', 'Yaşam karelerim hareketlenmiş olmalıydı Anlamsız bir iz bırakıyordu Çektiğim her nefeste Düşüncelerim  Kırılgan cam görüntüsü Duygularım ise...', ARRAY['Türk Edebiyatı','Şiir','Atıl Kesmen']::text[], 8.5, '{"poet":"Atıl Kesmen","poet_slug":"atil-kesmen","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/avuclarim-da-bir-ter-nefesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ve Aşk Büyüdü', 've-ask-buyudu-mehmet-tas-doh1a', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ve aşk

Büyüdü 

Şarap rengi dünyasında ötelerin.

Yelken açtı gönüller sonsuzluğa

Bir sen vardın, bir de sen.

Sürgün edilen ruhum

Bensizliğin çaresizliğinde 

Şaraba meze oldu.

Akşamlar yorgun düştü 

Berrak sularına denizlerin

Bir balıkçı ağına takılan ruhum

Bilinmezliğinde kayboldu ötelerin.

Zaman, eriyip bitti çoktan

Mekân, silindi kul yapısı haritalardan.

Ben, bir kürek mahkûmundan da suçlu

Bıraktım kendimi kollarına sonsuzluğun.

Aşk

Büyüdü

Sonsuzluğunda denizlerin.

Şarap ve aşk

Aşk ve zaman

Zaman..Ne büyük bilinmezlik.', 'Ve aşk Büyüdü  Şarap rengi dünyasında ötelerin. Yelken açtı gönüller sonsuzluğa Bir sen vardın, bir de sen. Sürgün edilen ruhum Bensizliğin ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Taş']::text[], 8.5, '{"poet":"Mehmet Taş","poet_slug":"mehmet-tas","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/ve-ask-buyudu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İhanet -1-', 'i-hanet-1-alper-kuruk-ybqhe', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Aşkımın katilisin sana ne ceza gerek? 

Koynumda beslediğim bir yılansın:engerek.

Aşkımı sana sundum,hem de ettim emanet

Hani,olmaz derlerdi emanete hiyanet? 

Sen bana nefretini aşk kınında sakladın

O bıçakla sen beni sırtımdan bıçakladın.

Aşkıma inancım var,artık kalmadı sana

Aşkım değil,sen oldun ihanet eden bana.

Aşkta temizlik vardır ve ölümsüzlük vardır

Beşerin insanlığı  ancak aşkı kadardır...', 'Aşkımın katilisin sana ne ceza gerek?  Koynumda beslediğim bir yılansın:engerek. Aşkımı sana sundum,hem de ettim emanet Hani,olmaz derlerdi ...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ihanet-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül Yaprağına Oruç', 'gul-yapragina-oruc-emre-ayvaz-5uclt', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '05.04.2005

aynalardan sessizce dehlizleri mi sildin

silindin çizilirken gül yaprağına oruç

mevsimsiz,yalan yere,son kerre mi kesildin

ilk sefere denizler nihayete sevdalı

 muhabbetten kanlanan aynalara dizildi...

ışıksız selvilere yansıyan gözyaşlarım

yarım kalmayasın ey, ye''se düşer ruzigar

yollar var sararınca kucaklar yolcusunu 

ve göğsünde büyüyen,yeşile koşan diyar

kelimeler asıldı hırçın bakışlarında 

kalmanın acısı bu,ızdırabı görmenin

eriyip gölgelerin hissizce aynasında...

ey garibim yaslanıp geceden geçmeyesin

gri karmaşıklığına dalıp düşüncelerin

hecenin sığlığından,şikayetinden uzak 

bir güvercin huzurunda hüzünlere bakarak 

kaynayan tefekkürün,derinleşen ümidin 

yeşeren nifaklar...', '05.04.2005 aynalardan sessizce dehlizleri mi sildin silindin çizilirken gül yaprağına oruç mevsimsiz,yalan yere,son kerre mi kesildin ilk se...', ARRAY['Türk Edebiyatı','Şiir','Emre Ayvaz']::text[], 8.5, '{"poet":"Emre Ayvaz","poet_slug":"emre-ayvaz","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/gul-yapragina-oruc-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuluçkada Kaldı Hayallerimiz', 'kuluckada-kaldi-hayallerimiz-selahattin-yetgin-k6wu0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Muammalarla örülü bir sevgi sarayıydı ördüğümüz, yıkıldık

Deli hasretler hırpaladı sevdamızı, kaynağı başından kuruttuk

Yüreğimizdeki asi basınçlarla kanıyor ellerimiz ve yüreğimiz

Biz bu aşkın rotasını hiç bilinmeyen, gidilmeyen adalara kırdık

Duvarlarıma sevdanın ağıtını sıvıyorum yakamozlar denizlerimden çekildiği zaman. Yitirilen, bir öfkeyle hurdaya atılan aşkımın kristal kavanozlarını kırdım, ufkumun en uç noktalarına yolculuğa çıktım ben. Gömütlüklerime bomboş odalarımdan götürecek resimlerin kalmadı ki, götüreyim. Çalılıklarının, yabani şiir ağaçlarının ışıklı neonlarında bir başına salınarak yürümeyi de öğreneceksin gözlerinin nehirleri ülkeme ulaştığında.

Yeryüzünün bütün kaya diplerine en nadide menekşeleri, en kırılgan yaseminleri senin için ekmiştim, bahardan önce açmalarını da beklemiyorum. Karlı dağ sularının suladığı bu gönül topraklarımda ateşten gömlekleri giyerek dolaşırım ben, her sevda kapımı çaldığında. Dilersen, öfkeni tetikleyen bütün sözcüklerimden yeni yapılar kurar, vücudunun güneş yanıklarını onarabilirsin. Üşüdüğümde üzerime giydirdiğin, terleyince de bir köşelere attığın kirli fanilamla yaşlarını siler, avuntu tepelerinde zafer çığlıkları da atabilirsin.

Fırtınaların pembe figürler çizerek karınca imparatorluklarını yıktığı, tüm savaş meydanlarından kılıç ve mızrakları çıkararak yeni bir medeniyete taşıdığı bir dünyadayız ne yazık. Dizlerimin yara berelerine acıyacaksan, düşlerimdeki sevgileri tarayacaksan, nefesin olmadan yaşayamayacağımı sanacaksan, şiirlerime sokul. Yaşamımızın kilit kırışlarında, kıskançlık bahçeleri her devirde vardır yunus gözlü. Ve o yunusların gemicileri sonsuzluğa taşıdığı bu hayat dümeninden çek ellerini artık. Gökyüzüne ellerini siper edip baktıkça, kara bulutlarla başka iklimlere kırılır rotan.

Hayalsiz tüm benlik savaşlarında ne yetgin olabildim sana, ne de etkin. Kuluçkadaki hayallerimin seni bir kobaya dönüştürmesini de hiç dilemedim. İmha edilmiş sözcüklerimi toplayarak evrenden, kırk bir yerinden yaralı bereli gönlümü saraylarına atmıştım sadece. Kefenlere sarılı bir sevdanın duasını yapamadan sana merhaba demiş, gecelerin büyülü pınarlarında yıkamıştım aynı sevdadan kirlenmiş ellerimi.

Kimi, ‘canı cehenneme’ dediğin olur şiirlerin ya hani, söyledikçe bir hançer kıyar yüreğini binbir yerinden. Kafiyesiz ve uyaksız sözcüklerimizin serbest kan dolaşımlarında endamına kapılmışlığım da biter, bu kırılgan sevdalar şairi seni de, seni de yüreğinden siler. Bomboş kalan kafesimde bir dağ kekliği ve bir yaramaz kedi besliyorum şimdi. Mutlulukla bitmeyen bir masal dünyasında Alaattin’in sihirli lambasına ellerimi sürüyor, nicedir karabasana dönüşen uykularımda unutmaya başladığım hayalini seviyorum.

Yeryüzünün bütün anlamsız tınılarında, serüvensiz aşk hikayelerinde ifrit fikirlere de gülüyorum ben. Her sarsıntıdan sonra yaşanan, yaşanması muhtemel olan depreminin fay hatlarından da kurtulurum gülüm. Özlemlerimizin tetiklendiği, acılarımızın depreştiği anlarda ağlamalarımızı da unutur, göz yaşlarımızın bir türlü çözemediğimiz duldasında, garip gülümsemelerle anarız birbirimizi.

Uğruma yazdığın bütün sözleri asa asa yıkılacaktır dilek ağaçların bir gün. Bütün yaşanmamışlıkların, bütün aldanmışlıkların topuk seslerinde kış gelince kar yeniden yağar, yeni bir sevdanın sesine kurarım saatlerimi. Şimdi yollarım hasır, ayaklarım nasır, bil ki seni düşündükçe içim acır. Katmer hasretinin acı künyelerinde ne koşacak bir sevdam var şimdi, ne de sensiz yaşayacak bir dünyam.

Oysa ki, hayat sevgilinin gülüşleriyle doldurulan bir içki kadehidir her devirde. Yer soframızın bayat ekmeklerini yedikçe, şerbet şerbet acıları içtikçe, bu bizi tam yüreğimizin ortasından bölen şarkıları dinledikçe, acımız da olgunlaşır elbet. İçimizde ‘elim sende’ oynayan çocukların çığlıklarını duyamadıktan sonra, körebe kaçışlara yüreğimizi beledikten sonra bu sevda çok yaşamayacaktı, yaşamadı da. Anlayacağın yunus gözlü sevdam, yokuş yukarı tırmanan bir sevda suyuyum şimdi ve ülkenin denizlerinden buharlaşarak uçuyorum senden.', 'Muammalarla örülü bir sevgi sarayıydı ördüğümüz, yıkıldık Deli hasretler hırpaladı sevdamızı, kaynağı başından kuruttuk Yüreğimizdeki asi ba...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Yetgin']::text[], 8.5, '{"poet":"Selahattin Yetgin","poet_slug":"selahattin-yetgin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kuluckada-kaldi-hayallerimiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nila nila 2', 'nila-nila-2-huseyin-dogan-a4n3e', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Önce kendini bulman gerekli,

keşfetmek için gelecekteki günleri

diyordum. 

Kendi kendime.

..... öyle yaptım Keşfettim bende beni.

Açtım bilinmeyene korkusuzca 

Yüreğimin beyaz yelkenini...

Bomboş bir haritaydım 

Yoktu pergelleyecek çizgilerim

Nerdeyim. 

Nereye gidiyorum.

Nereden ne kadar uzağım.

Bilmiyordum.

Sadece bir yolcu vardı 

Ve sırlarla dolu  yolculuk...

Deniz mavi Gök mavi idi

Mürekkebi mavi seyir defterimin.....

Tam seyahatimi yarılamıştım ki

Ha gayret anlaşılır olacaktı harita:

CIKTI korkunç bir fırtına.

Dalgalar alabora etti her şeyi

Çarpa çarpa paramparça oldu 

Kayalara yelkenlim.

Gözlerimi açtığımda

Yeni bir yolculuk başlıyordu.

Bir deniz kızı  tutmuş ellerimden

Gülümseyerek 

Derin maviliklere yol alıyordu.

Yüreğim artık bir denizaltıydı.

Ve seyir defterim deniz kızının ellerinde....

Nila: Mavi', 'Önce kendini bulman gerekli, keşfetmek için gelecekteki günleri diyordum.  Kendi kendime. ..... öyle yaptım Keşfettim bende beni. Açtım bili...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Doğan']::text[], 8.5, '{"poet":"Hüseyin Doğan","poet_slug":"huseyin-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/nila-nila-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlk Durağımıza Hoşgeldin', 'i-lk-duragimiza-hosgeldin-umit-koral-u9s4r', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ardına bakma ne olur istemem

Sen yolunda yürümeye devam et..

Başını önüne eğme ne olur istemem

Engellere takılmadan koşmaya devam ett

Bırak ağlama boşver                                                                                              Bu dünyanın dertlerini...                                                                                     Bırak gitsin ne olur 

Ben senin yerinede ağlarım

Aramızda sıra dağlarda olsa

Dönmeyecegini bildiğim halde

İlk günkü gibi o heyecanla 

Bekliyorum seni o ilk durağımızda

.....Yani burada.....Hoşgeldin yar...', 'Ardına bakma ne olur istemem Sen yolunda yürümeye devam et.. Başını önüne eğme ne olur istemem Engellere takılmadan koşmaya devam ett Bırak ...', ARRAY['Türk Edebiyatı','Şiir','Ümit Koral']::text[], 8.5, '{"poet":"Ümit Koral","poet_slug":"umit-koral","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ilk-duragimiza-hosgeldin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlk Aşkım', 'i-lk-askim-alper-kuruk-d9seq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Garipliği çitiledim sularda

Acısını hiç arıtamıyorum,

Gönlüme ne sevgiler katıyorum

Tanrı''ca aşklar yaratamıyorum.

Gündüz geceye ulanırcasına 

Günah günah uzasa da hayatım,

Ömrümde olacaktır tek sevabım

Unutamadığım ah o ilk aşkım...', 'Garipliği çitiledim sularda Acısını hiç arıtamıyorum, Gönlüme ne sevgiler katıyorum Tanrı''ca aşklar yaratamıyorum. Gündüz geceye ulanırcasın...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ilk-askim-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çeşitlemeler', 'cesitlemeler-mehmet-lutfu-aydin-ooae2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Milyarlarca insan var, her bir insan bir başka 

Tabiatın raconu, bu iş böyledir işte

Kimisi uyur tembel, kimisi gelir aşka

…………………… İnsanlığın raconu, bu iş böyledir işte

…………………… Kimi yer kuru ekmek, kimisi tavuk şişte

Şoför: 

Bulurum yüz otuzu, koyuldum mu düz yola 

Kural mural tanımam, dalarım sağa sola

Durdurdu mu aynasız, dans ederiz kol kola 

…………………… Şoförlüğün raconu, bu iş böyledir işte

…………………… Kuralsızlık dedin mi, biz geliriz en başta

Tembel:

Sabah zar zor kalkarım, tez cuvara yakarım

Üç beş saat yan gelip, az keyfime bakarım 

Duman altı olunca gaz maskemi takarım

…………………… Tembelliğin raconu, bu iş böyledir işte

……………………  Ekmek elden, su gölden, kârlıyım ben bu iş’te

Kabadayı:

Bu alemin kuralı, kazanır önce çakan

Asıp kesip doğra ki, bozulmasın hiç cakan

Bana derler “Can Yakan”, var mı bana yan bakan? 

…………………… Dayılığın raconu, bu iş böyledir işte

…………………… Altıpatlar atışta, düşmez elimden muşta

Balıkçı:

Lüfere bak ablacım, derya kuzusu derya

Tekir balığı dersen, okuyor türkü, arya 

Yetiş baba, sen de al, bugün palamut furya

…………………… Balıkçının raconu, bu iş böyledir işte

…………………… Ölü hamsi dirilir, horon teper kar kışta

Ayyaş:

Rakı olsa denizler, ortasında yüzerim

Yunuslarla birlikte, şarkı söyler, gezerim

Kafam iyi, göklerde, yıldızları süzerim

…………………… Ayyaşlığın raconu, bu iş böyledir işte

…………………… Davul zurna az gelir, ayılamam bir duşta

Hovarda:

Akşamı iple çeker, boşaltırım kasamı

Kapatırım bar, pavyon, donatırım masamı

Sağım solum manita, yazmışım ben yasamı

…………………… Çapkınlığın raconu, bu iş böyledir işte

…………………… Hızlı yaşa, matiz ol, uyuz olma genç yaşta 

Siyasetçi:

Vatandaş seçti beni, etti başının tacı

Gezdim Arap, Hicaz’ı, oldum kutlu bir hacı

Seçmen sıktı kemeri, sıktıkça çekti acı

…………………… Siyasetin raconu, bu iş böyledir işte

…………………… Yatıp kalkıp dua et, yaşa hayalde, düşte 

Yurttaş: 

Lütufi’yim, örflere, törelere uyarım 

Yetim hakkı yiyene, müthiş öfke duyarım

İki lokma, bir tas su, hemencecik doyarım

…………………… Dürüstlüğün raconu, bu iş böyledir işte

…………………… Tanrı muhtaç etmesin, ne namerde ne puşta', 'Milyarlarca insan var, her bir insan bir başka  Tabiatın raconu, bu iş böyledir işte Kimisi uyur tembel, kimisi gelir aşka …………………… İnsanlığ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Lütfü Aydın']::text[], 8.5, '{"poet":"Mehmet Lütfü Aydın","poet_slug":"mehmet-lutfu-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/cesitlemeler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Avuntu gölleri..', 'avuntu-golleri-hasan-esat-heptunali-i4qxf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'O sakin limanlar ki,

Avuntu gölleri...

Kendimizi aldattığımız... 

O fırtınalar ki,

Hep çeker bizi... 

Koynunda kaybolduğumuz.....', 'O sakin limanlar ki, Avuntu gölleri... Kendimizi aldattığımız...  O fırtınalar ki, Hep çeker bizi...  Koynunda kaybolduğumuz........', ARRAY['Türk Edebiyatı','Şiir','Hasan Esat Heptunalı']::text[], 8.5, '{"poet":"Hasan Esat Heptunalı","poet_slug":"hasan-esat-heptunali","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/avuntu-golleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçimdeki Gıcık Sesler', 'i-cimdeki-gicik-sesler-umit-koral-xrygr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yüzünü köpekler görsün ben değil..! 

...Ben değil onlar anlasın ancak seni

Derdine derman olurlar belki senin

...Nede olsa aynı kafaya

Sahip değilmisiniz 

...Değişen Bir yanınız yok ki..!', 'Yüzünü köpekler görsün ben değil..!  ...Ben değil onlar anlasın ancak seni Derdine derman olurlar belki senin ...Nede olsa aynı kafaya Sahip...', ARRAY['Türk Edebiyatı','Şiir','Ümit Koral']::text[], 8.5, '{"poet":"Ümit Koral","poet_slug":"umit-koral","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/icimdeki-gicik-sesler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilmek gerek...', 'bilmek-gerek-hasan-esat-heptunali-rpxcf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Toplanmış bulutlar… 

Hava patlamak üzere… 

Nefes almak ne de zormuş meğer 

Kabarır deniz az sonra … 

Arsızca...

Yutarcasına… 

Kayıp ilanlarında dinginliğim 

Ya teslim olmalı azgın dalgalara… 

Küçük bir ceviz kabuğu misali...

Ya da direnmeli… 

Seç seç beğen 

Binlerce soru içinden… 

fazla mesaideyken içimin kurtçukları...

Kuytu limanlar ne kadar da uzak…. 

Bir küfür savuruyorum fütursuzca 

Dumanı gibi sigaramın...

Rüzgarla... 

Ve...

Yitiyor boşlukta...

Sonra...

Bir yağmur çiseliyor ki 

Ahmak ıslatan… 

Koyuverse ya kendini gürül gürül… 

Çıkıverse ya güneş diyorum… 

Diyorum da...

Çıkmıyor be namussuz… 

Ben de sormuyorum…“niye? ” 

Erkeklik bizde kalsın...

Zira biliyorum… 

Her yağmurun ardında bir güneş gizli 

Ve bazen de… 

Beklemesini bilmek gerek… 

O güneşi…', 'Toplanmış bulutlar…  Hava patlamak üzere…  Nefes almak ne de zormuş meğer  Kabarır deniz az sonra …  Arsızca... Yutarcasına…  Kayıp ilanları...', ARRAY['Türk Edebiyatı','Şiir','Hasan Esat Heptunalı']::text[], 8.5, '{"poet":"Hasan Esat Heptunalı","poet_slug":"hasan-esat-heptunali","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/bilmek-gerek-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elveda İstanbul', 'elveda-i-stanbul-umit-koral-kr571', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '..........İstanbul beni sen değil 

...Beni sevgilim bitirdi..

....... Senin içindeki sokaklarda,

....Kaybolacağımı düşünürken

.......Sevgilimin nefret dolu..

....Kin dolu kalbinde kayboldum...

.......Ben sana değill...

...Sevgilime yenildim..

.......Elveda İstanbul

...Elveda yarim

........hoşgeldin yalnızlık', '..........İstanbul beni sen değil  ...Beni sevgilim bitirdi.. ....... Senin içindeki sokaklarda, ....Kaybolacağımı düşünürken .......Sevgili...', ARRAY['Türk Edebiyatı','Şiir','Ümit Koral']::text[], 8.5, '{"poet":"Ümit Koral","poet_slug":"umit-koral","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/elveda-istanbul-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çırıl çıplak..', 'ciril-ciplak-hasan-esat-heptunali-w467r', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çırıl çıplak 

Geldim sana… 

Meğer...

Şehvetinmiş kabaran yalnızca...

Yazık…. 

…………. 

Sigara?', 'Çırıl çıplak  Geldim sana…  Meğer... Şehvetinmiş kabaran yalnızca... Yazık….  ………….  Sigara?...', ARRAY['Türk Edebiyatı','Şiir','Hasan Esat Heptunalı']::text[], 8.5, '{"poet":"Hasan Esat Heptunalı","poet_slug":"hasan-esat-heptunali","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/ciril-ciplak-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah Bir Çocuk Olsaydım', 'ah-bir-cocuk-olsaydim-ahmet-ormanci-w9vfg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çocuklarımız saf ve temiz sembolleri,

Büyüklerin.

Şimdi bir çocuk olmayı,

Ne kadar çok isterdim.

Daha çok insanla tanışır,

Daha çok dinlerdim düşüncelerini,

Duygularını öğrenmek isterdim her konuda.

Oysa şimdi; 

Birine bir selâm bile verseniz,

Hemen nedenini arar,

Sorgular sizi kafasında.

Bir de hiç tanımadığınız biriyse bu,

Tuhaf tuhaf bakılırsınız bir süre ardınızdan.

İnsanlara yapılan yardımların,

iyiliklerin bile altında,

Bir şeyler ararız biz büyükler.

Neden değişir insanlar büyüdükçe? 

Hepten anlaşılmaz olurlar neden? 

Çocukken oynadığımız oyunları,

Neden oynayamayız şimdi? 

Aslında bunu biliyorum.

Deli derler bize değil mi? 

Ama desinler inanın hiç farketmez,

Hatta bana çocuk olmak bile yetmez.', 'Çocuklarımız saf ve temiz sembolleri, Büyüklerin. Şimdi bir çocuk olmayı, Ne kadar çok isterdim. Daha çok insanla tanışır, Daha çok dinlerdi...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ormancı']::text[], 8.5, '{"poet":"Ahmet Ormancı","poet_slug":"ahmet-ormanci","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ah-bir-cocuk-olsaydim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah Şu Benim Çocuksu Kalbim', 'ah-su-benim-cocuksu-kalbim-ahmet-ormanci-k3s02', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yalancının mumu hiç sönmezmiş.

Küçücük menfaatler uğruna,

Dostlukların yaralanmasına,

Dayanamıyor şu çocuksu kalbim.

Baka baka üzüm üzüme kararmazmış.

Sadece para, pul adına,

İnsanımın hırpalanmasına,

Dayanamıyor şu çocuksu kalbim.

İşe yaramaz olmuş artık kalem.

Varsa yoksa silahlanma.

Düşmanlıkların mayalanmasına,

Dayanamıyor şu çocuksu kalbim.

Sükût gümüş, söz altınmış.

Kulak kesilmişler konuşuna.

Aziz milletimin karalanmasına,

Dayanamıyor şu çocuksu kalbim.', 'Yalancının mumu hiç sönmezmiş. Küçücük menfaatler uğruna, Dostlukların yaralanmasına, Dayanamıyor şu çocuksu kalbim. Baka baka üzüm üzüme ka...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ormancı']::text[], 8.5, '{"poet":"Ahmet Ormancı","poet_slug":"ahmet-ormanci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ah-su-benim-cocuksu-kalbim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Sana Muhtacım', 'ben-sana-muhtacim-ahmet-ormanci-ib3uf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Denizler,ırmağa muhtaç,

Ağaçlar, yaprağa.

Ben, ben sadece sana muhtacım.

Gözlerim, gözlerine muhtaç,

Ellerim ellerine.

Ben sana muhtacım sadece,

Su gibi, ekmek gibi,

Aldığım nefes gibi muhtacım.

Söyle bana,

Deniz ırmaksız olur mu? 

Ya ağaç yapraksız.

İnsan hiç yaşar mı sanıyorsun,

Nefes almadan, aç, susuz.

Bilmem anlıyor musun? 

Acaba ben sensiz,

Yaşıyor muyum?', 'Denizler,ırmağa muhtaç, Ağaçlar, yaprağa. Ben, ben sadece sana muhtacım. Gözlerim, gözlerine muhtaç, Ellerim ellerine. Ben sana muhtacım sad...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ormancı']::text[], 8.5, '{"poet":"Ahmet Ormancı","poet_slug":"ahmet-ormanci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ben-sana-muhtacim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Farklı Ruhlar', 'farkli-ruhlar-ahmet-ormanci-0m41x', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Her akşam sensizlik çöker içime,

Kara bir bulut gibi,

Güneşin batışıyla birlikte,

Kararır,üşür ruhum.

Seni görebilmek,görememek

Bu ikilemle yaşarım tüm geceyi,

Ta ki günün ilk ışıklarına dek.

Nihayet Sabah olur:

Güneşle birlikte aydınlanır ruhum da,

Sen gelirsin aklıma,

Göremesem de seni, sesini duyamasam da; 

Biliyorum:

Sıcacık bakıyor gözlerin dünyaya,

Ama kim bilir kimin gözlerinde? 

Ilık sesin okşuyor yine; 

Etrafındaki insanların kulaklarını.

Sakin,uysal tavırların geliyor aklıma,

Kim bilir, kimleri mest ediyorsun yine

Benim ruhumdan çok uzaklarda.', 'Her akşam sensizlik çöker içime, Kara bir bulut gibi, Güneşin batışıyla birlikte, Kararır,üşür ruhum. Seni görebilmek,görememek Bu ikilemle ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ormancı']::text[], 8.5, '{"poet":"Ahmet Ormancı","poet_slug":"ahmet-ormanci","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/farkli-ruhlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duygu Mücadelesi', 'duygu-mucadelesi-ahmet-ormanci-4wart', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bunca yıl sensiz yaşadım,

Hem de hiç düşünmeden seni.

Bir çok insan tanıdım senin gibi,

Ama hiç böyle olmadım.

Şimdi,karmakarışık düşüncelerim,

Duygularım, ruhum.

Alabora oldu hayatım birden,

Derin sularda buldum kendimi,

Çırpınıyor, çıkamıyorum bir türlü,

Çırpındıkça derinlere,

Daha derinlere mi gidiyorum ne? 

Anlamıyorum bir türlü kendimi,

Sanki ben değilim bu deli dolu insan.

Ne yaptın ki bana,

Ne vardı sende farklı olan,

Dostluk mu, arkadaşlık mı? 

Sanki hiç olmadı mı arkadaşım, dostum,

Söyle bana şimdi ben niye böyle oldum.', 'Bunca yıl sensiz yaşadım, Hem de hiç düşünmeden seni. Bir çok insan tanıdım senin gibi, Ama hiç böyle olmadım. Şimdi,karmakarışık düşünceler...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ormancı']::text[], 8.5, '{"poet":"Ahmet Ormancı","poet_slug":"ahmet-ormanci","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/duygu-mucadelesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gerçek Dostlarıma', 'gercek-dostlarima-ahmet-ormanci-57b6z', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yalnız kalmak ne kadar zor,

Hele hele yığınlar içinde yalnız kalmak.

Çevren insan kaynıyor,

Ama seni anlayan,ne yazık ki yok.

Gerçek dostların değerini anlıyor insan,

Gerçek insanların değerini.

Sahte bakışlara,sözlere,gülücüklere,

Katlanmak ne kadar da zor.

                                                               

Ahmet Ormancı

13.07.2005', 'Yalnız kalmak ne kadar zor, Hele hele yığınlar içinde yalnız kalmak. Çevren insan kaynıyor, Ama seni anlayan,ne yazık ki yok. Gerçek dostlar...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ormancı']::text[], 8.5, '{"poet":"Ahmet Ormancı","poet_slug":"ahmet-ormanci","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/gercek-dostlarima-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yürek tuccarı''na', 'yurek-tuccari-na-mehmet-selim-bataroglu-dzzik', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Paylaşınca uzayıp gider

derin maviliklerin

her yeni canda hayat bulur 

yeniden doğmuşçasına

yürek ister 

doğum sancısını çekme cesareti

kaybettiklerin

yüreğinden verdiklerin

yürek tüccarı pazarında

eğilmeyen asi başın

her yeni insanda 

yeniden doğmayı isterken

derinlere inebilme çabası niyetin

inilememiş gizli deryalara açılmak dileğin

sadece dik dur

korkma ulan!', 'Paylaşınca uzayıp gider derin maviliklerin her yeni canda hayat bulur  yeniden doğmuşçasına yürek ister  doğum sancısını çekme cesareti kayb...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Selim Bataroğlu']::text[], 8.5, '{"poet":"Mehmet Selim Bataroğlu","poet_slug":"mehmet-selim-bataroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yurek-tuccari-na-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gecenin Garipliği', 'gecenin-garipligi-ahmet-ormanci-u1on8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gecenin en sessiz yerinde,

Seni hayal ederdim,

Yüzünde gülücüklerle.

Gecenin en tatlı yerinde,

Dalmışken uykuya herkes,

Kokunu duyardım ta içimde.

Gecenin en derin yerinde,

Kapanmışken tüm gözler,

Derin bakışların vardı benimle.

Gecenin en ıssız yerinde,

Bir yıldızlar vardı gökyüzünde,

Bir de sen vardın,

Gönlümde.', 'Gecenin en sessiz yerinde, Seni hayal ederdim, Yüzünde gülücüklerle. Gecenin en tatlı yerinde, Dalmışken uykuya herkes, Kokunu duyardım ta i...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ormancı']::text[], 8.5, '{"poet":"Ahmet Ormancı","poet_slug":"ahmet-ormanci","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gecenin-garipligi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İşte Hayat Bu', 'i-ste-hayat-bu-ahmet-ormanci-xmz56', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dünyada insana en ağır gelen şey,

Sana güvenenlerin güvenini,

Seni sevenlerin sevgisini,

Boşa çıkarmandır.

Güvenirse insan birine,

Emniyettedir.

Güvenilirse, huzurlu.

Mutlu etmeyebilir insanı,

Sevmek.

Ama bir de sevilirse! ..

İşte o zaman,

Değme gitsin,

Yaşamanın keyfine.', 'Dünyada insana en ağır gelen şey, Sana güvenenlerin güvenini, Seni sevenlerin sevgisini, Boşa çıkarmandır. Güvenirse insan birine, Emniyette...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ormancı']::text[], 8.5, '{"poet":"Ahmet Ormancı","poet_slug":"ahmet-ormanci","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/iste-hayat-bu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birini Arıyorum', 'birini-ariyorum-ahmet-ormanci-blix6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sevgiyi dolamış diline,

Konuşan birini arıyorum.

Aşkı sarmış kalbine,

Yaşayan birini arıyorum.

Dostluğu almış eline,

Dolanan birini arıyorum.

Bencillik atmış denize,

Kaçışan birini arıyorum.

Helâlinden almış evine,

Yarışan birini arıyorum.

Canını takmış dişine,

Çalışan birini arıyorum.

Gülücükler katmış yüzüne,

Bakışan birini arıyorum.

Savaşı çakmış yerin dibine,

Barışan birini arıyorum.', 'Sevgiyi dolamış diline, Konuşan birini arıyorum. Aşkı sarmış kalbine, Yaşayan birini arıyorum. Dostluğu almış eline, Dolanan birini arıyorum...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ormancı']::text[], 8.5, '{"poet":"Ahmet Ormancı","poet_slug":"ahmet-ormanci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/birini-ariyorum-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karşılıksız Sevmek', 'karsiliksiz-sevmek-ahmet-ormanci-jea2q', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İnsan sevdiği kadar,

Sevilmeye bilir belki.

Ama olsun,

Karşılıksız sevmek, bence en güzeli.

Hangisi güzel ki; 

Karşılık beklenerek yapılan şeylerin.

Ancak, şu da bir gerçek,

Sevince değil, 

İnsan sevilince mutludur', 'İnsan sevdiği kadar, Sevilmeye bilir belki. Ama olsun, Karşılıksız sevmek, bence en güzeli. Hangisi güzel ki;  Karşılık beklenerek yapılan ş...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ormancı']::text[], 8.5, '{"poet":"Ahmet Ormancı","poet_slug":"ahmet-ormanci","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/karsiliksiz-sevmek-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutlu Muyum?', 'mutlu-muyum-ahmet-ormanci-u69gt', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Mutluyum desem yalan olur,

Ben pek tadamadım bu duyguyu.

Didişirken birbiriyle insanlar,

Yaşayabilir miyim mutluluğu? 

Doğru, yalan olurdu mutluyum desem,

Hiç savaşılmadan geçirilen,

Bir gün var mı şu dünyada? 

Evet, asla mutlu değilim.

Boy boy, ırk ırk, renk renk insanları,

Görmeyince el ele,

Söyleyinbana, mutlu olabilir miyim sizce?', 'Mutluyum desem yalan olur, Ben pek tadamadım bu duyguyu. Didişirken birbiriyle insanlar, Yaşayabilir miyim mutluluğu?  Doğru, yalan olurdu m...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ormancı']::text[], 8.5, '{"poet":"Ahmet Ormancı","poet_slug":"ahmet-ormanci","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/mutlu-muyum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dillendirilmeyen...', 'dillendirilmeyen-hasan-esat-heptunali-xapoc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'gecenin ıslağından 

içine çektiğin 

serin bir nefes gibi, 

ardında bıraktığın onca 

yarımı düşünmek, 

üşütür içini… 

bir çift gözle, 

göz göze gelirsin 

inceden yağan yağmurun 

yol yol ettiği camda, 

irkilirsin… 

şehrin silueti uğurlar gibidir 

seni 

bir terk ediş, 

terk ediliş belki 

bu dillendirilmeyen.. 

gece… 

ve sessizlik.. 

içindeki..', 'gecenin ıslağından  içine çektiğin  serin bir nefes gibi,  ardında bıraktığın onca  yarımı düşünmek,  üşütür içini…  bir çift gözle,  göz gö...', ARRAY['Türk Edebiyatı','Şiir','Hasan Esat Heptunalı']::text[], 8.5, '{"poet":"Hasan Esat Heptunalı","poet_slug":"hasan-esat-heptunali","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/dillendirilmeyen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutlu Olmak', 'mutlu-olmak-ahmet-ormanci-48e46', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir gece iki genç,

Aynı pencereden dışarı baktı.

Biri gökyüzündeki parlak yıldızları gördü,

Diğeri yerdeki çamurları.

Nasıl bakarsan, öyle görürsün hayatı.

Her zaman iki seçenek var önünde.

Ya pozitif düşünüp,

Güzeli yaşayacaksın.

Ya da negatif düşünerek,

Çirkini. 

İstediğin sadece mutlu olmak mı? 

İnan bana bir şey gelmez elimden.

Biliyorsun ki bu, yalnızca sana bağlı.', 'Bir gece iki genç, Aynı pencereden dışarı baktı. Biri gökyüzündeki parlak yıldızları gördü, Diğeri yerdeki çamurları. Nasıl bakarsan, öyle g...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ormancı']::text[], 8.5, '{"poet":"Ahmet Ormancı","poet_slug":"ahmet-ormanci","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/mutlu-olmak-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tutsak', 'tutsak-ahmet-ormanci-rwkbu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen, benim özgürlüğümü aldın elimden,

Artık evime istediğim sokaktan gidemiyorum.

Halbuki hiç sevmezdim ben buraları,

Şimdi, sizin mahallenin köpeklerini bile seviyorum.

Sen, benim özgürlüğümü aldın elimden,

Artık etrafımda kalabalıklar istemiyorum.

Halbuki hiç sevmezdim ben yalnız kalmayı,

Şimdi artık yalnızlığı seviyorum.

Saçının tellerine bağlayıp beni,

Tutsak ettin kendine.

Senden başka hiçbir şey düşünemiyorum

Ve düşünmek de istemiyorum.', 'Sen, benim özgürlüğümü aldın elimden, Artık evime istediğim sokaktan gidemiyorum. Halbuki hiç sevmezdim ben buraları, Şimdi, sizin mahalleni...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ormancı']::text[], 8.5, '{"poet":"Ahmet Ormancı","poet_slug":"ahmet-ormanci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/tutsak-50-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eylül; sonbahar', 'eylul-sonbahar-galip-kemali-gunay-6dnso', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Eylül..............................................................................................................................koptu süzüldü dalından..............varmak için.............bir yeni bahara.................kondu şurama..............................................................................kahverengi sarı, bir altın varak, koptu süzüldü dalından kondu aramıza................................................haydi arkadaşlar mı dedi.. yoksa kim itti beni..............................................................................................................................koptu süzüldü dalından kondu aramıza...............................................................en duygusalı mı yoksa en yüreklisi mi idi..önce dalına, sonra göğe mi baktı atladı.. tartışılır da; ..düştü aramıza.......................................aldığım selam yeşilimsi sarı..............duydum sonbaharım diyen fısıltısını.....................sonbahar.......... aynı dallar...........aynı mı yapraklar....................dilerim ki sana..kış ardında  yeni baharım ben demiştir..................bir altın varaktı. aldım şurama koydum...', 'Eylül..............................................................................................................................koptu süz...', ARRAY['Türk Edebiyatı','Şiir','Galip Kemali Günay']::text[], 8.5, '{"poet":"Galip Kemali Günay","poet_slug":"galip-kemali-gunay","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/eylul-sonbahar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağaç gövdeli yürektaşım', 'agac-govdeli-yurektasim-mehmet-selim-bataroglu-qo7y1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çoğu ağaç parçası der

Benim gül yoldaşıma

İç dünyamın

Kanayan yaralarımın

Bilinmezlik ülkesine

Gitme cesareti gösterdiğim de 

Kurak çöllerime vaha olur

Pansuman olur ciğerime

Nağmelerinde kaybolurum 

Tiz sesinin

Haykıran dağ olurum 

Bamtelinin

Titreşiminde 

Orta telleri

Gülümsetir içimi 

Gövdesini kucaklarım 

İçimi ısıtır

Parmaklarımı 

İşlerim sapına 

Gümüş gümüş 

Ne düşünürsem 

Onu söyler 

Yargılamaz

Sorgulamaz 

Suçlamaz

Hor görmez 

Küçümsemez 

Karşılık beklemez 

Bu gün nasılsın derim 

Seni seviyorum der DO aşkıyla 

Sen özelsin der RE makamın da 

Hoş görü ve sevgi olsun yolun der Mİ baharın da

Karanlıktan korkma der FA gül bahçesin de 

İçini bana dök der SOL darboğazın da 

Sana zarar vermem der LA sıcaklığıyla 

Kucağıma yat saçlarını okşayayım der Sİ şefkatiyle 

İşte öyle güzel benim sessiz ağaç gövdeli yürek taşım', 'Çoğu ağaç parçası der Benim gül yoldaşıma İç dünyamın Kanayan yaralarımın Bilinmezlik ülkesine Gitme cesareti gösterdiğim de  Kurak çöllerim...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Selim Bataroğlu']::text[], 8.5, '{"poet":"Mehmet Selim Bataroğlu","poet_slug":"mehmet-selim-bataroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/agac-govdeli-yurektasim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur Damlası', 'yagmur-damlasi-ahmet-ormanci-880tm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sanki çorak bir toprak,

Sensiz hayat.

Can verirsin düştüğün yerlere,

Tıpkı bir yağmur damlası gibi.

Yeşerir güzellikler bir bir,

Yaşadığın her iklimde.

Asla hayat bulmaz kötü duygular,

Senin olduğun yerlerde.

Sen bir yağmur damlası kadar,

Saf, temiz,

Bir yağmur damlası kadar,

Bereketli ve şefkâtlisin.

Gönüllere dolan bir huzursun sanki,

Bir duygusun mutluluklar dağıtan,

Bilmem gerçek, bilmem yalan,

Bence bir yağmur damlası gibisin.', 'Sanki çorak bir toprak, Sensiz hayat. Can verirsin düştüğün yerlere, Tıpkı bir yağmur damlası gibi. Yeşerir güzellikler bir bir, Yaşadığın h...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ormancı']::text[], 8.5, '{"poet":"Ahmet Ormancı","poet_slug":"ahmet-ormanci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yagmur-damlasi-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalancı Tat', 'yalanci-tat-ahmet-ormanci-dzz9u', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bana da hoş gelir herkes gibi,

Tatlı sözler.

Götürür güzel rüyalara,

Sürükler süt liman denizlere,

Dalgalar gibi.

İşte her şey,

Uyandığım zaman başlar:

Güzel rüyam,

Kâbuslara,

Sürüklendiğim süt liman deniz,

Bataklıklara dönüşür.

Her çırpınışım,

Vücudumdan bir parça daha götürür.

Her feryadım,

Gücümden bir parça alır.

Sonunda yenilir,pes ederim.

Beni sıcacık saran,

Bataklığın kollarına bırakırım 

Kendimi.

Battıkça aklım başıma gelir,

Battıkça batarım.

Fayda vermez pişmanlığım,

Biliyorum,artık geç kaldım.

Ahmet ORMANCI

16.06.1994 - MARDİN', 'Bana da hoş gelir herkes gibi, Tatlı sözler. Götürür güzel rüyalara, Sürükler süt liman denizlere, Dalgalar gibi. İşte her şey, Uyandığım za...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ormancı']::text[], 8.5, '{"poet":"Ahmet Ormancı","poet_slug":"ahmet-ormanci","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/yalanci-tat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık', 'yalnizlik-ahmet-ormanci-hz2ag', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir başka oluyorum akşamları; 

Acaba korkuyor muyum? 

Sensiz,tek başıma karanlıktan.

Hayır! Hayır! Korkmuyorum.

Ama,yavaş yavaş üşüyorum galiba,

Akşamla batan,güneşlere denk

Sıcaklığın olmadığından.

Bir hüzün çöküyor ruhuma

İlerledikçe zaman.

Karanlığın sessizliğinde,

Sesini duyamadığımdan.

Ahmet ORMANCI

17.03.1995 - Kütahya', 'Bir başka oluyorum akşamları;  Acaba korkuyor muyum?  Sensiz,tek başıma karanlıktan. Hayır! Hayır! Korkmuyorum. Ama,yavaş yavaş üşüyorum gal...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ormancı']::text[], 8.5, '{"poet":"Ahmet Ormancı","poet_slug":"ahmet-ormanci","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yalnizlik-280-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık Hayali', 'yalnizlik-hayali-ahmet-ormanci-wuvtg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Batarken akşamları güneş,

Hafif bronz tenin gelir aklıma.

Az sonra meltem başlar,

Ilık nefesin gibi; ferahlatır her yanı,

Hafif hafif dalgalanır deniz,

Uzun saçların gelir aklıma.

Kararır gökyüzü,ilerledikçe zaman,

Yıldızlar gözükür bir bir yanıp sönen.

Gözlerin gelir aklıma,

Yanan, ama hiç sönmeyen.

Yıldızları seyrederken.

Onlar kadar gerçek,

 Gülüşlerin gelir aklıma,

Ay yükselir ardından yıldızların,

Sakin, neşeli yüzün görünür,

Yakamozlarda.

Ve ben dalar giderim yine yalnızlığıma.', 'Batarken akşamları güneş, Hafif bronz tenin gelir aklıma. Az sonra meltem başlar, Ilık nefesin gibi; ferahlatır her yanı, Hafif hafif dalgal...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ormancı']::text[], 8.5, '{"poet":"Ahmet Ormancı","poet_slug":"ahmet-ormanci","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yalnizlik-hayali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Med ve Cezir', 'med-ve-cezir-gulseren-onay-0uy1c', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Denizle kara gibi 

Çocukça oyun oynuyoruz 

İlk dördünde ayın 

Sen 

Dolunayda 

Ben 

Gidiyorum... 

Sadece ay sonları 

Kalıyor sevgimize 

Cebimizde metelik yokken.

10/06/2005/ANTALYA', 'Denizle kara gibi  Çocukça oyun oynuyoruz  İlk dördünde ayın  Sen  Dolunayda  Ben  Gidiyorum...  Sadece ay sonları  Kalıyor sevgimize  Cebim...', ARRAY['Türk Edebiyatı','Şiir','Gülseren Onay']::text[], 8.5, '{"poet":"Gülseren Onay","poet_slug":"gulseren-onay","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/med-ve-cezir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Sevgiliye Sitem*', 'sevgiliye-sitem-umit-koral-zbp6h', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '...Her zaman ki gibi sen haklısın

Ve bende her zamanki

...Olduğu gibi haksızım değil mi? 

Yoo..! Artık öyle değil...

...Sen haksızsın sen suçlusun...

Ben bu şiiri  kime yazıyorum ki

....Zaten anlamayacaksın..

Bırak ellerime yazık....', '...Her zaman ki gibi sen haklısın Ve bende her zamanki ...Olduğu gibi haksızım değil mi?  Yoo..! Artık öyle değil... ...Sen haksızsın sen su...', ARRAY['Türk Edebiyatı','Şiir','Ümit Koral']::text[], 8.5, '{"poet":"Ümit Koral","poet_slug":"umit-koral","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sevgiliye-sitem-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özür dilerim', 'ozur-dilerim-adem-sirin-nygb5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seni üzdügüm icin,

Seni cok sevdigim icin

Bilseydim bu kadar üzülecegini

Inanki yine severdim

       özür dilerim! 

Bilmiyorum sen de benim gibi misin? 

Ayni acilari cekebilir misin? 

Yooo, hic mi hic sanmiyorum

Sen ''TASASIZ'' sin yaniliyorsam,

        özür dilerim! 

Ne zaman anlatmak istesem sana

Sadece anlatmak istememde kalir,

Icime atarim icimde kalir

Sen istersen bir gün, anlatamam,

         özür dilerim! 

Bak yine seni düsünüyorum

Uzaktaymisin gibi seni özlüyorum

Yanimdasin ama yalnizim

Ne yapayim elimde degil,

          özür dilerim! 

Sen gülerken seninle gülmek,

Aglarken dur aglama demek

Aciyi tatliyi seninle...

Imkansiz olsa da

Yine de

           özür dilerim! 

Sunamadiysam sana sevgimi

Günesin sicagini, ciceklerin rengini

Anlamsiz anlamsiz atan kalbimi

Bütün bunlarin suclusu benim

            özür dilerim! 

Istemeden oldum böyle

dedim,

kendi kendime, 

gel kendine

Ama yapamadim, olmadi

          özür dilerim! 

Karar verdim gidecegim

Inanki arkama bile bakmayacagim

Biliyorum yalan da söyleyemiyorum

Her sözümde kendimi ele veriyorum

        özür dilerim! 

Elimde kalem, yanimda sen yaziyorum

Yazdiklarimi ben de bilmiyorum

Susuyor konusmuyor,

bakiyor görmüyorum

Seni düsündükce,

Her gün bir baska sekilde ÖLÜYORUM

Sen bunlara aldirma,

gecmese de

    cok

          cok

               cok

özür dilerim!', 'Seni üzdügüm icin, Seni cok sevdigim icin Bilseydim bu kadar üzülecegini Inanki yine severdim        özür dilerim!  Bilmiyorum sen de benim ...', ARRAY['Türk Edebiyatı','Şiir','Adem Sirin']::text[], 8.5, '{"poet":"Adem Sirin","poet_slug":"adem-sirin","theme":"Türk Şiiri","is_hero":false,"total_lines":54,"source_url":"https://www.antoloji.com/ozur-dilerim-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidiyorum', 'gidiyorum-umit-koral-31wfp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gİdiyorum artık buralardan 

Seni nefretinle başbaşa,

Bırakıp çekip gidiyorum.

Bir daha arayıp sormam artık..

Sana burdan baksam yeter! 

Neden gelemez oldu bu tren

Seside duyulmuyor uzaktan,

Yoksa yolunu mu şaşırdı benim gibi

İşte geliyor,elveda gidiyorum

Gidiyorum..... gidiyorum....', 'Gİdiyorum artık buralardan  Seni nefretinle başbaşa, Bırakıp çekip gidiyorum. Bir daha arayıp sormam artık.. Sana burdan baksam yeter!  Nede...', ARRAY['Türk Edebiyatı','Şiir','Ümit Koral']::text[], 8.5, '{"poet":"Ümit Koral","poet_slug":"umit-koral","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/gidiyorum-167-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ellerin Gülümsemiyor Artık', 'ellerin-gulumsemiyor-artik-mehmet-marsan-4m4f5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Nedir bakışlarına bağlayan beni

Bilir misin nedir gönlümde esen

Bakir hüzünlerden arda kalan

Bir ince yağmur ve sen

                      Kar mı yağdı yüreğine

                      Ürkek bakışlarında üşüdüm

Guruplara gerilirken akşamlar

Kızıl saçlarına asarlar  beni

Şarkılar söyle türküler yak

Sevda kundağına sar beni

                          Kar mı yağdı yüreğine

                          Ellerin gülümsemiyor artık', 'Nedir bakışlarına bağlayan beni Bilir misin nedir gönlümde esen Bakir hüzünlerden arda kalan Bir ince yağmur ve sen                       Ka...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Marşan']::text[], 8.5, '{"poet":"Mehmet Marşan","poet_slug":"mehmet-marsan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ellerin-gulumsemiyor-artik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Buğu', 'bugu-bekir-mutlu-gokcesu-kmzb6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bilir misin mor ne demek? 

Düşmek griden

Kahverengiden geçmek

Ötesi kızılların

Göğü, denizi içmek

Sarı hüzünlere küsmek

Ermek bahara

Ve gözlerinin buğusu

Bizatihi mor

Buğu aşk demek...', 'Bilir misin mor ne demek?  Düşmek griden Kahverengiden geçmek Ötesi kızılların Göğü, denizi içmek Sarı hüzünlere küsmek Ermek bahara Ve gözl...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bugu-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benden Sana Hediye', 'benden-sana-hediye-umit-koral-dr3qv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Beni attın bir kör kuyuya,

Bu öyle bir dipsiz kuyu ki

Senin hasretinle boğuluyorum 

Yakındır iflas edip ölmem

Hemde çok yakındır merak etme yar

Her yaşam tamamlanacak değil ya

Bırak beni bu da böyle yarım kalsın..

Sen de sefasını sür...', 'Beni attın bir kör kuyuya, Bu öyle bir dipsiz kuyu ki Senin hasretinle boğuluyorum  Yakındır iflas edip ölmem Hemde çok yakındır merak etme ...', ARRAY['Türk Edebiyatı','Şiir','Ümit Koral']::text[], 8.5, '{"poet":"Ümit Koral","poet_slug":"umit-koral","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/benden-sana-hediye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüyamda Gördüm', 'ruyamda-gordum-ekrem-sama-2sh5g', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kahretti beni, gece gördüğüm rüya; 

Üniversite önündeymişim güya,

Kapıdaki görevli; baktım bir azman,

Elinde koca bir satır, aman aman! 

Satırı öğrencilere bir vuracak,

Alimallah koparır kol veya bacak.

Şık giyimli bir öğrenciyi durdurdu,

Sakalsız halini görünce kudurdu:

“-Bre zındık, defol, hemen buradan sıvış! 

Sakal bırakıp da gel, en az bir karış! ”

İşte bir kız öğrenci, mahcup, hevesli,

Dikildi önüne o canavar sesli:

“-Oo! Hanıma bakın, başı gözü açık,

Başörtün yok, hemen arkanı dön ve çık.”

Allah Allah! Neler görüyorum yahu? 

Katledilmiş hak ve hürriyetin ruhu.

Öğrencilere yapılan bir barbarlık,

Tam da Avrupa’ya girecektik, yazık! 

İsyan ettim, sanki yıkılmıştı dünya,

Bağırıp fırlamışım, gördüm ki rüya.

Sırılsıklam olmuşum, boncuk boncuk ter,

Sesimi duymuşlar, koştu bizimkiler.

Annem dedi ki; “Hayır olsun be oğlum! 

Rüyalar ters çıkar iyi biliyorum.”

Şimdi baktım, üniversitenin önü,

Zulümler yüzünden ana baba günü.

Hatırladım annemin verdiği dersi,

Benim rüyam gerçekmiş, ama tam tersi...

(İstanbul:07.10.2004)', 'Kahretti beni, gece gördüğüm rüya;  Üniversite önündeymişim güya, Kapıdaki görevli; baktım bir azman, Elinde koca bir satır, aman aman!  Sat...', ARRAY['Türk Edebiyatı','Şiir','Ekrem Şama']::text[], 8.5, '{"poet":"Ekrem Şama","poet_slug":"ekrem-sama","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/ruyamda-gordum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geceler', 'geceler-canan-karadaglioglu-2-wo0sy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Renklerden geçtim,siyahı seçtim

Bana benzeyen sadece o''ydu

Geceler alsa da rengini benden

Tanrı gecelere yıldızlar koydu

Yıldızları söndürün,bir bir geceden

Perdeleri kapatın....Işıksız kalsın

Karanlığa, gark olunca geceler

Uzansın,güneşe bir haber salsın

Güneş,kırmaz geceyi sabaha gelir 

Sizdeki karanlık,biter geceler

Ne ay ne bir yıldız, girmez geceme

Bilmem, bu karanlık ne kadar sürer? 

Siyah benden içeri...Gecede değil

Yıldızsız her geceden daha siyahım

Gecelerin karanlığı. güneşle biter

Bendeki karanlık sürer geceler..', 'Renklerden geçtim,siyahı seçtim Bana benzeyen sadece o''ydu Geceler alsa da rengini benden Tanrı gecelere yıldızlar koydu Yıldızları söndürün...', ARRAY['Türk Edebiyatı','Şiir','Canan Karadağlioglu 2']::text[], 8.5, '{"poet":"Canan Karadağlioglu 2","poet_slug":"canan-karadaglioglu-2","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/geceler-107-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Balbadem/im*', 'balbadem-im-umit-koral-3i728', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hatırlarmısın balbademim derdim sana

Baldan da tatlı bademimdin

Sende bana kocacım derdin

Bir daha söyler ve söylerdim.

Çok özledim seni balım

BALBADEMİM...', 'Hatırlarmısın balbademim derdim sana Baldan da tatlı bademimdin Sende bana kocacım derdin Bir daha söyler ve söylerdim. Çok özledim seni bal...', ARRAY['Türk Edebiyatı','Şiir','Ümit Koral']::text[], 8.5, '{"poet":"Ümit Koral","poet_slug":"umit-koral","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/balbadem-im-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eylül', 'eylul-mehmet-marsan-vrz8s', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir dağ yamacına dökülür eylül

Bir ömür tükenirken kenarında akşamın

Sen öyle hep uzaklarda gül

Kirlenmiş zamanlardan kaçarak

Bir dağ yamacına dökülür eylül

Rüzgarın eteğini tutunca

Güngörmemiş sevdaları sor

Vakit diriliğince gül-gonca

Ellerin serilir şafaklara

Rüzgarın eteğini tutunca

Serçeler taşır ölümsüzlüğü

Girdabına yalnızlığın

Sevdalar taşır turna bölüğü

Ufacık kanatlarında

Serçeler taşır ölümsüzlüğü', 'Bir dağ yamacına dökülür eylül Bir ömür tükenirken kenarında akşamın Sen öyle hep uzaklarda gül Kirlenmiş zamanlardan kaçarak Bir dağ yamacı...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Marşan']::text[], 8.5, '{"poet":"Mehmet Marşan","poet_slug":"mehmet-marsan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/eylul-85-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşleyemiyorum', 'dusleyemiyorum-ayse-gul-asy19', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'D ü ş l e r i m e

e l

k o y d u n! ...

Y o k l u ğ u n u__d a

d ü ş l e y e m i y o r u m...

26/09/005 İst. A.G. Nisan_ca', 'D ü ş l e r i m e e l k o y d u n! ... Y o k l u ğ u n u__d a d ü ş l e y e m i y o r u m... 26/09/005 İst. A.G. Nisan_ca...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Gül']::text[], 8.5, '{"poet":"Ayşe Gül","poet_slug":"ayse-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/dusleyemiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bizim Ev', 'bizim-ev-adem-sirin-xivrd', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Mersin''den Adana''ya dogru

Dolmus ya da minübüs

her ne gidiyorsa artik

binecen

Dolmus amcaya sor

seni nato yolunda birakabilir mi? 

Nato yolunda birakabilirse

Seni Nato yolundaki mezarligin orada biraksin

Arap mezarligidir orasi

Mezarlikta indikten sonra, sirtini mezarliga dön

Sonra bir kac metre saga dogru yürü

Sonra yolun karsisina gec! 

Orasi toprak yoldur! 

O yolda etrafi camlarla cevrili,

büyük bahceli bir ev görecen! 

Evin önünde kocaman bir palmiye agaci

O agac belediye tarafindan korunmaya alinmistir.

Evin bir özelligi daha var:

kocaman, kahverengi renkte (Gartentor)  kapisi var 

bahceye ve avluya acilan! 

BIR DOSTUN HATIRALARI', 'Mersin''den Adana''ya dogru Dolmus ya da minübüs her ne gidiyorsa artik binecen Dolmus amcaya sor seni nato yolunda birakabilir mi?  Nato yolu...', ARRAY['Türk Edebiyatı','Şiir','Adem Sirin']::text[], 8.5, '{"poet":"Adem Sirin","poet_slug":"adem-sirin","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bizim-ev-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevişmek İstiyorum', 'sevismek-i-stiyorum-umit-koral-lfa1n', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sevişmek ikimiz içinde ayrı bir tutku

İkimizide uçuran, herşeyi unutturan bir duygu

Aynı yatağı paylaşmamız ise

Cehennem sıcağınıda geçiyordu

Biliyormusun  aşkım? 

Sevişmek istiyorum seninle

Saçlarını okşamak istiyorum saatlerce

Sarılmak istiyorum yıllarca boyununa.....

Nefessiz kalıncaya kadar,

Öpüşmek istiyorum tüm bedeninle...', 'Sevişmek ikimiz içinde ayrı bir tutku İkimizide uçuran, herşeyi unutturan bir duygu Aynı yatağı paylaşmamız ise Cehennem sıcağınıda geçiyord...', ARRAY['Türk Edebiyatı','Şiir','Ümit Koral']::text[], 8.5, '{"poet":"Ümit Koral","poet_slug":"umit-koral","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sevismek-istiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '**Pencere Önü Çiceği**', 'pencere-onu-cicegi-umit-koral-9b3v9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bekle bakalım kimleri göreceksin pencerende

Kimler sulayacak seni pencerenin önünde

Dışarıda havar nasıl kışa hazırlıyorsun değilmi kendini

Bensiz üşüyormusun yoksa oralarda

Kıyamam ben sana sevdiğim

Hiç kimseler bulamazsan eger,

Ben  gene sularım seni..', 'Bekle bakalım kimleri göreceksin pencerende Kimler sulayacak seni pencerenin önünde Dışarıda havar nasıl kışa hazırlıyorsun değilmi kendini ...', ARRAY['Türk Edebiyatı','Şiir','Ümit Koral']::text[], 8.5, '{"poet":"Ümit Koral","poet_slug":"umit-koral","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/pencere-onu-cicegi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gerçek Üzerine', 'gercek-uzerine-saint-ramos-5k1um', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Şayet “gerçek” kadın ise 

Bunu demiş bizim Niçe

Vay halimize gerçekse

Söylediği bizim Niçe

Şayet “gerçek” kadın ise 

Yanımızda “gerçek” yatar

Bizim filozoflar ise

“Gerçeği” kitapta arar

Şayet “gerçek” kadın ise

Bilmelisin ki o zaman

“Gerçeği” en az anlayan

Şüphesiz ki filozoflar

Şayet “gerçek” kadın ise

Böyle demiş bizim Niçe

“Gerçekten” en uzaktalar

“Gerçekleri” arayanlar', 'Şayet “gerçek” kadın ise  Bunu demiş bizim Niçe Vay halimize gerçekse Söylediği bizim Niçe Şayet “gerçek” kadın ise  Yanımızda “gerçek” yata...', ARRAY['Türk Edebiyatı','Şiir','Saint Ramos']::text[], 8.5, '{"poet":"Saint Ramos","poet_slug":"saint-ramos","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gercek-uzerine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düş Gezgini', 'dus-gezgini-guzin-eye-dundar-pka96', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Eşsiz bir güzellik çizdim

içine  saldım gün ışığını

her parmağım on renk

                              

bir düş gibi dokudum

                                 

sevdanın anlamını

                                     

sessiz  göl 

                              

kucaklarken ormanı

                              

alnında günün ışığı

                               

gözlerinde   hayat

                            

cennetten ölümsüz tat

                           

düş gezgini koydum adını..', 'Eşsiz bir güzellik çizdim içine  saldım gün ışığını her parmağım on renk                                bir düş gibi dokudum                ...', ARRAY['Türk Edebiyatı','Şiir','Güzin Eye Dündar']::text[], 8.5, '{"poet":"Güzin Eye Dündar","poet_slug":"guzin-eye-dundar","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/dus-gezgini-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aldanıyoruz', 'aldaniyoruz-nursen-buluc-tccbj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Geçti ömrüm, senin yolunda

Ağlıyor gönlüm, yanlızlığına

Sevdinmi, sevmedinmi beni

İnan, anlayamadım seni

Yüreklendim, sen kaçtıkca ben

İçimden bunu hiç istemeden

Nasıl geçti bunca zaman

Hiçbir anını unutmadan

Anlayanlar beni umursamıyor

Anlamayanlar ise, mutlu sanıyor

Dünyanın,düzeni buymuş işte

Kadınlar hep böyle aldatılıyor', 'Geçti ömrüm, senin yolunda Ağlıyor gönlüm, yanlızlığına Sevdinmi, sevmedinmi beni İnan, anlayamadım seni Yüreklendim, sen kaçtıkca ben İçimd...', ARRAY['Türk Edebiyatı','Şiir','Nursen Buluc']::text[], 8.5, '{"poet":"Nursen Buluc","poet_slug":"nursen-buluc","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/aldaniyoruz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olmaz mı...(deneme)', 'olmaz-mi-deneme-nedim-saatcioglu-893r5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'kırık bir tebessümün yarım kalan sesi gibisin kulağımda…eksik bir nota…yanlış bir rota…tutturulmamış bir kota gibisin hayatımda… … …

	…	 … 	…

	…	…	…

	bir güneş doğsa gönül sahilime ve bir sıcak nefes yalnızlık yorgunu  gözlerime… mumlar yakılsa tütsülenmiş kumlarda…kan izim kalsa baygın bir gecenin tedirgin nefesinde…tutsak etmesen anıları gözlerimde…hayat denen bir koyda, su sesine bıraksan kendini yeşil bir aydınlıkta…ince bir yağmur sesi,sırtına vursa taneleri,bir duvarın gölgesinde serin bir anı kalsa gözlerinde…fotoğraflar renkli çıksa ve sen silsen bakışındaki siyah beyaz desenleri…bir gökkuşağı bitirse içindeki özlemleri…yakın olsan bana, ama ulaşamasam, bir nefes kadar içimdeyken hem de…paylaşsam yokluğunda seni, yanımdayken tutamasam elini…kızsan bir otobüs yalnızlığında bıraksan kendini caddenin en uzun yoluna…koşsam peşinden, içimdeki öfkeyle kollarına sarılsam ve sen elimi tutsan… yasaklanmış bir aşkın son durağı olsan benim için… 

	olmaz mı…

	bir çocuk uyusa göğsümde ılık nefesiyle…kelimeler yaratsak ve cümleler kursak aşk adına yaşanmamış yanlarıyla…uykulu bir sabahın pas tutmuş ağız tadında…ne kadar uzak görünsem de sana, yüreğimde olduğunu bilsen,elini tutmasam da bir adım ardında olduğumu,ayağının takıldığı an, seni ilk tutan olacağımı bilsen…

	olmaz mı…

yaşamın en kırılgan anında yüreğimi düğümleyen bir an olsan… karanlığın en tortu anında tutsan ellerimi,hesap sormadan, beni yargılamadan ve aşk adına beni darağacına asmadan bana sarılsan… görebilsen yüreğimin arka bahçesinde sana diktiğim gülleri… görebilsen sensiz aç, sensiz susuz ve sensiz perişan kaldığım çölleri… görebilsen rüya diye baktığın, ama benim boğulduğum gölleri… 

olmaz mı…

içimdeki bütün kabus ağaçlarını kessen... hüzünlü bir eylül, yağmurlu bir nisan olmasa yüreğim…her sabah uyandığımda yastığıma bulaşmasa gözyaşımın kan izi…turuncu bir hayalim olsa pembe düşler üstüne ve beyaz gül demetleri olsa sahne ötesinde…sen ebruli bir gecede şiirler okusan bana deli düşler üstüne ve ben bir beyazlığın saydamlığını yaşasam mumlar içinde…kayıp gitmesem bir zaman tünelinde… hayatımda ilk defa ilk defa, dünü düşünmeden ve yarın için endişe duymadan yaşasam …ve takılmasa dilime her cümlenin sonunda… 

“ey hayat canımı acıtma artık”

olmaz mı…

olmaz mı…

olmaz mı…', 'kırık bir tebessümün yarım kalan sesi gibisin kulağımda…eksik bir nota…yanlış bir rota…tutturulmamış bir kota gibisin hayatımda… … … 	…	 … 	...', ARRAY['Türk Edebiyatı','Şiir','Nedim Saatcioğlu']::text[], 8.5, '{"poet":"Nedim Saatcioğlu","poet_slug":"nedim-saatcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/olmaz-mi-deneme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeter', 'yeter-elazigli-mustafa-kaya-wn3rh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Neyin var 

            Senin..? 

Her şeyin

            Ve

               Hiç bir şeyin..! 

Beni sevmeden gittin

                       Sevgimi ittin..

Biraz…

           Bir kez güzel bak

                               Yeter o bana … 

                                                         16.05.2005 / Ankara

                                                          Mustafa kaya

                     

www.mustafakaya.net', 'Neyin var              Senin..?  Her şeyin             Ve                Hiç bir şeyin..!  Beni sevmeden gittin                        Sevgi...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yeter-52-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayalimde hep sen varsın', 'hayalimde-hep-sen-varsin-elazigli-mustafa-kaya-6df0q', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'görünmez bir mutluluk

tanımak seni

hayallerime taşıyorum

beni bekliyorsun sahilde

avutulmuş çocuklar gibiyiz

salacakta ikimiz

geldin ya 

ellerin ellerimde..

ve aylardır görmedim yüzünü

canım benim

güzel yüzlüm

çiçeğim..biriciğim

yasakları kaldırdım

bu hayalimde.

ve dönüyor 

akşamlar geceye

ışıl ışıl şehir

karşımızda kız kulesi

serin eylül akşamında 

ellerinle büyüt beni..

içindeki çocuğu güldürebilmek

sevinçlerle seni,

utangaç ruhumun 

en güzel hediyesi..

ölümcül göğe inat

çiseleyen yağmur sıcaktı

derin bir İstanbul

gözlerinin kahvesi..

alıp her gece 

hayalime seni böyle

ateşleri içime atıp

gidiyorsun

iz bırakarak yüreğimde…

Mustafa kaya

27.09.2005 / salacak

www.mustafakaya.net', 'görünmez bir mutluluk tanımak seni hayallerime taşıyorum beni bekliyorsun sahilde avutulmuş çocuklar gibiyiz salacakta ikimiz geldin ya  ell...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/hayalimde-hep-sen-varsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'S e s i m i i ç e c e ğ i m...', 's-e-s-i-m-i-i-c-e-c-e-g-i-m-zafer-zengin-etnika-blgy5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sesimi içeceğim

Öyle ya; 

Bir şiirle ölmezdik biz

Kelimelerde kurşun olmasa

Sivriltmesen ucunu kalem traşla

Gelecekse ölüm buraya

Buyursun iki kaşın ortasına

| Yanlış anlaşılırdı aşk.. bu yüzden dostu olmazdı

karşılıksız sevdikçe görevi olurdu adamın, kadının sevda

Yaprak toplamayı en iyi rüzgar bildiği halde

çöpçülere iftiralar atarlardı

aşık olmuş çöpcü görülmezdi varoşlarda

oysa çöpler çocuk oyuncağı hala |

Öyle ya; 

Bir lafla ölmezdik biz

Konuşanın ağzında mavzer olmasa

Yivine setine nefret bağlanmasa

Gelecekse ölüm buraya

Buyursun iki kemiğin ortasına 

| Kırdın bizi elimizden ilk sevdamızı aldığında

çoktandır unuttuk dönüp dolaştık yıllarca

onu aradık bu şehrin süslü sokaklarında

ne zaman meydanlara çıksak gözlerimiz havada

çok insan gördükçe, bıraktık aşkı aramayı da

seçme şansı var mıdır söyle.. yanan eli suya tutmakta

kar yağmaz.. kar bulmak zor buralarda.. o gidince kaldık soğukta

..gör hayrını.. dua bilmez sözlerimizde..sen yaklaş tanrıya.. 

yalnız bırak bizi şehrin ortasında |

Öyle ya; 

Hasrete kitap dayanmaz

Üç beş satır mektup

Ağlayan çocuğa elma şekeri

Yas biraz

Biraz dua

Tanrıya yakın olmasa da

Gelecekse ayrılık buraya

Buyursun yüreğimizin ortasına

Öyle ya; 

Her mevsim ölmek kolay

Baharı bekler illa eller

Ölürken çocuk güleceğim

Susar dünyam

Sesimi içeceğim

İç’im ince hastalık

hüzünle gelir bilirim

Kızarmış burnum

üşür umudum

Söyle neyle avutayım yüreğimi

Nasıl ısıtayım gecenin dizlerini 

29 11 2004  '' Adamına sevdalar ''', 'Sesimi içeceğim Öyle ya;  Bir şiirle ölmezdik biz Kelimelerde kurşun olmasa Sivriltmesen ucunu kalem traşla Gelecekse ölüm buraya Buyursun i...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":50,"source_url":"https://www.antoloji.com/s-e-s-i-m-i-i-c-e-c-e-g-i-m-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Su tutmaz a t e ş...', 'su-tutmaz-a-t-e-s-zafer-zengin-etnika-txu3f', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kendini yakar ağaç

Biçilir

Şekillere sokulur istemeden

Motif eder usta eller

Sıcağında kurulur sevda

Bekler yangını yangını

Ateş değer

Ten ılınır

Sancı kastıkça eti

Et keser kendini

Acımı anla diye

Fırlatır kendini ötekine

Barut hakkı yoktur

Ateş fitiller kendini

Yakar hazır  içleri

Su tutmaz ateş

Kül sarar ıslağı

Fırlarsın  tutunduğun gülden

Patlar muz sürgünlerde

Nardan yan

Gülü yak

Ölüm birlikte şimdi

Geç gidene yalnızlık yok

Erken gidenden haber

Tutunsak sıcaktı kavuşmamız...

27 11 2004 

Ahşap ev yangınlarında, ahşapların çakıldığı

çiviler sıcağın etkisiyle fırlar başka evlere saplanır

söndürülmesi zor köy ya da mahalle yangınlarına dönüşür derler.

Araştırılma ilginç bir konu.', 'Kendini yakar ağaç Biçilir Şekillere sokulur istemeden Motif eder usta eller Sıcağında kurulur sevda Bekler yangını yangını Ateş değer Ten ı...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/su-tutmaz-a-t-e-s-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Başka Türlü Bir Cesaret İstiyor', 'ask-baska-turlu-bir-cesaret-i-stiyor-melih-coskun-s0dvf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Aşk başka türlü bir cesaret istiyor. 

Ne savaştaki yiğitliğe benziyor 

Ne de karanlıkta 

Islık çalmadan yürüyebilmeye. 

Aşk başka türlü bir cesaret istiyor. 

Dizlerin titremeden, 

Damağın kurumadan konuşabilmeye

Ne yiğit bir türküye benziyor 

Ne de bir şafak vakti 

Herkesi ve herşeyi bırakarak ardında 

Çekip gidebilmeye

Güneşin doğduğu yere…

2005', 'Aşk başka türlü bir cesaret istiyor.  Ne savaştaki yiğitliğe benziyor  Ne de karanlıkta  Islık çalmadan yürüyebilmeye.  Aşk başka türlü bir ...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ask-baska-turlu-bir-cesaret-istiyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arama Beni', 'arama-beni-kemal-tahir-ozcan-4ats4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Duydukça sesini,ürperiyorum,

Ne olur bir daha, arama beni.

Seni unutmaya, söz veriyorum,

Ne olur bir daha, arama beni.

Çırpınır yüreğim, hiç laf dinlemez,

Gururdan,onurdan, durdan anlamaz,

Beni mecnun eden, tatlı yaramaz,

Ne olur bir daha, arama beni.

Kaybolup gideyim, karanlıklarda,

Yağmurlar ıslatsın, donayım karda,

Öldüğümü duysan, öte diyarda,

Ne olur bir daha, arama beni.', 'Duydukça sesini,ürperiyorum, Ne olur bir daha, arama beni. Seni unutmaya, söz veriyorum, Ne olur bir daha, arama beni. Çırpınır yüreğim, hiç...', ARRAY['Türk Edebiyatı','Şiir','Kemal Tahir Özcan']::text[], 8.5, '{"poet":"Kemal Tahir Özcan","poet_slug":"kemal-tahir-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/arama-beni-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ateşin Küllenmeli! ! !', 'atesin-kullenmeli-hikmet-feridun-demir-refvu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seni istemez olurmuyum, 

yudum yudum içmek isterim seni. 

Ellerim her yerinde dolaşmalı..

En ücra yerlerine,

değmeli parmaklarım. 

Islak teninde dolaşmak senin, 

özlemlerini en güzeli olmalı..

ateşin küllenmeli, 

yeniden,

yeniden, 

yeniden...,

Yangın  yaratmak üzere…

Köln / 26.09.2005', 'Seni istemez olurmuyum,  yudum yudum içmek isterim seni.  Ellerim her yerinde dolaşmalı.. En ücra yerlerine, değmeli parmaklarım.  Islak ten...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Feridun Demir']::text[], 8.5, '{"poet":"Hikmet Feridun Demir","poet_slug":"hikmet-feridun-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/atesin-kullenmeli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidenlerin Ardından', 'gidenlerin-ardindan-ayse-gul-3iwg3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir zamanlar

göğsümüze takdığımız yıldızlar

hasreti bize bırakıp ruhlarını göğe astılar...

Rüzgar okşamıyor hüznümüzü artık.

Anılar gelince akla

hasretimize iyot basıyoruz

deniz, deniz...

Şimdi yalnızlığın kolunda dolaşırken sahil boyu; 

Bulutsuz, rüzgarsız, çığlıksız 

bir dünyada

kanadı kırık

martılar biziz...

27/09/005 İst. A.G. Nisan_ca', 'Bir zamanlar göğsümüze takdığımız yıldızlar hasreti bize bırakıp ruhlarını göğe astılar... Rüzgar okşamıyor hüznümüzü artık. Anılar gelince ...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Gül']::text[], 8.5, '{"poet":"Ayşe Gül","poet_slug":"ayse-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gidenlerin-ardindan-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözyaşları! ! !', 'gozyaslari-hikmet-feridun-demir-6ddsv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gözyaşları güzeldir,

insanın ruhunu temizler..

Duygular,

olumlu,

yada olumsuz, 

hep yaşamda var olacaktır..

Bunu bilerek yaşamak 

Yaşamı anlamak demektir.

Wermelskirchen / 20.09.2005

Almanya', 'Gözyaşları güzeldir, insanın ruhunu temizler.. Duygular, olumlu, yada olumsuz,  hep yaşamda var olacaktır.. Bunu bilerek yaşamak  Yaşamı anl...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Feridun Demir']::text[], 8.5, '{"poet":"Hikmet Feridun Demir","poet_slug":"hikmet-feridun-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/gozyaslari-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocukca', 'cocukca-salim-erben-bwb55', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Küçükmüşüm cadılara sadece 

masallarda raslanır sanırdım....

Sokulmuşum babama,

babamın hepsinden güçlü 

olduğuna inanmışım...

yıllar geçmiş aradan..

bir bakmışım bende cadıymışım..

masumlar masallarda...

babamsa hala kızının peşindeymiş,

cadı onun olduğundan habersizmiş...

 kayıt cadı kız', 'Küçükmüşüm cadılara sadece  masallarda raslanır sanırdım.... Sokulmuşum babama, babamın hepsinden güçlü  olduğuna inanmışım... yıllar geçmiş...', ARRAY['Türk Edebiyatı','Şiir','Salim Erben']::text[], 8.5, '{"poet":"Salim Erben","poet_slug":"salim-erben","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/cocukca-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ozaman Beni Hatirla...', 'ozaman-beni-hatirla-haci-murat-ates-ow0ua', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir gun aci cekersen 

Aradigini bulamazsan 

Onunla mutlu olamazsan 

Ozaman Beni hatirla... 

Aglayipda kahrolursan 

Geceleri yatamazsan 

Ona katlamazsan 

Ozaman beni hatirla.... 

Eger hayata kusersen 

Pes edipde gidersen 

Bir gun isyan edersen 

Ozaman beni hatirla.... 

Gun gelirde beni ararsan 

Ben diye resmime bakarsan 

Bos yatakda yastiga sarilirsan 

Ozaman beni hatirla... 

Neden diye kendine sorarsan 

Ben neyaptim deyip kahrolursan 

Eger pisman olursan 

Ozaman beni hatirla.... 

Bir gun geri gelirsen 

Gel benimle ol dersen 

Pismanim beni affet dersen 

Ozaman Gittigin gunu hatirla...', 'Bir gun aci cekersen  Aradigini bulamazsan  Onunla mutlu olamazsan  Ozaman Beni hatirla...  Aglayipda kahrolursan  Geceleri yatamazsan  Ona ...', ARRAY['Türk Edebiyatı','Şiir','Haci Murat Ates']::text[], 8.5, '{"poet":"Haci Murat Ates","poet_slug":"haci-murat-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ozaman-beni-hatirla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel artik ALI''M...', 'gel-artik-ali-m-haci-murat-ates-1upp3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ali''m sen gittin gideli buralar soguk 

Disarda kar var usuyorum ALI''M 

Gel durma orda kac kurtul cabuk 

Tek basima burda bitiyorum ALI''M. 

Ailem kendin sevdin kendin ettin diyor 

Zor gunler geciriyorum ben burda ALI''M 

Ne kadar dayanabilsemde zoruma gidiyor 

Onlarin dilinden gel kurtar ALI''M. 

Bir kac kisi elini bana yardim icin aciyor 

Kadin basima sensiz neyaparim ALI''M 

Biri iyi bakiyorsa biri kotu bakiyor 

El diline beni dusurme gel artik ALI''M. 

Namusum hayatim canim cigerimsin 

Gozumun nuru candamarimsin ALI''M 

Yurudugum yolum evimde diregimsin 

Evimi viraneye cevirme yikma beni ALI''M. 

Aldilar goturduler seni uzak yerlere 

Bir caresini bulda kac kurtul ALI''M 

Yagmur oldu gozyaslarim isyanim kadere 

Sel olan gozyaslarima kapilda gel ALI''M. 

Ben burda bekliyorum biraktigin yerdeyim 

Olumden bile artik korkmuyorum ALI''M 

Hayata seninle basladigim kucuk evdeyim 

Omurum bitene kadar seni bekliyorum ALI''M. 

Haci Murat Dostum yazmis bu siiri sana 

Sana en derin saygilarini iletiyor ALI''M 

Sen yoK oldun olali yardim ediyor bana 

Bir baci kardes gibiyiz sen korkma ALI''M. 

Allah kimseye aci keder vermesin.. 

Bu siiri sana yazdim candostum allah ALINE seni cabucak kavustursun..', 'Ali''m sen gittin gideli buralar soguk  Disarda kar var usuyorum ALI''M  Gel durma orda kac kurtul cabuk  Tek basima burda bitiyorum ALI''M.  A...', ARRAY['Türk Edebiyatı','Şiir','Haci Murat Ates']::text[], 8.5, '{"poet":"Haci Murat Ates","poet_slug":"haci-murat-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/gel-artik-ali-m-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Durma Git Gideceksen...', 'durma-git-gideceksen-haci-murat-ates-yt8rc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yanimda degilsin zaten benle olsan 

Boyle beni her gun yikacaksan 

Her gunumu zindan edeceksen 

Hadi neolur, Durma git gideceksen.. 

Zorla sevdirememki kendimi 

Yalvarsamda yolunu secmissin sen 

Boynumu bukup affet beni dersem 

Bakma geriye, Durma git gedeceksen.. 

Varligin zaten bir gun guldurmedi beni 

Ne denesem isteksizdin hep sen 

Onemlimi benim nekadar sevdigim seni 

Dusunme beni, Durma git gideceksen.. 

Haci Murat kusmustu zaten hayata 

Durma vur hanceri vuracaksan 

En guzel mutluga er gonlunce yasa 

Hadi git gulum, Git gideceksen...', 'Yanimda degilsin zaten benle olsan  Boyle beni her gun yikacaksan  Her gunumu zindan edeceksen  Hadi neolur, Durma git gideceksen..  Zorla s...', ARRAY['Türk Edebiyatı','Şiir','Haci Murat Ates']::text[], 8.5, '{"poet":"Haci Murat Ates","poet_slug":"haci-murat-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/durma-git-gideceksen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yagmurlu Sokaklar...', 'yagmurlu-sokaklar-haci-murat-ates-xp34m', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yagmurlu sokaklar... 

Bir sonbahar yine geldi geciyor 

Havalar soguk, dusen yapraklar 

Etrafi islak sularda yuzuyor 

Bir tane sigaram kalmis 

Icmeye korkuyorum 

Aslinda yeni bir paket 

Gidipde almaya eriniyorum 

Sen gittin gideli 

Iki paket sigaraya cikardim 

Gunluk kullandigim sigarami 

Sanki tadi yok gibi 

Ama aliskanlik bu benimki 

Sen yoksun yanimda 

Sanki o beni anlar gibi 

Ozlemini az da olsun 

Icimden cikarip atar gibi 

Yagmurlu sokaklar... 

Her taraf islak 

Ayni yuregimdeki sevdan gibi 

Gozyaslarimla 

Dinmeyen gozyaslarimla 

Senin icin aglayip 

Tukenmeyen gozyaslarim gibi 

Baksana gokyuzu bile agliyor 

Ben senin icin agladim 

Gokyuzu benim icin agliyor 

Yagmurlu sokaklar... 

Bom bos bir ben 

Bir tane sigaram 

Bir de gokyuzunden dokulen 

Birer birer yagmur damlalari 

Yagmurlu sokaklar.... 

Siril siklam islandim 

Goren deli diyor 

Bana gulup geciyor 

Ama ben senin hasretinle yaniyorum 

Yagmur yagsa ne fayda 

Sel olup alip goturse 

Korkmuyorum 

Artik istemiyroum sensiz dolasmayi 

Bu yanliz sokaklarda 

Her taraf islak 

Ayni sana hasret yuregim gibi 

Yine aksam oldu 

Sensiz yeni bir aksam 

ve yine 

Yagmurlu sokaklar...', 'Yagmurlu sokaklar...  Bir sonbahar yine geldi geciyor  Havalar soguk, dusen yapraklar  Etrafi islak sularda yuzuyor  Bir tane sigaram kalmis...', ARRAY['Türk Edebiyatı','Şiir','Haci Murat Ates']::text[], 8.5, '{"poet":"Haci Murat Ates","poet_slug":"haci-murat-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/yagmurlu-sokaklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Istemedin...', 'sen-istemedin-haci-murat-ates-xdiua', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Suc sende degil bende sevgilim 

Sana istedigini veremedim ben 

Zengin olan birtek benim gonlum 

Onuda maalesef istemedin sen.. 

Iki odali bir evim var vazlasi yok 

Hic supen olmasin benim sevgimden 

Tertemiz duygularim var verecek 

Onuda maalesef istemedin sen... 

Suc bende, yukseklere kondum 

Kanadim kirilmaz ucarim sandim 

Ama bir poyraz esdi yere cakildim 

Ve sana laik degilim bunu anladim... 

Git sen seviyende olan birini bul 

Benim gibi garibanla olmasin isin 

Bir sans verseydin olurdum sana kul 

Onuda maalesef sen istemedin...', 'Suc sende degil bende sevgilim  Sana istedigini veremedim ben  Zengin olan birtek benim gonlum  Onuda maalesef istemedin sen..  Iki odali bi...', ARRAY['Türk Edebiyatı','Şiir','Haci Murat Ates']::text[], 8.5, '{"poet":"Haci Murat Ates","poet_slug":"haci-murat-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sen-istemedin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yârin Aşkı', 'y-rin-aski-atilla-gozukucuk-5mjnw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'O yarin aşkı ile, yüreğin yanar da kavrulursa,

Ömrün boşa geçer de; harman olup savrulursa,

Sen sever isen; sevdiğin de senden ayrılırsa,

Ömrün boş hayallerle, avunur o zaman.

Gurbet ele gider de gelemezsen,

Göz yaşların akar da silemezsen,

Leyla Mecnun gibi, muradına eremezsen,

Yarin aşkı ile, kavrulursun o zaman.

Kerem Aslı misali, aşkı gurbette ararsan,

Aşk ateşine düşüp de; hayali ile yanarsan,

Sevip sevip de, boş hayallere kanarsan,

Ömrün harman olur, savrulur o zaman.

Yar dediğin, kıymetini bilmeli,

Seninle ağlayıp, seninle gülmeli,

Başın derde düşerse, koşup gelmeli,

Yarin aşkı ile yaşarsın o zaman.

27.09.2005', 'O yarin aşkı ile, yüreğin yanar da kavrulursa, Ömrün boşa geçer de; harman olup savrulursa, Sen sever isen; sevdiğin de senden ayrılırsa, Öm...', ARRAY['Türk Edebiyatı','Şiir','Atilla Gözüküçük']::text[], 8.5, '{"poet":"Atilla Gözüküçük","poet_slug":"atilla-gozukucuk","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yarin-aski-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umutlarımı Caldılar...', 'umutlarimi-caldilar-haci-murat-ates-2f463', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hayatimdan umutlarimi caldilar 

Donupde goturmeyin demedim 

Birer birer hayellerimi yiktilar 

Inan onu bile onemsemedim.. 

Ayagima celme takip yiktilar 

Ondan sonra oturupda baktilar 

Hani benim arkadaslarim coktular 

Bir gun olsun dostlarimi gormedim... 

Bir oksuzun neyi olur hayatta 

Bir dilim ekmek kokmus yumurta 

Gozum yok san sohret varlikta 

Bir gun olsun haram para yemedim.. 

Haci Murat Ates hep kotu bilindi 

Yaptiklari iyilikler cabuk silindi 

Neyi varsa kendinin degil elindi 

Bir gun olsun benim bile demedim.. 

Dunya sizin olsun yoktur gozumde 

Dinim imanim bir tek sozumde 

Allah sevgisi eksik olmaz gonlumde 

Bir gun olsun Kotuluk nedir bilmedim...', 'Hayatimdan umutlarimi caldilar  Donupde goturmeyin demedim  Birer birer hayellerimi yiktilar  Inan onu bile onemsemedim..  Ayagima celme tak...', ARRAY['Türk Edebiyatı','Şiir','Haci Murat Ates']::text[], 8.5, '{"poet":"Haci Murat Ates","poet_slug":"haci-murat-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/umutlarimi-caldilar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir sayı tut', 'bir-sayi-tut-hekim-coskun-vhuwz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'birincisi; 

seni seviyorum.

nerden çıktın sen? 

sitemim sana değil zamana

seni bana yazana.

reyhan kokulu yarim

ve yarim,

yarın akşam yine bu vakitlerde

aynı duygu ve düşünceler içersinde

ülkemin  içinde bulunduğu inkarın

imhanın

yalan ve talanın ortasında

bir kavgada

seni sevdiysem

ve seni düşünüyorsam

saçlarını okşamak için 

kereler-kereler

milyon kereler…

seni sevdim ben.

somut çelişkilerimde özgül niteliğimsin

seni evrenselimden ayırtmadım ben.

sen aşkımsın,

sevdamsın.

seni tüm ötekilerden önemli kılan

anlaşılıyor olmandır.

sen varsın bende; 

duygu ve istemlerin, fikirlerin

yani düşünsel her şeyinle sen

her şeyimsin.

gerçek olanla arzularım arasında

bir ölçüsün sen

ben bu gün yalnız değildim

senin kanatlarında uçtum okyanuslara

iki kere-iki dört eder mi? 

kereler-kereler

milyon kereler

seni sevdim ben.

bir sayı tut

ikincisi:

seni seviyorum.', 'birincisi;  seni seviyorum. nerden çıktın sen?  sitemim sana değil zamana seni bana yazana. reyhan kokulu yarim ve yarim, yarın akşam yine b...', ARRAY['Türk Edebiyatı','Şiir','Hekim Coşkun']::text[], 8.5, '{"poet":"Hekim Coşkun","poet_slug":"hekim-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/bir-sayi-tut-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül Yanakların', 'gul-yanaklarin-fikret-kanat-fpti7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'güzel yüzünden eksilmesin neşe 

böyle daha güzel gül yanakların

sevdiğim ne olur çıkma güneşe 

gün vurup yanmasın al yanakların

beni benden aldı sade bir sözün

benden başkasını görmesin gözün

güzelim yüzüne yakışmaz hüzün

yazık ıslanmasın sil yanakların

binlerce şükretsem az yaradana

nur yüzlü bir melek yarattı bana 

ne kadar öpsem de doyamam sana

şekerden tatlıdır bal yanakların.', 'güzel yüzünden eksilmesin neşe  böyle daha güzel gül yanakların sevdiğim ne olur çıkma güneşe  gün vurup yanmasın al yanakların beni benden ...', ARRAY['Türk Edebiyatı','Şiir','Fikret Kanat']::text[], 8.5, '{"poet":"Fikret Kanat","poet_slug":"fikret-kanat","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gul-yanaklarin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İhanet', 'i-hanet-metin-yalti-6kr87', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dün yazdığım şiirde 

Yakınmıştım size 

Kavramı bilmeyince 

Şiirde anlatmak zor diye 

Diyor ki Eser 

Şiir bilmediği topraklarda da eser. 

Olmaz başka bir sebebi 

Eminim öğrenmemi istedi 

Hemen ertesi 

Duygularıma karşıydı eylemi 

Dağ dağa kavuşmaz 

İnsan insana kavuşur, derler. 

Konu dostluk ve sevgi. 

Siz ne dersiniz peki? 

Sevmek ve dostluk için 

Gereken görüşmek mi? 

Göze değil, gönüle düşer sevda 

Bunu yazar, bunu söyler şiirler 

İnsana birini 

Yazdıkları ve söyledikleri 

Yazmadıklarını da okuyunca 

Tanıtmaya yetmez mi? 

Her şey incelikten 

İnsan kabalıktan kırılır derler 

Ona demiştim ki 

Beni tanırsın okursan şiirimi.. 

Olmamış olmalı yeterli 

Başka yollar denedi… 

“İnsan insanın kurdudur”, 

Belki de bu yüzden derler 

Art niyet taşımamalı sevgi 

“O mavi gözlü bir devdi 

Minnacık bir kadın sevdi” 

Şiirinde Nazım’ın anlattığı ihanetti 

26,9,2005  İst', 'Dün yazdığım şiirde  Yakınmıştım size  Kavramı bilmeyince  Şiirde anlatmak zor diye  Diyor ki Eser  Şiir bilmediği topraklarda da eser.  Olm...', ARRAY['Türk Edebiyatı','Şiir','Metin Yaltı']::text[], 8.5, '{"poet":"Metin Yaltı","poet_slug":"metin-yalti","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/ihanet-67-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasretin dağlar kadar', 'hasretin-daglar-kadar-ercan-akbay-04otw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hasretin dağlar kadar

            Aşsam desem aşamam

            Gönlüme hüzün dolar

            Atsam desem atamam

            İşte ben hep böyleyim

            Sensiz ömrü neyleyim

            Sızlar durur yüreğim

            Derman desem bulamam

            Gözümde tüter oldun

             Varsam desem varamam

            Yoluna bakar oldum

            Yansam desem yanamam...

                             BESTE..İSMAİL DEMİRKIRAN

                             MAKAM..EVİÇ   TRT NO.12165

                             BESTE..SUPHİ İDRİSOĞLU

                             MAKAM..M.KÜRDİ  TRT NO..12947

                             BESTE..SEDAT ERDOĞDU

                             MAKAM..NİHAVENT TRT NO..18276

                             BESTE..RAİF SOMER

                             MAKAM..SEGAH  TRT NO..13786', 'Hasretin dağlar kadar             Aşsam desem aşamam             Gönlüme hüzün dolar             Atsam desem atamam             İşte ben hep...', ARRAY['Türk Edebiyatı','Şiir','Ercan Akbay']::text[], 8.5, '{"poet":"Ercan Akbay","poet_slug":"ercan-akbay","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/hasretin-daglar-kadar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki Tel', 'i-ki-tel-nazan-i-zmirli-ndhpx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bilirmiydim

tutsakken karanlıklara yüreğim

şafaklara hasret gözlerim

kulağım,umudu kırık  dalganın tınısında

İki tel

parmaklık arasında

İnce sızılara gebeyim.

kanat çırpışlarının,guguklu saatim

bakışlarının,  müebbetimin

vazgeçilmezi  olacağını

Bilirmiydim.

.................vazgeçilmezimsin 

gönül penceremde...............

Sen değilmiydin

umutlarıma kar yağdığında

buzdan camımı tıklayan

sen değilmiydin

sıtmalar tuttuğunda

ter kokan,toz kokan şiltenin altında

İki tel arkasında

ak kanatlarınla

düşmüş kaşlarımı kaldıran

Nazan İzmirli-18.09.2005-antalya', 'Bilirmiydim tutsakken karanlıklara yüreğim şafaklara hasret gözlerim kulağım,umudu kırık  dalganın tınısında İki tel parmaklık arasında İnce...', ARRAY['Türk Edebiyatı','Şiir','Nazan İzmirli']::text[], 8.5, '{"poet":"Nazan İzmirli","poet_slug":"nazan-i-zmirli","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/iki-tel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşklar', 'asklar-nazan-i-zmirli-s0xng', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Akşam alacası sarmış

toprak çatılara

bir an yok olmuş yaşam

tütmese tandırdan çıkan duman da

Var görünen yaşamlarda

sönmüş ocaklar  tatsız.

yok görünsede yaşam,

akşam   alacasında 

yaşanır sıcak  ocak başında  tadılan 

AŞKLAR'' da.....................................

03.09.2000ntalya', 'Akşam alacası sarmış toprak çatılara bir an yok olmuş yaşam tütmese tandırdan çıkan duman da Var görünen yaşamlarda sönmüş ocaklar  tatsız. ...', ARRAY['Türk Edebiyatı','Şiir','Nazan İzmirli']::text[], 8.5, '{"poet":"Nazan İzmirli","poet_slug":"nazan-i-zmirli","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/asklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Giz', 'giz-sevim-turkoglu-2kzq7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Irmak ki, 

dibinde göründü gözler... 



ışıldayan berraklığında 

sıralandı akışına, 

kursağın hevesinde 

kalan dilekler... 

kirpiklere sürülen 

gülümsemelerin ucunda sesleniş... 

durdu akan sular 

duruldu kare kare yansımada 

su üstünde imgeler, 

çekildi düşler tek tek 

sergiye serildi dizeler... 

hiç bir suç 

işlenmez ya hani, 

iz bırakmaksızın... 

dinledim şiirin ezgisini 

asil bir öykünün 

bilinen gizinde...', 'Irmak ki,  dibinde göründü gözler...  ışıldayan berraklığında  sıralandı akışına,  kursağın hevesinde  kalan dilekler...  kirpiklere sürülen...', ARRAY['Türk Edebiyatı','Şiir','Sevim Türkoğlu']::text[], 8.5, '{"poet":"Sevim Türkoğlu","poet_slug":"sevim-turkoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/giz-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmek Sanattır....', 'sevmek-sanattir-i-brahim-ozgan-v10te', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sevmek sanattır

Gozlerı askın resmını cizmektir

Rengarenk bakışlara 

Ve bakışlara bir guvercının kanat cırpınısını saklamaktır

Algılamaktır sevmek

Sardunyalardaki gizli güzelliği

Gormek gibi

Dikenler arasında bir gülü anlamak gibi

Bir yudumda bin kere tatmak gibi aşkı

Sevmek neşedir

Fıkralara gulmektir beraberce

Dans etmektir aynı şarkı altında

Ve kalbin kıpır kıpır oluşudur

Karşılıklı duyulan seslerde

Sevmek bağlanmaktır

Her anında yasatmaktır sevgılıyı

Sıcaklığını hissetmektir

Zorluklara katlanmaktır beraberce

Ve bir sarhoş edasıyla asmaktır her bir engeli

Ve ona giden her bir yolu kabullenmektir içinde

Sevmek sanattır….

       2000 aydın', 'Sevmek sanattır Gozlerı askın resmını cizmektir Rengarenk bakışlara  Ve bakışlara bir guvercının kanat cırpınısını saklamaktır Algılamaktır ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Özğan']::text[], 8.5, '{"poet":"İbrahim Özğan","poet_slug":"i-brahim-ozgan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sevmek-sanattir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin İçin', 'senin-i-cin-i-brahim-ozgan-j28yr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gönlümün kuşları senin için,

havalanır

Dokunmadan çiçeklere gül bahçelerine bile

Sana doğru süzülür.

Gönlümün kuşları senin için havalanır,

Gökyüzünde yıldızlarla arkadaş,

Bulutlarla dost ay la kardeş olup,

Sana doğru süzülürler,hep birlikte

Hep birlikte seni selamlarlar.

Işık hüzmeleriyle,

Gönlümün kuşları senin havalanır

Çiçek tarlalarında arılarla,

Dağ başlarında kırlangıçlarla,

Gül bahçelerinde kelebeklerle

Sana koşarlar el ele,

Gönlümün kuşları senin için havalanır,

Yaz yağmurlarıyla yaren

Zehmeri güneşiyle paydaş,

Bahar kokukarıyla özdeş

Seni kucaklarlar

Gönlümün kuşları senin için havalandı yine,

Yürüdüğümüz yollara baktık.Gecenin içinde beraberce

Bir ışıga takıldı gölerimiz,

Seni gördük..

Gökyüzüne çevirdik sonra gözlerimizi,

Sen vardın yıldızlar arasında en parlak olan,

Ve ay’da senin gülümseyişini sezdik

Sonra aklımızdan geçenleri, hislerimizi

İki satıra sığdırdık.

Gönlümle beraber.

Sana uzattık hepsini,

Yetmez diye sonuna ünlem koyduk..ve üç nokta.

Çünkü yetmedi.

Gönlümden havalanan kuşların,

Seni gördüğü ve selamladığı..

        2000 aydın', 'Gönlümün kuşları senin için, havalanır Dokunmadan çiçeklere gül bahçelerine bile Sana doğru süzülür. Gönlümün kuşları senin için havalanır, ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Özğan']::text[], 8.5, '{"poet":"İbrahim Özğan","poet_slug":"i-brahim-ozgan","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/senin-icin-127-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Çöl Hikayesi', 'bir-col-hikayesi-i-brahim-ozgan-gy9xo', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bır coldeyim! ..

Ruzgarın savurdugu kum tanelerı

Yuzume ve gozlerıme carpıyor

Bır coldeyım 

Susuz ve pejmurde

Dudaklarım catlak, kupkuru

Hasretım; bır yudum suyadır

Beklıyorum oyle caresız

Bır coldeyım! ..

Leylamı beklıyorum 

Aklanlar içinde ayaklar yalın

Umutlarımla gelecek 

Bır damla suyla beraber,

Ve uyandıracak benı derın suren uykudan

Sonsuzluk onumde acılacak

Ve dız cokecek onumde caresızlık

Sonra, sonra umursamayacagım

Hıcbırseyı hıc kımseyı ve hayatı

bir coldeyım! ..

Ruyamı anlattım sıze

Ve arzularımı, umutlarımı, arzuladıgımı

Ve sıze anlatıyorum, hey! turnalar

Gulmeyın halıme

Sız kırlangıclar; ucup durmayın uzerımde 

Ve akbabalar, kartallar, atmacalar

Beklemeyın olulmumu, olmemide

Ben sırrıma kavusuncaya dek olmeyecegım

Ve gormeden gozlerını yarın,

Kapanmayacak gozlerım

Kalbım durmayacak bılıyorum

Tenını hıssetmedıkce tenımde

Iste hepınıze bu naram! ..

Duyun duyun vazgecın

Cunku ben, ne engeller astım

Ne coller geçtim bunun gıbı

Ne yagmurlar ne dolular gordu

Bu perısan halım

Beklemeyın bosuna

Hepiniz, hiçbiriniz

İşte ben bekliyorumya! 

İste buradayımya hala

Sırnaşıp durmayın

Ve bakmayın, nacar,nacar

Zormu dıyorsunuz? 

Evet zor, zor ama

Butun dehsetlerımın sonuda bu zaten

Umut dedıkya,

Umutsuzlukla ısım ne benım

Umutlarla yasarım ben

Yarının ve bır sonrakı anın umutla,

Kavusmakla umutla

Ah! bır bılsenız kavusmanın sehvetını

Bır anlayabılsenız benı

Haydı sızlere elveda

Ben boyleyım iste

Ama yakındır zaman 

Yakındır kavusmak goreceksınız

Dagılacak karabulutlar uzerımızden

Sızlerede duam

Cıkacagım aydınlıga

Islatacak dudagımı bır yudum su

Sevgi bu, aşk bu

Asırlarda surse beklerım onu

Coldeyim! 

O meleği, o ceylan bakıslıyı

Uzaklardanda olsa bekleyecegım

O benım melegim, hem ceylanım

O benın zaferım, sevıncım

Corak topraklarda acan tek gulum

Yani o benım can damarım

Iste sıze bu kadar

Ve gelecek, gelecek yarına kadar.

                  2000 aydın', 'Bır coldeyim! .. Ruzgarın savurdugu kum tanelerı Yuzume ve gozlerıme carpıyor Bır coldeyım  Susuz ve pejmurde Dudaklarım catlak, kupkuru Has...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Özğan']::text[], 8.5, '{"poet":"İbrahim Özğan","poet_slug":"i-brahim-ozgan","theme":"Türk Şiiri","is_hero":false,"total_lines":73,"source_url":"https://www.antoloji.com/bir-col-hikayesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidiyorsun....', 'gidiyorsun-i-brahim-ozgan-4shsb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Iste gıdıyorsun! …

Oyle yapayalnız bırakarak benı

Gozlerımde yas huzmelerı 

Anlımda ates,

Ellerımde sensızlık 

Gıdıyorsun sevıncımı benden alarak

Iste gıdıyorsun! ..

Yuregım kavı ve paramparca

Adımlarım agırlasıyor sonra

Bır an cansızlık bedenımde

Ve sadece yuzlerımız bır fılım negatıfınde

Cantamda oteberı arasında oylece duruyor

Sen gıdıyorsun; huzunler bende

Iste gıdıyorsun! …

Evet, gelmenı aylar bekledım

Asırlar gıbı gectı

Gelmen asırlara bedeldı

Oysa gıtmen bır an

Gonlum tarumar, perısan

Tuylerım dıken dıken

Sonbaharda kurumus bır dal

Ve gozlerımın ferı sondu

Ve sen gıdıyorsun

Geldıgınde baharla beraberdın 

Butun cıcekler sana guldu

Gokyuzu en guzel gunundeydı ısıl ısıl

Leyla ve mecnun kıskandılar o gun

Sonra denızde balıklar senın ıcın; 

Senın ıcın kumelendıler karsımıza

Ellerımız kenetlenıp,

Ve degınce gozlerıne gozlerım

Kalbımızden etna fıskırdı

Ruzgar ıfıl ıfıldı, yuzumuzde esıyordu

Yureklerımız; dalgalarla beraber carpıyordu.

Sahıle ve teknelere,

Sımdı gıdıyorsun butun carpıntılar bende

Ruyalar bende ve sen bende

Işte gidiyorsun! ..

Icımde supheler korkular

Askımıza daır

Sebebını bılmedıgım seyler bunlar

Gıdıyorsun yuregım yuregınde dıye

Gozlerın gozlerımde

Gozlerımde gozlerın

Gıdıyorsun; benı benden alarak

Gıdıyorsun;  bana el sallayarak

Gıdıyorsun; kursun yemıs yuregım

Paramparca; sermekes oluyor

Iste gıdıyorsun bırtanem kendıne ıyı bak

         ağustos 2000 aydın', 'Iste gıdıyorsun! … Oyle yapayalnız bırakarak benı Gozlerımde yas huzmelerı  Anlımda ates, Ellerımde sensızlık  Gıdıyorsun sevıncımı benden a...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Özğan']::text[], 8.5, '{"poet":"İbrahim Özğan","poet_slug":"i-brahim-ozgan","theme":"Türk Şiiri","is_hero":false,"total_lines":50,"source_url":"https://www.antoloji.com/gidiyorsun-46-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hazırdadır bir kaç ayı! !', 'hazirdadir-bir-kac-ayi-mikdat-bal-20pfc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bitmiş günler bitmiş sayı

Yaklaşıyor oruç ayı

Hazırdadır bir kaç ayı

Şimdi çıkar inlerinden

Dini satar acep kaça? 

Konuşacak sözde hoca

Karo mudur,  yoksa maça? 

Şeytan gider önlerinden

Mikrofonu koyvermezler

Konuşurlar becermezler

Kitabtan bir şey vermezler

Öğrenirler cinlerinden

Nice nane yiyecekler

Görün neler diyecekler

Soğutmak istiyecekler

İnsanları dinlerinden

İbadeti edeceğiz

Oruçları tutacağız

Teravihe gideceğiz

Çatlasınlar kinlerinden

Piç elinde şimdi ipler

Sapıktır bir çok  hatipler

Her şeyi ret eden tipler

Kopukturlar dünlerinden

Bal açıktır, talimlere

Saygım çoktur alimlere

Taş atarım zalimlere

Hiç çekinmem ünlerinden', 'Bitmiş günler bitmiş sayı Yaklaşıyor oruç ayı Hazırdadır bir kaç ayı Şimdi çıkar inlerinden Dini satar acep kaça?  Konuşacak sözde hoca Karo...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/hazirdadir-bir-kac-ayi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İskele', 'i-skele-elazigli-mustafa-kaya-j7jjk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'telaşlı insan kalabalıklarını, 

iskeleye yaklaşan vapuru, 

martıları

sıra sıra çınar ağaçları

denize yakın uçan kuşları

lodos

poyraz

karayel rüzgarlarını

sahil boyunca 

istanbul konuşacağız

bir gün 

eğer gelirsen

her gün yeniden 

dikeceğim şehri 

eylül yağmurları kokacak

sen geirsen eğer, 

bilmediklerimi öğrenceğim. 

ve kalbimi dolduran seni 

istanbul kadar seveceğim...

mustafa kaya

27.09.2005 / üsküdar

www.mustafakaya.net', 'telaşlı insan kalabalıklarını,  iskeleye yaklaşan vapuru,  martıları sıra sıra çınar ağaçları denize yakın uçan kuşları lodos poyraz karayel...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/iskele-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kedicikle Annesi', 'kedicikle-annesi-caglar-asik-0pppo', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Mini mini patisi.

Özlem kokar nefesi.

Nasıl arar annesi! ...

Mır mır çınlar sevgisi.

&

Kokluyor çevresini.

Gözlüyor gelmesini.

İstiyor memesini.

Seviyor emmesini.

&

Bulmalı sancısını.

Sevmeli kafasını.

Yapmalı yuvasını.

Koymalı mamasını.

&

Takmalı künyesini.

Görmeli neşesini.

Vermeli minderini.

Duymalı ninnisini.

&

Mırrrr

Mır mırr

Mır mırr mırrr

Mır mırr mırrr mırrr

&

İstanbul – 09.09.2005

Çağlar Aşık – Kedicik & Annesi', 'Mini mini patisi. Özlem kokar nefesi. Nasıl arar annesi! ... Mır mır çınlar sevgisi. & Kokluyor çevresini. Gözlüyor gelmesini. İstiyor memes...', ARRAY['Türk Edebiyatı','Şiir','Çağlar Aşık']::text[], 8.5, '{"poet":"Çağlar Aşık","poet_slug":"caglar-asik","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/kedicikle-annesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerimde Kaldın', 'gozlerimde-kaldin-osman-i-nci-028hd', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Senin için ben, sevdalarımı yaktım,

Kölen oldum da, avuçlarına baktım,

Her şeyi sildim, kafaya seni taktım,

Düşüncelerimde, gözlerimde kaldın…

Uğrunda çilelerle, savaşıp durdum,

Seninle ilgili, tatlı hayâller kurdum,

Sandım ki hedefi, on ikiden vurdum,

Düşüncelerimde, gözlerimde kaldın…

Sıkıntılar boşa imiş, gayretler boşa,

Aldanmışım yazık ki, bir kalem kaşa,

Vurmaya başladım, başımı her taşa,

Düşüncelerimde, gözlerimde kaldın…

Kimsenin üzmediği kadar, üzdün beni,

Oysa herkeslerden çok, severdim seni,

Ateşlere attın sen, yakıp gittin bu teni,

Düşüncelerimde, gözlerimde kaldın…', 'Senin için ben, sevdalarımı yaktım, Kölen oldum da, avuçlarına baktım, Her şeyi sildim, kafaya seni taktım, Düşüncelerimde, gözlerimde kaldı...', ARRAY['Türk Edebiyatı','Şiir','Osman İnci']::text[], 8.5, '{"poet":"Osman İnci","poet_slug":"osman-i-nci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gozlerimde-kaldin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anladım Artık', 'anladim-artik-osman-i-nci-9knfm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne dostlara güven kalmış, nede kardeşe,

Uzaktan el sallar olmuş, tebessüm neşe,

Yaşamak, buzla yazı yazmakmış güneşe,

Boşunaymış her uğraş, anladım artık…

Neler anlatırdın bana, bak şimdi sustun,

Keseyi açmışsan bil ki, herkes dostun,

Yokluk içinde, beş para etmiyor postun,

Boşunaymış her uğraş, anladım artık…

İnsanlar iyiliklerden, nasibini almamış,

Kimlerin ne derdi var, soran olmamış,

Dostlukların artık, hiç önemi kalmamış,

Boşunaymış her uğraş, anladım artık…

Yolcu kalmamış dünyada, herkes hancı,

İçimizi yakar da, kavurur bizi bu sancı,

Gözlerde sevgi, ellerde ihsan yabancı,

Boşunaymış her uğraş, anladım artık…', 'Ne dostlara güven kalmış, nede kardeşe, Uzaktan el sallar olmuş, tebessüm neşe, Yaşamak, buzla yazı yazmakmış güneşe, Boşunaymış her uğraş, ...', ARRAY['Türk Edebiyatı','Şiir','Osman İnci']::text[], 8.5, '{"poet":"Osman İnci","poet_slug":"osman-i-nci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/anladim-artik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nerede Şimdi', 'nerede-simdi-osman-i-nci-hd7e4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Rakip bulamazdık, yüce sevgimize,

Neden acılar çöktü, bu yüreğimize,

Hani otururda, bakışırdık biz bize,

O gülen gözlerin, nerede şimdi? ..

Öyle bir muhabbetti, koyu mu koyu,

Söz vermiştik, sürecekti asırlar boyu,

Tutmaya doymazdım, saatler boyu,

O sımsıcak ellerin, nerede şimdi? ..

Günlerimiz geçerdi hep, şen şakrak,

Bak uzaklardayız, işte bu son durak,

Şiir gibi dinlerdim, dizinde yatarak,

O harika sözlerin, nerede şimdi? ..

En yüce aşk, benimdir sanıyordum,

Seni en yakından, ben tanıyordum,

Sevdan ile bilsen, nasıl yanıyordum,

O duygusal yüreğin, nerede şimdi? ..', 'Rakip bulamazdık, yüce sevgimize, Neden acılar çöktü, bu yüreğimize, Hani otururda, bakışırdık biz bize, O gülen gözlerin, nerede şimdi? .. ...', ARRAY['Türk Edebiyatı','Şiir','Osman İnci']::text[], 8.5, '{"poet":"Osman İnci","poet_slug":"osman-i-nci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/nerede-simdi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Değerini Bilelim', 'degerini-bilelim-osman-i-nci-pnz03', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Neler gelip, neler geçti başımdan,

Göl olur toplasam, göz yaşımdan,

Öğrendiğim şey, şimdi yaşamdan,

Hayat kısa imiş, değerini bilelim…

İnsanı kırmaya, deymezmiş dünya,

Keyfini çıkarmalı, bak hoş bir rüya,

Gerçek olan ölümdür, gerisi hülya,

Hayat kısa imiş, değerini bilelim…

Üç günlük dünya için, üzülme asla,

Kendine bir hedef seç, hemen başla,

Neden geçsin günler, kederle yasla,

Hayat kısa imiş, değerini bilelim…

Neşeli ol, tebessüm dağıt etrafına,

Çiçekler yolla, evrenin her tarafına,

O zaman, hiç engel çıkmaz yollarına,

Hayat kısa imiş, değerini bilelim…', 'Neler gelip, neler geçti başımdan, Göl olur toplasam, göz yaşımdan, Öğrendiğim şey, şimdi yaşamdan, Hayat kısa imiş, değerini bilelim… İnsan...', ARRAY['Türk Edebiyatı','Şiir','Osman İnci']::text[], 8.5, '{"poet":"Osman İnci","poet_slug":"osman-i-nci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/degerini-bilelim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim mi Oldun', 'benim-mi-oldun-osman-i-nci-fchmw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gözlerinin içinde, kaybolur giderdim,

Dünyaları verseler, bir kenara iterdim,

Ben sadece seni, yalnız seni isterdim,

O kadar sevdim de, benim mi oldun? ..

Saçların ile oynamak, bir keyifti bana,

İlah gibiydin, tapıyordum inan ki sana,

Bak böyle bıraktın, aşkınla yana yana,

O kadar sevdim de, benim mi oldun? ..

Seni bir an görmesem, delice ağlardım,

Rüyalarımda bile, herkeslere sorardım,

Hataymış benimki, zorda olsa anladım,

O kadar sevdim de, benim mi oldun? ..

Hiç uyuşamadık, bir şeyler eksik kaldı,

Sahte gözlerin, benden her şeyimi çaldı,

Senin bu acı hasretin, beni çöllere saldı,

O kadar sevdim de, benim mi oldun? ..', 'Gözlerinin içinde, kaybolur giderdim, Dünyaları verseler, bir kenara iterdim, Ben sadece seni, yalnız seni isterdim, O kadar sevdim de, beni...', ARRAY['Türk Edebiyatı','Şiir','Osman İnci']::text[], 8.5, '{"poet":"Osman İnci","poet_slug":"osman-i-nci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/benim-mi-oldun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ararım Seni', 'ararim-seni-osman-i-nci-feiq3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gülmeye hasretim, gittin gideli,

Benim gönlüm şimdi, çılgın bir deli,

Göz yaşlarıyla veda, ettim edeli,

Mecnun gibi çölde, ararım seni...

Yokluğunla yaram, kanayıp gider,

Sanma ki zamanla, kuruyup biter,

Bu ızdıraplar, ölümden beter,

Kerem gibi dağda, ararım seni...

Şimdi saçlarımda, aklar çıkıyor,

Özlemin bir volkan, kötü yakıyor,

Yüreğimde sevdan, hızla akıyor,

Yunus gibi özde, ararım seni...

Sazımda tel oldun, dinledim durdum,

Altın kafeslerde, özledim durdum,

Çalıp nağme nağme, söyledim durdum,

Aşık gibi sözde, ararım seni...', 'Gülmeye hasretim, gittin gideli, Benim gönlüm şimdi, çılgın bir deli, Göz yaşlarıyla veda, ettim edeli, Mecnun gibi çölde, ararım seni... Yo...', ARRAY['Türk Edebiyatı','Şiir','Osman İnci']::text[], 8.5, '{"poet":"Osman İnci","poet_slug":"osman-i-nci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ararim-seni-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlhamdır Bana', 'i-lhamdir-bana-osman-i-nci-z3eo5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kelimeler duygularıma, kifayet etmez,

Bu aşkı yaşamaya, bir ömür yetmez,

Mezarıma girsem de, bu sevda bitmez,

Kerem ile Aslı aşkı, ilhamdır bana…

Çöllerde geçse de, kısacık ömrüm,

Senden başkasını, sevmez bu gönlüm,

Bitmeyen sevdamsın, sen kara gözlüm,

Leyla ile Mecnun aşkı, ilhamdır bana…

Yalnız seni tanır, yalnız seni severim,

Aşkın yolları çile doludur, iyi bilirim,

Dağların ardında olsan, deler gelirim,

Ferhat ile Şirin aşkı, ilhamdır bana…

Düşmanım olsa takmam, bütün dünyayı,

Bırakmak istemem, gördüğüm bu rüyayı,

Kurulacak bir gün, bizim de düğün alayı,

Tahir ile Zühre aşkı, ilhamdır bana…', 'Kelimeler duygularıma, kifayet etmez, Bu aşkı yaşamaya, bir ömür yetmez, Mezarıma girsem de, bu sevda bitmez, Kerem ile Aslı aşkı, ilhamdır ...', ARRAY['Türk Edebiyatı','Şiir','Osman İnci']::text[], 8.5, '{"poet":"Osman İnci","poet_slug":"osman-i-nci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ilhamdir-bana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Varsın İşte', 'sen-varsin-i-ste-osman-i-nci-tawwg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hayatta en fazla, inan seni severim,

İstersen bu canı, sana feda ederim,

Yıldızlarda olsam da, uçar gelirim,

Gelmeye neden mi, sen varsın işte…

Aşka doymaz gönül, senin yanında,

Aleve aldırmaz, kalır da yangında,

Tüm mutluluklar, senin kollarında,

Sevmeye neden mi, sen varsın işte…

Yaşam günlerime, mutluluk saçar,

Görünce gönlümde, çiçekler açar,

Üzüntü ve keder, kahrından kaçar,

Gülmeye neden mi, sen varsın işte…

Ah bilebilsen, ne hayaller kurarım,

Hayallerimde bile, hep seni sararım,

Bu ömrümü inan, yollarına adarım,

Ölmeye neden mi, sen varsın işte…', 'Hayatta en fazla, inan seni severim, İstersen bu canı, sana feda ederim, Yıldızlarda olsam da, uçar gelirim, Gelmeye neden mi, sen varsın iş...', ARRAY['Türk Edebiyatı','Şiir','Osman İnci']::text[], 8.5, '{"poet":"Osman İnci","poet_slug":"osman-i-nci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sen-varsin-iste-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Gideli', 'sen-gideli-dilek-hokkaomeroglu-iffsp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'biliyor musun; 

sen evden ayrılalı,üç gün oldu.

senden haber almayalı,üç gece

bu ev değişti,

üç günde...

eskiden olduğu gibi

şikayet etmiyorum bu koltuktan

sehpanın üzerinde duran lambadan

içi dolu kül tablasından

sen gideli.

gök yüzü başka bu gece,

korkutuyor karanlık ve yalnızlık

yıldızlara baktım

kaydı bir yıldız.

yıldızların birinde seni gördüm.

aynalara baktım,aynalar düşman.

her sabah,

yüzümü yıkadığım sular,

yüzümü sildiğim havlu bile

bir başka davranıyorlar.

sular bir başka akıyor avuçlarıma

sen gideli

bak; sen sevmezsin diye

haberleri bile dinlemiyorum.

sigara''da içmiyorum artık,

terliklerimi tam koltuğun yanına çıkarıyorum

kanepede bile uyuya kalmıyorum.

abur cuburda yemiyorum,

senin seyrettiğin diziyi

seyretme diye kızardım ya! 

bak ben bile seyrediyorum.

ne kadar değiştim bak sen gideli.

ben ben çoktan değiştim.

elim telefona gidiyor,

günde tam beş defa,

sabahları kalkmak sensiz,

günaydın demeden dolaşmak

evin içinde çaresiz,

üşümek sıcakta bedenin ürpererek,

gecede uğultular,yalnızlıklar

meğer ne çok severmişim seni

sen gideli..

anladım...

DÖN ARTIK...', 'biliyor musun;  sen evden ayrılalı,üç gün oldu. senden haber almayalı,üç gece bu ev değişti, üç günde... eskiden olduğu gibi şikayet etmiyor...', ARRAY['Türk Edebiyatı','Şiir','Dilek Hokkaömeroğlu']::text[], 8.5, '{"poet":"Dilek Hokkaömeroğlu","poet_slug":"dilek-hokkaomeroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/sen-gideli-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Istırap - Tufan Yığıntıları Kitabından', 'istirap-tufan-yigintilari-kitabindan-omer-ekinci-micingirt-8fxgc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kıvrım kıvrım yollar uyan gardaşım

Karanlıkla kimler nere kısıldı 

Secdenin önüne devrilen başım 

Beyaz sevdalarda ebed nasıldı

Ah be yolculuklar içinde narın

Ki nesil ziyânda niceolur yarın

Çarpık zihniyetler gürzü inkârın

Yerli beslemeler  aslan kesildi 

Derin vadilerde  kimler kimle bil 

Dağınık vicdanlar vicdanlar sefil

Ülkem çatırdıyor kök bizim değil

Hainler kahraman kimler asıldı', 'Kıvrım kıvrım yollar uyan gardaşım Karanlıkla kimler nere kısıldı  Secdenin önüne devrilen başım  Beyaz sevdalarda ebed nasıldı Ah be yolcul...', ARRAY['Türk Edebiyatı','Şiir','Ömer Ekinci Micingirt']::text[], 8.5, '{"poet":"Ömer Ekinci Micingirt","poet_slug":"omer-ekinci-micingirt","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/izdirap-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sakın Hiç Bırakma Ellerimi', 'sakin-hic-birakma-ellerimi-huseyin-erdogan-bpdkx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bir yağmur gibi

sevgimde sırılsıklam

ıslatacağım seni

sen de ömrünce

kurumak istemezsin değil mi? 

geceleri

yalnızca sana ayıracağım düşlerimi

ne olursun sen de

sakın hiç bırakma ellerimi

sakın hiç üşütme beni

bu güne kadar ben

yaşamıyormuşum meğer

bunu sen karşıma çıkınca anladım

uzaktan da olsa 

seninle paylaşmak çok şeye değer

yeter ki arada bir olsa da

dön yüzünü benden yana

ve gülümseyiver bana

inan ki ben bütün kalbimle

bir tek sana bağlandım

ömrüm boyunca da

yalnızca senin sevdanla yandım

bil ki yokluğunda 

buralarda isyanlardayım

                       27.09.2005', 'bir yağmur gibi sevgimde sırılsıklam ıslatacağım seni sen de ömrünce kurumak istemezsin değil mi?  geceleri yalnızca sana ayıracağım düşleri...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sakin-hic-birakma-ellerimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Melek', 'melek-asli-yildiran-1uu9k', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'YASEMİN''E - MELEĞİME 

Kötüsü bol iyisi az yalanı çok doğrusu yok bir dünyada     

Nasıl olmuşsa bir melek yaşarmış inanmak zor olsada

Gülerek bakarmış zümrüt gözleri insanoğluna

Kocaman yüreği yaradandan dolayı severmiş yaratılan herşeyi

Güneşe,aya benzermiş güzelliği kendisine dost seçmiş birkaç şanslı kişiyi 

Ağlayıp gülerlermiş beraber şaşırtırmış onları dünya halleri

Melekte yaşamış tabi herkes gibi hayatın kalleşliğini 

Melekmiş gerçek melek kaybetmemiş asla yüreğinin güzelliğini

O melekte savrulup gidiyormuş bu rüzgarda herkes gibi

İnsanoğlu, yalan dolanla yoğurulmuş hamurları

Melek bilmezmiş yalanı buymuş diğerlerinden farkı', 'YASEMİN''E - MELEĞİME  Kötüsü bol iyisi az yalanı çok doğrusu yok bir dünyada      Nasıl olmuşsa bir melek yaşarmış inanmak zor olsada Gülere...', ARRAY['Türk Edebiyatı','Şiir','Aslı Yıldıran']::text[], 8.5, '{"poet":"Aslı Yıldıran","poet_slug":"asli-yildiran","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/melek-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilmiyorum', 'bilmiyorum-asli-yildiran-fkoa6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben seni yeni doğmuş bebeğin niyeti kadar masumca

Dünya kadar büyük,güneş kadar sıcak,buz gibi soğuk

Ben seni yazılmış yazı gibi net

Kanadı kırık bir serçe gibi çaresiz

Duvarlar gibi kör,sağır,dilsiz

Can gibi içten, ben seni benden öte sevmiştim bilmiyorum neden?', 'Ben seni yeni doğmuş bebeğin niyeti kadar masumca Dünya kadar büyük,güneş kadar sıcak,buz gibi soğuk Ben seni yazılmış yazı gibi net Kanadı ...', ARRAY['Türk Edebiyatı','Şiir','Aslı Yıldıran']::text[], 8.5, '{"poet":"Aslı Yıldıran","poet_slug":"asli-yildiran","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/bilmiyorum-53-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Toprak Dost olunca', 'toprak-dost-olunca-recep-recai-nurcan-0vtp7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bak güneş nerdeyse batmak üzere

Abanı yerlere yayıver sarhoş

Yanından kıvırtıp geçen güzele

Gönlünden geçeni salıver sarhoş

Bu deniz kenarı, bu köşe başı

Evin barkındır bu kaldırım taşı

Yıllardır bilmezsin sıcak bir aşı

Kaderine hayret ediver sarhoş

İnsanlar haline hep güldü durdu

Seni en yıkılmaz yerinden vurdu

Gözünde görünmez seller kurudu

Sabrını günlere satıver sarhoş

Devrilen şişene bakıpta sanma

''Artık dostum yok'' diye tasalanma

Her yağmur gövdene kadar ıslanma

Toprağa son bir kez yatıver sarhoş

               (27 Ocak 1995  İstanbul)', 'Bak güneş nerdeyse batmak üzere Abanı yerlere yayıver sarhoş Yanından kıvırtıp geçen güzele Gönlünden geçeni salıver sarhoş Bu deniz kenarı,...', ARRAY['Türk Edebiyatı','Şiir','Recep Recai Nurcan']::text[], 8.5, '{"poet":"Recep Recai Nurcan","poet_slug":"recep-recai-nurcan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/toprak-dost-olunca-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman içinde', 'zaman-icinde-halil-colak-73gn3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kırık düşler içinde hayaller

Yok olup giden o umutlar

Sahte olan  dostluklar

Kaybolur gider zaman içinde

Zaman en iyi ilaçtır derler

Hekimler hep bunu söyler

Acı çeken elbet iniler

Geçer bunlar zaman içinde

Halil Çolak 27.9.2005 Ankara', 'Kırık düşler içinde hayaller Yok olup giden o umutlar Sahte olan  dostluklar Kaybolur gider zaman içinde Zaman en iyi ilaçtır derler Hekimle...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/zaman-icinde-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülay', 'gulay-recep-recai-nurcan-cbz4u', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'G özlerin kadar güzel

Ü mitlerim solmasın

L âkin rüyada isem

A sla sabah olmasın

Y arın güneş doğmasın

      (İstanbul 1993)', 'G özlerin kadar güzel Ü mitlerim solmasın L âkin rüyada isem A sla sabah olmasın Y arın güneş doğmasın       (İstanbul 1993)...', ARRAY['Türk Edebiyatı','Şiir','Recep Recai Nurcan']::text[], 8.5, '{"poet":"Recep Recai Nurcan","poet_slug":"recep-recai-nurcan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/gulay-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana, Senin, İçin', 'sana-senin-i-cin-i-lknur-er-412kc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir yudum su için ölsemde için için

Gelip geçmem kapından seni görmemek için

Bana yaptığın zulüm bilmemki ne için

Bütün başıma gelenler seni sevdiğim için

Gayrı bundan sonra tanımam etmem seni

Seviyorum desende inan dinlemem seni

Kör oldu gözlerim göremem artık seni

Unut beni artık unuttum bende seni

Nice sitemler etsem ah etsem azdır sana

Bakamam senden yana sevgim azaldı sana

Bütün beddualar, ahlar hep sana

Ellerim uzanmaz artık hiç sana', 'Bir yudum su için ölsemde için için Gelip geçmem kapından seni görmemek için Bana yaptığın zulüm bilmemki ne için Bütün başıma gelenler seni...', ARRAY['Türk Edebiyatı','Şiir','İlknur Er']::text[], 8.5, '{"poet":"İlknur Er","poet_slug":"i-lknur-er","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sana-senin-icin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşadığım Sen', 'yasadigim-sen-seyhan-sevgili-uvitn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Uzaktan elimi sıktığın,

buz gibi ''''kendine iyi bak'''' dediğin kaldırımda bıraktım,

yaşadığım seni.', 'Uzaktan elimi sıktığın, buz gibi ''''kendine iyi bak'''' dediğin kaldırımda bıraktım, yaşadığım seni....', ARRAY['Türk Edebiyatı','Şiir','Seyhan Sevgili']::text[], 8.5, '{"poet":"Seyhan Sevgili","poet_slug":"seyhan-sevgili","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/yasadigim-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Meğer Ayrılmışız', 'meger-ayrilmisiz-seyhan-sevgili-puk0w', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kolay görünmüştür o arkamı dönüşüm...

Şaşkınlıktan gülümsemiştim,sende hiç sormamıştın nedenini.

Meğer ayrılmışız bir zamanlar bugün,

yeni yeni anlıyorum.', 'Kolay görünmüştür o arkamı dönüşüm... Şaşkınlıktan gülümsemiştim,sende hiç sormamıştın nedenini. Meğer ayrılmışız bir zamanlar bugün, yeni y...', ARRAY['Türk Edebiyatı','Şiir','Seyhan Sevgili']::text[], 8.5, '{"poet":"Seyhan Sevgili","poet_slug":"seyhan-sevgili","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/meger-ayrilmisiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah Şu Muma Dönmüşlüğüm..', 'ah-su-muma-donmuslugum-can-ceylan-ovc3w', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir tekmelik sehpanın darağacı koynunda

Gönüllü geçirdiğim ilmektin sen boynuma

Kıymak için bekleyen celladın inadına

Sarmaş dolaş olurdum tutunurdum koluna

Bazen bir düş hayaldin tütsüydün yüreğime

Buram buramdı gecem sen tüterdin burnumda

Sitem kokulu güller sunarken hasretine

Bir çiğ olur düşerdin gecemin efkarına

Hiç sözüm yok gülmene bu şaşkın hallerime

Yalnız senden kopmamı ayrılmamı bekleme

Kan ağlayan kalbime resti çekerdim ama

Mahcup olmak kolay mı muma dönmüşlüğüme', 'Bir tekmelik sehpanın darağacı koynunda Gönüllü geçirdiğim ilmektin sen boynuma Kıymak için bekleyen celladın inadına Sarmaş dolaş olurdum t...', ARRAY['Türk Edebiyatı','Şiir','Can Ceylan']::text[], 8.5, '{"poet":"Can Ceylan","poet_slug":"can-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ah-su-muma-donmuslugum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güz Yüzlüm', 'guz-yuzlum-ertugrul-sakar-cfi8e', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Güz yüzlüm

Hayatım

Yeşermiş baharlardan

Sararmış baharlara

Kahve gözlüm

Altın sarısı umutlum

Kırık dalların yorgun

Üzüntü peteğim

Üzümü derilmiş bağ

Hazan fırtınam

Güz kapısı aralı

Yüreğin nereli

Aşk atım

Sevgilim, hayatım', 'Güz yüzlüm Hayatım Yeşermiş baharlardan Sararmış baharlara Kahve gözlüm Altın sarısı umutlum Kırık dalların yorgun Üzüntü peteğim Üzümü deri...', ARRAY['Türk Edebiyatı','Şiir','Ertuğrul Şakar']::text[], 8.5, '{"poet":"Ertuğrul Şakar","poet_slug":"ertugrul-sakar","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/guz-yuzlum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dizgin', 'dizgin-hakki-hakan-kaya-w10xm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yine sabahın gözleri mahmur

çığlık çığlığa uykuda hala 

gündüz düşlerim

bir karanlık hayalin 

benzersiz dokunuşu

içimdeki tüm organları 

harekete geçiren eşsiz bir nağme

yüreğimden öpen 

gecenin sesi

ve bendeki hayaliyle 

ruhumu tekamüle ulaştıran

sessiz nefesiyle beni 

masal diyarında dolaştıran

altın sarısı saçlarından 

gözlerime güneş gibi doğan

o endam-ı hülyası tarifsiz

o aşk-ı sevdası biçimsiz

varlığıyla bir hare gibi

etrafımı kuşatan

ve daha yaşamadan

yaşanmayanları yaşatan

yüreğimin kapısına kilit

kalbimin geçitine mühür vuran

uzak bakışlı sevdam...

çık gel artık hayallerin içinden

bırakalım dizginlerini gerçeğin', 'Yine sabahın gözleri mahmur çığlık çığlığa uykuda hala  gündüz düşlerim bir karanlık hayalin  benzersiz dokunuşu içimdeki tüm organları  har...', ARRAY['Türk Edebiyatı','Şiir','Hakkı Hakan Kaya']::text[], 8.5, '{"poet":"Hakkı Hakan Kaya","poet_slug":"hakki-hakan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/dizgin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '…Soğuk Parantez…*', 'soguk-parantez-naime-erlacin-cj8nr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'sabahlar bilmez yaşlanmayı

kadim bir masalın ayak izlerine gece

kırmızı saatlerin mührünü vurur

açılır parantez

cezaya durduğunda tek ayak üstünde

en fazla kendi kökünü söker kişi

eşikten sızan suyudur buz 

dona çeken akşamın

adresini bulamayan bir mektup yazar sevgiye

soğur beden

geçmiş bir zamandan kalan iri sözler

ufalanıp un eler yazgımıza

arsızca kuşanılır sabahın diri vakitleri

tanrısal gücü umulur dağın 

yalnız bir ağıttan

dişlerini geçirir gerçek etimize

acıtır içimizin çengelleri

sessizliği dinleriz

meçhule üflenmiş 

mum alevinde kapanır parantez

puhu kuşu sonuncu kez kanat çırpar

ağlar

tüylerini bırakır kırık bir eylül cübbesine

soğur evren

üşürüz böyle...

(*)      13 Eylül 2005 - Sevgili Babam A. Muzaffer Bulgulu anısına.', 'sabahlar bilmez yaşlanmayı kadim bir masalın ayak izlerine gece kırmızı saatlerin mührünü vurur açılır parantez cezaya durduğunda tek ayak ü...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/soguk-parantez-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Musa-Hızır Buluşması I (Hızıra Sorular)', 'musa-hizir-bulusmasi-i-hizira-sorular-abdullah-acar-574cf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seninle dost olduk, düştük bir yola

Günlerce yürüdük, vermedik mola

Aklıma sorular geldi bir sürü

Sorsam bir türlü, sormasam bir türlü

Önce bir gemiye bindirdin beni

Meraktan merağa kondurdun beni

Hele bindiğimiz gemiyi delmeni

Sorsam bir türlü, sormasam bir türlü

Karaya çıktık, rastladık bir eve

Sen bir garip baktın evde sabiye

O masumun canını aldın ne diye

Sorsam bir türlü, sormasam bir türlü

Yürüdük sonunda bir köye vardık

Yıkılmış gördük, bir duvar onardık

Çalışıp ücretini neden almadık

Sorsam bir türlü, sormasam bir türlü

Şu işlerinle aklımı karıştırdın

Öfkemi kabarttın, sabrımı taşırdın

Merakım ırmaktı denize aşırdın

Sorsam bir türlü, sormasam bir türlü

(26/09/2005-Ankara)', 'Seninle dost olduk, düştük bir yola Günlerce yürüdük, vermedik mola Aklıma sorular geldi bir sürü Sorsam bir türlü, sormasam bir türlü Önce ...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Acar']::text[], 8.5, '{"poet":"Abdullah Acar","poet_slug":"abdullah-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/musa-hizir-bulusmasi-i-hizira-sorular-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '…Kaftan...', 'kaftan-naime-erlacin-e2y4u', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'nükseder kimi hastalıklar

eylüllü ağıtlara benzer 

silinmez hiç

çölü çekmek gibidir içine

biri bozdurarak harcar kendini

ne bütünlenir daha

ne ''üstü kalır'' alacaklısında

kiminde kül 

kuyum tozu 

ayrıksı bekleyiş

ışığa susamış kilitli bir kasanın 

soğuk yalnızlığında

sabır taşı biriktirir başkası

uzun soluklu kader tayının 

semere vurulmuş 

ağır torbasında

yalandan yaşar 

hayata hiç “merhaba” dememiş gibi 

ölür yalandan 

bilmeyiz nerdedir onca delik

yüzümüzde tutuşur nükseden hastalık

bin yerden paralanır deli kaftan

sonrası derin acı

yeis

çarpılır ruh terazisi 

mihengi noksan

sönmüş bir balonu yeniden uçurabilir misiniz 

kaynak tutmaz bu yüzden eylülde gözlerimiz

(27 Eylül 2005 – Eylül Dosyası)', 'nükseder kimi hastalıklar eylüllü ağıtlara benzer  silinmez hiç çölü çekmek gibidir içine biri bozdurarak harcar kendini ne bütünlenir daha ...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/kaftan-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mesleğim...', 'meslegim-mehmet-demir-atmali-9xfl2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '-Dostlarım ne ile uğraştığımı

soruyorlar; sonu (T)  ile biten

mesleklerle uğraşıyorum...

Siyaset

Ticaret

Hareket

Bereket

Rezalet

Fazilet

Adalet

Evlat

Devlet

Şeriat

Tarikat

Marifet

Hakikat

Maalesef

en sonunda; 

Tuvalet...

27.9.2005', '-Dostlarım ne ile uğraştığımı soruyorlar; sonu (T)  ile biten mesleklerle uğraşıyorum... Siyaset Ticaret Hareket Bereket Rezalet Fazilet Ada...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Demir Atmalı']::text[], 8.5, '{"poet":"Mehmet Demir Atmalı","poet_slug":"mehmet-demir-atmali","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/meslegim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '…Eylül Kuşları…', 'eylul-kuslari-naime-erlacin-bn6st', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'yarısı yaz / yarısı kış

yarısı bir dolu hüzün / gece

yarısı günışığı / kışkırtıcı

ipini kopartmış entrikacı fahişe 

işte geldi çattı mevsim

yaz’ı bitirdik diyorum anla! 

deniz tatsız 

düğünler tavsadı artık

mağazalarda bir ucuzluk furyasıdır gidiyor

ne alırsan üç’e beş’e

oysa “insandan ucuz şey yok” demişti kadın

yakında bizleri de koyarlar vitrinlere

bir geliş 

telaşlı 

bir gidiş / bir sayrılık

bir de kemirgen duygu 

insafsız

kalbe hançer saplayan cinsten

yaşama sevincimizi çalmıştı hani

sessizce ağlıyorduk 

ağlıyorlardı durmadan 

bundan söz ediyorum

masumiyet gülücükleri 

içimizdeki ıssızlığın 

dudağında kuruyor 

zamansız

erkekler rızk peşinde 

dörtnala ter atıyorlar

işleri varsa ne mutlu! 

yaygaracı kadınlar mı? 

ne desem ki 

...yorum yok...

biliyorsun farklı biriyim ben

anlamam onları 

sizin anladığınız kadar 

önümüz kış’mış aldırma 

yakala eylül kederlerini 

aşka ve ölüme bağışla hüznümü ey sevgili

orada çöreklenen habis intihara

kalbimdeki kuşları sıkı tut yeter

göçmesinler! 

(27 Eylül 2005 – Eylül Dosyası)', 'yarısı yaz / yarısı kış yarısı bir dolu hüzün / gece yarısı günışığı / kışkırtıcı ipini kopartmış entrikacı fahişe  işte geldi çattı mevsim ...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/eylul-kuslari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'EKSİlerindeyim Hayatın', 'eksi-lerindeyim-hayatin-yasar-yilmaz-er6y5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bir konuşma geçti ressamla aramda

dedim; 

mutsuzluğun resmini yapabilir misin? 

şöyle bir baktı gözlerimin içine 

önce aldı boyayı  fırçayı eline

sonra da beni karşısına

çıkardı resmimi tuvale

işte dedi; mutsuzluğun resmi

peki dedim; 

ya mutluluğun? 

önce dedi; 

hayatından bu resmi çıkar

geri kalanla bana gel

bir daha gidemedim ressama

EKSİlerindeyim hayatın', 'bir konuşma geçti ressamla aramda dedim;  mutsuzluğun resmini yapabilir misin?  şöyle bir baktı gözlerimin içine  önce aldı boyayı  fırçayı ...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Yılmaz']::text[], 8.5, '{"poet":"Yaşar Yılmaz","poet_slug":"yasar-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/eksilerindeyim-hayatin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '…Kışlak …', 'kislak-naime-erlacin-3e46b', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ileri gidiyor mevsim saatleri

aç gözlü rüzgarlar yutuyor sevdiklerimizi

orda bir yerde bekliyor sonsuzluk 

kapı duvar

içim kale

kum tanelerinden kalp yapıyorum

çırılçıplak soymadım henüz eylülü 

borç senetleri ödenmedi şiddetli yele

bekliyorum 

sararan yaprakları kuş sanırdım evvelden

toplanıp giderdi mahzun çingeneler

meçhul bir adrese doğru yol yılgını

bilmezdim sonyaz çiçeklerinin

vakitsiz solduğunu

yuvasızlığa bayrak açtıklarını güz günlerinde 

erken çöküyor acının gölgesi

kumdan ördüğüm palamarları 

sebepli sebepsiz çözüyorum

dışarısı gece nöbeti 

zalim

yaşanmamış saatler ve ben 

ve içim sevgiyi vururken 

derin bir yalnızlığa yürüyorum

:

ölüm beslemesi çelimsiz kalbim 

eylülden yana kışlak…

(27 Eylül 2005)   – Eylül Dosyasından', 'ileri gidiyor mevsim saatleri aç gözlü rüzgarlar yutuyor sevdiklerimizi orda bir yerde bekliyor sonsuzluk  kapı duvar içim kale kum taneleri...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/kislak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İhtiyarlık', 'i-htiyarlik-ensar-cevval-jzftf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Uzun soluklanmalarla adımlanan yokuşlarda

Buz gibi korkuluklar tutar ellerini

Kar düşmüş zirveler gibi saçların

Gözlerin sis çökmüş vadi gibi derin

Tutulan ellerin an  kadar ayrılmışken

Aynalar hep ensenden yansıyordu

Toprak adımlarını yar dibinde tutmuşken

Aynalar alnına gün düşüyordu.

Bir inişi vardı mutlak tırmandığın tepenin

Sevinçle, nefessiz koşuyorken

Sonra bir tepe,bir tepe daha derken

Artık inişlerde de yoruluyordun

Elinden tutunca düşmeme engeldin sen

Basamaklardan inip çıkarken; 

Şimdi ellerinden tutmak ne tuhaf

Elinden tutulan sen olmuşken.

Çamlıca 01,09,2005', 'Uzun soluklanmalarla adımlanan yokuşlarda Buz gibi korkuluklar tutar ellerini Kar düşmüş zirveler gibi saçların Gözlerin sis çökmüş vadi gib...', ARRAY['Türk Edebiyatı','Şiir','Ensar Cevval']::text[], 8.5, '{"poet":"Ensar Cevval","poet_slug":"ensar-cevval","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ihtiyarlik-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin Aşk Kölen', 'senin-ask-kolen-sahin-erturk-1jip2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'RİTA kasırgası gibi

Önüne aldın beni

TUSUNAMİ gibi

Kabardı duygularım

Beynimde,kalbimde

Düşüncemde,kalemimde

Hep sen varsın

Seninim ayışığım

Herşeyimle seninim

Sana teslim oldum

Senin aşk kölen

Artık benim,ben

(27.09.2005-Yeni)', 'RİTA kasırgası gibi Önüne aldın beni TUSUNAMİ gibi Kabardı duygularım Beynimde,kalbimde Düşüncemde,kalemimde Hep sen varsın Seninim ayışığım...', ARRAY['Türk Edebiyatı','Şiir','Şahin Ertürk']::text[], 8.5, '{"poet":"Şahin Ertürk","poet_slug":"sahin-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/senin-ask-kolen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mum Işığı', 'mum-isigi-cem-i-mdat-1gifg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Mum ışığına benziyorum bu gece

Hafif rüzgardan kıvrılan

Umutsuzca göz açıp kapayan mum ışığı 

Güneşten çok küçük 

Karanlıkta küçük bir loşluk 	

Fark edilemeyen küçük bir ışık sadece 

Umutlarımı anlatıyor hali

Uğraşıyor ama 

Yenemiyor karanlığı 

Yalnızlığı…

Saatler kaldı ölmesine onun 

Saatler kaldı sabaha… 

Güneşle ölecek umutları 

Beni görmeden 

Seni görüp 		

Umutlarımı gömdüğün gibi…', 'Mum ışığına benziyorum bu gece Hafif rüzgardan kıvrılan Umutsuzca göz açıp kapayan mum ışığı  Güneşten çok küçük  Karanlıkta küçük bir loşlu...', ARRAY['Türk Edebiyatı','Şiir','Cem İmdat']::text[], 8.5, '{"poet":"Cem İmdat","poet_slug":"cem-i-mdat","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/mum-isigi-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '14 Şubat', '14-subat-cem-i-mdat-sy83l', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '14 Şubat

Sevgililerin

Sevenlerin

Aşıkların bayramı…

Bazılarının yüzünde bir ilk heyecanı

Kimilerinin hediye telaşı…

Tek başına özleyenlerin

Bekleneni bekleyenlerin

Yapayalnız bu gece koynunda

Beyninde eski bir fotoğraf

Anılan küçük vakitler

Yan yana olunan

Değeri bilinemeyen

Sevinç dolu günler…

Bir yıl öncesi gözlerimde

İlk kez olan bayramda

Bizim bayramımızda…

Aradığındaki korku

Sevinç,heyecanla…', '14 Şubat Sevgililerin Sevenlerin Aşıkların bayramı… Bazılarının yüzünde bir ilk heyecanı Kimilerinin hediye telaşı… Tek başına özleyenlerin ...', ARRAY['Türk Edebiyatı','Şiir','Cem İmdat']::text[], 8.5, '{"poet":"Cem İmdat","poet_slug":"cem-i-mdat","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/14-subat-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duvarın Kardeşliği', 'duvarin-kardesligi-cem-i-mdat-uw3pt', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Korku gizli kirpiklerimde

Göz kapamakla karşımda sanki

İçime gizli bir sancı giriyor gecelerde

Saatler hüznü vurduğunda… 

Dilim açılıyor bir anda 

Söylemek üzere oluyor hissettiklerimi 

Seni,sevgimi… 	

Ama bulamıyor yüreğim o dakikalarda 

Beni seven,düşünen bir dost… 

Karanlık yarenim oluyor birden 

Aklımda dün,bugün,yarın 	

Duvarlar şahit hüznüme 	

En çok da sevgime 	

Hasretine ve eşsiz güzelliğine… 

Bir bakıma dost oluyor bana 

Gülümsemeden dinliyor beni bir anda 

Sessiz bir karşılıkla… 

Sessiz ve cevapsız sorularla yarına 

Yarından da bir ötekine 	

Sürükleniyorum sayende…', 'Korku gizli kirpiklerimde Göz kapamakla karşımda sanki İçime gizli bir sancı giriyor gecelerde Saatler hüznü vurduğunda…  Dilim açılıyor bir...', ARRAY['Türk Edebiyatı','Şiir','Cem İmdat']::text[], 8.5, '{"poet":"Cem İmdat","poet_slug":"cem-i-mdat","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/duvarin-kardesligi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmurlar Sensiz Yağıyor', 'yagmurlar-sensiz-yagiyor-sair-dicleyagmur-0ib2z', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Şimdi çok uzaklardasın biliyorum.

Sen yoksun yanımda  ve bu şehirde...

Şimdi yağmurlar sensiz yağıyor.

Biliyor''musun yağan yağmurlarda seni düşündüm.

Sensiz ıslandım...! 

Şimdi yanımda ve bu şehirde yoksun.

Oysa yağan her yağmur damlasında,yüreğime sen ve sevgi damlaları düşerdi.

Biliyorum''Ki sen eylülü ve hazanı,başka bir şehirde bensiz yaşıyorsun.

Bir başka yağmurlarla ıslanıyorsun...! 

Şuan  yağmur zamanı ama sen yoksun.

Yağmurlarda sensiz ıslanıyor ve sensiz üşüyorum.

Yoksun yine yanımda...

Sol yanım yine üşüdü.

Ben yine ıslandım.

Sen yoktun yanımda.

Biliyor''musun yüreğime  artık yağmur  damlaları değil,hasret

ve özlem  damlaları  düşüyor.

Bu yağmurda yine sensiz ıslandım.', 'Şimdi çok uzaklardasın biliyorum. Sen yoksun yanımda  ve bu şehirde... Şimdi yağmurlar sensiz yağıyor. Biliyor''musun yağan yağmurlarda seni ...', ARRAY['Türk Edebiyatı','Şiir','Şair Dicleyagmur']::text[], 8.5, '{"poet":"Şair Dicleyagmur","poet_slug":"sair-dicleyagmur","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yagmurlar-sensiz-yagiyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tercih', 'tercih-abdurrahim-karakoc-wkjak', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hava basmak vatan borcu, ha gayret

Ben “hava”nın millîsini severim.

İçi  ''Kızılelma'' doluysa şayet

Ben “Kuvva”nın millîsini severim.

İsterim darbeci başı da konsun

Karganın, baykuşun beşi de konsun

Ayırmam, Mao''nun kuşu da konsun

Ben”yuva”nın millîsini severim.

Toplanmaz demişler elma armutla

Ben topladım oldu şalgamı dut''la

Yürüsün ayılar, keçiler, kurtla

Ben “dâvâ”nın millîsini severim.

Katılan katılsın, aranmaz şart-şurt

Emekli çobanlar etmeli cart-curt

Duysun sesimizi Paris, Frankfurt

Ben “cıva”nın millîsini severim.

Otağlar kurulsun dokuz direkli

''Onuncu yıl'' haykırılsın sürekli

Kızartmada ulusal yağ gerekli

Ben “tava”nın millîsini severim.

Münafıklar hayır olmaz dese de

Aldırmayın, civelekler kesede

Dolaptaki elbisemi yese de

Ben “güve”nin millîsini severim.

Sıkı duran mert,  mevziyi terk etmez

Soldan sağa, sağdan sola çark etmez

Öküz-inek gücense de fark etmez

Ben “düve”nin millîsini severim.

Azametli başlar başı çekmeli

Körler böbrekteki taşı çekmeli

Nalbantlar dil kesip, dişi çekmeli

Ben “deva”nın millîsini severim.

Koçyiğitler at oynatmak istiyor

Mülkü toz-dumana katmak istiyor

Ovalarda cirit atmak istiyor

Ben “ova”nın millîsini severim.

Varsın cila, küster kullanılmasın

Varsın alta astar kullanılmasın

Varsın mala-mastar kullanılmasın

Ben ''sıva''nın millîsini severim.

Gül beyazsa kızıl renge boyarız

Kızılelma saksısına koyarız

Yalan, yave palavraya doyarız

Ben “yave”nin millîsini severim.

Diyorum ki ''ulusalcı'' olmalı

Olmayanın saçlarını yolmalı

Kovalara millî rakı dolmalı

Ben “kova”nın millîsini severim.

Muhalif kafalar ezilsin artık

Pas bağlayan diller çözülsün artık

Develer kervana dizilsin artık

Ben “deve”nin millîsini severim.

18 Eylül 2005/Vakit', 'Hava basmak vatan borcu, ha gayret Ben “hava”nın millîsini severim. İçi  ''Kızılelma'' doluysa şayet Ben “Kuvva”nın millîsini severim. İsterim...', ARRAY['Türk Edebiyatı','Şiir','Abdurrahim Karakoç']::text[], 8.5, '{"poet":"Abdurrahim Karakoç","poet_slug":"abdurrahim-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/tercih-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir-Fatihâ', 'bir-fatih-yurdagul-kurnaz-xw7jm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ellerine alacaksin unutulmus umutlari

Aynanda göreceksin sonsuz ufuklari

Senki aglanacak haline gülebiliyorsan

Gönlündeki goncalari hic actirmadiysan

Oturtursun gönül tahtina sevgi den bir anahtar

Din, irk, renk ayirt etmeksizin

Sev insani, kadimi, kal her daim bahtiyar

Karamsarliga okundu bir-Fatihâ

09.23

20.09.2005', 'Ellerine alacaksin unutulmus umutlari Aynanda göreceksin sonsuz ufuklari Senki aglanacak haline gülebiliyorsan Gönlündeki goncalari hic acti...', ARRAY['Türk Edebiyatı','Şiir','Yurdagul Kurnaz']::text[], 8.5, '{"poet":"Yurdagul Kurnaz","poet_slug":"yurdagul-kurnaz","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bir-fatiha-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülzârı şeyda *', 'gulz-ri-seyda-ali-riza-unal-02933', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Nur eyledi sahnı çemeni, nigârı cemâlin ey yâr,

Değmesin ellerim sana, gözlerim kıskanır yâr,

Sensizlik bir an bile aklımdan geçmezki benim,

Gayrı firak eyleme dildarınım,dilzârı sevda var.

Varlığın tükenmez bin umut, ömürsün bana,

Bahrı gönlüm gülşen, şimdi gülzarı şeyda var..

Lügatçe ::

Şeyda : çok seven sevgiden hasıl olan hal

Tutkun divane.

Sahnı  : meydan ‘ Sahne.

Nigâr  : alıcı’ çekici çok güzel en ala yüz. Simama.

Cemâl  Çehre suret surat.

Firak :  ayrılık.

Dilzar : ağlayan inleyen dil

Dildar  Aynı lehçe ‘şive aynı lisanla konuşan.

Bahr:   deniz

Gülşen : gül bahçesi güllük.

Gülzar   : gül bahçesinden büyük gül tarlası gül 

Ormanı', 'Nur eyledi sahnı çemeni, nigârı cemâlin ey yâr, Değmesin ellerim sana, gözlerim kıskanır yâr, Sensizlik bir an bile aklımdan geçmezki benim,...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/gulzari-seyda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kan-baglarim', 'kan-baglarim-yurdagul-kurnaz-zk9fe', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Siz kanbaglarim

Yakinlarim

Bu duygu yüklü yürege

Sizi ben gibi sevene

Yasamin zehir zikkim 

Icen bene

Kanayan yaralarima tuz basmazmisiniz

Ben ki

Kirik kanatlarimi actim size

Beni diri diri öldürdünüz

Basi olmayan yeni bir güne

Gömdünüz

Gidecegim buralardan uzaklara

Aldanmayacagim sevgi denen tuzaklara

Varsin basi buyruk yalnizligimi iceyim

Ben beni hic acitmayacagim

Hep sevecegim

Hep sevecegim...

01.39

27.09.2005', 'Siz kanbaglarim Yakinlarim Bu duygu yüklü yürege Sizi ben gibi sevene Yasamin zehir zikkim  Icen bene Kanayan yaralarima tuz basmazmisiniz B...', ARRAY['Türk Edebiyatı','Şiir','Yurdagul Kurnaz']::text[], 8.5, '{"poet":"Yurdagul Kurnaz","poet_slug":"yurdagul-kurnaz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kan-baglarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Meğer', 'meger-ahmet-toper-ra798', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Körebe oynar gibi karanlığında aldandığım

Tutuklu gecenin sessizliğinde seni aradığım

Meğer yalanmış her şey

Hiç düşünmeden varlığına inandığım

İçimde keşfedilmeyi bekleyenler vardı

Bir sarsıntınla toprağa gömüldüler

Her batışın yeniden doğuşunu bilenler vardı

Bir heyecanla doğarken dibe battılar

Senden bana kalan yitik parçalarım

Etrafıma dizdiğim hayal kırıklıklarım

Meğer hepsi gerçekmiş

Hiç düşünmeden sensizlikte yaralandığım

Gözlerimde durulmuş sağanaklar vardı 

Bir gidişle damlalara yenik düştüler

Yüreğimde dipdiri duygular vardı

Bir öpüşle yerden yere dağıldılar', 'Körebe oynar gibi karanlığında aldandığım Tutuklu gecenin sessizliğinde seni aradığım Meğer yalanmış her şey Hiç düşünmeden varlığına inandı...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Toper']::text[], 8.5, '{"poet":"Ahmet Toper","poet_slug":"ahmet-toper","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/meger-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vazgeçilmezim olurdun', 'vazgecilmezim-olurdun-zati-erbas-7opjb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ben.

senden.

vazgeçerim

diyorsun.

ne garip  değilmi  sözcükler

anlamlı

anlamsız

sevgi yüklendiğin kadar var.

mesela 

rüzgar 

vapurda 

yüzünü okşarken

ben kıskanırdım 

sen bunu bilmezdin

kalabalığa karışmazdı

sevgim.

ben 

aklı başında  olurdum.

neden mi? 

vazgeçilmezim olurdun', 'ben. senden. vazgeçerim diyorsun. ne garip  değilmi  sözcükler anlamlı anlamsız sevgi yüklendiğin kadar var. mesela  rüzgar  vapurda  yüzünü...', ARRAY['Türk Edebiyatı','Şiir','Zati Erbaş']::text[], 8.5, '{"poet":"Zati Erbaş","poet_slug":"zati-erbas","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/vazgecilmezim-olurdun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutma', 'unutma-ercan-akbay-tncot', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İnsanlar her zaman mutlu olmaz küçüğüm

         Mutsuzluklarda vardır UNUTMA

         Sen sevsende yürekten,sevilmiyebilirsinde

         Kimselere hiç DARILMA

         Hayat budur diyeceksin bazen

         Belki kapılar yüzüne kapanacak açılmadan

         Belki unutulacaksın solan bir yaprak gibi

         Yalnız kalmaktan hiç KORKMA

         Sanma ki yolun hep düz

         Engellerde olacak,çelme takanlarda

         Düşsen bile kalkmakta geç KALMA

         Gün gelecek kahkahalarla güleceksin

         Gözlerin ışıl ışıl parlayacak mutluluktan

         Dudaklarını bir çift dudak öpecek

         Sakın ömür böyle geçecek SANMA

         Mutsuzluklarda vardır

         Yaşamın iki yüzlü çilveside,

         Parayla satılan değerlerde.

         Yaşadıkça görecek pişeceksin

         Ellerin nasır  olacak

         Bir büyük mücadeleye doğdum diyeceksin

         Son nefesini vermeden YIKILMA....

                                       İST.1990', 'İnsanlar her zaman mutlu olmaz küçüğüm          Mutsuzluklarda vardır UNUTMA          Sen sevsende yürekten,sevilmiyebilirsinde          Kim...', ARRAY['Türk Edebiyatı','Şiir','Ercan Akbay']::text[], 8.5, '{"poet":"Ercan Akbay","poet_slug":"ercan-akbay","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/unutma-77-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eylül', 'eylul-i-rfan-tansel-turhan-9gia9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'EYLÜL

Anısı vardır elbet yüreğimizde

Dökülen yaprakların hüznü

Hangi yağmur sularına kapılıp gittiler

Titrek rüzgar uğultusu sesleri

Eylül saçlı, eylül bakışlı anılar.           

1994', 'EYLÜL Anısı vardır elbet yüreğimizde Dökülen yaprakların hüznü Hangi yağmur sularına kapılıp gittiler Titrek rüzgar uğultusu sesleri Eylül s...', ARRAY['Türk Edebiyatı','Şiir','İrfan Tansel Turhan']::text[], 8.5, '{"poet":"İrfan Tansel Turhan","poet_slug":"i-rfan-tansel-turhan","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/eylul-86-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seviyorum', 'seviyorum-filiz-yildirim-0ivhw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir duygu sardı beni

O gece içimi birdenbire,

Gözlerin yeterdi anlatmana,

Sözlerin  yeterdi haykırmana.

Bir duygu sardı yüregimi

Nefesin,kokun,yeşil gözlerin,

Gözlerine bakınca erirdim,

Sanki tutusurdu yüregim,

Aşık oldugumu anladıgımda,

Basımı omzuna yasladıgımda,

Hergece seni kokladıgımda,

Ogece anladımki,yüregimle,

Seni seviyorum', 'Bir duygu sardı beni O gece içimi birdenbire, Gözlerin yeterdi anlatmana, Sözlerin  yeterdi haykırmana. Bir duygu sardı yüregimi Nefesin,kok...', ARRAY['Türk Edebiyatı','Şiir','Filiz Yıldırım']::text[], 8.5, '{"poet":"Filiz Yıldırım","poet_slug":"filiz-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/seviyorum-68-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk/ım Misafirlik Değil...', 'ask-im-misafirlik-degil-dilek-egri-bcrti', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'kalemimde hüzne dair kaç dize varsa söküp attım hepsini

ardından çaktım karanlığa bir kibrit

şüphelerim yansın

yolumu bulmalıyım artık

gece sütünü içirdim korkularıma

ve umutlu ninnilerle uyuttum her birini yeni sevdamın koynunda

zorlu sevdalardan çıkıp bi soluklanırım diye uğradım yüreğinde; 

yüreğim yerini yadırgamadı

dizlerimde derman yok

gidemem artık....

aşk/ım sen/de kal/ıcı..! 

25/09/05

/..Tanrı misafiri değilim birazdan gidecek...ziyaretim sonsuzluk../', 'kalemimde hüzne dair kaç dize varsa söküp attım hepsini ardından çaktım karanlığa bir kibrit şüphelerim yansın yolumu bulmalıyım artık gece ...', ARRAY['Türk Edebiyatı','Şiir','Dilek Eğri']::text[], 8.5, '{"poet":"Dilek Eğri","poet_slug":"dilek-egri","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ask-im-misafirlik-degil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Yazdığım Bu Şiir Olacak', 'sana-yazdigim-bu-siir-olacak-hifzi-ozbekmez-o5j2t', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'SANA YAZDIĞIM BU ŞİİR OLACAK

Sevenin aşkıdır zalimden farkı

Dünyanın döndükçe alemde çarkı

Dillerde dolaşan en güzel şarkı 

Sana yazdığım bu şiir olacak

Sevdandır gönlümde çakılı duran

Hasretin beynime balyozu vuran

Ortalığı yakıp kasıp kavuran

Sana yazdığım bu şiir olacak

Hayalin kurarım her gün her gece

Hasreti çözemem sanki bilmece

Dilimden dökülen hep hece hece

Sana yazdığım bu şiir olacak

Aklımda takılı busenin tadı

Gönlümde yazılı aşkının adı

Bütün varlığımın sana biadı

Sana yazdığım bu şiir olacak

Aşkıma evveli ahir dedirten

Göz yaşın sevdaya dair dedirten

Ozan latifiye şair dedirten

Sana yazdığım bu şiir olacak', 'SANA YAZDIĞIM BU ŞİİR OLACAK Sevenin aşkıdır zalimden farkı Dünyanın döndükçe alemde çarkı Dillerde dolaşan en güzel şarkı  Sana yazdığım bu...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sana-yazdigim-bu-siir-olacak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senden Bende Kalanlar', 'senden-bende-kalanlar-arsen-lupen-45l0f', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bozkır nöbetlerinde gönlüm

Anladım yağmurlarım sende kalmış

Çağırdım, aradım bulamadım

Anladım yüreğim sende kalmış

Saçlarım dağılmaz oldu gecelerine şehrin

Anladım rüzgarım sende kalmış

Çıkamadım ne gündüz ne gece yola

Anladım tüm yollarım sende kalmış

Ne akıllıyım ne deli yunus misali

Anladım aşkın namı sende kalmış

Bir bahar olmuşsun ölüme şimdi

Anladım baharım sende kalmış', 'Bozkır nöbetlerinde gönlüm Anladım yağmurlarım sende kalmış Çağırdım, aradım bulamadım Anladım yüreğim sende kalmış Saçlarım dağılmaz oldu g...', ARRAY['Türk Edebiyatı','Şiir','Arsen Lüpen']::text[], 8.5, '{"poet":"Arsen Lüpen","poet_slug":"arsen-lupen","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/senden-bende-kalanlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostlarım', 'dostlarim-mahmut-simsek-trfh7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Acınız acım,derdiniz derdim olsun

Keder olmasın,gülen yüzler solmasın

Yalnızlık çok zor,kimse yalnız kalmasın

Canımdan kıymetli bildiğim dostlarım 

	

Yeterki isteyin canım size kurban 

Hepiniz için feda olsun her zaman

En kötü günleriniz mutluluk dolsun

Canımdan kıymetli bildiğim dostlarım 

	

Bir bir ayrılan oluyor aramızdan 

Ne olur tutun bırakmayın ayrılmasınlar desemde

Gidecek ya bugün yada yarın 

Canımdan kıymetli bildiğim dostlarım

                                                                     YAZAN VE DERLEYEN

                                                                           MAHMUT ŞİMŞEK

                                                                                ADIYAMAN', 'Acınız acım,derdiniz derdim olsun Keder olmasın,gülen yüzler solmasın Yalnızlık çok zor,kimse yalnız kalmasın Canımdan kıymetli bildiğim dos...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Şimşek']::text[], 8.5, '{"poet":"Mahmut Şimşek","poet_slug":"mahmut-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/dostlarim-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Git…veya…..Kal', 'git-veya-kal-turgay-yildirim-8szcx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sözlerin yüreğime dokunuyor

Ağlamaklı oluyorum 

Sözcüklerin kurşun

Kor ateş yürekte

Yürekte yangın yeri

Yara hiç kapanmayacak 

Hiç kan durmayacak 

Habis bir UR……

Zehir zemberek

Sus artık

Konuşma ne olur 

Git

Gitmelisin

Her şeyinle gitmelisin

Ağırda olsa gitmelisin

Yüreğimden çıkmalısın

Sesinle varlığınla ağır sözlerinle

Kal 

Kal desem neye yarar

Git……..git…..git

Gitmelisin

Sen….. 

Adamı intihara sürükler

Damlardan atlatırsın 

Git…

Kal….desem? 

kalırmısın

Sen aslında

Gül gibi güzel 

Su gibi berraksın 

Belki de maviye çalan 

Gökyüzüsün....', 'Sözlerin yüreğime dokunuyor Ağlamaklı oluyorum  Sözcüklerin kurşun Kor ateş yürekte Yürekte yangın yeri Yara hiç kapanmayacak  Hiç kan durma...', ARRAY['Türk Edebiyatı','Şiir','Turgay Yıldırım']::text[], 8.5, '{"poet":"Turgay Yıldırım","poet_slug":"turgay-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/git-veya-kal-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaralı Gönlüm', 'yarali-gonlum-mahmut-simsek-juctg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir değseniz bin ah işitirsiniz,

Benim şu yaralı gönlümde.

Bir aşk, bir sevda, bir özlem yarası,

Deymeyin benim bu kederli halime.

İlahi kaderimi böyle yazmışsa eyer; 

Boynumuz kıldan ince, ne gelir elden.

Köz gibi yanıp tutuşmamı istermişse eğer! 		

Tabip,tedavi de etse söyle ne gelir elden.

	

Zaten misafir değil miyiz bu dünyada,

Bir rüzgar gelir savurur misali,

Bir oraya,bir buraya gurbetlik hali,

Evimde bile oldum bir misafir emsali 

Değmeyin yaralı,kederli,gamlı halime,

Su gelir mi ki kuruyan göz çeşmelerime,

Merhem olur mu ki kalbimde açılan derin yarama

Her şeyi o bilir,sığınırım beni yaradanıma.

                                                                        YAZAN VE DERLEYEN

                                                                             MAHMUT ŞİMŞEK

	                                                                   ADIYAMAN', 'Bir değseniz bin ah işitirsiniz, Benim şu yaralı gönlümde. Bir aşk, bir sevda, bir özlem yarası, Deymeyin benim bu kederli halime. İlahi kad...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Şimşek']::text[], 8.5, '{"poet":"Mahmut Şimşek","poet_slug":"mahmut-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/yarali-gonlum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bulmuşum Seni', 'bulmusum-seni-mahya-sultan-tosun-fk5m6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yeni insanlar tanıdıkça,

Yakışıksız, gereksiz

Çocuksu davranışlar gördükçe,

Saçmasapan kırılganlıklar yaşadıkça,

Olgunca bir davranış, bir söz duymayı özledikçe; 

Sana olan özlemim hergün artmakta

Sana olan sevgim kat be kat güçlenmekte

Seni bulduğum için,

Bana ait olduğun için,

Hep benimle olduğun için,

Yüreğim coşmakta her geçen günle.

Anladım ki; 

Sen, sen bir tanesin yeryüzünde

Anladım ki; 

Ben, ben bulmuşum seni yüreğimde

Sonunda anladım ki; 

Tek ihtiyacım sensin benim bu evrende...', 'Yeni insanlar tanıdıkça, Yakışıksız, gereksiz Çocuksu davranışlar gördükçe, Saçmasapan kırılganlıklar yaşadıkça, Olgunca bir davranış, bir s...', ARRAY['Türk Edebiyatı','Şiir','Mahya Sultan Tosun']::text[], 8.5, '{"poet":"Mahya Sultan Tosun","poet_slug":"mahya-sultan-tosun","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bulmusum-seni-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Ömür Böyle Geçti', 'bir-omur-boyle-gecti-sadik-altinkaynak-zl38f', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir Ömür Böyle Geçti

Bunca senedir olmadı kârım

Ömrümün baharı yel gibi geçti

Bir selam bile vermedi yarim 

Geldi yanımdan el gibi geçti

Yedi kat göklere çıktı feryadım

Boşandı göz yaşım sel gibi geçti

Bu fani dünyadan bir tat almadım

Koskoca bir ömür yıl gibi geçti

Seni bulmak ümidiyle zalim

Ömrüm kapılarda kul gibi geçti

Nihayet karıştı toprağa tenim

Her gelen üstümden yol gibi geçti

			Sadık ALTINKAYNAK', 'Bir Ömür Böyle Geçti Bunca senedir olmadı kârım Ömrümün baharı yel gibi geçti Bir selam bile vermedi yarim  Geldi yanımdan el gibi geçti Yed...', ARRAY['Türk Edebiyatı','Şiir','Sadık Altınkaynak']::text[], 8.5, '{"poet":"Sadık Altınkaynak","poet_slug":"sadik-altinkaynak","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bir-omur-boyle-gecti-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Londra'' da Bir Old Man', 'londra-da-bir-old-man-sadik-altinkaynak-jpzcm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'I saw in London a very old man

Elinde baston başında fotör kulakta walkman

I don’t know his name may be Coni may be Toni

Bilmem nasıl anlatsam... Şey... Varya.... Hani...

Listen to me I’ll tell you something funny

Size bir hikâye anlatacağım yani

One day this very old man

Ki bu zat centilmen mi haza centilmen

He wanted to go to the toilet

İşte o zaman koptu kıyamet

Don’t ask me Wat happened? How? 

Söyleyemem. Because I don’t know

The very old man in this story

Kusura bakmasın, I’m terrible sorry

Karıştırdı “Lady” ile “Gentleman”i

İzin verirse eğer anlatayım serüveni

He went to the toilet of lady

Aman kardeşim o bağırtı neydi? 

A woman screamed “Get out, get out...”

Old man bir çıktı ki olmuş knock out

Neyse... gerisini sormayın beni döver

“Of course” kızdı mı kardeşine bile söver

                                          Sadık ALTINKAYNAK

                                                   1989', 'I saw in London a very old man Elinde baston başında fotör kulakta walkman I don’t know his name may be Coni may be Toni Bilmem nasıl anlats...', ARRAY['Türk Edebiyatı','Şiir','Sadık Altınkaynak']::text[], 8.5, '{"poet":"Sadık Altınkaynak","poet_slug":"sadik-altinkaynak","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/londra-da-bir-old-man-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Old Man''in Ahı', 'old-man-in-ahi-sadik-altinkaynak-nttuh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Atalar dememiş boşu boşuna

Gülersen komşuna gelir başına

Hani Lodra’da bir “old man” varmış

Güya “Lady” ile “Gentleman” i karıştırmış

Bir arkadaş, sorma ismi bir yana Dursun

Ararsan satırlar arasında bulursun

Bunu hikâye etmiş bir mecliste

Aynen başına gelmiş Büyük Mecliste

Yani O da girmiş bayan WC sine

Tıpkı “Old Man” Londra’da girercesine

Bu dost ki makamı Âli bakışları Şahin...

O da gadrine uğramış kör talihin

Kovulmuş mu oradan kovulmamış mı? 

Bilmiyorum olayın yabancısıyım

Ben gözümle görmedim

Görenlerin yalancısıyım

Derler ki tuttu “Old Man” in ahı

Doğru mu yalan mı söyleyene günahı

Aziz dostum kızmayasın arkamdan

Yüz yüze gelince tutmayasın yakamdan

İnan... Kendi kendime yazmadım

Talimat verildi bir yüce makamdan

                                             -1990-', 'Atalar dememiş boşu boşuna Gülersen komşuna gelir başına Hani Lodra’da bir “old man” varmış Güya “Lady” ile “Gentleman” i karıştırmış Bir ar...', ARRAY['Türk Edebiyatı','Şiir','Sadık Altınkaynak']::text[], 8.5, '{"poet":"Sadık Altınkaynak","poet_slug":"sadik-altinkaynak","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/old-man-in-ahi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elimde Yalnızlığın Var', 'elimde-yalnizligin-var-muhammet-faruk-koca-mjshi', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gecelerin yalnızlığı, gecelerin hüznü, 

Varlığım sensiz bu kadar anlamsızken, 

Böyle severken gitmen akıl karı değil, 

Soruları cevapsız bırakıyorsun bana, 

Şimdi içimde ki bütün kelebekler suskun, 

Çarpmıyor artık kanatlarını, 

Bu kenti seninle tanımıştım, 

Seninle yaşadım, 

Şimdi İstanbul’u böyle sessiz hüzünlü görmek, 

Acımı daha bir katlıyor ah bir bilsen, 

Kalbim nasılda ağlıyor şimdi sensiz, 

Seni özlemeyi en çok ben biliyorum, 

Boğazın kıyısından ışıklara bakarken, 

Bir tepeden diğerine gidip geliyor gözlerim, 

Belkide senin ışığını arıyorum, 

Şimdi sen kim bilir hangi kıyıdasındır, 

Kime açıyorsun yüreğinin derinliklerini, 

Benimde gemimin yelkenlerini şişirecek bir gün rüzgâr, 

Yapa yalnız yol alacağım aşk denizlerinde, 

Yüzleşmek mi demeli hesaplaşmak mı, 

Adını da tam olarak koyabilmiş değilim içimde, 

Bu kadar zor muydu sensizlik? 

Bu kadar dayanılmaz mıydı ah sevgilim? 

Kendimi şimdi o kadar yalnız hissediyorum ki, 

Her şarkı hüzün dolu sensiz gecelerde, 

Her şarkı özlem kokuyor, 

Ne varsa hayata dair alıp götürdün beni benden, 

Farkında değilsin. 

Oysa beklediğim tek sevgiliydin sen, 

Yorgun gecelerden dam atılmış, 

Kimsesiz sevdalardan süzülmüş aşkımın tek sahibi, 

Hadi git. 

Dileğince özgürce at adımlarını, 

Bende kalsın yalnızlığın. 

Her şarkı özlem kokuyor, 

Ne varsa hayata dair alıp götürdün beni benden, 

Farkında değilsin. 

Oysa beklediğim tek sevgiliydin sen, 

Yorgun gecelerden dam atılmış, 

Kimsesiz sevdalardan süzülmüş aşkımın tek sahibi, 

Hadi git. 

Dileğince özgürce at adımlarını, 

Bende kalsın yalnızlığın. 

25.09.2005', 'Gecelerin yalnızlığı, gecelerin hüznü,  Varlığım sensiz bu kadar anlamsızken,  Böyle severken gitmen akıl karı değil,  Soruları cevapsız bır...', ARRAY['Türk Edebiyatı','Şiir','Muhammet Faruk Koca']::text[], 8.5, '{"poet":"Muhammet Faruk Koca","poet_slug":"muhammet-faruk-koca","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/elimde-yalnizligin-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yetiş Bana', 'yetis-bana-huseyin-sigirtmac-1xx97', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bensiz sanma ki yaşarsın.

Sevgisiz kalır üşürsün.

İstersen dağlar aşarsın.

Beklerim gel yetiş bana.

Sensiz yaşamın yok tadı.

Ömrün geçiyor miadı.

Ceza vermez aşka kadı.

Beklerim gel yetiş bana.

Sensiz zevki yok dünyanın.

Anlamı yok hiçbir anın.

Faydası yok bu kavganın.

Beklerim gel yetiş bana.

Gel bu Sığırtmaç’ı kırma.

Kısa ömür aşksız durma.

Duyguna kelepçe vurma.

Beklerim gel yetiş bana.', 'Bensiz sanma ki yaşarsın. Sevgisiz kalır üşürsün. İstersen dağlar aşarsın. Beklerim gel yetiş bana. Sensiz yaşamın yok tadı. Ömrün geçiyor m...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sığırtmaç']::text[], 8.5, '{"poet":"Hüseyin Sığırtmaç","poet_slug":"huseyin-sigirtmac","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yetis-bana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Giden Dostluk', 'giden-dostluk-huseyin-ercan-f2bya', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sorgular gibi bakma öyle

Bakışlarından anlıyorum

Sen karşı yakadasın 

Ben bu yakadan

Uzak gibi görünse de

Bir nefes kadar yakındı inan

Kaçırma bakışlarını ısrarından

Bir tutam kırçiçeği iken sevgim

Çiçek bahçesine döndürdü zaman

Duygular müsade etmez sorgulayamam

Geri gelir mi zannediyorsun kaybolan zaman? 

Uzak gibi görünse de 

Bir nefes kadar yakındı inan', 'Sorgular gibi bakma öyle Bakışlarından anlıyorum Sen karşı yakadasın  Ben bu yakadan Uzak gibi görünse de Bir nefes kadar yakındı inan Kaçır...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Ercan']::text[], 8.5, '{"poet":"Hüseyin Ercan","poet_slug":"huseyin-ercan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/giden-dostluk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah Birde Sen Sevsen', 'ah-birde-sen-sevsen-kamil-soylemez-gsl4r', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dökülsün güllerim 

Solsun baharım

Sen olmayacaksan sevdam

Ben ne işe yararım

Ha gelipte gitmişim dünyaya

Ha gitmemişim 

Sevdan deryasında rotasız

Dümensiz bir canım

Sevgilim sendin,canım,kanım sen

Karları delen,kardelen ben

Bir günde sen sevsen ah biriciğim sen

Her şeye sil baştan,yeniden başlardım', 'Dökülsün güllerim  Solsun baharım Sen olmayacaksan sevdam Ben ne işe yararım Ha gelipte gitmişim dünyaya Ha gitmemişim  Sevdan deryasında ro...', ARRAY['Türk Edebiyatı','Şiir','Kamil Söylemez']::text[], 8.5, '{"poet":"Kamil Söylemez","poet_slug":"kamil-soylemez","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ah-birde-sen-sevsen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk''a Rüzgarlı', 'ask-a-ruzgarli-seyhan-sevgili-0vc3m', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Tanışmayacak gözlerimiz biliyorum.

Hep, '' sarılsaydık mutlu olurduk '' diyebileceğim

biri olarak hatırlayacağım seni.

Belki aynı sokaktan geçer,aynı köşeyi döneriz bi kaç kere.

O zaman ezberlerim,o zaman biriktiririm güzelliğini.

Şimdi kendimi aşan bir umutla bekliyorum seni.

İnanıyorumki bizimde bir yolumuz var.

Belki başı başka ama, sonu aşk''a rüzgarlı.', 'Tanışmayacak gözlerimiz biliyorum. Hep, '' sarılsaydık mutlu olurduk '' diyebileceğim biri olarak hatırlayacağım seni. Belki aynı sokaktan geç...', ARRAY['Türk Edebiyatı','Şiir','Seyhan Sevgili']::text[], 8.5, '{"poet":"Seyhan Sevgili","poet_slug":"seyhan-sevgili","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ask-a-ruzgarli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Efkarlanmadan', 'efkarlanmadan-baran-demir-7ex07', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Baharın cıvıltılı şiirsel bir anıydı 

O yaşanılan sevinç dolu kareleriydi. 

Beklide resimlere tutsak ettiğimiz günler 

Bazıları acı, bazıları mutluluk olsa da 

Kimi zaman sevinçlerimizi 

Kimi zamanda sevdiklerimizi 

Bu karelere sığdırmak istediğimiz 

Sevdalarımızı hapsettiğimiz 

Sanki hiç bitmeyecekmiş gibi 

Öylesine durup gülücükler verdiğimiz 

Mutluluk oynadığımız 

Ve hep baktık ca  hüzünlendiğimiz 

Ah o günler dediğimiz 

Ve hiç bitmesini istediğimiz 

Kağıt karelerine sığdırma ya çalıştığımız 

Oy sa ne gerek vardı 

Öylesine  yaşanıp gitseydi 

Hapsetmeden özgürce 

O güzelim günler acısıyla,tatlısıyla 

Efkarlanmadan', 'Baharın cıvıltılı şiirsel bir anıydı  O yaşanılan sevinç dolu kareleriydi.  Beklide resimlere tutsak ettiğimiz günler  Bazıları acı, bazılar...', ARRAY['Türk Edebiyatı','Şiir','Baran Demir']::text[], 8.5, '{"poet":"Baran Demir","poet_slug":"baran-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/efkarlanmadan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elvedân', 'elved-n-yilmaz-helimergin-30kwj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kapayınca gözlerimi; 

gözlerini görüyorum

kapalı gözlerimin

toz, pembe ufuklarında.

ve ben 

ne zaman tıkasam şu aciz kulaklarımı; 

senin 

o cımasız dudakların

fısıldar kendini bana.

şimdi sen yoksun yanımda

ve yine

senin yerine

yokluğun var baş ucumda.

oturmuşuz onunla 

seni konuşuyoruz 

dertli dertli...

sessiz yağan 

göz yaşlarımın altında.

hayalinle dolaşıyorum 

bom boş sokaklarda.

hüznü

aleve boyadığım

o müzdarip akşamlarda

dökülürken 

kıpkızıl dudaklarından elvedan; 

hayali bir geminin 

yolcularıydı 

bana el sallayan.

27.09.2006 12:21:00', 'Kapayınca gözlerimi;  gözlerini görüyorum kapalı gözlerimin toz, pembe ufuklarında. ve ben  ne zaman tıkasam şu aciz kulaklarımı;  senin  o ...', ARRAY['Türk Edebiyatı','Şiir','Yılmaz Helimergin']::text[], 8.5, '{"poet":"Yılmaz Helimergin","poet_slug":"yilmaz-helimergin","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/elvedan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anne.... (Esintim)', 'anne-esintim-mustafa-celebi-cetinkaya-9ej1b', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ah anne ah.... 

kıymetini gittiğinde,, 

kudretini de bittiğinde anladım.... 

Anladım ki tek dost tek sırdaşsın ve anladım ya ağladım... 

bana bir masal anlatır mısın anne... 

dünkü gibi.... 

ve ne güzeldi senle yaşamak aslında 

kırdık seni 

üzdük seni 

bilemedik ki..... 

anne.... 

kıymetini gittiğinde 

kudretini bittiğimde anladım. 

Anladımya 

ne vefasızmışım meğer... 

çok ağladım... 

27 Eylül 2005 Salı 

12:30 Sıhhiye', 'ah anne ah....  kıymetini gittiğinde,,  kudretini de bittiğinde anladım....  Anladım ki tek dost tek sırdaşsın ve anladım ya ağladım...  ban...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Çelebi Çetinkaya']::text[], 8.5, '{"poet":"Mustafa Çelebi Çetinkaya","poet_slug":"mustafa-celebi-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/anne-esintim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiç usanıp bıkmadan', 'hic-usanip-bikmadan-baran-demir-qr5a8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Oysa nede çok sevmiştim

Yüzündeki o tatlı hüznü ve seni

Alıp gitmedin mi yüreğimi

Zindanlara atıp zincirlere vurmadın mı

Sonra uzattığım gülleri

Hançer olup saplamadın mı  yüreğime

Kan olup aktı sevdam

Senide alıp bedenime

Kapladı her yerimi 

Sen ah sevdam 

Kan olup aksanda tenimden 

Acıda versen

Yinede seveceğim ilk gün ki gibi

Hiç usanıp bıkmadan', 'Oysa nede çok sevmiştim Yüzündeki o tatlı hüznü ve seni Alıp gitmedin mi yüreğimi Zindanlara atıp zincirlere vurmadın mı Sonra uzattığım gül...', ARRAY['Türk Edebiyatı','Şiir','Baran Demir']::text[], 8.5, '{"poet":"Baran Demir","poet_slug":"baran-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/hic-usanip-bikmadan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül olsam ama dikensiz', 'gul-olsam-ama-dikensiz-baran-demir-4jz89', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gül olsam ama dikensiz

Açsam gözlerimi görk yüzüne

Gülümsesem ve gülümsetsem

Mutluluk versem

Dikensiz olsam ya acı vermesem

Sarı, beyaz,kırmızı fark etmez

Anlatsam da farklı duyguları

Ayrılığı,sevdayı,mutluluğu,acıyı

Yinede hep gülsem gülümsetsem

Bazen acı olsam da 

Bazen sevda da

Bazen de mutluluk  olurum

Dalımdan koparılsam da gücenmem

Sevdalara şiirlere konu olurum

Ah birde ben sevdalansam

Birde ben mutlu olsam

Biride bana bir gülü verse

Anlasam tattırdığım duyguları

Birde ben tadabilsem

Olsun be birazcık mutluluk

Birazcık acıda versem

Sen hep gül,gülümse 

Dikende batsa eline

Damlamasın  yüzünden 

O göz damlaların 

İncinme', 'Gül olsam ama dikensiz Açsam gözlerimi görk yüzüne Gülümsesem ve gülümsetsem Mutluluk versem Dikensiz olsam ya acı vermesem Sarı, beyaz,kırm...', ARRAY['Türk Edebiyatı','Şiir','Baran Demir']::text[], 8.5, '{"poet":"Baran Demir","poet_slug":"baran-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/gul-olsam-ama-dikensiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özgürlüğe hasret', 'ozgurluge-hasret-baran-demir-tsgbw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Uzandım ranzama

Aklıma düştü bedenin

Tutsaktır zincire 

Vurulmuş yüreğim

Tavana bakmak da gözlerim

Haylin karşımda duruyor

Ben sana gelmek isterken

Kollarım zincire vurulmuş

Nasıl geleyim

Bileklerim kanarken

Hala kendimi zorlarım

Mazgallar sürüldü üstüme

Güneşe hasret gözlerim

Denizi hatırlatır bana

Düşlerimde de olsa

Maviye çalan gözlerim

Esaretin bedeli olsa gerek

Özgürlü ge hasret olmak

Kendimi sokaklara salıp

Alabildiğince hızlı yeşile koşmak

Hayalini kurduğum

Dalgasını duyduğum

Denize atlayıp kucak atmak

Kanatlanıp pencereden gördüğüm

Martıya yaren olup uçmak

Rüyalarımda da olsa

Sevdama sarılıp öylesine uzanmak

Yanağına ufacık da olsa

Öpücük kondurmak

Sonra içerde bir ses

Haykırıyor dikkat

Teftiş var ilkiniyorum

Birden ne olmuş diye

Uykudaymışım meğer

Özgürlüğüme koşarken

Uyanıyorum rüyamdan

Oysa daha sevdama

Yeni sarılmışken

O kiraz dudaklarına

Bir öpücük kondurmadan

Yapılır mı be gardiyan', 'Uzandım ranzama Aklıma düştü bedenin Tutsaktır zincire  Vurulmuş yüreğim Tavana bakmak da gözlerim Haylin karşımda duruyor Ben sana gelmek i...', ARRAY['Türk Edebiyatı','Şiir','Baran Demir']::text[], 8.5, '{"poet":"Baran Demir","poet_slug":"baran-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/ozgurluge-hasret-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '** Bağış Parası**', 'bagis-parasi-seyhmus-sevilmez-az9cb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Minik yavrum büyümüş, çok susamış bilgiye

Okulun kapısını, tıkmış bağış parası

Hevesle bakıyordu, önlük, kalem, silgiye

Umudu azdırmadan, yıkmış bağış parası

Velinin yüreğine, açmışlar derin yara

Eğitmezmiş çocuğu, vermez isen bir para

Nice anne babalar böylece düşmüş hara

Dar gelirli belleri, bükmüş bağış parası

Okulun ilk gününde, çocukta garip bakış

Burkulmuş bir yürekle, sınıfa sesiz akış

Parasız velilere, müdürden sert bir çıkış

Garibanı kafaya takmış bağış parası

Meğer ilköğretime, kayıt ne kadar zormuş

Para vermeyenleri “sürgün” sınıfa sürmüş

Gözleri dolan baba, eli masaya vurmuş

Gizli bir kamerayla çıkmış bağış parası.

Açıldı soruşturma, boyadılar gözleri

İnanmamızı ister vaat veren sözleri

Sadece bir okulda araştırdı izleri

Şu kararsız medyadan bıkmış bağış parası

Hangi veliye baksan, yürekleri yaralı

Makbuzsuz bağışlarda kaç sıfırlar karalı

Devletin okulları hepsi olmuş paralı

Meşaleye mermiyi sıkmış bağış parası

27.09.2005/ Batman', 'Minik yavrum büyümüş, çok susamış bilgiye Okulun kapısını, tıkmış bağış parası Hevesle bakıyordu, önlük, kalem, silgiye Umudu azdırmadan, yı...', ARRAY['Türk Edebiyatı','Şiir','Şeyhmus Sevilmez']::text[], 8.5, '{"poet":"Şeyhmus Sevilmez","poet_slug":"seyhmus-sevilmez","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/bagis-parasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gökyüzü', 'gokyuzu-musa-oz-053yl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gül attım gökyüzü düştü

Denizi bir kilime serdim

Üst üste ekledim güzü

Aydede..

Ah, işte orada dur! Onardım da sözü

Taş gibi kavrayıp suları

Saçtım yüzüne gözüne

Sonra topladım çalısını çırpısını

Tenindeki çiy damlasını

Vurup hançeri beyaz rüzgara

Mor kınalar devşirdim

Soludum da tarlalar uçuştu 

Gökyüzü gelip usulca

Konuverdi delişmen kızın sesine

Konsun konmasına da

‘Da’sı var işte bir de

Hadi be neyse diyecektim

O Lekeleri olmasaydı 

Külotunun öyle gizlice görünmesine

İlahi gökyüzü

Kamaşıp durdu günlerce

Soludum gökyüzü uçtu 

Uzandım da kanadı dağlar', 'Gül attım gökyüzü düştü Denizi bir kilime serdim Üst üste ekledim güzü Aydede.. Ah, işte orada dur! Onardım da sözü Taş gibi kavrayıp suları...', ARRAY['Türk Edebiyatı','Şiir','Musa Öz']::text[], 8.5, '{"poet":"Musa Öz","poet_slug":"musa-oz","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/gokyuzu-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yangın yeridir artık', 'yangin-yeridir-artik-baran-demir-bzuan', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hırcın sularda boy verdik

Kimi zaman asi kimi zaman özgürce dolaştık

Sıkıpda yumruğumuzu haykırınca sevdamızı

Yangın yeridir artık munzur

Geçit vermez laf anlamaz

Nice sevdalara tanıktır

Rüzgara kapılıp gitmiş nice aşklara

Yitip giden hayatlara düşlere

Anamın gözünden akıp giden bir çift damla

Ağıttır artık kaybolup giden canlar

Yumruğum artık sım sıksı

Kanatmak da artık avuçlarımı 

Damlar toprağa, munzura 

Karışıp gider savrulur rüzgara

Taşır yarınlara

Munzurda yaşayan aşkları,sevdaları umutları', 'Hırcın sularda boy verdik Kimi zaman asi kimi zaman özgürce dolaştık Sıkıpda yumruğumuzu haykırınca sevdamızı Yangın yeridir artık munzur Ge...', ARRAY['Türk Edebiyatı','Şiir','Baran Demir']::text[], 8.5, '{"poet":"Baran Demir","poet_slug":"baran-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yangin-yeridir-artik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlarım', 'aglarim-necati-keceli-zuhwa', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ayrılık kalbime vurunca darbe

    Bam teline vurup çalar ağlarım

    Gönül hasretinle girince harbe

    Hayalden, hayale dalar ağlarım

    Gözlerim her yerde yüzünü arar

    Yokluğun çektirir bana ahu zar

    Bende bir kul gibi ölene kadar

    Gözümden yaşları salar ağlarım

    Kalbimde yaşıyor buruk bir sızı

    Hayatın ne tadı kaldı ne tuzu

    Yılın dört mevsimi baharı yazı

    Hasreti koynuma beler ağlarım

    Duygular yırtıldı tutmuyor yama

    Umut zehirdir her türlü hülyama

    Hayalin düştükçe, gece rüyama

    Gözlerime yaşlar dolar ağlarım

    İçimde ki derdin bir tek nedeni

    Terk edip gidişin bu can bedeni

    Her gece yürekten özlerken seni

    Başımdan saçları yolar ağlarım

    Kaderim de varmış acı ve zülüm

    İlaçtan çare yok bu aşka gülüm

    Zamanım tükenip gelirken ölüm

    Bende bir gül gibi solar ağlarım

    Necati KEÇELİ

    İZMİR', 'Ayrılık kalbime vurunca darbe     Bam teline vurup çalar ağlarım     Gönül hasretinle girince harbe     Hayalden, hayale dalar ağlarım     G...', ARRAY['Türk Edebiyatı','Şiir','Necati Keçeli']::text[], 8.5, '{"poet":"Necati Keçeli","poet_slug":"necati-keceli","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/aglarim-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başçavuş’un.../Hiciv', 'bascavus-un-hiciv-mehmet-akif-gulhan-2cyij', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Başçavuş’un.. 

Kadir kıymet bilmez çeşmesine varmışım 

Muradım bir aya su içip mercan tas koymak oldu 

Eğildim ki feyz almaya,billur akan su katran oldu 

Mercan tas aktı gitti elimden, alelade kum oldu 

Gidip hitabet meclisine gireyim dedim 

Sözüm,kum saatindeki kum tanesi gibi heba oldu 

Aşinası müptela olur zannettim-söylediğim sözlere- 

Başçavuş ile,gaz kaçıran hayvanının muamelesi oldu 

Mehmet Akif Gülhan 25.07.2005 Saat 12.23', 'Başçavuş’un..  Kadir kıymet bilmez çeşmesine varmışım  Muradım bir aya su içip mercan tas koymak oldu  Eğildim ki feyz almaya,billur akan su...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif Gülhan']::text[], 8.5, '{"poet":"Mehmet Akif Gülhan","poet_slug":"mehmet-akif-gulhan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bascavus-un-hiciv-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Kalp', 'bu-kalp-mahya-sultan-tosun-mix07', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu kalp; 

Daha kaç kişiyi sevebilir ki

Senden sonra,

Senin için attığı gibi

Kaç kişi için çarpabilir artık yüreğim,

Senin için ağladığı gibi

Kaç kişi için gözyaşı döker ki bu gönül,

Yok artık, bitti bu yürek.

Şimdi; 

Paramparça, darmadağın

Solgun ve durgun

Sıradan ve anlamsız 

Bu kalp; 

Senden sonra.', 'Bu kalp;  Daha kaç kişiyi sevebilir ki Senden sonra, Senin için attığı gibi Kaç kişi için çarpabilir artık yüreğim, Senin için ağladığı gibi...', ARRAY['Türk Edebiyatı','Şiir','Mahya Sultan Tosun']::text[], 8.5, '{"poet":"Mahya Sultan Tosun","poet_slug":"mahya-sultan-tosun","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bu-kalp-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benide Yanına Alıp da Gitsen', 'benide-yanina-alip-da-gitsen-serkan-madak-p1azv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sözlerim bir anlam bulurdu belki

Bir gece gönlümde kalıp da gitsen

Kalbime dur emri veriyor sanki

Beynimden beş ay''ı alıp da gitsen

Manasız akmazdı hiç bir katresi

Gözümde bir lahza kalıp da gitsen

Dünya''ya küsmezdi gönül kafesi

Aşk''tan nasibini alıp da gitsen

Bina yapılır mı kalan enkaz''a

Bir kibrit çakıp da, yakıp da gitsen

Söz anmayacağım seni bir daha

Gönlümü yanına alıp da gitsen

Aklımı boşluğa salıp da gitsen...', 'Sözlerim bir anlam bulurdu belki Bir gece gönlümde kalıp da gitsen Kalbime dur emri veriyor sanki Beynimden beş ay''ı alıp da gitsen Manasız ...', ARRAY['Türk Edebiyatı','Şiir','Serkan Madak']::text[], 8.5, '{"poet":"Serkan Madak","poet_slug":"serkan-madak","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/benide-yanina-alip-da-gitsen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mimesis', 'mimesis-kadir-ucvet-2h7nl', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Arthur Rimbaud ile “BEN” i “BİR BAŞKASI” OLMAKLARA DAİR SESLENİŞ,

KAPATMAK HESAPLARI, YOLA ÇIKIŞ LARDA:

Vakti geldi edilgin hesapları,

Faturalara vurmaların:,

''Yeterince görüldü. Bütün kılıklara girdi çünkü gizli görüntü..''

Metaforuna uzatmaktı kulaklığını erkin,

Yiterken

Kırık aynalardan yansıyan sesinde yankının:,

''Yeterince duyuldu. Kentin uğultuları, akşamleyin ve güneşte, ve her zaman.''

Yola çıkışın mekanıydı o vakit ve zamanı

Olmazdı, çıkarmak kör kuyusundan oturaklı imanı:,

Vakti gelmişti yeni bir gelişime inanın...

Evet,

''Yeterince yaşandı. Yaşamın durakları.-Ey uğultular ve 

Gizli görüntüler! '' Ey gidesiceler bizden ırağa..

''Yola çıkış.Yeni sevgi ve yeni görüntüler içinde..''

ARAMAK “NE” Yİ GECE TOPLANTI LARI NDA:

I..

Yazgı aranmalı mıydı ne olacaklarda

Ne idi bu, toplantısında yarasaların

Körler sayrısı, gelecek karaltısı mı..? 

''Aydınlık bir erinç bu, ne sayrılıkateşi, ne de bitkinlik,

yatakta ya da çayırda.''

''Dost bu, ne ateşli ne de güçsüz.Dost.''

Mesafesinde uzaklığın yakın ateşiyle,

yanan, Olimposlar’ da,

''Sevgili bu, ne acı çektiren ne de acılı.Sevgili.''

Karanlık bir düş sahnesinde,

tekrar bu hep tekrar:,

''Gök ve yeryüzü, hiç aranmayan.Yaşam.''

''-Gerçekten bu mu? ''

Beyazında ılık

Soğuyor mu, ve kayıp ve uzak..

yine Evet

''-Ve soğuyor düş..''

II..

''Yeniden görünüyor ışık çatı direğinde.Salonun iki ucundan birleşiyor anlamsız bezekler, uyumsuz yükseklikler.Efriz kesiklerinin, atmosfer kuşaklarının ve yerbilimsel ilineklerin ruhsal ardışıklığıdır gece bekçisinin karşısındaki duvar.Her görünüşten, her kişilikten insanlardan oluşan duygusal toplulukların yoğun ve hızlı düşü.''

III.

Ve belki yeniden eskiye dönebilmek

şüphesi

tüm umut..:,

''Kara ocağın kapağı, gerçek güneşi kumsalların:Ah! 

Büyünün kuyuları: bu kez, tanın biricik görünümü..''', 'Arthur Rimbaud ile “BEN” i “BİR BAŞKASI” OLMAKLARA DAİR SESLENİŞ, KAPATMAK HESAPLARI, YOLA ÇIKIŞ LARDA: Vakti geldi edilgin hesapları, Fatur...', ARRAY['Türk Edebiyatı','Şiir','Kadir Üçvet']::text[], 8.5, '{"poet":"Kadir Üçvet","poet_slug":"kadir-ucvet","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/mimesis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O(o)', 'o-o-fatih-kuyucu-7h391', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'An gelir kıvranır insan 

Ölüme ramak var 

Taş kesilse bu beden 

Dil de tek kelime o var', 'An gelir kıvranır insan  Ölüme ramak var  Taş kesilse bu beden  Dil de tek kelime o var...', ARRAY['Türk Edebiyatı','Şiir','Fatih Kuyucu']::text[], 8.5, '{"poet":"Fatih Kuyucu","poet_slug":"fatih-kuyucu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/o-o-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sanrı', 'sanri-kadir-ucvet-02niw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dalgalardı kıyıdan köşelere vuranlar, dalgaları aşmaktı yerleşik 

amaçlar.. Elini eteğine değdirmekti, taşların altına giren suları avuçlamaktı sevgiler, arayışlara köpükleri karıştırmaktı belki. 

Bir yeşili çalmaktı maviye ve hüzne.. Dalgaları bırakıp, özlemlere kaçıştı bir kumsal boyu, geriye.. Bir zeytin bahçesini düşlemekti, dalgaların üstünden bakıp, sahile..Yalnızlığına yazgılı kaderleri ertelemekti, kumsal kalabalığında azalan seslerine şarkıların, sözler aramaktı.. 

Sakinini bulmaktı hızlı gidenlerin. Erteleyişleri dizginlemek ve bir fırtınaya daha hazır olmaya yatmak, gerekçesiydi düzlemsiz düşlerin. Onun için yaşam düşlerdeki değildi.. Askılar hep asılandı, asılı''nan olamayacak olandı. Oysaki sorumluluklarını asmak ve düşlerindeki düzlemi bulmak için kaçmak, bir deniz kıyısına varmak ve sadece karşı kıyıya bakmak vardı. Umuttu, vardı....Oysa askı hep asılandı... 

Bir yer aramaktı. Kaçamayışlarını saklayacak. Beğenilesi ama sıkça vazgeçilesi, çokça.. Yokça. 

Görülesi bir yer. Görülünce kaçılası...Görülmelere kıyılamayası, bir yer... Bir bakış, açısı.. 

Umutların hiçlere ertelendiği...', 'Dalgalardı kıyıdan köşelere vuranlar, dalgaları aşmaktı yerleşik  amaçlar.. Elini eteğine değdirmekti, taşların altına giren suları avuçlama...', ARRAY['Türk Edebiyatı','Şiir','Kadir Üçvet']::text[], 8.5, '{"poet":"Kadir Üçvet","poet_slug":"kadir-ucvet","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sanri-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlem Sevmekle Başlıyor...', 'ozlem-sevmekle-basliyor-fatih-kuyucu-bsdbz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Özlem sevene yakışır... 

Sevmek yaşamaya

Kal benimle desem geç 

Gel desem erken 

Özlemler yeşerirken 

Çaresiz kıvranmalar 

Özlem sevmekle başlıyor...', 'Özlem sevene yakışır...  Sevmek yaşamaya Kal benimle desem geç  Gel desem erken  Özlemler yeşerirken  Çaresiz kıvranmalar  Özlem sevmekle ba...', ARRAY['Türk Edebiyatı','Şiir','Fatih Kuyucu']::text[], 8.5, '{"poet":"Fatih Kuyucu","poet_slug":"fatih-kuyucu","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/ozlem-sevmekle-basliyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin Eserin', 'senin-eserin-umit-koral-y3gur', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Nice gece yarıları sıçrayarak uyanıyorum

....Nice geceler huzurla uyumanın,

Ne demek oldugunu unuttum

...İşte güneş doğuyor yeni güne.

Yine aynı şeyler

...Dayanılmaz kalp acılarıyla başlıyorum

Tatsız tuzsuz bir hayat işte...

....Nede olsa senin eserin..', 'Nice gece yarıları sıçrayarak uyanıyorum ....Nice geceler huzurla uyumanın, Ne demek oldugunu unuttum ...İşte güneş doğuyor yeni güne. Yine ...', ARRAY['Türk Edebiyatı','Şiir','Ümit Koral']::text[], 8.5, '{"poet":"Ümit Koral","poet_slug":"umit-koral","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/senin-eserin-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anı', 'ani-kadir-ucvet-cf8kq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Herkesin işi çıktı birdenbire

yağmurdu

aniden bastırır gibi...ydi.

Halbuki en zor a''nı''mdı

ya''ra''rına koşmanın getirisini

almaklığım zamanıydı

kırk yıldır bekliyordum

yalnızlığımda

sırılsıklam kalışların şemsiyesi

elimdeydi

gülümse! dedi fotoğrafçı

ıslakça...

Resminde niye dudaklarin ıslak çıkıyor

demiştin,hani...', 'Herkesin işi çıktı birdenbire yağmurdu aniden bastırır gibi...ydi. Halbuki en zor a''nı''mdı ya''ra''rına koşmanın getirisini almaklığım zamanıy...', ARRAY['Türk Edebiyatı','Şiir','Kadir Üçvet']::text[], 8.5, '{"poet":"Kadir Üçvet","poet_slug":"kadir-ucvet","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ani-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalabalıklarda', 'kalabaliklarda-kadir-ucvet-oxl71', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sesini duyacağım o anda

ne kadar

da

yalnız olduğumu

anlayacaktım

biliyordum,

kalabalıklarda..', 'Sesini duyacağım o anda ne kadar da yalnız olduğumu anlayacaktım biliyordum, kalabalıklarda.....', ARRAY['Türk Edebiyatı','Şiir','Kadir Üçvet']::text[], 8.5, '{"poet":"Kadir Üçvet","poet_slug":"kadir-ucvet","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/kalabaliklarda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'KusLar', 'kuslar-ali-aydogan-pqwyk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ucun kuslar yarın gözlerine götürün kalbimi

kırık kanatlarınıza yukleyin caresiz yuregimi

anlatın ona benim aglayan gözlerimi 

onsuz kaldıgımda agladıgımda sizlerdiniz yanımda olan

kalemim kalmıstı onsuz yuregim yarımdı onsuz 

onlarıda anlatın anlatın kuslar 

yuregimdeki cıglıkları duyansınız kuslar 

derdime derman kalbime care

götürün yuregimi yar eline bırakın kuslar

bakın gözlerine bir damla yas varmı 

aglıyormu mektuplarında gözyaslarımla 

yazıyorum derdi simdi aglıyormu bakın kuslar

alın götürün ömrümü verin ona kuslar 

kalmasın sevdaları yarım kalmasın kimsesiz

kalmasın umutları bir gece yarısı 

kalmasın gözleri yolda verin ömrümü kuslar

götürün kuslar dilimi ona söyleyemiyorum 

söylüyemiyorum derdimi kaldım kendimle 

kaldım kendimle basbasa bir onsuzum

anlarmı halimde kuslar anlarmı beni anlarmı kuslar

caresiz kalmısım kuslar cıldıracagım 

agladım sızladım dizlerine kapandım kuslar 

yinede dönmüyor geri işte halim kuslar

aglıyorum şimdi kuslar bir zalim ardından

dönmüyor geri dönmüyor dönmüyor', 'ucun kuslar yarın gözlerine götürün kalbimi kırık kanatlarınıza yukleyin caresiz yuregimi anlatın ona benim aglayan gözlerimi  onsuz kaldıgı...', ARRAY['Türk Edebiyatı','Şiir','Ali Aydogan']::text[], 8.5, '{"poet":"Ali Aydogan","poet_slug":"ali-aydogan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/kuslar-39-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Miş..ti geçmiş zaman', 'mis-ti-gecmis-zaman-kadir-ucvet-kx42c', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'I.

Bir

Zaman dilimini

                         hınzırca 

                         çatallayıp,

                          yedi adam..

Bunu hergün yaptı.

En son göründüğü sahnede

Tüm sevdikleri,çatalıyla

                            pizzası nın arasında

                            dişlen MİŞ..Tİ. 

II.

Bir

Mavi düşlü kadın sevmişti.

En maviye ve

sakin dönenen balık gibi

Turkuazına yeşilin,görürcesine! ,

dönüp

           etrafında

                           kadının

Sadece düşünün mavi olduğunu

                            görebil MİŞ..Tİ...', 'I. Bir Zaman dilimini                          hınzırca                           çatallayıp,                           yedi adam.. Bunu her...', ARRAY['Türk Edebiyatı','Şiir','Kadir Üçvet']::text[], 8.5, '{"poet":"Kadir Üçvet","poet_slug":"kadir-ucvet","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/mis-ti-gecmis-zaman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamak', 'yasamak-kadir-demirel-ye3qq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yıllar önce

Bir dost

Ölümüne varım

Demişti

Yıllar sonra

Akıllandım

Ölümüne 

Yokum ben

(Ankara,27.09.2005)', 'Yıllar önce Bir dost Ölümüne varım Demişti Yıllar sonra Akıllandım Ölümüne  Yokum ben (Ankara,27.09.2005)...', ARRAY['Türk Edebiyatı','Şiir','Kadir Demirel']::text[], 8.5, '{"poet":"Kadir Demirel","poet_slug":"kadir-demirel","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yasamak-158-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Görüngü', 'gorungu-kadir-ucvet-hrfpp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aşk sandığın şey yanıltıcıdır

Bazen yadırgatıcı.

Bir beğeni (ve/veya) 

Bir gizemin ötesinde sonsuz,

ümit vaadeden şey,bağlayıcıdır

Bazen bağdaştırıcı...

Üzüm sandırırlar sana

Bir a priori (ve/veya) 

Bağsız ve bağlantısız (o) ağacı..

Ve meyvesini yemeden

anlayamazsın,

Üzüm sanırsın

Acıdır..(Ve/veya) 

Bazen acıtıcı', 'Aşk sandığın şey yanıltıcıdır Bazen yadırgatıcı. Bir beğeni (ve/veya)  Bir gizemin ötesinde sonsuz, ümit vaadeden şey,bağlayıcıdır Bazen bağ...', ARRAY['Türk Edebiyatı','Şiir','Kadir Üçvet']::text[], 8.5, '{"poet":"Kadir Üçvet","poet_slug":"kadir-ucvet","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/gorungu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidersen Eğer..!', 'gidersen-eger-hasan-basri-kale-hzd1g', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'gidersen eğer

susuz değirmene döner dünya

gidersen... 

garip kalır mevsimler

yoksan...

boşa bekler geceler sabaha varmak için

gün hiç doğmaz ki o zaman

korkarım karanlıklardan

sensizliğin sonu yok

geceler uzun

geceler yalnız

gün sensiz kalır

bitmez bu çile

...............gitme

gül yüzlüm

gülüm..

gülen yüzüm..

...............GİTME..! 

03/09/2005 istanbul', 'gidersen eğer susuz değirmene döner dünya gidersen...  garip kalır mevsimler yoksan... boşa bekler geceler sabaha varmak için gün hiç doğmaz...', ARRAY['Türk Edebiyatı','Şiir','Hasan Basri Kale']::text[], 8.5, '{"poet":"Hasan Basri Kale","poet_slug":"hasan-basri-kale","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/gidersen-eger-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İhanetin İzleri', 'i-hanetin-i-zleri-i-sa-tekin-j1skc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bakma bana öyle

Ağaran saçlarıma

Alnımdaki kırışıklara

Gözümdeki halkalara

Dökülen dişlerime

Bunlar hayatımın biyografisidir

Acı çekmenin 

Hasret çekmenin

İhanete uğramanın

Yalnız kalmanın 

İzleridir bunlar 

İşkencede zindanda 

Tez yorulanların

Erken bırakıp kaçanların

Arkamdan vuranların

Yarasıdır bunlar!', 'Bakma bana öyle Ağaran saçlarıma Alnımdaki kırışıklara Gözümdeki halkalara Dökülen dişlerime Bunlar hayatımın biyografisidir Acı çekmenin  H...', ARRAY['Türk Edebiyatı','Şiir','İsa Tekin']::text[], 8.5, '{"poet":"İsa Tekin","poet_slug":"i-sa-tekin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ihanetin-izleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Hayat Bu İşte*', 'hayat-bu-i-ste-umit-koral-b5gzl', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bizi yaşayamadıklarımız yargıladı hep

Yaşayamadıklarımızı aldık büyüttük içimizde

Birlikte yaşadığımız ''''anlar''''

Geleceğe dair beslediğimiz ''''umutlar''''

Büyüyen hayal kırıkları arasında kaybolup gitti

Bardağın dolu tarafını değilde

Hep boş tarafını gördük biz..', 'Bizi yaşayamadıklarımız yargıladı hep Yaşayamadıklarımızı aldık büyüttük içimizde Birlikte yaşadığımız ''''anlar'''' Geleceğe dair beslediğimiz ...', ARRAY['Türk Edebiyatı','Şiir','Ümit Koral']::text[], 8.5, '{"poet":"Ümit Koral","poet_slug":"umit-koral","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/hayat-bu-iste-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Gece', 'bir-gece-ali-aydogan-wkykl', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir Asi yuregim şimdi sazım telinde ve gece karanlıgında bir adım gözyası kaybolmus umutlarımın aciz arayısıydı belkide içimde bilmedigim bir buruk hüzün yagmurlar yagıyordu avcuma usul susl caresice dolastıgım sokakların taslarına yazdım adını ve bagıra bagıra yazdım içime süzülen bir parca ay ısıgı ısıtırdı sanki donuk kalmıs gülüşlerimi adımlarım kaldı bir sokak basında kırılmıs bir yuregin kanadıgı yerde donup kaldım sıtımı yasladım duvara elim düştü inatla cigaraya caresizim sensizim  kaybolmusum kendi kendime koca sehirde yanlızım bulunmazlardayım yuregim param parca bir kırık camlar ardınan gelen bir acı turkü kulaklarımı oksuyor sanki dura kaldım dinledim kendimi gördüm sanki sazın acı telinde can tıkanır oldu kaldım sensiz bir gece vakti', 'Bir Asi yuregim şimdi sazım telinde ve gece karanlıgında bir adım gözyası kaybolmus umutlarımın aciz arayısıydı belkide içimde bilmedigim bi...', ARRAY['Türk Edebiyatı','Şiir','Ali Aydogan']::text[], 8.5, '{"poet":"Ali Aydogan","poet_slug":"ali-aydogan","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/bir-gece-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuklarımız', 'cocuklarimiz-ozan-ozel-ew5xv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'çocuklarımız

kavgacı

küfürbaz

tacizkar

hırsız

küçüklerimiz...

sizlerlerle 

-kendimizle-

gururluyuz! ! 

ey insanlar! 

bir düşünelim

nereden gelip

nereye gidiyoruz...', 'çocuklarımız kavgacı küfürbaz tacizkar hırsız küçüklerimiz... sizlerlerle  -kendimizle- gururluyuz! !  ey insanlar!  bir düşünelim nereden g...', ARRAY['Türk Edebiyatı','Şiir','Ozan Özel']::text[], 8.5, '{"poet":"Ozan Özel","poet_slug":"ozan-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/cocuklarimiz-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizliğe Bir Dakika', 'sensizlige-bir-dakika-tekin-koc-0s4yf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sensizliğe bir dakika

Ve geri sayım başladı

Ellidokuz, Ellisekiz

Sayaç devam ediyor

Gideceğini bilmek zor geliyor

Seni benden ayıracak yerdeyiz

Gidişin zor nasıl alışırım bilmem

Son beş saniye

Son sözcükler ise senden geldi

Seni çok seviyorum

Hoşcakal sevgilim', 'Sensizliğe bir dakika Ve geri sayım başladı Ellidokuz, Ellisekiz Sayaç devam ediyor Gideceğini bilmek zor geliyor Seni benden ayıracak yerde...', ARRAY['Türk Edebiyatı','Şiir','Tekin Koç']::text[], 8.5, '{"poet":"Tekin Koç","poet_slug":"tekin-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sensizlige-bir-dakika-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özledim Seni Yar (Karıcığım)', 'ozledim-seni-yar-karicigim-umit-koral-kqts9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Özleminle baş edemiyorum artık

'''' GEL '''' desem gelirmisin? 

Kollarını acarak koşarmısın bana? 

Bu sevdayı benimle ötelere taşırmısın? 

Beni sensizlikten kurtarırmısın?', 'Özleminle baş edemiyorum artık '''' GEL '''' desem gelirmisin?  Kollarını acarak koşarmısın bana?  Bu sevdayı benimle ötelere taşırmısın?  Beni ...', ARRAY['Türk Edebiyatı','Şiir','Ümit Koral']::text[], 8.5, '{"poet":"Ümit Koral","poet_slug":"umit-koral","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ozledim-seni-yar-karicigim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gecenin Gündüze Aşkı', 'gecenin-gunduze-aski-tekin-koc-td5xx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben geceleri gündüze çaldım

Gündüzün o soğuk saatlerine

Hep düşündüm

Geceler olmasa, Sen olmasan 

Ben du dertleri yaşamadan 

Nasıl anlardım senin aşkını', 'Ben geceleri gündüze çaldım Gündüzün o soğuk saatlerine Hep düşündüm Geceler olmasa, Sen olmasan  Ben du dertleri yaşamadan  Nasıl anlardım ...', ARRAY['Türk Edebiyatı','Şiir','Tekin Koç']::text[], 8.5, '{"poet":"Tekin Koç","poet_slug":"tekin-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/gecenin-gunduze-aski-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yol', 'yol-cigdem-bir-genc-ehsj5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir kırlangıcın bilmeden

                                   kendine yolculuğuydu  aşk

nesirler boyu yol alıyordu esrik kanatları

                                                             döngüde…

ve nihayet  buluyordu

                                 bir şiirin ırmağında… 

yıkandıkça arınıyordu

                                 imgeler…

arındıkça yeniden kırlangıç oluyordu  her biri 

                                                                       garip! 

ve başlıyordu tekrardan

                                      yolculuk

gitmeler…

              gelmeler…

anlardan anılar türetmeler…

                 hepsi bu…', 'Bir kırlangıcın bilmeden                                    kendine yolculuğuydu  aşk nesirler boyu yol alıyordu esrik kanatları            ...', ARRAY['Türk Edebiyatı','Şiir','Çiğdem Bir Genç']::text[], 8.5, '{"poet":"Çiğdem Bir Genç","poet_slug":"cigdem-bir-genc","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yol-95-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*İçimdesin Hala*', 'i-cimdesin-hala-umit-koral-6xf7a', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Her giden gibi  iz bırakacağını

Ve sonra yok olacağını düşündüm

Olmadı olmadı yapamadım

Ben yüreğimden çıkardığımı sanırken seni,

Sen saklanmışsın bir yerlere..

Meğer hiç çıkmamışsın benden

Meğer çoğalmışsın kök salmışsın bedenimde

Şimdi yeniden çicek acıyorsun

Yayılıyorsun bütün bedenime

Şimdi seninle yaşadığımne varsa,

Resmi geçite çıkmış,

Tören kıtaları gibi önümden geçiyor

Bu kent, bu sokaklar

Köşedeki durak, sahildeki kayalar

Meydandaki simitci,

Kücük masaları olan aşıhan cafe

Hepsi ''''o burada'''' dermişcesine

Birer birer dikiliyor önüme

Söylermisin bütün bunları yaşarken

Nasıl silebilirim seni? 

Nasıl olmadığını varsayabilirim?', 'Her giden gibi  iz bırakacağını Ve sonra yok olacağını düşündüm Olmadı olmadı yapamadım Ben yüreğimden çıkardığımı sanırken seni, Sen saklan...', ARRAY['Türk Edebiyatı','Şiir','Ümit Koral']::text[], 8.5, '{"poet":"Ümit Koral","poet_slug":"umit-koral","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/icimdesin-hala-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dağlara Ver Sırtını', 'daglara-ver-sirtini-zeki-ergin-glwm0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'dağlara ver sırtını 

şiirlerde türkülerde

Ege sularında serinlesin yüreğin

sıcak kumsallarında huzur ara

bir gece vakti

gelebilir yanına

Afrodit güzelliğiyle aydınlatır

ısırgan otları saran yüreğin huzur bulur

dağlara ver sırtını

uzat denize ellerini

yukarda ay

su elinde

dilinde bir Ege türküsü

tütün ve şarap kokusu

ve sevdası yüreğinde

_gülpınar 1ağus05

_dağlara ver sırtını yt.haz09', 'dağlara ver sırtını  şiirlerde türkülerde Ege sularında serinlesin yüreğin sıcak kumsallarında huzur ara bir gece vakti gelebilir yanına Afr...', ARRAY['Türk Edebiyatı','Şiir','Zeki Ergin']::text[], 8.5, '{"poet":"Zeki Ergin","poet_slug":"zeki-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/daglara-ver-sirtini-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Hayattın', 'sen-hayattin-umit-koral-buuyk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hiç böyle unutsuz olmadım ben

..........Yaşama hiç bir zaman böylecesine,

Yılgın böylecesine soğuk bakmadım.

..........Soğuk kışta bile kimseciklerin

Görmediği güneş ısıtırdı beni

...........Karda çicekler açtırırdım

Çünkü sen vardın.

............Sen aşktın,sen maviydin,

Sen güneştin,sen rengarenk çicektin,

...........Sen kalbimdeki ateştin

Sen gülüşlerimin adı

..............Sen umutlarımın kaynağı

Sen hayatımın anlamıydın.

..............Hayır... hayır....

Sen Hayattın....', 'Hiç böyle unutsuz olmadım ben ..........Yaşama hiç bir zaman böylecesine, Yılgın böylecesine soğuk bakmadım. ..........Soğuk kışta bile kims...', ARRAY['Türk Edebiyatı','Şiir','Ümit Koral']::text[], 8.5, '{"poet":"Ümit Koral","poet_slug":"umit-koral","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sen-hayattin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdamın Adı da Kara...', 'sevdamin-adi-da-kara-i-brahim-ethem-bingul-mcs3b', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gözlerin isterse olmasın kara

Sözlerin merhem olsun yarama

Dostluğun mavi sularında

Dinle derdimi, sevdamın adı da kara

Sanma meylim sade gözü karaya

O bakışının menbaı var ya

Aşkıyla baktığı anda

Ne renk kalır, ne göz, aşktan başka...

Küllerim nasıl savrulmaz sen söyle

Bîçareyim dermansız, dururum böyle

Gülen yüzümün altında gizli kederim de

Bimem gerek kaldı mı başka söze...

www.iebingul.com', 'Gözlerin isterse olmasın kara Sözlerin merhem olsun yarama Dostluğun mavi sularında Dinle derdimi, sevdamın adı da kara Sanma meylim sade gö...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sevdamin-adi-da-kara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Su Ateş ve Ahlak', 'su-ates-ve-ahlak-sadik-altinkaynak-yztir', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Su Ateş Ve Ahlak



Arkadaş olmuşlar ahlak su ve ateş

Gezip tozarlarken kardeş kardeş

Biri demiş ki belki bir gün kayboluruz

Bu durumda birbirimizi nasıl buluruz

Su demiş bir şırıltı duyarsanız oradayım

Ateş demiş ben duman çıkan her yerdeyim

Konuşma sırası ahlaka gelince

Bir cevap vermiş ki inceden ince

Kaybolmamam için yalvarın Allah’a

Çünkü ben kaybolursam bulunmam bir daha

			Sadık ALTINKAYNAK', 'Su Ateş Ve Ahlak Arkadaş olmuşlar ahlak su ve ateş Gezip tozarlarken kardeş kardeş Biri demiş ki belki bir gün kayboluruz Bu durumda birbiri...', ARRAY['Türk Edebiyatı','Şiir','Sadık Altınkaynak']::text[], 8.5, '{"poet":"Sadık Altınkaynak","poet_slug":"sadik-altinkaynak","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/su-ates-ve-ahlak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur', 'yagmur-kemal-sik-cgpjx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir gün ölürsem  senden önce

Yağmur olacağım

Her yağışımda göz yaşlarını silmek için tane tane yağacağım

Her yağışımda saçlarını okşayacağım

Göz yaşlarınla karışıp dudağından öpeceğim

En sonunda kalbine varacağım

Her yağışımda sana beni hatırlatacağım

Seni seviyorum diye haykırışlarımı duyabiliyormusun

Her gök gürültüsünde sana seni seviyorum diye haykırışlarım

Bak neler söylüyorum sana

Bütün sesimle sana haykırıyorumseni seviyorum diye sadece Seni birtanem sadece seni

Yıldırımlar onlar benim dayanılmaz acılarım

Beni öldürdün ama  ben ölmedim

Yaralı bir kuş gibi çırpınıyorum 

Senmi zavallı, benmi bilmiyorum

Kara bulutlar acmasız bir dünyaya öfkemi gösteriyor

Adaletsizliklere eşitsizliklere

Hadi bir tanem bak güneş çıkıyor

Zamanımız tükeniyor artık

Sadece sen sen bana geliversen birtanem

Hadi geliver gözümde kalan yaşları siliver

Bak yağmur yağıyorrr

Sana neler söylüyor 

Dinle bak neler anlatıyor sana

Bir bilsen birtanem bir bilsen

Yağmurun dilinden anlayabilsen

Bilemezsin ki sen

Anlayamazsın sen sadece

Her yağmur yağdığında

Benden kaçtığın gibi yağmurdan kaçarsın 

Sen beni anlayamazsın anlayamazsın', 'Bir gün ölürsem  senden önce Yağmur olacağım Her yağışımda göz yaşlarını silmek için tane tane yağacağım Her yağışımda saçlarını okşayacağım...', ARRAY['Türk Edebiyatı','Şiir','Kemal Şık']::text[], 8.5, '{"poet":"Kemal Şık","poet_slug":"kemal-sik","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/yagmur-219-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sessiz Liman', 'sessiz-liman-mehmet-uluc-rghn6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ölü kuşlar getirir haberini dağların 

havlayan köpeklerin diyarı olur gök

kankırmızı umutlar yeniler kendini durmadan

şah damardan yakın olduğunu söyleyen bir tanrıyla 

kavgalıdır gerillalar', 'ölü kuşlar getirir haberini dağların  havlayan köpeklerin diyarı olur gök kankırmızı umutlar yeniler kendini durmadan şah damardan yakın old...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Uluç']::text[], 8.5, '{"poet":"Mehmet Uluç","poet_slug":"mehmet-uluc","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sessiz-liman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizim', 'sensizim-umit-koral-vhvyw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hayat geçiyordu ellerimin arasından

Bİr evin köşesinde başbaşayım yalnızlıkla

Yaşanmamış zamanlarım,öykülerim vardı

Mevsimleri hiç bulamadım hep kayıptı

Sensiz gecelerin yorgunuydum ben

Duvardaki gölgeler eşlik ediyordu bana

O gölgelerde sadece hayaldi...', 'Hayat geçiyordu ellerimin arasından Bİr evin köşesinde başbaşayım yalnızlıkla Yaşanmamış zamanlarım,öykülerim vardı Mevsimleri hiç bulamadım...', ARRAY['Türk Edebiyatı','Şiir','Ümit Koral']::text[], 8.5, '{"poet":"Ümit Koral","poet_slug":"umit-koral","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sensizim-38-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Maniler (93) ''Mudurnu''nun Oyası''', 'maniler-93-mudurnu-nun-oyasi-abdullah-atay-exxne', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Mudurnu’nun oyası

Güzellerin boyası

Sevip de sevilelim

Sevgi gönlün mayası...

Yosun taşta olurmuş

Akıl başta olurmuş

Yari gözel olanın

Gözü meşkte olurmuş...

Yüzük taşlı olurmuş

Güzel kaşlı olurmuş

Yari çirkin olanın

Gözü yaşlı olurmuş...

O gözler gamlı gözler

Sevdayla demli gözler

Nazlı yari gidince

Kederde nemli gözler...

Kalbin dilidir gözler

Aşkla doludur gözler

İki gönlün arası

Sevda yoludur gözler....

Yel bulutu sağınca

Gün tepeden ağınca

Bahçeye gel güzelim

Ay erkenden doğunca...

İnsandır beşer şaşar

Kah durulur,kah coşar

Paylaşmayı  bilenler

Nice gönülde yaşar...

Bak sararan yaprağa

Düşer kara toprağa

Bu dünya yalan imiş

Değmez mala tapmaya...', 'Mudurnu’nun oyası Güzellerin boyası Sevip de sevilelim Sevgi gönlün mayası... Yosun taşta olurmuş Akıl başta olurmuş Yari gözel olanın Gözü ...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Atay']::text[], 8.5, '{"poet":"Abdullah Atay","poet_slug":"abdullah-atay","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/maniler-93-mudurnu-nun-oyasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İmlerin Şafağı', 'i-mlerin-safagi-mehmet-tombuloglu-qre9t', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'güz boyu yürünmüş zamandır bu şiir

ayrı hecelerin ekleriyle bölünmüş 

sesinde taşıdığı umut 

kök salar tutkuyla pullanmış düşünceye 

arzunun etkisi altında kabuk bağlar yara

duygunun ruhunda kendi yolunu bulur söz

binlerce düşün heyecanından harlanan ateşle

aşkın yaşama sunduğu lûtfu kutlar, imlerin şafağı', 'güz boyu yürünmüş zamandır bu şiir ayrı hecelerin ekleriyle bölünmüş  sesinde taşıdığı umut  kök salar tutkuyla pullanmış düşünceye  arzunun...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Tombuloğlu']::text[], 8.5, '{"poet":"Mehmet Tombuloğlu","poet_slug":"mehmet-tombuloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/imlerin-safagi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gonuşmuyom Senle Gayrı', 'gonusmuyom-senle-gayri-ayhan-yavuz-acikgoz-umc04', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben karşında kekelerken niye gülüyon

Gonuşmuyom senle gayrı, küstüm ben sana

Senin için dağ aşardım, bunu biliyon

Gonuşmuyom senle gayrı, küstüm ben sana

Amminoğlu kur yapınca, cilve ediyon

Ben gelince yamacına, gaçıp gediyon

Bana deli, başkasına sevdiğim diyon

Gonuşmuyom senle gayrı, küstüm ben sana

Aklım yetmez okumağa, câhil galmışım

Taramamış saçlarımı, yele salmışım

Ne sevilmiş ne de bir kez murad almışım

Gonuşmuyom senle gayrı, küstüm ben sana

Sevmesen de alay etme, vardır onurum

Ben seni ta güccüklükten beri tanırım

Dün görenler kandırmışlar seni sanırım

Gonuşmuyom senle gayrı, küstüm ben sana

Adım Ayhan, nâmım deli, olsun sevdiğim

Gözyaşlarım kör kuyuya dolsun sevdiğim

Vermem artık sana çiçek, solsun sevdiğim

Gonuşmuyom senle gayrı, küstüm ben sana

(adana-26.06.2005)', 'Ben karşında kekelerken niye gülüyon Gonuşmuyom senle gayrı, küstüm ben sana Senin için dağ aşardım, bunu biliyon Gonuşmuyom senle gayrı, kü...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Yavuz Açıkgöz']::text[], 8.5, '{"poet":"Ayhan Yavuz Açıkgöz","poet_slug":"ayhan-yavuz-acikgoz","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/gonusmuyom-senle-gayri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmek', 'sevmek-salim-erben-e5u02', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Her uyandığımda seni 

Kollarımda bulmalıyım

Yüreğini yüreğimle çarpınca 

Bölünmez bir bütün  olarak 

kalmalıyım 

Gözlerden kalbe giden yolda 

İlk ve son yolcu o yolcun 

Ben olmalıyım

Vakit ayrılığın ismidir 

Işıklar göz bebeğinin yansıması

Sesin umuda yolculuğumdur

O sesindir ki

Seni bana dönüştüren 

Yokluğunsa ölümüdür baharımın

Sakın perişan halime acıma

Tek varisi hatıraların sensin', 'Her uyandığımda seni  Kollarımda bulmalıyım Yüreğini yüreğimle çarpınca  Bölünmez bir bütün  olarak  kalmalıyım  Gözlerden kalbe giden yolda...', ARRAY['Türk Edebiyatı','Şiir','Salim Erben']::text[], 8.5, '{"poet":"Salim Erben","poet_slug":"salim-erben","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sevmek-118-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hz.Mevlâna -2-', 'hz-mevl-na-2-alper-kuruk-kvqul', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Belh''te filizlenen tohum

Göçüp de kondu Konya''ya,

Hayırlı,nurlu bir doğum:

Mevlânâ gelmiş dünyaya...

Kökü, yeraltını sardı

Gövdesi,yeryüzünü bu ağacın,

Dallarında meyve vardı

Gözü doydu tokun,acın.

Kemâli aradı,durdu

Gönlü kimi zaman durgun,

Denizler gibi kudurdu

Hamdı,pişti,şimdi olgun.

Şems''te ışığını buldu,

Erkini ilahî  tacın,

Aşkıyla da sarhoş oldu

Faydası yoktu ilacın.

Pervaneler gibi döndü

Döndükçe kendini aştı,

Bütün ihtirası söndü

Güzelliklere ulaştı.

Ayrılığın acısını

Sevdiği Şems''inden tattı,

Buldu Yaratıcısını

Elemi üstünden attı.

Döndükçe döküldü bir bir

İnsanlığına yapışan

Kötülükler,gurur,kibir,

Para,servet,şöhret ve şan...

''Bir ayağım eksen ve dik,

Huzurunda başım eğik,

Gönlüm doygun,yeter aşım,

Külahımdır mezar taşım,

Uçan ak kaftan kefenim,

Göğe,yere açık elim

HAK''tan halka naklederim,

Canlar,erenler yoldaşım,

Dönerim Allah dönerim,

Sanki kutsal mey içerim

Dönüp kendimden geçerim

Af dilerim,şükrederim,

Ebediyete uçarım,

Geçici bir göç ederim

Bura değil ora yerim

Hadde uygun yer seçerim.

Fâniliği terkederim

Bâkiliğe yükselirim,

Alem arası seferim

Bir giderim,bir gelirim

Dünyada sınav veririm.

Tam dön! emriyle dönerim

Aslıma rücu ederim...

İşte buna SEMA derim...''

Kudüm,neyle ruhlar coştu,

Doğu,semaya alıştı,

Batı,Mesnevî''ye şaştı.

İsmin sınırları aştı.

Gel! çağrını duyan koştu

Canlar KONYA''da buluştu....

Hayat boştu,ölüm hoştu,

Ona ''Şeb-i Arûs''  muştu

Onda MEVLA''ya kavuştu...', 'Belh''te filizlenen tohum Göçüp de kondu Konya''ya, Hayırlı,nurlu bir doğum: Mevlânâ gelmiş dünyaya... Kökü, yeraltını sardı Gövdesi,yeryüzünü...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":61,"source_url":"https://www.antoloji.com/hz-mevlana-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haykırış', 'haykiris-umit-koral-xi1zc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Can ver bana ne olur

Can suyum ol yar

İceyim seni kana kana....

Damarlarımda vücudumda dolaş

Bütün bedenim senin olsun.

Dayanamıyorum sensizliğe artık

Ne olursa olsun..

Gözünü kapat bana doğru gel....', 'Can ver bana ne olur Can suyum ol yar İceyim seni kana kana.... Damarlarımda vücudumda dolaş Bütün bedenim senin olsun. Dayanamıyorum sensiz...', ARRAY['Türk Edebiyatı','Şiir','Ümit Koral']::text[], 8.5, '{"poet":"Ümit Koral","poet_slug":"umit-koral","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/haykiris-51-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geç Kalmadın mı', 'gec-kalmadin-mi-yavuz-dogan-j5841', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '''- İkinci el aşkından ne kaldıysa al geri

Çünkü senin ardından ''aşk'' taşındı içeri. -''

Tam unuttum demişken ne zaman gittiğini 

Unutmuşken hasretin aşkı erittiğini 

''Keşke''ler biriktirip ömrün sığınağında 

''Eyvah''larla ağlarken hasret sağanağında 

Riyakâr anıları kabus sanmadım sayıp 

İsmini bedduayla ahla anmadım sayıp 

''Vakitsiz bir düş gibi çıkıp geldim'' diyorsun 

''Sensiz ne yaşadıysam yıkıp geldim'' diyorsun. 

Ölmüş aşkına mezar kazdım geç kalmadın mı? 

Ardından bin bir sitem yazdım geç kalmadın mı? 

Kimdi hesapsız giden ömre bin ah sığdıran 

Bir Temmuz ortasında çöllere kar yağdıran? 

İhtiyati tedbir kim, sûkut-û lîsan kimdi 

Günahsız bir yüreği yargısız asan kimdi? 

Şimdi karşıma geçmiş sahte gülüşlerinle 

Simsiyah kabuslara yar olmuş düşlerinle 

''Hasretine kör kurşun sıkıp geldim'' diyorsun 

''Sensizlik çok ağırdı bıkıp geldim'' diyorsun. 

Beklemekten yoruldum bezdim geç kalmadın mı? 

Senden sonra kaç gönül gezdim geç kalmadın mı? 

Hüzzamı adres bilmiş dertli bir mızrap gibi 

Aşka tövbeler ettim ömre ızdırap gibi 

''Yan! '' dediğin gönlüme ''Sön! '' dedim söndü çoktan 

Toz pembe bulutlarım yağmura döndü çoktan 

Sense hâlâ eski bir şarkıyı söyler gibi 

Yorulmuş bir gönüle icâzet eyler gibi 

''Gözlerinden gönlüne akıp geldim'' diyorsun 

''Mazide ne var ne yok yakıp geldim'' diyorsun. 

Ömrüne intizarlar dizdim geç kalmadın mı? 

İsmini bir kalemde çizdim geç kalmadın mı? ...', '''- İkinci el aşkından ne kaldıysa al geri Çünkü senin ardından ''aşk'' taşındı içeri. -'' Tam unuttum demişken ne zaman gittiğini  Unutmuşken h...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Doğan']::text[], 8.5, '{"poet":"Yavuz Doğan","poet_slug":"yavuz-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/gec-kalmadin-mi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '* İstiyorum Seni *', 'i-stiyorum-seni-umit-koral-8ukf4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ne yaptın bana da  değiştim ben 

Nasıl sana bağlandım

Gözüm senden başkasını görmüyor

Kalbim senin nefesinle atıyor

Kulaklarım senin sesinle can buluyor

Dudaklarım seni istiyor! 

Ellerim senin bedenini arıyor 

Neredesin? 

Ver elini birlikte olalım..

Yapamıyorum sensiz olmuyor bir türlü..

Geçmişteki hatalarımızı unutup

Yeni bir sayfa acalım beraber....

Seni istiyorum ama sadece seniiiiiiiii! ! ! ! ! ! ! !', 'Ne yaptın bana da  değiştim ben  Nasıl sana bağlandım Gözüm senden başkasını görmüyor Kalbim senin nefesinle atıyor Kulaklarım senin sesinle...', ARRAY['Türk Edebiyatı','Şiir','Ümit Koral']::text[], 8.5, '{"poet":"Ümit Koral","poet_slug":"umit-koral","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/istiyorum-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Reşaranî Şiir ve Beyitsiler 27', 'resaran-siir-ve-beyitsiler-27-huseyin-avdic-i4nru', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Beyazlaşmak İstersen

Beyazlaşmak ister misin, ey kara-zenci adam? 

İnanırsan Allah''a, olursun kar gibi insan! 

******

Varlıkların İnançlıya Hoşamedisi

İyi ki varedildin sen ey imanlı insan! 

Sen olmasaydın, olamazdı bu güzel cihan.

******

Ölümden Sonra Kalan

Ölüm gelince, insanın elinden her şeyi alır.

Geriye yalnızca, yapılan sevap ve günah kalır.

******

Razı Olmalısın

Kısanın yanında uzunsun, uzunun yanında kısasın.

Allah''ın verdiği boy-bos nimetine razı olmalısın.

Berlin, Ağustos-Eylül 2005.', 'Beyazlaşmak İstersen Beyazlaşmak ister misin, ey kara-zenci adam?  İnanırsan Allah''a, olursun kar gibi insan!  ****** Varlıkların İnançlıya ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Avdic']::text[], 8.5, '{"poet":"Hüseyin Avdic","poet_slug":"huseyin-avdic","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/resarani-siir-ve-beyitsiler-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüzünün Kaçışı Gözlerimden', 'yuzunun-kacisi-gozlerimden-kamil-soylemez-7dhos', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yüzün belirdiği zaman

Ezik yaşamım üstüne

Neler unutulmuş geride

Hepsini bir,bir süzdüm

Yüzünün kaçışı gözlerimden

Dağlara,denizlere yansıyan

Meğer bir ışıkmışsın içimde

Renkli bir dünya görüşümün

Işığı yüzün

Benim bitti dediğimde

Sil baştan başlatışı hayatı

Renk körlüklerimin ilacı

Hiç ayak basmadığım bir dünya

Bir toprak,bir su,bir hava gibisin bana

Şimdi öyle korkuyorum ki biterse diye

Göz yaşlarım biter,coşkularım biter

Karşı koymuyorum o korkuya

Çünkü seviyorum seni korkularımda beni

Korkuları düşündükçe,yokluğunun

Biliyorum bu dakikalar kısa

Biliyorum silinecek bu korkularım göz bebeği

Hüznüm düştüğünde toprak rengi

Ama sen asla silinmeyeceksin

Çünkü ben sende doğdum

Sendedir ölüp,gitmek mutluluğum', 'Yüzün belirdiği zaman Ezik yaşamım üstüne Neler unutulmuş geride Hepsini bir,bir süzdüm Yüzünün kaçışı gözlerimden Dağlara,denizlere yansıya...', ARRAY['Türk Edebiyatı','Şiir','Kamil Söylemez']::text[], 8.5, '{"poet":"Kamil Söylemez","poet_slug":"kamil-soylemez","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/yuzunun-kacisi-gozlerimden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiyi bölüşmek', 'sevgiyi-bolusmek-ercan-akbay-3jmv3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Elleri üşümüştü,ellerinden tuttum

        Gözleri güldü.

        Dudakları üşümüştü,dudaklarını öptüm

        Bir sıcaklık yayıldı benden ona

        Gözleri güldü

        Kalbi taş değildi,eğilip dinledim

        Gizli kalmış bir özlem vardı

        Damarlarımda hissettim

        Gözleri güldü

        Saçları üşümüştü,kollarımla sardım

        Karlar eriyordu saçaklarda

        Gözleri güldü

        Sonra gözlerine baktım

         Bir sevinç yumağıydı yüzü

         Beraber güldük

         Yeni doğan bir dostluğun şafağında

         Biz sevgiyi bölüştük....

                                  İSTANBUL-1988', 'Elleri üşümüştü,ellerinden tuttum         Gözleri güldü.         Dudakları üşümüştü,dudaklarını öptüm         Bir sıcaklık yayıldı benden on...', ARRAY['Türk Edebiyatı','Şiir','Ercan Akbay']::text[], 8.5, '{"poet":"Ercan Akbay","poet_slug":"ercan-akbay","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sevgiyi-bolusmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Yüzde Yalan Yok', 'bu-yuzde-yalan-yok-osman-karahasanoglu-i8pf2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Resulallahın; yüzünü görenler,

Bu yüzde, yalan yok demişler.

Çokları böyle,İslam’ı seçmişler.

Doğruluyla da, örnek lider.

12.08.2005', 'Resulallahın; yüzünü görenler, Bu yüzde, yalan yok demişler. Çokları böyle,İslam’ı seçmişler. Doğruluyla da, örnek lider. 12.08.2005...', ARRAY['Türk Edebiyatı','Şiir','Osman Karahasanoğlu']::text[], 8.5, '{"poet":"Osman Karahasanoğlu","poet_slug":"osman-karahasanoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/bu-yuzde-yalan-yok-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasret Türküsü', 'hasret-turkusu-osman-karahasanoglu-1fnq0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Karşımda durur,sıra sıra dağlar.

Gözü yaşlı anam sılada ağlar.

Hasret ateşi de,kalbimi dağlar.

Gözü yaşlı,anam sılada ağlar.

Bir ramazan bayramı,böyle geçti.

Gözü yaşlı anam,yaramı deşti.

Bu hasret böyle,nasıl bir hasretti.

Gözü yaşlı anam,yaramı deşti.

Bu bayramda,bir kuş olsam da  varsam.

Şefkatli ana,kucağına doysam.

Bir varıp,uzakları yakın kılsam.

Şefkatli ana,kucağına doysam.

Bu hasretler,elbet bir gün biter.

Yuvamızda vuslat,dumanı tüter.

Bu ayrılık artık,bizlere yeter.

Yuvamız da vuslat,dumanı tüter.

    

20.02.1996', 'Karşımda durur,sıra sıra dağlar. Gözü yaşlı anam sılada ağlar. Hasret ateşi de,kalbimi dağlar. Gözü yaşlı,anam sılada ağlar. Bir ramazan bay...', ARRAY['Türk Edebiyatı','Şiir','Osman Karahasanoğlu']::text[], 8.5, '{"poet":"Osman Karahasanoğlu","poet_slug":"osman-karahasanoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/hasret-turkusu-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kara Çarşamba', 'kara-carsamba-osman-karahasanoglu-qxpgo', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ekonomi nasılda, dibe vurdu.

Vatandaşın kesesi, birden kurudu. 

Acaba bu vurgun, nasıl bir vurgundu.

Devleti fırsatçılar da, nasıl soydu.

                  

Bir gecede milyarlar nereye kaçtı.

Fakirlikle milletin de, aklı şaştı.

Hayırlısı, Sezer kıvılcımı yaktı.

Hainler buna da, niçin çok ters baktı.

                 

Önceden gidişata, dikkat çekildi. 

Kadir icraatını, takdir eyledi.

İnsanlar mesuldür, elbet söz söyledi.

Bu işler, bu hale birden nasıl geldi.

	    

21.02.2001-Ankara', 'Ekonomi nasılda, dibe vurdu. Vatandaşın kesesi, birden kurudu.  Acaba bu vurgun, nasıl bir vurgundu. Devleti fırsatçılar da, nasıl soydu.   ...', ARRAY['Türk Edebiyatı','Şiir','Osman Karahasanoğlu']::text[], 8.5, '{"poet":"Osman Karahasanoğlu","poet_slug":"osman-karahasanoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kara-carsamba-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akşam Sefaları', 'aksam-sefalari-kiymet-sonmez-ypvb8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çiçeklere bakıyorum 

Akşam sefalarına

Hem bakıyorum,

Hem de konuşuyorum onlarla

Tohumlarını topluyorum

Sarısından,pembesinden,beyazından

Birde kendi zayıflığımıza kızıyorum

O çiçekler bile daha sadık

Yaradan onlara akşam açın demiş,

Yaradanın dediğini yapıyorlar

Gündüz kapanıyorlar,

Akşam açıyorlar.

Sürekli de tohum veriyorlar

Yeniden yeniden üremek için

Bugün canım istemiyor demiyorlar

Oysa dil vermemiş Rabbim,

Akıl vermemiş,

Yürek vermemiş,

Kulak vermemiş onlara.

Bunlardan yoksun olarak yaşıyorlar,

Bizlerde bunların hepsi var,

Ama biz ne kadar sadığız  bizi Yaradana

Bize verilen nimetleri görmezlikten geliyoruz,

Verildiği halde şükretmiyor,

Hatta zaman zaman küfrediyoruz.

Yazık,

Şu küçücük, narin 

Akşam sefaları kadar olamıyoruz....', 'Çiçeklere bakıyorum  Akşam sefalarına Hem bakıyorum, Hem de konuşuyorum onlarla Tohumlarını topluyorum Sarısından,pembesinden,beyazından Bir...', ARRAY['Türk Edebiyatı','Şiir','Kıymet Sönmez']::text[], 8.5, '{"poet":"Kıymet Sönmez","poet_slug":"kiymet-sonmez","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/aksam-sefalari-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kur’an  Hazinesi', 'kur-an-hazinesi-osman-karahasanoglu-6y297', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bizlere Kur`anı

Gönderdin Yarabbi 

Okuyun Kur`anı

Buyurdun Yarabbi 

Kuru, yaş ne varsa 

Hepsi de sendedir 

Şifa kalbin darsa

Kur`an ilmindedir

Kıyamete kadar 

İnsana rehbersin 

Onsuz dünya hep dar

Oku huzur versin

Elbet necat oldun

Tabi olanlara

Kalbimize doldun

Hakkı bulanlara 

18.08.1994', 'Bizlere Kur`anı Gönderdin Yarabbi  Okuyun Kur`anı Buyurdun Yarabbi  Kuru, yaş ne varsa  Hepsi de sendedir  Şifa kalbin darsa Kur`an ilminded...', ARRAY['Türk Edebiyatı','Şiir','Osman Karahasanoğlu']::text[], 8.5, '{"poet":"Osman Karahasanoğlu","poet_slug":"osman-karahasanoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kur-an-hazinesi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim Fukaram', 'benim-fukaram-osman-taspinar-qnlor', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ayın onbeşinde alır maaşı

Ayın onaltısında ağrır başı

Onyedi de döker gözlerden yaşı

Memurum memurum benim fukaram

Bakkal,kasap,manav bekler sırada

Ev sahibi canavar durur kapıda

Kaynana gelmişte biz de yatıda

Memurum memurum benim fukaram

Oğlan kalem, defter,harçlık parası

Hanım evde üst baş mutfak parası

Belini bükerde taksit parası

Memurum memurum benim fukaram.

Enflasyonla boğuşur,kemer sıkarsın

Yaşamaktan usanır candan bıkarsın

En sonunda fıttırıp ziller takarsın

Memurum memurum benim fukaram.', 'Ayın onbeşinde alır maaşı Ayın onaltısında ağrır başı Onyedi de döker gözlerden yaşı Memurum memurum benim fukaram Bakkal,kasap,manav bekler...', ARRAY['Türk Edebiyatı','Şiir','Osman Taşpınar']::text[], 8.5, '{"poet":"Osman Taşpınar","poet_slug":"osman-taspinar","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/benim-fukaram-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kurtulursun', 'kurtulursun-osman-karahasanoglu-x6q41', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Allah’a,kul olursan.

Kalmaz, hiçbir tasan.

Hakkı, her an ansan.

Daima,huzurda olsan.

Manevi,saltanata konsan.

Sıkıntılardan,kurtulsan.

	

Tuzla /İstanbul

30.08.1997', 'Allah’a,kul olursan. Kalmaz, hiçbir tasan. Hakkı, her an ansan. Daima,huzurda olsan. Manevi,saltanata konsan. Sıkıntılardan,kurtulsan. 	 Tuz...', ARRAY['Türk Edebiyatı','Şiir','Osman Karahasanoğlu']::text[], 8.5, '{"poet":"Osman Karahasanoğlu","poet_slug":"osman-karahasanoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kurtulursun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dörtlük', 'dortluk-huseyin-gul-24tmk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gelsin bela sakınırsam gözümü

Felek çakıp, çakıp yaksın özümü

Bir güzele çevirmişim yüzümü

Gülsün diye gülüm ağlar yanarım

Hüseyin Gül', 'Gelsin bela sakınırsam gözümü Felek çakıp, çakıp yaksın özümü Bir güzele çevirmişim yüzümü Gülsün diye gülüm ağlar yanarım Hüseyin Gül...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Gül']::text[], 8.5, '{"poet":"Hüseyin Gül","poet_slug":"huseyin-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/dortluk-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Yüzle', 'ne-yuzle-osman-karahasanoglu-ru5yb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kitabım okununca,

Ben ne edeceğim.

Huzuru Rahmana,

Ne yüzle gideceğim.

Dört bir yandan günah,

Ateşiyle sarılmışım.

Tövbe,istiğfarım olmazsa,

Ben nasıl yaşarım.

03.01.1996-Girne-Kıbrıs', 'Kitabım okununca, Ben ne edeceğim. Huzuru Rahmana, Ne yüzle gideceğim. Dört bir yandan günah, Ateşiyle sarılmışım. Tövbe,istiğfarım olmazsa,...', ARRAY['Türk Edebiyatı','Şiir','Osman Karahasanoğlu']::text[], 8.5, '{"poet":"Osman Karahasanoğlu","poet_slug":"osman-karahasanoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ne-yuzle-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düş Yanığım', 'dus-yanigim-yusuf-safi-87mp4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Durup dinlenmeden yıkanıyorsun

karanlık gecenin yağmurlarında

Uzak bir kentte 

Sahibini bulamamış bir medeniyetin

Sahipsiz çocuğu 

Sen

Beyaz ama kirli ellerinle

Arınıyor sanıyorsun kendini

Günahlarından

Düş yanığı gecelerde 

Salıyorsun kendini şehvetin

O doymak nedir bilmez açlığına 

Düşler görüyorsun

Adem Havva misalı çırılçıplak.

Ruhun temiz bedenin kirli

Parçalanıyorsun iki tarafa

Dağılıyor saçların

Ve 

Birbirine geçiyor herşey

Kaynaşıyor kaybolanlar ayrı düşenler.

Sen teslim ediyorsun yine kendine günaha

Hem bedenin hem ruhun 

Yarın belki temiz uyanır diye', 'Durup dinlenmeden yıkanıyorsun karanlık gecenin yağmurlarında Uzak bir kentte  Sahibini bulamamış bir medeniyetin Sahipsiz çocuğu  Sen Beyaz...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Safi']::text[], 8.5, '{"poet":"Yusuf Safi","poet_slug":"yusuf-safi","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/dus-yanigim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz Daha Mutluyum', 'sensiz-daha-mutluyum-ahmet-ormanci-xeq29', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şimdi sensiz daha mutluyum.

Artık biri için boşa fedakârlıklar gerekmiyor,

Bir başkası için kolay kolay üzülmüyorum artık.

Hayatta düşünecek bir ikinci kişim yok.

Şimdi sensiz daha bir dincim.

Artık biri için boşa koşup yorulmuyorum,

Bir başkası için uykularım bölünmüyor artık,

Günlerce yol gitmem için birileri yok.

Şimdi sensiz daha hoş gönlüm.

Artık biri için boşa duyguların yorulmuyor,

Bir başkası için kahrolmuyorum artık,

Ulaşmak için bir pembe amacım yok.', 'Şimdi sensiz daha mutluyum. Artık biri için boşa fedakârlıklar gerekmiyor, Bir başkası için kolay kolay üzülmüyorum artık. Hayatta düşünecek...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ormancı']::text[], 8.5, '{"poet":"Ahmet Ormancı","poet_slug":"ahmet-ormanci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sensiz-daha-mutluyum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel Baharım Ol Sevdam', 'gel-baharim-ol-sevdam-kamil-soylemez-teilo', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Haydi gel bitanem

Gel desem sana

Gel de gir,gir hayatıma

Düşlerime girdiğin 

Ruhuma sindiğin kadar

Haydi gel gir

Gir ki bahar olayım

Kışları asıp

Yazlar da kalayım 

Sarıp,sarmalar da girermisin

Yıllara inat hayatıma

Baharlarmısın bağrımda

Bitanem yaparmısın bunları

Hıçkırıklarımı 

Yalvarışlarımı duyar da

Anlayış kılarmısın 

Bu aşık adam sana

Açarmısın kol kanatlarnı

Sarılıp,okşarmısın başımı

Girermisin bitanem

Canıma,kanıma 

Karanlık gecelerime ay

Günlerime güneş

Olurmusun bana

Silerek bulutlarımı

Yar olurmusun bana

Ne olur anlat 

Anlatsan bitanem

Bak gelip,geçiyor hayat

Göz yaşlarım da

Yüreğime girdiğin kadar

Canıma,kanıma kaynarmısın 

Bağışlarmısın bundan sonraki ömrünü

Benim bağışladığım kadar aşikar', 'Haydi gel bitanem Gel desem sana Gel de gir,gir hayatıma Düşlerime girdiğin  Ruhuma sindiğin kadar Haydi gel gir Gir ki bahar olayım Kışları...', ARRAY['Türk Edebiyatı','Şiir','Kamil Söylemez']::text[], 8.5, '{"poet":"Kamil Söylemez","poet_slug":"kamil-soylemez","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/gel-baharim-ol-sevdam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ömür Geçiyor', 'omur-geciyor-osman-karahasanoglu-crtie', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seyyar hapishanede,	

Ömür geçiyor.

Ömrümüzün her gün,

Bir taşı düşüyor.

Değerlendirdinse ne ala,

Ömür gidiyor.

Bu hayat işte şerde de,

Hayırda da bitiyor.

Ruh ceset sefinesinde,

Osman sefine de.

O hayattan sıkılmazsa,

Buradan ben de.

Ben bir gün gemiyi,

Terk edeceğim.

Ruhum da cesedimi,

Terk edince öleceğim.

Ölmeyeceğim,

Hayat değiştireceğim.

Faniden bekaya,

Elbette göçeceğim.

03.01.1996-Girne-Kıbrıs', 'Seyyar hapishanede,	 Ömür geçiyor. Ömrümüzün her gün, Bir taşı düşüyor. Değerlendirdinse ne ala, Ömür gidiyor. Bu hayat işte şerde de, Hayır...', ARRAY['Türk Edebiyatı','Şiir','Osman Karahasanoğlu']::text[], 8.5, '{"poet":"Osman Karahasanoğlu","poet_slug":"osman-karahasanoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/omur-geciyor-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mükemmel Sanatlar', 'mukemmel-sanatlar-osman-karahasanoglu-dnmbe', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ağaçtaki hep kuşlar.

Bak dinleyin çocuklar.

Çiçekteki arılar.

Dünya geçici yerdir.

Güzeliz gözünüzde.

Hepsi bize ne söyler.

Herkes kendi işinde.

Her şey onu gösterir.

Koşmayın peşimizde.

O Rahim ve Kerimdir.

Sanat var üstümüzde.

Sanatkarımız birdir.

4/10/2002', 'Ağaçtaki hep kuşlar. Bak dinleyin çocuklar. Çiçekteki arılar. Dünya geçici yerdir. Güzeliz gözünüzde. Hepsi bize ne söyler. Herkes kendi işi...', ARRAY['Türk Edebiyatı','Şiir','Osman Karahasanoğlu']::text[], 8.5, '{"poet":"Osman Karahasanoğlu","poet_slug":"osman-karahasanoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/mukemmel-sanatlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelemem', 'gelemem-ahmet-ormanci-5aul6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bekleme beni,

Gelemem artık,

Buluştuğumuz o yerlere.

Okulun kapısında bekleyen,

Ben değilim.

Yolum düşmez,

El ele dolaştığız caddelere.

Karşı kaldırımda bekleyen,

İyi bak, ben miyim? 

Söyledim sana gelemem,

Konuştuğumuz pencerelere.

Elinde şemsiye, istasyonda bekleyen,

Anlasana, ben değilim.

Bekleme artık,

Bekleme gelemem diyorum sana,

Başbaşa oturduğumuz kafelere,

Arkana dönüp, bakma boşuna,

Çayını yudumlayan,

Beni göremezsin bir daha.', 'Bekleme beni, Gelemem artık, Buluştuğumuz o yerlere. Okulun kapısında bekleyen, Ben değilim. Yolum düşmez, El ele dolaştığız caddelere. Karş...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ormancı']::text[], 8.5, '{"poet":"Ahmet Ormancı","poet_slug":"ahmet-ormanci","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/gelemem-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Anlar Sünnetten', 'ne-anlar-sunnetten-osman-karahasanoglu-j5k5w', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Öğle,akşam soframız,güzelce kurulur.

Herkes yemek saatinde,yerine oturur.

Enfes yiyecekler,önümüz de durur.

Herkes karnını,güzelce doyurur.

Bu gün otuz aralık,cumartesi sofradayız.

Çorba tasını,tam sünnet yaparız.

Süvari bey yeter der,tası kaptırırız.

Hayrola ne oldu,diye sorarız.

İstersen; bir tas daha çorba getirsin.

Temiz mi? Tasın dibini,deleceksin.

Bıraktık tası,kaşığı ne dersin.

Dilimden anlamaz ki,cevap veresin.

Dedim bir kaşık rızkıma,mani oldun.

İnsan mertebesine çıkacaktı,geri koydun.

''Dedi bıraksaydım,tası delik bulurdum.''

Cevap vermedim,çünkü bilmiyor sustum.

30.12.1995-Mersin.', 'Öğle,akşam soframız,güzelce kurulur. Herkes yemek saatinde,yerine oturur. Enfes yiyecekler,önümüz de durur. Herkes karnını,güzelce doyurur. ...', ARRAY['Türk Edebiyatı','Şiir','Osman Karahasanoğlu']::text[], 8.5, '{"poet":"Osman Karahasanoğlu","poet_slug":"osman-karahasanoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ne-anlar-sunnetten-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geç Şehir Yağmurları', 'gec-sehir-yagmurlari-yusuf-safi-9pyrx', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Acı ve hüzün kalıyorsun yine de bana 

Bildiğim bir şehrin 

Bildik insanı

Ama çıkmaz sokaklara 

Dönüyor senin yolculuğun

Sen bir seyyah bense

Peşin sıra sürüklenen

bir müfreze

Ve kabına sığmayan bir bir ten

Şimdi en ıssız sokakta bıraktın beni

Saçlarının en dağınıklığında.', 'Acı ve hüzün kalıyorsun yine de bana  Bildiğim bir şehrin  Bildik insanı Ama çıkmaz sokaklara  Dönüyor senin yolculuğun Sen bir seyyah bense...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Safi']::text[], 8.5, '{"poet":"Yusuf Safi","poet_slug":"yusuf-safi","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/gec-sehir-yagmurlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tutuştur Düşlerimi', 'tutustur-duslerimi-yusuf-safi-6cpyp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yağmayack genede yağmur

