INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Ne Özlemlerdi', 'o-ne-ozlemlerdi-salim-erben-0c607', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İkimiz taşımıştık zamanın umutlarını

Zamanların en ölmezini yaşamıştık,

Sık ormanların hışıltısında

Büyük kasırgaları çembere almıştık 

Mutluluğun sonunda

Ben uzak mesafelere aşkı taşımıştım 

Sense yakınlığıma alışıktın

Hatırlar mısın kırda koşardık 

Elele beraberce

Yağmurlar yağdırıp ıslanmıştık

En kurak mevsimde

Boy boy çocuklar büyütmüştük

Yanan yüreğimizde

Bütün şiirlerimde sen vardın

Senin için yazardım

Bir bakman yeterdi  Zalım

Kahve rengi gözlerinle', 'İkimiz taşımıştık zamanın umutlarını Zamanların en ölmezini yaşamıştık, Sık ormanların hışıltısında Büyük kasırgaları çembere almıştık  Mutl...', ARRAY['Türk Edebiyatı','Şiir','Salim Erben']::text[], 8.5, '{"poet":"Salim Erben","poet_slug":"salim-erben","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/o-ne-ozlemlerdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey Sonbahar', 'ey-sonbahar-ozel-arabul-27b7t', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '- Shine için-

                   

Ey sonbahar

Ey hüzünlü gözleri aşkın ve mevsimlerin

Ne zaman geldin

Güneşin üstüne düşen gölge

Ey sonbahar

Yalnız kadın 

Saltanatı dulluğun

Aklından gelip geçen bütün yazlar

Ayışığı kadar sadeydi

Ayışığı kadar temiz

Hatırladığın kış geceleri

Şimdi ağzında renklerin bütün tadı

Kızılın güneş tadı 

Mavinin su tadı

Beyaz zambakların utanmaz tadı

Hiçbir kuş barınamaz seninle 

Yüreğin en eski aşk kırgını

Boş limonluklar, kurutulmuş elmalar 

Kayıp gider, ürperdikçe zeytin ağaçları 

Eylül böylece ayrılığın ve ölümün mührüdür

Kaybolan zamanların 

Yaşayamadıklarımızın

Bu çılgın oyun, hayatlar içinde 

Devinip duran

Ortak bir düş salgını

İşte aşkım 

İşte ruhum

İşte ben

Ey sonbahar 

Savrulup duruyoruz 

Rüzgarlarınla

Yapraklarınla', '- Shine için-                     Ey sonbahar Ey hüzünlü gözleri aşkın ve mevsimlerin Ne zaman geldin Güneşin üstüne düşen gölge Ey sonbahar...', ARRAY['Türk Edebiyatı','Şiir','Özel Arabul']::text[], 8.5, '{"poet":"Özel Arabul","poet_slug":"ozel-arabul","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/ey-sonbahar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözyaşları Dantel Olmuş', 'gozyaslari-dantel-olmus-arda-ozdemir-l64zy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'En Yoğun Ayrılırken Birleşiliyor...

Metin Üstündağ (met-üst) 

Taş duvar; 

yosun tutmuş,

heybetli ve güçlü

yıkılmaz ama zayıf,

çepecevre sarmış

gizemli bir odayı...

duvarda bir pencere; 

saydamlığını unutmuş,

kirli mi kirli

özlemiş güneşi görmeyi,

geçmesini kalbinden ışığın.

gizemli bir odaya açılıyor...

ve bir tül; 

ışıl ışıl tertemiz.

hüzünlü bir beyazlık,

pencereyi ışıktan,

gizemli odayı sırsızlıktan

alıkoymanın vicdan azabında.

gözyaşları dantel olmuş.

büyülüyor onu bu gardiyanlıktan

azad edecek olanları.

umutla ve hüzünle bekliyor; 

büyüsüne kapılmadan

kendini aşacak olanı

tiksinmeden kirli camın açılıp

gizemli odanın sırsızlaştırılmasını...

Her ne kadar bilse de

ne olduğunu içeride

(daha önce açılmıştı o pencere)  

merak ediyor ölesiye

şimdi nasıl olduğunu gizemin

yılların nasıl onu değiştirdiğini...

Çıkması iyi mi olacak? 

bilmiyor... bilinmez

ama tül bekliyor

duvar bekliyor

pencere bekliyor

gizemli odanın gizemi

bekliyor...

merak, hüzün ve umutla...

Taş duvar

Parlak tül

hatta kirli pencere.

hepsinin unuttuğu bir nokta; 

Pencerenin ancak içeriden açıldığı.

ancak gizemli odanın gizemi

hüzünlü odanın hüznü

sırsızlaştıracak odayı.

ancak unuttukları başka bir nokta var; 

(daha öncede açılmıştı o pencere)  

Kimsenin aklına gelmeyen

Tülün gardiyanlıktan azadı için

pencerenin güneşe kavuşması için

odanın aydınlanması için

Beklenen O''nun gelmesi değil...

Duvar, pencere,tül,ben,sen,O

yanılıyor(um)    (sun)    (lar)  

O''nun gidişi aslında bekledikleri,

Hüzünle, umutla, merakla

UmSunLar

İçerdekinin çıkmasını

Çıkması iyi mi olacak? 

Bilmiyorum... Bilinmez...

14,03,05 ArDa Özdemir', 'En Yoğun Ayrılırken Birleşiliyor... Metin Üstündağ (met-üst)  Taş duvar;  yosun tutmuş, heybetli ve güçlü yıkılmaz ama zayıf, çepecevre sarm...', ARRAY['Türk Edebiyatı','Şiir','Arda Özdemir']::text[], 8.5, '{"poet":"Arda Özdemir","poet_slug":"arda-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":66,"source_url":"https://www.antoloji.com/gozyaslari-dantel-olmus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yonca I-II-III', 'yonca-i-ii-iii-arda-ozdemir-bz7hg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'I

İnsanoğlunun 

iyimserliği değil mi ki? 

binlerce yonca içinde

genetiği bozuk

dört yapraklıyı seçmesi...

25,04,2005

II

Üç kolu iki kafası varmış gibi

Toplumdan dışlandı, yazık! 

Üst tarafı 4 yapraklıydı 

31/03/2009

III

Binlercesi içinde

Bir tek onu ayirdi

Çimen rengi gözler

Usulcacık eğildi

Nazikcecik kopardi

İncecik tutuştur yakasına

Şans getirecekti

Yoncası ona

Geride kalanlar 

Ağlamadılar arkasından

Dört yapraklıydı

Allah kurtardı...

31/03/2009 

ArDa Özdemir', 'I İnsanoğlunun  iyimserliği değil mi ki?  binlerce yonca içinde genetiği bozuk dört yapraklıyı seçmesi... 25,04,2005 II Üç kolu iki kafası v...', ARRAY['Türk Edebiyatı','Şiir','Arda Özdemir']::text[], 8.5, '{"poet":"Arda Özdemir","poet_slug":"arda-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/yonca-i-ii-iii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzellik Beyindedir', 'guzellik-beyindedir-burhanettin-akdag-y1a9o', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Güzellik beyindedir

Karşılığı tende değil

Güzellik sevgidedir

Hissetmemek elde değil...

Güzellik duygudadır

Kelimelerde değil

Güzellik yürektedir

Ruhta, dilde değil...

(19.03.2005)', 'Güzellik beyindedir Karşılığı tende değil Güzellik sevgidedir Hissetmemek elde değil... Güzellik duygudadır Kelimelerde değil Güzellik yürek...', ARRAY['Türk Edebiyatı','Şiir','Burhanettin Akdağ']::text[], 8.5, '{"poet":"Burhanettin Akdağ","poet_slug":"burhanettin-akdag","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/guzellik-beyindedir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Révolution', 'r-volution-yasar-dogan-eaijf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'karşıdan karşıya

