INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Soğuk Düş', 'soguk-dus-ufuk-bayraktar-fdv94', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'en soğuğu hangisi biliyor musun; 

bir çocuğun son bakışı hayata.

pırıl pırıl gözlerden akan son damla gözyaşı

taşır o yaşanmamışlıkların yükünü.

en dayanılmazı ne biliyor musun; 

bir annenin çığlığı hastane koridorunda.

bir çığlık bin kere döner gelir çarpıp duvarlara,

bir yürek bin yerinden kanar.

en acısı ne biliyor musun; 

hayat vermek için dokunan ellerin değmiştir son defa o sıcak

ilk defa o soğuk bedene.

en acısı; 

bir annenin o soğuk bakışıyla yakıp tüketmesidir seni.', 'en soğuğu hangisi biliyor musun;  bir çocuğun son bakışı hayata. pırıl pırıl gözlerden akan son damla gözyaşı taşır o yaşanmamışlıkların yük...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Bayraktar']::text[], 8.5, '{"poet":"Ufuk Bayraktar","poet_slug":"ufuk-bayraktar","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/soguk-dus-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Takmaz Kimseyi Şair O Anda', 'takmaz-kimseyi-sair-o-anda-sabri-gunenc-tttrq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sakın şair olma derdi babam

bir zenaatın olsun evvela

çırak olsan bile yeter

tenekeci dayının yanında

ben şiir yazardım gazel boyunca.

Bırak şairliği bir yana derdi anam

boş iş bunlar akıllan uslan

şairlik yapar oğlum demek kolay mı

kız istemeye el kapısına varanda

ben şiir yazardım suna boyunca.

Şairler sevilmez derdi amcam

ortada kalırsın ezerler adamı 

sürüm sürüm süründürürler

cebin kuruş görmez yamalı pantolonda

ben şiir yazardım vaaz boyunca.

Bir martı uçarken yalardı denizi

sümüklü çocuk ağlardı günboyu

hamile kadın gururlanırdı yükünden

denizde balıklar hoplayıp zıplayanda

ben şiir yazardım boğaz boyunca.

Endişeye devam etti babam

anam yine ağlamakta

birileri küstü selamı kesti

birileri küfreder oldu sonunda

ben şiir yazardım ömür boyunca.

Kıssadan hisse ister ol hikaye bu ya

beş düşünüp bir söylerdi diyecek biri

kötü bir şairdi yazacak diğeri yorumunda

arkadan konuşmalar o da kimin umurunda

Yatarken şair musallada boylu boyunca...', 'Sakın şair olma derdi babam bir zenaatın olsun evvela çırak olsan bile yeter tenekeci dayının yanında ben şiir yazardım gazel boyunca. Bırak...', ARRAY['Türk Edebiyatı','Şiir','Sabri Günenç']::text[], 8.5, '{"poet":"Sabri Günenç","poet_slug":"sabri-gunenc","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/takmaz-kimseyi-sair-o-anda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vatan elden çoktan çıktı', 'vatan-elden-coktan-cikti-mikdat-bal-swwe0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Artık kimse ses etmesin

Vatan elden çoktan çıktı

Kalkıp beni söyletmesin

Vatan elden çoktan çıktı

Çok söyledik duymadınız

Sözümüze uymadınız

Uyumaya doymadınız

Vatan elden çoktan çıktı

Çoktan bitti pazarlıklar

Yapıldı hep hazırlıklar

Kazıldı tüm mezarlıklar

Vatan elden çoktan çıktı

Akıttılar yaşımızı

Bağladılar başımızı

Bitirdiler işimizi

Vatan elden çoktan çıktı

Bize kara giydirdiler

Boynumuzu eğdirdiler

Yerlere dek değdirdiler

Vatan elden çoktan çıktı

Fayda vermez son pişmanlık

Artık sökmez kahramanlık

Yandı kül oldu samanlık

Vatan elden çoktan çıktı

Mikdatî der çok üzgünüm

Kederliyim hem kızgınım

Şaşırmışım ben bozgunum

Vatan elden çoktan çıktı', 'Artık kimse ses etmesin Vatan elden çoktan çıktı Kalkıp beni söyletmesin Vatan elden çoktan çıktı Çok söyledik duymadınız Sözümüze uymadınız...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/vatan-elden-coktan-cikti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Bu Kasabanın Serserisi', 'ben-bu-kasabanin-serserisi-kibar-tavasav-sl10i', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ne zaman şiir yazmak gelse içimden 

yağmura teslim olmuş söğüt dalları gibi,

sallanır durur bir şeyler gam tellerimden 

hüzün bütün tenimde koşar, 

tutkular kemendini boynuma dolar 

sevdan bir baştan bir başa, ılık ılık akar bütünümden 

kesilmez akıntın hiç bir yerimden 

geçilmez ıslandığım ateşlerinden 

serseri bir aşk dolaşır bedenimin her yerinden 

kül kül olur gönül yollarım 

göz göz olur kalp damarlarım 

tutulmaz zamanlarda yıkıcı bir aşkı yaşarım 

dizelere sığmamda sayfalardan dışarı taşarım 

ben bu kasabanın serserisiyim 

bil ki şu beden ´´ BÜYÜK AŞKINLA ´´ gömülecek 

bunun altına koskoca bir imzamı basarım 

ben bu çilekeş dünyaya ait değilim 

asla değilim 

bilemem ki nerededir yerim 

kaç gece kendimi kaybedip de nerelerde gezindiğimi ne bilirim 

kaç gece mum ağaçlarının gölgesinde uyandım 

ışıl ışıldı her yanım, saydam gibi 

hani cam gibi 

kaç gece toprağın altından çıkardım elimi 

meğer oralarda gezinmişim bir solucan gibi 

kaç gece uyandım ki 

bir o yanda bir bu yanda gezerken buldum kendimi

ben bir tek seni sevmişim çılgın bir insan gibi 

bir türlü akıl erdirememişim 

ben neredeyim bilemem ki 

ben bir tek seni yazarım coşkunca pınar gibi 

ben bir tek seni yaşarım tıpkı bir dolunay gibi 

ben bir tek seni sayarım kendime kalbime kondurduğun tik taklar gibi 

ben bir tek seni severim 

bir tek seni 

belki kimse farkında değil 

kimse değil kimse 

ben aklımı bağ bozum gecelerinde şarap içer gibi aşkınla bozarım 

ekmek gibi, 

katık gibi seni yer içerde doyarım 

seni bulamadığımda girmediğim delik kalmaz 

toprağı eşelerim bir solucan gibi 

gökyüzünde ararım kanatlı bir karınca gibi 

denizlere dalarım yosunlar gibi 

seni emzikte süt bekleyen bir çocuk gibi ararım 

seni yeni doğmuş bir farenin yavrusu gibi bekler karnım aç yatarım 

seni özgürlüğe gıptayla bakan bir mülteci gibi sever yokluğunda özgürlüksüz yaşarım 

ben bu kasabanın serserisiyim 

seni yakarım güneş ışığım gibi kalbimde

seni yaşarım bıkmak tükenmek bilmeden koskoca bedenimde 

ben bu kasabanın serserisiyim

aşkına müptela dünyayı her gece bir yıkarım bir yaparım dizelerimde 

bin gece açım sana 

bin yıl belki de 

belki de sonsuza kadar sürecek 

bilemem, 

belki de 

ben bu kasabanın serserisi 

sana söyleyeceklerim var 

kaldır kaşlarını bak şu anda okuduğun eserine 

bak sana dökülen şu sevgime 

bak dağların saçlarını doladığım avuçlarımda nasıl senin adını zikrediyor be... 

nasıl yıldızlar duramıyor yerlerinde 

nasıl mevlitler de dua okunurda bütün kainat yatar secdeye 

bak sular nasıl çağlıyor sana 

bak yağmurlar nasıl ağlıyor sana 

bak kuşlar nasıl ötüyor 

toprak nasıl çimleniyor 

bebekler nasıl doğuyor 

bak insanlar nasıl ölüyor 

nasıl ölüyor 

nasıl ölecek 

sevgisiz, kör kütük sevgisiz be 

nasıl yaşıyorsun  gözlerin bu kadar kör mü dünyaya 

kör kütük sevgisiz 

bu sana ve bana reva mı Allah aşkına 

revamı duy da dön şaşkına 

gir eksenime de mutluluk çiçekleri açsın her yanında 

gülümsesin her bir yanın sabah akşam dünyaya 

yıksın aşk poyrazları ikimizi 

dönsün devran başımızda 

dönsün yaşam karşımızda 

içelim aşk masallarını bir dikişte 

dalalım aşkın deryasına 

yüzelim sabah akşam hiç çıkmadan 

bir gün değil, 

yüz yıl değil 

bir milyon yıl hiç bıkmadan 

tüket de geç sensizlik saniyelerini 

yık ta geç 

yıkıl da geç 

oy 

ooooy

ben bu kasabanın serserisi 

ay dokuz doğurur gözlerim düştükçe üstüne 

aşkın bin bölümlü olur şu yanık yüreğimde 

sevgin her yanımdan vurur hiç çekinmeden kalleşçe 

ben bu kasabanın serserisi 

aşkın hem enimden dokunur hem de boyumdan be 

ben bu kasabanın serserisi 

bak nasıl Kibar serildanları alüvyonlu aşk topraklarını sürüklüyor aşkların denizine yanık dillice 

aşkını süzüyorum eleklerden geçirerek elemine, boyuna, dikine, enine 

aşkın ile söylüyorum 

aşkın ile susuyorum 

aşkın ile ölüyorum 

aşkın ile gömülüyorum bir mum ağacının gölgesine 

ben bu kasabanın serserisi 

bir tek bunu çok iyi biliyorum 

ben seni çoook seviyorum 

ben bu kasabanın bıçkın serserisi

seni yazıyorum şiirlerimde

ben bu kasabanın  serserisi

seni taşıyorum ölene dek  yüreğimde

ben bu kasabanın sana sevdalı serserisi 

üşüyorum 

seni yakıyorum ısınmak için içimde', 'ne zaman şiir yazmak gelse içimden  yağmura teslim olmuş söğüt dalları gibi, sallanır durur bir şeyler gam tellerimden  hüzün bütün tenimde ...', ARRAY['Türk Edebiyatı','Şiir','Kibar Tavasav']::text[], 8.5, '{"poet":"Kibar Tavasav","poet_slug":"kibar-tavasav","theme":"Türk Şiiri","is_hero":false,"total_lines":116,"source_url":"https://www.antoloji.com/ben-bu-kasabanin-serserisi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kısmetim Filiz', 'kismetim-filiz-mustafa-dilki-zbcyk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bilmezsin ne kadar susuzum açım

Sevip sevilmeye hasretim Filiz

Gönlüme sultansın başıma taçım

İnan bana sensin kısmetim Filiz

Dünyayı yakarım tek bir sözüne 

Razıyım inan ki bin bir nazına 

Müsade etsen de yatsam dizine 

İşte orasıdır cennetim Filiz 

Harcarım yolunda olanlarımı 

Hoş gör sen uğrunda yalanlarımı

Bir bilsen hakkında planlarımı

Senle mutluluktur niyetim Filiz

Eğer sevmek suçsa karşı dursunlar

Zincirlere vurup hesap sorsunlar

İşkence yapsınlar boynum vursunlar

Varsın başım olsun diyetim Filiz', 'Bilmezsin ne kadar susuzum açım Sevip sevilmeye hasretim Filiz Gönlüme sultansın başıma taçım İnan bana sensin kısmetim Filiz Dünyayı yakarı...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Dilki']::text[], 8.5, '{"poet":"Mustafa Dilki","poet_slug":"mustafa-dilki","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kismetim-filiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk İle', 'ask-i-le-firuze-keles-8l2k5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Düşerim aşk uğruna 

Yeditepeden.

Sayarım yıldızları

Hiç üşenmeden.

Döner dururum,

Dört bir yan döner…

Işıklar yanar,

Işıklar söner…

Bir yol çizerim

Denizin yüzüne.

Ve uzanır tutarım

Mehtap çok yakın.

Kanarım her sefer

Deniz kızına, ama

Ufuklar bekliyor

Tutmayın sakın…

30.09.2005', 'Düşerim aşk uğruna  Yeditepeden. Sayarım yıldızları Hiç üşenmeden. Döner dururum, Dört bir yan döner… Işıklar yanar, Işıklar söner… Bir yol ...', ARRAY['Türk Edebiyatı','Şiir','Firuze Keleş']::text[], 8.5, '{"poet":"Firuze Keleş","poet_slug":"firuze-keles","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ask-ile-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ahh Bir Çocuk Olsam', 'ahh-bir-cocuk-olsam-turk-oger-koc-cdw5a', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'AH BİR ÇOCUK OLSAM

1-)

     Ne zaman sıkışsam dalarım düşlere, alır başımı giderim, akranı olurum dertlerimin…

ahh bir çocuk olsam 

doya doya 

kaçabilsem 

bir yerlere 

kar yesem 

karnım ağrısa 

annem 

okşasa başımı 

ne güzel olurdu 

ne güzel olurdu 

2-)

     Çocukluğumda kurtarmaz beni, dönerim devran gibi gerçeklerin içinde…

bisikletim 

hiç olmadı 

hiç olmadı 

öyle uzun uzun 

voltalara zamanım 

bir başından 

bir başına kentin 

yılan gibi 

kıvrılmalara 

bağdaş kurup 

ara sokaklarda 

zar atmalara 

3-)

     Yaralıdır hep hayallerim, yaşarken hep böyle öğrendim, derlerdi ki hep uyuz (yavuz)  itin yarası çok olur, yaralı (yavuz) uyuz it hiç görmedim….

misketlerimi kırdım 

okşanmalara inat 

şımartılmalardan uzak 

yaralar açtım 

çıplak baldırlarımda 

çalılara dolanarak 

4-)

    Kucağına almadı kimse beni, bildim bileli kendimi, daha da geriye kaçamadım hiç, adım şimdi kucak delisi….

ahh bir çocuk olsam 

bir ateş alsa beni 

gül yüzlü anam 

sarsa beni kollarına 

göğsü süt kokusu 

yüreği sevda 

bir sınıfa girsem 

kalem tutsam 

kırılmasa parmaklarım 

bir şiire mısra yazsam 

biri okusa beni 

biri okumasa 

sınıfta saysalar beni 

bir olsam 

birlik olsam 

karaya çalar mıydı 

sevdiklerim 

5-)

     Ahhhh bir çocuk olmasam diyeceğim anlarım çoğalsa, kaçmasam bir yerlerden, kaçmasam sevdiklerimden, yok yok bir çocuk olabilsem…

ahh bir çocuk olsam 

bir ağaca çıksam 

dal kırılmasa 

ben düşsem 

annem üzülmese 

canım yanmasa 

ben avutulmasam 

avutmalardan 

uzak kalsam 

ninnileri unutsam 

ahhh bir insan olsam 

ellerim ağlamasa 

ağlamasa güllerim 

yağmurlar yağsa 

güneş doğsa 

doğsa dünyama 

tütün sarar gibi 

ustaca 

şiirlerden öte 

yaşar olsam 

otursam 

düşünsem doya doya 

tutsam elini 

sevdiklerimin 

kırsam umutsuzluklarımı 

yarınların 

unutsam 

yalnız düşlerimi 

çıkarsam 

siyah beyaz 

düşlerden herkesi 

toy bir alay kursam 

doysam düşlerime', 'AH BİR ÇOCUK OLSAM 1-)      Ne zaman sıkışsam dalarım düşlere, alır başımı giderim, akranı olurum dertlerimin… ahh bir çocuk olsam  doya doy...', ARRAY['Türk Edebiyatı','Şiir','Türk Öğer Koç']::text[], 8.5, '{"poet":"Türk Öğer Koç","poet_slug":"turk-oger-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":89,"source_url":"https://www.antoloji.com/ahh-bir-cocuk-olsam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '* Yarim Güle Benzer *', 'yarim-gule-benzer-gulsen-senderin-hs3g2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yarim güle benzer al gülüşüyle

Gül açar misk saçar her seher vakti

Sinemi yandıran  al tutuşuyla

Aşk serer aşk derer her seher vakti.

Bir alev deryası gonca dudağı

Giz saklı gamzesi tutku odağı

Ruhuma dem katar sevgi otağı

Aşk serer aşk derer her seher vakti.

Gülşen bir tutkudur seven gönüle

Kokusu nağmedir şeyda bülbüle

Sevdaya al katar bin bir şevk ile

Aşk serer aşk derer her seher vakti.', 'Yarim güle benzer al gülüşüyle Gül açar misk saçar her seher vakti Sinemi yandıran  al tutuşuyla Aşk serer aşk derer her seher vakti. Bir al...', ARRAY['Türk Edebiyatı','Şiir','Gülşen Şenderin']::text[], 8.5, '{"poet":"Gülşen Şenderin","poet_slug":"gulsen-senderin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yarim-gule-benzer-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çile-Fikir Sancısı', 'cile-fikir-sancisi-taner-nisanci-plx0i', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Herkes oyunda oynaşta dururken

Can atmakmış ölüme, bile bile

Geceler sabaha selam verirken

Fikir sancısı çekmekmiş Çile

Turnalar sökün ederken yurduna

Dert içinde bin derdi katıp derdine

Omuz verip has beylerin merdine

Fikir sancısı çekmekmiş Çile

Ay şavkı vururken mehtap geceler

Aymazlara söz söylerken heceler

Hiç uğruna can verirken niceler

Fikir sancısı çekmekmiş Çile

Yüreğe saplayıp keskin hançeri

Kanlar damlarken beyinden içeri

Merhaba derken ölüme son çeri

Fikir sancısı çekmekmiş Çile

Doğudan batıya dünya dönerken

Yaralı bedende güneş sönerken

Bozkurt yüreklere hüzün sinerken

Fikir sancısı çekmekmiş Çile

Didişirken hak ve batıl düşünce

Cellatlar gerçeği kesip deşince

Hakimler verirken hükmü peşince

Fikir sancısı çekmekmiş Çile

Ağaran saçlarda yüzde çizgiler

Dilde söylenirken hazan ezgiler

İmtihan belli ki yazan yazgılar 

Fikir sancısı çekmekmiş Çile

01/10/2005', 'Herkes oyunda oynaşta dururken Can atmakmış ölüme, bile bile Geceler sabaha selam verirken Fikir sancısı çekmekmiş Çile Turnalar sökün ederk...', ARRAY['Türk Edebiyatı','Şiir','Taner Nişancı']::text[], 8.5, '{"poet":"Taner Nişancı","poet_slug":"taner-nisanci","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/cile-fikir-sancisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Düşündüm Durdum', 'seni-dusundum-durdum-mehmet-sait-akkus-j9iyz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Uyumadım dün gece

Seni düşündüm durdum

Boyu uzun beli ince

Bir dilbere vuruldum

Yağmur olup yağacağım

O bembeyaz tenine

Seni hep anacağım

bakarken senin resmine

Toz olaydım toprak olaydım

Serilseydim ayaklarına

Düşen yaprak olsaydım

Açılmış olan kollarına', 'Uyumadım dün gece Seni düşündüm durdum Boyu uzun beli ince Bir dilbere vuruldum Yağmur olup yağacağım O bembeyaz tenine Seni hep anacağım ba...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Sait Akkuş']::text[], 8.5, '{"poet":"Mehmet Sait Akkuş","poet_slug":"mehmet-sait-akkus","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/seni-dusundum-durdum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkı Tarif Edemedim', 'aski-tarif-edemedim-munevver-senol-f878z', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bana aşkı tarif et dediler,

Edemedim...

Öyleyse, resmini çiz dediler.

Siyahtan başka kalemle,

Çizemedim...

Niye öyle karamsarsın,

Hadi anlat bakalım dediler,

Sustum...

Sadece  sustum hiçbirşey,

Diyemedim...

Nasıl derdimki? ,

Ben hiç sevilmedim ki, seveyim.

Meğer hiç mutlu olamıyacakmışım, 

Nerden bileyim? 

Şansımı zorlamıyorum artık,

Razıyım kaderime,.

Bundan sonra sevsem ne olur,sevmesem ne? 

Tren kaçtı bir kere.

Bana aşkı tarif et dediler,

Edemedim...

Öyleyse resmini çiz dediler.

Siyahtan başka kalemle,

Çizemedim.

Kaderimi soruyorsanız eğer,

İşte onu, hiç değiştiremedim...', 'Bana aşkı tarif et dediler, Edemedim... Öyleyse, resmini çiz dediler. Siyahtan başka kalemle, Çizemedim... Niye öyle karamsarsın, Hadi anlat...', ARRAY['Türk Edebiyatı','Şiir','Münevver Şenol']::text[], 8.5, '{"poet":"Münevver Şenol","poet_slug":"munevver-senol","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/aski-tarif-edemedim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Masum Asker', 'masum-asker-sait-kucuk-xn56r', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ben çocukken

babamın aldığı

oyuncak tabancayla

kapsüller patlatırdım

büyüyüp asker olunca

komşu ülkelerin

insanlarına karşı

kullanmam için

komutanım elime

sahici mermiler ile

bir tüfek tutuşturdu', 'ben çocukken babamın aldığı oyuncak tabancayla kapsüller patlatırdım büyüyüp asker olunca komşu ülkelerin insanlarına karşı kullanmam için k...', ARRAY['Türk Edebiyatı','Şiir','Sait Küçük']::text[], 8.5, '{"poet":"Sait Küçük","poet_slug":"sait-kucuk","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/masum-asker-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'AŞK YANığı', 'ask-yanigi-dilek-egri-874ab', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '...yarınlarım kaderime emanet, iyi bak onlara alın yazım

..............ben delirmeye gidiyorum ne zaman dönerim bilinmez...! 

valizime ayrılıkları tıkıştırdım

en altta anılarım

yabancılık çekersem gittiğim yerde

arada bir çıkarır koklarım

kimse beni uğurlamaya gelmemiş

bu şehir beni yalnızca gülerken seviyor

sağolsun tek bir kuru ağaç var

sararıp kalmış bir iki yaprağını sallıyor

-istasyon bomboş

-raylar tespih gibi

-çekiyorum sabrımı

-birde sigaramı

kirpiklerim tutuştu

gözyaşlarım söndürmeye çalıştıkça yangını

dahada alevleniyor

külleri yüreğime yağıyor

içim dışım aşk yanığı

aşikar bir zavallılık var üstümde

devrilip düşüyorum mecalsiz bekleyişlere

elim göğsümü işaret ediyor; 

beni bulanlar bilsinler; ayrılığa...................d

.............................................................ü

.............................................................ş

.............................................................m

..............................................................e

..............................................................k 

.................................................................................böyle oluyor...! 

01/10/05', '...yarınlarım kaderime emanet, iyi bak onlara alın yazım ..............ben delirmeye gidiyorum ne zaman dönerim bilinmez...!  valizime ayrıl...', ARRAY['Türk Edebiyatı','Şiir','Dilek Eğri']::text[], 8.5, '{"poet":"Dilek Eğri","poet_slug":"dilek-egri","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/ask-yanigi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gün Batımı....', 'gun-batimi-omer-golge-vshm6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gün batımında hüzün erkek işidir..

Kimseler görmeden yuvarlanır

İki kirpik arası dert yağmurları

Yüreğine.......

Ve iner......

Dağ gibi sarsılmaz

Kartal yuvası doruklarda oyulmuş

Yıkılmaz....

Muhkem bir kale gibi benliğine

Yalnızlığın ağır darbesi

Gün batımındasın.......

Ne farkeder hangi mevsim olduğu

Allanmış.pullanmış,destanlaşmış..

Erkekliğinle...sarsılmaktasın

Birazdan yıkıverip bendini..

Gözlerinden taşıverecek

Yüreğinin ölü denizi.. farkındasın

Yaşam sakıncalı bir şiir gibi

Akıyorken gözlerimden mısra,mısra

Bunca işkence kan ve barut kokusu arasında

Kahretsin! ...her şeye rağmen...

Sen yine aklımdasın.

Vazgeç artık rol kesmekten 

Yiğidim.....

Geçilmez bir siper gibi dursanda

En kanlı kavgaların orta yerinde

Aslında...

Sen başını yaslayıp,ağlayacak

Bir çift diz aramaktasın.', 'Gün batımında hüzün erkek işidir.. Kimseler görmeden yuvarlanır İki kirpik arası dert yağmurları Yüreğine....... Ve iner...... Dağ gibi sars...', ARRAY['Türk Edebiyatı','Şiir','Ömer Gölge']::text[], 8.5, '{"poet":"Ömer Gölge","poet_slug":"omer-golge","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/gun-batimi-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Dünyâ Hepimizin', 'bu-duny-hepimizin-timur-i-likan-hdlbd', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu dünyâ hepimizin,çocuklarımızın,gelecek kuşakların

Kirletmeyelim tabiatı,yakmayalım ormanları,

Öksüz bırakmayalım hayvanları

Koruyalım çevremizi,sanâyi atıklarından,

Zehirli varillerden,önce kendimizden

Emânet aldık biz bu dünyâyı,

Çocuklarımızdan,gelecek nesillerden

Hıyânet etmeyelim emânete,

Tahrip etmeyelim doğayı,katletmeyelim ağaçları

Sahip çıkalım evrendeki tek evimize,

Dünyâ barınaktır,gönüllerimize,

Sevgilerimize,sevdiklerimize

Süs olur bu dağlar,ovalar,

Akarsular,ormanlar gözlerimize

Eşya olur ağaçlar,masa olur,dolap olur,

Kapı olur evlerimize

Çöp atmayalım denize

Bırakmayalım sintine atıklarını böylesine

Boşaltmayalım fabrika atıklarını

Derelere,göllere,denizlere

Sahip çıkalım dünyâmıza,geleceğimize

Gidecek,kalacak,yaşayacak 

Başka yerimiz var mı söylesenize

(1 Ekim 2005/İstanbul)', 'Bu dünyâ hepimizin,çocuklarımızın,gelecek kuşakların Kirletmeyelim tabiatı,yakmayalım ormanları, Öksüz bırakmayalım hayvanları Koruyalım çev...', ARRAY['Türk Edebiyatı','Şiir','Timur İlikan']::text[], 8.5, '{"poet":"Timur İlikan","poet_slug":"timur-i-likan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bu-dunya-hepimizin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Be Hey Şerefsiz', 'be-hey-serefsiz-ayhan-yavuz-acikgoz-gl5og', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Müslümanım dersin, ama tarafsız

Sahada işin ne koşmayacaksan

Git benim yanımdan, ''Be Hey Şerefsiz''

Benimle bu yolu aşmayacaksan

(adana-01.10.2005)', 'Müslümanım dersin, ama tarafsız Sahada işin ne koşmayacaksan Git benim yanımdan, ''Be Hey Şerefsiz'' Benimle bu yolu aşmayacaksan (adana-01.10...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Yavuz Açıkgöz']::text[], 8.5, '{"poet":"Ayhan Yavuz Açıkgöz","poet_slug":"ayhan-yavuz-acikgoz","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/be-hey-serefsiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lider Dubaide', 'lider-dubaide-vahdet-mehmet-gunes-w98v0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Güney şehrimin gözdesi

Sürükledin karasevdamızı,canevimizi

Düşsel sarayların merkezini

Süvaribirliği komutanın lokomotifiyle

Sonsuza kadar tutunduk bilgeligine

Aradık huzurlu günü göçebe güvercinin özğürlügünde

Müsaade verseler irademize,kanatlarımıza

Gİdeceğiz uzak çok uzak ülkere

Nedir bu! Rabbim şehrimde olmuşuz şehirsiz bir kere

Seviyoruz kültürümüzü sentezleşmiş tarihle

Tabiatıyla yorgun bedenimiz

Ekmek peşinde koşmaktan,uyurgezerlikten

Oldu mazlumiyet bitmedi sefalet

Vurmuş bizi derinden

Yüksek lidere muhtaç güney şehir

Olmalı  bir lider sencileyin amcazadem

Mavi dalgaları korkutan,yunuslar gibi süratli

Mahsur kalacağız yoksa! ! ! 

karanlıga düşmüş bir kafile gibi

Çelik duvarları tuş etmeli  Berlin duvarı  gibi

Panzerle,mirajla,misketle değil! 

Zihinsel karizmanla,bilgi haznenle, tecrübenle

Bilki duraksız boşluga düşmüş gülbahçesi şehrim

Her canlı, her cansız onulmaz yaralar aldı

Katran yolların ardında

Nice sene içinde güneşten ışık istedik

Vermedi bağrı yanık güneylime

Volkan sıcağını bulamadık eskilerde

Gel ve sakın gitmeyelim! elimizde meşale

Ey! geniş ovanın  öncüsü

Büyük özlemle bekliyoruz  seni! ! ! 

seni ki Mücahid  amcazadem  liderliğinle

7 yıldızlı gibi Dubainin  tahtına', 'Güney şehrimin gözdesi Sürükledin karasevdamızı,canevimizi Düşsel sarayların merkezini Süvaribirliği komutanın lokomotifiyle Sonsuza kadar t...', ARRAY['Türk Edebiyatı','Şiir','Vahdet Mehmet Güneş']::text[], 8.5, '{"poet":"Vahdet Mehmet Güneş","poet_slug":"vahdet-mehmet-gunes","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/lider-dubaide-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölümsüz Sevgi', 'olumsuz-sevgi-munevver-senol-a6cya', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dün,

Şöyle daldımda bir eski günlere.

Zaman tünelinde buldum ben beni.

Hey gidi günler dedim, kendi kendime.

Nerde kaldı o bitmez tükenmez sevgili.

Bebekteyim gel derdim hemen gelirdin.

Hiç bir menfaatinin olmadığını da bilirdin.

Sadece ve sadece, bir merhaba, tokalaşan iki el.

Oturduğumuz çay bahçesinde gelecekten konuşurduk.

Birde havadan sudan muhabbet işte.

Ora nere bebek nere, şimdi evliliklerde bile kalmamış,

Aman Allah''ım! 

şu büyük sevgiye bakarmısın bir kere.

Şimdi gözlerin kaldı aklımda sadece gözlerin.

Galiba yeşilmiydi ne? 

Ama ben bakamazdım utanırdım.

Bir daha ki sefere bakıcam derdim.

Ama göz göze gelirdik gene bakamazdım,

Çünki utanırdım.

Biliyormusun ikimizde kız çocuklarını çok severdik.

Olursa ilk çocuğumuz kız olsun derdik.

Evet benim kızım oldu 

Senin de iki oğlunun olduğunu duymuştum.

İşte bizim zamanımızda sevgi,  öyle saf öyle temizdi.

Bebekteyim gel derdim, hemen gelirdin.

Hiç bir menfaatinin olmadığınıda bilirdin

Sadece bir merhaba tokalaşan iki el.

Oturduğumuz çay bahçesinde gelecekten konuşurduk.

Bir de havadan sudan muhabbet işte.

Ora nere Bebek nere  şimdi evliliklerde bile kalmamış.

Aman Allah''ım! 

Şu büyük sevgiye bakarmısın bir kere.

Ne yazık  ki sevenler kavuşamıyor

Şu acımasız  kadere bakarmısın,

Bakarmısın bir kere.', 'Dün, Şöyle daldımda bir eski günlere. Zaman tünelinde buldum ben beni. Hey gidi günler dedim, kendi kendime. Nerde kaldı o bitmez tükenmez s...', ARRAY['Türk Edebiyatı','Şiir','Münevver Şenol']::text[], 8.5, '{"poet":"Münevver Şenol","poet_slug":"munevver-senol","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/olumsuz-sevgi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadındır Adı Yağmurun', 'kadindir-adi-yagmurun-orhun-basat-ztjkm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Can çekişmeler / mavi küskünü sularda 

Yılgın kıraçlarında gönlümün yılkı atları / yüzün 

Kanamaktır yaranın orgazmı 

Çabuk ölümlere iten 

Yenilgiler iç savaşlarımda 

Senle başlayıp bende biten 

Hiçlik sessiz duvarda resim 

Şimdi yangınlara tohum nefesim 

Ki yanardı geceler sesimizde 

Gün geldim derdi de / aldırmazdık 

Böyleydik iç içeyken 

Kördük dünyaya / sağırdık 

Döl tutmuş kelebek kadar 

Ölümü hafife alırdık 

Ak köpüklü mavi etekleri vardı denizin 

Ateşe yakın yaşardık 

(Çok sürmezdi bilirdik / bu yüzden aşk kesilirdik / ateş 

olurduk çoğu zaman kıvılcımı tenlerimizde / yangın bizi 

aşardı şehre bulaşırdı / seyrederdik / şiir dokurdu gözlerin 

imgeleri eskimiş şiirlerle uçlarından yakardık / 

hükümsüz kılardık zamanı) 

Geceyi gün kılan ışıkta vardık 

Ya şimdi / gece vakti 

yolu kendine çıkıyor herkesin 

isli camlarda yazan 

Güne teğet bir güncenin / 

İçinde adın yok artık senin 

Ak köpüklü mavi etekleri de denizin 

Var olan / yalnızca ekmek arası hazan... 

30.09.05', 'Can çekişmeler / mavi küskünü sularda  Yılgın kıraçlarında gönlümün yılkı atları / yüzün  Kanamaktır yaranın orgazmı  Çabuk ölümlere iten  Y...', ARRAY['Türk Edebiyatı','Şiir','Orhun Basat']::text[], 8.5, '{"poet":"Orhun Basat","poet_slug":"orhun-basat","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/kadindir-adi-yagmurun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kan Açar Çiçeğini', 'kan-acar-cicegini-sait-kucuk-aiktr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bir insanın sevgi dolu

yüreğinde güzelleşir bu dünya

vakt erişip

mevsim bahar olunca

aşk açar çiçeğini

aydınlığın bedelini

aydın düşünceli insanlar

bazen canıyla öder

kahbeliğin

kara saplı bıçağıyla vurulup

meydanlarda düşünce

kan açar çiçeğini', 'bir insanın sevgi dolu yüreğinde güzelleşir bu dünya vakt erişip mevsim bahar olunca aşk açar çiçeğini aydınlığın bedelini aydın düşünceli i...', ARRAY['Türk Edebiyatı','Şiir','Sait Küçük']::text[], 8.5, '{"poet":"Sait Küçük","poet_slug":"sait-kucuk","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kan-acar-cicegini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlâhi', 'i-l-hi-timur-i-likan-3l422', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ALLAH aşkıyla ürperir hemen gönüller

Hep onu tespih eder bütün yerler ve gökler

Âlemlerin Rabbı şânı yüce ALLAH

Yeri göğü inletir Lâ İlâhe İllallah

ALLAH''ı zikreder şakıyarak bülbüller

Sevgiyle dolup taşar imân dolu yürekler

Âlemlerin Rabbı şânı yüce ALLAH

Yeri göğü inletir Lâ İlâhe İllallah

Hz. Muhammed''i görmek ister bu gözler

Onun güzelliğine özenir gonca güller

Âlemlerin Rabbı şânı yüce ALLAH

Yeri göğü inletir Lâ İlâhe İllallah', 'ALLAH aşkıyla ürperir hemen gönüller Hep onu tespih eder bütün yerler ve gökler Âlemlerin Rabbı şânı yüce ALLAH Yeri göğü inletir Lâ İlâhe İ...', ARRAY['Türk Edebiyatı','Şiir','Timur İlikan']::text[], 8.5, '{"poet":"Timur İlikan","poet_slug":"timur-i-likan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ilahi-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Gemisi', 'ask-gemisi-alper-kuruk-j8m56', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sevgilerle yüklendi gemilerim

Sevgiyle dolup şişti yelkenlerim

Aşk denizinde bu ilk seferim

Fenerlerim bile aşk diye çaktı.

Öyle birgün geldi rüzgârım  durdu

Sandım gemiler karaya oturdu,

Yıldırımlar düştü,yer-gök kudurdu

Deniz engin,sahil ise uzaktı.

Yükü,safra gibi denize attım

Aklımsıra böyle kurtulacaktım,

Bir iskele bir sancak yana yattım

Sevgide boğuldum,gemiler battı...', 'Sevgilerle yüklendi gemilerim Sevgiyle dolup şişti yelkenlerim Aşk denizinde bu ilk seferim Fenerlerim bile aşk diye çaktı. Öyle birgün geld...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ask-gemisi-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdim..', 'sevdim-sacide-yaylaz-9fr36', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hani bir bahar günü,

Kırlarda gezinirsin  ya,

Yeni açan, papatyaların,

Lalelerin arasında,

Hani içine yaşama sevinci dolar ya,

İşte seni ben öylesi sevdim....

Hani ağaçlar çiçek açar ya,

Kuşlar konar ya dallarına,

En güzel şarkılarını,

Söyler ya,

Hani içine yaşama sevinci dolar ya,

İşte seni ben öylesi sevdim........

Hani masmavi gökyüzü,

Kucaklar ya engin denizleri,

Dalar gidersin ya,

Bakarken o maviliklere,

Derinden bir, aaahhhh  çekersin ya,

Hani içine yaşama sevinci dolar ya,

İşte seni ben öylesi sevdim........

Hani sevdim mi, sevdiM.

Dostluktan da öte,

Arkadaşlıktan da öte, 

Kardeşlikten de öte,

Hani içine yaşama sevinci dolar ya, 

İşte seni ben öylesine SEVDİM....', 'Hani bir bahar günü, Kırlarda gezinirsin  ya, Yeni açan, papatyaların, Lalelerin arasında, Hani içine yaşama sevinci dolar ya, İşte seni ben...', ARRAY['Türk Edebiyatı','Şiir','Sacide Yaylaz']::text[], 8.5, '{"poet":"Sacide Yaylaz","poet_slug":"sacide-yaylaz","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sevdim-53-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
