INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Arkadaşa', 'bir-arkadasa-gokay-ciftcioglu-spwe9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hasret gelip öylece yerleşmiş senin kalbine

Geldikleri gibi gitmezler iyi bilirsin bizim buraların aşkları…

Yürekte saklanır bir sürü söz verilemez şahsın kendisine

Bu bizimkiler sahibinden habersiz sevda

Kısa bir dans...

Uzun bir hasret.', 'Hasret gelip öylece yerleşmiş senin kalbine Geldikleri gibi gitmezler iyi bilirsin bizim buraların aşkları… Yürekte saklanır bir sürü söz ve...', ARRAY['Türk Edebiyatı','Şiir','Gökay Çiftçioğlu']::text[], 8.5, '{"poet":"Gökay Çiftçioğlu","poet_slug":"gokay-ciftcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/bir-arkadasa-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeşil....630-646. Gün', 'yesil-630-646-gun-huseyin-dogan-f0gp9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yeşil                                                              630-646. Gün

Buralar hep yeşil

Dal yeşil ağaç yeşil kuş yeşil

Su bile yeşil.

Göremezsin tepende gök kubbeyi

Ara sıra Görünürse sana  bir bakmışsın o da yeşil….

Yağmurlarda yeşil yağıyor buralarda

Kızların gözleri yeşil.

Akşamları yemekler pişiyor taş ocaklarda

İçinde pişen yeşil.

Yeşil bir rüyadasın uyursan eğer

Bir bakmışsın orman perisi tutmuş ellerinden 

Aralanır kapıları sihirli  ülkelerin

Kalkarken perdeler bir bir

Perdeler yeşil.

Bir yer düşünün tepesinde kocaman yeşil bir göl

Altında Kayalara oyulmuş bir şehir göğü göl

Ak tepelerine kadar dağların

Çepeçevre bir yeşil.

Şehre giden yolların taş korkuluklarından  bakınca aşağı

İki bin üç yüz metre uçurum.

İskender’in  torunları

Yüzler ak, gözler yeşil.

Dediler ki bu orman oraya giden tek yol

Sabahları içinde kaplanlar  zehirli yılanlar 

Akşamları ormanın cinleri

Adam yüreği yer.

Güldüm.

En izsiz en ıssız yolu seçtim.

Kader bu ya sadece periler sardı etrafımı

Şehre kadar yolumda izci.

Buradaki adlarıyla Kafirlerin (Alexander the Great Village)  gizli şehrine kadar gittim…doğrusu buradakiler özel günler hariç et yemiyorlar ölülerini çırılçıplak meydandaki sunağa koyup onun için yas değil düğün ediyorlar …..…….16 Eylul 2005

Bir daha ki rotamı dünyanın ikinci en yüksek çatısına K2 ye çevirdim. Umarım bu Kaf dağı maceramı Anka kuşunun yuvasında noktalarım.

Pakistan / Gandhara', 'Yeşil                                                              630-646. Gün Buralar hep yeşil Dal yeşil ağaç yeşil kuş yeşil Su bile yeş...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Doğan']::text[], 8.5, '{"poet":"Hüseyin Doğan","poet_slug":"huseyin-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/yesil-630-646-gun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahar Geldi Deme Bana', 'bahar-geldi-deme-bana-munevver-senol-icosk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne  olursun  Bahar geldi deme bana

                  benim  gönlüm  kış yaşıyor 

                  dertlerim okadar çok  ki

                   sormayın  beni aşıyor

                  halbu ki  bahar geldiğin de

                  insan  nasıl da coşuyor

                  ama  benim  gönlüm  kırık

                   baharda kış  yaşıyor

Sakın bahar geldi deme bana,

Benim gönlüm kış yaşıyor.', 'Ne  olursun  Bahar geldi deme bana                   benim  gönlüm  kış yaşıyor                    dertlerim okadar çok  ki                 ...', ARRAY['Türk Edebiyatı','Şiir','Münevver Şenol']::text[], 8.5, '{"poet":"Münevver Şenol","poet_slug":"munevver-senol","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bahar-geldi-deme-bana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gücenme (ahmet''in vedası)', 'gucenme-ahmet-in-vedasi-ahmet-ozyilmaz-xl5m2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bu şehri sana bırakıyorum.

bu sabah yüklendim hüzünleri,

aşkı, ayrılığa satıyorum.

pembe begonviller gibi yüzün,

mıh gibi gözlerime batıyor.

yüreğime sığmıyor bu hüzün...

benden seni bıraktım bu şehre

hiçbir şey almadım senden, 

bir tek

yokluğun bende kalmış, 

gücenme...

4 Ekim 2005', 'bu şehri sana bırakıyorum. bu sabah yüklendim hüzünleri, aşkı, ayrılığa satıyorum. pembe begonviller gibi yüzün, mıh gibi gözlerime batıyor....', ARRAY['Türk Edebiyatı','Şiir','Ahmet Özyılmaz']::text[], 8.5, '{"poet":"Ahmet Özyılmaz","poet_slug":"ahmet-ozyilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gucenme-ahmet-in-vedasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Atam', 'atam-ali-i-pekli-wmsj4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir güneştin Selanikten dogarken

Varol Atan senden çok şey ögrendik

Bazen atlı bazen yaya koşarken

Varol Atam senden çok şey ögrendik

19 mayısda Samsun''a çıktın

Mücadele odunu burada yaktın

Düşmana kaşını çatıpda baktın

Varol Atam senden çok şey ögrendik

Bazen ögretmendin tahta başında

Binbir akıl vardı o genç yaşında

Nam salmıştın bütün dünya çapında

Var ol Atam senden çok şey ögrendik

Medeni insan oldun giydin şapkayı

Bazende çiftçi oldun aldın çapayı

Milletine ögretirken akla karayı

Varol Atam senden çok şey ögrendik

Yurt çapında saltanatı kaldırdın

Geri zihniyeti yere batırdın

Ülken için toplantıya katıldın

Varol Atam senden çok şey ögrendik

Milli Misak dedin sınırı çizdin

Sana hain diyenlere kükreyip kızdın

Bazen şair olup yazılar yazdın 

Varol Atam senden çok şey ögrendik

Meclisi açarken vurdun tokmağa

Ardahandan Tekirdagdan Hataya

Milyonları o zaman döktün sokağa

Varol Atam senden çok şey ögrendik

Seni anlatmaya kalemim yetmez

Göndere çektiğin bayrağın inmez

İlkelerin asla yerlere düşmez

Varol Atam senden çok şey ögrendik

Ali İPEKLİ''de senin izinde

Bir çok ders var senin herbir sözünde

Kitleleri koşturursun peşinde 

Varol Atam senden çok şey ögrendik.', 'Bir güneştin Selanikten dogarken Varol Atan senden çok şey ögrendik Bazen atlı bazen yaya koşarken Varol Atam senden çok şey ögrendik 19 may...', ARRAY['Türk Edebiyatı','Şiir','Ali İpekli']::text[], 8.5, '{"poet":"Ali İpekli","poet_slug":"ali-i-pekli","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/atam-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Absisyon', 'absisyon-yaren-gurler-ulfd5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu iklim değişikliği,

