INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Belki Geç Geldim Ama İyi ki Geç Kalmadım', 'belki-gec-geldim-ama-i-yi-ki-gec-kalmadim-osman-murat-koktas-vl0ky', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sözler nasıl da anlamını yitiriyor bazen değil mi? 

Bir anda kelimeler düğümleniyor boğazımda

Her şey susuyor

İnsanlar, arabalar, gemiler, tramvaylar…

Her şey duruyor

Nehirler, taşıtlar, zaman…

Tükeniyor sanki

Tüm lügatlerdeki kelimeler…

Üç kelime kalıyor dilimde

Ancak onu söyleyebiliyorum sana…

Seni bırakıp gitmek değil benimkisi

“Sen beni bırakıp gideceksin” diyorsun ya…

Seni gittiğim yere götürememek…

En çok kanatan yanı bu 

Hayat gülünün dikenlerinin…

En küçük ayrı kalmalara bile tahammül edemezken 

Uzun bir ayrı kalışa mecbur olmak…

Hayat nasıl da tanımsız ve tutarsız bazen değil mi? 

Geç kalmışlıklarımızı düşünüyoruz kimi zaman

Kaybettiğimiz yıllarımızı

Ve sonunda bulduğumuza inandığımız gerçek aşkımızı…

Sonra yine geç kalmışlıklar giriyor araya

Ve mesafe koyuyor kavuşmamız için birbirimize…

“Belki geç geldim sana ama iyi ki geç kalmadım…”

Ulaşmak ve kavuşmak zordu sana…

Kurumaya yüz tutmuşken umut çiçeklerim

Sen su verdin onlara

Hiç beklemediğim bir zaman diliminde

Her şeyden vazgeçmiş ve her şeyi silmişken hayallerimden

Yeniden yaşamayı öğrettin bana

Tuttun ellerimden ve kaldırdın beni…

Şair; 

“Öyle bir zamanda gel ki, 

Vazgeçmem mümkün olmasın” demiş

Ben de; öyle bir zamanda geldin ki

Hayatımı bana geri verdin diyorum…

Sen; en önemli parçası hayatımın,

Beni tamamlayan ve ayağa kaldıran

Tekrar kendime kavuşturan

Sen benim her şeyimsin

Ben nefes alıp verdiğim sürece de

Hep içimde olacaksın

Her gün daha fazla artarak, 

Hiç azalmadan…

En güzel şeysin sen, hayatımdaki

Son nefesimi verdiğimde de öyle olacaksın…

24.09.2005 00:30    Osman Murat KÖKTAŞ (g.m.)', 'Sözler nasıl da anlamını yitiriyor bazen değil mi?  Bir anda kelimeler düğümleniyor boğazımda Her şey susuyor İnsanlar, arabalar, gemiler, t...', ARRAY['Türk Edebiyatı','Şiir','Osman Murat Köktaş']::text[], 8.5, '{"poet":"Osman Murat Köktaş","poet_slug":"osman-murat-koktas","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/belki-gec-geldim-ama-iyi-ki-gec-kalmadim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'zzzzz / Mani Hali..!', 'zzzzz-mani-hali-bir-mim-kemal-ertugrul-kzu2x', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir düş ki sızılıydı

Alnımda yazılıydı

Mani hali yüzünden 

Susumda kazılıydı...', 'Bir düş ki sızılıydı Alnımda yazılıydı Mani hali yüzünden  Susumda kazılıydı......', ARRAY['Türk Edebiyatı','Şiir','Bir Mim Kemal Ertuğrul']::text[], 8.5, '{"poet":"Bir Mim Kemal Ertuğrul","poet_slug":"bir-mim-kemal-ertugrul","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/zzzzz-mani-hali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geleceğim Sana', 'gelecegim-sana-turgut-onal-t4p3g', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben yeşil gözlerinin uğruna

Düşeceğim yola

Hem de yalınayak

Hem de yaya

Yıkarak duvarları

Kırarak kapıları

Peşime takılacak İstanbul''un

Tüm vapurları

Duman duman geleceğim sana

Ben yeşil gözlerinin uğruna

Düşeceğim yola

Yağmur, çamur

Kar, fırtına

Döndüremiyecek yolumdan beni

Ben yüreği yangın gibi harlı

Saçlarına kır düşmüş delikanlı

Söz veriyorum geleceğim sana

Belki elini tutacağım

Belki alnına küçük bir buse konduracağım

Yeşil gözlerine doya doya bakacağım

Ben yeşil gözlerinin uğruna 

Tutunup bir kuşun kanadına

Dağdan, bayırdan aşarak

Nehirler gibi coşarak

Geleceğim sana

Belkide çiçeğe duracak tabiat

Benim gibi sevincinden

Ben yeşil gözlerini anımsatan

Her nesneye bakarak

Bir şiir yazmak geldi içimden

Elimde çiçeklerle geleceğim sana

Her işini bırak....bekle

Yüreğimi ortasına koyup

Binbir çiçekle

Geleceğim sana....geleceğim sana

Geleceğim

Ne olur bekle', 'Ben yeşil gözlerinin uğruna Düşeceğim yola Hem de yalınayak Hem de yaya Yıkarak duvarları Kırarak kapıları Peşime takılacak İstanbul''un Tüm ...', ARRAY['Türk Edebiyatı','Şiir','Turgut Önal']::text[], 8.5, '{"poet":"Turgut Önal","poet_slug":"turgut-onal","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/gelecegim-sana-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umu''da...', 'umu-da-ali-baksi-duzg8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir dü? müsün sen? 

Rüyalarymy hapseden

Bende olan a?k’ty sana 

Neydi korkmana sebep? 

Tortulu bir a?k benimkisi! ! ! 

Buralarda sana tutsak 

Suçmu i?ledim sana? 

Bir kez olsun beni anla

Kelimeler yetmedi anlamynda

Ya?anmadan baharda

Ne kadar anlamsyz bir veda

Sev yada lütfen sev! ! 

Sevseydin! 

Olmazdy senin ?iirin

Sensiz tutunamayan bu beden

Bulut’lu gök yüzünde kyryk

Yylgyn ve koca dü?leriyle

Sana olan hasret bitsin

Ya?ansyn  bu a?k ba?akta

Sonsuz ilk benimki’si

Binlerce daha s,s,e,i,b…', 'Bir dü? müsün sen?  Rüyalarymy hapseden Bende olan a?k’ty sana  Neydi korkmana sebep?  Tortulu bir a?k benimkisi! ! !  Buralarda sana tutsak...', ARRAY['Türk Edebiyatı','Şiir','Ali Baksı']::text[], 8.5, '{"poet":"Ali Baksı","poet_slug":"ali-baksi","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/umu-da-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Minik Kuşum', 'minik-kusum-turgut-onal-el8np', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gözü yağmur gözlü bulutta kalmış

Uçar gurbetlere oy minik kuşum

Rüyası pembe güle takılmış

Gider gurbetlere oy minik kuşum

Yüreğinde sevda yangınları var

Konduğu her dalda gönül yarası

Umut kapısından mı  seni kovdular

Gözlerin hep böyle gece karası

Yıldızlar takılmış ipek saçına

Alevden bir kuşak sarmış belini

Ulaşmak kolay mı murat tacına

O ateşten bir top yakar elini

Semahlar oynayıp türküler söyle

Denizler ufkundan bir rüzgâr getir

Gönül köşklerine kurul da şöyle

Uzak limanlardan umutlar getir

Ve sen de artık şen şarkılar söyle

Gönül kapısını kapatma emi

Minik kuşum sakın gitme öfkeyle

Şimdi vuslat vakti muhabbet demi', 'Gözü yağmur gözlü bulutta kalmış Uçar gurbetlere oy minik kuşum Rüyası pembe güle takılmış Gider gurbetlere oy minik kuşum Yüreğinde sevda y...', ARRAY['Türk Edebiyatı','Şiir','Turgut Önal']::text[], 8.5, '{"poet":"Turgut Önal","poet_slug":"turgut-onal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/minik-kusum-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
