INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fatoşum', 'fatosum-ali-i-pekli-7y5ca', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gözlerine bakınca eridim bittim

Sensiz yaşanmıyor anla Fatoşum

Nasıl oldu senden ıradım gittim

Sensiz yaşanmıyor anla Fatoşum

Aşkın beni sarhoş etti nideyim

Çıban oldu yaralandı yüreğim

Sabah öğle akşam hep seninleyim

Sensiz yaşanmıyor anla Fatoşum

Gece gündüz adın ezberim oldu

Aliş''im dedinde gözlerim doldu

Baharda çiçegim sarardı soldu

Sensiz yaşanmıyor anla Fatoşum

Ali İPEKLİ''nin özlemi bitmez

İçindeki hasret daimdir gitmez

Bu sevda ateşi sönmeyi bilmez

Sensiz yaşanmıyor anla Fatoşum

                                                            

                                             12.05.1999/Samsun

                                                    Ali İPEKLİ', 'Gözlerine bakınca eridim bittim Sensiz yaşanmıyor anla Fatoşum Nasıl oldu senden ıradım gittim Sensiz yaşanmıyor anla Fatoşum Aşkın beni sar...', ARRAY['Türk Edebiyatı','Şiir','Ali İpekli']::text[], 8.5, '{"poet":"Ali İpekli","poet_slug":"ali-i-pekli","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/fatosum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayna Yüzleşmesi', 'ayna-yuzlesmesi-gulay-yildiz-6hjs9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yüzümün acıyan diğer yanıydın,

Baktıkça yüzleştiğim aynalarda.

Aynalar kustukça seni

Yüzsüzlüktü çarem,

Kaçtım ağlamalarda

Oysa; 

Yaşanmamışta

Yalnız kalma korkusuydu 

Öfkelendiren...

Öfkem delirttikçe 

Kaçmaktı çarem

Ağladım aynalarla', 'Yüzümün acıyan diğer yanıydın, Baktıkça yüzleştiğim aynalarda. Aynalar kustukça seni Yüzsüzlüktü çarem, Kaçtım ağlamalarda Oysa;  Yaşanmamış...', ARRAY['Türk Edebiyatı','Şiir','Gülay Yıldız']::text[], 8.5, '{"poet":"Gülay Yıldız","poet_slug":"gulay-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ayna-yuzlesmesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şefaat', 'sefaat-elazigli-mustafa-kaya-6zhk8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '“…Allah’ın izin verdiklerinden başkası

            şefaat edemez…yunus / 3…” 

kapına geldim

sürüne sürüne,

yüz çevirme

ya Rasulallah..! 

katı kalbimi bıraktım

ölüm durağımı fark ettim

nefsimle beni baş başa 

bırakma ya Rasulallah..

gam ve kederimi

dünyadan yana,

ne varsa 

suya verdim.

inkarımı bıraktım

daru-s selam a geldim

sen şefaat et

ya rasulallah

tevbeleri kabul eder Rabbim..

Mustafa kaya

05.10.2005 / Üsküdar

www.mustafakaya.net', '“…Allah’ın izin verdiklerinden başkası             şefaat edemez…yunus / 3…”  kapına geldim sürüne sürüne, yüz çevirme ya Rasulallah..!  kat...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sefaat-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gam', 'gam-elazigli-mustafa-kaya-2plm9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ağır bir gam var

bulutlarda.

sonsuz bir çölde,

hiçbir yere çıkmayan

bir yolun üstünde,

ağlayan ve okşanmak isteyen

bir çocuk gibiyim..

baştan başa yalnızlık

içindeyim…

gece oldu,

ay yanımdan gitti.

sokağın ışıkları kanatlandı.

acı bir bitkinlik ve,

usanç sardı ruhumu

gamlı ve kederli…

Mustafa kaya

03.10.2005 / üsküdar

