INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kusursuz', 'kusursuz-elazigli-mustafa-kaya-cjtkj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'sen..,

sen ki hayatımda

hiç görmediğim

kim olduğunu hiç bilmediğim

fakat,

kendi göğünde yalnız, saf ve

güzel olarak 

görünen güneş gibi,

ruhumda gezinir bir parlaklıkla

kusursuzca varsın…

