INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Ayda (Ramazan)', 'bu-ayda-ramazan-tuncay-akdeniz-5acmg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Açıldı aleme rahmet kapısı

İlmik,ilmik düğüm çözer bu ayda

Kabul olur duaların hep isi

Sıra,sıra saflar dizer bu ayda

Zikirle geçirdik recep şabanı

Ramazanın başka gülü gül şanı

Bu ayda bulursun cana şifanı

Şifa reçetesi yazar bu ayda

Mümin olan hürmet eder bu aya

Kabul için kalkar eller duaya

Ezanın sesleri çıktı semaya

Şeytanın canını üzer bu ayda

O temiz kalpleri nuruyla yıkar

Kin nefret kötülük içinden çıkar

Gönüller ırmağı şenlenir akar

Bulanık suları süzer bu ayda

Şükür eder canlı cansız kainat

Doğuştan başlıyor canlıda hayat

Arınmış günahtan gönüller rahat

Şeytanda kendine kızar bu ayda

Ramazan içinde kadir gecesi

Ayet,ayet inmiş kuran süresi

Tuncay in dilinde elif hecesi

Rahmeti alemi gezer bu ayda', 'Açıldı aleme rahmet kapısı İlmik,ilmik düğüm çözer bu ayda Kabul olur duaların hep isi Sıra,sıra saflar dizer bu ayda Zikirle geçirdik recep...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Akdeniz']::text[], 8.5, '{"poet":"Tuncay Akdeniz","poet_slug":"tuncay-akdeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bu-ayda-ramazan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasret Öyküsü', 'hasret-oykusu-engin-aktepe-n72bh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ardından kaç kırık hikaye anlattım martılara

Hasrete kalmasın diye öykümüz 

Kaç mevsimsiz bahar sakladım bir bilsen 

Karboranlara doğan güneşim (sen)  solmasın diye.....

Bir nefeslik ömrüm kalsa 

Yine seni koklardım

Sen dağ çiçeğim ol 

Yağmurun ben olurdum

Yeter ki solmasın toprak gözlüm gülüşün', 'Ardından kaç kırık hikaye anlattım martılara Hasrete kalmasın diye öykümüz  Kaç mevsimsiz bahar sakladım bir bilsen  Karboranlara doğan güne...', ARRAY['Türk Edebiyatı','Şiir','Engin Aktepe']::text[], 8.5, '{"poet":"Engin Aktepe","poet_slug":"engin-aktepe","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/hasret-oykusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağla Dostum', 'agla-dostum-suheyla-kurnaz-af41v', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Otur karabaş, otur dostum! 

Geç karşıma otur da, derdimi dökeyim...

Kadehimi yudumlarken eşlik et bana

Sanma ki sarhoşum, sanma ki ayyaşım,

Sanma ki aklımı oynattım.

Sadece  efkarlıyım  bu gün,

Kederimden ağlamak geliyor içimden

Ağlamak…ağlamak… doyasıya ağlamak.... 

Senin hiç boğazın düğümlenip, 

Arzuların sürüklenip, kalbinde sızı,

İçinde derin bir acı oldu mu? ...

İçip içip figan edip,

Alev alev yanan yüreğine, 

Bir kaç damla su serpiştirip,

Sarhoş olup, ağlamak istediğin oldu mu? ...

Sahra çöllerde

Çatlayan dudaklarına bir damla su ararken,

Serap görüp ağlamak istediğin oldu mu? ...

Zalim bir kâhya tufanlar koparıyor, 

Hiddetle kırbaçlıyor sırtımı.

Kanayan yaralarım çok derin, 

Tuz bassan, yine canım yanmaz.

Ama...

Aha buramda,

Küt küt atan sol yanımda, 

Öyle derin, öyle çirkin kırbaç izi var ki…

Zalimin ayakları altında ezilen  gururumu

Islak sokaklarda aradım.

Taş duvarlara kaldırımlara sordum.

''''Buhar olup gökyüzünü mesken tuttu'''' dediler

Yitirdim umutlarımı, kaybettim duygularımı... 

Ne o? ...

sende ağlamaya başladın be dostum…

Hani nerede o yüzümüze gülen, seven dostlarımız 

Nasır mı tuttu yürekleri, yalnız bıraktılar bizi? 

Yoksa şimdi, onlada mı ağlıyor senin gibi? 

Ağla dostum ağla

Çekelim  bir kadeh daha ve ağlayalım...

Gözyaşlarımızı  birleştirelim.

Bir kıvılcım yaratalım gökyüzünde

Mor bulutlar ağlasın... 

Ağlasın ki, gururum tezi yok yüreğime kavuşsun.

SuheylaKurnaz.com - Kişisel Web Sitem

SuheylaKurnaz.com - Kişisel blog Sayfam', 'Otur karabaş, otur dostum!  Geç karşıma otur da, derdimi dökeyim... Kadehimi yudumlarken eşlik et bana Sanma ki sarhoşum, sanma ki ayyaşım, ...', ARRAY['Türk Edebiyatı','Şiir','Süheyla Kurnaz']::text[], 8.5, '{"poet":"Süheyla Kurnaz","poet_slug":"suheyla-kurnaz","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/agla-dostum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanlıştasın', 'yanlistasin-musa-yasaroglu-voko0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yanlıştasın her an

Bilmeden yürüyorsun yolunu

Susuyorsun aniden

Haykırmadan sevdanı 

Bitirmeden günahını

Yanlış diyarlarda geziyorsun

Sırf hayata yaranmak için

Yanlış ufukları gözlüyorsun

Umuda sarılmak değil niyetin

Hüzünlerde kaybolmuş yüreğin

Yanlış ateşlerde yanıyorsun

Yalnızca yanmak içim belki de

İnanmadan yaşıyorsun sabahları

Karanlığı yakıştırmıyorsun kendine

Ve zamanı uydurmuyorsun kendine

Yanlışsın

Yanlıştasın her an

Duymadan gidiyorsun yarını

Hep dünleri yaşıyor gözlerin

Ellerin yanlış badenleri sarıyor

Ve yine yüreğin boşlukta

Yanlış kişiyi bekliyor', 'Yanlıştasın her an Bilmeden yürüyorsun yolunu Susuyorsun aniden Haykırmadan sevdanı  Bitirmeden günahını Yanlış diyarlarda geziyorsun Sırf h...', ARRAY['Türk Edebiyatı','Şiir','Musa Yaşaroğlu']::text[], 8.5, '{"poet":"Musa Yaşaroğlu","poet_slug":"musa-yasaroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/yanlistasin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Utanç', 'utanc-musa-yasaroglu-6bc47', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Günahlar doyumsuz haz verir arsız kalmış nefsime

Sonrası perişanlıktır hep, utanç vurunca yüzüme', 'Günahlar doyumsuz haz verir arsız kalmış nefsime Sonrası perişanlıktır hep, utanç vurunca yüzüme...', ARRAY['Türk Edebiyatı','Şiir','Musa Yaşaroğlu']::text[], 8.5, '{"poet":"Musa Yaşaroğlu","poet_slug":"musa-yasaroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/utanc-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arzuhalim', 'arzuhalim-suheyla-kurnaz-r6zp8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sanadır arzuhâlim, bu seher vakti, sana! 

Kanadı kırık serçeydim şu fâni dünyada,

Gökyüzünde acılarımla, savruldum, kavruldum da geldim... 

Kum tanesiydim kainatın bir köşesinde,

Bahar yeliyle savrulup,

Denizlere yüreğimi saldım da geldim...

Kurşun yedim, ağır yaralıyım, 

Damarlarımdaki kan, son firarda

Gecelerin  ayazında, taş sokaklarda

Yarım kalan arzularımı yaktım da geldim…

Yetim kalan kanadı kırık turnaların,

Öksüz kalan gün görmedik yavruların, 

Yaralarını bir bir sardım da geldim...

Aşkıma ihanet eken, sevgime hıyanet eden

Sahte gülen yüzlerden, riyakar dostlardan

Nasibimi aldım da geldim....

Muhabbet bağında, aşkın badesini taşlara vurup 

Eziyeti, işkenceyi  yaşatanlara,

Ah... etmeden, isyan etmeden

Merhamet aşkımla sevdim de geldim...

Prangalarla okyanusları çölleri aşıp, 

Aşkın ateşine nefsimi dağlayıp,

Mukaddes pınarından damlayan,

Mübarek suyun içtim de geldim...

Seher vakti eğildim kapın önünde

Secde ettim gönül bağımla evinde

Musalla köşkünde tekbirin  dilde 

Aşkına sığınıp, nârınla yanmaya geldim...

Açtım avuçlarımı sana,  budur arzuhâlim,

Işığınla yak, ateşinle yak beni, sana geldim

SuheylaKurnaz.com - Kişisel Web Sitem

SuheylaKurnaz.com - Kişisel blog Sayfam

Yorum: Ömer Aykan (Radyo Davet_Bursa)', 'Sanadır arzuhâlim, bu seher vakti, sana!  Kanadı kırık serçeydim şu fâni dünyada, Gökyüzünde acılarımla, savruldum, kavruldum da geldim...  ...', ARRAY['Türk Edebiyatı','Şiir','Süheyla Kurnaz']::text[], 8.5, '{"poet":"Süheyla Kurnaz","poet_slug":"suheyla-kurnaz","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/arzuhalim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çıkmaz Patika', 'cikmaz-patika-engin-aktepe-62hrx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kömür gözlerinde bir patikaya düştü yüreğim

Kaybolmuş bir adres kadar çaresiz sevgimi 

Çıkmazlara sürgün etme.........

Yokluğunla gölgem kadar içimdesin 

Tarihsiz gecelerde ansızın koynumdasın

Sorgusuz denklemler değildi kadersiz geçmişin

Sinmesin ömrüne yazgısız yangınların...........', 'Kömür gözlerinde bir patikaya düştü yüreğim Kaybolmuş bir adres kadar çaresiz sevgimi  Çıkmazlara sürgün etme......... Yokluğunla gölgem kad...', ARRAY['Türk Edebiyatı','Şiir','Engin Aktepe']::text[], 8.5, '{"poet":"Engin Aktepe","poet_slug":"engin-aktepe","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/cikmaz-patika-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arıyorum', 'ariyorum-musa-yasaroglu-e04ez', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Arıyorum kendimi her adımda gayretle

Ben kendime, alem bana göz kırpıyor hayretle', 'Arıyorum kendimi her adımda gayretle Ben kendime, alem bana göz kırpıyor hayretle...', ARRAY['Türk Edebiyatı','Şiir','Musa Yaşaroğlu']::text[], 8.5, '{"poet":"Musa Yaşaroğlu","poet_slug":"musa-yasaroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/ariyorum-35-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sahipsizim', 'sahipsizim-musa-yasaroglu-46qw7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Belirsiz bir yol ortasında nefessiz, yüreksiz ve sahipsizim

Her şeyden habersiz, her şeyden uzak, biçare serseriyim', 'Belirsiz bir yol ortasında nefessiz, yüreksiz ve sahipsizim Her şeyden habersiz, her şeyden uzak, biçare serseriyim...', ARRAY['Türk Edebiyatı','Şiir','Musa Yaşaroğlu']::text[], 8.5, '{"poet":"Musa Yaşaroğlu","poet_slug":"musa-yasaroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/sahipsizim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son', 'son-musa-yasaroglu-ddz9y', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Zaman huzursuzluğu vuruyor

Dünya kıyamete gebe

İnsanlık Son''u yaşıyor

Ruhlar ölümsüzlüğe hasrette', 'Zaman huzursuzluğu vuruyor Dünya kıyamete gebe İnsanlık Son''u yaşıyor Ruhlar ölümsüzlüğe hasrette...', ARRAY['Türk Edebiyatı','Şiir','Musa Yaşaroğlu']::text[], 8.5, '{"poet":"Musa Yaşaroğlu","poet_slug":"musa-yasaroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/son-104-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm', 'olum-musa-yasaroglu-fjsi3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ölüm; gidişlerin belirsizliği

Ölüm; yolun yokluğu değil

Ölüm; ruhların ebediyeti

Ölüm; sonlardaki son değil', 'Ölüm; gidişlerin belirsizliği Ölüm; yolun yokluğu değil Ölüm; ruhların ebediyeti Ölüm; sonlardaki son değil...', ARRAY['Türk Edebiyatı','Şiir','Musa Yaşaroğlu']::text[], 8.5, '{"poet":"Musa Yaşaroğlu","poet_slug":"musa-yasaroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/olum-212-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlamıyorum Seni', 'anlamiyorum-seni-mehmet-aslan-ftrv3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Anlamıyorum seni; 

öpüyorum

mutlu oluyorsun.

Öptüm diyorum

kızıyorsun.

Anlamıyorum seni; 

Seviyorum

hoşlanıyorsun

Sevdim diyorum

darılıyorsun.

Anlamıyorum seni; 

Geliyorum

kaçıyorsun

Gidiyorum

özlüyorsun.

Anlamıyorum seni; 

anlamıyorum.

Seninde beni 

anladığını

hiç sanmıyorum.', 'Anlamıyorum seni;  öpüyorum mutlu oluyorsun. Öptüm diyorum kızıyorsun. Anlamıyorum seni;  Seviyorum hoşlanıyorsun Sevdim diyorum darılıyorsu...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Aslan']::text[], 8.5, '{"poet":"Mehmet Aslan","poet_slug":"mehmet-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/anlamiyorum-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sigaram', 'sigaram-mehmet-aslan-frht7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sigaram benim tek dostumdur,

Kanser yaparmış, çokta umurumdur.

Ölüp gitsem bile kanserden,

Kurtulurum sensizlikten çektiğimden.

Bırak diyorsun bana sigarayı,

Ama sen açıyorsun en büyük yarayı.

Söyle kimin için bırakayım,

Sen yoksan onsuz nasıl yaşayayım.

Yeter ki sen iste bırakırım,

Ama sen yoksan tekrar yakarım.

Sen yoksun zaten bırakamam,

Sensizken onsuz da duramam.

Biliyorum çoktur zararları,

Bir tek o unutturuyor açtığın yaraları.

Sen gel ki onu bırakayım,

Unutup ta onu seninle yaşayayım', 'Sigaram benim tek dostumdur, Kanser yaparmış, çokta umurumdur. Ölüp gitsem bile kanserden, Kurtulurum sensizlikten çektiğimden. Bırak diyors...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Aslan']::text[], 8.5, '{"poet":"Mehmet Aslan","poet_slug":"mehmet-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sigaram-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ve Ölüm', 've-olum-ebru-yucesoy-yc7d6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Her sabah uyandığımda 

Atıyorum çöpe 

Yaşama hakkımdan bir sayfa daha

Her gün, yavaş yavaş,

Ölmüyor muyuz aslında

Ve mefta oluyoruz 

Son sayfa koptuğunda...', 'Her sabah uyandığımda  Atıyorum çöpe  Yaşama hakkımdan bir sayfa daha Her gün, yavaş yavaş, Ölmüyor muyuz aslında Ve mefta oluyoruz  Son say...', ARRAY['Türk Edebiyatı','Şiir','Ebru Yücesoy']::text[], 8.5, '{"poet":"Ebru Yücesoy","poet_slug":"ebru-yucesoy","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/ve-olum-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Meleğimsin', 'melegimsin-mehmet-aslan-pv4t3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Biriciğimsin benim,

hayalde olsan.

hayalimsin benim,

gerçekte olsan.

Tek çaremsin benim,

çaresizde olsan.

Aşk ateşimsin benim,

sönmüş bile olsan.

Gerçeğimsin benim

serapta olsan.

Geleceğimsin benim

geçmişte olsan.

Sevdiğimsin benim,

sevmemişte olsan.

Meleğimsin benim,

İbliste olsan.

Canımsın benim,

kansızda olsan.

Can pınarımsın benim,

kurumuşta olsan', 'Biriciğimsin benim, hayalde olsan. hayalimsin benim, gerçekte olsan. Tek çaremsin benim, çaresizde olsan. Aşk ateşimsin benim, sönmüş bile o...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Aslan']::text[], 8.5, '{"poet":"Mehmet Aslan","poet_slug":"mehmet-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/melegimsin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sanal Aşk', 'sanal-ask-yalcin-isik-3icbj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yıllarca gerçek aşkı arayan bendim

Seninle gerçek aşkı buldum sandım

Şimdi anladım aşkımız bir yalanmış

Gördüm şimdi asıl olan aşk sanalmış

Hayatımdaki ilk ve tek kadın sendin

Belki bundan sonra tek olmayacaksın

Nasıl unuturum ben seni bilmiyorum

Hep hayatımdaki ilk kadın olacaksın', 'Yıllarca gerçek aşkı arayan bendim Seninle gerçek aşkı buldum sandım Şimdi anladım aşkımız bir yalanmış Gördüm şimdi asıl olan aşk sanalmış ...', ARRAY['Türk Edebiyatı','Şiir','Yalçın Işık']::text[], 8.5, '{"poet":"Yalçın Işık","poet_slug":"yalcin-isik","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sanal-ask-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adem Oğlu', 'adem-oglu-aylin-onder-eygq1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Komşular duymasın diye bu gece sessiz haykıracağım,

Çığlıklarımı duymayacak kimse.

Belki sen bile.

Cam kenarında oturup ilham vermeyeceğim bulutlara,

Yansın yüreğin,bir damla harcamayacağım.

Yıldızların kaymasını beklemeyeceğim, 

İnadına onlar kaymadan salacağım dileklerimi.

Bu gece yastığa koymayacağım başımı,

Yatmayacağım,istemiyorum pembe rüyalarını.

Hiç bakmayın bu gece balkonda oturup,

Poz vermiyeceğim sizlere.

Sessiz basacağım gecenin basamaklarına, 

Ben duymayacağım sizi,sizde duymasanız bu gece.

Pervaneler mumları.

Duvarlar esareti,

Ben de kendimi,

İstemiyoruz bu gece...

Gelmesin sevgili arkadaş,tahammülü yok gönlümün,

Anlatacak ne iyi,ne kötü hikayem yok.

Kulaklarımı tırmalarken sesi bülbülün,

Kırarım kendim kadar,ortak istemiyorum.

Seni bile göresi gözüm yok, 

Aynalar da yok,

Nefes almak bile zorunlu olmasa...

Mecbur olmadan hiç birşeye,

Kanamasın bu gece de kara kalemim,

Bakmayın da utanmasın beyaz sayfalarım,

Rahat bırakın işte bu gece beni...

Gelmesin aklıma düşünceler

Tadımı kaçırmasın,

İstemem güzelliğini hiç bir duygunun,

İnadı tuttu işte adem oğlunun...', 'Komşular duymasın diye bu gece sessiz haykıracağım, Çığlıklarımı duymayacak kimse. Belki sen bile. Cam kenarında oturup ilham vermeyeceğim b...', ARRAY['Türk Edebiyatı','Şiir','Aylin Önder']::text[], 8.5, '{"poet":"Aylin Önder","poet_slug":"aylin-onder","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/adem-oglu-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geldin Yirmiye', 'geldin-yirmiye-mehmet-aslan-bhy2w', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir yıl daha gitti ömründen,

Geldi yaşın yirmiye,

Hatıranda neler kaldı maziden,

Hiç dönüp de baktın mı geriye.

Geçmişe gülüp geçiyorsun,

Ne cahillikler yapmışım diye.

Geleceğine de bir yön veremiyorsun,

Çünkü dönmüşsün artık deliye.

O güzel gözlerine söyle,

Sevinç yaşlarıyla dolsun.

Darılma sakın tarzım böyle,

Doğum Günün Kutlu Olsun.', 'Bir yıl daha gitti ömründen, Geldi yaşın yirmiye, Hatıranda neler kaldı maziden, Hiç dönüp de baktın mı geriye. Geçmişe gülüp geçiyorsun, Ne...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Aslan']::text[], 8.5, '{"poet":"Mehmet Aslan","poet_slug":"mehmet-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/geldin-yirmiye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öleyazmak', 'oleyazmak-ebru-yucesoy-gbtb3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Daha gündüz vakti hava karardı

Yol karanlık, yol uzun

Dizilmiş kenarlara beyaz testiler

Kimbilir kimdiler? 

Yüzleri yok, sesleri yok.. 

Sadece bir uğultu

Kafamda dönen kelimeler 

Döndükçe yitiyor sesler, yüzler

Gittikçe uzayan yol 

Kısaldıkça acıtıyor

Hiç bitmese ne fark eder? 

Varılacak nokta yok ki!', 'Daha gündüz vakti hava karardı Yol karanlık, yol uzun Dizilmiş kenarlara beyaz testiler Kimbilir kimdiler?  Yüzleri yok, sesleri yok..  Sade...', ARRAY['Türk Edebiyatı','Şiir','Ebru Yücesoy']::text[], 8.5, '{"poet":"Ebru Yücesoy","poet_slug":"ebru-yucesoy","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/oleyazmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Feride''m', 'feride-m-yusuf-ter-2m9et', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bekle beni Feride’m elbette geleceğim

Her an senin yanında canında olacağım

Canımı feda edip uğruna öleceğim

Yeter ki bana inan inan aşkın gücüne 

Sabah oldu uyanıp ta gel  yanıma Feride

Güneş gibi doğaraktan gir kanıma Feride

Al bohçanı hazırlan sar canıma  Feride 

Yeter ki bana inan inan aşkın gücüne 

Şafak söktü ağır ağır can veriyor dağlara

Can geliyor güldüğün de açıyor gül bağlara

Görür derman olursun   hastalara  sağlara

Yeter ki bana inan inan aşkın gücüne

Gözde fer oldun inan dizlerimde dermansın

Şu gönlüme örülmüş yıkılmaz bir kirmansın

Bağ zamanı bağbansın har zamanı harmansın

Yeter ki bana inan inan aşkın gücüne

Vermediler  Feride''m kaderindir çek  diye

Bekledim ben her gece bilmem gelmedin niye

Heder oldum  ben burada günleri saya saya

Yeter ki bana inan inan aşkın gücüne

Yusuf Ter 05.10.05

Saat 02:20 İsviçre 

Bağbansın: Bağ yetiştiren kişi', 'Bekle beni Feride’m elbette geleceğim Her an senin yanında canında olacağım Canımı feda edip uğruna öleceğim Yeter ki bana inan inan aşkın g...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ter']::text[], 8.5, '{"poet":"Yusuf Ter","poet_slug":"yusuf-ter","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/feride-m-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Demiştim Sana', 'demistim-sana-salim-erben-z6w8s', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gözlerinin güzelliğinde gerçekler 

Saklı kalır

Sen öğünürsün güzelliğinle 

Gün biterken baktığın zaman 

Aynalara

Uzun boylu yeşil gözlü biri gelir 

Karşına

Duyguların gece yarısı karmaşık

Dolaşır

Hislerin görüntünden yara alır

Biliyormusun

Yıldızlar küsmüş gökyüzüne

Ay karanlık dönük içine 

Demiştim sana taşıyamazsın 

Ağır olur benim sevgim zalım  diye', 'Gözlerinin güzelliğinde gerçekler  Saklı kalır Sen öğünürsün güzelliğinle  Gün biterken baktığın zaman  Aynalara Uzun boylu yeşil gözlü biri...', ARRAY['Türk Edebiyatı','Şiir','Salim Erben']::text[], 8.5, '{"poet":"Salim Erben","poet_slug":"salim-erben","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/demistim-sana-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul... (16 Beyit)', 'i-stanbul-16-beyit-atakan-kartaltepe-rkrms', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Günün ilk ışıkları yükselirken Hisar’dan...

Seyredin Marmara’yı...Boğaz’ı, Üsküdar’dan...

Çek içine havayı...bulunmaz bir nimet bu! 

Yaz’ı, Kış’ı Bahar’ı...gerçekten bir ziynet bu! 

Kızkulesi...sevgili,  kıt’alar arasında...

İstanbul ismi vardır her gönülün ıs’ında...

İstanbul...İstanbul ki taş’ına âlem feda...

İstanbul’u bir başka yaratmıştır ki Hüda...

İşlemiş havasını – suyunu her bir şeyini...

Bırakmamış dışarda hiçbir şeyi ne’yini...

Bu şehir yıllar yılı her gönüle kurulur...

Kim görse kim yaşasa İstanbul’a vurulur...

Şair, Ozan kim varsa...âşıklara bir hayal...

Gönüller fetheder de Fatih’lere ideal...

İki kavuşmaz yaka...gönüller yaka – yaka...

Be İstanbul nedir bu? ..nedir bu afi – caka? 

Ne demiş Yahya Kemal “ her semti bir ömür” mü? 

Be İstanbul...İstanbul! ..insan sende ölür mü? 

Yazdım bir şiirimde “her mevsimin bir güzel! ”

Sensin gönüller yakan! ..sensin be ebed – ezel! 

Ne semt – semt dolaşarak...ne sende yaşayarak...

Yetmez sana kanmaya...sana yanmaya...ancak! 

Sen Dünya’nın kalbisin...sende Dünya’nın gözü...

Hep birinci! ..İnci’sin! ..sensin âlemin öz’ü...

Sanki Dünya Başkenti...her din’den her insan var...

İşte bu yüzdendir ki herkes her an sana yâr...

Demiş ki Yahya Kemal “O’nda yaşa – O’nda öl”

Doğru valla...başka yer ya mezarlık ya da çöl...

Şiirde ne söylemiş “çok yıl yaşayan – yatan”

Sende doğdu da...yine, sende yatsın Atakan...

Ne  var sende? ..ne var? söyle ne o büyülü şey? ..

İstanbul! İstanbul be! İstanbul! ..İSTANBUL HEEEY!', 'Günün ilk ışıkları yükselirken Hisar’dan... Seyredin Marmara’yı...Boğaz’ı, Üsküdar’dan... Çek içine havayı...bulunmaz bir nimet bu!  Yaz’ı, ...', ARRAY['Türk Edebiyatı','Şiir','Atakan Kartaltepe']::text[], 8.5, '{"poet":"Atakan Kartaltepe","poet_slug":"atakan-kartaltepe","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/istanbul-16-beyit-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadınların Rüyası', 'kadinlarin-ruyasi-alper-kuruk-o1avr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Doğru mu söylemiş âlimler

Kadın rüyası renk renk olurmuş.

Söyle sen de renkli rüyalar görür müsün? 

Beni görür müsün rüyalarında

Özleyişle yattığın geceler? 

Üzüntüden kara - sarı mı görürsün benzimi? 

Acı duyacak olsan

Renkleri uçar mı rüyalarının? 

Gülsen gül rengi mi olur rüyaların,

Ağlasan kara bulutlar mı görürsün? 

Bir erkek girse rüyalarına

Farzet ki ben girsem

Erkek rüyalarına mı döner rüyaların

Kara -kuru baştan ayağa? 

Söyle,âlimler mi yanılıyor

Sen de renkli rüya görür müsün? 

Bak,şeytan demiyorum

Bir erkek girse rüyalarına

Rüya içinde rüya görür müsün? 

Şeytanlı rüyalarımı bir gecelik versem sana

Benim için de renkli rüyalar görür müsün?', 'Doğru mu söylemiş âlimler Kadın rüyası renk renk olurmuş. Söyle sen de renkli rüyalar görür müsün?  Beni görür müsün rüyalarında Özleyişle y...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/kadinlarin-ruyasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alışamadım...', 'alisamadim-mustafa-komuscuoglu-ec1xf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yıllar öncesiydi bir terkedilişin başlangıcı

Sözde mutluluk hikayesinin son sayfası 

Tam olaraksa bir Ağustos akşamıydı 

Ve o akşam da bir can çifte zafer kutladı 

Yıllar geçti aradan ve herkes deyişti 

Her gidenin yerine bir yenisi geldi 

Ölürcesine seviyorum diyenler bile 

Üçer beşer tane sevgiliyi eskitti 

Anladımki insan zamanla herşeye alışıyormuş 

Unutulmak adama yanlız birkaç ay koyuyormuş 

Meğer terkedilmişliğin acısı geçici bir duyguymuş 

Meğer geçmeyen tek şey beyhude bir avuntuymuş 

Zamanla bende herşeye alıştım biliyormusun 

Yanlızlığa,gözyaşına,umutsuzluğa ve umuda 

Ve hatta senin yokluğuna bile amma; 

Alışamadım hala sevdiğim...

Senin için çarpan sol yanıma...', 'Yıllar öncesiydi bir terkedilişin başlangıcı Sözde mutluluk hikayesinin son sayfası  Tam olaraksa bir Ağustos akşamıydı  Ve o akşam da bir c...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Kömüşcüoğlu']::text[], 8.5, '{"poet":"Mustafa Kömüşcüoğlu","poet_slug":"mustafa-komuscuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/alisamadim-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir fotoğraftan', 'bir-fotograftan-halime-vatansever-djm6z', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Küçük bir serçe konmuş

Dikenli tellere

_Neredesin sen gerçek misin? 

Ne kadar? 

_Serçe kadar

Dikenli teller kadar gerçeğim

Serçenin özgürlüğü kadar

İnsan içinde yaratır özgürlüğünü

Sen kadar gerçeğim

İnandığın kadar', 'Küçük bir serçe konmuş Dikenli tellere _Neredesin sen gerçek misin?  Ne kadar?  _Serçe kadar Dikenli teller kadar gerçeğim Serçenin özgürlüğ...', ARRAY['Türk Edebiyatı','Şiir','Halime Vatansever']::text[], 8.5, '{"poet":"Halime Vatansever","poet_slug":"halime-vatansever","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bir-fotograftan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kusur', 'kusur-aysun-erat-kj45a', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen beni sevdiğinde,

Gökte ay daha bir parlak

Yerde toprak daha bir bereketli

İçim dışım düğün dernek.

Vazgeçme hiç emi? 

Sev beni hep.

Benim mutluluğum kusur kalsın,

Olmasa da olur içimde düğünler.

Ama ya ay? 

Ya toprak? 

En iyisi sen hep sev beni

10/2005', 'Sen beni sevdiğinde, Gökte ay daha bir parlak Yerde toprak daha bir bereketli İçim dışım düğün dernek. Vazgeçme hiç emi?  Sev beni hep. Beni...', ARRAY['Türk Edebiyatı','Şiir','Aysun Erat']::text[], 8.5, '{"poet":"Aysun Erat","poet_slug":"aysun-erat","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kusur-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gecenin Mâtemi', 'gecenin-m-temi-timur-i-likan-mxfce', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gecenin mâtemi kaplıyor her yanımı

İçimde yanıyor hüzünlerin korları

Bir tek ayak sesim karanlığı delerken

Edâlıca bir meltem esiyor denizden

Eşelenen bir kedi çöp tenekesinde

Sanki dans ediyor yıldızlar gökyüzünde

Mehtâbın aksi dalmış köpüklü sulara

Dalgalar sahile vuruyor peşisıra

Pırlanta kolye gibi şehrin ışıkları

Nâzikçe sarıyor körfezin gerdanını

Bir yıldız kayıyor ardında iz bırakıp

Sürüklüyor beni de arkasına takıp

Zaman tatile çıkmış hiç ilerlemiyor

Kederler artık beni ilgilendirmiyor

(5 Ekim 2005/İstanbul)', 'Gecenin mâtemi kaplıyor her yanımı İçimde yanıyor hüzünlerin korları Bir tek ayak sesim karanlığı delerken Edâlıca bir meltem esiyor denizde...', ARRAY['Türk Edebiyatı','Şiir','Timur İlikan']::text[], 8.5, '{"poet":"Timur İlikan","poet_slug":"timur-i-likan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/gecenin-matemi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çarpık Harfler', 'carpik-harfler-erdogan-ergin-4pgbp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'düşüncelerimin eskidiği oldu

gecelerin sabahı ayarlamadığı vakitlerde

uykusuz yazılar yazdım

dönemeçlerde kaldım

vakitlerin kuramadığım olduğu

kendimi sevmediğim

sevemediğim insanlardan biriyim

çirkinim

koyu sohbetlere, açık sözler anlattım

sözlerin nereye gittiği belli olmadı

aydınlığı karanlık zannettim

zifirin ne olduğunu bilmediğim günlerde

hayallerle boğuşuyorum, vakit geç değil

delice düşünceler saplanıyor beynime

üşüyorum, ürküyorum hayattan

karanlığı gördüğüm her gündüzde

aydınlığa hasret gecelerde 

ikilemler arasında kalıyorum

düşüncelerim eskiyor

delice şiirler yazıyorum

çarpık harflerle', 'düşüncelerimin eskidiği oldu gecelerin sabahı ayarlamadığı vakitlerde uykusuz yazılar yazdım dönemeçlerde kaldım vakitlerin kuramadığım oldu...', ARRAY['Türk Edebiyatı','Şiir','Erdoğan Ergin']::text[], 8.5, '{"poet":"Erdoğan Ergin","poet_slug":"erdogan-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/carpik-harfler-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pelin', 'pelin-gulcin-aksekili-6wp79', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'P apatyalar topla sarı beyaz mütevazi

E llerine batmasın cazibeli güllerin keskin dikenleri

L alelerle birlikte girsin baharlar bahçene

İ yilikler güzellikler mululuklar topla eteklerinde

N adide çiçeğim sen hepsinden güzelsin', 'P apatyalar topla sarı beyaz mütevazi E llerine batmasın cazibeli güllerin keskin dikenleri L alelerle birlikte girsin baharlar bahçene İ yi...', ARRAY['Türk Edebiyatı','Şiir','Gülçin Aksekili']::text[], 8.5, '{"poet":"Gülçin Aksekili","poet_slug":"gulcin-aksekili","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/pelin-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüzgarın Kızları', 'ruzgarin-kizlari-gulseren-onay-bplxq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bilmezdim 

Rüzgar babamın 

Bu kadar çapkın olduğunu

Estiği her mahallede 

Bir kızı doğduğunu

Öğrendim 

Artık önemsizim', 'Bilmezdim  Rüzgar babamın  Bu kadar çapkın olduğunu Estiği her mahallede  Bir kızı doğduğunu Öğrendim  Artık önemsizim...', ARRAY['Türk Edebiyatı','Şiir','Gülseren Onay']::text[], 8.5, '{"poet":"Gülseren Onay","poet_slug":"gulseren-onay","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/ruzgarin-kizlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık', 'yalnizlik-sedat-i-nci-0zpsh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Karanlık odamı aydınlatan bir mum,

Çektiğim zehrin dumanı sigaram,

Bir de yalnızlığım var odamda.

Migren gibi baş ağrım! 

Bir bataklıktayım,

Sesler canlanmış bugün,

İçine bütün kederleri toplamış kara bulutta,

Yağarken keder yağmuru, sokaklara,

Şemsiyesiz bekliyorum, 

Ağacın gövdesine kazınmış yazı gibi.

Yaşam kaynağımı değiştirdim, 

Ben, yalnızlıktan korkmazdım, şimdi korkuyorum,

Hücrelerim bölünmüyor yenilenmiyor artık,

Adrenalinim yüksek dozda! 

Sevginin doruğunda evim var, kuşlar bahçesinde,

Girmesin istiyorum başka hiçbir yaratık,

Yorgun yalnızlığım,

Bitkinim! 

Ya bırak beni sonsuza, yada al artık seninim,

Satırlar arkadaş yada veda,

Kalmak istemez gibiyim dünyada,

Yaşamak isterken canlı bir cesedi taşıyarak vücudumda.

Oynamak istiyorum bir çocuk gibi kelimelerle,

Suçlar işliyorum tahrik ederek onları.

Ben severim başlangıç taşıyan sonları…

Yırtık bir elbise gibi değersizleşen sevgim,

Artık giyinilmez olduysa; 

Çıkar at, yeni elbisen kaldıysa! 

Yada sözcüklerimin sihri bozulduysa; 

Bırak ve çek git ruhum! ; 

Yeni heyecanlı aşklara! 

Ben hazmederek hazımsızlaşıyorum,

Kimliksiz, yasak bölgelerde dolaşıyorum,

Ve bir lambanın ışığı gibi titriyorum,

Beni sana terk ederek gömüyorum.

Elimde değil, seni ürpererek özlüyorum.

Buzul çağında terleyerek seviyorum seni,

Ekvatorda bir yerdeyim,

Güneş ışıklarını dik alıyorum,

Vücudumun içinde tutsak olmuş eriyorum.

Bir gün tükenecek hacmi olan bedenim,

Doğarken kaybedecek seni.

Yeni hayatta bulmamak mümkün sevgini.

Devrimler oluyor ruhumda.

Yeni iktidarlar oturuyor tahtlarına,

İhtilallerden bağımsızım,

Almıyorlar hiç kimseyi yanlarına,

Bir halının desenindeki bir iplik parçası gibi,

Anlamımı yitiriverip belirginsizleşiyorum…

Ruhum, sar beni sensiz ekvatorda da üşüyorum.

Bir çemberin yarı çapıyım,

Diğer yarımı bulmaya yetmiyor pi sayısı,

Bir elektrik akımıyım, voltajım yükseliyor,

Korkarım ki ruhum; sevgin beni öldürüp de gidiyor.

Artık, değişmiş, kimliksiz yaşıyor bulacağım kendimi,

Silinmiş gibi hissedeceğim; beynimin anı köşesini,

Tanımlayayım istiyorum yalnızlığı; 

Birden bire iç çekmek gibi,

Belli bir zaman dayanıp sonra ölmek gibi,

Karanlık odalarda güneşle büyümek gibi,

Kayan iki yıldızın çarpışması gibi,

Kesilmiş parmaklarla yazmak gibi,

Küçük çocukları içinde yaşatmak gibi,

Uyurken gözlerini kapatmamak gibi,

Zaman geçirmek için kendini oyalamak gibi,

Bir yere geç kalıp ta koşamamak gibi,

Aynı şehirde yaşayıp buluşamamak gibi,

Bildiğin sokaklarda kaybolmak gibi,

Çok fazla şeyin hiç birini paylaşamamak gibi,

Üzerindeki kamburu atamamak gibi,

Kendini yıllardır uykusuz hissedip de yatamamak gibi,

Yaş dolarken gözlerin ağlamamak gibi,

Hiç halin yokken, yerinde duramamak gibi,

Sevgini herkesten saklamak gibi,

Nefret edipte sevdiğinden unutamamak gibi,

Telefonu alıp ta eline arayamamak gibi,

Andığında ismini “ruhum”; parçalanmak gibi! 

 03.05.2005', 'Karanlık odamı aydınlatan bir mum, Çektiğim zehrin dumanı sigaram, Bir de yalnızlığım var odamda. Migren gibi baş ağrım!  Bir bataklıktayım,...', ARRAY['Türk Edebiyatı','Şiir','Sedat İnci']::text[], 8.5, '{"poet":"Sedat İnci","poet_slug":"sedat-i-nci","theme":"Türk Şiiri","is_hero":false,"total_lines":78,"source_url":"https://www.antoloji.com/yalnizlik-284-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rezerve', 'rezerve-sedat-i-nci-08vu9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'REZERVE

Taksim de, İstiklal’de bırakıyorum ruhumu,

İlerleyerek kayboluyor kalabalığın arasında,

Metroda ki insan yüzlerinde arıyorum umudumu,

Bilerek olmadığını o kalabalıkta.

Gözlerimin altına çukurlar iniyor,

Mor ve itici,

Kanım dolaşamıyor damarlarımda,

Nefesim titriyor, ayaklarım halsiz,

Anlıyorum yok ruhum bu kalabalıkta! 

İnsanlar gülümsemekte, sevilmekte,

Yıllanmış şarap tadında umutlarım tükenmekte,

Şizofreni gibi sevgim çıkıyor,

Teşhisimi, bilmem hangi sokakta,

Kurtuluşun ortasında, uğur apartmanındaki; 

Anlatılmazım, vermekte! 

Dönüş alıyorum ayrılığa,

Çift kişilik koltukta tek kişilik boş yer; 

Ruhum için rezerve! 

Denizin serin havasını alıyorum bir nefes,

Bir nefes de ruhumdan aynı atmosferde,

İstila edilmiş topraklarda yaşıyor herkes,

Kimisi ayrılık için çok uzun seferde! 

Kimse fark etmiyor ruhum boş gözüken koltuğu istila ettiğini,

İlerlerken karanlık gecede ayrılık yollarına.

Kondurtuyorum gülücükleri, masum dudaklarına,

Sana yakışıyor tebessüm, sakın hiç çıkarma! 

Muavin tek kişilik servis yapıyor,

Benimse kalbim, seni fark edecek diye çarpıyor.

Kaçak yolcusu gibi oturttum seni yanıma.

Saniyeler dahi aramızda mesafeler açarken yakınlaşmak için,

Sensiz de anlam bulmak için,

İçerimde ki tahta sultan yapmak için,

Herkes varken de seninle olmak için,

Oturdun o boş koltuğa! 

Ahşap tahtalara bastık seninle,

Gıcırdadılar, isyankardılar,

Seni birbirlerinden de kıskandılar,

Bunun için bana düşmandılar! 

Parçalanmış camlar vardı görüntünde,

Bulanıktı, her sana dokunmak istediğimde.

Güvercinler kalbime çalı yapıyorlar, yuvaları yokmuş,

Onlarda izinsiz istila ettiler kalbimi.

Derin okyanuslarda bir kız çocuğu boğulmuş,

Çığlıklarında bir aşk bir de nefret bulunmuş! 

Annesiz değil, mor yüzünde ki gülümsemesi,

Sahipsiz değil sevgiliye ulaşmak istemesi! 

Saliselerde saatlik senaryolarla,

Buluşup tekrar kaybolmalarla,

Yüksek basınçtaki gibi patlamalarla,

Dolaştım ruhumla! 

                            11.05.2005- 20.34', 'REZERVE Taksim de, İstiklal’de bırakıyorum ruhumu, İlerleyerek kayboluyor kalabalığın arasında, Metroda ki insan yüzlerinde arıyorum umudumu...', ARRAY['Türk Edebiyatı','Şiir','Sedat İnci']::text[], 8.5, '{"poet":"Sedat İnci","poet_slug":"sedat-i-nci","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/rezerve-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '**Selim', 'selim-i-lhan-kirbac-f2hn9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Fidanlar,çiçekler yetiştirecekti,

Vatanına,milletine.

Ne ümitlerle yollara düşmüştü

Karadeniz''in sarp dağlarına.

Anasına,bacısına bakacaktı,

Kazanacağı üç,beş kuruşla.

Vatana,millete olan borcunu,

Ödeyecekti çalışarak canla başla.

Yatılı okumuştu pekçoğumuz gibi,

''''Fidanlar yetiştireceğim yurdum için,

Bu uğurda isterseniz  kefenimi biçin''''derdi.

Bu hevesle yollara koyuldu yel gibi.

Adı Selim''di,soyadı Aksakal,

Adı gibi selim,soyadı gibi ak.

Kalleşçe pusuya düşürdüler,

Hayallerine set çektiler.

Çiçekler,gençler yetiştirecekti,

Kendi gibi mert.

Kalleşçe pusuya düşürdüler,

Sevdasına perde çektiler.

O''nun sevdasını,onun gibiler 

Yaşatıyor şimdi.

Soyadı gibi ak,adı gibi selimdi,

Göğe yükselirken sanki bir melekti...', 'Fidanlar,çiçekler yetiştirecekti, Vatanına,milletine. Ne ümitlerle yollara düşmüştü Karadeniz''in sarp dağlarına. Anasına,bacısına bakacaktı,...', ARRAY['Türk Edebiyatı','Şiir','İlhan Kırbaç']::text[], 8.5, '{"poet":"İlhan Kırbaç","poet_slug":"i-lhan-kirbac","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/selim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir şehre varmalıyım', 'bir-sehre-varmaliyim-elazigli-mustafa-kaya-uu2vr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '(“…rabbim bu şehri güvenli kıl beni ve

oğullarımı putlara tapmaktan uzak tut…İbrahim-35..)

bir şehre varmalıyım

umutlarımın yeşereceği

özgürlüğümü bileceğim

acıları mutluluğa

karanlığı aydınlığa çeviren

selam yurdu edineceğim

bir şehir olmalı

aradığım şehir nerede..? 

dışarısı ürkütücü

en uğursuz sözler

yırtıyor ruhumu

gam ve kederleri topluyor

gösterişli vitrinler

arka sokaklar

hiç dürüst değiller

kalabalık insanlar

kalbim zayıf bir kuş

bir şehre varmalıyım

kızgın bir çölün kalbi de olsa

huzurla konmalıyım

güven versin bana

hangi şehir bekliyor beni

hangi şehir yaşıyor mutlulukla ….

Mustafa kaya

06.10.2005 

www.mustafakaya.net', '(“…rabbim bu şehri güvenli kıl beni ve oğullarımı putlara tapmaktan uzak tut…İbrahim-35..) bir şehre varmalıyım umutlarımın yeşereceği özgür...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/bir-sehre-varmaliyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dost', 'dost-gulcin-aksekili-5pmnw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dost dost diye arama dostunu aynada gör

Aynalar olmasaydı olmazdın insan bile

Tuvalinin üstünde en önde senin resmin

Arkandaki hayaller dost sandığın bin çif yüz

Ben kimim diye sorma bak aynada yüzüne

Gözlerinin içinden zavallı sen bakmakta

Arkana dönme bir an çok vakit kaybedersin

Yorgun ayaklarınla koş da diyemem sana

Dostların dost olsaydı, ağlarlardı seninle

Duvarlar bile buz kestiler soğuktan

Sen sen ol yalnızken geçtiğin her huduttan

Önce kendini götür isteyen geçsin ordan', 'Dost dost diye arama dostunu aynada gör Aynalar olmasaydı olmazdın insan bile Tuvalinin üstünde en önde senin resmin Arkandaki hayaller dost...', ARRAY['Türk Edebiyatı','Şiir','Gülçin Aksekili']::text[], 8.5, '{"poet":"Gülçin Aksekili","poet_slug":"gulcin-aksekili","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/dost-111-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birgün Geleceğım Dağlara Kardelen Çiçekleri', 'birgun-gelecegim-daglara-kardelen-cicekleri-ahmet-nural-ozturk-u468l', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Birgün geleceğim dağlara kardelen çiçekleri 

Burnumda gençlik duyarlığı saçlarımda ak

Zulamda silah taşımam ben sen sadece gözlerime bak

Mustafa Kemal''li göreceksin

Ve anlatacağım sana bir Ermeni gelini hikayesi

Dedenin kanı nasıl düşmüş pusuya 

Kanda  büyüyen kardelen çiçekleri

Nenenin gözyaşları şimdi postallarının altında

Kendi dağlarına silah çekmenin duyarsızlığında

Birgün geleceğim dağlara kardelen çiçekleri

Kurtaracağım yalnızlığı yanılgıdan 

Sen üzülsen de üzülmeyecek kardelen çocukları

Güneş doğacak balçıktan..', 'Birgün geleceğim dağlara kardelen çiçekleri  Burnumda gençlik duyarlığı saçlarımda ak Zulamda silah taşımam ben sen sadece gözlerime bak Mus...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Nural Öztürk']::text[], 8.5, '{"poet":"Ahmet Nural Öztürk","poet_slug":"ahmet-nural-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/birgun-gelecegim-daglara-kardelen-cicekleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nasipler Ve Nasipsizler…', 'nasipler-ve-nasipsizler-zulfikar-yapar-kaleli-8kr4v', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Vardır beni tutmanın beni tutmaktan farkı

Hakkıyla tutanlara yücelerden Bir bakar! 

Gönüllerde aynı şevk, dillerde aynı şarkı,

Vuslata giden yolda, rehber olan er bakar. 

Sessiz sedasız geldim, duymazsanız giderim

Kendi kendime yanar, feryat, figan ederim.

Kalbimi kıranlara, ne gücenir, ne derim

İsteyen tutar beni, istemeyen hor bakar.

Alnı yere gelmeyen “nadide yiğitleri”

Karaltısı silinir, dinlemez öğütleri

Secde de tüm mahlukat, çiçeği, söğütleri

Nimetten nasipsizler bu aleme kör bakar. 

Korkuyu boncuk gibi bir ipe diziyorum

Başım önüme eğik, sedasız geziyorum

Gönülde sadece zan, ben bunu seziyorum

“Merhametin, varlığı kuşatır mı? ” Der, bakar.

Sezmek dursun bir yana, kulağımız duymuyor

Nefisler gündelikçi, kızarıyor, doymuyor

Güneşler esarette, zaman bize uymuyor

Biz zamana uyarız, düşünmeyiz YER bakar! 

Kendine gelme vakti, içerime od düşer

Dosta muhtaç zamanda, dost dediğim yad düşer

O’na boyun eğerim, bilincime tad düşer

Baş eğdiğim kapıda, ahvalime pir bakar.', 'Vardır beni tutmanın beni tutmaktan farkı Hakkıyla tutanlara yücelerden Bir bakar!  Gönüllerde aynı şevk, dillerde aynı şarkı, Vuslata giden...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/nasipler-ve-nasipsizler-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '(Tahlil) Karıncanın Gölgesi Olabilmek -Yorum', 'tahlil-karincanin-golgesi-olabilmek-yorum-mustafa-ceylan-o59th', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kimden: hasanbildirki (Bay, 58)    

 Kime: Mustafa Ceylan

 Tarih: 4.10.2005 17:25 (GMT 2:00)   



 Konu: “KARINCANIN GÖLGESİ” OLABİLMEK 

ŞİİRLERLE ŞAİR ÇİZGİSİ 

OYHAN HASAN BILDIRKİ 

“KARINCANIN GÖLGESİ” OLABİLMEK 

YEŞİL KARINCANIN DÜŞ YOLCULUĞU 

Yeşil karıncanın düş yolculuğu 

Uyusam, uyansam gözbebeğimde... 

Hasretin tokmağı iner de çıkar 

Ömür avlusunun aşk dibeğinde... 

Tutamam kendimi burda sensizim 

Sevda saatinin zembereğinde... 

N’ideyim? 

Çaresizim... 

Yüce dağ yolcusu yeşil karınca 

Adımları küçük, yüreği büyük 

Bir iner, bir düşer, bir kalkar garip 

Ağrı Dağı sanki sırtındaki yük... 

Gölgesiyim karıncanın, sessizim 

Yollar girdap girdap, yollar hep höyük: 

N’ideyim? 

Çaresizim... 

Mustafa CEYLAN 

(PAŞA GÖNLÜM, Şiirler. Antalya / 2005, Sayfa: 25)   

Aklını bir yere odaklamaya gör. Ne yaparsan yap, ne edersen et; düşünce ve duygu tohumlarının tamamı, o noktada filizlenir, şah çıkarır, büyür. Mümkünü yok, hayatına renk veren ya da öyle olmasını istediğin durumlar, yakanı bırakmaz. 

“Yeşil karınca”, amacı uğruna oldukça zor bir yolculuğa çıkar. Çoklarına göre bu yolculuk, bir “düş yolculuğu”dur. Gerçekleşme şansı, belki de hiç yoktur. Ona rağmen, bu yolculuğa çıkılır. 

Amaca ulaşmak, hangimizin takıntısı değildir? Bu takıntı, hem uykuda, hem de uyandığımızda; mıh gibi, gözbebeğimizde çakılı durmaz mı? Bu da bizi, “unutulmaması gereken”e götürmez mi? Hayata tutunmak için attığımız adımlarımızın izinde, amacımızın gölgesi yok mudur? 

Girişi uzattım. Aslında benim anlatmak istediğim bunlar değildi. Yakamı kaptırmışım ya kalemime, koparamadım. Oysa “ömür avlu”muzda neler yok ki? .. Hasretlerimizin tokmağı, avlumuzdaki “aşk dibeği”nde iner çıkar. Dövüle dövüle olgunlaşırız. Bu olgunlaşmanın neticesinde, çaresizliğe düştüğümüz zamanlar da olur. O zaman bağla-nacağımız birini, “sen”i ararız. O, dostumuz ya da sevdiğimizdir. Buluşma saati yaklaştıkça, “sevda saati”nin zembereğinde eziliriz. 

“Yüce dağ yolcusu yeşil karınca”, aklımıza düşer o saat. Ömür avlumuzdaki dibeği döven tokmağın verdiği acılara katlana katlana, türlü çaresizlikler içinde, kabaran yüreğimizin sellerine kapılarak, “Ağrı Dağı”na dönmüş yüklerimizden kurtulmak için, karıncanın gölgesi olmaya can atarız. 

Atarız ya? .. Yollarımız kavşaklarla, dönemeçlerle, çevrintilerle, gittikçe derinleşen çukurlar, çöküntülerle kesilmiştir. İşte bu noktada ne yapalım? Dönelim mi, ilerleyelim mi? 

Ceylan’ın kahramanı, şiirdeki karıncaya dönelim. Demek ki o, ilerlemiş, ne kadar zorlu olursa olsun, kendisini amacına götürecek olan bütün yolları aşmış. Aştığı yollar, zor yollar... Bu yollar; zaman gelmiş “tokmak” olmuş, zaman gelmiş “dibek” olmuş, zaman gelmiş “zemberek” olmuş. Üç öğenin özelliklerine şöyle böyle de olsa bir göz atalım: Tokmak dövücü, dibek dövüleni içinde tutan, bütün fırsat kapılarını kapatan, zemberek de dişli çarklarıyla çeviren ya da geren değil midir? 

Karınca oldukça metin, büyük yüreklidir. İnse, düşse de kalkar, omuzladığı yüke aldırmaz, yolunca ilerler. 

- “Ah! ” diyorum, “Biz, karıncadan ibret alsak da, onun gölgesi olabilsek... Değmez mi? 

Yaşadığımız yüzyılı kirletenlerin, yüzyıla ağıtlar yaktıranların karşısına çıkabilenlerin “gölgesi olabilsek”, fena mı olur? 

Sevgilerimle..

O.Hasan BILDIRKİ

Söke / AYDIN', 'Kimden: hasanbildirki (Bay, 58)      Kime: Mustafa Ceylan  Tarih: 4.10.2005 17:25 (GMT 2:00)     Konu: “KARINCANIN GÖLGESİ” OLABİLMEK  ŞİİRL...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/tahlil-karincanin-golgesi-olabilmek-yorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tevazu', 'tevazu-gulcin-aksekili-tac37', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Mütevazi düşlerimden gelen anılar besler kaderimi

Çiçek koparmaya bile kıyamazken ellerim

Kırılası eller büker bileğimi

Anlarsın bu dünyanın tüm sahteliklerini

Saltanat kayığında seyrederken maziyi

Göremezsin hapisliğini duyamazsın gönlünün çığırtkan sesini

Tam yol alırken usul usul

Kör bir dalga vurur kaderine

Ne kadar dikkatli açsan da gözlerini

Kamaşır gecenin zifiri karanlığında

Çık görkemli sarayından bak insanlara ne yer ne içer

Yamalı perdelerinin aralığında', 'Mütevazi düşlerimden gelen anılar besler kaderimi Çiçek koparmaya bile kıyamazken ellerim Kırılası eller büker bileğimi Anlarsın bu dünyanın...', ARRAY['Türk Edebiyatı','Şiir','Gülçin Aksekili']::text[], 8.5, '{"poet":"Gülçin Aksekili","poet_slug":"gulcin-aksekili","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/tevazu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Buruk veda', 'buruk-veda-elazigli-mustafa-kaya-74h7r', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'uğurladım ,

geceyi  az  geçe..

kaçıncı  ayrılık  tekrarıydı  bu,

iki  yabancının uzaklığı  vardı.

ve,

biricik  kızımın çabası  boşunaydı.

ne  bir  el  salladın

ne de  bir  gülüş vardı

ölgün  başın  cama  dayalı

feri  sönmüş  gözlerinden

acı  bir  tebessüm  yayıldı.

ve  solgun  yüzün,

gece  kadar  derindi.

sımsıkı  sarılmış   bedenler  olamadık

ayrılıklara  dayanıksız

ve

gözyaşı  dökmedik birbirimize.

anlamı  bitmiş  bir vedaydı,

oysa ,

acılarla  sarılı  ruhumu  dindirecektim.

bir  umut  ışığı  görecektim..

bir  dokunuşun  yeterdi..

şimdi gece  kadar  yalnız  kalacağım

ve  gece  kadar  uzun  bekleyeceğim

uğurlar  olsun  canım

bu  kaçıncıydı   alıştım.

hangi  düşüncelerin  esirisin

çözemedim  hangi  boyutlarda  gezersin

iki  yabancı  yaptı  bizi

paranoya  duruşların  .

hadi  yollarınız  açık  olsun

canım  kızım.

bağrış  çağrışlarına  kırılmadım

ben  sizi  hep  seveceğim

sizi  hep bekliyeceğim …..

                                                                     08.08.2004 / harem

                                                                      mustafa kaya

www.mustafakaya.net', 'uğurladım , geceyi  az  geçe.. kaçıncı  ayrılık  tekrarıydı  bu, iki  yabancının uzaklığı  vardı. ve, biricik  kızımın çabası  boşunaydı. ne...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/buruk-veda-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seninle Başlayacak Sabahların Muştusu', 'seninle-baslayacak-sabahlarin-mustusu-melih-coskun-bu4fm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seninle başlayacak sabahların 

Muştusunu veriyor penceremde kuşlar 

Sakat doğmuş çocuklarının 

Rüyalarında çılgınca koştuğu yalan gecelerin sonrasında. 

Ben ki, 

Dört yanı duvarlarla çevrilmiş bir avluda açan çiçek gibi 

Tutsak yaşamışım yıllar yılı 

Ve yokluğun 

Etime saplanan kırık bir cam parçası gibi 

Acıtmış sürekli canımı 

Kollarına zincirler vurulmadan, 

Kapanmadan demir kapılar üzerine 

Yani özgürken tutsak olmak nasıldır bilir misin? 

Bir baksana

Zaman nasıl değiştirmiş bizi 

Nasıl eskimiş gülüşlerimiz, 

Siyah beyaz öpüşlerimiz

''Ağlamak bize yakışmaz ''derlerdi eskiden 

Şimdi ne zaman hatırlasam eski dostlarımın yüzlerini 

İki gözüm iki çeşme... 

Militan kuşlar uçuşuyor penceremin önünde 

Seninle yaşanacak günlerin muştusunu veriyorlar yine bana 

Belli ki bu sabah güneş biraz daha parlak doğacak...

2004', 'Seninle başlayacak sabahların  Muştusunu veriyor penceremde kuşlar  Sakat doğmuş çocuklarının  Rüyalarında çılgınca koştuğu yalan gecelerin ...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/seninle-baslayacak-sabahlarin-mustusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'D i r e n ç', 'd-i-r-e-n-c-nevzat-erkol-ytk39', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hüzünlü gecelerde kalmışım, yapayalnız

Bekliyorum çaresiz kim bilir böyle neyi

Ve sil baştan etmişim bir kalemde her şeyi

Bir hesap sonrasında bu da mı olacaktı,

Sen de mi peşim sıra mendil sallayacaktın

Sen de mi benim gibi sessiz ağlayacaktın

Gurbet şarkılarını sevmedim hiçbir zaman

Neden bunca yıl sonra boynum bükük kalayım,

Neden bir hiç uğruna gurbette kahrolayım.

Acımasız yılların bana ettiğine bak,

Ne oldu saçlarıma, hani gençliğim nerde

Özlemlere bürünmüş biri yaşıyor bende

Son günün akşamına kalmadan döneceğim

Ve inan ki bir tanem, ve inan ki meleğim

Ellerim ellerinde, dizinde söneceğim.

1981 - Fransa', 'Hüzünlü gecelerde kalmışım, yapayalnız Bekliyorum çaresiz kim bilir böyle neyi Ve sil baştan etmişim bir kalemde her şeyi Bir hesap sonrasın...', ARRAY['Türk Edebiyatı','Şiir','Nevzat Erkol']::text[], 8.5, '{"poet":"Nevzat Erkol","poet_slug":"nevzat-erkol","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/d-i-r-e-n-c-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ta Derinde', 'ta-derinde-yasar-aslan-7hima', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'gece yıldızlar düşüyor

kıyamet kopuyor ta derinde

içimdeki çocuk ölüyor

sıcağın soğuğu iliklerimde

tüm alışmışlıklarımı geride bırakıyorum

ilk aşk şehrim

ilk göz ağrım 

yosmalarım

diclenin öfkesine armağan ediyorum

hüzün bu olsa gerek 

zoruma giden öfke

balzalta bulanmış yüreğim

öfkeyle 

yitik sevdalara

elveda diyor', 'gece yıldızlar düşüyor kıyamet kopuyor ta derinde içimdeki çocuk ölüyor sıcağın soğuğu iliklerimde tüm alışmışlıklarımı geride bırakıyorum i...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Aslan']::text[], 8.5, '{"poet":"Yaşar Aslan","poet_slug":"yasar-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ta-derinde-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küçüğüm 2-', 'kucugum-2-evren-dalgic-11kvo', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bitti,

her biten gün gibi.

her ölen; 

canlı gibi.

sönmeyen her ışık 

bir bir söndü,

o çiçeklerimiz vardı ya; 

sanki hepsi küldü.

sana küçüğüm derdim,

o küçük olanlar

şimdi çoktan büyüdü.

rüyalar bitti,

gece sabaha döndü.

şiirler sustu,

şarkılar ikiye bölündü.

bitti aşkımız,

anlatılan masala döndü.

aşklar soldu,

sözler unutuldu.

ateşler söndü,

küçükler büyüdü.', 'bitti, her biten gün gibi. her ölen;  canlı gibi. sönmeyen her ışık  bir bir söndü, o çiçeklerimiz vardı ya;  sanki hepsi küldü. sana küçüğü...', ARRAY['Türk Edebiyatı','Şiir','Evren Dalgıç']::text[], 8.5, '{"poet":"Evren Dalgıç","poet_slug":"evren-dalgic","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/kucugum-2-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen olsaydın', 'sen-olsaydin-hekim-coskun-9fywm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'sen olsaydın; 

bir solukta geçer giderdim karşı kıyıya

aldırmazdım,

ne dalgasına denizin

ne tuzuna.

bak sensiz atan şu yüreğim; 

teklerse bir gün

günahı vebalı senin boynunadır

sen olsaydın; 

bir solukta bitirirdim

bu romanı

ve anlatırdım,

özetlenmiş bu yaşamın kısa tarihini.

sen olsaydın; 

birlikte oturur hayal kurardık,

tek başına zor oluyor bilirsin.

yani gelecek güzel günleri inşa ederdik mesela.

ben amelesi olurdum,

sen harcı yaşamın.

sen olsaydın; 

yelken açardık okyanuslara

gözlerimiz maviş

ellerimiz yosun

nefesimiz güneş kokuyor olurdu.

sen olsaydın; 

köhnemiş bu düzenden çekip çıkarırdık yaşamı

yeniden yeşertirdik tüm umutları

ben toprak olurdum

sen su.

sen olsaydın; 

kanlı çatışmalara gebe ülkemde,

umut ekerdik denize.

ben sana sarılır seni koklardım.

sen beni bi öp,

ben mutlu bakayım yarınlara.

www.antoloji.com\hekim_coskun', 'sen olsaydın;  bir solukta geçer giderdim karşı kıyıya aldırmazdım, ne dalgasına denizin ne tuzuna. bak sensiz atan şu yüreğim;  teklerse bi...', ARRAY['Türk Edebiyatı','Şiir','Hekim Coşkun']::text[], 8.5, '{"poet":"Hekim Coşkun","poet_slug":"hekim-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/sen-olsaydin-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık', 'yalnizlik-yunus-isikoglu-gmmta', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hep kalkmaya yelteniyorum

Halbuki nereye gideceğim ki

Nasıl sa nereye gitsem aynı

Düğün bayram hep aynı

Benim için her yerde aynı yalnızlık

Ha burada oturmuşuuum

Ha oraya gitmişim.', 'Hep kalkmaya yelteniyorum Halbuki nereye gideceğim ki Nasıl sa nereye gitsem aynı Düğün bayram hep aynı Benim için her yerde aynı yalnızlık ...', ARRAY['Türk Edebiyatı','Şiir','Yunus Isikoglu']::text[], 8.5, '{"poet":"Yunus Isikoglu","poet_slug":"yunus-isikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/yalnizlik-285-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deli Deli Kulakları Küpeli!', 'deli-deli-kulaklari-kupeli-nazife-abayli-i0hlg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Uçuk kaçık bir Yusufçuk,

Almış eline zilleri,

Giymiş yırtık pırtık elbiseleri,

Şıkıdım şıkıdım,

Koyvermiş ipleri....

''Bozuk paran var mı abi! ''

Adam gibi adammış Yusufçuk,

Zamanının delikanlısı,

Kızların tavlamakta yarıştığı deli mi deli,delikanlısı,

Kazandığı bir lokmayı paylaşan dost canlısı,

Zenginin düşmanı,

Fukaranın yanlısı,

Sevgi arsızı.......

Bir gün karşısına çıkıvermiş davalısı,

Bir iki derken,yemiş onlarca tüfek saçmasını,

Uçuk kaçık oluvermiş Yusufçuk...

Almış eline zilleri,

Giymiş yırtık pırtık elbiseleri,

Şıkıdım şıkıdım,

Koyvermiş ipleri....

''Bozuk paran var mı abi! ''

Saç sakal karışık Yusufçukta,

Gözlükleri desen düşmüş burnun altında,

Elinde zilleri,ta yangının ortasında,

Yanmışta umursamaz,oynar kendi sevdasında.! 

Bir Yusuf geçti bu memleketten,

Bir de Yusufçuk geçmekte..

Bilinmez ki O, hangi yola gitmekte? 

Hani derler ya deli,

Deli deli kulakları küpeli...

Neden deli oldun be deli? 

Uçuk kaçık oluvermiş Yusufçuk...

Almış eline zilleri,

Giymiş yırtık pırtık elbiseleri,

Şıkıdım şıkıdım,

Koyvermiş ipleri....

''Bozuk paran var mı abi! ''

(Sadettin''in anısına....Toprağın bol olsun dost!)', 'Uçuk kaçık bir Yusufçuk, Almış eline zilleri, Giymiş yırtık pırtık elbiseleri, Şıkıdım şıkıdım, Koyvermiş ipleri.... ''Bozuk paran var mı abi...', ARRAY['Türk Edebiyatı','Şiir','Nazife Abaylı']::text[], 8.5, '{"poet":"Nazife Abaylı","poet_slug":"nazife-abayli","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/deli-deli-kulaklari-kupeli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasret Tınısı', 'hasret-tinisi-gulden-karabudak-3czyu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Uzak şehirlerin türküsüne el vermiş

Yağmurun ıslatamadığı bir umuttur gelişin

Giderken bakma geriye 

Gurbete inanır ağlarım demiştim

Şimdi…! 

Sözlere sığınıp bugünleri çizdim

Takvimde yürek atışı var mıdır ki

Iskalıyorum belki,

Utanç içinde mırıldanıyorum

An’larımı kaybettim

Bir yudum sesini bekliyorum

Mecburluğuma kilitlenmiş sızılar

Adam gibi ağlayamıyorum.

Yorgunluğuna geldim

Harfleri birleştirdim kendimce

Seni çok seviyorum… 

			

05.10.2005

			    00:30', 'Uzak şehirlerin türküsüne el vermiş Yağmurun ıslatamadığı bir umuttur gelişin Giderken bakma geriye  Gurbete inanır ağlarım demiştim Şimdi…!...', ARRAY['Türk Edebiyatı','Şiir','Gülden Karabudak']::text[], 8.5, '{"poet":"Gülden Karabudak","poet_slug":"gulden-karabudak","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/hasret-tinisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pişmanlığın deminde', 'pismanligin-deminde-evren-dalgic-nvwds', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'geçen hangi acıdan 

seni sorabilirim.

hangi çekilen derdimden

seni isteyebilirim.

Aslında seni ben hak ettim,

o geçen her günde; 

zincirlere vurulan bendim.

Bekleyen bendim gözlerini,

takvimleri yırtan,

sensizlikte ağlayan,

olmaz denen her engeli,

mucizelere bağlayan.

yanlışlara dalmışım,

koskoca bir gençliği; 

göz göre göre yakmışım.

şaşkınım şimdi,

elinde birşeyi olmayan.

bir keder var ellerimde,

onunla yanıp onunla oyalanan.

Bir gençlik ellerinde bitti,

en güzel yıllarım

yollarında tükendi.

şimdi dönülmez yollardayım,

keşkelerle dolu pişmanlıktayım.

sormayın beni artık; 

ne gülden ne de bülbülden,

ben yalnız yaşamış; 

bir deli rüzgarın rıhtımandayım.

yanlışım,

yanıldım.

biliyorum çok geç,

ben herşeyin farkındayım.

sessizce oturmalıyım bir yere,

başımı almalıyım ellerimin arasına,

ben bu gece en iyisi

bir güzel ağlamalıyım.

Mübarek gecenin 

son demine girerken,

son defa geçip pencerenin önünden; 

bir gökyüzüne çıkıp,

bir yeryüzüne kaymalıyım..

Ankara Ekim 2005)', 'geçen hangi acıdan  seni sorabilirim. hangi çekilen derdimden seni isteyebilirim. Aslında seni ben hak ettim, o geçen her günde;  zincirlere...', ARRAY['Türk Edebiyatı','Şiir','Evren Dalgıç']::text[], 8.5, '{"poet":"Evren Dalgıç","poet_slug":"evren-dalgic","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/pismanligin-deminde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sev Çocuğum', 'sev-cocugum-abdullah-yasar-erdogan-z0u5n', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sevgilerin en büyüğü sendedir.

Sev çocuğum.

Kederi, elemi tatmayasın,

Tatlı, şirin çocuğum.

Sevgi, mutluluk dolsun kalbin,

Yücelmek olsun hep emelin,

Sen, sen meleksin çocuğum.

Çocuk; sevginin temelidir,

Gelecek nesil sizlerindir,

Sen sevmeyi sakın unutma,

Herkesi, her şeyi sev çocuğum.

Aklınla karar ver, Hakk olsun,

Daima alnın açık, pak olsun.

Gelecek sizlerindir ak olsun,

Sen de seni yaratanı sev çocuğum.', 'Sevgilerin en büyüğü sendedir. Sev çocuğum. Kederi, elemi tatmayasın, Tatlı, şirin çocuğum. Sevgi, mutluluk dolsun kalbin, Yücelmek olsun he...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Yaşar Erdoğan']::text[], 8.5, '{"poet":"Abdullah Yaşar Erdoğan","poet_slug":"abdullah-yasar-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sev-cocugum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Türk Çocuğu', 'turk-cocugu-abdullah-yasar-erdogan-urcdq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ey Türk evlatları,

Unutma ecdatlarını,

Nasıl feth etti dünyayı? 

Oku, oku Türk çocuğu.

Sendedir İslâmiyet, 

Sendedir hürriyet.

Yükselecekse millet,

Oku, oku Türk çocuğu.

Sendedir ilim, irfan ocağı.

Şimdi sırası yükselme çağı,

Hep dalgalanmalı ilim sancağı,

Oku, oku Türk çocuğu.', 'Ey Türk evlatları, Unutma ecdatlarını, Nasıl feth etti dünyayı?  Oku, oku Türk çocuğu. Sendedir İslâmiyet,  Sendedir hürriyet. Yükselecekse ...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Yaşar Erdoğan']::text[], 8.5, '{"poet":"Abdullah Yaşar Erdoğan","poet_slug":"abdullah-yasar-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/turk-cocugu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sus çekirdeği / Düş kırılmaları', 'sus-cekirdegi-dus-kirilmalari-zafer-zengin-etnika-oqfio', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '.

Sessizlik başlamış yine ve ben anlıyorum ki bu sessizliğin içinde, müzik varsa çoktan olmuştur gece..Gece yaşıyorum yalnızım, saklı gizli okunan mektuplar gibi..Noktalar virgüller dolaşıyor içimde..biraz koşayım diyorum, bir şarkıya yakalanıp

Sesini duyup “orda olsam var ya, atlardım üstüne, ısırırdım seni kıtlardım” demeni düşünüyorum..Sen konuşuyorsun halen “ben büyürken sen neredeydin”, hep buradaydım diyorum kendime,hep burada..Bıyıklarımı kurcalıyorum,öyle erkeğim ki senin düşündüğüm anlarda, nedense çocuklar geliyor hep aklıma..yapacaklarım arasına adları da sığıyor ya, sen 

de doğur ne var sanki diyorum.. Yedi tane olsun istiyorum, birinin adını ben koyayım, diğerlerinikini sen. Gece nasılsa görmez kimse deyip, hiç görmediğim koynuna sokulup sus gelsin diye bekliyorum.. Sus ne zaman gelir, bir sen biliyorsun.  Yeminler olsun ki senden başka kimseye demedim, demiyorum..

O kadar ölüm varken birileri tamamlıyor onları.Sen ben üremiyorken ve susa durmuyorken,  birileri bizden, Habersiz çocuk saklıyor..mevsimi gelmiş tomurcuk gibi patlayıp duruyorlar ve bu sesler seni içimden sökün ediyorlar.. Şimdi ayaklarım üşüyor,soğuktan biraz da cinayetler geliyor aklıma, Güzel bir film sinemada Şimdi şu sancım geçmeli seni görmedim ondan belki. Portakal, sigara yoldaşlığında yarı uykulu yazılar yazıyorum sana..işte dedim ya mektup gibi, seni düşünmek şimdi. 

Bu günü anlatmadım sana biriktirmeleri hınçları mesela..Yolda gördüm topal kuş ve bir takım biley taşı on bıçak satan adamı..”

-Alır mısın abi, beş milyon hepsi

-Ben de iki takım var bundan dedim, iki sene evvel almıştım.  Güldün değil mi, anladın yalan söylediği mi.. sonra dönüp kavşaktan, içimi tutan o yerden, o anda fırladım aşağı. Şehrin rahmine, insan dolu merkezine. Sorma hiç birinin yüzünü hatırlamıyorum. Hızlı giderken göz görmüyor iç düşünüyor sadece. Araba sürdüysen sen de bilirsin işte..bir küfür ediyorum şimdi “ a be hayvan adam sinyal versene.. sövüyorlar mı ulan sinyal verince, bak sinyal vermedin, asıl küfrü şimdi yedin “ diyorum.. Yoldayken bile düşünüyorum

Yollar da düşünmek gibi. Ne başı belli, ne sonu.  Soracaktım unuttum, üşüyor mu hala ellerin, memelerin, dudakların, gözlerin. 

Acıktım da, saatte geç.. yemek kalmamıştır  bana şimdi..

Düşünüyor musun bana diyorsun ya “ evet “ diyorum sana, vallahi doğru. Çok kadın sevmek, en güzel iş şimdi..Küsersen konuşmam bak.. O kızanlar kadar haksızsın çünkü..Hep kızıyorlar ya “ insan sevgisi  yok mu ulan sende.Sevmeyi öğrensen ölür müsün diyenler.

“ yahu benim işim gücüm sevmek “ dedikçe.. “hastir “ çekiyorlar.. Umursamıyorum. Sevmek bu işte diye bir yerinden başlıyorum. Aç bir çocuğun önüne sen tut ekmek aş koy, yeme de gibi..bile bile oruç bu sevmemek işi. Sonra diyorum ki; lego gibi her aşk büyütüyor bütünü,  tekte kalanlar bulmacayı tamamlayamayanlar.. Belki de bir aşkı görüp ikinciden korkanlar.. Kızmıyorum onlara, bir yerde kalmak kolay nasılsa.. sevmek bu yüzden güzel.. vampirlik yoksa yanında..sen onlara benzeme..çoğu gitti dönmedi içleri geriye.

Sigaram bitti.. içimin kurtları yolda şimdi etimi kemiğimi kurcalıyorlar..Kemik neyse de,etimi  kemirmeleri kesiyor beni ince ince..Düşüyorum, düşüncenin dibine.  Dibinde kendi kendime.  Sen de olmasan sıyırırdım, bakamazdım halime..Canım cekti dur kendimi seveyim. Yerine koyacak yine bir ben varım..canım, canımmm

Kopuyorum..Satırlarımı burada bırakıp uykuya gidiyorum..Erken gelirsen güleriz biraz..Çekirdek  çitleriz,  ben ön dişlerimde kırar kabuklarını,çıkarırım içlerini..Böyle bir avuç  olunca sana uzatırım. Bir avuç çiğnersin iyi mi.. Neden öyle bakıyorsun,  sevişeceğiz elbet,  Şimdi erken değil mi, hem çekirdekte bitmedi ki.. ıımm.. elinle..ımmm yau dursana  az. anladım.. artık susmalı....

“ o an “ 2005

kimsenin kimseyle olmadığı an’dır..korkulmadan ve yaşandığı halde ayıplanan sevişmeler 

üzerine, sırf iç kıpırdatsın, az üzerinde düşünülüp özlediğimiz o mahremiyet yeniden anılsın

diye yazılmıştır..kişilerle alakası yoktur..insanla alakası vardır..üzerine alınmak..gücenmek

ve darılmak ikinci bir yaşama kadar yasaktır..

ne arıyorum burada diyene; 

şimdi ömrü düşün, kime gülüyor yüzü..saklayana mı.. saklanana mı..kendini kandırmayı kolay sanana mı.. her kimsen, bağışla ve düş kur. 

.', '. Sessizlik başlamış yine ve ben anlıyorum ki bu sessizliğin içinde, müzik varsa çoktan olmuştur gece..Gece yaşıyorum yalnızım, saklı gizli ...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sus-cekirdegi-dus-kirilmalari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tut e l i m i / c a n kırılmaları...', 'tut-e-l-i-m-i-c-a-n-kirilmalari-zafer-zengin-etnika-xllw8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Tut elimi 

hastayım cane

göğsümün orta yeri yangın

başıma toplamışım hayatı

ah ağrım ah ağrım

acıma dil sürüp

türkülerde kaldım

hastayım cane

yüzyılım var tutuştuğum

çare düşünmez ellerimle

üstünü örtüyorum geceleri

sen uyurken

boynu bükükleri topluyorum

kırık kolumu içime sarıp

yanağından öpüyorum

kopuyor

sert çekilen akordun da

- ince çıkar ses..ip ince -

bağlamamın teli

telli turnalar geçiyor iç''imden

katıyorum adını turnalara

türkülerin ortasında

oyy canım 

bin yıl hasret kokanım

kavuşmak gülmekse

gülmekte özlemekse

özlemek ayrılık demekse

geliyorum yüzüne

turna sesleriyle

tut elimi

yüreğimin gölgesinde

ismim can de..

01 12 2004

Bahsi geçenler ölümlüdür..her gün sokaklarda gezerler..

evleri barkları vardır..herkes gibi yaşarlar..sonra sessizce giderler.

Kıyafetleri herkese uyabilir..maske çıkarılınca en sevimli hallerini bulurlar.

Onları sevenler kendilerini sevmiş olurlar..sonra herkes işine bakar

Yazanda kendini bir şey yaptım sanıp oyalar..Yaptığımız keşifler bizimdir.

.', 'Tut elimi  hastayım cane göğsümün orta yeri yangın başıma toplamışım hayatı ah ağrım ah ağrım acıma dil sürüp türkülerde kaldım hastayım can...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/tut-e-l-i-m-i-c-a-n-kirilmalari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nasıl Bilirdiniz?', 'nasil-bilirdiniz-abdullah-yasar-erdogan-q1m1j', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir yada birkaç kişi,

Veya kalabalık bir cemaat.

Toplanacak ve namazını kılacaklar,

İmam soracak oradakilere; 

“Bu mevtayı nasıl bilirdiniz? ”

Bazıları iyi, bazıları içten mırıldanacak.

Mırıldanan da gelecek bir gün oraya.

Mutlaka herkesin uğrayacağı yerdir orası.

Herkese burada  sorulanın aynısı sorulur.

Bundan sonra ayrımcılık asla olmaz.

Herkes aynı çukura aynı elbise ile girer.

Kişi ile beraber giden sadece,

Amel defterinden başka bir şey olmaz,

Gelmeden önce insan, amel etmeli,

Güzellik dolmalı amel defteri.

Nasıl bilirdiniz’i,  insanlar iyi bilmeli.

Herkese de iyi bilirdik dememeli.', 'Bir yada birkaç kişi, Veya kalabalık bir cemaat. Toplanacak ve namazını kılacaklar, İmam soracak oradakilere;  “Bu mevtayı nasıl bilirdiniz?...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Yaşar Erdoğan']::text[], 8.5, '{"poet":"Abdullah Yaşar Erdoğan","poet_slug":"abdullah-yasar-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/nasil-bilirdiniz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vah Ki Vah', 'vah-ki-vah-abdullah-yasar-erdogan-evq4c', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yine sirenler çalıyor,

Beynimin içinde.

Trenler köstebek misali,

Depreşiyor kafamın içinde.

Yer altından gelen sesler,

Yer üstünü titretirler.

Vah bana, vah ki vah.

İçimdeki sirenlere koşamam,

Gem vuramam düşüncelerime,

Çıldıracağım neredeyse,

Dört bir yanım hain dolu.

Vah bana, vah ki vah.

Beynimi kemiren nedir bilemem,

İyilik beklemiyorum kimseden,

Sorun benim içimde ise eğer,

Benim bedenim bunu çözer,

Yok dışardan ise, ki öyle; 

İşte o zaman sirenin yok sonu.

Vah bana, vah ki vah.

Mazlumlar için haykıramadım,

Zalimlerin karşısına çıkamadım,

Bedenimin isyanı doruğa çıktı,

Elime verin odun, başıma vurayım.

Hücrelerim benden bıktı.

İsyanım var bu düzene,

İsyanım var insanı üzene.

Karşı duramıyorsam eğer,

Vah bana, vah ki vah.

Durun ey yığınlar durun,

Yanlış yoldasınız yanlış.

Yok İslâm’da böyle kalkış.

Zalime  yapılmaz ki alkış.

Ey bedenim, zonkla, patla; 

Sen umurumda değilsin. 

Seni düşünüyorsam eğer,

Vah bana, vah ki vah.

Ümmet kırılıyor, zalim elinde,

Ben nasıl düşerim dünya derdime? 

Koşamam ki mal mülk peşinde,

Koşanlar varsın koşsunlar,

Yeter ki benden uzak dursunlar.

Ben dünyanın her yerindeyim,

Nerede bir acı varsa, içimde duyarım,

Acı hissetmiyorsam eğer,

Vah bana, vah ki vah.

Korkarım tek suçlu benim,

Zulmün ana kaynağı bedenim,

Bana yönelsin bütün darbeler,

Acı duyar, vah dersem  namerdim,

Ben zevk içinde olamam ki; 

Olduğumu hissedersem eğer,

Vah bana, vah ki vah.', 'Yine sirenler çalıyor, Beynimin içinde. Trenler köstebek misali, Depreşiyor kafamın içinde. Yer altından gelen sesler, Yer üstünü titretirle...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Yaşar Erdoğan']::text[], 8.5, '{"poet":"Abdullah Yaşar Erdoğan","poet_slug":"abdullah-yasar-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/vah-ki-vah-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Helal Etmem', 'helal-etmem-abdullah-yasar-erdogan-u1eep', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben ekmeğime katık, çorbama tuz,

Siz bu dünyada saltanat sürdünüz,

Bize düşecek, katığa göz koydunuz,

Sizlere hakkımı helal etmem beyler.

Hz. Ebubekir gibi sevemediniz,

Hz. Ömer adaleti veremediniz,

Hz. Osman şefkati göstermediniz,

Hz. Ali’nin  ilmini seremediniz,

Sizlere hakkımı helal etmem beyler.

Yavrularım aç-açık dolaşırken,

Yırtık ayakkabılar tamir isterken,

Mutfak tam takır, kıtlık içindeyken,

Sizlere hakkımı helal etmem beyler.

Ben yoksulluk sınırında çırpınırken,

Uykusuz gecenin sabahını beklerken,

Hastamla hastanede çileler çekerken,

Sizlere hakkımı helal etmem beyler.', 'Ben ekmeğime katık, çorbama tuz, Siz bu dünyada saltanat sürdünüz, Bize düşecek, katığa göz koydunuz, Sizlere hakkımı helal etmem beyler. Hz...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Yaşar Erdoğan']::text[], 8.5, '{"poet":"Abdullah Yaşar Erdoğan","poet_slug":"abdullah-yasar-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/helal-etmem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biz Neyiz?', 'biz-neyiz-abdullah-yasar-erdogan-3s6oe', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Köyümün yolu dereden, tepeden,

Yapılmaz oldu torpil yüzünden,

Düştük mü biz, devletin gözünden.

Bizler neyiz, neciyiz beyler? 

Gelen ister bir otuzbeş-yetmişlik,

Köylümün cebinde yok ki metelik,

Tavuksuz, kazsız yanmaz elektrik,

Bizler neyiz, neciyiz beyler? 

Oy zamanı, boylarını ancak görürüz,

Yolumuz yapılacak diye, hep seviniriz,

Nice zaman geçer, yine bizler dövünürüz,

Bizler neyiz, neciyiz beyler? 

Okulumuz var öğretmeni yok,

Camimiz var ama, imamı yok,

Yolumuz yok, suyumuz yok,

Bizler neyiz, neciyiz beyler? 

Köylüm hep horlanmıştır ezelden,

Kömür yerine medet bekler tezekten,

Ömürleri heder olmakta beklerken,

Bizler neyiz, neciyiz beyler?', 'Köyümün yolu dereden, tepeden, Yapılmaz oldu torpil yüzünden, Düştük mü biz, devletin gözünden. Bizler neyiz, neciyiz beyler?  Gelen ister b...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Yaşar Erdoğan']::text[], 8.5, '{"poet":"Abdullah Yaşar Erdoğan","poet_slug":"abdullah-yasar-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/biz-neyiz-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Su’ya Yazdığım Sözler – III', 'su-ya-yazdigim-sozler-iii-ugur-deniz-ulkegul-j9gda', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '-I-

Katlime ferman bir aşk

Belanın üstüne yazılmış adım

Gölgem düşer yüzüne zamansız…

Mavi turuncu arası boşluk

Siyaha gebe kalan yalnızlığım

Gidip gelmeler, bütün kelimeler

Donuk..Yenik…Kararsız………..

-II-

Çocuktum, uçurtmamı astılar

Tel örgüde çarmıha gerildi mavim

Çocuktum, düşlerimin üstüne bastılar

Kan kustu umarsız gecelerim……….

Hala saklarım o resmi

Sakalı uzamıştı babamın, yorgundu..

Gözlerinde umudun o yasaklı ismi

Bekle oğlum, bir gün gelecek diyordu…

Kimdi beklediği(m) 

Kimeydi zamanın öfkesi

Boynundan çıkarıp sökemediği(m) 

Soğuk bakışlı ayrılık kelepçesi…..

-III-

Öylesi geçip gidiyor zaman

Bilmek acı veriyor nasılsa işte

Sadece gözyaşların, sözlerimde kanayan

Bir de söylemediklerim..Bu amansız gidişte..

Ben hiç bilmedim sevmeyi

Nasıldır öykünmek tene…

Sarılıp yatmayı, dokunup sevişmeyi

Bilmedim hiç..Sormayı..Gözlerine…

Şimdi ucuza gidiyor sevda

Bu zamanda aşk’ı bulmak zor

Buluyorsun lakin bunca sorguda

Bir de yitirmek..Yüreğinde ateş, kor…

-IV-

Eylül geçti

Çocuktum,

Bir Pazar sabahı

Ölüm geldi babamı seçti…..

Sonra büyüdüm ben

Boyandıkça çizmeler

Derinleşti çizgiler

Acı, yüreğimden

Göz yaşı içti………………

Çıplak kadınlar üretti ressam

Üstünü arsız örtülerle kapattı

Türküm, Doğruyum, Çalışkanım,

Yasam! ! 

Ağlasam diyorum, ağlasam…

Ya gülüşümü kimler kanattı…? 

-V-

Of be gülüm

Böyleyim işte ben

Biraz öfkeden çalmışım

Biraz sevdaya bulanmış mayam..

Sevmek,

Ölümcül gerekçe taşır yüreğimde

Olmasa sen halim..Aklım karışır,

Düşlerinde bile yaşayamam……..

Var git yoluna şimdi

En soysuz arzulara meze olsan da

Seni sevmenin bir adı yok bende

Bu ismi sürgünde..

Ben bile taşıyamam! ! ! .....................', '-I- Katlime ferman bir aşk Belanın üstüne yazılmış adım Gölgem düşer yüzüne zamansız… Mavi turuncu arası boşluk Siyaha gebe kalan yalnızlığı...', ARRAY['Türk Edebiyatı','Şiir','Uğur Deniz Ülkegül']::text[], 8.5, '{"poet":"Uğur Deniz Ülkegül","poet_slug":"ugur-deniz-ulkegul","theme":"Türk Şiiri","is_hero":false,"total_lines":64,"source_url":"https://www.antoloji.com/su-ya-yazdigim-sozler-iii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bize Sorsana', 'bize-sorsana-abdullah-yasar-erdogan-a9bpt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Allah belanızı versin.

Aç ayı oynar mı dersin? 

Aç halinden, tok ne bilsin? 

Birde bize sorsana.

Kul hakkı nedir bilir misin? 

Soğan ekmeği sen yer misin? 

Yamalı pantolon giyer misin? 

Birde bize sorsana.

Et bayramdan bayrama gelir,

Bal baklava nerede yenilir? 

Kışın yazlık mı giyilir? 

Birde bize sorsana.

Bizde insanız, insan.

Size hep düğün bayram,

Nasıl gitmekte bu kervan? 

Birde bize sorsana.

Bizim çocuklar okumasın mı? 

Bizim ocaklarımız yanmasın mı? 

Nefes alma hakkımız olmasın mı? 

Birde bize sorsana.

 Temmuz 1980', 'Allah belanızı versin. Aç ayı oynar mı dersin?  Aç halinden, tok ne bilsin?  Birde bize sorsana. Kul hakkı nedir bilir misin?  Soğan ekmeği ...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Yaşar Erdoğan']::text[], 8.5, '{"poet":"Abdullah Yaşar Erdoğan","poet_slug":"abdullah-yasar-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bize-sorsana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nerede O Bahçivan?', 'nerede-o-bahcivan-abdullah-yasar-erdogan-1nh7h', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hasta bir çiçekti o, hasta.

Sonbahar gelmeden solmuştu.

Gerçi yaprakları dinç gibi; 

Acaba bir yerimi kırıldı? 

Sızıları, acıları belli olmuyor.

Irkdaşları, yandaşları yoktu.

Garip bir duruşu vardı,

Anadolu’nun bağrında yetişmiş,

Eskiden tekti onun soyu.

Davaları vardı, inançları vardı; 

Dünya, öpmek için belini bükerdi.

Saygıda kimse kusur etmez,

Onu incitmekten çekinirdi.

Doktor çare olamadı derdine,

Su, güneş, hava ve toprak verdiler,

Aradığını bulamamış gibiydi,

Aradığı neden sonra anlaşıldı.

Bahçıvanını arıyordu.

O biliyordu onun her derdini,

O bahçıvan yok olmuştu birden,

Adı vardı, kendi silinmişti defterden,

Bir garip düzen çarkına kurban gitmişti; 

İşte bu nedenle çiçekler dahi yastaydı.

O bahçıvan bir çıksa ortaya,

Ne hastalık kalır, ne de parya.', 'Hasta bir çiçekti o, hasta. Sonbahar gelmeden solmuştu. Gerçi yaprakları dinç gibi;  Acaba bir yerimi kırıldı?  Sızıları, acıları belli olmu...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Yaşar Erdoğan']::text[], 8.5, '{"poet":"Abdullah Yaşar Erdoğan","poet_slug":"abdullah-yasar-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/nerede-o-bahcivan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki Sevgili', 'i-ki-sevgili-abdullah-yasar-erdogan-3nrb9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ne mistik bir ortam; 

Şu yağmurlu  yaşam.

Düşen her damlada,

İnsanlığa bir hayat var.

Bütün mâhlûkat sevinmekte,

Bense onun kokusuna sevdalı.

O koku kendisinden değil,

Toprağa kavuşmanın kokusu.

Yani iki sevgilinin kokusu.

Bense ikisini sevmekteyim,

O koku beni benden alır.

Onda var başkasının kokusu,

O her şeyi kuşatmıştır. 

İşte ben o kokudan dolayı aşığım,

O sevgilinin kulu kölesi olayım,

Ben azmayınca,

Ondan hasıl olmaz çile,

O’ndan dert gelmez asla.

Yağmur kavuştu, sevgilisine,

Benim sevgilim de aynı yer.

Ondan gelen hep ona gider.', 'Ne mistik bir ortam;  Şu yağmurlu  yaşam. Düşen her damlada, İnsanlığa bir hayat var. Bütün mâhlûkat sevinmekte, Bense onun kokusuna sevdalı...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Yaşar Erdoğan']::text[], 8.5, '{"poet":"Abdullah Yaşar Erdoğan","poet_slug":"abdullah-yasar-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/iki-sevgili-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çilem', 'cilem-abdullah-yasar-erdogan-zejz1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yıllardır yanarım,

Ben, bende değilim.

Çilem dağı aşmış,

İçinde boğulan benim.

Çektikçe çekerim,

Bu alın yazımmış.

Yazgıdır bu katlanırım.

Yazgıya karşı konulmaz.

Gülmek uzak bana.

Hayat tuzak bana.

Çilem azık bana.

Mükafatı Rabbim bilir.

Sermayem sabırdır benim.', 'Yıllardır yanarım, Ben, bende değilim. Çilem dağı aşmış, İçinde boğulan benim. Çektikçe çekerim, Bu alın yazımmış. Yazgıdır bu katlanırım. Y...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Yaşar Erdoğan']::text[], 8.5, '{"poet":"Abdullah Yaşar Erdoğan","poet_slug":"abdullah-yasar-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/cilem-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüya', 'ruya-canan-motorcu-27nfm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Saatin tiktakları 

Beynimde davul çalarken

Aklımda hep sen vardın

Sen ve canım deyişin

Tatlı bir serinlik

Pencereden odama dolarken

Taaa uzaklardan

Oralarda bir yerlerden

Kokunu getiriyordu bana

Gözlerimi kapadığımda

Aşılmaz gibi duran dağlar 

Derin vadiler uçurumlar

Kolkola verip düzleşiyor

Birbirimize kavuşmamız için

Mis kokulu rengarek çiçeklerle

Yemyeşil yapraklı ağaçlarla bezenmiş

Cennet yoluna dönüşüyorlardı

Bu cümbüşün içinde yürümüyor koşmuyor

Adeta kayarak gidiyordum

Orada karşıda olduğunu

Ve hep beni beklediğini biliyor

İçim titreyerek huşuyla ürpererek

Şavkınla aydınlattığın yolda

Gitgide sana yaklaşıyordum

Gelişimi büyük bir özlemle

Sabırsızlıkla izlediğin

Yumuşacık olmuş gözlerine

Bakışlarına yansıyordu

Şüphesiz kavuşmamız

Devlerin buluşması gibi

Muhteşem olacaktı

O anın heyecanını hissederek

Önümde açtığın gümüşten yolda

İyice hızlanmıştım ki

Bütün güzellikler dağılıverdi

Saatin zili sabah oldu diyordu

Rüyam ise her zamanki gibi

Kavuşamadan bitiyordu

05:18 30.09.2005', 'Saatin tiktakları  Beynimde davul çalarken Aklımda hep sen vardın Sen ve canım deyişin Tatlı bir serinlik Pencereden odama dolarken Taaa uza...', ARRAY['Türk Edebiyatı','Şiir','Canan Motorcu']::text[], 8.5, '{"poet":"Canan Motorcu","poet_slug":"canan-motorcu","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/ruya-201-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Baba Yüreği', 'baba-yuregi-abdullah-yasar-erdogan-al9xv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yıkma beni, ben kalkamam.

Eziklik içinde hayatım oldu.

Ben, beni asla anlatamam.

Kalemim hep sırdaşım oldu.

Karşı gelme, bildiğin az.

El kapısı çekemez naz.

Yüreğine derin kuyu kaz.

Ne bulursan içine at kızım.

Onurun incinsin istemem,

Gururun kırılsın dilemem,

Dünya toz pembe bilesin,

Evlatlarım üzülsün istemem.

Siz beni içten yıkmadıkça,

Siz beni utandırmadıkça,

Beni kimse yıkamaz bilesiniz,

Kul kaldırmaz, Hakk kaldırmadıkça.

Yine öğüttür, tutun belki yarar.

O öğütle hayat bağı sıkı sarar.

El gülmek ister halinize de,

Bir baba yüreği hep yanar.

Dünya malı için uğraşmayın,

Eller işine asla karışmayın,

Kendi dünyanızı kurun da,

Zalimliklere hiç bulaşmayın.

Okumak olsun sizin dostunuz,

Hep asaletle dursun onurunuz,

Kim ne derse desin size,

Yeter ki, Hakk yolunda olunuz.', 'Yıkma beni, ben kalkamam. Eziklik içinde hayatım oldu. Ben, beni asla anlatamam. Kalemim hep sırdaşım oldu. Karşı gelme, bildiğin az. El kap...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Yaşar Erdoğan']::text[], 8.5, '{"poet":"Abdullah Yaşar Erdoğan","poet_slug":"abdullah-yasar-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/baba-yuregi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstersem', 'i-stersem-canan-motorcu-bkznq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dağ bayır koşarken korkusuzca

Onmaz bir yara açtın ruhumda

Aranıp dururken pervasızca

Binlerce dert yükledin sırtıma

Şimdi çağlayıp seller gibi coşsamda

Başımı bir o yana bir bu yana vuruyorum

Ümitsizlik girdabında boğulurcasına

Ayağıma vurduğun prangalarla uğraşıyorum

Sanma ki mutsuzum ve korkuyorum

Gece gündüz hep seni düşünüyorum...

Ben kendimi gayet iyi tanıyorum

İstersem seni bir solukta unuturum

06:39 01.10.2005', 'Dağ bayır koşarken korkusuzca Onmaz bir yara açtın ruhumda Aranıp dururken pervasızca Binlerce dert yükledin sırtıma Şimdi çağlayıp seller g...', ARRAY['Türk Edebiyatı','Şiir','Canan Motorcu']::text[], 8.5, '{"poet":"Canan Motorcu","poet_slug":"canan-motorcu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/istersem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yolcuyuz', 'yolcuyuz-abdullah-yasar-erdogan-d9hb7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dünya bu hepimiz bir yolcuyuz,

Yolcuya kalmaz hiçbir han.

Bugün var isek, yarın yokuz.

Kimseyi kırma, hayırlarla an.

Beni üzmeyin mutluluk sizin olsun.

İstedim ki küçük bir nasihat olsun,

İhtiyacım yok demeyin sakın,

Varsın heybenizin dibinde  dursun.

Babanın görevidir nasihat etmek,

Sizin mutluluğunuzu hep istemek,

Sanmayın kafanızdakiler hep doğru,

Lâzımdır işte,  bir büyük dinlemek.

Bak geçmişe niceleri yok oldu,

O güzel gözlerine toprak doldu,

Öyle narin simalar vardı ki; 

Kimisi ilkbaharında kayboldu.

Değer mi, insan üzmeye dünyada? 

Değer mi, boş dolaşmak hülyada? 

Gelecek ile geçmişe köprü olda,

Yolculuğun mutlu geçsin dünyada.', 'Dünya bu hepimiz bir yolcuyuz, Yolcuya kalmaz hiçbir han. Bugün var isek, yarın yokuz. Kimseyi kırma, hayırlarla an. Beni üzmeyin mutluluk s...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Yaşar Erdoğan']::text[], 8.5, '{"poet":"Abdullah Yaşar Erdoğan","poet_slug":"abdullah-yasar-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yolcuyuz-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Su', 'su-abdullah-yasar-erdogan-or5ay', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Su  mecrasında akmaktadır,

Onda ne büyük ulviyet vardır,

Akar, hakkın çizdiği  yolda,

Her zerresi bin bir hayattır.

Yer üstünde yer altında da akar,

Her canlının hayatına can katar,

Mayidir, akmaktır onun amacı,

Kâinata bir bütünlük katar.

Kıvrım kıvrım Sakarya olur,

Toplanıp derya deniz olur,

Ulviyeti yüksektir suyun,

İnsan için temiz ve pis olur.

Dünyanın her yerinde aynıdır,

Her damlasında hayat vardır,

Küffar, zalim, masum demez,

Her canlıya hayat kaynağıdır.

Gökten iner, bazen yerden çıkar.

Toprakla buluşunca hep kokar,

Su, düşündükçe düşündürür de,

O her daim mecrasında akar.', 'Su  mecrasında akmaktadır, Onda ne büyük ulviyet vardır, Akar, hakkın çizdiği  yolda, Her zerresi bin bir hayattır. Yer üstünde yer altında ...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Yaşar Erdoğan']::text[], 8.5, '{"poet":"Abdullah Yaşar Erdoğan","poet_slug":"abdullah-yasar-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/su-54-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nerede O Millet?', 'nerede-o-millet-abdullah-yasar-erdogan-tygzh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Tarih utanıyor bizden, buna inanın.

Kalmadı el içine çıkacak takatım.

Az da olsa sevdası yok mu o atanın? 

Nerede o millet, nerede o ümmet? 

Ey zalim düzen size sorarım; 

Akifler mi yetiştirdiniz ki? 

Hak olsun en son kararın.

Fatihler mi yetiştirdiniz ki? 

Aydınlıklar içinde olsun yarının.

Diz boyu yükselmektedir rezalet,

Kurtulur mu bu kafayla memleket? 

Neyle rakip, neyle edersin rekabet? 

Nerede o millet, nerede o ümmet? 

İnsanlığı uçuruma atan sizdiniz.

Her baş kaldıranı vurup ezdiniz.

O koskoca mirasımı siz yediniz.

Nerede o millet, nerede o ümmet?', 'Tarih utanıyor bizden, buna inanın. Kalmadı el içine çıkacak takatım. Az da olsa sevdası yok mu o atanın?  Nerede o millet, nerede o ümmet? ...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Yaşar Erdoğan']::text[], 8.5, '{"poet":"Abdullah Yaşar Erdoğan","poet_slug":"abdullah-yasar-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/nerede-o-millet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üzüldüm', 'uzuldum-abdullah-yasar-erdogan-g6aor', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir yolcu gördüm

Acele acele gidiyor.

Bir aşık gördüm,

Elinde çiçek bekliyor.

Bir garip gördüm,

Eli alnında düşünüyor.

Birde kendimi düşündüm, 

Kalbim hızla çarpıyor.

Bir ölümü düşündüm, 

Peşimde kol geziyor.

Hayatta var olmak zormuş,

En çok ona üzüldüm.', 'Bir yolcu gördüm Acele acele gidiyor. Bir aşık gördüm, Elinde çiçek bekliyor. Bir garip gördüm, Eli alnında düşünüyor. Birde kendimi düşündü...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Yaşar Erdoğan']::text[], 8.5, '{"poet":"Abdullah Yaşar Erdoğan","poet_slug":"abdullah-yasar-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/uzuldum-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kelepir', 'kelepir-abdullah-yasar-erdogan-4eub4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ucuzluk var beyler ucuzluk…

Kelepir bunlar kelepir.

Ne mi satılan ortada? 

İnsanlık, insanlık

İnsanlık.

O kadar ucuz ki! 

Kelepirden de kelepir.

Alıcısı yok mu bunun,

Versen bir, elde bir, kalan bir.

Kalmamış kimsede ulviyet, 

Yokunu etmez ki bir.

Hele bazıları var ki; 

Kelepirden de kelepir. 

Bilirim beş kuruş etmez, 

Nursuz yüzde dolu kir.

Alan yok mu diyoruz da,

Ucuz ya adı kelepir.

İşte bu yüzden elde kaldı.

Ne kadar olsa da kelepir.

Değer bulmadı, elde kaldı.

İşte böyle adi bir kelepir.', 'Ucuzluk var beyler ucuzluk… Kelepir bunlar kelepir. Ne mi satılan ortada?  İnsanlık, insanlık İnsanlık. O kadar ucuz ki!  Kelepirden de kele...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Yaşar Erdoğan']::text[], 8.5, '{"poet":"Abdullah Yaşar Erdoğan","poet_slug":"abdullah-yasar-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/kelepir-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Misto efendi', 'misto-efendi-i-brahim-kilinc-mtzrw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sabahları vakitlice kalkardı

Köyün çeşmesinde el yüz yıkardı

Genç kızların yüreğini yakardı

Yağız delikanlı Misto efendi

Görürdü kızların göz ettiğini

Sonra kıkırdayıp söz ettiğini

Yüzyüze gelince naz ettiğini

Yağız delikanlı Misto efendi

Birgün Ayşe kıza verdi gönülü

Yolladı en güzel kırmızı gülü

Kendisine sırdaş tuttu bülbülü

Yağız delikanlı Misto efendi

Anlamadı onun naz ettiğini 

Aslında kendinden haz ettiğini

Gönülde ne derin iz ettiğini

Yağız delikanlı Misto efendi

Kara sevdasıyla çıktı gurbete

Katlanarak hergün binbir mihnete

Hasret bir çorbaya, yüz gram ete

Yağız delikanlı Misto efendi

Çilesine hergün çile koyarak

Günü ay, ayları sene sayarak

Yaşadı gurbete sonra uyarak

Yağız delikanlı Misto efendi', 'Sabahları vakitlice kalkardı Köyün çeşmesinde el yüz yıkardı Genç kızların yüreğini yakardı Yağız delikanlı Misto efendi Görürdü kızların gö...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Kılınç']::text[], 8.5, '{"poet":"İbrahim Kılınç","poet_slug":"i-brahim-kilinc","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/misto-efendi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Etmez', 'etmez-abdullah-yasar-erdogan-62k5z', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne haysiyetsizler bilirim, 

Bozuk üç kuruş etmez.

Ne hokkabazlar bilirim, 

Çanak içinde yal etmez.

Öyle  çok insan bozması var ki; 

Yaratanına kulluk etmez.

Öyle ulema bozması  var ki; 

Yazması beş para etmez.

Soysuzluğu servet edinmişler,

Varlığı, varlık etmez.

Yetim hakkı demeyip yemişler,

Kimse ona hak helal etmez, etmez.', 'Ne haysiyetsizler bilirim,  Bozuk üç kuruş etmez. Ne hokkabazlar bilirim,  Çanak içinde yal etmez. Öyle  çok insan bozması var ki;  Yaratanı...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Yaşar Erdoğan']::text[], 8.5, '{"poet":"Abdullah Yaşar Erdoğan","poet_slug":"abdullah-yasar-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/etmez-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgilim', 'sevgilim-abdullah-yasar-erdogan-5uh5z', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Fırtınamıydı neydi o esen? 

Gelip de şu halimi  görsen,

Çile çekmek nedir anlarsın,

O zaman bana acırsın sevgilim.

Ağlamak boş yere burada,

Nafileymiş yaşamak dünyada,

Tatlı anılardan uzaklarda,

Kalmak nedir anlarsın sevgilim.

Hep eriyip gittiğimi,

Sensiz neler çektiğimi,

Tekrar döner misin,

 Görsen halimi sevgilim.', 'Fırtınamıydı neydi o esen?  Gelip de şu halimi  görsen, Çile çekmek nedir anlarsın, O zaman bana acırsın sevgilim. Ağlamak boş yere burada, ...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Yaşar Erdoğan']::text[], 8.5, '{"poet":"Abdullah Yaşar Erdoğan","poet_slug":"abdullah-yasar-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sevgilim-86-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık', 'yalnizlik-abdullah-yasar-erdogan-goq7z', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yalnızlık, yalnızlık.

Ah şu yalnızlık.

Ne korkunç bir kelime.

Kimse inanmaz sevgine.

Düşersin hep el diline.

Yalnızlık, yalnızlık.

Ah şu yalnızlık.

Nereye gitsen dost yok.

Kimi gün aç, kimi tok.

Istırap ve kederse çok.

Yalnızlık, yalnızlık.

Ah şu yalnızlık.

Sırdaş desen bulunmaz.

Duvarlarla da konuşulmaz.

Sevgisiz, aşksız yaşanmaz.

Yalnızlık, yalnızlık.

Ah şu yalnızlık.', 'Yalnızlık, yalnızlık. Ah şu yalnızlık. Ne korkunç bir kelime. Kimse inanmaz sevgine. Düşersin hep el diline. Yalnızlık, yalnızlık. Ah şu yal...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Yaşar Erdoğan']::text[], 8.5, '{"poet":"Abdullah Yaşar Erdoğan","poet_slug":"abdullah-yasar-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yalnizlik-286-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Vapur', 'o-vapur-abdullah-yasar-erdogan-1h9ux', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'O, Vapur düdüğü,

Hala kulaklarımdadır.

Seni benden kopardığı gün,

Boynu bükük rıhtımdaydım.

Öylece kalakalmıştım.

Lanet edesim geldi, vapura.

Her vapur düdüğünde, 

Vazgeçerim lanet okumaktan.

Sonra ufuklara bakarım.

Bir vapur görsem,

Seni getiriyor diye,

Rıhtımda yerimi alırım.

O vapur gelir gider de,

Sen bir türlü gelmezsin.', 'O, Vapur düdüğü, Hala kulaklarımdadır. Seni benden kopardığı gün, Boynu bükük rıhtımdaydım. Öylece kalakalmıştım. Lanet edesim geldi, vapura...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Yaşar Erdoğan']::text[], 8.5, '{"poet":"Abdullah Yaşar Erdoğan","poet_slug":"abdullah-yasar-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/o-vapur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Albüm', 'album-abdullah-yasar-erdogan-6qmuq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir albümüm var, 

Çocukluğumu,

Genlik yılarımı saklar.

Bir anı defterim var,

Acılarımı, hayatımı

Geçmişimi saklar.

Bir hafızam var,

Seni düşününce,

Şimşekler çakar.', 'Bir albümüm var,  Çocukluğumu, Genlik yılarımı saklar. Bir anı defterim var, Acılarımı, hayatımı Geçmişimi saklar. Bir hafızam var, Seni düş...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Yaşar Erdoğan']::text[], 8.5, '{"poet":"Abdullah Yaşar Erdoğan","poet_slug":"abdullah-yasar-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/album-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Utangaç Yıldız', 'utangac-yildiz-abdullah-yasar-erdogan-nvska', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dün akşam yıldızlarla dertleştim.

Yanıp sönerek cevap veriyorlardı.

Biri utandı sanki seni anlatmaktan,

Tıpkı senin yaptığın gibi kaçıverdi.

Öbür yıldızlar anlat dediler,

Kayan yıldıza aldırma dediler,

O hep böyle oyun bozanlık eder,

Her şeyi yarı bırakıp gider.

Dostlar da o kayan yıldız gibiydi,

Zorlukta  hep çekip gitmişlerdi,

Hiç olmazsa yıldızlar yukarıda,

Dinliyorlar, vefasız değillerdi.', 'Dün akşam yıldızlarla dertleştim. Yanıp sönerek cevap veriyorlardı. Biri utandı sanki seni anlatmaktan, Tıpkı senin yaptığın gibi kaçıverdi....', ARRAY['Türk Edebiyatı','Şiir','Abdullah Yaşar Erdoğan']::text[], 8.5, '{"poet":"Abdullah Yaşar Erdoğan","poet_slug":"abdullah-yasar-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/utangac-yildiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşar', 'yasar-abdullah-yasar-erdogan-at1f8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yıllardan 1960

Herkes yine,

Aynısı olacak sanmışlar.

Bu da az yaşar demişler

Onun için adımı,

Yaşar koymuşlar.

Benden öncekiler ölmüş,

Adım gereği mi? 

Yoksa şans mı? 

Rabbim’in lütfu olsa gerek.

Ben yaşamışım.

İşte adım o nedenle Yaşar.

Yaşar deyince insan mı yaşar?', 'Yıllardan 1960 Herkes yine, Aynısı olacak sanmışlar. Bu da az yaşar demişler Onun için adımı, Yaşar koymuşlar. Benden öncekiler ölmüş, Adım ...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Yaşar Erdoğan']::text[], 8.5, '{"poet":"Abdullah Yaşar Erdoğan","poet_slug":"abdullah-yasar-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yasar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Adam', 'bir-adam-abdullah-yasar-erdogan-1qg12', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gözleri görmeyen bir adam,

Yaklaştı yanıma.

Sordu; 

Nerede benim dünyam? 

Sanki girdi kanıma.

Nereden geldi? 

Neydi ki o? 

Ermiş mi? 

Derviş miydi yoksa o? 

Aniden gözden kayboldu.

Hafızamda sadece

Bir adam kaldı.

Mayıs 1986', 'Gözleri görmeyen bir adam, Yaklaştı yanıma. Sordu;  Nerede benim dünyam?  Sanki girdi kanıma. Nereden geldi?  Neydi ki o?  Ermiş mi?  Derviş...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Yaşar Erdoğan']::text[], 8.5, '{"poet":"Abdullah Yaşar Erdoğan","poet_slug":"abdullah-yasar-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bir-adam-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senden Önce', 'senden-once-burhanettin-akdag-x6xs7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Senden önce bebeğim

Okyanuslar ötesindeydi

Hayallerim...

Sen,

Gözlerime gölgeni

İzinsiz düşürene kadar

Öksüzdü, bilgisizdi aşktan

Yüreğim...

Artık, benim için

Bu, son üzülme olacak

Uğramayacak kapıma

Yılgınlık...

Çılgınca oynaşacak

Rüyalarım...

Kul olacak kapında

Sevdalarım...

Bedenini giydirecek

Sevmelerim...

Artık, senin için

Bu, son ağlama olacak

İpotek koydum yaşlarına

Yalnız kalbime akacak

Yaşların...

Yasakladım gözlerine dünyayı

Yalnız bana bakacak

Gözlerin...

Hapsettim bedenime gülmelerini

Yalnız beni öpecek

Gülmelerin...

Seni öylesine seveceğim ki

Bebeğim...

Ardımızdan gelenler

Hikayemizden öğrenecekler

Yanmayı...

Yeni baştan, en başından

''AŞK'' denilen ''MAVİ'' ihtişamın

Nasıl yazıldığını...

(09.05.2005)', 'Senden önce bebeğim Okyanuslar ötesindeydi Hayallerim... Sen, Gözlerime gölgeni İzinsiz düşürene kadar Öksüzdü, bilgisizdi aşktan Yüreğim......', ARRAY['Türk Edebiyatı','Şiir','Burhanettin Akdağ']::text[], 8.5, '{"poet":"Burhanettin Akdağ","poet_slug":"burhanettin-akdag","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/senden-once-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acı Halimize', 'aci-halimize-abdullah-yasar-erdogan-952yj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gözümün nuru Ahmed-i Mahmut, 

Devrân-ı âlem bozulmuş gidiyor.

Kâinat serveri sevgili Muhammet, 

Ruhundan bekler kul istimdat. 

Bize himmet eyle, bize hep ol beyan.

Ümmetinden yükselir feryat figan.

Başsız kalmışız şu  dar-ı âlemde,

Çırpınmakta çaresiz Müslüman.

Toprak ağlar, taş ağlar halimize, 

Boşluktayız, düşmanız biz bize,

Bin nasihatle yatıp kalktık da,

Bir türlü gelemdik kendimize.

Biliriz suçluyuz biz bu yolda, 

Fetbazlıkta üste yok her dalda.

Allah’ım acı, himmet eyle bize, 

Şuursuz gençlik kaldı ortada..', 'Gözümün nuru Ahmed-i Mahmut,  Devrân-ı âlem bozulmuş gidiyor. Kâinat serveri sevgili Muhammet,  Ruhundan bekler kul istimdat.  Bize himmet e...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Yaşar Erdoğan']::text[], 8.5, '{"poet":"Abdullah Yaşar Erdoğan","poet_slug":"abdullah-yasar-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/aci-halimize-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Allah''ım', 'allah-im-abdullah-yasar-erdogan-oz25s', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yakarışlar sana Allah’ım,

Seni anmayan düşmanım.

Senin için fedadır canım,

 Bize, iman ver Allah’ım.

Hoyrattır yapı itibariyle insan,

Bazıları inançsız, bir hayvan,

Yarattığını, düşünüp anlayan,

Akıl fikir  ver Allah’ım.

Güzel bir dünya verdin insanlığa,

Kimi gider aydınlığa, kimi karanlığa,

Kimi de boş vermiş  bu ustalığa,

Bize, iman ver Allah’ım.', 'Yakarışlar sana Allah’ım, Seni anmayan düşmanım. Senin için fedadır canım,  Bize, iman ver Allah’ım. Hoyrattır yapı itibariyle insan, Bazıla...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Yaşar Erdoğan']::text[], 8.5, '{"poet":"Abdullah Yaşar Erdoğan","poet_slug":"abdullah-yasar-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/allah-im-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mahcup Etme', 'mahcup-etme-abdullah-yasar-erdogan-0pbdl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen sana sığınanı, 

Cevapsız koymazsın Allah’ım.

Sen sana güveneni, 

Mahcup etmezsin Allah’ım.

Ellerim açık yalvarıyorum,

Uğruna bu canı koyuyorum,

Yalnız sana inanıyorum,

Sen mahcup etme Allah’ım.

Kitab’ım, canım Kuran’ım.

Uğrunda aksın bu kanım,

Kalmasa dahi dermanım,

Mahcup etme Allah’ım..', 'Sen sana sığınanı,  Cevapsız koymazsın Allah’ım. Sen sana güveneni,  Mahcup etmezsin Allah’ım. Ellerim açık yalvarıyorum, Uğruna bu canı koy...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Yaşar Erdoğan']::text[], 8.5, '{"poet":"Abdullah Yaşar Erdoğan","poet_slug":"abdullah-yasar-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/mahcup-etme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İşte O Zaman', 'i-ste-o-zaman-abdullah-yasar-erdogan-kmd35', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İnsanlar var, insana benzer.

İnsanlar var, destursuz gezer.

İnsanlar var, imansız gider.

İnsanlar var, insanlık eder.

Saymakla biter mi, hayvanlar? 

Dağda ayı, ovada kurtlar var.

Leş bekleşiyor akbabalar.

İnsansa onlardan da barbar.

İnsanlar var, insanı boğar,

İnsanlar var, bine bin katar,

İnsanlar var, hep kuyu kazar,

İnsanlar var, alnında nur var.

Saymakla biter mi iyilikler? 

Gözetilirse bütün garipler,

İşte o zaman açar solan güller.

İnsanın, insana gülmesi yeter.', 'İnsanlar var, insana benzer. İnsanlar var, destursuz gezer. İnsanlar var, imansız gider. İnsanlar var, insanlık eder. Saymakla biter mi, hay...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Yaşar Erdoğan']::text[], 8.5, '{"poet":"Abdullah Yaşar Erdoğan","poet_slug":"abdullah-yasar-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/iste-o-zaman-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sohbet-1', 'sohbet-1-abdullah-yasar-erdogan-681vg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sordum bir gence:

Mânâ ve madde arasında ne fark var diye? 

Mânâ: Hâyal, bomboş dedi.

Madde: Zevk eğlence, hoş dedi.

Hep maddeye koşmuş bu dünyada,

Gezinmiş hep zevk dünyasında,

Boşluk içinde olduğunu duydum,

Kendini alkole vermişti.

Derken hastalandı, hasta yatıyordu.

Merhabam vardı, ziyaretine koştum.

Gözleri boşlukta, görmüyordu kimseyi.

Her yanından takviye yapılmıştı.

Vücut iflas etmişti belli halinden.

Sesimi tanır dedim seslendim.

Tanıdı, toparlanır gibi yaptı.

Rahat olmasını istedim.

Ağladı ve bana öğret dedi.

Dünya varsın sizin olsun, 

Mânâ âlemine ihtiyacım var dedi.

Boş gözlerle bakıp inliyordu.

Gözleri yalan dünyaya kapanmıştı.

Gırtlak delinmiş, hırıldıyordu.

Vücut erimiş, iskeleti çıkmıştı.

Üzüldüm haline.

İmtihan dedim, imtihan.

Hepimizin olduğu imtihan.

Bazılarının ki, böyle sert olurmuş,

Sabret mükafatın büyüktür dedim.

İnanamıyordu.

Çok asi bir hayat yaşamıştı.

Madde dünyasının hakimi sanmıştı.

Hırıltılı bir ses tonuyla; 

Bana bir duâ okur musunuz dedi.

Okudum. Ben okudum o ağladı.

Mânâ, mânâ, mânâ diye hayıflandı.

Elini tuttum,  buz gibiydi.

Ben bu kapıya neden geç geldim, dedi.

Kendi kendine hayıflandı, söylendi.

İçim, dışım, bomboş biliyorum.

Suçluyum, günahım çok.

Mânânın böyle güzel olduğunu bilmedim.

Sadece ben mi suçluyum dedi.

Baba öğretmez, anne öğretmezse,

Sadece ben mi suçluyum? 

Elini tekrar tuttum.

Vakit var. Kâr her zaman olur.

Yeter ki sen, niyetlen dedim...

Yalvardı, yakardı, ağladı.

Bizim gibileri affet Allah’ım.

Bizim gibileri ıslah et Allah’ım.

Kıymetli zamanı boşa harcadım,

Beni, dergahına kabul buyur Allah’ım.

Artık, anlamıştı. Hep yalvarıyordu.

Vedalaşıp ayrıldım, oradan.

Üç gün sonra bir sâla işitim.

Merhumun adını söylediler.  Ölmüştü.

Arkasından dostları dizildi. 

Madde veren olmadı hiç ona,

Mânâlı yaşamak gereklidir  denildi.', 'Sordum bir gence: Mânâ ve madde arasında ne fark var diye?  Mânâ: Hâyal, bomboş dedi. Madde: Zevk eğlence, hoş dedi. Hep maddeye koşmuş bu d...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Yaşar Erdoğan']::text[], 8.5, '{"poet":"Abdullah Yaşar Erdoğan","poet_slug":"abdullah-yasar-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":59,"source_url":"https://www.antoloji.com/sohbet-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uyan Uyan', 'uyan-uyan-abdullah-yasar-erdogan-mv32q', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aslın toprak, neslin nutfe.

Gireceksin mutlaka kefene,

Aldanma dünya güzel diyene,

Uyan, uyan gaflet uykusundan.

Döneceksin er geç aslına,

Meyletme dünya malına, 

Güvenme kızına, oğluna,

Uyan,uyan gaflet uykusundan. 

Boş bu dünya bilmez misin? 

Geri dönen yok görmez misin? 

Sana söyleneni dinlemez misin? 

Uyan, uyan gaflet uykusundan.

Frenk diyarlarına kaçsan bile.

Fezaya çıkıp, bize baksan bile,

Sonsuz servete sahip olsan bile, 

Uyan, uyan gaflet uykusundan.

Dostların Mü’min’mi Müşrik mi bak? 

Sözümü dinle, doğru yol Cenab-ı Hak.

Kalbine iman anahtarını sende tak.

Uyan, uyan gaflet uykusundan.

Geçici şeylerdir dünyadaki her şey.

Mahşerde kendinden sorulu birey.

Götüren var mı dünyadan bir şey.

Uyan, uyan gaflet uykusundan.

Her dakika desen Allah, Allah.

Sırtın yere gelmez billah.

Alnın secdeye değmeli her sabah.

Uyan, uyan gaflet uykusundan.

Her zaman seni caydıracak  şeytan.

İnsandır bu, kimi dost kimi yandan.

Uzak durma sakın, seni yaratandan.

Uyan, uyan gaflet uykusundan.', 'Aslın toprak, neslin nutfe. Gireceksin mutlaka kefene, Aldanma dünya güzel diyene, Uyan, uyan gaflet uykusundan. Döneceksin er geç aslına, M...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Yaşar Erdoğan']::text[], 8.5, '{"poet":"Abdullah Yaşar Erdoğan","poet_slug":"abdullah-yasar-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/uyan-uyan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ebedi Sonda', 'ebedi-sonda-abdullah-yasar-erdogan-u58bk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Soğuk bir mermer taşına.

Elbet  sende yatacaksın.

İşte o zaman sorulacak.

Dünya malın faydası ne? 

Sen başın öne eğerken,

Dünya malına lanet edeceksin.

İşte o zaman geriye dönüş yok.

Kabir denen o çukur yerde,

Çaresizlik içinde olacaksın.

Amel defterin olduysa kapkara,

Hep olacaksın maskara.

Orada yer yoktur, 

Dünyadaki maskaralıklara.', 'Soğuk bir mermer taşına. Elbet  sende yatacaksın. İşte o zaman sorulacak. Dünya malın faydası ne?  Sen başın öne eğerken, Dünya malına lanet...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Yaşar Erdoğan']::text[], 8.5, '{"poet":"Abdullah Yaşar Erdoğan","poet_slug":"abdullah-yasar-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ebedi-sonda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Utanıyorum', 'utaniyorum-abdullah-yasar-erdogan-qh1tr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İnsan, insanlığını bilmez durumda.

Gönlü gözü olmuş dünya malında.

Aramamış mutluluğu maneviyatta.

Onlarla olmaktan utanıyorum.

Ezip geçme pahasına çıkarcı olmuş.

Kendince kurtulmak parayla olurmuş.

Yaşarken hep boş şeyler için koşmuş.

Onlarla nefes almaktan utanıyorum.

Din ne verirmiş eğlenmek varken.

Yaşamalıymış eli ayağı tutarken.

Hiç haberdar değil rezzak-ı âlemden.

Onlarla konuşmaktan utanıyorum.

Manasız yaşıyorlar, madde hırsı sarmış.

Şükretmeden har vurup harman savurmuş.

Gönülleri şeytanlar mesken tutmuş.

Onlarla koşmaktan utanıyorum.

Ashabı kiramı, atalarını inkar eder.

Zamanında öyle gerekiyormuş der.

Münafıkları kendine dost seçer.

Onlarla olmaktan utanıyorum.

İtiş kakış toplum düzeni çarpılmış.

Uyuşuk insanın beyni şeytana açılmış.

İyiyle kötü bir kefede tartılmış.

Onlarla duymaktan utanıyorum.

Mahşer gelecek, hesap sorulacak.

Dünyada ne yaptınız denilecek.

O zaman insanlık ne diyecek? 

Sizlerle yaşamaktan utanıyorum.', 'İnsan, insanlığını bilmez durumda. Gönlü gözü olmuş dünya malında. Aramamış mutluluğu maneviyatta. Onlarla olmaktan utanıyorum. Ezip geçme p...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Yaşar Erdoğan']::text[], 8.5, '{"poet":"Abdullah Yaşar Erdoğan","poet_slug":"abdullah-yasar-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/utaniyorum-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Utan Utan', 'utan-utan-abdullah-yasar-erdogan-zs3j7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Müslüman’ım deyip, rezil yaşıyorsun.

Bir gün olsun Yaratanını anmıyorsun.

Müslüman’ım demeye utan, utan.

Berzâh âleminden haberin yok.

Âhiret âleminden bilincin yok.

Müslüman’ım demeye utan, utan.

Müslümanlık dille, sözle olmaz ki,

Gönül bu, dünya malına doymaz ki,

Müslüman’ım demeye utan, utan.

Bazen kâdere kâhır edersin.

Münafıklara selam verirsin.

Müslüman’ım demeye utan, utan.

Gıybet, dedikodu mirasın mı? 

Yediklerin helal mi, haram mı? 

Müslüman’ım demeye utan, utan.

El, dil, göz, koku, dokunma zinası.

Olmuş bedenlerimiz fuhuş binası.

Müslüman’ım demeye utan, utan.

Dar-ı perişan olduğuna gelir aklına.

Hani çok güveniyordun dostlarına.

Müslüman’ım demeye utan, utan.

Bedenin mi hamal, ruhun mu bilmezsin.

Bu nimetleri verene neden şükretmezsin.

Müslüman’ım demeye utan, utan.

Helal, haram, demedin yedin içtin.

Zevk, eğlence deyip kendiden geçtin.

Müslüman’ım demeye utan, utan.

Müslümanlığı, Müslüman gibi yaşamıyorsan,

Allah demeye, Resulü demeye koşmuyorsan,

Müslüman’ım demeye utan, utan.

Mevki, makam uğruna satmışsan ruhunu,

Dört hokkabazda arıyorsan umudunu,

Müslüman’ım demeye utan, utan.

Yıkılır dünyada yıkılmaz sandığın ne varsa,

Eğer zerre kadar yürekte Allah aşkı yoksa,

Müslüman’ım demeye utan, utan.

Müslümanların düşmanlarını dost edinmişsen,

Dünyalıklar  için aşağı derekelere inmişsen,

Müslüman’ım demeye utan, utan.

Bir garip Yaşar’dır hep dertli söyler.

Bütün insanların secde etmesini diler.

Gök kubbe altında kardeşlik ister.

Secde etmeyen olsun divaneden beter.', 'Müslüman’ım deyip, rezil yaşıyorsun. Bir gün olsun Yaratanını anmıyorsun. Müslüman’ım demeye utan, utan. Berzâh âleminden haberin yok. Âhire...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Yaşar Erdoğan']::text[], 8.5, '{"poet":"Abdullah Yaşar Erdoğan","poet_slug":"abdullah-yasar-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/utan-utan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sohbet-2', 'sohbet-2-abdullah-yasar-erdogan-mq5np', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Havai bir tavır içinde başladı söze; 

İçki, eğlence, zevk madem var; tatmalıyız.

Dedim; Ama Allah akıl, fikir vermiş.

Daha yaşım genç, ileride tövbe ederiz.

Dedim; Yarına senedin var mı senin? 

Bırak boş lafları, yorma beni be dayı.

Uzun, uzun anlattım, beni dinledi.

Pek de benimsemiş değildi.

Hep maddeye koşmuş dünyada.

Eğlencenin her türlüsü,

Onun için mübah sayılmıştı.

Zevk veren ne varsa tatmıştı.

Adına zevk dediği şeyler içinde,

Gırtlağına kadar batmıştı.

Neyi var neyi yok kaybetmiş,

Sokaklarda evsiz yaşar olmuş,

Üç beş kuruş için el açmış,

Saçı sakalı birbirine karışmış.

Böyle bir halde gördüm,

Beş sene kadar zaman sonra.

El açıyordu bana, elinde şarap,

Gelmişi geçmişi olmuştu harap.

Yakası söküktü ceketinin,

İçinde gömleği çok kirliydi.

İnsanım dayanamadım.

Onu tepeden tırnağa giydirdim.

Güzel bir yemek yedirdim.

Karnı doymuştu, gözü ışıldıyordu.

Hafif hafif kaşınmaya başladı.

Bu elbiselere nasıl alışacağım? dedi.

Bir parka oturup sohbet ettik.

Dünyadan bezmişti,

Hele iki yüzlü riyakarlardan,

Dost deyip arkadan vuranlardan,

Epey çekmiş, onları nefretle andı.

Bu arada ezan okundu,

Ben izin istedim gitmek için; 

“Bu ezandan ne anlıyorsun? ” dedi.

Uzun uzun anlattım ona,

Bir zaman sonra ayrıldım.

Ona bir yer bulacağımı,

Ona sıcak yuva kuracağımı,

Ona sevgi verebilecek,

Dostluk verebilecektim artık.

Bu sevdayla oradan uzaklaştım.

Bir hafta sonra onu aramaya çıktım.

Ona ne söz verdimse, hazırlamıştım.

Sıcak bir ev döşemiştim, dostlarla.

Onu aradım iki gün boyunca,

Umudum tükenmek üzere idi,

Bir çöp atılan yerden geçiyordum.

Biri yatıyordu orada, cansız.

Hemen yanına koştum; 

Bir de baktım ki; bizim bahtsız.

Gereken yere haber verdim,

Cenazesini kaldırdık. 

Bu dünyada edemedik  ama,

Son yolculukta, ona dua eyledik...', 'Havai bir tavır içinde başladı söze;  İçki, eğlence, zevk madem var; tatmalıyız. Dedim; Ama Allah akıl, fikir vermiş. Daha yaşım genç, ileri...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Yaşar Erdoğan']::text[], 8.5, '{"poet":"Abdullah Yaşar Erdoğan","poet_slug":"abdullah-yasar-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":58,"source_url":"https://www.antoloji.com/sohbet-2-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mavilerle Donatacağım', 'mavilerle-donatacagim-burhanettin-akdag-5pqk8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Doruklardan çılgınca çağlıyor

Suların gürültüsüyle geliyor hiddetin

Delicesine, kontrolsüzce, uçuşarak 

Taşlarla vuruşuyor yüreğinde zerrecikler

Acısından, hırsından yokluğumun.

Haberini güvercinlerden alıyorum

Takılmış ağacın suya değen dalına

Asılmış umutsuz, beyaz elbiseli sevdam

Çığlıkların karışıyor havaya.

Beyaz zerrecikler yarışıyor, darmadağın

Zamana inat, duvarla vuruşuyor sedası

Yırtıyor havayı, isyanın patlayan fırtınası 

Kor ateşe dönmüş, serin mavilerin.

Şavkını yansıtıyor yıldızlar

Yankılanıyor semada, döne döne

Bir girdaba tutulmuş iniyor

Kızıl tuzlar basıyor, yaralı yüreğime

Yakıyor, acıtıyor, incitiyor.

Islığını duyuyorum nefesinin

Hıçkırıyor kısık sesle, kesik kesik

Çıkamıyor ciğerinden, canhıraş haykırışlar

Tıkanmış, takılmış dönüyor

Aynı yörüngede, biteviye, amaçsızca.

Hırsların dertli dolap gibi amaçsız

Sanki bana nazire, semazen misali

Ritmik, ama aynı noktaya takılmış

Anlamsızca, bakıyor boş nazarlarla.

Yükseklere de savrulsa hırsların

Ve bembeyaz hüzün bulutların

İnmeyecek mi sonunda aşağılara 

Çaresizce, umutsuz ve umarsız.

Düşeceksin kucağıma bitkin, yorgun

Ürkek, çaresiz, yılgın

Avuçlarımda ısıtacağım mavi zerreciklerini

Öpeceğim usulca, teker teker.

Sonra yüzüme süreceğim sırayla

İçeceğim bir yudumda hepsini

Ruhuma, hüznüme ilaç niyetine

Alacağım seni yüreğime

Hapsedeceğim sevdamın sarayına.

Mavilerle donatacağım baştan başa

Sileceğim acılarının yangınını...

(07.05.2005)', 'Doruklardan çılgınca çağlıyor Suların gürültüsüyle geliyor hiddetin Delicesine, kontrolsüzce, uçuşarak  Taşlarla vuruşuyor yüreğinde zerreci...', ARRAY['Türk Edebiyatı','Şiir','Burhanettin Akdağ']::text[], 8.5, '{"poet":"Burhanettin Akdağ","poet_slug":"burhanettin-akdag","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/mavilerle-donatacagim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dolma Kalem', 'dolma-kalem-omer-yildiz-4k9t1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Değiştir ucu,

Ver renk renk mürekkebi

Söyle yazsın...

Sen...

Dolma kalem.

Ne onursuz yaratıksın...', 'Değiştir ucu, Ver renk renk mürekkebi Söyle yazsın... Sen... Dolma kalem. Ne onursuz yaratıksın......', ARRAY['Türk Edebiyatı','Şiir','Ömer Yıldız']::text[], 8.5, '{"poet":"Ömer Yıldız","poet_slug":"omer-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/dolma-kalem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünya', 'dunya-omer-yildiz-8dpwo', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ulan dünya! ...

Ne obur

Ne aç gözlü şeysin.

Bırak,

Azıcık da bizi

Öbür gezegenler yesin....', 'Ulan dünya! ... Ne obur Ne aç gözlü şeysin. Bırak, Azıcık da bizi Öbür gezegenler yesin.......', ARRAY['Türk Edebiyatı','Şiir','Ömer Yıldız']::text[], 8.5, '{"poet":"Ömer Yıldız","poet_slug":"omer-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/dunya-83-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Nasihat', 'son-nasihat-omer-yildiz-gpg5n', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dost...

Gönül gözünü

İyi aç,

Gönül dostunu 

İyi seç...

Semada herşey boş

Her söz

Laf-ı güzaf.

Dünyada 

Muylu olmak için

Ya inkar et,

Ya da

İtiraf...', 'Dost... Gönül gözünü İyi aç, Gönül dostunu  İyi seç... Semada herşey boş Her söz Laf-ı güzaf. Dünyada  Muylu olmak için Ya inkar et, Ya da İ...', ARRAY['Türk Edebiyatı','Şiir','Ömer Yıldız']::text[], 8.5, '{"poet":"Ömer Yıldız","poet_slug":"omer-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/son-nasihat-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dudakların Değdi', 'dudaklarin-degdi-omer-yildiz-s4oy6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dudakların değdi,dudaklarıma.

Sevda ateşini,söndüremezsin.

Girdin gözden ırak anılarıma

Anılarıma söz geçiremezsi...

Sevmesen de olur, söyle yüzüme,

Yürü geç gönlümden, bir izin kalsın.

Güzelliğin vurdu mühürü gözlerime

Açılarsa mührün yerde açılsın...', 'Dudakların değdi,dudaklarıma. Sevda ateşini,söndüremezsin. Girdin gözden ırak anılarıma Anılarıma söz geçiremezsi... Sevmesen de olur, söyle...', ARRAY['Türk Edebiyatı','Şiir','Ömer Yıldız']::text[], 8.5, '{"poet":"Ömer Yıldız","poet_slug":"omer-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/dudaklarin-degdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küllenmiş yüreğim', 'kullenmis-yuregim-omer-yildiz-dyf9d', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Küllenmiş yüreğim,

                       Alma eline.

                               Kurumuş toprağı

                                                    Sürme

                                                          Toz kalsın...

Şal olsam da

           yarim

                   Sarma

                                 Beline...

Şahbazım,

          Dönemem,

                Dilde söz kalsın..

Kara dağlar

               Kalır,

                    Kara

                       Dumanda,

Ne sevdalar 

           Yaşar,

                  Kimi zamanda...

Kabahat,

       Deliden

              Destur Umanda.

Destursuz 

         Varmaya,

                Dilde

                 Söz kalsın...

Parçalanır ışık,

                 Renk

                     Renk

                           Kırılır...

Gül...

Toprağa küser,

               Bülbül 

                  Güle darılır....

                            Bahar,

                                Goncasına

                                      Keyf ile sarılır.

Gözden 

        Göze giden yolda,

                           Söz kalsın...', 'Küllenmiş yüreğim,                        Alma eline.                                Kurumuş toprağı                                        ...', ARRAY['Türk Edebiyatı','Şiir','Ömer Yıldız']::text[], 8.5, '{"poet":"Ömer Yıldız","poet_slug":"omer-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/kullenmis-yuregim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dörtlük - I', 'dortluk-i-hamit-pala-7l4vz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gönlümün bülbülü ötse seherde, 

Kınalı yârimin elleri nerde? 

Bir merhem yok mudur çektiğim derde? 

Sarıyorum amma, sen gel bana sor.

03.10.2005', 'Gönlümün bülbülü ötse seherde,  Kınalı yârimin elleri nerde?  Bir merhem yok mudur çektiğim derde?  Sarıyorum amma, sen gel bana sor. 03.10....', ARRAY['Türk Edebiyatı','Şiir','Hamit Pala']::text[], 8.5, '{"poet":"Hamit Pala","poet_slug":"hamit-pala","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/dortluk-i-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Medet Ya Rabb!', 'medet-ya-rabb-ekrem-sama-zlce4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çarpıtılan senin emrindir; cihad,

Şimdi mücahide hasrettir serhad.

Allahü Ekber’le çınlardı bilad,

Hafıza kaybı var medet İlahi! 

Lime lime İslam yurdu hep harab,

Şehit kanlarıyla boyandı turab,

Zulüm içindeyiz sen acı ya Rabb! 

Bizlere şuurlar bahşet İlahi! 

Rabbım, mücahitle terörist bir mi? 

Beyni sulanmışlar bunu bilir mi? 

Cihad ruhu öldü, hiç dirilir mi? 

Emrinle dirilir, lütfet İlahi! 

(İstanbul:05.10.2005)', 'Çarpıtılan senin emrindir; cihad, Şimdi mücahide hasrettir serhad. Allahü Ekber’le çınlardı bilad, Hafıza kaybı var medet İlahi!  Lime lime ...', ARRAY['Türk Edebiyatı','Şiir','Ekrem Şama']::text[], 8.5, '{"poet":"Ekrem Şama","poet_slug":"ekrem-sama","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/medet-ya-rabb-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostluğa Kardeşliğe', 'dostluga-kardeslige-adnan-durdagi-jxlcd', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gel gardaşım gel hele

Bar tutalım el ele

Dost olalım hep böyle

El ele biz birliğe

Dostluğa kardeşliğe

İnsanları sevelim

Kin nefreti savalım

Hep beraber olalım

El ele biz birliğe

Dostluğa kardeşliğe

İnsanız insanlığa

Biz muhtacız dostluğa

Sevince mutluluğa

El ele biz birliğe

Dostluğa kardeşliğe

Değer mi kötülüğe

Hep güzele iyiliğe

Candan beraberliğe

El ele biz birliğe

Dostluğa kardeşliğe

Gelecek yarınlara

Çocukla torunlara

Yurdumun huzuruna

El ele biz birliğe

Dostluğa kardeşliğe

Kardeşliğin yüzünden

İnsanlığın özünden

Ataların izinden

El ele biz birliğe

Dostluğa kardeşliğe

Bu dünya hepimizin

Mutlu yarınlar bizim

Hoş görüdür tek çözüm

El ele biz birliğe

Dostluğa kardeşliğe

YETİMİ''yim can olsam

Derdine derman olsam

Yoluna kurban olsam

El ele biz birliğe

Dostluğa kardeşliğe', 'Gel gardaşım gel hele Bar tutalım el ele Dost olalım hep böyle El ele biz birliğe Dostluğa kardeşliğe İnsanları sevelim Kin nefreti savalım ...', ARRAY['Türk Edebiyatı','Şiir','Adnan Durdağı']::text[], 8.5, '{"poet":"Adnan Durdağı","poet_slug":"adnan-durdagi","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/dostluga-kardeslige-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anadolu Diyorki... Biz Bütünüz', 'anadolu-diyorki-biz-butunuz-adnan-durdagi-kva8j', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ANADOLU DİYOR Kİ  !      19.......................

Şırnaklısı Rizelisi 

Tekirdağlı Vizelisi 

Sinoplusu Cizrelisi 

Biz bütünüz bölünmeyiz 

Milletiyle ülkesiyle 

Bir bütünlük ilkesiyle 

Savunmada tek sesiyle 

Biz bütünüz bölünmeyiz 

Antakyadan Ordusuna 

Kuzey Kıbrıs yavrusuna 

Çeşmesinden Vanlısına 

Biz bütünüz bölünmeyiz 

Ne alevi ne sunnisi 

Çerkez Türkmen Azerisi 

Yedi bölge yurdun sesi 

Biz bütünüz bölünmeyiz

Kastamonu devrim yeri

Birlik ister ölü diri

Hacıbektaş pirler piri

Biz bütünüz bölünmeyiz 

Amasyanın tamimi var

Kocatepe Dumlupınar

Bölünürsek ceddim kınar

Biz bütünüz bölünmeyiz

Kayseride dağ Erciyes

Yükseliyor Sivastan ses

Gençler koşuyor bir nefes

Biz bütünüz bölünmeyiz

Gezdim yurdu karış karış 

Tüm insanlar ister barış 

Boşa değil bu haykırış 

Biz bütünüz bölünmeyiz 

Iğdır Konya Adanası 

Sıra dağlar düz ovası 

Anadoludur yuvası 

Biz bütünüz bölünmeyiz 

Bir incisi İstanbula 

Adıyaman Artvin Muğla 

Şanıların kenti Urfa 

Biz bütünüz bölünmeyiz 

Serhat şehri Kars Kalesi 

Antalyası mor lalesi 

İlk kurşunla İzmir sesi 

Biz bütünüz bölünmeyiz 

Uludağın kalkmaz karı

Çaydaçıra gagkoş barı

Ege efeler diyarı

Biz bütünüz bölünmeyiz

Barış dolu bir Türkiye 

İpsaladan Şemdinliye 

Kağızmandan tüm ülkeye 

Biz bütünüz bölünmeyiz

Dıyarbakırda sur çekmiş

Mardinde kültür yerleşmiş

Fıratla dicle birleşmiş

Biz bütünüz bölünmeyiz

Asya ile Avrupası 

Başkentidir Ankarası 

Bizlere ata mirası 

Biz bütünüz bölünmeyiz 

Benim Kahramanmaraşım 

Hopa Erzurum Dadaşım 

Gaziantep der gardaşım 

Biz bütünüz bölünmeyiz 

Ceylanpınar Zonguldağı 

Anamurla Samsun bağı 

Çanakkale Ağrı Dağı 

Biz bütünüz bölünmeyiz

Afyon Aydın Muş Tatvanı

Hakkari Ordu Batmanı

Bu halk böldürmez vatanı

Biz bütünüz bölünmeyiz

Aynı halay aynı sazı 

Bir milletiz herkes razı 

Türkü Kürdü var mı Lazı 

Biz bütünüz bölünmeyiz 

Kütahyadan Malatyadan

Kızılırmak Sakaryadan

Çağrımız var Mevlanadan

Biz bütünüz bölünmeyiz

Özüm vatan canım bayrak 

Şehidimle dolu toprak

Olur mu hiç ayrı bakmak 

Biz bütünüz bölünmeyiz 

Seksenbir il bütün yerler 

Bu vatan bizimdir derler 

Bir ağızdan türkü söyler 

Biz bütünüz bölünmeyiz

Yetimi aşık vatana 

Ülkemde şehit yatana 

Edirneden Ardahana 

TÜRKİYEYİZ bölünmeyiz

             Adnan DURDAĞI

http://www.antoloji.com/adnan_durdagi', 'ANADOLU DİYOR Kİ  !      19....................... Şırnaklısı Rizelisi  Tekirdağlı Vizelisi  Sinoplusu Cizrelisi  Biz bütünüz bölünmeyiz  Mi...', ARRAY['Türk Edebiyatı','Şiir','Adnan Durdağı']::text[], 8.5, '{"poet":"Adnan Durdağı","poet_slug":"adnan-durdagi","theme":"Türk Şiiri","is_hero":false,"total_lines":95,"source_url":"https://www.antoloji.com/anadolu-diyorki-biz-butunuz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bayrama Çağrı', 'bayrama-cagri-adnan-durdagi-4cfc9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ey Türkiyem bu gün birlik olalım

Sevgi dostluk köprüsünü kuralım

Kin nefretin zincirini kıralım

Bar tutalım sallanalım bugün de

Sevgi yumağını dokumak için

Kardeşlik türküsün okumak için

Severek gülerek şakımak için

Birlik olup bağlanalım bugün de

Canlar feda olsun bu güzel yurda

Binlerce şehidim yatıyor burda

Çok güzel nimetler bu cennet yerde

Kaynaşıp ta karılalım bugün de

Ne kadar övünsek az gelir bize

Düşmanın oyunu vız gelir bize

Çağdaşlık yolunda hız gelir bize

Cahillikten arınalım bugün de

Sevgi olsun bulut bulut yayılsın

Dostluk olsun insanlığa sayılsın

Barış olsun hoşgörüye uyulsun

Şeffaf berrak durulalım bugün de

YETİMİ''yim sona ersin kinimiz

Kardeşliği emrediyor dinimiz

Bu gün bizim bayram seyran günümüz

Tahtlarına kurulalım bugün de', 'Ey Türkiyem bu gün birlik olalım Sevgi dostluk köprüsünü kuralım Kin nefretin zincirini kıralım Bar tutalım sallanalım bugün de Sevgi yumağı...', ARRAY['Türk Edebiyatı','Şiir','Adnan Durdağı']::text[], 8.5, '{"poet":"Adnan Durdağı","poet_slug":"adnan-durdagi","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bayrama-cagri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tutmadı Gitti', 'tutmadi-gitti-adnan-durdagi-h2e1g', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir maruzatım var yüce makama

Aralık hesabı tutmadı gitti

Uğraştık didindik olmadı ama

Hesap günü bitti tutmadı gitti

İşleri sorarsan biraz çok idi

Zamanı sorarsan sanki yok idi

Geçmişe bakarsan dairem tek idi

İnceleme bitti tutmadı gitti

Üzüldük sıkıldık çaresiz kaldık

Maziye bakarsan hep ödül aldık

Nasıl yapamadık inan bunaldık

Düzeltmeler bitti tutmadı gitti

YETİMİ ADNAN''ım yok çare bende

Halimden anlarsın dert oldu hem de

Makamsın takdir et umudum sende

Uzatmalar bitti tutmadı gitti', 'Bir maruzatım var yüce makama Aralık hesabı tutmadı gitti Uğraştık didindik olmadı ama Hesap günü bitti tutmadı gitti İşleri sorarsan biraz ...', ARRAY['Türk Edebiyatı','Şiir','Adnan Durdağı']::text[], 8.5, '{"poet":"Adnan Durdağı","poet_slug":"adnan-durdagi","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/tutmadi-gitti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dadaş-"siz hiç ay aşığında ağladınız mı" Kitabından', 'dadas-siz-hic-ay-asiginda-agladiniz-mi-kitabindan-omer-ekinci-micingirt-s8wpz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Biz dadaşız dadaş ha sevdalıyız ağalar 

Biz vurgunuz bayrağa, cân kurban cân vatana 

Biz ciritle büyüdük, şahlanırlar çağalar

Biz devlet-i ebediz, tabyalarda yatana 

Biz İbrahim Hakk’ıyız, mârifetli yaşarız

Biz ki Şükrü Paşayız, Edirne’de coşarız 

Biz Alvar’lı Efe hâyy, Hak aşkıyla pişeriz 

Biz dadaşız dadaş hâ, şükrettik Yaradan’a 

Biz pek şanlı bir millet, tülleniyor sinemde

Biz şehitlik bıraktık üç kıtada Yemen’de 

Biz Ermeni besledik, şimdi başka dümende

Biz ölümle gardaşız! Fedâ olsun vatana 

Biz Malazgirt Mohaçız biz ne kıtalar gördük 

Dava büyük aşk büyük, gün geldi hesap sorduk 

Biz alevler içinde, Büyük Türkiye kurduk 

Biz fetihler müjdeli, hayranım o irfâna 

Biz doğunun kalesi, palandöken balası 

Bizde tarih yoğruldu, biz yiğidin alası 

Bize dadaş derler ha! mertliktir hâsılası

Biz milli ruh sancağı, astık bütün cihâna', 'Biz dadaşız dadaş ha sevdalıyız ağalar  Biz vurgunuz bayrağa, cân kurban cân vatana  Biz ciritle büyüdük, şahlanırlar çağalar Biz devlet-i e...', ARRAY['Türk Edebiyatı','Şiir','Ömer Ekinci Micingirt']::text[], 8.5, '{"poet":"Ömer Ekinci Micingirt","poet_slug":"omer-ekinci-micingirt","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/dadas-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul', 'i-stanbul-ufuk-coban-x8hpf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Saklanmak için köşe var mı yüreğimdeki acılardan,

Yıllarca bekle, bulunca yıkıl, kaçılır mı gerçeklerden? 

Suç var mı kaderin her sözünün yüreğine değmesinde,

Değecek bir nefes kalmıyor ki gücüm olsun yürümeye.

Yüreğimin doğduğu yere gitmek isteği var bugün ellerimde,

Hayatımın güzel günlerini doğuran güneşin battığı yere.

Toprakda can var sanki bastırmıyor beni uzak köşelerde,

Dönmeyi yakalamış bırakmıyor bedenim yalnız gecelerde.

Bu kaçışı ben koymadım kendime durup dururken,

Birisi gelip her defasında bir duvar ördü severken.

Bir kale kaldı sonunda içine giremedeğim kapısından,

Gücüm de yok yıkmaya zarar veririm korkusundan.

Uzakta, yalnız, sessiz ne yapar ki bir garip kul? 

Bir sevda arıyor, olmuyor, değmiyor kimse yüreğine usul usul.

Ya özgürlük ya gözler anlatıyor sonunda hayat acımasız bir okul,

Derdime derman olacak birini bulamadım, bari sen merhem ol İstanbul.

06/10/2005 08:45', 'Saklanmak için köşe var mı yüreğimdeki acılardan, Yıllarca bekle, bulunca yıkıl, kaçılır mı gerçeklerden?  Suç var mı kaderin her sözünün yü...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Çoban']::text[], 8.5, '{"poet":"Ufuk Çoban","poet_slug":"ufuk-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/istanbul-338-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Benim Sardunyamsın', 'sen-benim-sardunyamsin-huseyin-erdogan-r6c0u', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'her sabah uyanınca

kokunu bırakıver

benden yana

serin esen rüzgarlarla

ben de seni

içime çekeyim doya doya

gerçi ömrüm boyunca

seni dalında koklasam da

yine doyamam sana

hiç olmazsa yokluğunda 

teselli bulurum buralarda

ne olursun oralarda

her baktığın yerde

yalnızca beni görsün gözlerin

ruhumu bir meltem yeli gibi

okşasın bütün sözlerin

al beni de senin dünyana

ben de bir güneş gibi

doğayım yüreğimin sultanına

bir daha batmamacasına

bil ki vaz geçemem senden 

sonunda ölüm olsa da

sen benim sardunyamsın

ömrünce yer yüzüne

en güzel kokular senden yayılsın

seni hiç görmedim amma

inan ki sen bende hep varsın

sen benim mahşerde bile

delicesine seveceğim tek yarsın

                      06.10.2005', 'her sabah uyanınca kokunu bırakıver benden yana serin esen rüzgarlarla ben de seni içime çekeyim doya doya gerçi ömrüm boyunca seni dalında ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/sen-benim-sardunyamsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırık Düş Ezgileri', 'kirik-dus-ezgileri-metin-basturk-oeg6r', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 've aşk,

karanlığın en koyu tonu

ne ahval ne de yalnızlık şiiridir bu...

sade susmaları kuşanmak

sade susmaları istemlerine sunmak

ve sınamak aşkı sevmelerin örsünde

tren bekleyen garların kahreden karanlığında

kara gözlerindeki ölüme susamak...

sen...

sesimin yankısında kıyametim

bütün yangınlardan artakalan

coğrafyamda kurak bir iklim

aldırmaz yaralı kuşların çığlığına bile

kanat kanat takınıp  en olgun tavrını

akan zamanın telaşında

kan damlar da göğsün,

gülümserdin...

derken,

kederli bir Malatya akşamında

uzanıp bir selvi dal gibi geceyi alnından öperdin...

her çıkmazda bir tufan şimdi,

yağar adı konmamış sağanaklar

puslu gözlerinden

yağar acemi sevmelere

bütün duvarlarda kasvet

ve buğusunda kan sızar geceye

kaç zamandır böyle,

ay ışığına takılır gülüşün

sürgün yemiş gibi mağlup,lal...

ve puslu,soluksuz bir poyraz

akşamüstü alacasında çığlık çığlığa

bu kentin buğday tenli çocukları gibi

dağıtma hüznümün katran rengini...

desem ki; 

zamanın bir ucundan

uçurup kanatlarımı Harput’tan ardın sıra

böyle yol-iz bilmezken

tutup ellerinden

gözlerinin karasına karşı ağlamak

beni böyle garip

böyle mahcup

böyle divaneme sebep

olmasaydı gözlerinin karası

yokluğun bu denli koymazdı bana

ve dahi,gölgenin aksi düşmezken yüzüme

uzun uçurum boylarından düşmek

ayaz gecelerin sabahında yada

kor ateşlere dadanmak gibi

kelimeler öyle zor

öyle lanetli takılır boğazıma

bilmelisin ama,

yitik aşkların öksüzlüğüdür bu

vakitsiz yağmalanmasıdır bir kentin

sen tapın yine düşlerine

her hecemde solmasın ama rengin...

kan-revandır

talandır bu ömrümde

her ömür kendi rahminde ölür yinede

çünkü derim,

kınında hançer gibi ışıldayan kara gözlerinden

mahcup bir bakış düşerse bile

sevdan yine talandır bende...', 've aşk, karanlığın en koyu tonu ne ahval ne de yalnızlık şiiridir bu... sade susmaları kuşanmak sade susmaları istemlerine sunmak ve sınamak...', ARRAY['Türk Edebiyatı','Şiir','Metin Baştürk']::text[], 8.5, '{"poet":"Metin Baştürk","poet_slug":"metin-basturk","theme":"Türk Şiiri","is_hero":false,"total_lines":62,"source_url":"https://www.antoloji.com/kirik-dus-ezgileri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'e.U. aa! ? (!)', 'e-u-aa-akin-akca-pwanq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '*-

I.a

Kendi içinde birtakım sırlar saklayan eşuyumlular,

Birbirleriyle de uyumlular.

Evet, 3ekim’i, dördüne günlerden bağlayan gece; 

Saatler durdurulmuş olmalı (saat)    23:58’de …

01:30’da Gül, oraya varmış; 

(da raporunu Baykal’a, envai çeşnili verememiş) 

13 Nisan’da doğmuşum sabaha karşı 01:30 sularında.

Yani bir uğursuzluk yok (hayret) 

[ saat (öğlen)    12 tam, 00:00 p.m. surları’ydıysa,

(ayrı ayrı değil ikisinde, aynı bir hamurda)   ]

, Biraz gecikmeyle:

Merdivenaltı değil.

I.b

Güzel günler bekliyor…

*

Hawking de ’73’de doğmuş.

(ağaçaltı elmaları’yla istop oynayan 

Newton öldüğü yıl) 

Yani 300 yıl öte, Galile’nin ölümünden:

(Bir diyalog der ki, diyor ki:

- Gaipten Bir Ses:

“13 Nisan 1973 mü? ”

- Ben: 

‘Büyük oranda evet

ama bir adım kala ‘73’e, yani 1972’de; 

Jakob Bakenstein keşfetti

bir şey de varmış diye,  ‘Kara delik entropisi’..

ki ’72, 1973’ü elbet getirecekti.

sonra Roger Penrose doğdu,

gerçekten doğmadı ama,

yani keşfini yaptığında doğmuş oldu; 

‘73’ te doğmuş oldu Twistorlar’la. Ki

tüm o bilimsel çalışmalar boyunca,

Hawking’in en yakın partneriydi! 

düz mantık.. ya bu işte.

Bu cevap seni tatmin etti mi, ‘Gaipten -Bir ses’? 

- Gaipten Bir Ses: 

Evet ancak senin sesin de sanki 

gaipten geldi ….

- Ben:

: ;) 

) 

Devam ettirmek, bir şeyi! ...

*

Yapraklaraltı gölgeliği’n(d)   e dinlencede 

Dinlenen, ama aklı yoğun

Ama değil yorgun

Ve hisleri de …

Biraz sabretmek lazım (o halde) 

, umut-gelen’ günleri -kendileri için- daha güzel.

*

Bağlantılara bakmak gerek,

[ “… Sayılar hiç bir şeydir. 

önemli olan anlamdır - 

dizilim …”

diye(rek)    çimmiş mi,

çığırırken ‘P Yakınlaşması’ndan

..Bay Cohen; 

p filmindeki o gezgin(ci) ? 

Suçum yok Valhalla (! 

onun yalancısıyım valla :) 

Barış(mak)    gibi ] 

Derinlik bazen bazıları için bir engerek:

Hawking’in Newton’a döngüsü, örneklenen; 

Doğumum olayına da benziyor görünüyor.

(O)    Mütabakat, A.B.’yle nihayetlenen:

(Erkan Yolaç çok yaşa) 

O, olduğu için değil; 

Ya da biz olduğumuz için değil:

O, o olduğu için ve biz de biz olduğumuz için.

Yani hep birlikte yelken açacağımız için.

(Emme basma tulumba,

İzmir ya da Mehter Marşları gibi değil) 

*

Evet çünkü mantık götürmez duyguları; 

İçi boş bir

Kuru saflık götürür..

Yani ortadan kaldırmaz anlamında …

Ve/ ama safkan İngiliz at koşunca,

Tazı(lığı)   sı/yla Orta Asya’nın Türkiye’sinden Anadolu’nun

Trakya’nın; 

At gözlükleri düşmüş:

Düşsün! ! 

Süratlenince zihin açılır,

(koşunca insan soluk soluğa kalır,

bu, ne güzeldir) 

Hem beden de bundan faydalanır.

Hafıza da bir daha (da)    unutmaz,

Hızla okunulan bir sayfayı.

Ama süratle okuyorum diye de -

genelin paylaştığı bir çeşit umuda

devrik işaretler çakan olumsuz

köprülerdir tam da bu beş-dizeler’de

sözü edilen … -

Düşmemeyi güçten hepten insan, bilmeli.

*

“O ’73 (yılı)    bağı”,

Hepsinin hepsine benziyor insanların insanlararası uyumu.

Mucizeleri ifade etmek için yeterli kelime yok.

Ancak ‘gece 01:30 benzeşmeleri’ de hayli garip

Ki gerçekleşebildi, ‘gerçek olamadığı 

İçin’ değil asla muzdarip.

II.

Hayatta olmak elbet çok güzel

Ama düşünün bir:

Büfeye yollayan çocuğunu kavşaktaki, bir anne; 

Ekmek almaya.. ya da Hürriyet, Milliyet..

…Çocuk ilerlerdi nasıl, bacaklarına güç ver(€)   mese? ? 

E®vet, böyledir; evet! 

(ah, er-velet; yılmayan şu velet.

“şu”, “bu” değil; o belli, belirli. 

senden, benden bizden biri) 

Olmak çok güzel hayatta elbet,

Ama “daha güzel ‘bir (güzel)   ’ ayakta durmak”

Dimdik! 

(Ama barış olmalı yolu,

yenilmeyecektir asla kardeşlik gayesi, bu bulduğu; 

ha burada şu önemli) 

Ayakta öyle dururken, çevirdiğin pedallarda

..saklısın ….

Yaşamak, o ‘ayakta durmak’ (görevi)    olabilir ki:

(zaten oldu) 

… Adı üstünde, yaşam(ak) : (yaşam ak! duru, 

beyaz.. bembeyaz…) 

{ yaşam, durağan; isim –sim-isim, ‘cep tel-sim isim’..

- oldu mu hayat, dilbilgisinde fiil; 

hayat, yaşamak! (?)    }

Bak, aman ne oldu! 

: Hayatla yaşam bir göründü! ! 

Çünkü yaşamak ikisinin tümü etti! 

Döngüler eşitlendi.

Umut, filiz; sabırsa, büyük boy boy verdi! 

“‘Asla sonlanmayacak’ gibi fikir”ler, tercüman oldu

Hislerden; nefret ikizleri’ne, 

Kendisinin.. 

Duygularda saklanan

İt onu! 

[itecek isen, (it)   bir kara inadı! ! .. ]

O (göze)    nefreti …

: İşte, arın(mıştı)   dı hisler; 

Empatiler; umut yeşerten ilerleyişler(dir) , duyulan sempatiler! 

Sir’müş –

miş müş meş şeşbeş de dubara bağıra 

bağıra düşeş- babası, fakat çok 

Çalışmış ki demek buralara gelmiş:

“Isı harekettir.” (1620; F. Bacon, 1561 -  1626) 

(Demek ta o zamanlardan,

Kendi içinde düzenli ‘dalga-parçacık paradoksu’) 

: Yumurta-tavuk mevzu, kirli çıkın hiç değildir! ! 

Bilinebilir gidişler, gidiş-geliş’lerde ancak *

Gitmeyişlerde iletişimin…

Öğrenilebilir.

-

Başlıktaki ‘a! ’ bir şaşma ifadesi sergilese de, mutlu neticelenmiş. Asıl isim E.U. olacaktı ama hepsi büyük olmasın diye

Avrupa Birliği’ne girişe atfen, (konuyu)    bir değerlendirme, (olayları netleştirme …) 

Sevgiler

“Isı harekettir” lafı Francis Bacon’a ait.

Sondan üçüncü dizedeki ‘ancak’ kelimesi ‘sadece’ anlamına gelmemekte, ‘yalnız’ anlamında.

5.10 ‘05

-*', '*- I.a Kendi içinde birtakım sırlar saklayan eşuyumlular, Birbirleriyle de uyumlular. Evet, 3ekim’i, dördüne günlerden bağlayan gece;  Saatl...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":162,"source_url":"https://www.antoloji.com/e-u-aa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sanki', 'sanki-nurdan-elver-ugyx8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sanki sabahlar soluksuz 

Sensiz. 

Sanki güneş doğamıyor, 

Rüzgar esemiyor, 

Nefes alamıyor sabahlar sanki, 

Sensiz.

Sanki geceler uykusuz

Sensiz.

Sanki yıldızlar parlayamıyor,

Ay doğamıyor,

Nefes alamıyor geceler sanki,

Sensiz.

Sanki,

Sensiz ben,

Sabahsız, gecesiz.

Güneşsiz, aysız.

Rüzgarsız, nefessiz.

Sanki sensizlik

Sankisizlik...', 'Sanki sabahlar soluksuz  Sensiz.  Sanki güneş doğamıyor,  Rüzgar esemiyor,  Nefes alamıyor sabahlar sanki,  Sensiz. Sanki geceler uykusuz Se...', ARRAY['Türk Edebiyatı','Şiir','Nurdan Elver']::text[], 8.5, '{"poet":"Nurdan Elver","poet_slug":"nurdan-elver","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sanki-33-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben,Ben Olmadımki,Biz...', 'ben-ben-olmadimki-biz-seyhan-sevgili-e44yr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yok yok! ...

Aynı cümlede değiliz biz.

Olmayacağızda,seni bildiğim gibi biliyorum.

Sana sormadığıma kızma düşünceni.

Hiçbir şeyin değişmeyeceğinide biliyorum.

Yeni doğmuş bir bebek gibi temizsin.

Yeni açan bir yaprak gibi berrak.

Toprağa düşen ilk yağmur damlası gibi paylaşılmazsın

Biz,biz olamadıysak,olamayacaksak...

Sen söylemezsin biliyorum.

Ben,ben olamadığımdandır.', 'Yok yok! ... Aynı cümlede değiliz biz. Olmayacağızda,seni bildiğim gibi biliyorum. Sana sormadığıma kızma düşünceni. Hiçbir şeyin değişmeyec...', ARRAY['Türk Edebiyatı','Şiir','Seyhan Sevgili']::text[], 8.5, '{"poet":"Seyhan Sevgili","poet_slug":"seyhan-sevgili","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ben-ben-olmadimki-biz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kapan', 'kapan-naime-erlacin-c5u0k', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'alışkanlığa rücu edilir yıldız çekiminde

gök ve kök aynı hamurdan

toprakla 

iç ormanı arasında yaşam 

bir kapan bazen

kişi hem yem hem fare

doğmayı umar ecel tazeliğiyle

suyu çekilirse ruhun

göğüne tapan 

mutlak bir ilkel canlanır derinde

sorarız: 

yıldızımız kim? 

takınca süngüsünü hani aslına döner ya insan

(4 Ekim 2005)', 'alışkanlığa rücu edilir yıldız çekiminde gök ve kök aynı hamurdan toprakla  iç ormanı arasında yaşam  bir kapan bazen kişi hem yem hem fare ...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kapan-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kıymık', 'kiymik-naime-erlacin-4vwsj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'yaşanmamış bir yaz tütsüleniyor saçlarımızda

gün dünden yaslı

yağmur bırakıyor arsız güz gelen zamana

elleri tanımlıyoruz yeniden

:

şemsiyemiz yok çünkü

güzel bir dönüş olabilmek uğruna

ağrıyan göğsümüz

yaprak sarısına vuruyor düşerken

anlamıyoruz

neden siyahtır yalnızlık

şiir derlerken kara bir delikten

bağbozumu neden bu denli insafsız

bu kıymık izleri avuçlarımızda

neden? ....

(4 Ekim 2005)', 'yaşanmamış bir yaz tütsüleniyor saçlarımızda gün dünden yaslı yağmur bırakıyor arsız güz gelen zamana elleri tanımlıyoruz yeniden : şemsiyem...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kiymik-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...Yalnızlık Kapısı...', 'yalnizlik-kapisi-naime-erlacin-cad88', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'içeriye dönen ey! 

yalnızlığı paylaşırız 

aynı kapıda

aşk sırtımızda çıban

şiir

defin alanı 

söz meleklerinin

bir dizi intihardan sıyrılmak

dönüşmek anlamlı bir intihara

ölümcül direniş 

aynı kapıda

önü güz

arkası ıssız arazi

dışarıya susmanın bu fasılda

kimsesizliğini anlatırız

mahmur güller 

solar da dudağımızda

son müntehirin dilinde sızlayan 

külle noktalanır 

erken eskitilmişliği hayatın

ölmeyi öğreniriz fütursuzca

cetvel keskin 

eller kelepçeli

aynı kapıda

(4 Ekim 2005)    

(''ŞİKÂYETNAME'' - Hayal Yay. Temmuz 2010, Sayfa 44)', 'içeriye dönen ey!  yalnızlığı paylaşırız  aynı kapıda aşk sırtımızda çıban şiir defin alanı  söz meleklerinin bir dizi intihardan sıyrılmak ...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/yalnizlik-kapisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsan Doğuracağım…', 'i-nsan-doguracagim-muammer-celik-ptb6c', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kendime bir kadın bulacağım

ondan hamile kalacağım

ve bir aşk çocuğu doğuracağım...

Çocuğun 

adı Dize

göbek adı Şiir

soyadı Duygu konacak...

Büyüdüğünde; 

İNSAN gibi İNSAN olacak! ...

BirDeli

06.10.2005', 'Kendime bir kadın bulacağım ondan hamile kalacağım ve bir aşk çocuğu doğuracağım... Çocuğun  adı Dize göbek adı Şiir soyadı Duygu konacak......', ARRAY['Türk Edebiyatı','Şiir','Muammer Çelik']::text[], 8.5, '{"poet":"Muammer Çelik","poet_slug":"muammer-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/insan-doguracagim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Kendine Yan', 'sen-kendine-yan-munevver-senol-zyg2j', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gün gelirde bu dünyadan gidersem eğer.

Sen bana değil, asıl sen kendine yan.

Senden bir   ricam olacak haa,

Beni iyi sözlerle an.

Merak etme  beni sakın, 

Ben orada da yanlız kalmam.

Islık çalarak seslenirim onlara.

Bir dirsek atarım sağ komşuma,

Bir dirsekte sol komşuma.

Huhuu, yalancı dünyadan ben geldim derim.

Çok eminim onlarında gider hoşuna.

Oh be ne neşeli komşu geldi derler gülerek.

Tabii tanıtırım kendimi önce onlara.

Dünyanın halini sorarlarsa 

Özenilecek bir şeyin kalmadığını.

Herkesin buraya kaçmak için can attığını söylerim.

Bak beni merak etme, 

Ben buraya da alışırım gönlümü eğlerim.

Sen bana değil, asıl sen kendine yan...', 'Gün gelirde bu dünyadan gidersem eğer. Sen bana değil, asıl sen kendine yan. Senden bir   ricam olacak haa, Beni iyi sözlerle an. Merak etme...', ARRAY['Türk Edebiyatı','Şiir','Münevver Şenol']::text[], 8.5, '{"poet":"Münevver Şenol","poet_slug":"munevver-senol","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sen-kendine-yan-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cevapsız Koyma Yâr', 'cevapsiz-koyma-y-r-ayhan-yavuz-acikgoz-edssx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Her duyguyu atsam da hasret durur sînede

Acep öldüren bu his kaybolur kaç senede

Beni sevmediğini söyle ama gene de

Beni cevapsız koyup düşünceye salma yâr

Üç kuruşluk uykumu hayâlinle çalma yâr

(adana-05.10.2005)', 'Her duyguyu atsam da hasret durur sînede Acep öldüren bu his kaybolur kaç senede Beni sevmediğini söyle ama gene de Beni cevapsız koyup düşü...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Yavuz Açıkgöz']::text[], 8.5, '{"poet":"Ayhan Yavuz Açıkgöz","poet_slug":"ayhan-yavuz-acikgoz","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/cevapsiz-koyma-yar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostluk Üzerine', 'dostluk-uzerine-alper-kuruk-0rvhv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Unumu eledim astım eleği

Yenemedim bir kez olsun Feleği,

Düşeş attı kuvvetliymiş bileği

Bükmediğim eli öpmem gerekir.

Kırktan sonra bu saz çalmak neyime

Beğendirmek zordur gönül beyime,

Bir koşum var o deyimden deyime

Yüz akıyla bundan çıkmam gerekir.

Hayat yalnızlıkla gelip geçmiyor

İnsan uygun bir dost bulup seçmiyor,

Arkadaş olmaksa cana yetmiyor

Dostluk için eller sıkmam gerekir...', 'Unumu eledim astım eleği Yenemedim bir kez olsun Feleği, Düşeş attı kuvvetliymiş bileği Bükmediğim eli öpmem gerekir. Kırktan sonra bu saz ç...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/dostluk-uzerine-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eylül', 'eylul-halil-i-brahim-kecebas-3hfkn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Eylül,hüzünlendirir beni her seferinde

Neşe dolu yaz mevsiminin bitmesi…

Rengarenk ağaçların ayrılık gözyaşı dökmesi…

Bir matem rüzgarı eser eylül günlerinde

Fakat bir başkadır eylül akşamları

Şiirler ve şarkılar söylenir ay ışığında

Bir de sevgilin oldu mu yanı başında

Bu anı değişmezsin,verseler dünyaları

Aslında beşinci mevsimdir eylül

Dört mevsimi koynunda barındıran

Sadece hüzün değildir eylülden kalan

Sonbaharda açan farklı bir gül

İşte eylül…', 'Eylül,hüzünlendirir beni her seferinde Neşe dolu yaz mevsiminin bitmesi… Rengarenk ağaçların ayrılık gözyaşı dökmesi… Bir matem rüzgarı eser...', ARRAY['Türk Edebiyatı','Şiir','Halil İbrahim Keçebaş']::text[], 8.5, '{"poet":"Halil İbrahim Keçebaş","poet_slug":"halil-i-brahim-kecebas","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/eylul-91-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşler Yitiyor da', 'dusler-yitiyor-da-hulya-arikan-x8lsi', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kurumuş bir yaprak şimdi kimsesizliğim

Rüzgara kapılıp meçhule yol alan...

Kırılmaya mahkum, yeşili kaybetmiş damarlar

Vakitsiz gelen güz mevsimiydi dalından koparan

Kimbilir belki de  yarını olmayan beklentiler

Düşler yitiyor da… 

Bitmiyor arzular…..

Ufalanmış yüreğim susuyor da

Sönmüyor umutlar...

Bilinmeze yol alan yalnızlığıma yoldaş oluyor hülyalar

07/04/2005', 'Kurumuş bir yaprak şimdi kimsesizliğim Rüzgara kapılıp meçhule yol alan... Kırılmaya mahkum, yeşili kaybetmiş damarlar Vakitsiz gelen güz me...', ARRAY['Türk Edebiyatı','Şiir','Hülya Arıkan']::text[], 8.5, '{"poet":"Hülya Arıkan","poet_slug":"hulya-arikan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/dusler-yitiyor-da-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sürünüyorum', 'surunuyorum-munevver-senol-gdnz1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hiç yüzün gülmesin inşallah, dedin mi bana? 

Gerçekten gülmedim, hep ağlıyorum.

Suçlusu tek benmiyim bilemiyorum.

Bir gün gülsem, üç gün hep ağlıyorum.

Kaderciyim, kadere de inanıyorum.

Geçmişteki hatalara ben yanıyorum.

Birdaha dünyaya gelirsem eğer.

Sana kavuşacağımı var sayıyorum.

İşte bu güçle herşeye katlanıyorum.

İntizar mı ettin doğru söyle, hep ağlıyorum? 

İntizarın tuttu beni, sürünüyorum sürünüyorum', 'Hiç yüzün gülmesin inşallah, dedin mi bana?  Gerçekten gülmedim, hep ağlıyorum. Suçlusu tek benmiyim bilemiyorum. Bir gün gülsem, üç gün hep...', ARRAY['Türk Edebiyatı','Şiir','Münevver Şenol']::text[], 8.5, '{"poet":"Münevver Şenol","poet_slug":"munevver-senol","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/surunuyorum-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adem''le Havva''nın Aşkı', 'adem-le-havva-nin-aski-alper-kuruk-jyf4y', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Adem''le Havva''yı gördüm rüyamda

Ne güzel de sevişiyorlardı,

İlk aşkı gördüm rüyamda.

Sâdeydi,çıplaktı aşkları

Kendi çıplaklıklarınca,

Işık ışıktı gönülleri

Baktım da çıplak gözümle gördüm.

Sıcak sıcak sevişirlerken

Buğday ya da elma ağacının altında

Bir rüzgâr esti hafiften.

Titreyen yapraklarla

Titredi içi Havva''nın

Bu,aşkta ilk korkuydu beliren.

Şeytan rüyamda da buldu onları

Benim rüyalarım zanetmem hiç

Olmaya ki şeytansız olsun.

Ayrılık girdi araya

Hasretin sillesini yedi Adem ve Havva

Böyle oldu ilk aşkta ilk ayrılık

Bir şeytan yıktı,rüyada ilk aşkı

Başladı yine benim rüyalarım

Başladı şeytanlı rüya...', 'Adem''le Havva''yı gördüm rüyamda Ne güzel de sevişiyorlardı, İlk aşkı gördüm rüyamda. Sâdeydi,çıplaktı aşkları Kendi çıplaklıklarınca, Işık ı...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/adem-le-havva-nin-aski-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Suya düşmüş yüzüyor', 'suya-dusmus-yuzuyor-ulas-guleviz-3dxyt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Suya  düşmüş  yüzüyor

yeşil  bir  yaprak

ve  bir  karınca  üzerinde

çırıl  çıplak

Su  duru

Yaprak  yeşil

Karınca  ürkek

gidiyor  bak

savrularak

Karıncayı  düşün  bir  an

Ve  korkusunun  büyüklüğünü

Ve  soruyorum  size

karıncanın  zihninden  geçenleri 

Fark  eder  mi  acaba

Suyun  duru

Yaprağın  yeşil  olduğunu

Ve  fark  eder  mi  sizin  için  bu', 'Suya  düşmüş  yüzüyor yeşil  bir  yaprak ve  bir  karınca  üzerinde çırıl  çıplak Su  duru Yaprak  yeşil Karınca  ürkek gidiyor  bak savrula...', ARRAY['Türk Edebiyatı','Şiir','Ulaş Güleviz']::text[], 8.5, '{"poet":"Ulaş Güleviz","poet_slug":"ulas-guleviz","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/suya-dusmus-yuzuyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söyle', 'soyle-bahriye-koto-iiwin', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Eğer söyleyeceksen sevdiğini; 

Yürektense söyle

Klabin birgün çarparsa; 

Aşkımdansa söyle.

Gözlerin aldatırsa beni başka gözlerle; 

Aldattıgını inkar etmeden söyle; 

Dilin başka yüreğin başka konuşacaksa eğer; 

Vazgeç benden arkadaş; 

Uğraşamam seninle........', 'Eğer söyleyeceksen sevdiğini;  Yürektense söyle Klabin birgün çarparsa;  Aşkımdansa söyle. Gözlerin aldatırsa beni başka gözlerle;  Aldattıg...', ARRAY['Türk Edebiyatı','Şiir','Bahriye Koto']::text[], 8.5, '{"poet":"Bahriye Koto","poet_slug":"bahriye-koto","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/soyle-57-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güller', 'guller-mehmet-sait-akkus-cuo51', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yoruldu güller sana bakmaktan

Eğilipte şöyle koklayı versen

Her sene senin için açmaktan

İnanmazsan dön bak istersen

Sanadır güllerin yolu sanadır

Dönüpte bir bakı verirsen

Umutları hep senden yanadır

Eğilipte şöyle dokunuversen', 'Yoruldu güller sana bakmaktan Eğilipte şöyle koklayı versen Her sene senin için açmaktan İnanmazsan dön bak istersen Sanadır güllerin yolu s...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Sait Akkuş']::text[], 8.5, '{"poet":"Mehmet Sait Akkuş","poet_slug":"mehmet-sait-akkus","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/guller-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Avrupa Birliği Başarımız ! ! !', 'avrupa-birligi-basarimiz-saim-bastik-m19os', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Lütfen biri bana birşey söylesin

Bu; müzakere mi, mütareke mi? 

Ey AB aşığı yalaka basın

Bu; müzakere mi,mütareke mi? 

Karşıda olanlar hepsi de memnun

Bu nasıl başarı sırrı ne bunun? 

Birşey saklamayın doğruca sunun

Bu; müzakere mi, mütareke mi? 

Anlaşma var ortalarda belge yok

Meclis dahil hiç kimseye bilgi yok

Anlaşılan bu işin de sonu ..........

Bu; müzakere mi, mütareke mi? 

Meclisi yok sayıp,kaçıp dışına

Çorap mı ördünüz Türk''ün başına? 

O elçinin partinizde işi ne? 

Bu; müzakere mi, mütareke mi? 

Hani biz Kıbrıs''ta oyun bozandık

Kırk yıldır herşeyi yanlış yazandık

Söyleyin; Kıbrıs''ta neler kazandık? 

Bu; mütareke mi, müzakere mi? 

Serbest dolaşım yok, Türk''ler dışarı

Kıbrıs''tan ordu da kapı dışarı

Aslanım! Tayyibim bu mu başarı? 

Bu; mütareke mi, müzakere mi? 

Ucu açık diyor garantisi yok

Bunu da iyice o kafana sok

Sizde hiç mi akıl,hiç mi iz''an yok? 

Bu; müzakere mi mütareke mi? 

Sen rumları tanı,limanları aç

Soykırım yaptım de,sınırı da aç

GÜL''üm! bu mu bize aldığın ilaç? 

Bu; mütareke mi, müzakere mi? 

Bu başarı Milletindir dediniz

Millete ne kadar bilgi verdiniz

Postu kurtarmak mı sizin derdiniz? 

Bu; mütareke mi, müzakere mi? 

Takke çabuk düştü, kel görünüyor

Bize de sıvanmış kol görünüyor

Size yüce dîvan,yol görünüyor

Bu; mütareke mi,müzakere mi? 

06/10/2005', 'Lütfen biri bana birşey söylesin Bu; müzakere mi, mütareke mi?  Ey AB aşığı yalaka basın Bu; müzakere mi,mütareke mi?  Karşıda olanlar hepsi...', ARRAY['Türk Edebiyatı','Şiir','Saim Bastık']::text[], 8.5, '{"poet":"Saim Bastık","poet_slug":"saim-bastik","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/avrupa-birligi-basarimiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Siz Beni Yok Sayın', 'siz-beni-yok-sayin-muharrem-cetinkaya-47x7n', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'siz beni yok sayın

sonsuz sandığınız

hayatın içinde

şen şakrak yaşayın

bense

gölgesi uzun namlularının

ucunda  tetikte sabahlarken

siz gün batımında

yakamozları seyredin

yatlarda

el ele

rıhtım sefalarında

......

alacakaranlıklarda

ben sizin için 

öleyim

siz beni yok sayın!', 'siz beni yok sayın sonsuz sandığınız hayatın içinde şen şakrak yaşayın bense gölgesi uzun namlularının ucunda  tetikte sabahlarken siz gün b...', ARRAY['Türk Edebiyatı','Şiir','Muharrem Çetinkaya']::text[], 8.5, '{"poet":"Muharrem Çetinkaya","poet_slug":"muharrem-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/siz-beni-yok-sayin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk', 'ask-oguz-yirmibes-hoj48', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bana yakınsın yanı başımda

İçimde bir yerlerdesin ve hatta

Benim özümsün beni ben yapan

Ama uzaksın bir o kadar da

Sanırım sevmiyorsun benim seni sevdiğim kadar

Sen olmayı o kadar çok isterdim ki

Herkes korkuyor senden

Onların varlığını alıp gitmenden

Ve titriyorlar senin ıssızlığında

Tüyler diken diken oluyor kalkıyor ayağa

tıpkı insanlar gibi Seni duyduğunda 

Ürpertiyorsun onları kimi zaman tek bir parça

Kimi zaman param parça

Nedir sendeki asaletin nedeni 

Ve niye bu kadar merak ediyorum ben seni

Herkes kaçarken senden

Nedir kovalamamın sebebi

Ve şimdi soruyorm tekrar

İnat mı bu hayat dedikleri

Başında sen varsın sonunda sen 

Sen olmadan olmaz

Ama bitirende sen

Aşk mı öldürüyor yoksa ölmeye mi aşığım

Bunca aşkın içinde ölmeye mi hasret kaldım', 'Bana yakınsın yanı başımda İçimde bir yerlerdesin ve hatta Benim özümsün beni ben yapan Ama uzaksın bir o kadar da Sanırım sevmiyorsun benim...', ARRAY['Türk Edebiyatı','Şiir','Oğuz Yirmibeş']::text[], 8.5, '{"poet":"Oğuz Yirmibeş","poet_slug":"oguz-yirmibes","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ask-456-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fâilâtun Fâilûn', 'f-il-tun-f-il-n-ayhan-yavuz-acikgoz-y4p1q', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bilmiyorlar nâmüsâit, çerh-i bâtıl câhilûn

Fâ i lâ tun   fâ i lâ tun   fâ i lâ tun   fâ i lûn

(adana-06.10.2005)', 'Bilmiyorlar nâmüsâit, çerh-i bâtıl câhilûn Fâ i lâ tun   fâ i lâ tun   fâ i lâ tun   fâ i lûn (adana-06.10.2005)...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Yavuz Açıkgöz']::text[], 8.5, '{"poet":"Ayhan Yavuz Açıkgöz","poet_slug":"ayhan-yavuz-acikgoz","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/failatun-failun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eski Dostlar', 'eski-dostlar-adem-uzun-67kwj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yollara baktıkça yıllara daldım.

Maziyi düşündüm ve efkarlandım.

Ağladım bu gece, ben çok ağladım,

Yalnızlık gücüme gitmiş olmalı.

Yalnızlığım her gün sürdü artarak.

Uzaktı dostlarım, bana çok uzak.

Şu göğün kırmızı rengine bir bak! 

Bugün de bir dostum yitmiş olmalı.

Siz burdan gideli eğildi başım.

Ne bir dostum kaldı, ne arkadaşım...

Akmıyor işte bak artık gözyaşım! 

O da en sonunda bitmiş olmalı.', 'Yollara baktıkça yıllara daldım. Maziyi düşündüm ve efkarlandım. Ağladım bu gece, ben çok ağladım, Yalnızlık gücüme gitmiş olmalı. Yalnızlığ...', ARRAY['Türk Edebiyatı','Şiir','Adem Uzun']::text[], 8.5, '{"poet":"Adem Uzun","poet_slug":"adem-uzun","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/eski-dostlar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sabahı bekleyen / gerçeğin kırılması...', 'sabahi-bekleyen-gercegin-kirilmasi-zafer-zengin-etnika-3ig9l', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '.

Hatayı dönülmez hale getirip, yasal katliamlar düzenleyen

Övündükleri tahtlarını kaybeden, parayı insandan önce tutan

Katil yüzlerce hayine, çaldıklarınız ömrümüzdür.

Kayıp canım afife ve kayıp kızım ezgi’ye...

.afife

esmer kaşında türkü dilim

koparma gözüm saklı

giremedim yüreğine

toz çığ kondu ciğerine

savanlar kuruluyor yüreğime

afife gitmedim de

.kaçmak ayıp

kuldan geldi

kuldan gitti ölüm

seni dilemiş sevmiştim

ellerimle son dileğe verdim

üstün açık yaz günü

üşüme

.fay

ağustos dilimde erir beterim

yaralı ezgi geçmiş

mezarında can suyu gözlerim

kemik kırılmaz 

can incinmiş

kıskanmış ince kabuk dünya

çatlamış  üstünde gezenlerin derdinden

ilk ses geldi derinden

.yıkım

ne zaman cam  doğrama

beton görsem

köşelerim kopar

kat olurum

suya doymuş toprağa

bir adım basar

silinirim

.söndürün

alın beni

son nefesin olduğu yerde söndürün

dokunmayın

ezip 

çıra yakıp

afife’yi aldı ölüm

ezgim

hatırlamam gözlerini

hiç görmedim

baban uyku şimdi

sabahı bekleyen

.beddua

büyüdüm gülün solduğu gece

ihaneti tükürün yüzünüze

siz de ölün

afife öldüğü gün

ocağımda tütüyor hüzün

elimde dağılıyor

yapamadığım düğün

.düğün

afife 

“evet” son sözüm

.göç

kaçamam bağlıyım

turnalar kadar göçmen

turnalar kadar allıyım

beş para etmez göz yaşım

gittiğiniz yaşta kalmışım

.son arzu

bana ettikleri senden değil

gülüm sensiz dikenim

köreltseler ucumu

yanına gelirim

.tut

diş çıkaran bebemiz

anası afife

sebebim

göğümde kutsadım sizi

gerçek çıplak

sıcak tutun  ellerinizi

.veda

geleceğim

solduğum yerde 

sizle güleceğim

.geçmez

kurdun kuşun vakti

gelip alsalar  eti

az yer kaplar

beklentisizin kemiği

Ağustos 17

Bilindiği halde olanlara ağlama, isyan değil bu, kendi yok oluşunu hazırlama, neden hayin  bu kadar kendine, ekinler için hazırlanmış toprağa ki; binlerce yılı vardır olmaya, neden kurarlar üstüne betonla karton kuleler, öğrendik ki kağıt bile daha sağlam istenilen yerde.

O duyunca haberi gitti. İçini döktüğü bilinmez bir sayfada, bunu okuyan yazanın ağzıyla karıştı şiirin hamuruna. Bir sabah her şey düzelecek

ve güzelleşecek diye bekleyene Sabır dilenir. Hatamız varsa, gerçek ola.

Saygıyla.

.', '. Hatayı dönülmez hale getirip, yasal katliamlar düzenleyen Övündükleri tahtlarını kaybeden, parayı insandan önce tutan Katil yüzlerce hayin...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":92,"source_url":"https://www.antoloji.com/sabahi-bekleyen-gercegin-kirilmasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tedavülden Kalkan Sevda', 'tedavulden-kalkan-sevda-gul-ozan-s8zc5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'sen sevdayı

en eski haliyle biliyorsun

tedavülden kalkan

...

aslında kalkmayacaktı ama

o kadar yolcusu vardı ki

mecburen kalktı

...

aslında tedavülden kalkmayacaktı

başka bir limandan kalkacaktı

ama o liman kapandı

...

senin hafızan...

o fil hafızan...

sevdayı hatırlar mı acaba

gerçekten bir an? ! 

...

tedavülden kalktı sevda

kalkmasaydı da

öyle eskidi ki

tutmazdı yama

...

20-30 yıl sonra

yırtılan yerine bir yapışkan bantla

idare eder gider dedin

...

ama sevda

öyle her dem geçer akçe değilmiş

...

sevda ipek gibi - yama tutmaz

sevda fil gibi - hiç unutmaz

öyle yumuşacık dokunur

öyle acımasız geçer gidermiş

...

fillerin hep aynı yoldan geçtiklerini

fillerin hep aynı sudan içtiklerini

bilir miydin? 

...

ipeğin de bir gün yıprandığını

ipeğin yama tutmadığını

bilir miydin? 

...

bilmezdin

gençtin

ben ne kadar seni kamil sandımsa da

gençtin

al benden de o kadar

...

öğretilmedik

ilk aşka

...

acemiydik

başka! 

bunca uzak benzetmeyle

fillerle ve ipeklerle dolu bir şiir

yazacağımı sanmazdım

ben de...', 'sen sevdayı en eski haliyle biliyorsun tedavülden kalkan ... aslında kalkmayacaktı ama o kadar yolcusu vardı ki mecburen kalktı ... aslında ...', ARRAY['Türk Edebiyatı','Şiir','Gül Ozan']::text[], 8.5, '{"poet":"Gül Ozan","poet_slug":"gul-ozan","theme":"Türk Şiiri","is_hero":false,"total_lines":57,"source_url":"https://www.antoloji.com/tedavulden-kalkan-sevda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lahza', 'lahza-elazigli-mustafa-kaya-nu103', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seni sevdim.

senden bir ışık gelsin

istedim..

gündüzüm geceden,

daha karanlık oldu.

şimdi istanbul’da hayat

sensiz siyah bir lahza …

Mustafa kaya

06.10.2005 / Anadoluhisarı

www.mustafakaya.net', 'Seni sevdim. senden bir ışık gelsin istedim.. gündüzüm geceden, daha karanlık oldu. şimdi istanbul’da hayat sensiz siyah bir lahza … Mustafa...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/lahza-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırdılar', 'kirdilar-osman-taspinar-7hgbq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Eskilerde bir günde

Sağcımısın,solcumusun

diye sordular

Ben anlamam,

Ben anlamam dedikçe

Kafam,gözüm kırdılar

Kafam,gözüm değil benim

Malım,mülküm değil benim

Aşkım,sevdam değil benim

Can dostumu kırdılar.

Bakmadılar feryadıma

Acırlarmı göz yaşıma

Lenin,Mao,Marx adına

Kolum,kanadım kırdılar.

Kolum,kanadım değil benim

Kalbim,yüreğim değil benim

Aşkım sevdalım değil benim

Can dostumu kırdılar.

Haklımıydı,haksızmıydı? 

Bu derece ruhsuzmuydu? 

Düşmandan da farksızmıydı? 

Bu can-ı tenden aldılar.

Bu can bu ten bende değil

Kahrolmamak elde değil

Yüreğimde dilde değil

Can dostumu kırdılar.', 'Eskilerde bir günde Sağcımısın,solcumusun diye sordular Ben anlamam, Ben anlamam dedikçe Kafam,gözüm kırdılar Kafam,gözüm değil benim Malım,...', ARRAY['Türk Edebiyatı','Şiir','Osman Taşpınar']::text[], 8.5, '{"poet":"Osman Taşpınar","poet_slug":"osman-taspinar","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/kirdilar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ustura Kesiği', 'ustura-kesigi-mehmet-caner-sumengen-zzxn6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir ustura kesiği kadar

Sert, derin ve acı verici oldu gidişin...

Saçlarına taktığın o pembe toka gibi

Kolay çıkar sanma yüreğimden bu yara! ...', 'Bir ustura kesiği kadar Sert, derin ve acı verici oldu gidişin... Saçlarına taktığın o pembe toka gibi Kolay çıkar sanma yüreğimden bu yara!...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Caner Sümengen']::text[], 8.5, '{"poet":"Mehmet Caner Sümengen","poet_slug":"mehmet-caner-sumengen","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ustura-kesigi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlayana Sivrisinek', 'anlayana-sivrisinek-ekrem-sama-so45v', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çığlık gibi tizdi, kesiksiz bir siren,

Bu bir ambulanstı, yaralı getiren...

Bir kazazedeymiş, ağırdı yarası,

Kan fışkırtıyordu, iki kaş arası.

Herkesi aldı bir telaş koşuşturma...

-Şu sedyeyi tutun! 

.....................-Doktor çağır, durma! 

-Kanama çok fena! 

............................-Bir kan takviyesi! 

-Kan gurubu nedir? 

..............................-Koştursun birisi! 

-Laborant nerede? 

..............................-Bulunsun çabuk! 

-Durumu ağırmış, benzi de çok soluk.

-Kızım damarına bir anjiyokat tak,

Önce çok acele nabzına da bir bak! 

		***

Dakikalar geçti bulmak için damar,

Damarı bulundu, musluğu taktılar.

Yarım saat sonra geldi aranan kan,

Ter içinde kaldı, kanı kola takan.

Çok geçti adamın yüzü hepten soldu,

Son nefesini de vererek eks oldu.

		***

Dedi ki bilge bir kişi bağırarak; 

-İlkellik bu doktor, mazereti bırak! 

Kan gurubu damar, deyip geçti zaman,

Vakit israfından, ölmüştür bu insan! 

Pike yapıp hemen kılcal bir damarı,

Milim şaşırmadan kanal bulanları,

Uzaktan süzülüp hızlıca uçarken,

Kan guruplarını tespit eden varken,

Hem rahat bir işlem, acıtmaz hiç sizi,

Anında yapılır, lokal anestezi

Teknik gelişmeniz, bu kadarmış demek...

Bil ki sizden daha teknik sivrisinek! 

(istanbul:06.10.2005)', 'Çığlık gibi tizdi, kesiksiz bir siren, Bu bir ambulanstı, yaralı getiren... Bir kazazedeymiş, ağırdı yarası, Kan fışkırtıyordu, iki kaş aras...', ARRAY['Türk Edebiyatı','Şiir','Ekrem Şama']::text[], 8.5, '{"poet":"Ekrem Şama","poet_slug":"ekrem-sama","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/anlayana-sivrisinek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizlik', 'sensizlik-derya-aslan-imbvs', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yine geceler sessiz yüreğim gibi

Yine yağmurlar yağar gözlerim gibi

Neden seni beklerim sevdalı gibi

Oysa mevsim kışa döndü sen gelmedin

.................................................................', 'Yine geceler sessiz yüreğim gibi Yine yağmurlar yağar gözlerim gibi Neden seni beklerim sevdalı gibi Oysa mevsim kışa döndü sen gelmedin ......', ARRAY['Türk Edebiyatı','Şiir','Derya Aslan']::text[], 8.5, '{"poet":"Derya Aslan","poet_slug":"derya-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sensizlik-211-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yolcu', 'yolcu-derya-aslan-pqhq2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kayıp kentin yolcusuyum bu cihan-ı alemde

Gözlerim Nil nehri gibi taşar da durulmaz.

Bedenim yorgun viran sokaklarda pervane

Kaçar dururum yanlızlık peşimi bırakmaz

...................................

............................................', 'Kayıp kentin yolcusuyum bu cihan-ı alemde Gözlerim Nil nehri gibi taşar da durulmaz. Bedenim yorgun viran sokaklarda pervane Kaçar dururum y...', ARRAY['Türk Edebiyatı','Şiir','Derya Aslan']::text[], 8.5, '{"poet":"Derya Aslan","poet_slug":"derya-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yolcu-88-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönüller Pasını Attı...', 'gonuller-pasini-atti-dursun-elmas-nl36u', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Müjde olsun dağa taşa

Ayların sultanı geldi.

Selâm salın kurda kuşa

Ayların sultanı geldi.

Hemen ilk gün belli oldu

Canlı cansız hayat buldu

Haneye bereket doldu

Ayların sultanı geldi.

Göklerin rahmeti arttı

Sofralara lezzet kattı.

Gönüller pasını attı

Ayların sultanı geldi....', 'Müjde olsun dağa taşa Ayların sultanı geldi. Selâm salın kurda kuşa Ayların sultanı geldi. Hemen ilk gün belli oldu Canlı cansız hayat buldu...', ARRAY['Türk Edebiyatı','Şiir','Dursun Elmas']::text[], 8.5, '{"poet":"Dursun Elmas","poet_slug":"dursun-elmas","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gonuller-pasini-atti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünyada Kaldılar', 'dunyada-kaldilar-abdullah-yasar-erdogan-g1me0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dünyalık adına zengin sayılan,

Bir zevat ölmüştü.

Baktım sırtında sadece kefeni var.

Yanına sevdiği mallardan koyun dedim.

Bir kat, bir yat, bir araba,

Neden? Lazım olmazmış adam.

O değil miydi onları kazanan,

Bırakında servetinden götürsün.

Yada sevdiği insanları yanına koyun.

Hani çok severdi oğlunu, kızını? 

Onu da koysak mı ki yanına? 

Karısını, arabasını, köpeğini de severdi.

Neden sevdiklerini vermiyorsunuz ki? 

Kazanırken sizler mi kazandınız? 

Ya adam özlerse bir de mallarını? 

Siz mi vereceksiniz hesabını? 

Ne kadar sevdiği şey varsa; 

Koyun mezara gitsin.

Adam, onlar için bir ömür harcadı.

Bu nedenle Hakk’ı hiç anmadı,

Beni biri azarladı, fırçaladı:

“De bre mecnun git işine” dedi.

Beni deli sandı, ama ben deli değildim.

“Kişi sevdikleri ile beraberdir” dedim.

Varsın sevdikleri ile mezarda bir olsun,

Orada sorular sorulurken,

Dünyada kalan mallarını saysın.

Yine azarladılar beni.

Çünkü adamı tanırdım az çok; 

Dünya malı için çok canlar yakmıştı.

Adamı bir metre toprağın altına gömdüler,

Sonra evlatları göz yaşı içinde gitti.

Daha bedeni soğumadan,

Evlatları mal derdine düştü.

İşte dünyalıkların akıbeti, 

Adamsa  iki cihanını mahvetti.', 'Dünyalık adına zengin sayılan, Bir zevat ölmüştü. Baktım sırtında sadece kefeni var. Yanına sevdiği mallardan koyun dedim. Bir kat, bir yat,...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Yaşar Erdoğan']::text[], 8.5, '{"poet":"Abdullah Yaşar Erdoğan","poet_slug":"abdullah-yasar-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/dunyada-kaldilar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekliyoruz', 'bekliyoruz-abdullah-yasar-erdogan-hwpcw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Duymuyor bu insanlar.

Görmüyor, körelmiş gözler.

Secdeye değmez alınlar,

Bir nefes, bir nefes Yarabbim.

Muhammed’im Önderim benim.

Sokaklar irinle leşle dolmuş,

Kadınlar anadan üryan olmuş,

İzzet, irfan, ar, namus kaybolmuş,

Bir nefes, bir nefes Yarabbim.

Muhammed’im Önderim benim.

Her taraf Ebû Leheb’in elinde,

Bazılarında dava sadece dilde,

İman aşkı kalmamış gönüllerde,

Bir nefes, bir nefes Yarabbim.

Muhammed’im Önderim benim.

Her taşın altın bir Bilal yatıyor, 

Müslüman’ın sakalı göze batıyor,

Mazlumlar Hz. Ebubekir bekliyor,

Bir nefes, bir nefes Yarabbim.

Muhammed’im Önderim benim.

Ebubekir, Ömer, Osman, Ali; 

Bekliyoruz kurtaracak bir eli.

Rabbim kahreyle  Ebu Lehebi.

Bir nefes, bir nefes Yarabbim.

Muhammed’im Önderim benim.', 'Duymuyor bu insanlar. Görmüyor, körelmiş gözler. Secdeye değmez alınlar, Bir nefes, bir nefes Yarabbim. Muhammed’im Önderim benim. Sokaklar ...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Yaşar Erdoğan']::text[], 8.5, '{"poet":"Abdullah Yaşar Erdoğan","poet_slug":"abdullah-yasar-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/bekliyoruz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dileğim', 'dilegim-abdullah-yasar-erdogan-wyt9d', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kurumuş dudağını ıslatan su olsam,

Kusva’nın üzerindeki semer olsam,

Hira’da bir taş, kumda ben olsam,

Seni görmekten başka dileğim yok.

Yakıyor içimi Ahmed’imin sevgisi.

Gelmedi, gelmeyecek O’nun gibisi,

Bu dava beden değil, yürek derbisi,

Seni görmekten başka dileğim yok.

Ahmed’im ayak izini sevseydim,

Medine’de bir toz olabilseydim,

Çok uzak ta olsa görebilseydim,

Seni görmekten başka dileğim yok.', 'Kurumuş dudağını ıslatan su olsam, Kusva’nın üzerindeki semer olsam, Hira’da bir taş, kumda ben olsam, Seni görmekten başka dileğim yok. Yak...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Yaşar Erdoğan']::text[], 8.5, '{"poet":"Abdullah Yaşar Erdoğan","poet_slug":"abdullah-yasar-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/dilegim-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Büyük Yalan', 'buyuk-yalan-hasan-cam-igxl6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gerçek kimliğim, kişiliğim var benim

İşte ben, benim, bu da atalarımdan asaletim

Bir sevgi, bir aşk coğrafyası yaşadım sende

Hiç yalansız, yıkılan tüm sevgim, şefkatimle

Aşmadım sınırlarımı, sana olan sevgimde 

Yaşadığım yurdumda, ibadetimle, dinimde

Ama sen 

Yine büyük yalanla döndün, sahte kişiliğinle

İnkar ettin aslını, yaşadığım sensiz ahretimde

Hakaret saydın bana, gerçek olan doğrularımı

Yakışmadı, başka kapıdan gereksiz haykırman

Bari sus, fikrin neyse zikrinde o, kalsın sende

Biz iki yan bahçenin cevizleri dallarımız iç içe

Hüsrana uğradım hala değişmeyişine, sustum

Susacağımda, sanma bundan sonra sözüm sana 

Sen bu gün değil, masanda ellerimi tuttuğunda 

Gözlerime bakarak, yalanlarla sevdanı kurdun

Ne dualarım, nede bedduam, artık bulmaz seni 

Ben yaşayan canlı mazi, küllenmiş sevdalınım

Ama sen 

Yine büyük yalanla döndün, başka adreslerden 

Tanrı misafiri oynadın, yabancıyım gibilerden

Gerek yoktu aynı hataları, yine yeşertmekten 

Senin kokun belli, rüzgar getirir yön dönmeden

Sürgünüm diye bilirdin, bilirim geldin hangi elden

Susuyorum yine ben, ilk ve son sevgimde senden

06 10 2005

Ümraniye İstanbul', 'Gerçek kimliğim, kişiliğim var benim İşte ben, benim, bu da atalarımdan asaletim Bir sevgi, bir aşk coğrafyası yaşadım sende Hiç yalansız, y...', ARRAY['Türk Edebiyatı','Şiir','Hasan Çam']::text[], 8.5, '{"poet":"Hasan Çam","poet_slug":"hasan-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/buyuk-yalan-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Baba! ..', 'baba-ugur-yeniler-uumg6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'BABA! ...

Dünyanın düzeni çoktan değişti 

Çalanlar çırpanlar bey oldu baba! ...

Ar namus kalmadı,suç değil zina

Nankörlük insanda huy oldu baba! ..

*

Unuttu çoğu, giydiği çarığı

Yağmurlar kapattı birçok yarığı

Kilise keşişi giymiş sarığı

Devşirme artıklar soy oldu baba! ..

*

Kardeşi, kardeşe kırdırır düşman

Onca canlar verdik olmadık pişman

Ezilen zayıftır ezense şişman

Köşe başları hep pay oldu baba! ..

* 

Çiftçinin elinde kaldı yabası

Efendinin şimdi yanmaz sobası 

Göçe zorlandı on çocuk babası

Kentte varoşlarda oy oldu baba! ..

*

İşçinin, memurun hali çok beter

Bordroyu almadan maaşlar biter

Ay başı gelince bizi  kim tutar

Maaşlı kaçmaktan tay oldu baba! ..

*

Fakir ot toplayıp yiyor yayladan

Et gıdası gelir  komşu Leyla’dan

Gözümüz doydu İstanbul Layla’dan

Yemeğimiz simit çay oldu baba! ..

*

Çağ atladık sen öldükten buyana

Medeni olduk boyana boyana

Küpeyi takan o yana bu yana

Gece bayan gündüz bay oldu baba! ..

*

Okula yolladık oğlanı kızı

Kayboldu sokakta bulunmaz izi

Bu gençlerin hali içimde sızı

Kurtlar sofrasına mey oldu baba! ..

*

Uğur oğlun için sözün vasiyet

Bıraktığın gibi hala  vaziyet

Soyundan  eksilmez, asla haysiyet

Sözlerim ok! .. dilim, yay oldu baba! ...

Uğur Yeniler/Eskişehir', 'BABA! ... Dünyanın düzeni çoktan değişti  Çalanlar çırpanlar bey oldu baba! ... Ar namus kalmadı,suç değil zina Nankörlük insanda huy oldu b...', ARRAY['Türk Edebiyatı','Şiir','Uğur Yeniler']::text[], 8.5, '{"poet":"Uğur Yeniler","poet_slug":"ugur-yeniler","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/baba-47-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ümmet', 'ummet-abdullah-yasar-erdogan-s19we', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne oldu sana ey Muhammed yolcusu? 

Üzerimize gelmekte dünya çapulcusu,

Bu işin olmaz asla sağcısı, solcusu,

Ayağa kalk, kalk ey cennetlik Ümmet.

Afyon içirmişler sanki bedenine,

Ezilmiş dünyanın her metresinde,

İhtiyacı var, muhtacız bir mürşide,

Sürü çobansız, dağınık  Ümmet.

Korkma, kalk ayağa, gürle meydanda.

Senin kadar var mı ezilen, şu dünyada,

Eser kalmadı, yedi düveldeki namında,

Derin bir uykuya yatmış, garip Ümmet.

Asırlar var, ezilmedin ezmedin de,

Son asırdır, neden başın hep önde? 

Olmalı, olacak cihat aşkı kalbinde,

Ayağa kalk, kalk ey  Ümmet.

Yönü değişmeli, sana gelen bu selin.

Mazluma kalkmaz, senin dualı elin,

Susmasın artık, ne olur mübarek dilin.

Bari, kalben buğz eyle ey Ümmet.

Yaşayan ölü gibi,  olma sakın pısırık,

Dünya zalimleri, Ümmet için barışık,

Bak çevrene, din kardeşlerin karışık,

Ayağa kalk, kalk ey cennetlik Ümmet.

Susmak sermaye değil, icraat eyle,

Bu dava çok büyüdü iman ateşiyle,

İnsan düşman olur mu hiç kardeşiyle,

Ayağa kalk, kalk ey cennetlik Ümmet.', 'Ne oldu sana ey Muhammed yolcusu?  Üzerimize gelmekte dünya çapulcusu, Bu işin olmaz asla sağcısı, solcusu, Ayağa kalk, kalk ey cennetlik Üm...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Yaşar Erdoğan']::text[], 8.5, '{"poet":"Abdullah Yaşar Erdoğan","poet_slug":"abdullah-yasar-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/ummet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mü''min', 'mu-min-abdullah-yasar-erdogan-0hv2x', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Mü’min; zulme rıza göstermez.

Mü’min; zulüm nedir  bilmez.

Mü’min; küffârı dost edinmez.

Mü’min; Hakk yolun bekçisidir.

Mü’min; İbadeti hep şiar edinir.

Mü’min; Muhammed’i lider bilir.

Mü’min; Dava uğrunu canını verir.

Mü’min; Hakk yolun hizmetçisidir.

Mü’min; dünyalık peşinde koşmaz.

Mü’min; malayani işlerle uğraşmaz.

Mü’min; sevdasın direm şaşırmaz.

Mü’min; Hakk yolun bekçisidir.

Mü’min; hak-hukuk sevdasındadır.

Mü’min; dava kardeşinin yanındadır.

Mü’min; helal-haram dairesindedir.

Mü’min; Hakk yolun hizmetçisidir.

Mü’min; davasını çok iyi bilendir.

Mü’min; sevdası uğrunda ölendir.

Mü’min; her  haliyle bir güvendir.

Mü’min; Hakk yolun  bekçisidir.

Mü’min; gıybet-dedikodu asla bilmez.

Mü’min; başkasının malına göz dikmez.

Mü’min; küffâr zulmüne boyun eğmez.

Mü’min; Hakk yolun hizmetçisidir.

Mü’min; Hakk yolu için yanar gönlü,

Mü’min; ibadet etmekle geçer günü.

Mü’min; her zaman doğruluktur sözü.

Mü’min; Hakk yolun bekçisidir. 

Mü’min; acizdir bilir, teslim olur.

Mü’min; her daim Allah’a kul olur.

Mü’min; gelecek nesle köprü olur.

Mü’min; Hakk yolun hizmetçisidir.

Mü’min; Allah’tan gayrisinden korkmaz.

Mü’min; helal bilirde, harama bakmaz.

Mü’min; topluluk arasına nifak sokmaz.

Mü’min; Hakk yolun bekçisidir.

Mü’min; bir tuğladır, naldır görevini bilir.

Mü’min; kalbindeki  dünyalık nefsini siler.

Mü’min; yerinde saymaz, hep ileri gider.

Mü’min; Hakk yolun hizmetçisidir.

Mü’min; kalbini kapatır dünya zevklerine.

Mü’min; her daim saygılı olur büyüklerine.

Mü’min; şefkatte kusur etmez küçüklerine.

Mü’min; Hakk yolun hizmetçisidir.', 'Mü’min; zulme rıza göstermez. Mü’min; zulüm nedir  bilmez. Mü’min; küffârı dost edinmez. Mü’min; Hakk yolun bekçisidir. Mü’min; İbadeti hep ...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Yaşar Erdoğan']::text[], 8.5, '{"poet":"Abdullah Yaşar Erdoğan","poet_slug":"abdullah-yasar-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/mu-min-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sağlam Olmalı', 'saglam-olmali-abdullah-yasar-erdogan-x8rcd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ters dönecek, iman tahtası,

Engelli gelir, gönül yaylası,

İnsan ayakta duracaksa,

Çok sağlam olmalı davası.

Hüzne kapılan kalp ziyandadır.

Âhiretin azığı bu dünyadadır.

Günü gün edene de bir sormalı.

Ne kazandı, ne kazanmaktadır? 

Yolların yolu hep birdir,

Gider Mevla’ya, Mevla’ya. 

İnsanı çukura götüren kirdir,

Bağlanmışsa candan dünyaya.

Sağlam olmalı, insan sevdada,

Küffara baş eğilmez bu davada,

Ettimse ben ettim yoktur,

Her zerrenin hesabı var orada.', 'Ters dönecek, iman tahtası, Engelli gelir, gönül yaylası, İnsan ayakta duracaksa, Çok sağlam olmalı davası. Hüzne kapılan kalp ziyandadır. Â...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Yaşar Erdoğan']::text[], 8.5, '{"poet":"Abdullah Yaşar Erdoğan","poet_slug":"abdullah-yasar-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/saglam-olmali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tophane', 'tophane-oguz-yirmibes-wzvrd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İçime bir yalnızlık doğdu bu öğlen

Hiç olmadığım kadar tekim

Tophane hiç olmadığı kadar tekin

Yalnızım tek başıma

Beni dinleyen kendim 

Anlatan kendim

Derken bir soru uyandı içimde 

Soru işareti gördüğü her şeyi takıp götürrmekte

Israrlıydı oldukça 

Bende yenilmek üzere 

Ve artık çaresizliğimi kabulenmekte

Susuz kalmak gibi bir şeydi bu benim için

Sanırım bu sefer dayatmaları kabullenecektim

Dünyanın guzelliğini umursamadan

Senin yüzünü anımsayamadan 

Çekip gidecektim

Ama kabullenemedi bunu ruhum

Her şeye rağmen devam edecek

Yalnızlığı benimseyecektim

Belki ağlayarak belki uyuyamayarak

Haykıracaktım senin adını

Gördüğüm her ağaca tekrar tekrar

Haykıracaktım ki seni gördüğünde bana haber versin 

Koşup geleyim

Soluduğun havayı bastığın toprağı ayak izini 

Ve belki yere düşmüş bir tel saçını görüp

Seni nekadar çok sevdiğimi 

Ölümün gereksizliğini hatırlayıp 

O kurtulamadığım uykusuz gecelere bu sefer 

Gülümseyerek girebileyim', 'İçime bir yalnızlık doğdu bu öğlen Hiç olmadığım kadar tekim Tophane hiç olmadığı kadar tekin Yalnızım tek başıma Beni dinleyen kendim  Anla...', ARRAY['Türk Edebiyatı','Şiir','Oğuz Yirmibeş']::text[], 8.5, '{"poet":"Oğuz Yirmibeş","poet_slug":"oguz-yirmibes","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/tophane-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acaba..?', 'acaba-dilek-egri-l67mn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'eli; evin ziline basmaya hasret

yüzü bebeğine, eşine, güneşe.....

göreceğime bu günleri

yer yarılsaydı da içine girseydim diye söylemişmiydi acaba 

maden işçileri.....................................?', 'eli; evin ziline basmaya hasret yüzü bebeğine, eşine, güneşe..... göreceğime bu günleri yer yarılsaydı da içine girseydim diye söylemişmiydi...', ARRAY['Türk Edebiyatı','Şiir','Dilek Eğri']::text[], 8.5, '{"poet":"Dilek Eğri","poet_slug":"dilek-egri","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/acaba-48-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sattım', 'sattim-serkan-karabulut-6e2f5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kurulup baş köşeye şaşkın

Kendini sanmış efendi

Otur efendi otur

Sonraki gelenler ayakta durmasın otursun 

Yer önemi yok kucak kucağa

Açık dükkan bakma yazsa da kapalıyız

Has adımı olmuş itin çakalın

Oysa piyon e malum yürüyecek

Satranç misali varınca hedefe olur mu olur vezir

Düzeni dünyanın dibine vurayım

Parası varsa fark etmez 

Başlıyor var mı artıran satıyorum

Satıyorum

Sattım…', 'Kurulup baş köşeye şaşkın Kendini sanmış efendi Otur efendi otur Sonraki gelenler ayakta durmasın otursun  Yer önemi yok kucak kucağa Açık d...', ARRAY['Türk Edebiyatı','Şiir','Serkan Karabulut']::text[], 8.5, '{"poet":"Serkan Karabulut","poet_slug":"serkan-karabulut","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sattim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Engelli', 'engelli-serkan-karabulut-z75do', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'maktulü nasıl bilirdiniz? ? 

İYİ mi? 

katili kimmiş? 

- şşşşhh..

maktul engeli imiş 

- aaaa! ! ! 

kim demiş? 

-şşşşhh ölmeden öğrenmiş...

kime demiş? 

-Azrail e 

hadi be! ! ! !', 'maktulü nasıl bilirdiniz? ?  İYİ mi?  katili kimmiş?  - şşşşhh.. maktul engeli imiş  - aaaa! ! !  kim demiş?  -şşşşhh ölmeden öğrenmiş... ki...', ARRAY['Türk Edebiyatı','Şiir','Serkan Karabulut']::text[], 8.5, '{"poet":"Serkan Karabulut","poet_slug":"serkan-karabulut","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/engelli-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüznün Rengi', 'huznun-rengi-serkan-karabulut-rydzv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'hüznün siyahsa rengi

çayım demli; siyah. 

içmeye dost,dedim 

buyur', 'hüznün siyahsa rengi çayım demli; siyah.  içmeye dost,dedim  buyur...', ARRAY['Türk Edebiyatı','Şiir','Serkan Karabulut']::text[], 8.5, '{"poet":"Serkan Karabulut","poet_slug":"serkan-karabulut","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/huznun-rengi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nüg Ket Rib', 'nug-ket-rib-sair-babili-52z93', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ellerimin tamamen boş

Gözlerimin baygın olduğu

İçimden 

Ta içimden bir sesin olduğu

Sigaramda biliyor sanki

Bir türlü sönmüyor

Bulutlar gibi dumanı 

Sonsuz

Alnımın üzerinde

Bitmiyor

Bir tek gün var biliyorum

Ve bunu bildiğim için

Şafak sökerken

Her gün 

Biraz daha ölüyorum', 'Ellerimin tamamen boş Gözlerimin baygın olduğu İçimden  Ta içimden bir sesin olduğu Sigaramda biliyor sanki Bir türlü sönmüyor Bulutlar gibi...', ARRAY['Türk Edebiyatı','Şiir','Şair Babili']::text[], 8.5, '{"poet":"Şair Babili","poet_slug":"sair-babili","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/nug-ket-rib-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel! ...', 'gel-ugur-yeniler-xshsg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'GEL! ..

Beni bu dertlere salan sensin yar! ...

Çırpınan yüreğim, yorulmadan gel

Bitmedi mi hasret; yarim nerdesin? 

Kahredip yaşama darılmadan gel! ..

*

Seviyorsan hayır, deme çağrıma

Bak Allah aşkına! .. yanan bağrıma

Başka çare var mı  gönül ağrıma? 

Çaresiz dertlere, karılmadan gel! ....

*

Her gece içkiye sarıldım durdum

Çöllerden çöllere savruldum durdum

Öyle bir yandım ki  kavruldum durdum

Sevgiler içimde kor olmadan gel! ..

*

Kar yağmış dağlara, döndürdün başı

İçimde tükendi,  bitti göz yaşı

Bu gamı çekemez,   her sabır taşı

Ne olur çatlayıp kırılmadan gel! ...

*

Kalbime çektirme,gönül suçunu

Dünyaya değişmem; bir tel saçını 

Aşkına toplatma, erken göçünü 

Uğur’un tabuta,sarılmadan gel! ....', 'GEL! .. Beni bu dertlere salan sensin yar! ... Çırpınan yüreğim, yorulmadan gel Bitmedi mi hasret; yarim nerdesin?  Kahredip yaşama darılmad...', ARRAY['Türk Edebiyatı','Şiir','Uğur Yeniler']::text[], 8.5, '{"poet":"Uğur Yeniler","poet_slug":"ugur-yeniler","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/gel-211-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biz Ayrılalı', 'biz-ayrilali-celal-topo-x4mvl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Daha kaç gün oldu biz ayrılalı

Sanki aradan yıllar geçmiş gibi

Gönlüm hiç ayık değil hep sarhoş

Özlemi yudum yudum içmiş gibi....

İçimi yakan bu sıcaklık nedir

Gözümden gönlüme akan yaş mıdır

Her gören dost bana sabret der

Taşıdığım yürek değil de taş mıdır....

ANTALYA', 'Daha kaç gün oldu biz ayrılalı Sanki aradan yıllar geçmiş gibi Gönlüm hiç ayık değil hep sarhoş Özlemi yudum yudum içmiş gibi.... İçimi yaka...', ARRAY['Türk Edebiyatı','Şiir','Celal Topo']::text[], 8.5, '{"poet":"Celal Topo","poet_slug":"celal-topo","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/biz-ayrilali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vasıfsız Sevgililer', 'vasifsiz-sevgililer-serkan-karabulut-nqv2i', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aşk unutuldu.

Eskidi mazi oldu.

Hiç dengi yok,

Ritmi şaşmış biraz.

Geçmişi yok

Bugünü yok

Geleceği yok

Aşk bilinmezlikte ilişkilerde.

Şimdi ortalıkta cirit atıyor; 

Vasıfsız sevgililer', 'Aşk unutuldu. Eskidi mazi oldu. Hiç dengi yok, Ritmi şaşmış biraz. Geçmişi yok Bugünü yok Geleceği yok Aşk bilinmezlikte ilişkilerde. Şimdi ...', ARRAY['Türk Edebiyatı','Şiir','Serkan Karabulut']::text[], 8.5, '{"poet":"Serkan Karabulut","poet_slug":"serkan-karabulut","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/vasifsiz-sevgililer-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostluk Bize Irak...', 'dostluk-bize-irak-muharrem-cetinkaya-mot4b', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ne biçim komşu bunlar

birinin gözü malımızda

birinin canımızda

komşunun komşusu var bir de

o bizim evimizde

oturmuş camımızda', 'ne biçim komşu bunlar birinin gözü malımızda birinin canımızda komşunun komşusu var bir de o bizim evimizde oturmuş camımızda...', ARRAY['Türk Edebiyatı','Şiir','Muharrem Çetinkaya']::text[], 8.5, '{"poet":"Muharrem Çetinkaya","poet_slug":"muharrem-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/dostluk-bize-irak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yoksun', 'yoksun-ozgur-kokturk-h01zy', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Zaman değildi seni alan

Götüren ayrılık değil

Rüzgâr değildi savuran uzaklara

Yakıp kavuran güneş değil

Titreyişlerde gecemin ufku

Gelen sevda değil, özlem değil

Başıboş geçiyor gün zerreleri

Ömür hem yalan hem sebil

Gözlerim ecel akşamı...

Bilmiyorum kim çaldı düşlerimden

Hangi lânet iklimdi koparan ellerini ellerimden

Hangi kahrolası çığlıkla doldu kahrolası kulaklar

Kimin eline ne geçti sen gidince

Kim ne kazandı yokluğunda

Kimi güldürür ağlayışlar

Küfürlerden kim medet umar

Hangi umut, hangi umutsuzluğu boğar

Hangi çaresizlik, hangi umara doğar

Ağlıyorum boş bakışlarla

Neye yarar...

Uykularım seni sayıklar

Ve yalnızlık saatim

Ve isyan duruşum

Ve çaresizliğe bağlanmışlığı ellerimin 

Ve durgunluğum 

Ve yokluğun 

Ve yokluğunda yokluğum...

Sen yoksun 

Ben hâlâ aynı tütünü çekiyorum

Sen yoksun

Ben hâlâ aynı şarkıyı dinliyorum

Sen yoksun

Ve ben hâlâ aynı seni özlüyorum...

Sen yoksun...

Sen...

Yoksun...

Yok...', 'Zaman değildi seni alan Götüren ayrılık değil Rüzgâr değildi savuran uzaklara Yakıp kavuran güneş değil Titreyişlerde gecemin ufku Gelen sev...', ARRAY['Türk Edebiyatı','Şiir','Özgür Köktürk']::text[], 8.5, '{"poet":"Özgür Köktürk","poet_slug":"ozgur-kokturk","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/yoksun-115-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nazlı Sevdiğim', 'nazli-sevdigim-ugur-yeniler-ol75t', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'NAZLI SEVDİĞİM! ..

Ne yaptım da sana, bana küsersin

Başkasına gönül verdiğim mi var? 

Sam yelleri gibi, kızgın esersin

Ömrümü yoluna serdiğim mi var? 

Hasretten yanmışım, düşmüşüm derde

Artık gözlerime, çekmişim perde

Sen varsın dünyada, baktığım yerde

Benim senden başka, gördüğüm mü var? 

*

Cihana sor var mı, giren köşküne? 

Ben senin aşkınla, döndüm şaşkına

Günahıma girme, Allah aşkına! ...

Başkasına gönül, verdiğim mi var?', 'NAZLI SEVDİĞİM! .. Ne yaptım da sana, bana küsersin Başkasına gönül verdiğim mi var?  Sam yelleri gibi, kızgın esersin Ömrümü yoluna serdiği...', ARRAY['Türk Edebiyatı','Şiir','Uğur Yeniler']::text[], 8.5, '{"poet":"Uğur Yeniler","poet_slug":"ugur-yeniler","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/nazli-sevdigim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman şaşırtmacası', 'zaman-sasirtmacasi-berrak-su-sm85j', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ansızın mı! 

Hayır; 

Doğru zamanlamaydı,

Gelişine hazırlıksızdık sadece.

Öyle sere serpe oturmuş,

Düşler uçuruyorduk...

Berrak Su', 'Ansızın mı!  Hayır;  Doğru zamanlamaydı, Gelişine hazırlıksızdık sadece. Öyle sere serpe oturmuş, Düşler uçuruyorduk... Berrak Su...', ARRAY['Türk Edebiyatı','Şiir','Berrak Su']::text[], 8.5, '{"poet":"Berrak Su","poet_slug":"berrak-su","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/zaman-sasirtmacasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşe dönersin', 'duse-donersin-ugur-yeniler-9fwx3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'DÜŞE DÖNERSİN! .

Dolu dizgin koşan, taylar gibisin

Güldür güldür akan, çaylar gibisin

Sen şimdi baharda, aylar gibisin

Geçer o mevsimler, kışa dönersin! ..

*

Hep dümdüz değildi,r çıktığın yollar

Neler çalar neler,  şu zalim yıllar

Tutmaz olur dizler, yorulur kollar

Kanatları kırık, kuşa dönersin! ..

*

Can verdiğim canan, bakmaz sözüne

Gün gelir bir tokat, yersin yüzüne

Acılar içinden, taşar gözüne

Yağmurda ıslanan, taşa dönersin! ..

*

İçimde çıkarsa, kanayan çıban

Çare bulamazsın, yarılır taban

Derman sultan olur, sen ise çoban

Uykunda gördüğün, düşe dönersin! ..', 'DÜŞE DÖNERSİN! . Dolu dizgin koşan, taylar gibisin Güldür güldür akan, çaylar gibisin Sen şimdi baharda, aylar gibisin Geçer o mevsimler, kı...', ARRAY['Türk Edebiyatı','Şiir','Uğur Yeniler']::text[], 8.5, '{"poet":"Uğur Yeniler","poet_slug":"ugur-yeniler","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/duse-donersin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlerliyorum', 'i-lerliyorum-asya-yildiz-kqdq8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İlerliyorum... 

Erişemediğim hayalin 

Takılmış gözbebeklerime,

Özlemine vurgun ilerliyorum.

Bu özleme benim sevdam belki de, 

Vazgeçemediğim özlemin, doyumsuzluğum. 

Adımlarım ağırlaşır oldu 

Yol aldıkça çaresizliğinde. 

Dayanamamanın verdiği acıyı 

Hissetmez oldu yüreğim. 

Bir ikinci ben çıktı ortaya 

çarptı duvara olanca hışmıyla... 

Kıyamadı yıkılmışlığına belli, 

Minik damlacıklar simasında kıvranıyor. 

Nafile... 

Binlerce parçaya bölündü yüreğim 

Çarpınca duvara 

Ve binlerce kat daha arttı ıstırabım. 

İsyanım... İşte buna.

Gecenin kör karanlığının cazibesine 

Aşık oldum özleminin koluna girerek. 

Başımı yasladım omzuna, 

Gözlerimi yumarak. 

Bir umudun varolduğunu ispatlarcasına 

Göz kırpan yıldızları görmemek için 

Yumdum gözlerimi. 

Özleminin sıcaklığında tenini hissettim. 

Tırnaklarım battı avuçlarıma, 

İnan, 

Yine de açmadım gözlerimi.

Hala ilerliyorum...

Özleminin yükselişine gem vuramaz oldum; 

Kendimi tanıyamaz oldum. 

Bir derbeder oldum, 

Özleminin koluna girmişim, 

Durmadan ilerliyorum...', 'İlerliyorum...  Erişemediğim hayalin  Takılmış gözbebeklerime, Özlemine vurgun ilerliyorum. Bu özleme benim sevdam belki de,  Vazgeçemediğim...', ARRAY['Türk Edebiyatı','Şiir','Asya Yıldız']::text[], 8.5, '{"poet":"Asya Yıldız","poet_slug":"asya-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/ilerliyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsyankar', 'i-syankar-asya-yildiz-qxzwk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hayır, böyle olmasını ben istemedim,

Bırak hapsettiğin tüm hislerini. 

Prangaları, kelepçeleri çöz. 

Zaten çevrendeki o maskeli yüzlerin 

Gardiyanlıkları seni gereğinden fazla bağlıyor. 

İşkence çektirme kendine,

Çöz bağlarını… 

Bir şans ver kendine,

Etrafına çizdiğin o çemberin 

Dışına bir adım at. 

Yo, hayır; adım kafi değil. 

Sıçra, çık dışarı. 

Aç o yumduğun gözlerini; 

Ürkme, herkes senin gibi dışarıda da. 

Evet biraz daha bencil, biraz daha riyakar.

Oysa elbet vardır faziletleri de; 

Sen, yeter ki görmek iste.

Biliyorsun, 

insanoğlu ancak görmek istediğini görüyor. 

Yaşamından hep memnun ol, yaşadıklarından. 

Sonuçta, kendi isteklerini gerçekleştir hep. 

Diğer insanlar olarak nitelendirdiğin şahısların 

Görüşlerine göre hayatını düzenleme. 

O zaman, hayat, senin hayatın olmaktan ziyade 

“diğer insanların hayatı” olur. 

Sen yoksun o zaman. 

Sen cesetsin, bir kadavra, bir leş. 

O kadarsın işte! …

Yumduğun gözlerini açtığında 

Farkedeceğin parlak ışıkların görünüşlerine aldanma. 

Hangisinin güneş, 

Hangisinin yıldız olduğunu başta anlayamazsın. 

İncelemelisin, irdelemelisin. 

Bir çok yıldızdan biri olmamaya çalış. 

Sen güneş olmalısın. 

Diğerleri senden yararlanmalılar. 

Bırak yararlansınlar, kendini kullanılmış hissetme. 

Düşün, üstünsün; 

Üstünsün ki senden faydalanıyorlar. 

Kendi değerini bil, zekanı kullan. 

Kimsenin sana yaklaşmasına izin verme. 

İnsanoğlu belki Midas gibi her dokunduğunu 

Salt altına dönüştürmüyor 

Lakin çirkefleştirmeye kafi. 

Amaçları, içinde binbir özveri ile yetiştirdiğin 

O çocuğu acımasızca katletmek. 

Katledilince sen de onlardan farksız olacaksın. 

Basit, alalade…

Gözlerin hep ışık saçmalı, mutlu olmalı, 

Sevinç dağıtmalısın. 

Eh, bencil de olmalısın, unutma. 

Bilmediğin yabancı bir gölgenin 

Yaklaştığını hissettiğinde 

içindeki şeytanın seni sollamasına izin ver. 

Bırak, önden ilerlesin. 

Çıkar hançer tırnaklarının izini 

Gölgenin bilinmeyen yüzüne. 

Bir darbe yeter. 

Sonsuza dek o izi taşıyacak. 

Vicdanının yetim ellerde kalmasından 

Rahatsızlık duyacağını düşünerek at her adımını. 

Yapacağın hamlede vezirini kaybedebilirsin, 

Belki de mat olur, zekanı kullan.

İnsanoğlu peşinde koştuğu gülün etkisindeyken 

Ezdiği menekşelerin farkına varmaz derler. 

Bir gün mazine şöyle bir başını çevirir bakarsan, 

O an içinde hiç bir tereddüt yeli esmemeli. 

Yaptıklarının sonucuna katlanacaksan ez, 

Parçala, dağıt, sev, isyan et, kendini bırak. 

Yüreğinin sesine kulak ver, 

Doğru bildiğini uygulamaktan asla çekinme. 

Yaptıklarının neticeleri ne olursa olsun 

Herşeyi göze alıyorsan; sorun yok. 

Sen özgürsün. 

Yaşam senin.

Şu lanet olası yaşam! 

Sahip olduğun en büyük nimet olan yaşam! 

İsyankarlığını sevgiyle terbiye et,

Ancak sevginin gücü buna yeter.', 'Hayır, böyle olmasını ben istemedim, Bırak hapsettiğin tüm hislerini.  Prangaları, kelepçeleri çöz.  Zaten çevrendeki o maskeli yüzlerin  Ga...', ARRAY['Türk Edebiyatı','Şiir','Asya Yıldız']::text[], 8.5, '{"poet":"Asya Yıldız","poet_slug":"asya-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":79,"source_url":"https://www.antoloji.com/isyankar-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kara Cümbüşler', 'kara-cumbusler-asya-yildiz-797qg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Elini tuttum, ilk adımım... 

Belki bendim ilk el uzatan, 

Kızıllığında güneşin...

Yüreğimi nadasa bırakmıştım. 

Ne umutlar ekmiş, 

Ne değerler biçmiştim emekle. 

Mutluluğumla paketleyip, 

Dağıttım güleryüzümle. 

Mükafatımı saymadım. 

Ne kadar zaman geçti aradan... 

Dönüp baksam toplamaya gücüm yeter mi? 

Zamanın periyotlarını, 

Yeşile boyanmış dağlardan topladığım 

Kır çiçekleri gibi. 

Demet haline getirsem, 

Kokar mı benim çiçeklerim gibi güzel? 

Götürür mü vurulduğum dağlara 

Kokusuyla beni kendimden geçirerek...

Kızıllığına büründü yine hava. 

Vedasında güneşin böyle efkarlanır yeryüzü. 

İnsanlar yuvalarına döner, kuşlar yuvalarına. 

Bürünüp kasvetime çıkarım dışarı. 

Ufkun kızıllığı siyaha çalar olmuş, 

Ayak izlerimi seçemez oldum. 

Semadaki yıldızları seçmeye başlarken bir bir; 

İsim verdim her birine yüreğimden söküp hüzünle. 

Her gece, her gece yaşar oldum bu anı. 

İnanıyorum ki bir gün yüreğimden söküp 

çıkarmadığım isim kalmayacak. 

Sen de kalmayacaksın o gün. 

Ağlayabilirim. 

Hala akacak zerre yaş kalırsa göz pınarlarımda.

Özleminin omzuna yasladım başımı, 

Göz kırpan yıldızlara masallar anlatıyorum. 

İçinde var olmayan aşklar yaşanan. 

Zaman, hain hırsız! 

Alıp sevgimi, gençliğimi aldığı gibi kaçırıyor benden! 

Kara cümbüşler çalıyor dört bir yanımda. 

Rakseden kara feracelerin altında gizliymiş her şey. 

Çocukluğum da orada mı? 

Yıllardır arayıp, ulaşamadığım. 

Yoksa aşk da mı orada, inanmadığım...

Aç gözlerini, çıkar at büründüğün kasveti 

sabahın ilk ışıklarıyla. 

Bu demlerde tadacaksın yüreğindeki sevgileri. 

Paletinden bir parça beyaz çal 

Her gördüğün karamsarlığa; çekinme. 

Görmek istediğini görür insanoğlu. 

Seni böyle görmek yıpratıyor beni. 

Gönül sepetini al eline bu gece, 

Gökyüzüne dağıttığın isimleri toplayacaksın, 

Kır çiçeklerini topladığın gibi dağlardan. 

Bir şans daha ver benliğine, merhametinle. 

Yitirme üzerine titrediğin meziyetlerini.

Pencerene konan serçelere su ver 

Ve her serçe gördüğünde beni hatırla. 

Benim gibi küçük, benim gibi özgür...', 'Elini tuttum, ilk adımım...  Belki bendim ilk el uzatan,  Kızıllığında güneşin... Yüreğimi nadasa bırakmıştım.  Ne umutlar ekmiş,  Ne değerl...', ARRAY['Türk Edebiyatı','Şiir','Asya Yıldız']::text[], 8.5, '{"poet":"Asya Yıldız","poet_slug":"asya-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":57,"source_url":"https://www.antoloji.com/kara-cumbusler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırılmış Dalım', 'kirilmis-dalim-asya-yildiz-13rju', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dayanamam gözyaşlarına, 

Silmek isterim. 

Ellerim dokunur tenine, 

Gözlerim gözlerini hapseder sonsuz zamanda. 

Acını hissederim, 

Süzülür damarlarımda kanım gibi, 

Dolanır bedenimin büyük dolaşımında. 

Yaşamıma hükmeder med-cezirlerin. 

Kırarım tüm zincirleri, 

Açar kafesleri bırakırım tüm kuşları özgürlüklerine. 

Doğru yok artık, yanlış yok. 

Sevda manasını yitirmiş. 

Hüznün dolaştıkça damarlarımda, 

Artar titreyişlerim. 

Bir ince dal olmuşum koca çınarın gövdesinde; 

Soğuklar sarmış dört bir yanımı. 

Titriyorum...

Kestiler... 

Kanadım yerli yerince. 

Süzülen damlaları çekti içine toprak. 

Rüzgar esti, 

Kurumuş yapraklarla örttü üstünü 

Dilinde bir acı ağıt. 

İspatı yok artık yaramın. 

Kanımı örtbas etmişler. 

Kırıklığım gün gibi ortada, 

Bir sancı var silip atamadığım içimde. 

Miras bırakmışlar sevdamın kalıntıları, 

Toprağa gömülüp giderken. 

Bir kırık dalım işte. 

İşte orada, 

Tek bir yaprağı bile olmayan yerdeki dal. 

Hep bu kadar büyükmüymüş 

Bir zamanlar parçası olduğum çınar? 

Hala anımsadığım yeşil yapraklarımın kokusu 

Kaç bin asırdır uzak benden? 

Gecelerin dilini kesmişler. 

Bir zamanlar mehtapla flört ederdi oysa. 

Belki beni kıran sevdanın ahıdır, 

Gece hiçbir aydınlığa kavuşamaz oldu. 

Kaç ışık yılı uzakta bu gün? 

Unuttu mu gecesini! 

Kolay mıydı bu kadar, 

Yüzyıllar boyunca peşinden koştuğu günü terketmek... 

Küstüm güne, 

Kaç güneş hediye etse de bağışlamayacağım. 

Karalarımı giyeli nice oldu, alıştım artık. 

Çıkarsam matemi yapışkanlığıyla üzerimden, 

çıkarabilsem... 

Ah bir de şu kırıklığımı telafi edebilsem. 

Tüm çabalar boşa, biliyorum. 

Açamaz rengine vurulduğum yapraklarım artık 

Mevsim mevsim renk değiştirerek bünyemde; 

Gövdem uzaklarda kalmış. 

Kökleri uzamaktaymış gün be gün arzuyla, 

Bensiz nasıl uzuyorsa. 

Bir vurdumduymazlık musallat olmuş olmalı; 

Yok, başka açıklaması yok.

Kanım çekildikçe büyüyor iklimlere olan sevgim. 

Mevsimleri özler oldum, 

İç çekişlerim gövdemi aştı, dağlardan büyük özlemlerim. 

Ateşlerim daha kaç orman yakar, 

Hangi deniz sözdürebilir beni. 

Hüznümü yaşarken kırıldım ben; 

Tenine dokununca koptum gövdemden, 

Düştüm gözyaşlarımla toprağa...

Örttü üstünü rüzgar 

Uzak diyarların yabancı kuru yapraklarıyla, 

Görmemem için. 

Hissediyorum oysa tüm derinliğinle seni 

Karışırken toprağın cansuyuna. 

Daha ne kadar zaman geçecek üzerime basıp kırılmışlığımla, 

Ne zaman dönüşeceğim seni saran kara toprağa...

Bana kara ağıtlar yakma... 

Geliyorum...', 'Dayanamam gözyaşlarına,  Silmek isterim.  Ellerim dokunur tenine,  Gözlerim gözlerini hapseder sonsuz zamanda.  Acını hissederim,  Süzülür d...', ARRAY['Türk Edebiyatı','Şiir','Asya Yıldız']::text[], 8.5, '{"poet":"Asya Yıldız","poet_slug":"asya-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":75,"source_url":"https://www.antoloji.com/kirilmis-dalim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kurumuşsa Dallarım', 'kurumussa-dallarim-asya-yildiz-p869l', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Beni bıraktın ya bu karanlıklarda sensiz; 

Bilmem... Ne demeli sana. 

Hangi sözcükler ifade edebilir hissiyatımı. 

Taşır mı kelimeler sitemimi. 

Yorulmaz mı benliğim sensizlikte çılgınca koşarken. 

Ulaşmak istediği çizgiye takılıyken gözleri, 

Belirsizleşince ufuk; 

Hüzne teslim olmaz mı gökyüzü.

Çok geç değil. 

İnan bana. 

Umut taşıyorsa yürek, 

Beslenebiliyorsa ümitler geç değil. 

Gönlüm nasır, ama taş değil.

Düşüncelerin seni hapsetmesine izin verme,

Bu düşünceler senin olsa bile. 

Ele geçirmeye çalışma kendini. 

Sev, arzula, nefret et tüm içtenliğinle. 

Galip gelmek önemli değil. 

Yaşam bu, yarış değil. 

İzin ver benliğinin yaşamasına. 

Tut ellerinden, kaldır; düştüğünde çaresizliğiyle. 

Ağladığında ellerinle sil göz yaşlarını. 

Anlamaya çabala, 

Mutlulukları savur avuçlarından.

Gün geldi dallarım çiçeklerle coştu; 

Gün geldi döküldü kırmızıya çalan yapraklarım 

Nemli topraklara. 

Vazgeçtiğim de oldu kendimden. 

Tüm duygular kenetlenmişken çevremde olumlu ya da olumsuz; 

Bir tek sese özlem duydum. 

Açabildiysem gözlerimi, 

Açabilip bakabildiysem etrafıma; 

Bir tek ona ihtiyaç duydum, 

Aradı gözbebeklerim ısrarla. 

Bir cıvıltı kulaklarımda, bayram mutluluğu yaşatan... 

Rüzgarın sesine karışan kanat çırpışları... 

Bülbül dalımdaysa kurumuşluğuna rağmen; 

Mevsimlere inat çiçek açarım. 

Güneşe verir sırtımı, yaprağımdan gölge yaparım. 

Köklerimi daha bir derine salarım... 

Dallarımı göğe açarım...

Güneşimi çalmışlar. 

Mevsimler birer birer terkteler. 

Yapraklarımı tutamaz oldum dallarımda, 

Dallar durmaz oldu gövdemde. 

Köklerim çekilir oldu topraktan. 

Kulaklarım sağır oldu, gözlerim kör. 

Rüzgar bencilliğine bürünmüş, 

Boğar olmuş salt kendi sesiyle beni. 

Günü hapsettim bir pencereye, 

Çektim perdelerini. 

Gecelere teslim oldum...

Seni kimler aldı? 

Çok geç değil. 

İnan bana. 

Ellerim perdelere dokundu dokunacak. 

Bir umut besliyorum ısrarla can evimde. 

Bir güneş değil beklediğim. 

Bir minik yıldız parıltısı seçebilsem gecede... 

Savurup perdeleri, açacağım penceremi. 

Kapanmamak üzere...', 'Beni bıraktın ya bu karanlıklarda sensiz;  Bilmem... Ne demeli sana.  Hangi sözcükler ifade edebilir hissiyatımı.  Taşır mı kelimeler sitemi...', ARRAY['Türk Edebiyatı','Şiir','Asya Yıldız']::text[], 8.5, '{"poet":"Asya Yıldız","poet_slug":"asya-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":61,"source_url":"https://www.antoloji.com/kurumussa-dallarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Müptela', 'muptela-asya-yildiz-e6rt6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sesini duymak yetti bana,

Bir bent oluşturdu yüreğimdeki seline. 

Seni aramayacaktım aslında. 

Her kasırgamı hissetmek zorunda değilsin, 

Çekilmezliğime katlanmak zorunda da değilsin...

...Müptela...

Bir yol çizmişim biliyor musun, 

Ya bir gece hayalinle sohbetimde, 

Ya da gündüz gözlerim yokluğuna dalmış ilerlerken. 

Güçlü olmam gerektiğinin bilincindeyim sadece. 

Çizdiğim yolda isteklerim doğrultusunda ilerlemem için. 

Tüm duyularımı yitirmeliyim belki de... 

...Müptela...

Birer birer yitirirken üzerine titrediğim, 

Değer biçemediğim vasıflarımı; 

Gözlerden uzak olmalıyım. 

Acizliğim bir oyun değil ki 

Gözler önünde sergilensin! 

Yıkılmışlığım benim. 

Sıkarken dişlerimi, 

Yastığımı ellerimle tüm gücümle; 

Akan gözyaşlarım benim! 

Paylaşmak istemiyorum.

...Müptela...

Beni yalnız bırak...

...Müptela...

Yaralarımı sıvarken sevginle şefkatle; 

Yine de beni yalnız bırak.

...Müptela...

Ama asla sensiz bırakma...

...Müptela...', 'Sesini duymak yetti bana, Bir bent oluşturdu yüreğimdeki seline.  Seni aramayacaktım aslında.  Her kasırgamı hissetmek zorunda değilsin,  Çe...', ARRAY['Türk Edebiyatı','Şiir','Asya Yıldız']::text[], 8.5, '{"poet":"Asya Yıldız","poet_slug":"asya-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/muptela-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Taklacı', 'taklaci-muharrem-cetinkaya-ds640', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ne diller döktün

takla attın

eğildin

kırıldın

büküldün

………..

çıktın sonunda

üs kata

yerin artık 

üst kat salonda

salonun solunda.

.

su kattın

bizim de

pişmiş aşımıza

elinde dondurma

yalıyorsun

yalama

utanmadan

bi-de geçmiş karşımıza

yalıyor yalama', 'ne diller döktün takla attın eğildin kırıldın büküldün ……….. çıktın sonunda üs kata yerin artık  üst kat salonda salonun solunda. . su kattı...', ARRAY['Türk Edebiyatı','Şiir','Muharrem Çetinkaya']::text[], 8.5, '{"poet":"Muharrem Çetinkaya","poet_slug":"muharrem-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/taklaci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nihayet', 'nihayet-asya-yildiz-0cafr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yüreğim ayrı bir loş bu gece, 

Yalnızlığın verdiği acıyla haykırıyorum 

Tik tak seslerine. 

Varlığına öylesine ihtiyacım var ki; 

Şu biçare kimsesizliğimle 

Nasıl başbaşa bırakabildin beni? 

Sesim ulaşmıyor mu sana? 

Gel, bitmeden nefesim. 

Gücümü de yitirir oldum 

Olmayan bakışlarının takibinde, 

İnancımı yitirdiğim gibi. 

Boynum hala bükük, dizlerim yerde. 

Bırakıp gidişinle üstlendiğim bu rol 

Terketmiyor beni. 

Sadece kollarım düştü yere. 

Zamanla, artık hatlarını çizemediğim 

Hayalini görmek için 

Açılan göz kapaklarım da acizliğe bürünecek. 

Kahrolacağım. 

Varlığını hissetmek isterken 

Sensizliğin ıstırabıyla sevişmek ne acı… 

Ve ne acı kurumuş çiçekler üzerine düşen 

Zavallı gözyaşlarının buharlaşması.

Bu dört duvar arasından çıkmaz oldum,

Ben ne oldum? 

Mahvoldum, ardından… 

Acizliğime lanet eder oldum. 

Sahilde, gitar sesine karışan 

Melodilerimizi hatırlıyorum başbaşa vermişliğimizle. 

Kulağıma fısıldayışlarını. 

Sıcaklığın... 

Müziğin ritmiyle dansediyoruz, 

Sen yine basıyorsun ayağıma. 

Böldüğüm elmanın büyük yarısını yine sana veriyorum. 

Eriyorum, toprak kokusunu da epey özlemişim. 

Ruhum sana kavuşunca bedenim de toprağa karışacak…

Göz kapaklarımı açamaz oldum, 

Yine inciler süzülmeye başladı yanaklarımdan aşağı. 

Sevdan dayanılmaz!

Sana yüreğimi verdim ben. 

Şimdi de kendimi veriyorum. 

Aman Tanrım!

Neler oluyor. 

Kıpırdayamıyorum. 

Bak, yine hayalin belirdi karşımda.

Tebessümüne vuruldu zaten bu yürek, 

Herşeyinden önce. 

Sevdim seni. 

Tüm diretmişliğimle, benliğimle.

Sensizliğe hiç alışamadım zaten. 

Geceleri dost bildim. 

Gündüzlere, sensiz dünyayı aydınlatan güneşe 

Lanet ederken gökyüzünün karanlığında seçemediğim, 

Oysa tüm benliğimle hissettiğim varlığına anlattım seni. 

Seni sensiz yaşamak öyle zor ki. 

Özledim seni!

Ve sen… Karşımdasın işte.

Niçin karşımda açmış kollarını bekliyorsun? 

Hadi kucakla beni. 

Kıpırdayamıyorum… 

Sonunda kanayan hasretin dinecek nihayet.

Nihayet...', 'Yüreğim ayrı bir loş bu gece,  Yalnızlığın verdiği acıyla haykırıyorum  Tik tak seslerine.  Varlığına öylesine ihtiyacım var ki;  Şu biçare ...', ARRAY['Türk Edebiyatı','Şiir','Asya Yıldız']::text[], 8.5, '{"poet":"Asya Yıldız","poet_slug":"asya-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":62,"source_url":"https://www.antoloji.com/nihayet-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalbim gülündür', 'kalbim-gulundur-ugur-yeniler-2f6pj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bedenim bahçendir kalbimde gülün

Kopar ellerinle, ser yollarına! ..

Ölürsem gözlerim açık gitmesin

Bir kez olsun beni; al kollarına! ..', 'Bedenim bahçendir kalbimde gülün Kopar ellerinle, ser yollarına! .. Ölürsem gözlerim açık gitmesin Bir kez olsun beni; al kollarına! .....', ARRAY['Türk Edebiyatı','Şiir','Uğur Yeniler']::text[], 8.5, '{"poet":"Uğur Yeniler","poet_slug":"ugur-yeniler","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kalbim-gulundur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olmuyor İşte', 'olmuyor-i-ste-asya-yildiz-buaps', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Olmuyor işte... 

Attıkça adımları bir şeyler yitiyor, 

Kanıyor dağlanmış yaralar. 

Nerelerden döner dolaşır, 

Beni bulur bilmem, 

Gelir o çığlık kulaklarıma takılır. 

Bulur muyum dersin 

Bir çıkış yolu yittiğim girdapta. 

Nasıl yaralandım... 

Sandım ki gücüm yeter değiştirmeye, 

Doğru bildiklerimi alırsam yanıma, 

Gücüm yeter. 

Olmuyor işte. 

Bir duvar oluyor çarptığın. 

Dağılan seni toparlamaya yetmiyor takatin. 

İlerlemek... 

İlerlemek olsa olsa düş. 

Oysa düşlerim rengarenk olmalı. 

O çok sevdiğim hüzünlü sonbahardan ayrılmalı önce. 

Her şeyden önce tutunacak bir dal bulmalı. 

Yaş veya kuru ne fark eder. 

Ne fark eder düşlerim olmuş veya olmamış. 

Yaşamışım ya şu hayatı. 

Senli ya da sensiz, 

çok şey fark eder.

En sevdiğim kitabı alıp yanıma, 

çıkacağım yola. 

Hayır, adımladığım park taşlarını 

Saymayacağım artık. 

Dudağımda ritim aldığım bir melodi de olmayacak.

Dedim ya... 

Olmuyor işte. 

Bir şeylerden vazgeçmeden olmuyor mutluluk. 

Önce alışkanlıkları terk etmeli belki birer birer. 

Hayatı onlarsız kucaklamalı, olduğu gibi; kuralsız. 

Ah bu ne huysuzluk böyle, 

Adını seslendiğim halde benden uzak huzur. 

Yoksa ben mi göremez oldum dersin? 

Yaşam karmaşasındayken, yanı başımdaki saadeti. 

Bir zamanlar pembe gözlüğüm de vardı. 

Artık yok; üzülmüyorum ama aramıyor da değilim.

Bir uzun yol bu. 

Yürüyorum. 

Koşuyorum. 

Kendini katlayarak artan bir uzun yol. 

Her şeyin bir başlangıcı ve sonu olduğuna göre 

Bunun da olmalı. 

Kim alıp beni bıraktı 

çaresizliğimle yolun ortasına söyle. 

Bir ses ver. 

Olmuyor işte. 

Hep bir çığlık musallat kulaklarıma, 

Silip atamadığım. 

Ve silip atamadığım gözyaşlarım benim.

Attıkça adımları bir şeyler yitiyor,

Kanıyor dağlanmış yaralar. 

Hala çıkış yolu yok. 

Dedim ya... 

Olmuyor işte...', 'Olmuyor işte...  Attıkça adımları bir şeyler yitiyor,  Kanıyor dağlanmış yaralar.  Nerelerden döner dolaşır,  Beni bulur bilmem,  Gelir o çı...', ARRAY['Türk Edebiyatı','Şiir','Asya Yıldız']::text[], 8.5, '{"poet":"Asya Yıldız","poet_slug":"asya-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":59,"source_url":"https://www.antoloji.com/olmuyor-iste-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Özledim', 'seni-ozledim-asya-yildiz-93o6k', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sensizliğe alışamıyorum, 

Çabalarım hep boşuna. 

Aldanmışım, 

Alışırım derken sana, 

Aldatmışım meğer kendimi. 

Özledim seni…

Seni, sesini, gülüşünü, 

Sıcaklığını, göz kapaklarını. 

İçim, içim öylesine titriyor ki 

Adını andıkça nöbet halinde dudaklarım. 

Daha bir derin çeker oldum 

Sigaranın lanet olası dumanını içime. 

Seni çeker oldum, 

Sıcaklığın sarar gibi benliğimi.

Izdırabım beni aştı, isyanlardayım. 

Doğruyu göremez olacağım yakında. 

Uzaklaşacağım senden. 

Bak, engel olmuyorsun. 

Bıktın mı yoksa benden? 

Bir bilsen sana nasıl ihtiyacım olduğunu, 

Kıyasıya sürüklendiğim şu yolda…

Gerçekleşmeyecek pembe sonlar hazırladım ikimize. 

Öyle mutlu tablolar çizdim ki 

Yüreğimdeki tuvallere. 

Oysa gerçeğe bakıyorum da, 

Cümbüş renkleri arasında yalnızım. 

Yalnızım yine. 

Ellerim boş, tutan yok, 

Gözyaşlarımı silen yok,

Haykırışlarımı duyan yok. 

Bir ayak izine hasret kalmışım. 

Kim ördü etrafıma bu dört duvarı? 

Nerede benim denizim; 

Dörtnala koşan tayım, neredesin? 

Bir kadeh daha çarpsam yıkılmaz mı şu duvar? 

Yüreğimin tüm gücüyle haykırdığım 

Sessiz çığlıklarımı duymaz mı biri? 

Aramazlar mı hiç, 

Hatırlamazlar mı da sormazlar beni? 

Neredeyim… 

Artık karanfillere döker olmuşum içimi. 

Beni bir onlar anlar olmuş. 

Tepkisiz sırdaşlarım… 

Seni sevdiğimi anlaman için çöllere mi düşmeliyim, 

Yoksa dağları mı delmeliyim? 

Benden bekleme. 

Bir derbederim işte. 

Seni düşünür, düşerim yollara. 

Her adım atışımda adın dökülür 

Dilimden sokak taşlarına, 

Yüreğimin kuytu köşelerine dökülen sevgin gibi. 

Aktıkça gözyaşlarım yıpranırım aslında. 

Ama daha bir coşkuyla açar 

Gönül bahçemde çiçeklerim. 

Hiç tatmadıkları sevgidir bu. 

Hiç yaşamadıkları. 

Hiç yaşayamayacakları. 

Sonlu olması ne acı…

Üzülme. 

Solan her çiçeği teker teker koparıp yerinden, 

Taç yapacağım başıma. 

Gönlüm çorak kalacak. 

Gönlüm yüzyıllarca kilit altında kalmış 

Bir esir kadar tutsak duygular içerisinde. 

Beni toprak temizleyecek, biliyorum. 

Evet, o zaman çürümüş bedenimle karışan 

Toprakta yeşerip açacak gönül verdiğim çiçekler. 

Toprağın sıcaklığıyla ısınacağım, hasretini çekerek.

Sana herşeyin en güzelini vermek istedim, 

Vermek isterim. 

Beyaz giysiler içerisinde gelemezsem sana; kızma. 

Kahrolası yaşamın oyunlarından biri kabul et. 

Unut… 

Beni olmayan gerçekliğinle başbaşa bırak…

Bu diri beden seni istemese bile 

Çürüyünce ruhu seni bekleyecek. 

Esirgemezsin değil mi ondan bir ziyareti? 

Toprağına su dökersin değil mi kendi ellerinle. 

Ağlama ama. 

Gözyaşlarını diz çöküp öpecek kadar güçlü olamayacağım.

Beni affet…

Seni Özledim.', 'Sensizliğe alışamıyorum,  Çabalarım hep boşuna.  Aldanmışım,  Alışırım derken sana,  Aldatmışım meğer kendimi.  Özledim seni… Seni, sesini, ...', ARRAY['Türk Edebiyatı','Şiir','Asya Yıldız']::text[], 8.5, '{"poet":"Asya Yıldız","poet_slug":"asya-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":82,"source_url":"https://www.antoloji.com/seni-ozledim-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tutsak', 'tutsak-asya-yildiz-a1fx7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çıktım geceden... 

O kara, zifiri yollardan 

Adımlarımı çekerken düğümlendi boğazımda sevgi. 

Çıkmak istercesine dışarıya çırpınan canım, 

Ah canım, götürdü beni adımlarımla uzaklara. 

Dediler ki yokmuş hüzün, 

Gelmezmiş toplayıp dostlarını o diyarlara. 

Git, dedi yüreğime can çekişen canım. 

Bedenimi bırakmak isterdim oysa o yollarda. 

Senden hatıralar beynimde dolaşırken 

Koşarcasına kaçtığım kapkara gecede. 

Gece senden yadigar. 

Ve dua eden fısıltılarım gökyüzünde. 

Çıktım geceden... 

Canım yandı...

Tutmuşlar, yere indirmişler bakışları. 

Baş eğilmiş, gurur çırpınmış. 

Kiminmiş bu ceset? 

Motif motif işlenmiş tenime kokun. 

Çizgisinde sesin, renginde gözlerin. 

Vurulmuş içimin mutluluğu. 

En kara düşlere tutsak kalmış uykularım. 

Dokundukça seni anlatan motiflere ellerimle, 

Yaşarım oysa. 

Kanayan mutluluğum gezinir hatlarında, 

Kahkahanla sarhoş mırıldanırken. 

Beni anma, en kara düşlerde tutsak kalmışım...

Aylar ağır ağır yığılırken birbirinin üzerine, 

Ben doğan güne aldanmışım. 

Gündüzün geceden ne farkı var? 

Yaşadığım mevsimde açmayan çiçekleri sevdim ben. 

Solmayan umutlar besledim, rengarenk. 

Kuşlarla şakıdım, rüzgarla uğuldadım. 

Ayları kovaladım ard arda; mevsimim değişmedi. 

Gecenin gündüzden ne farkı var? 

Çektim, aldım içimdeki sevgileri. 

Kapattım panayır yeri gönlümü. 

Tuttum  yakasından anıların, 

Birer birer söktüm çivilerini. 

İzler kalmış geride... 

Kapanmaz... 

Hüznümle paketledim sana ait ne varsa. 

Bir tebessüm iliştirdim üzerine, 

Gönderdim adresine. 

Bildiğim tüm nesneler üzerine okudum adını. 

Sebepsiz yere mutlu olduğun anlar, 

işte o anlar beni anlarsın. 

Tuttum yakasından söktüm anıları, 

İzi kaldı yüreğimde. 

Gücüm yeter mi sanıyorsun acıları sarmaya... 

İnanma...', 'Çıktım geceden...  O kara, zifiri yollardan  Adımlarımı çekerken düğümlendi boğazımda sevgi.  Çıkmak istercesine dışarıya çırpınan canım,  A...', ARRAY['Türk Edebiyatı','Şiir','Asya Yıldız']::text[], 8.5, '{"poet":"Asya Yıldız","poet_slug":"asya-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":51,"source_url":"https://www.antoloji.com/tutsak-51-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzak Eller', 'uzak-eller-asya-yildiz-ioorl', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Saklanıp güneşten, aya göz kırpmak gibi... 

Yıldızlara laf atmak, 

Geceye sevda türküleri söylemek gibi. 

Bir ömrü sona erdirip, 

Herşey bitti dediğin an 

Yeniden merhaba demek gibi... 

Sevgin, kara toprak altında 

Diriliğini koruyan tohum gibi... 

Sevgin ruhumun derinliği, gözyaşımın kaynağı. 

Taşıdığım yürek ev sahipliği yapar, 

Üzerine titrer yavrusu gibi...

Sanki alından akan terleri 

Hiç silmemiş eller. 

Hiç telaş içinde oğuşturulmamış, 

Sıcak dokunuşlara şahit olmamış, 

Yaşamamış kadar soğuk. 

Ve uzak çırpınan yürekten o eller. 

Sesini duyamayacak derecede uzak artık. 

Yürek sitem eylesin, 

Varsın küssün yaban ellere. 

Tavşan dağa küsmüş de dağın haberi mi olmuş? 

Ellerin telaşı başka, 

Yüreğin sancısı her geçen gün daha derin. 

Yaşamdan aldığı izbeleri 

Karanlıkta tutup saklamakmış oysa 

Tek kaygısı yüreğin. 

Aynalara dargın bir sima 

Hüzün dolu bedenin taşıdığı. 

Kalın hatlar var; 

Geçmişi tarif eden kalın ve bilgin hatlar. 

Gülse, daha belirgin olacaklar... 

Ellerle hep dost olmuş. 

Silinen yaşları yüzünün kıvrımlarında 

Gezdirmek istermiş oysa. 

Kenarına dek inip, 

Asla dudaklarına dokunmadan düşermiş yaşlar. 

Dudağı ıslanıp çenesine değişleri 

Düşlermiş her akıttığında. 

Dolan, dolup taşan gözlerin tek isteğiymiş bu. 

Eller dost, 

Eller dayanamayıp hep silmiş; 

Hayaller hayal olarak kalmış. 

Dudaklar hiç ıslanmamış. 

Oysa akan damlalarla yürekte ne seller, 

Ne kasırgalar yaşanmış. 

Pes ettiği de olmuş, 

Tüm ümitlerin suya düştüğü de; 

Yine de dimdik ayakta kalmış yürek, 

Yılmamış. 

Bu en tükenilmiş anlarda dahi 

Eller merhamet etmez, 

Dinlemezlermiş sözünü. 

Tek bildikleri 

Gözyaşları akmaya başlamadan silmek olmuş. 

Neler söyler, ne isyanlar sunar 

O gözyaşlarıyla oysa yürek. 

Göz dayanamaz verir yaşını cömertçe. 

Ah bu eller yine de söz dinlemez... 

Usulca bir ahizeye asla yaklaşmaz...', 'Saklanıp güneşten, aya göz kırpmak gibi...  Yıldızlara laf atmak,  Geceye sevda türküleri söylemek gibi.  Bir ömrü sona erdirip,  Herşey bit...', ARRAY['Türk Edebiyatı','Şiir','Asya Yıldız']::text[], 8.5, '{"poet":"Asya Yıldız","poet_slug":"asya-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":59,"source_url":"https://www.antoloji.com/uzak-eller-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yadederim', 'yadederim-asya-yildiz-0xx2c', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hissediyorum,

Aldığım manevi güç ile epey yol alacağım.

Kuzeyden bir güneş ışığı farkettiğimde, 

Gerçekliğine inanmadım, 

Haklısın, belki de inanmak istemedim ısrarla. 

Oysa kaldırınca gözlerimdeki perdeyi, 

Çekince yüzümü kapatan ellerimi aşağıya; 

Gördüm. 

Şimdi, o gerçekle yaşıyorum. 

Bir yaşam hırsı sunmuş bana, 

Binmişim bu hırsın sırtına, 

Dörtnala ilerliyorum yolumda.

Başlarda mücadele verdiğim güvensizliğimi 

Kendi ellerimle parçaladım. 

Ufalanırken izledim gözlerimle. 

Hüzünlendiğim, 

Görmemek için yumduğum da oldu gözlerimi. 

Başarınca bir tatlı huzur kapladı bedenimi. 

Ve ruhumun derinliğine inen kapıyı 

Aralamaya karar verdim. 

Uzatıp yavaşça, ürkekliğimle elimi araladım. 

Bilemiyorum, 

Belki en büyük yanlışımla tanıştım kapı aralığında. 

Bir hamlede yüzündeki maskeyi indirebilirdim 

Ya da gerçekliğiyle başbaşa olduğumu kavrardım. 

Oysa hiç kalkmadı elim. 

Bir sarhoşluk musallat oldu; 

Üzerine düşmedim. 

Kenara çektim bedenimi, zamana geçit verdim.

Kuzey güneşinin parlaklığına aldanıyor olmalıyım. 

Diyorum ikna etmek için, 

İlk adımı atmak üzere olan ruhuma. 

Hatalarımı telafi etmekte o kadar zorlanıyor ki 

Kırılmaması için gözlerimi kör etmeyi düşünüyorum. 

Tedavi edecek gücüm var mı, hiç sınamadım. 

Riske atılmayacak kadar yaşlı hissediyorum, 

Duyarsızlığım değer vermeyişimden değil. 

Kaynağıma indiğimde karışık düşüncelerimi toplayıp 

Birer birer akarsulara bırakıyorum. 

Alsın, götürsün gittiği yere, 

Uzaklaştırsın benden diye. 

Hayretlerim bent oluşturuyorlar karşımda. 

Akarsular donmuş! 

Diz çöküyorum; 

Başka rolü yakıştıramıyorum kendime. 

Üstlendiğim rollerin ehemmiyeti mühim değil. 

Yüreğimdeki sesin çığlıklarını gömdükten sonra toprağa. 

Ardından… 

Büyük bir kayadan kopmuş 

Minik bir parçacık koyarım toprağın üzerine, 

Kutsal bir törenle; kendimce. 

Dönmesine izin verirsem bir gün başımın bu yöne, 

Yadederim… 

Kuzey güneşinin sıcaklığını hissederim, 

Biçare yüreğimin sakin köşesinde. 

Yadederim…

Başımı önüme eğerim…', 'Hissediyorum, Aldığım manevi güç ile epey yol alacağım. Kuzeyden bir güneş ışığı farkettiğimde,  Gerçekliğine inanmadım,  Haklısın, belki de...', ARRAY['Türk Edebiyatı','Şiir','Asya Yıldız']::text[], 8.5, '{"poet":"Asya Yıldız","poet_slug":"asya-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":57,"source_url":"https://www.antoloji.com/yadederim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yığılan Yıllar', 'yigilan-yillar-asya-yildiz-vn8y5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Andım... 

Senden kalan ne varsa. 

Yandım... 

Koca bir dağ önümde geçmiş yıllarım. 

Nasıl toplanmış, 

Birikmiş de yığılmış önüme onca yıllar...

Denedim. 

Geceleri konuştum karanlıkla. 

Yokluğuna anlattım içimdekileri. 

Aradım, bulamadım gülüşlerimi. 

Ağladım hıçkırarak, yoktun yine. 

Uzaklar sana verir mi benim sevgimi söyle? 

Olmadı, 

Olamadı geceler senin kadar dost. 

Ve veremedi güneş senin sıcaklığını. 

Sarılacak omzun olmayışı ne kötü... 

Mutluluğu paylaşmakta sakınca yok; 

Ama bu hüzün neden paylaşılmaz. 

Nedir bu çevremdeki duvarlar?', 'Andım...  Senden kalan ne varsa.  Yandım...  Koca bir dağ önümde geçmiş yıllarım.  Nasıl toplanmış,  Birikmiş de yığılmış önüme onca yıllar....', ARRAY['Türk Edebiyatı','Şiir','Asya Yıldız']::text[], 8.5, '{"poet":"Asya Yıldız","poet_slug":"asya-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/yigilan-yillar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıldızlar Gökyüzünde', 'yildizlar-gokyuzunde-asya-yildiz-cq0w9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yine gece... Yine yıldızlar gökyüzünde... 

Bak istersen ellerine, sevdiğin ellerine. 

Bir şey geleceğine inanıyor musun ellerinden? 

Sarılıp ağladığın duyguların sarhoşluğunda...

Aslında ilk adımını attığında süzülecekti 

Yanaklarından ilk yaş özlemle. 

Yüzünün kıvrımlarında ilerleyecekti coşkuyla ağırca. 

Özlemi buydu ya; çıkmıştı göz pınarından, 

Süzülmüştü ya yanaklarında usulca. 

Bakabilseydin aynalara gerçek yüzlerinden 

Farkedebilecektin sen de. 

Süzülen bir damlayla karışıp yaşayacaktın, 

Kavuşmanın özleme, verdiği hazzı tebessümünle. 

Yıkabilseydin ardına saklandığın bahane duvarlarını 

O sevdiğin ellerinle, 

Parçalarını yüreğinin çizmeyecektin sarı sayfalara... 

Bakmakla kalmayacaktın güzelliklere, 

Vermekle yetinmeyecektin. 

Bakabilseydin sırsız yüzlerinden...

Soğuk kayaları eş tutmayacaktın kendine. 

Bütünleşmek, dönüşmek istercesine bir kayaya 

Uzanmayacaktın iç çekişlerinle. 

Yapışmayacaktı üzerine anılar dönüp bakmasaydın. 

İzlemeseydin uçuşan martıları, özgürlükleri görmeyecektin 

sahip oldukları cazibeleriyle koklaşırken. 

Arzulamayacaktın uçmayı, dilemeyecektin bir kuş olmayı. 

Nefes aldıkça bağlanmayacaktın yaşama. 

Yaşadıkça şükretmeyecektin Yaradan’a, ellerin semaya dönük. 

Üstlenmek zorunda kaldığın tüm rolleri 

Silip atacaktın belki yüreğinden. 

Kazımak kendi ellerinle, sevdiğin ellerinle, 

Kendi yüreğini; titrediğini hissederek...

Bir temiz ırmak bul kendine dinlenebileceğin kıyısında, 

Kendini bulmuşcasına. 

Eğil, bak ırmağın akan sularına kendi yüzünle. 

Aynalara ihtiyaç duyma! 

Bir göz kırp ırmağa özgüveninle, dön arkanı. 

Kendini görmen için tek ihtiyacın sensin. 

Bakışlarını çevir yüreğine, 

Sal tüm hislerini arzularının takibine. 

Usanma izlemekten, yorulma. 

Başaracaksın aşmayı bahane duvarını. 

Ardından, bir damla yaşa, gözyaşına kavuşacaksın. 

Özlemini hissedince kilidi açılacak tüm kafeslerin. 

Vurulduğun saadet okşayacak saçlarını.

Sen, doğrularına sarıl yalnızca, 

Yalnızlığının kalabalığında soluk alırken. 

Kaldır gözbebeklerini, bak yıldızlara. 

Yine gece... Yine yıldızlar... 

Evet, her şey senin elinde, 

O çok sevdiğin ellerinde. 

Sen yeter ki iste...', 'Yine gece... Yine yıldızlar gökyüzünde...  Bak istersen ellerine, sevdiğin ellerine.  Bir şey geleceğine inanıyor musun ellerinden?  Sarılıp...', ARRAY['Türk Edebiyatı','Şiir','Asya Yıldız']::text[], 8.5, '{"poet":"Asya Yıldız","poet_slug":"asya-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/yildizlar-gokyuzunde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yolculuk', 'yolculuk-asya-yildiz-6hpeq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Güneş kokan bir sevdaymış sarılıp yattığım, 

Boylu boyunca uzanmıştık gecenin karanlığına bir zaman. 

Vakit ayrılıkla tanıştırmak için nasıl da hevesli. 

Gökyüzü kasırgalarına haber salmış; 

Benim hüzünlerim yanıbaşımda. 

Güneş kokan bir sevdaymış doyamadığım...

Yeşile bürünmüş yeryüzü. 

Umutlarım demet demet sevgiler gibi. 

Tutulabilse, dile gelse... 

Hüküm gönlümün olsa. 

Bir kuş konsa sağ elime, okşasam usulca. 

Öpsem onu ürkmeden, ürkütmeden. 

Mavi göğe kanat açsa, 

O en uzaktaki en yakınlara götürse sıcaklığımı. 

Sevebilsem umarsızca, 

Ah bir de sırtımı dönebilsem yargılara...

Kahverengi gözler... 

Aralarından süzülüp geçilen dağlar kadar kahverengi. 

Zor yolun sert kıvrımları 

zarif yüzünün hatlarına yansımış olmalı. 

Evet, mutlaka böyle olmalı. 

Yorulmaksızın kanat çırpan büyük kuşu okşayan 

Rüzgar da ben olmalıyım.

Bir büyük orman. 

Yaşıyor, yaşamalı. 

Toprağını okşayan dalgalar 

Dokunmasa da yaşlı ağaçlarına... 

Ne farkeder ki! 

Kapat gözlerini, dinle sesini. 

Yapraklarını savuran rüzgara üfle nefesini. 

Rengini değiştiren yaprağını ver toprağa, 

Ulaşır belki kıyıya, ulaşamadığın dalgalara.

Kan kırmızıymış yattığım gece. 

Uykularım bulanık, rüyalarım kayıp. 

Yıldızlarım da gitmişler bilinmeyen yerlere. 

Örtmüş olamaz gecenin karanlığı 

Ne kadar karamsar da olsa. 

Bir parıltı belirirdi elbet semada, 

En azından ben baktığımda, olsaydın hayatta. 

Üzerime ağıt ağıt dökülmekte gece. 

Tutup atamıyorum. 

Uykularımı da kaçıran bu ağıtlar mı? 

Rüyalarımı gizleyen benden, 

Gözlerimi kan kırmızıya mahkum eden... 

Kan kırmızıymış yattığım gece. 

Uyanmama izin yok.

Ve buyruk geldi; en soğuklarda en sıcak bulunmalıymış. 

En yakınlarda öpülen en uzaklar kadar sıcak mıdır nefesi... 

Söyleyemeyeceğim şiirleri şarkı yapmışlar. 

Tüm renklerimi birbirine karıştırmışlar, çözülemiyorum. 

Yağmur uğramasın diye kesildi ağaçlar. 

Sal olup, vurulduğu dalgalara kavuşsun diye değil. 

Hiçbir şey göründüğü gibi değil. 

Varolmak yok bana artık. 

Yağmur yok artık. 

Buyruk geldi gökkuşağım, söyle, tüm renklerin sussun.

Direndiler. 

Doğru bildiklerinden vazgeçmemek içindi bu savaş. 

Üzerine titrediklerini kaybetmemek içindi. 

Tüm zamanlar dize geldi, 

Kesilen başlar toprağı deldi, 

Yeşil maviye söz verdi. 

Fayda vermedi çabalar. 

Çekmecedeki fotoğraflar sararmış; 

Resimdeki göz akıtabilmiş mi yaşını?

Akıtabilse silen bir teselli eli olacak mı... 

Dokunulmayı unutmuş sararmış fotoğraflar. 

Gözyaşı manasını yitirmiş. 

Anılar isyan isyan çekmecelerde. 

Direttiler, solmuşluğu kabul etmediler. 

Nafile...', 'Güneş kokan bir sevdaymış sarılıp yattığım,  Boylu boyunca uzanmıştık gecenin karanlığına bir zaman.  Vakit ayrılıkla tanıştırmak için nasıl...', ARRAY['Türk Edebiyatı','Şiir','Asya Yıldız']::text[], 8.5, '{"poet":"Asya Yıldız","poet_slug":"asya-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":71,"source_url":"https://www.antoloji.com/yolculuk-93-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırmaya değmez', 'kirmaya-degmez-suleyman-zaman-f647h', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Soldurdun gönlümde, gonca gülümü

Kullanırsın, zehir gibi dilini

Arttırırsın sinemdeki selimi

Bir mal için, gönül kırmaya değmez

Çürütürsün olgunlaşmış meyvemi

Seyrinde gider mi? Dümensiz gemi

Sineğe yendirdin kocaman devi

Para için gönül kırmaya değmez

Nereden öğrendin gönül kırmayı

Bilmiyorsun doğru soru sormayı

Becermedin bir gönüle girmeyi

Hezeyanla gönül kırmaya değmez

Aydınlık günümü, mata çevirdin

Nice pişmiş aşı, kurda yedirdin

Gerçekleri neden, nasıl görmedin

Hata için gönül kırmaya değmez

Çekilemez oldun  kırdın sinemi

Anlaksız tavrınla  yordun tinimi

Hemen her gün zehir ettin günüm

Çıkar için gönül kırmaya değmez

Yanıltır insanı anlık duygular

Doyumsuz olur, bilisiz yığınlar

Zamanım kem söze, kalbi sızılar

Yanlış için gönül kırmaya değmez.

                                 01.12.2002', 'Soldurdun gönlümde, gonca gülümü Kullanırsın, zehir gibi dilini Arttırırsın sinemdeki selimi Bir mal için, gönül kırmaya değmez Çürütürsün o...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Zaman']::text[], 8.5, '{"poet":"Süleyman Zaman","poet_slug":"suleyman-zaman","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/kirmaya-degmez-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Züğürt Ağa', 'zugurt-aga-suleyman-zaman-fvdzn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Benim tanıdığım bir züğürt ağa var

Beş kuruş meteliğe on takla atar

Sunuyor insanlara bir çok vaatler

İçi boş, dışı boş bir züğürt ağa o! 

Ona başka buna başkadır söylemi

Kandırır onu,bunu sürüyor gemi

Yalanla- dolanla geçiyor günleri

Meteliksiz biri, tam züğürt ağa o! 

Konuşunca sanırsın, çok asil biri

Tanıyınca anlarsın gerimi geri 

Dümen için yapıyor, onca siperi

Zavallı birisi tam  züğürt ağa o! 

Gösteriş üstüne kurmuş hayatını

Nedense bayırlara sürer atını

Yüklendiği her iş aşıyor çapını

Kurnazca tavrı var, zor züğürt ağa o! 

İşi yoktur ama, herkese iş verir

Davranışı kaba, niyeti incedir

Haklardan söz eder, tuzak sinsicedir

Zeki bir yanı var, tam züğürt ağa o! 

Zamanım’ın züğürtle başı belalı

Züğürtlere kaptırmayın ha yuları

Bulandırırlar onlar, temiz suları

Bulanık kafalı, tam züğürt ağa o! 

                                         25.05.2002', 'Benim tanıdığım bir züğürt ağa var Beş kuruş meteliğe on takla atar Sunuyor insanlara bir çok vaatler İçi boş, dışı boş bir züğürt ağa o!  O...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Zaman']::text[], 8.5, '{"poet":"Süleyman Zaman","poet_slug":"suleyman-zaman","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/zugurt-aga-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Durdur Erozyonu', 'durdur-erozyonu-adnan-durdagi-vacu6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kesilir ağaçlar ormanlar yanar

İçimde yaradır kapanmaz kanar

Sanma ürün olur ne kuşlar konar

Durdur erozyonu toprak gidiyor

Rüzgar parça parça alır süpürür

Yağsa yağmur seller gelir götürür

Dünya çoraklaşır hayat bitirir

Durdur erozyonu toprak gidiyor

Kurudu akmıyor coşan dereler

Topraklar taş olur beni yaralar

Dikmezsen ağacı gelmez çareler

Durdur erozyonu toprak gidiyor

Bak YETİMİ ADNAN bir çare arar

Dikersen yeşili dünyayı sarar

Kucaklar toprağı veremez zarar

Durdur erozyonu toprak gidiyor', 'Kesilir ağaçlar ormanlar yanar İçimde yaradır kapanmaz kanar Sanma ürün olur ne kuşlar konar Durdur erozyonu toprak gidiyor Rüzgar parça par...', ARRAY['Türk Edebiyatı','Şiir','Adnan Durdağı']::text[], 8.5, '{"poet":"Adnan Durdağı","poet_slug":"adnan-durdagi","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/durdur-erozyonu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağaç', 'agac-adnan-durdagi-6xf9i', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dünyanın ciğeri ağaçtır ağaç

Yanınca ormanlar kalıyor kıraç

İyi uğraş için ne güzel süreç

Bir ormanı koru bir de yeşili

Ağaç dünyamızın yeşil örtüsü

Kurmak istiyorsan sevgi köprüsü

Fidanla bestele barış türküsü

Bir ormanı koru bir de yeşili

Ağaç sevgi ağaç verim ağaç su

Ağaç  yaşam ağaç hayat ağaç bu

Ağaç hava ağaç cennet doğrusu

Bir ormanı koru bir de yeşili

Bir çok tatlar onda lezzet ondadır

Dertlere ilaçtır sıhhat ondadır

Dünya nimetidir servet ondadır

Bir ormanı koru bir de yeşili

Onunla büyüdük onla gideriz

Ekşiyi tatlıyı hep ondan yeriz

Ağaçsız dünyada nasıl ederiz

Bir ormanı koru bir de yeşili

Ağaçlar yaşamın tadı lezzeti

Ağaçlar ülkemin milli serveti

YETİMİ ağaca yapar hizmeti

Bir ormanı koru bir de yeşili', 'Dünyanın ciğeri ağaçtır ağaç Yanınca ormanlar kalıyor kıraç İyi uğraş için ne güzel süreç Bir ormanı koru bir de yeşili Ağaç dünyamızın yeşi...', ARRAY['Türk Edebiyatı','Şiir','Adnan Durdağı']::text[], 8.5, '{"poet":"Adnan Durdağı","poet_slug":"adnan-durdagi","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/agac-41-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalınayak', 'yalinayak-sanem-deniz-mvzob', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İlk kez vazgeçiyorum

süslü pabuçlarımdan,

Ayağıma batacakların 

kaygısını duymadan.

Işıl ışıl karanlığında 

seni yaşıyorum

Gözlerini kapasanda

duyuyorsun biliyorum...

Korkma! 

çıkar pabuçlarını

ayağını keseceklerin

kaygısını duymadan.

Sesinin tınısında

aşkı yaşıyorum

Kulaklarını tıkasanda

görüyorsun biliyorum...', 'İlk kez vazgeçiyorum süslü pabuçlarımdan, Ayağıma batacakların  kaygısını duymadan. Işıl ışıl karanlığında  seni yaşıyorum Gözlerini kapasan...', ARRAY['Türk Edebiyatı','Şiir','Sanem Deniz']::text[], 8.5, '{"poet":"Sanem Deniz","poet_slug":"sanem-deniz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yalinayak-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Asal Aşk', 'asal-ask-mehme-arslan-ozcvf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'senden ve kendimden başka

kimseye bölünmem ben

bi de ölüme 

istemeden', 'senden ve kendimden başka kimseye bölünmem ben bi de ölüme  istemeden...', ARRAY['Türk Edebiyatı','Şiir','Mehme Arslan']::text[], 8.5, '{"poet":"Mehme Arslan","poet_slug":"mehme-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/asal-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayak sesleri(1)', 'ayak-sesleri-1-enes-ates-amx3s', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yaşamak müşkül imiş bîmecal, kuytularda

Kuytularda yalnızlık ebedî bir misafir

Misafir ruhlarımız gülmüyor sayfalarda

Sayfalarda kelime hummâlı ve çetrefil...', 'Yaşamak müşkül imiş bîmecal, kuytularda Kuytularda yalnızlık ebedî bir misafir Misafir ruhlarımız gülmüyor sayfalarda Sayfalarda kelime humm...', ARRAY['Türk Edebiyatı','Şiir','Enes Ateş']::text[], 8.5, '{"poet":"Enes Ateş","poet_slug":"enes-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ayak-sesleri-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Trafik', 'trafik-adnan-durdagi-90iqp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Nice canlar gitti ocaklar söndü

Kanlar hiç durmadı savaşa döndü

Kor ateş düşürdü yürekler yandı

Güvenli bir seyir senin elinde

Eceliyle olsa dayanır insan

Başına gelince uyanır insan

Eğer ibret alsa uslanır insan

Güvenli bir seyir senin elinde

Acele nedenle ecele gitme

Kuralı tedbiri sakın terketme

Seni bekleyeni sonsuz bekletme

Güvenli bir seyir senin elinde

Düşürme acıyı ağlatma canı

Dikkat et yoluna akıtma kanı

Bir şey olmaz deme kuralı tanı

Güvenli bir seyir senin elinde

YETİMİ''yim açık olsun yolunuz

Kazadan beladan uzak olunuz

Kırılmasın kanadınız kolunuz

Güvenli bir seyir senin elinde', 'Nice canlar gitti ocaklar söndü Kanlar hiç durmadı savaşa döndü Kor ateş düşürdü yürekler yandı Güvenli bir seyir senin elinde Eceliyle olsa...', ARRAY['Türk Edebiyatı','Şiir','Adnan Durdağı']::text[], 8.5, '{"poet":"Adnan Durdağı","poet_slug":"adnan-durdagi","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/trafik-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnselim Ben', 'i-nselim-ben-suleyman-zaman-o7trw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Varolduğu için evren, varım ben

Öldüğümde, benim için yok evren

Özüdür evrenin her şey; ben ve sen

Kavrıyorum bunları; inselim ben

Varolmadım yoktan; vardım ben tözde

Dünyayı küçümser softa her sözde

Bağıntı yok mudur; baharla güzde

Çözüyorum bunları; inselim ben.

Bağlıdır tinle ten; gör sen gerçeği

Bağımsız sanma; tenden düşünceyi

Hakikat gör dışındaki özdeği

Seziyorum bunları; İnselim ben

Bir değil, sürekli oluştur doğa

Devinir her şeyler kendin olmağa

Dolu boşa; boş yönelir dolmağa

Biliyorum bunları; inselim ben

Yoktur bir başlangıç; bu evren sonsuz

Kozmostan kaos; kaostan doğar kozmos

Küçük büyük; büyüğü oluşturur toz

Biliyorum  bunları; inselim ben.

Yoktur boşluk evrende; var plazma

Söyleyince bunu; sen bana  kızma

Enerjidir özde tin; tensiz sanma

Yaşıyorum bunları; inselim  ben.

Çok evrenli, evrendeyiz bil bunu

Farklı, farklıdır özdeğin konumu

Dönüştü,  oluşturdu Zamanımı

Ölüp ve doğuyorum; inselim ben.



                                                    02.11.2001', 'Varolduğu için evren, varım ben Öldüğümde, benim için yok evren Özüdür evrenin her şey; ben ve sen Kavrıyorum bunları; inselim ben Varolmadı...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Zaman']::text[], 8.5, '{"poet":"Süleyman Zaman","poet_slug":"suleyman-zaman","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/inselim-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çıktım Aşkın İle Dağbaşlarına', 'ciktim-askin-i-le-dagbaslarina-kamil-soylemez-ou3k0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Senmiydin gerçekten seven

Ya da benmi..? 

Ömür rüzgar gibi geçip,giderken

Özlemle gecelere günaydınlar 

Gündüzlere iyi akşamları 

Hüzünlü gözyaşlarını  takan 

Bir kısrak yelesi 

Ya da yıldırımlar çakımı

Hangimiz duydu 

Ya da duymadı

Ölüp,ölüp dirilmelerin sancısını

Çokta önemlimi ki dünya malı

Geçgin yaşın sanılan sarmaş dolaş aşkı

Ya vurduysa yaşlılığın ite kaka çalımı

Uktelerin biri inip biri binerken ahlarla

Neyin önemi kalır ki

Neyin özlemi sevgili kadar ağır çeker

Ten kokusunun özlemi 

Bir gülüşün gizemi

Göz bebeklerindeki çilemi

Seni beni mutlu eder

Hiçte sanmam yarından tezi yok

Geçmeden zaman kucaklayıp saracağım

Tüm arzumla seni sevdam saracağım

Yıllara inat çıkacağım sevdan dağbaşlarına

Ve seni seveceğim hemde hiç ayrılmamacasına

Yeterki sen çık aşk ve sevda dağbaşlarına', 'Senmiydin gerçekten seven Ya da benmi..?  Ömür rüzgar gibi geçip,giderken Özlemle gecelere günaydınlar  Gündüzlere iyi akşamları  Hüzünlü gö...', ARRAY['Türk Edebiyatı','Şiir','Kamil Söylemez']::text[], 8.5, '{"poet":"Kamil Söylemez","poet_slug":"kamil-soylemez","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/ciktim-askin-ile-dagbaslarina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yok Senin Adın', 'yok-senin-adin-tunahan-ermihan-x5fvo', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '“ Kırık yüreğim ve avucumda düşlerim

Ümit diye beslediğim tüm iyi niyetlerim kırıldı sevdiğimin ellerinde

Şimdi beni hangi hüzün katarı alsın

Hangi melek avutsun ”

Yok Senin Adın

Geçip giderken ömrümüz

Kenarında durmuşum hayatın renklerini seçmeye çalışıyorum

Hatıralardan süzülen ışık kırıkları geliyor gözlerime

Sanıyorum ki hayat kimseye acınmayacak kadar zalim

Umut dolu çocukların neşeli çığlıkları geliyor yamacıma

Bir heyecan kaplıyor bedenimi

Belki de tükenmeyen şeyler de vardır diyorum

Kendimi düşünüyorum adını anıyorum içten içe

Bomboş bir karanlıkta ellerim ayaklarım kesiliyor

Ve anlıyorum ki senin rengini beyaz adını bahar koyan yanlarım

Tüm gerçeklerini görmezden gelen aşık yanımmış

Kapkara sevdanın ardından adının yanında kalan

Ne bahar ne de beyaz

Adın ……..

Yok senin adın', '“ Kırık yüreğim ve avucumda düşlerim Ümit diye beslediğim tüm iyi niyetlerim kırıldı sevdiğimin ellerinde Şimdi beni hangi hüzün katarı alsı...', ARRAY['Türk Edebiyatı','Şiir','Tunahan Ermihan']::text[], 8.5, '{"poet":"Tunahan Ermihan","poet_slug":"tunahan-ermihan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yok-senin-adin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Reşaranî Şiir ve Beyitsiler 36', 'resaran-siir-ve-beyitsiler-36-huseyin-avdic-30axr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İbadetsiz, Hıyanettedir

Oruçta bütün vücud ibadettedir.

İbadetsiz bir mevcud, hıyanettedir.

******

Ödemen Gereken

Bedava değildir hayat

Ücretidir teşekkürat

Allah''tır seni yaşatan

O''nadır bütün şükürat

******

İnsanlığın Gereği

Bil ki oruçsuzluk; tıbba, sıhhate ihanettir.

İhanete düşmemek, insanlığın gereğidir.

Berlin, Ağustos 2005.', 'İbadetsiz, Hıyanettedir Oruçta bütün vücud ibadettedir. İbadetsiz bir mevcud, hıyanettedir. ****** Ödemen Gereken Bedava değildir hayat Ücre...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Avdic']::text[], 8.5, '{"poet":"Hüseyin Avdic","poet_slug":"huseyin-avdic","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/resarani-siir-ve-beyitsiler-36-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dilan', 'dilan-ugur-yeniler-pi3to', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ACILI SEVDAM

Ne zaman elim bir kalem tutsa

Hep seni yazıyorum

Ne zaman gözlerim dalsa

Bil ki hep sen varsın

Göz bebeklerimde! Kardelen...

Ne zaman bir meyle buluşsa dudağım

Hep seni içiyorum

Her yudumda seni

Kalbime çiziyorum

İçim yanıyor

Yalnız ve soğuk odamda

Bir rakım, birde mezem sen

‘ACILI   SEVDAM ‘ 

Kardelen..

Oysa

Ah ah! ..... be, Kardelen; şimdi var ya! ...

Seninde olmanı isterdim

Adını kazıdığım masamda

Bir ömre bedel o geceyi

Acısız

İhanetsiz

Mertçe

Yalnız seninle

Bir tek seninle yaşamak isterdim

Kardelen! ....

Gelmeyeceksin biliyorum

Bir gün aklına gelirsem

Buz göndermeyi unutma sakın

Rakım için değil ha! 

Senin için yanan

Su yüreği söndürmek için

Kardelen! ...

Uğur Yeniler/Eskişehir             22.04.2003', 'ACILI SEVDAM Ne zaman elim bir kalem tutsa Hep seni yazıyorum Ne zaman gözlerim dalsa Bil ki hep sen varsın Göz bebeklerimde! Kardelen... Ne...', ARRAY['Türk Edebiyatı','Şiir','Uğur Yeniler']::text[], 8.5, '{"poet":"Uğur Yeniler","poet_slug":"ugur-yeniler","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/dilan-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel De Sev', 'gel-de-sev-alper-kuruk-qmw92', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir sabah ölüm

Silkine silkine kalktı uykusundan

Çocukca bir korku ile 

Korkuttu hayatı sevenleri.

Tabiat yine güzeldi

Her zamanki kadar.

Hele yaşamak

Yaşamak umutlar dolu günleri

Doyamamaktan yana delice yaşamak.

Gel de sev ölümü 

Bir de sevgilin varsa,

Gel de sev ölümü

Yenice öpüşmeyi öğrenmişsen.

Dünyalık ödünç bir canın olduğunu

Gel de unutma 

''Yaşamak güzel...''derken.

Ölüm silkindi uykudan

Uykusu döküldü yaşamanın üstüne 

Bir tabut daha yöneldi selviliklere

Bir kez daha ayrıldı:yaşayan,yaşamayan...', 'Bir sabah ölüm Silkine silkine kalktı uykusundan Çocukca bir korku ile  Korkuttu hayatı sevenleri. Tabiat yine güzeldi Her zamanki kadar. He...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gel-de-sev-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın Gözyaşları', 'askin-gozyaslari-tulay-sustam-r6fgc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yokluğun; yüreğime öyle ağır geliyor ki... Sensiz hayatın tadı yok, tuzu yok, anlamı yok. Sanmam! Her yüreği yokluğun böyle acıtsın. Attığım her adımın yolculuğu sen... Sen gittin ya! ... Artık yüzüm gülmüyor. Çayım azalmıyor, sigaram bitmiyor, yediğim lokma boğazımdan geçmiyor… Nasıl bir yokluk seninkisi … Varlığı da yok ediyor…

Ülkemin en kalabalık şehrinde, hücremde yalnızım. Kaç kez volta attım elele dolaştığımız sokaklarda... Kimi zaman eğilip ayak izlerini öptüğüm zamanlar da oldu, gözyaşlarımla sildiğim zamanlar da...Ölümcül bir hastalık gibi kanıma işledin.Yokluğunla öldürdün.

Bilirsin! ...

Özlem her bakışa başka çizer resmini, her yüreğe ayrı vurur acısı... Her tende başkadır kokusu... Kimi zaman seni hatırladım sana benzeyen her yüzde sanki hiç gitmemişsin gibi... Gülüşler sen oldu, bakışlar sen... Aradan asırlar geçmesine rağmen... Ne var ki ruhu sen olmuş bedenim ne dokunuşunu, ne de öpüşünü unutabildi... 

Bilirsin! ... 

Her ağacın kökü, toprağın koynundadır... Her yaprağı gökyüzüne el açar...Şu koca yüreğim, gövdemin sol yanına kök salmış... Nice canlar içinde bir seni canından öte can saymış... adını ''''can ikizim'''' koymuş... Ellerin kalmış koynumda ilk günkü sıcaklığıyla, rüzgâr bile kıskanmış dokunuşundaki ateşi esmekten vazgeçip, terketmiş bedenimi... Ne zaman aklıma düşse adının ilk harfi el açardım, dilek dilerdim yıldızlardan... 

Düşünemedim! ... 

Kara gözlü gökyüzünün ışıkları, ayrılığı tez getirir. Yıldızım olup, kayıp gittin mavi yüreğimden... Oysa hiç okumadın dudağımı... Aşkı yudumlamadın gözyaşlarımdan... Bilseydin! ... Benim Ay parçası olduğumu... Gitmezdin böyle... Giderken, kendini bıraktın bende... O günden beri her halini yaşadım da Ay''ın... Senden sonra bir DOLUNAY olamadım... 

Düşünemedim! ... 

Kara gözlü gökyüzünün ışıkları, ayrılığı tez getirir...

18.09.2005 İstanbul', 'Yokluğun; yüreğime öyle ağır geliyor ki... Sensiz hayatın tadı yok, tuzu yok, anlamı yok. Sanmam! Her yüreği yokluğun böyle acıtsın. Attığım...', ARRAY['Türk Edebiyatı','Şiir','Tülay Sustam']::text[], 8.5, '{"poet":"Tülay Sustam","poet_slug":"tulay-sustam","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/askin-gozyaslari-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Garip (Elgin)', 'garip-elgin-alper-kuruk-4uoce', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Elgin diyorlar bana

Hem ermiş,hem elmişim,

Kader atmış yabana 

Bu yerlere gelmişim.

Tahammül ettim sana 

Sabır dolu geçmişim,

Takdir et,anlasana

Mey diye gam içmişim.

Kuvvet ola tabana

Durmadan gezermişim,

Düşmüşüm bir kapana

Oysa ben de zermişim.

Her taş yerinde ağır

Demiş atalarımız,

Ne desen duymaz sağır

Bitmez hatalarımız.

Mekâna bağlı değil

Ben her zaman özgürüm,

Girmek istersen eğil

Alçak kapılı gönlüm...', 'Elgin diyorlar bana Hem ermiş,hem elmişim, Kader atmış yabana  Bu yerlere gelmişim. Tahammül ettim sana  Sabır dolu geçmişim, Takdir et,anla...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/garip-elgin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İniş - Çıkış', 'i-nis-cikis-alper-kuruk-2s5zl', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben sana söyledim ya bu da gelir ve geçer

Göçebe olan kişi gün olur yine göçer.

Kimi birikintiden,kimi kaynaktan içer

Dünyanın hâli böyle,bu,Yaratan kuralı.

Aleme gücün yetmez,sen kendini değiştir

O kadar büyüklensen bile dünya geniştir,

Her çıkışın mutlaka sonu yine iniştir

Boşa düzlük arama,ya in ya çık yukarı...', 'Ben sana söyledim ya bu da gelir ve geçer Göçebe olan kişi gün olur yine göçer. Kimi birikintiden,kimi kaynaktan içer Dünyanın hâli böyle,bu...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/inis-cikis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Domates Tarlası', 'domates-tarlasi-mehmet-bicik-b0tbx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir yaz günü karşılaşınca senle,

Ne hâle geldim bak bir dinle:

Ben eridim gittim senin sevginle,

O sıcak, şirin domates tarlasında…

Bitmesin bu rüya diye yazmıştın,

Evlenelim deyince heyecanlanmıştın,

Ayrılık girince araya ağlamıştın,

O güzel, şirin domates tarlasında…

İlyaslar’da senle çarpan bir kâlp var,

Derdin, domateste olduğumuz zamanlar,

Hadi kaçalım deyince etmedin hiç âr,

O güzel, sıcak domates tarlasında…

Neler konuşmuştuk seninle neler,

Şimdi mâzide kaldı o güzel günler,

Hâtıra kaldı yolladığın mendiller,

O sıcak, şirin domates tarlasında…

Nereye gitsen bulurum seni ben,

Diyordun ki, bu sözü unuttun sen,

Filizlenen aşkımızı sen oldun bitiren,

O güzel, sıcak domates tarlasında…', 'Bir yaz günü karşılaşınca senle, Ne hâle geldim bak bir dinle: Ben eridim gittim senin sevginle, O sıcak, şirin domates tarlasında… Bitmesin...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Bicik']::text[], 8.5, '{"poet":"Mehmet Bicik","poet_slug":"mehmet-bicik","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/domates-tarlasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sürgün', 'surgun-sezai-sengonul-s1ru4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yalnızdı

Anlaşılmazdı

Biraz kızgın biraz küskün

Bu yüzden

ve  biraz vardı içinde 

Çam kokulu hüzün

Yollamış kim neden

Hem yazın

Hem de güzün

İçine kuru kalabalıkların

Sanki Sürgün...', 'Yalnızdı Anlaşılmazdı Biraz kızgın biraz küskün Bu yüzden ve  biraz vardı içinde  Çam kokulu hüzün Yollamış kim neden Hem yazın Hem de güzün...', ARRAY['Türk Edebiyatı','Şiir','Sezai Şengönül']::text[], 8.5, '{"poet":"Sezai Şengönül","poet_slug":"sezai-sengonul","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/surgun-84-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vapurun Ölümü', 'vapurun-olumu-oguz-kaan-2-3ccou', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Son kez yüzüyordu dalgalara karşı

Onurlu,bir o kadar da hırslı

Bitmişti o güzel yaz ayları

Son kez çalışıyordu motorları

Akşam serininde

Yaklaştı iskeleye

Verdi son nefesini

Sessizce...', 'Son kez yüzüyordu dalgalara karşı Onurlu,bir o kadar da hırslı Bitmişti o güzel yaz ayları Son kez çalışıyordu motorları Akşam serininde Yak...', ARRAY['Türk Edebiyatı','Şiir','Oğuz Kaan 2']::text[], 8.5, '{"poet":"Oğuz Kaan 2","poet_slug":"oguz-kaan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/vapurun-olumu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgidir Gönlünde', 'sevgidir-gonlunde-i-brahim-ethem-bingul-qinuj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İster ilân et afişlerde

İster gizle

Sırla, yüreğinde

Göçerken dünyadan bir kefenle

Yanında götürebileceğin tek şey

Sevgidir

Gönlünde...

Hakkını verebildin mi kendince

Veremedin mi

Bir düşün...

Boş ver,üzülme

Bir kere hissedebildiysen özünde

Korkma yalnız değilsin

Değilsin yalnız

Kefenle bile...

Ne olmuş varsa acı, sevgide

Ne olmuş varsa ulaşılmazlık sevilende

Göçerken dünyadan bir kefenle

Yanında götürebileceğin tek şey

Sevgidir gönlünde...

www.iebingül.com', 'İster ilân et afişlerde İster gizle Sırla, yüreğinde Göçerken dünyadan bir kefenle Yanında götürebileceğin tek şey Sevgidir Gönlünde... Hakk...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sevgidir-gonlunde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hurafe', 'hurafe-mehme-arslan-mkm2t', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'arefe günü yıkansam

bi arpa boyu yol alırmıyım 

bu sevdadan

ya da kadir gecesi 

kırk rekat namaz kılsam

kurtulabilir miyim kırk günde

bu ayrılık acısından

yahut sana kahve ısmarladım diyelim

unutur musun beni gün aldığında

altmış bir yaşından', 'arefe günü yıkansam bi arpa boyu yol alırmıyım  bu sevdadan ya da kadir gecesi  kırk rekat namaz kılsam kurtulabilir miyim kırk günde bu ayr...', ARRAY['Türk Edebiyatı','Şiir','Mehme Arslan']::text[], 8.5, '{"poet":"Mehme Arslan","poet_slug":"mehme-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/hurafe-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
