INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gölgemde ölen günesim', 'golgemde-olen-gunesim-halime-kirnic-96gvo', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bütün gemilerini yaktigim bu limandan

Cekilemem bir türlü yalnizligima......

Hala gölgede ölen bir günesin

Umudunu tasir cünki yüregim...

01.08.2005/Hollanda', 'Bütün gemilerini yaktigim bu limandan Cekilemem bir türlü yalnizligima...... Hala gölgede ölen bir günesin Umudunu tasir cünki yüregim... 01...', ARRAY['Türk Edebiyatı','Şiir','Halime Kırnıç']::text[], 8.5, '{"poet":"Halime Kırnıç","poet_slug":"halime-kirnic","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/golgemde-olen-gunesim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur Damlaları', 'yagmur-damlalari-oguz-kaan-2-rac1s', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yağmur damlaları yollarda

Sessizlik var parklarda

Gün batıyor ufukta

Ağlıyor gökyüzü yavaşça

Bir damla yağmur, bir damla daha

Islanır kent sessiz ve usulca

Bir çocuk var camda

Bakıyor yağmurda ıslanmış sokaklara

Kuşlar ötmüyor ağaçlarda

Yağmur yağmayıp dursa da 

Sessizlik bozulmadı hala

Şimdi toprak kokusu var kırlarda', 'Yağmur damlaları yollarda Sessizlik var parklarda Gün batıyor ufukta Ağlıyor gökyüzü yavaşça Bir damla yağmur, bir damla daha Islanır kent s...', ARRAY['Türk Edebiyatı','Şiir','Oğuz Kaan 2']::text[], 8.5, '{"poet":"Oğuz Kaan 2","poet_slug":"oguz-kaan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yagmur-damlalari-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Bu', 'ask-bu-bekir-mutlu-gokcesu-zmxn7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aşk bu

Soluduğun hava kadar 

Sinmeli içine 

Bir bulut kadar hafif

Süzülüp, gezinebilmeli 

İçinde özgürce...

Ve bir sağanak gibi inmeli

İşlemeli iliklerine kadar

Canı isteyince...

Aşk bu, sana mı soracak...', 'Aşk bu Soluduğun hava kadar  Sinmeli içine  Bir bulut kadar hafif Süzülüp, gezinebilmeli  İçinde özgürce... Ve bir sağanak gibi inmeli İşlem...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ask-bu-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüzgâr', 'ruzg-r-enes-ates-puu65', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gariban gariban dolaşma rüzgâr,

                   İçimi göklere salıp da gitme! ! 

  Ayrılık ruhumu elimden aldı,,

                    Benliğimi de sen alıp da gitme! ! !', 'Gariban gariban dolaşma rüzgâr,                    İçimi göklere salıp da gitme! !    Ayrılık ruhumu elimden aldı,,                     Benl...', ARRAY['Türk Edebiyatı','Şiir','Enes Ateş']::text[], 8.5, '{"poet":"Enes Ateş","poet_slug":"enes-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ruzgar-115-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben şiir yazacağım', 'ben-siir-yazacagim-naime-kurtulus-od4hw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Simdi 

tam havamdayim simdi 

simdi siir yazacagim 

odam daginikliktan bitmis 

karisikliktan kafam

buldum caremi 

ben siir yazacagim

belki cok uzun olur

kisa belki

ama ben yaacagim

siie siir yazacagim

caresidir yalnizligin 

durgunlugun,  haylazligin siir

siir ben siir ben yazacagim

ben siir yazacagim

kalemim kagit benim siirim

olacagim cocuk 

tutturacagim gibi cocuk 

ben siir yazacagim 

kitap okurum cok belki bugun

kaciyorum 

kaciyorum 

ben siir yazacagim 

kalem yazmaz oldu 

ama ben siir yazacagim....', 'Simdi  tam havamdayim simdi  simdi siir yazacagim  odam daginikliktan bitmis  karisikliktan kafam buldum caremi  ben siir yazacagim belki co...', ARRAY['Türk Edebiyatı','Şiir','Naime Kurtuluş']::text[], 8.5, '{"poet":"Naime Kurtuluş","poet_slug":"naime-kurtulus","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ben-siir-yazacagim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Der''dim', 'der-dim-burhanettin-akdag-jzk3p', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu alemin dayanılmaz dertlerini çekmek değildir...........''''Derd'''' im

Ezelden ebede uzanan ilahi ilimle bilgilenmektir............''''Derd'''' im

Kubbede hoş sada, ardımdan dua edecek nesildir.........''''Derd'''' im

''

Meğer ki günahtan arınıp, ahirete imanla göçmektir.......''''Derd'''' im

Derdi dert etmeyenin, gaflette direnenin hali nicedir........''''Der''''dim

Yol yakınken, vakit tezken uyanmalı derin uykudan........''''Der''''dim...

(06.10.2005)', 'Bu alemin dayanılmaz dertlerini çekmek değildir...........''''Derd'''' im Ezelden ebede uzanan ilahi ilimle bilgilenmektir............''''Derd'''' i...', ARRAY['Türk Edebiyatı','Şiir','Burhanettin Akdağ']::text[], 8.5, '{"poet":"Burhanettin Akdağ","poet_slug":"burhanettin-akdag","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/der-dim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Bir Irak''lı Çocuğum', 'ben-bir-irak-li-cocugum-abdurrahman-tepe-5kezy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gül bağında her gül gibi tam da açmak üzereydim

Kopardılar beni hiçteni ben bir Irak''lı çocuğum

Ben de minik her kuş gibi tam da uçmak üzereydim

Vurdurdular beni hiçten ben bir Irak''lı çocuğum

Ben annemin kollarında beklerdim bin umutlarla

Hayallerle hülyalarla beyaz doru kıratlarla

Bulutların üzerinde uçacaktım kanatlarla

Kırdırdılar kanadımı ben bir Irak''lı çocuğum

Kimimiz ana rahminde kimimiz tatlı uykuda

Bir sabah namaz vaktiydi büyüklerim hep rukuda

Ölümün kokusu vardı titriyorduk hep korkuda

Sindirdiler bizi hiçten ben bir Irak''lı çocuğum

Ben de emsallerim gibi gezmek tozmak istiyordum

Çocuk gibi hem doyunca çokça azmak istiyordum

Bir gün varıp bir okulda yazmak çizmek istiyordum

Sürdürdüler bizi yoktan ben bir ırak''lı çocuğum

Katlettiler anamızı katlettiler babamızı

Muradından kopardılar abimizi ablamızı

Sabaha daha çıkmadan bombalarla hepimizi

Yaktırdılar bizi hiçten ben bir ırak''lı çocuğum

Ben küçük henüz körpeydim hayalim gelin olmaktı

Allı pullu gelin olup beyaz gelinlik giymekti

Yaşamak benim de hakkım evlenip yuva kurmaktı

Kandırdılar bizi hiçten ben bir ırak''lı çocuğum

Ben henüz delikanlıyım nazedar dalyan boyluyum

Çok kibarım çok efendi nazenin tatlı huyluyum

Emperyalist siyonistler demese de ben soyluyum

Sömürdüler bizi hiçten ben bir ırak''lı çocuğum

BuHaçlılar kudurarak ülkemizi böldürdüler

Huzur getiririz diye varıp petrola kondular

SAMİHİ der bal yerine mümine zehir sundular

Öldürdüler bizi hiçten ben bir ırak''lı çocuğum', 'Gül bağında her gül gibi tam da açmak üzereydim Kopardılar beni hiçteni ben bir Irak''lı çocuğum Ben de minik her kuş gibi tam da uçmak üzere...', ARRAY['Türk Edebiyatı','Şiir','Abdurrahman Tepe']::text[], 8.5, '{"poet":"Abdurrahman Tepe","poet_slug":"abdurrahman-tepe","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/ben-bir-irak-li-cocugum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Nasıl ''Dost''sun?', 'sen-nasil-dost-sun-burhanettin-akdag-okvlg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Düşkün anında,

Hep yanındaydım

Üzüldüğünde,

Gözyaşına ortaktım

Sıkıştığında,

Koşuşturan bendim

Bunaldığında,

Dert ortağın bendim

Kavgaya karıştığında,

Yetişen bendim...

Bir işim düştüydü sana

Hani dostum diyerek

Kaçacak delik aradın

Selamı bile esirgedin

Uzattığım eli tutmadın

Vefadan, haberin var mı senin? 

Var isem eğer, yüreğinde

Ne kadardır, yerim? 

Söyle bana Allah aşkına

Sen, nasıl bir ''dost''sun? 

(28.09.2004)', 'Düşkün anında, Hep yanındaydım Üzüldüğünde, Gözyaşına ortaktım Sıkıştığında, Koşuşturan bendim Bunaldığında, Dert ortağın bendim Kavgaya kar...', ARRAY['Türk Edebiyatı','Şiir','Burhanettin Akdağ']::text[], 8.5, '{"poet":"Burhanettin Akdağ","poet_slug":"burhanettin-akdag","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sen-nasil-dost-sun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Muamma', 'muamma-arafat-arik-bwvcg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Küsülü göklerin Süreyya kızı

Sen çorak gönlümün lâlegâhısın.

Hem umut ağrısı, hem kahpe sızı,

Hem can çekişenin çilegâhısın

Tereddüt getiren buluta inat

Gene de selimin karargâhısın

Hem sadık bir akde sensin teminat

Hem de günübirlik can seyyahısın

Rotasız gemime sensin kılavuz

Derman arayanın tek dergâhısın 

Yavuza zebunsun, zebuna yavuz

Derdine düşenin dinmez âhısın

Kulları umutta nöbet bekleyen

Efsun ülkesinin pad-ı şahısın

Hem cana cemresin, hem güz ekleyen

Gözlere kıyılan yaş nikâhısın

Gökçe sevdaların nazlı maralı,

Ölümün âzadı, tez felâhısın.

Hem gönül hapsinim, hem de karalı

Sen şeytanın emri, tek silahısın

Sen doğmadık suçun ilk günâhısın

Sen onmaz yazgının en siyahısın

Nedamet zehrinin bin eyvâhısın

Neyleyim göğsümün sol cenahısın.

5-Ekim-2005', 'Küsülü göklerin Süreyya kızı Sen çorak gönlümün lâlegâhısın. Hem umut ağrısı, hem kahpe sızı, Hem can çekişenin çilegâhısın Tereddüt getiren...', ARRAY['Türk Edebiyatı','Şiir','Arafat Arık']::text[], 8.5, '{"poet":"Arafat Arık","poet_slug":"arafat-arik","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/muamma-36-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Savaşın Ortasında Dili Tutulmuş Bir Kedi', 'savasin-ortasinda-dili-tutulmus-bir-kedi-erdinc-ozdemir-hgriz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Savaşın ortasında...

Susamıştı

Susuzdu

Su dolmuş miğferden su içti

Gözyaşları sudaki yüzüne damladı

Yorulmuştu

Yorgundu

Eşi kaybolmuş postalın içine girip uyudu

Savaş sonrasında...

Kuş avlamayı bıraktı

Günlük tuttu

Kuşların kanatlarında getirdiği pastayı yedi

Fareyle şakalaşıp

Kelebeklerin dansına katıldı

Karların eridiği bir gün

Yanında bir kemancıyla

Siyah renkli faytona zıplayıp

Gitti

O,kafasında şiir dolaşan ilk kediydi', 'Savaşın ortasında... Susamıştı Susuzdu Su dolmuş miğferden su içti Gözyaşları sudaki yüzüne damladı Yorulmuştu Yorgundu Eşi kaybolmuş postal...', ARRAY['Türk Edebiyatı','Şiir','Erdinç Özdemir']::text[], 8.5, '{"poet":"Erdinç Özdemir","poet_slug":"erdinc-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/savasin-ortasinda-dili-tutulmus-bir-kedi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yenilmez Süvari', 'yenilmez-suvari-samet-bayar-pf7lp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Mantığımla kalbimin savaşında

Yenilmez bir süvari gibiydin

Gece birkaç kadehte 

Sensizlik aradım

Kapattım gözlerimi 

Bilinçsizce sensizliğe

Sabahın ilk ışıklarıyla

Doldun kalbime sessizce

Kalbim yine seninle

Bedenim sensiz

Hep çaresiz...', 'Mantığımla kalbimin savaşında Yenilmez bir süvari gibiydin Gece birkaç kadehte  Sensizlik aradım Kapattım gözlerimi  Bilinçsizce sensizliğe ...', ARRAY['Türk Edebiyatı','Şiir','Samet Bayar']::text[], 8.5, '{"poet":"Samet Bayar","poet_slug":"samet-bayar","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/yenilmez-suvari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dokunuşlar', 'dokunuslar-yasar-yilmaz-q4srh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ilk dokunuşları tatmışım

Boğaziçi''nde

bir 6 ekim akşamında

yine bir 6 ekim

kaçıncı dokunuşlardayım 

kim bilir 

45 defa döndürmüşüm 

dünyayı yörüngesinde

kaçıncı umutlarında

kaçıncı kaybedişlerinde

kaçıncı hüzünlerindeyim hayatın 

kim bilir

doğduğumda beni saran eller nerde

nerde sıcaklığı o kutsal kucağın

dört yanımızı saran kardeşler, arkadaşlar

coşkularımız, içten gülüşlerimiz

nerde........

topaç çevirdiğimiz çocukluğumuz

ilk aşklarımız, masumiyetimiz

sevgiliye mektuplarımız

nefes nefese geçen gençliğimiz

gün oldu büyüklerimizi uğurladık aramızdan

gün oldu arkadaşlarımızı 

biriktirdik acılarımızı

taş ettik yüreklerimizi 

ama çaktırmadık üzüntülerimizi

yine de sevdik hayatı be

koşturduk sevgilinin ardından

aldattık, aldatıldık

çektik acıyı da zevki de bir nefeste

yarını yakalama sevdasıyla

harcasak da yaşamımızı

yaşlansak da 

kaybetmedik umudumuzu

ah dokunuşlarımız

06.10.2005 (Doğum Günüm Anısına)', 'ilk dokunuşları tatmışım Boğaziçi''nde bir 6 ekim akşamında yine bir 6 ekim kaçıncı dokunuşlardayım  kim bilir  45 defa döndürmüşüm  dünyayı ...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Yılmaz']::text[], 8.5, '{"poet":"Yaşar Yılmaz","poet_slug":"yasar-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/dokunuslar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Garipcan', 'garipcan-ali-aydogan-rqjjj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Günlerden Ekim Ayının Bir Persembe sabahı saar sabahın üc bucugu hava inadına soguk yoluma cıkan bir can küçüçük ve sevimli dolu dolu bakısları insanın kanını kaynatmaya yetiyorda artıyor bile minicik yüregi sımsıcak kalbi vardı bakıslarında yeni bi dostum olmustu kanım donarken bir seher vakti aldım yanıma düştük evin yoluna sokakta bizden baska kimse yoktu ben ve peşimde adına koydugum garipcan ah garipcan dilin var konusabilsne neler anlatıcaksın kimbilir insanlara nelerrr ve yasamak denilen bir döngünün içinde kalmıstı ben gibi kimsesiz sevgidi annesiyoktu yanında belki hüznü onun  içindi için için dolu dolu bakışlarında gördügüm bir tutam yanlızlıık vardı aynı kaderimi paylasıyoruz garipcan dilsiz dostum benim karnı ac kalmıs eve varıyoruz gözleri parlıyor sanki elimdeki bir parca ekmegi görünce dili cözülüyor kendince seviniyor bişiler anlatmak istiyor ama anlamıyorum ki anlasam ah garipcan', 'Günlerden Ekim Ayının Bir Persembe sabahı saar sabahın üc bucugu hava inadına soguk yoluma cıkan bir can küçüçük ve sevimli dolu dolu bakısl...', ARRAY['Türk Edebiyatı','Şiir','Ali Aydogan']::text[], 8.5, '{"poet":"Ali Aydogan","poet_slug":"ali-aydogan","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/garipcan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerin', 'gozlerin-sair-habibi-96gcv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gözlerin; 

                              Ölümsüzlük gibi bir şey kana kana içtiğim

                              Ve ayazda sarıldığım yürek yangınım.

             Gözlerin; 

                              Çaresizce savrulduğum çöllerinde

                              Bir vahaya ulaşmak gibi bir şey.

              Gözlerin; 

                              Kurumuş dudaklarımla içmek,

                              Tekrar tekrar içmek gözlerini; 

                              Sonsuzluğu içmek gibi bir şey...', 'Gözlerin;                                Ölümsüzlük gibi bir şey kana kana içtiğim                               Ve ayazda sarıldığım yürek ...', ARRAY['Türk Edebiyatı','Şiir','Şair Habibi']::text[], 8.5, '{"poet":"Şair Habibi","poet_slug":"sair-habibi","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/gozlerin-191-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üzüntü', 'uzuntu-adem-uzun-hc6oe', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Aç kapını yine, yine ben geldim. 

Gül kokuları getirdim sana. 

Bütün gülleri önüne serdim, 

Bütün gülleri ayaklarına. 

Bilmezsin seni nasıl sevmiştim, 

Sevgilerin en bahtiyarından. 

Sana ne kadar değer vermiştim. 

Anlayamadın, üzüntüm ondan. 

Çok zor geliyor olmalı sana, 

Bir kere olsun yüzüme gülmek. 

Artık bunun böyle olduğuna, 

İnandım artık, öyleymiş demek.', 'Aç kapını yine, yine ben geldim.  Gül kokuları getirdim sana.  Bütün gülleri önüne serdim,  Bütün gülleri ayaklarına.  Bilmezsin seni nasıl ...', ARRAY['Türk Edebiyatı','Şiir','Adem Uzun']::text[], 8.5, '{"poet":"Adem Uzun","poet_slug":"adem-uzun","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/uzuntu-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasrete 5 Kala', 'hasrete-5-kala-mirac-durmus-kddsx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hasrete 5 kala hissettim acını

Anladım Ayrılığın yürekleri yakışını.

Anladım Senin ßenden kopuşunu...

Seni Geri getirecek,

Seni ßana kavuşturacak,

Çareyi bulamadım.

ßu acıyı Dindirecek Çareyi ßulamadım.

Koptun,gittin,Uzaklaştın benden...

Gözlerim Seni aradı,ulaşamadı,

Ellerim Dokunmak istedi tenine,ßeceremedi.

ßedenim yarım kaldı,Kalßim Her atışında ismini Sayıkladı...

Hasrete 5 kala ßaşladı yangın..

İçimi yakıp kavurdu.

Nefes alamadım sensiz,

ßir yanım eksildi; Yürek, kaldı Çaresiz..

ßumuydu hasret,ßumuydu ayrılık,ßumuydu Sensizlik..

Acıların en kötüsüymüş Çaresizlik..

Sanmaki yaşıyorum Şimdilerde,

Sanmaki; gülüyorum,Tebessüm ediyorum

Aslında ßen,Hasrete 5 kala ölmüşüm...', 'Hasrete 5 kala hissettim acını Anladım Ayrılığın yürekleri yakışını. Anladım Senin ßenden kopuşunu... Seni Geri getirecek, Seni ßana kavuştu...', ARRAY['Türk Edebiyatı','Şiir','Miraç Durmuş']::text[], 8.5, '{"poet":"Miraç Durmuş","poet_slug":"mirac-durmus","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/hasrete-5-kala-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiliye', 'sevgiliye-mirac-durmus-voy2j', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İnsan kaybedince anlıyor değerleri.

Ulaşamayınca anlıyor sevgilinin değerini.

Özlüyor,umut ediyor geri gelmesini.

Dönmek istiyor gecmişe,

Yaşamak için,yaşatmak icin...

Sevgiliye duyulan özlem çığ gibi artıyor,

Küçük bir bakış götürüyor eskilere...

Anlam dolu maziyi anımsatıyor.

Sevilen hala sevildiğinden habersiz belki.

Ama sevgi terk etmiyor yüreği.

Ne zamanki yürek duracak, 

Sevgide o zaman ölecek! 

Sevgiliden habersiz başka yüreklere sığınacak,

Büyüyecek,büyüyecek kücük bir cocuk gibi...

Ama unutmayacak hicbir zaman sevgilinin degerini.!', 'İnsan kaybedince anlıyor değerleri. Ulaşamayınca anlıyor sevgilinin değerini. Özlüyor,umut ediyor geri gelmesini. Dönmek istiyor gecmişe, Ya...', ARRAY['Türk Edebiyatı','Şiir','Miraç Durmuş']::text[], 8.5, '{"poet":"Miraç Durmuş","poet_slug":"mirac-durmus","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sevgiliye-125-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dön', 'don-mirac-durmus-5p2vp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yarası saklı bir aşktı bizimki.

İçten duygularla bezenmiş,

Tüm güzelliklerle süslenmiş bir aşk...

Zaman bize her şeyi verdi,

Aşkı,Sevgiyi...

Tek bedende bir olmayı öğretti,

Gün geldi,Ayrılığımızın sebebi oldu zaman,

Kopuş başladı,Kalpler ayrıldı,

ßir fırtına gibi geldi ve herşeyi darmadağın etti...

Yürek bedeni terketti,Gidişinin ardından,

ßekliyorum,bir gün yüreğim geri dönecekmiş gibi...

Ne olur dön,Zaman kalmadı.!', 'Yarası saklı bir aşktı bizimki. İçten duygularla bezenmiş, Tüm güzelliklerle süslenmiş bir aşk... Zaman bize her şeyi verdi, Aşkı,Sevgiyi......', ARRAY['Türk Edebiyatı','Şiir','Miraç Durmuş']::text[], 8.5, '{"poet":"Miraç Durmuş","poet_slug":"mirac-durmus","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/don-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düz en|eğri en|benzey en|del en|diren en|körele en| en kırılmaları', 'duz-en-egri-en-benzey-en-del-en-diren-en-korele-en-en-kirilmalari-zafer-zengin-etnika-509j2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'düz en  | eğri en  |  benzey en  |  del en  |  diren en |  körele en |

kopandan arta kalanları toplama zamanı

saçmalamanın keskinliği

şartlanmalara bakış

deşme -

ve lanet olası adım         larınız

motorlu taşıtlarla attığınız

yüzlerce kilo

kilolarca acının hatırası

oysa

kimseyi ezmediniz otoyol            da

ne bir geyik

ne inek

ne de karşıya geçen bir köylü

çoğundan çok

bir sürü ömür

her yürek devrimci bir hücredir*



güya adaletliymiş azrail

vakti zatın da geleni alırmış

iki lahana ve ben güldüm buna

ve bir yandan da çırpındı karadeniz

onunda içine ettiniz

sizi ne kurtaracak biliyor             sunuz

bizden alacağınız dua

etmeyeceğiz atmosfere saldığınız gaza

gaz vermekle aynı yola

baş koymayacağız yalnızlığınıza

güya işi biliyor                 lar                    ya

çalıştık kazandıkla

çok mal bin canı almak        la

çok laf bin canı yakmak            la

dualarınız incitici

bizi değil bildiğinizi

kahpe yalanlarınızı 

sokamazsınız altını

sahi 

en son ne zaman aşık olmuş          tunuz

ne zaman korkuyu anlamış

açlığı yaşamış               tınız

biz biliyoruz

karnınız tok        ken

incinmeyin

gerçek şiir

işbirlikçi zulüm

nefretle

yakasına yapış       ır

sonra ayır          ır

atılmış

geri adım        lar

ve lanetlerin peşinde düş           ler

yer yok

nereye gidecek         ler      de     ler

tekil kendini ezer

dayatma

duruyor yazı

da

20 09 2005

Atılan her adım bir az daha çalıyor bizi insanlıktan.. tiksindim medeniyetten.

İç kanaması olanı karga tulumba hastanelere götürmek, o hastane senin bu benim

gezdirmektir cahil medeniyet.. Suyu bile bırakmazlar yatağında akmaya, İlk fırsatta

işerler içine..Aşağılarda bir yerde çamaşır yıkanır..Çocuklar çimer.. Hayvanlara su verilir.

Bahçe bostan sulanır ve kan karışır kimi yerde.. Halen memleketimin doğusunda, batısında

lağım suyu içen insanlarım varken.. damacana suyunun tadını beğenmeyen

medeniyetin içindeyim.. onlara benziyorum artık.. normalleşiyorum.. normal leşi yiyorum

ne kadar çok iğrenç olursam, ne kadar iğrenç olursak o kadar iyi diyorum.

dedim de.. seni anımsadım can baba..bu yaz uğramadım mezarına, toprağına bağışla.. anlarsın işte insanlık hallerini.. öpüyorum gözlerini.. eywallah.

.', 'düz en  | eğri en  |  benzey en  |  del en  |  diren en |  körele en | kopandan arta kalanları toplama zamanı saçmalamanın keskinliği şartla...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":67,"source_url":"https://www.antoloji.com/duz-en-egri-en-benzey-en-del-en-diren-en-korele-en-en-kirilmalari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yine Sen', 'yine-sen-mirac-durmus-hth3y', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Artık sana başka bakıyor gözlerim,

ßaşka süzüyor.

Ellerim uzanmak istiyor resmine,Tutmak istemiyor.

Her tutuşta bir acı,Her bakışta bir sızı var resminde...

Uzak olmak istiyor sana yüreğim.

Ağlamak istemiyor gözlerim,yaş dökmek istemiyor uğruna,

Gururum engel artık Sana.

Terkedilişin intikamı mı bu,çözemez oldum.

Artık yüreğimle değil,

Mantığımla düşünür oldum.

Yine Sen engel oluyorsun,

Yine Sen cıkıyorsun Karşıma,

Yine Sen,Yine Sen...

Git artık düşlerimden.

ßırak artık umutlarımı...

ßırak artık,ßırak...                                                                            

Yine 2 damla yaş düştü gözümden,

Biri senin uğruna,biri çaresizliğime...

Yine ağlattın,Yine kanattın ßu yüreği,

Yine yaptın yapacağını.

Yine acı,Yine Sızı...

Yineler Yineleniyor,

Yine Sen yoksun,Yine...', 'Artık sana başka bakıyor gözlerim, ßaşka süzüyor. Ellerim uzanmak istiyor resmine,Tutmak istemiyor. Her tutuşta bir acı,Her bakışta bir sızı...', ARRAY['Türk Edebiyatı','Şiir','Miraç Durmuş']::text[], 8.5, '{"poet":"Miraç Durmuş","poet_slug":"mirac-durmus","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/yine-sen-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sürpriz İroni', 'surpriz-i-roni-aynur-uluc-joris', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sürprizlerle gelen günleri seviyorum. Hele bir şeyleri artık öyle değil, böyle yapmaya karar verdiğimiz zamanlarda, bize akla gelmeyen bambaşka yaklaşımlar sunan günleri daha da çok. Yaşamda böylesi günlerin varlığı, yenilerinin de olabilme ihtimalini müjdeliyor çünkü bir yanıyla. Sürprizler, yeni yaklaşımlara olan hevesli açlığımızı sembolize ediyor.

''Okuyucu olmak ciddi iştir'' diye düşünüp bu konuda bazı sonuçlar çıkarmıştım kendime. Düşündüm ki; bir kitap okunduğunda onun içindekileri beynine yerleştirmek gerek. Ve buna yardımcı olması adına, bazı satırların altını çizip, yanına çiziktirmeli cümlelerin çağrıştırdığı birikimleri. Öyleyse ilk koşul; kitap kendimizin olmalı.

İşte bu düşüncelerle yoğunlaşmışken aklıma Nietzche geldi. Diyordu ki ''Yeni bir kitap, yeni bir yaklaşım getiremiyorsa onun iyiliğinden nasıl söz edilebilir? '' 

Okuyucu rolümü usul usul bu düşünceler ışığında değiştirmeye soyunurken; ilk kez kâğıt üzerinde doyasıya kalem oynatabilmek amacıyla bir kitap seçtim kendime ve gidip satın aldım onu: Virginia Woolf`ün Mrs. Dalloway`i.

Oysa, bu kitabın ilk sayfasının  ilk satırında sürpriz bir cümle bekliyordu beni:

''Felsefe bir romana yedirilmemişse, bir cümlenin altını kurşun kalemle çizebiliyorsak, güvenle diyebiliriz ki ya felsefede bir yanlışlık vardır, ya romanda, ya da ikisinde birden.'' 

Önce derin bir nefes alarak, yeniden ve en baştan mı başlamalı düşünmeye? Bu konuda çıkabilecek yepyeni bir sürprizin şimdilik hangi kapının altında olabileceğini de düşünmelerime katarak elbette.

Aynur Uluç

Mor Taka Edebiyat Dergisi

2006 -Sayı 6', 'Sürprizlerle gelen günleri seviyorum. Hele bir şeyleri artık öyle değil, böyle yapmaya karar verdiğimiz zamanlarda, bize akla gelmeyen bamba...', ARRAY['Türk Edebiyatı','Şiir','Aynur Uluç']::text[], 8.5, '{"poet":"Aynur Uluç","poet_slug":"aynur-uluc","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/surpriz-ironi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aldanışım', 'aldanisim-mirac-durmus-k9vmy', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sevdin sanmıştım yanılmışım,

Benimsin sanmıştım aldanmışım,

Aldanışım,Yanılışım kahretti beni...

Çok sevmiştim seni.

İçimde kanayan bir yarasın artık.

Seni düşündükçe derinleşen ßir yara...

Hiç bir ilaç çare olamıyor bendeki sana.

Tek isteğim var şu dünyada.

İlacım ol,benim ol,dünyam ol...', 'Sevdin sanmıştım yanılmışım, Benimsin sanmıştım aldanmışım, Aldanışım,Yanılışım kahretti beni... Çok sevmiştim seni. İçimde kanayan bir yara...', ARRAY['Türk Edebiyatı','Şiir','Miraç Durmuş']::text[], 8.5, '{"poet":"Miraç Durmuş","poet_slug":"mirac-durmus","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/aldanisim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşünce', 'dusunce-alper-kuruk-eyvxl', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Düşünce,düşünce,düşünce...

Korkuyorum ne olur benim hâlim? 

Ben yatağa  düşünce...

Ben toprağa düşünce...

Nerde kalır düşünce?', 'Düşünce,düşünce,düşünce... Korkuyorum ne olur benim hâlim?  Ben yatağa  düşünce... Ben toprağa düşünce... Nerde kalır düşünce?...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/dusunce-46-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şu yanım y a r a /günce kırılmaları...', 'su-yanim-y-a-r-a-gunce-kirilmalari-zafer-zengin-etnika-gvy6y', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '.

| ne yalanım var..özledim iç’imden

derler ya burnumda gözümde yüreğimde tütüyorsun

sonra bir yerler yanıyor.. eriyen kar suyu düşüyor boğazıma çatılardan

sonra kırıyorum kanatlarımı..sürüyorum ocağa.. yanıyor

köz olmadı. serçe külü az.. teberik diye dağıtılıyor bozkırlar da

kara sevdalılara ermiş derler.. türbe yaparlar bizim oralar da|

yalanmış ateş

iç’te yanandan gayrı

varsa

sal suyuna al

gösterme karşı yakayı

düşünsün ömrüm

ateş su toprak ne der

adem havva’yı

neresinde öper

| içi’imde büyüdüm kendimce.. her yaş

biraz daha yakın ölüme.. desem inanmazsın

ölüm canlı bir şey.. öldüğünü görmedim |

gidelim

zulüm uğramış buralara

haber verelim

gülün kırılmış boynuna

sen ölme 

adsız kalır buralarda

teberiğe renk katarlar al’ıda

nerede

nasıldır 

kim avutur yalnızlığı

kim saklar iç çocuğunu

oyunların kuytusuna

oyuncak mı

saklar her parçasında

düşüyorum elbet şiirlerimin içine

şairler yazıyor

kazıyorum kendimi

akıl çalan dizelerde

şu yanım yara

dikişten gayrı tüysüz

yetim hakkı ayrılık

çalanı yok sahipsiz

ikiye bölsem

biri bana

biri bana

nasıl anlatırım

özlerken ağlamayı sana

özledim ya

diyorum rengi nasıl

kış gelmiş memleketime

kar ne renk yağar

yağmur ne renk orada

| diyorlar |

bahçede solar güller

kırılmış kalemi

düşmüş yere

her yer çiçek

yazdıkça kökleri dirilecek

çivilenmek kendi içine

bile bile

çeke çeke

söküp atsan

kemik kalmaz elinde

sırf yazmanın adına

bağışladım güz’üde

dökülmez harflerimi

şiir dizerim geceye

acıma ilişme

senle güzel böyle

| dün döndü düşündüm

düşündüm döndü dün

düşündüm

düş/t/ün |

akla gelmez

hesap tutmaz suyun rengi

rengin gibi gözlerimin feri

sözüm kesildi

dal düştüm toprağa

ateş ek

köz sür elime

iç’im yanmasın

alev taşı bakışınla

yara ismin

kan taşının ucunda

kireç tutmuş dişlerin

| bana bıçak getirin |

gidelim

zulüm uğramış buralara

renk verelim gülün gözyaşına

bağışlasın bizi

ah ne fayda

can ne fayda

26 11 2004

Felaketler görmeye alışamadım.. başka acıları kabuldeki rahatlık

o genişlik aklıma geldikçe küsüyorum iç’ime.. umut kalmıyor çocuk,

gidesim tutuyor hani anlattığım yerlere, gidiyorum hep birileri benden

önce davranıyor.. Yıkılmak da nafile artık, yere bile düşsen yine oradasın

Bir rüzgar gelse diyorsun, alıp götürse, can taşımak bile rüzgara büyük işkence.

Böyle diyor, anlıyor ve susuyorum.. en’ler dağılıyor elimde..  sevenlere akıl

veriyorum, kendime veremiyorum.. korkuyorum bu teslimiyetten..korkuyorum.

.', '. | ne yalanım var..özledim iç’imden derler ya burnumda gözümde yüreğimde tütüyorsun sonra bir yerler yanıyor.. eriyen kar suyu düşüyor boğa...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":100,"source_url":"https://www.antoloji.com/su-yanim-y-a-r-a-gunce-kirilmalari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Garip', 'garip-alper-kuruk-ui6ds', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Garip,garipliğini akşam olunca anlar

Dünyadaki tüm hüzünler çöküverir ruhuna.

Gülmeyi unutur dudakları

Gözleri ağlar,içi ağlar.

Garibin türküsü aşk üstünedir

Öbür türküleri neylesin garip? 

Bir de gurbet şarkılarından hoşlanır gönlü.

Garbi öldüren ah bu gecelerdir...

Garip,garip,garip,

Gönlü muzdarip,kalbi muzdarip...', 'Garip,garipliğini akşam olunca anlar Dünyadaki tüm hüzünler çöküverir ruhuna. Gülmeyi unutur dudakları Gözleri ağlar,içi ağlar. Garibin türk...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/garip-34-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öğüt', 'ogut-mehmet-ayhan-gunaydin-drx28', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ÖĞÜT

Daima ileriye bakacaksın! 

Derdi,

Rahmetli dedem.

Çünki; 

Gelişmenin temeli budur.

Ama,

Arada bir,

Geriye de döneceksin,

Nereden geldiğini bilmek için.

ADAMLIĞIN GEREĞİ DE BUDUR! 

Öğüdünü aldım.

Oğluma da aktardım.

Ruhun huzur bulsun,

Mekanın cennet olsun.

Sevgili dedem.

M. Ayhan Günaydın.

    15 Aralık 2004

         Ankara', 'ÖĞÜT Daima ileriye bakacaksın!  Derdi, Rahmetli dedem. Çünki;  Gelişmenin temeli budur. Ama, Arada bir, Geriye de döneceksin, Nereden geldiğ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ayhan Günaydın']::text[], 8.5, '{"poet":"Mehmet Ayhan Günaydın","poet_slug":"mehmet-ayhan-gunaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/ogut-38-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneş', 'gunes-mehmet-ayhan-gunaydin-de555', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'GÜNEŞ

Doğuşun başka,

Zevalin başka,

Batışın bir başka güzel.

Ah ki güneş,

Bence seyrin, 

Bir ömre bedel.

O güneş ki; 

Bana hep geleceği anlatır.

O güneş ki; 

Batarken bana hep, 

Ölümü hatırlatır.

M. Ayhan Günaydın.

  28 Temmuz 2005

          Ankara', 'GÜNEŞ Doğuşun başka, Zevalin başka, Batışın bir başka güzel. Ah ki güneş, Bence seyrin,  Bir ömre bedel. O güneş ki;  Bana hep geleceği anla...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ayhan Günaydın']::text[], 8.5, '{"poet":"Mehmet Ayhan Günaydın","poet_slug":"mehmet-ayhan-gunaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/gunes-52-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bak...bu şiirde sen varsın', 'bak-bu-siirde-sen-varsin-zeynep-aydinlioglu-73m5n', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'sen varsın şiirimde, 

ellerin, 

gözlerin...ve tatlı tebesümün. 

bu şiirimin omurgası sensin. 

ışıl ışıl bakışların. 

aşk dolu sözlerın 

kaçamak dokunuşların var. 

mum gölgelerinde 

masumca süzüşün, 

duman duman oluşun var. 

seni... benden alamayışın, 

titreyen kalbinle.. 

dans edışın var. 

ellerimi her defasında... 

sıkıca kavrayışın var. 

bu şiirde... 

sana olan hasretim... ve özlemim var...', 'sen varsın şiirimde,  ellerin,  gözlerin...ve tatlı tebesümün.  bu şiirimin omurgası sensin.  ışıl ışıl bakışların.  aşk dolu sözlerın  kaça...', ARRAY['Türk Edebiyatı','Şiir','Zeynep Aydınlıoğlu']::text[], 8.5, '{"poet":"Zeynep Aydınlıoğlu","poet_slug":"zeynep-aydinlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bak-bu-siirde-sen-varsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düş''ün''ce Gözden', 'dus-un-ce-gozden-cihan-kaya-r6tvx', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gece gezmesine barışkın aşık,

Kavuşma zamanı düşünce gözden...

Nice bezmesine alışkın kaşık,

Buluşma tam anı, düşünce gözden...

Gözler aşkı kusar, gökte yıldızken

Yağmur gibi yağar, rahat yalnızken

Damla damla parlar yaşlı yaldızken

Rahatlık dermanı düş''ünce gözden...

Her an mutlusundur, yarinden ırak

Kararınca dünyan üzülmek yasak

Hayal özgür kalsın, gerçeği bırak

Umudun harmanı düş''ün''nce gözden...

Dert seni kovalar tezin olmazsa

Kar sevgi yarına yazın olmazsa

Kim dinler sözünü sazın olmazsa

Dil susar fermanı, düşün''ce gözden...

Cihan''da acımaz, acı acıdan

Kur''an''da söylüyor, kork yalancıdan

Değer alemini, almaz hancıdan

Güzelin yamanı, DÜŞÜNCE GÖZDEN....', 'Gece gezmesine barışkın aşık, Kavuşma zamanı düşünce gözden... Nice bezmesine alışkın kaşık, Buluşma tam anı, düşünce gözden... Gözler aşkı ...', ARRAY['Türk Edebiyatı','Şiir','Cihan Kaya']::text[], 8.5, '{"poet":"Cihan Kaya","poet_slug":"cihan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/dus-un-ce-gozden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstediğim Evren', 'i-stedigim-evren-alper-kuruk-cs5ic', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bazan öylesine duymak isterim evreni

Seslerden bir buket olmuş,

Aşk fısıltılarıyla coşkun

Doğan güncesine yeni.

Öylesine görmek isterim bazan

Evreni bir kuş kanadında

Taşınabilsin heran

Sevapkâr insanlarcasına hafif...

Benim bildiğim evren böyle değil! 

Bir dünyasında kızılca kıyamet,

Bir insanının başı tonlarca ağır düşünceden.

Oysa benim evrenim iyiliklerle hafif

Benim evrenim güzelliklerle kurulu.

Sen benim istediğim gibi bir evren de yaratabilirsin Tanrı''m

Tüm insanlarına iyilik ver önceden

Ki böylesine bir evren isterdim ben...', 'Bazan öylesine duymak isterim evreni Seslerden bir buket olmuş, Aşk fısıltılarıyla coşkun Doğan güncesine yeni. Öylesine görmek isterim baza...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/istedigim-evren-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkım Gidiyor', 'askim-gidiyor-yakup-icik-cwnnr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Öyle mi güzelim? 

Beni terk edip gidiyorsun.

Hadi git, git..

Allahaismarladik.

Sahi son bir defa,

Dönüp bakmadan mi gidiyorsun? 

Hadi git.

Ama ne olur,

Bir kac adim at sonra dur! 

Dur ve dön bir bak bana.

Sana yalvaran,

Bu bakislarimida mi görmüyorsun? 

Öyle olsun güzelim..

Bensiz günün mutluluk olsun.

Hadi git.

Yolun acik olsun!', 'Öyle mi güzelim?  Beni terk edip gidiyorsun. Hadi git, git.. Allahaismarladik. Sahi son bir defa, Dönüp bakmadan mi gidiyorsun?  Hadi git. A...', ARRAY['Türk Edebiyatı','Şiir','Yakup Icik']::text[], 8.5, '{"poet":"Yakup Icik","poet_slug":"yakup-icik","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/askim-gidiyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz Yine Akşam Oldu', 'sensiz-yine-aksam-oldu-i-sa-tekin-hrmbn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sensiz yine akşam oldu

Her yer karanlık

Beynimde binbir soru

Yüreğim sancıyor

Yanımda değilsin

Sensiz hayal kuramıyorum

Geceler kara

Sensizlikten yana 

Bir boşluktayım

Sağa dönüyorum faydası yok

Sola dönüyorum nafile

Sensizlik vurmuş beni

Gözlerim kan çanağı

Unutmak istiyorum

Yatmak istiyorum

Off be of..

İtiraf ediyorum

Sensiz Olmuyor

Akşamlar sensiz

Kapkara

Akşamlar sensiz olmuyor

Off be of..

Bu karanlık gece bitmiyor 

Sensiz yine akşam oldu', 'Sensiz yine akşam oldu Her yer karanlık Beynimde binbir soru Yüreğim sancıyor Yanımda değilsin Sensiz hayal kuramıyorum Geceler kara Sensizl...', ARRAY['Türk Edebiyatı','Şiir','İsa Tekin']::text[], 8.5, '{"poet":"İsa Tekin","poet_slug":"i-sa-tekin","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sensiz-yine-aksam-oldu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yine Yaz Başladı', 'yine-yaz-basladi-alper-kuruk-bjt0a', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bülbül için gül neyse benim için sen osun

Bülbül mutlu olmadı,bırak şu gönlüm olsun.

Mutsuzluğu terennüm ediyorken şarkılar

İnsanlar şarkılardan neden teselli arar? 

Sevgi denizlerinde boğulmadan yüzelim

Hıdırellez gününde biz kırlarda gezelim.

Aşkı yaratan Tanrı acıyı yaratmamış

İnsanlar kendileri tatlıya acı katmış.

Akıl,aşkı emreder perişanlığı değil

Eğilmek istiyorsan aşkın önünde eğil.

Paraya,pula tapma tapacaksan aşka tap

Aşkın yaratıcısı,aşkın kendisidir Rab.

Hâlâ aşk arıyorsan çıkmaz yola girersin

Sana olanlar olmuş,müstehakını versin...', 'Bülbül için gül neyse benim için sen osun Bülbül mutlu olmadı,bırak şu gönlüm olsun. Mutsuzluğu terennüm ediyorken şarkılar İnsanlar şarkıla...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yine-yaz-basladi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ç a ğ ı r a n K i m?', 'c-a-g-i-r-a-n-k-i-m-ayse-gul-2709w', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gözlerin bulut topluyor

penceresi açık

anılara uçuyor kanatlı düşlerin...

Kim bu,

yalnızlığının kapısını aralayıp

seni geçmişe çağıran? ...

Çocuk ayaklarını okşayan

martı gülüşlü denizin dalgaları mı? 

Her düşüşünde yüreğiyle seni yerden kaldırıp

acılarını öpen o yüce insan mı? 

Sevdalarını şarkılayan eski baharlar

İz sürdüğün yorgun umutlar

Adreslerinde bulunamayan dostlar

Emanet edemediğin bekleyişler

Sırlanmış hayatların gözlerindeki son vedalar mı? 

Kim bu,

şimdi

seni çağırıp

gözlerinin renginde ağlatan? ...

04/10/005 İst. A.G.Nisan_ca', 'Gözlerin bulut topluyor penceresi açık anılara uçuyor kanatlı düşlerin... Kim bu, yalnızlığının kapısını aralayıp seni geçmişe çağıran? ... ...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Gül']::text[], 8.5, '{"poet":"Ayşe Gül","poet_slug":"ayse-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/c-a-g-i-r-a-n-k-i-m-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşıklara', 'asiklara-i-sa-altunbay-0x2je', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İnsan denen kitabın sayfalarıyız

Kalbimiz deli çarpar ama temizdir

Hayat yelkenlisinin tayfalarıyız

Ölüme kürek çekmek adetimizdir

Hayal katillerine vermeyiz aman

Kaf dağına deh deriz binip sırtına

Dıştan görünüşümüz belki süt liman 

Ama yüreğimizde kopar fırtına

Uyanın ey aşıklar aşk sekaratta

Kalp merdivenlerinden ayağa düştü

Düşerken takıldığı her basamakta

Üstüne yarasalar itler üşüştü', 'İnsan denen kitabın sayfalarıyız Kalbimiz deli çarpar ama temizdir Hayat yelkenlisinin tayfalarıyız Ölüme kürek çekmek adetimizdir Hayal kat...', ARRAY['Türk Edebiyatı','Şiir','İsa Altunbay']::text[], 8.5, '{"poet":"İsa Altunbay","poet_slug":"i-sa-altunbay","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/asiklara-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dev Cüceler', 'dev-cuceler-alper-kuruk-oy0fl', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İnsan yükselir olur 

Erişilmez bir yüce,

Alttan baksan doğrudur

Üstten bak gör bir cüce.

İşbu dev cücelerdir

Dünyamızı yöneten,

Gün susup gecelerdir

Baykuşlar gibi öten...', 'İnsan yükselir olur  Erişilmez bir yüce, Alttan baksan doğrudur Üstten bak gör bir cüce. İşbu dev cücelerdir Dünyamızı yöneten, Gün susup ge...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/dev-cuceler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umutsuzdu Gelecek', 'umutsuzdu-gelecek-ahmet-nural-ozturk-yxlu5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Benim için herşey bir başkaydı 

Rüzgarı afet

Baharı felaket

Yazı otsuz

Kışı çulsuz

Umutsuzdu gelecek

Seni sensiz gördüğümde bu memleket

Ve ben onaltısındaydım

Otuzyedi yıl geçti aradan

Söyle Allah aşkına

Yanıldık mı acaba..', 'Benim için herşey bir başkaydı  Rüzgarı afet Baharı felaket Yazı otsuz Kışı çulsuz Umutsuzdu gelecek Seni sensiz gördüğümde bu memleket Ve b...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Nural Öztürk']::text[], 8.5, '{"poet":"Ahmet Nural Öztürk","poet_slug":"ahmet-nural-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/umutsuzdu-gelecek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nihan', 'nihan-i-sa-altunbay-y4mg9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Nasıl bir akşam ki bu şafağı sökmez 

Düştüğüm bu kuyunu dibi gözükmez

Dipsiz kuyu korkusu Yusuf a sökmez

Düşüme gir,uykumu böl,beni uyutma

İmkansızım,tek sevdiğim beni unutma

İrademi kaybedeli epey çok oldu

Fırsat bildi art niyet cana sokuldu

Kurduğum bütün düşler bir bir yok oldu

Gidişini düşündükçe tutuyor sıtma

İmkansızım,tek sevdiğim beni unutma

Hayat buldum gözlerinde içim bir başka

Ölüm mü? Sensizlik mi? Seçim bir başka

Sevgiliye,vuslata açım bir başka

Düşünü bari benden uzakta tutma

İmkansızım,tek sevdiğim beni unutma

Ayrılık kavuşmanın başlangıcıdır

Aşk ne ki unutulmak aşktan acıdır

Gurbet gönülde yara aşk ilacıdır

Bırak kasın gözyaşım sakın kurutma

İmkansızım,tek sevdiğim beni unutma

Nur yüzlüm vuslat yakın buna iman et

Yalnız Hak tan yardım iste,O na aman et

Olasın canım sevdiğim Hak a emanet

Öyle bir yaşam sür ki Rabia yı aratma

İmkansızım,tek sevdiğim beni unutma', 'Nasıl bir akşam ki bu şafağı sökmez  Düştüğüm bu kuyunu dibi gözükmez Dipsiz kuyu korkusu Yusuf a sökmez Düşüme gir,uykumu böl,beni uyutma İ...', ARRAY['Türk Edebiyatı','Şiir','İsa Altunbay']::text[], 8.5, '{"poet":"İsa Altunbay","poet_slug":"i-sa-altunbay","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/nihan-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akilli Kalem', 'akilli-kalem-yurdagul-kurnaz-jvu82', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yazmak 

Icin

Yazmaya

Durmus

Birde

Baktim 

Kalem 

Susmus

Akilli

Kalem

Ben 

Huysuzmus

Inat 

Etti

Artik

Yazmiyor_mus! 

YK/ 03.20

06.10.2005', 'Yazmak  Icin Yazmaya Durmus Birde Baktim  Kalem  Susmus Akilli Kalem Ben  Huysuzmus Inat  Etti Artik Yazmiyor_mus!  YK/ 03.20 06.10.2005...', ARRAY['Türk Edebiyatı','Şiir','Yurdagul Kurnaz']::text[], 8.5, '{"poet":"Yurdagul Kurnaz","poet_slug":"yurdagul-kurnaz","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/akilli-kalem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Izdırap...', 'izdirap-ulug-celik-g3niw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hangi dala uzansam

Ol dal kuruyor.

Hangi gülü tutsam 

Ol gülün dikeni batıyor.

Hangi kavşağa girsem

Yolum çıkmaza sapıyor.

Bu ne ızdırap ya Rab! ...

Beni benden alıyor...', 'Hangi dala uzansam Ol dal kuruyor. Hangi gülü tutsam  Ol gülün dikeni batıyor. Hangi kavşağa girsem Yolum çıkmaza sapıyor. Bu ne ızdırap ya ...', ARRAY['Türk Edebiyatı','Şiir','Uluğ Çelik']::text[], 8.5, '{"poet":"Uluğ Çelik","poet_slug":"ulug-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/izdirap-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sayın fanatikler.', 'sayin-fanatikler-zeynep-aydinlioglu-yq1xn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'sesimizi  alkışlarla  tenpo  tuturduk 

ofsayıt dedik, penaltı dedik  haykırdık 

takım gol yıiyince küfrü  savurduk 

heryerde saygın olalım...sayın fanatikler.... 

yeşil saha heyecan verdi  yerimizden fırladık, 

sakince izleyelim...bitmesin   insanlık, 

faydası varmı bılmem,  kafa göz kırdırdık, 

maç,  heyecanı zarasız olsun sayin   fanatikler.... 

izlerken takımımıza gücümüzü  hissetıirelim 

zarar vermeden trbünde.temmpo tutalım 

biz, sadece atılan golleri   sayalım 

mücadele   alkış  ister sayın fanatikler....', 'sesimizi  alkışlarla  tenpo  tuturduk  ofsayıt dedik, penaltı dedik  haykırdık  takım gol yıiyince küfrü  savurduk  heryerde saygın olalım.....', ARRAY['Türk Edebiyatı','Şiir','Zeynep Aydınlıoğlu']::text[], 8.5, '{"poet":"Zeynep Aydınlıoğlu","poet_slug":"zeynep-aydinlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sayin-fanatikler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tatlıdır', 'tatlidir-mevlut-i-hsani-7j765', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Münevver adamın hoş latifesi,

Demeki arının balı tatlıdır.

Beslemez kemiği, olmaz hilesi.

Fakir bile olsa, dili tatlıdır.

      Namerdin yanından varıpta geçme

      Anlatma derdini,  sırrını açma

      Suyu kevser ise, eyilip içme.

      Akan derelerin seli tatlıdır.

Görmezmisi bu dünyanın halini.

Çekme namertlerin kalmakalını.

Yeme muhammetin dalak balını.

Kadir bilenlerin külü tatlıdır.

        Mevlüt keder etme olursun hilalal. 

        Lütfundan etmesin bizi zülcelal.

        Varmıdır hiç buna uyacak ahval.

        Hepsinden hak cemali tatlıdır', 'Münevver adamın hoş latifesi, Demeki arının balı tatlıdır. Beslemez kemiği, olmaz hilesi. Fakir bile olsa, dili tatlıdır.       Namerdin yan...', ARRAY['Türk Edebiyatı','Şiir','Mevlüt İhsani']::text[], 8.5, '{"poet":"Mevlüt İhsani","poet_slug":"mevlut-i-hsani","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/tatlidir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilalini hiç düşünmedinmi ya', 'bilalini-hic-dusunmedinmi-ya-bilal-altuntas-ozjed', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Eskiden sen yokken sevgilim,

Ellerim yüreğimden önce üşürdü.

Hayalle seni yaşayan bu kalbim,

Sensizliğe nasıl alışacağını düşünürdü.

Eskidendi sevgilim o eskidendi,

Bir mavi gökyüzüm vardı hiç solmayan,

Birde senin maviye çalar gözlerin,

Şimdi ne mavi gökyüzüm var,

Nede maviya çalan o deniz gözlerin.

Bu gece ilk defa sevgilim,

İlk,sensizliğe içiyorum! 

Bu gece hayatımda sevgilim,

İlk kez kendimden geçiyorum! 

Sen bana emanetmiydin? 

Yoksa mavi bir rüya.

Bir anda nasıl gittin? 

Bilalini hiç düşünmedinmi ya?', 'Eskiden sen yokken sevgilim, Ellerim yüreğimden önce üşürdü. Hayalle seni yaşayan bu kalbim, Sensizliğe nasıl alışacağını düşünürdü. Eskiden...', ARRAY['Türk Edebiyatı','Şiir','Bilal Altuntaş']::text[], 8.5, '{"poet":"Bilal Altuntaş","poet_slug":"bilal-altuntas","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bilalini-hic-dusunmedinmi-ya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadehimde Sen', 'kadehimde-sen-erkan-kocak-y5kdd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Nerden düştün şimdi durup dururken gönlüme

Oysa sigaramı söndüreli çok olmuştu

Pencereyi  de kapatmıştım 

Rüzgarda koklamamak için saçlarını

Ne gereği vardı ki şimdi usulca sokulmanın aklıma

Ne gereği vardı şişenin dibindeki son yuduma saklanmanın

Nasılsa bu şişe de bitecek

Nasılsa son kadehimin son yudumunda sileceğim seni yine

Belki gereksiz bir şarkı eşlik edecek sana

Belki ellerimde hissedeceğim saçlarını

Yada en fazla bir sigara daha isteyecek canım

Ama dedim ya son kadehin son yudumunda

Sileceğim kokunu odamdan................................................', 'Nerden düştün şimdi durup dururken gönlüme Oysa sigaramı söndüreli çok olmuştu Pencereyi  de kapatmıştım  Rüzgarda koklamamak için saçlarını...', ARRAY['Türk Edebiyatı','Şiir','Erkan Koçak']::text[], 8.5, '{"poet":"Erkan Koçak","poet_slug":"erkan-kocak","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kadehimde-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tanrı''nın dizinin dibi', 'tanri-nin-dizinin-dibi-sait-muharrem-say-chvz1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dolaşıyorken bu sokaklarda

başka sokaklarda dolaşamadığım için ama

menzilimde hep beni beklediğini bildiğim

kirli raflarda 

hayatımın yaşanmamış aşk romanlarını

ve okumaya niyetim yokken

o loş ışıklarda

varsın beklesinler

Dolaşıyorken içimde ben

kıvrımlarında yaşadığım yaşamadığım 

kıyıların

biliyorum 

tanrıya yalan söylenmez

dolaşırken bu sokaklarda, kentlerde

ay ışığını döken kim? 

tanımasam da bana yakın bir kitap

ilahi dizgelerle kutsanmış

işi sevmek olan

bilgeler tanırım

Yine de

dizinin dibinde uyurum her gece tanrının

hep aynı cümle gelip takılan aklıma inadına

cehennemde yerim hazır

kabul edersen tanrım....

(7.10.2005)', 'Dolaşıyorken bu sokaklarda başka sokaklarda dolaşamadığım için ama menzilimde hep beni beklediğini bildiğim kirli raflarda  hayatımın yaşanm...', ARRAY['Türk Edebiyatı','Şiir','Sait Muharrem Say']::text[], 8.5, '{"poet":"Sait Muharrem Say","poet_slug":"sait-muharrem-say","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/tanri-nin-dizinin-dibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Feda ettim bilesin anne', 'feda-ettim-bilesin-anne-bilal-altuntas-3jbjn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hangi gündüz hangi gece,

Yaşamışım seninle anne? 

Unuttum dünü dünden önce,

Sen varmıydın yokmuydun anne? 

Bir resmin kalmış duvarda,

Oda solmuş sana benzemiyor anne.

Senden başka ne varsa,

Tek tek sildim attım bilesin anne! 

Bak büyüdü bu oğlun,

Büyüdüde ne oldu anne? 

Simsiyah saçlarını,

Bir bahar yeline,

Senin hayaline,

Bir gün gelmene,

Her gece yaş dökmeme

Günden güne erimeme

Ve sensizliğe,

Feda ettim bilesin anne! ...', 'Hangi gündüz hangi gece, Yaşamışım seninle anne?  Unuttum dünü dünden önce, Sen varmıydın yokmuydun anne?  Bir resmin kalmış duvarda, Oda so...', ARRAY['Türk Edebiyatı','Şiir','Bilal Altuntaş']::text[], 8.5, '{"poet":"Bilal Altuntaş","poet_slug":"bilal-altuntas","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/feda-ettim-bilesin-anne-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dost Yüzüdür...', 'dost-yuzudur-sait-muharrem-say-7yky7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dost yüzüdür hep aktığım 

aradığım

denizde dostumdur diyorum

gökyüzü de

ve dahi beraber doğurdukları

tüm ahu hayat zenginlikler

dost yüzüne yola çıktığımda

ve vardığımda

iklimsiz memleketlere

ne deniz var yanımda ne göküyüzü

hepsi tek parça güzel

ve hepsi

bir arada mutlu....

Ekim 2005', 'Dost yüzüdür hep aktığım  aradığım denizde dostumdur diyorum gökyüzü de ve dahi beraber doğurdukları tüm ahu hayat zenginlikler dost yüzüne ...', ARRAY['Türk Edebiyatı','Şiir','Sait Muharrem Say']::text[], 8.5, '{"poet":"Sait Muharrem Say","poet_slug":"sait-muharrem-say","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/dost-yuzudur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçindeki insanı dirilt', 'i-cindeki-insani-dirilt-i-lhami-arslantas-h29ur', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İncitirken fakir düşmüş bir canı,

Deme ki kötülük kar kalır bana.

Dirilt  içindeki  kutlu insanı,

Sanma ki dünyada yar kalır sana.

Tabiatın ortak havası suyu,

İşlediğin kusur eştiğin kuyu,

Varlık ile  yokluk bir nefes boyu,

Sanma ki her zaman sır kalır sana.

Sermayen cahilin aklını güder,

Canını eylersin emrinde heder,

Bir bak şu aleme her gelen gider,

Sanma ki servetten kâr kalır sana.

Üsküdarı geçmiş dörtnala atın,

Kefenine sığmaz uçağın yatın,

Küçültme kendini insan sıfatın,

Sanma ki beylikten ar kalır sana.

Sendeki insafı almalı satın,

Alıp ta atmalı dört yere sütun,

Hile üzerine  kurmuşsun çatın,

Sanma ki kovanda bar kalır sana.

Der İlhami hakka dönmek istersen,

Nefsini eğitip yenmek istersen,

Bir kez bizim gibi yanmak istersen,

Kocaman bir erdem kar kalır sana.', 'İncitirken fakir düşmüş bir canı, Deme ki kötülük kar kalır bana. Dirilt  içindeki  kutlu insanı, Sanma ki dünyada yar kalır sana. Tabiatın ...', ARRAY['Türk Edebiyatı','Şiir','İlhami Arslantaş']::text[], 8.5, '{"poet":"İlhami Arslantaş","poet_slug":"i-lhami-arslantas","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/icindeki-insani-dirilt-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hicrân', 'hicr-n-timur-i-likan-qskjq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Birgün gelirsin diye umutla beklerken yollarını

Hasretle arıyorum, bedenimi saran o güzelim kollarını

Aklıma sen düşünce, unutuyorum bütün dünyayı

Tek tek açıp okuyorum yazdığın aşk mektuplarını

Beni dertten derde,kederden kedere salan sevgilim

Sanki ben,artık o eski ben değilim

Bilmiyorum rüyâda mıyım,hayâllerde miyim ben nerdeyim

Söyle bana ne olur,sen nerdeysen ben de sana geleyim

Çekilmez oldu bu hicrân,kalbimde yaradır kanayan

Çölde bir çiçek gibiyim, aşkına yanmış susayan

Üstüne bir damla su düşmemiş toprak gibiyim kuruyan

Yağ benim çorak gönlüme,yeşersin yüreğim aşkınlan

Dertliyim dertli,derdim Kaf dağından da yüce

Hatıralar canlanır hep gözümde,o güzel resmini öpünce

Hayatımın akışı değişti birden,seni candan sevince

Durma gel hadi gel artık,boğ beni sevince

(6 Ekim 2005/İstanbul)', 'Birgün gelirsin diye umutla beklerken yollarını Hasretle arıyorum, bedenimi saran o güzelim kollarını Aklıma sen düşünce, unutuyorum bütün d...', ARRAY['Türk Edebiyatı','Şiir','Timur İlikan']::text[], 8.5, '{"poet":"Timur İlikan","poet_slug":"timur-i-likan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/hicran-34-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şeytan biraz melek, biraz şeytan', 'seytan-biraz-melek-biraz-seytan-murat-oner-7ajnk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Özlersin, vakti dolmaz idare edemezsin

Her doneme tutunamazsin, söz geçiremezsin

Yaşanamayanın kavgasını veremezsin 

Gider hayat bazan kenardan izlersin 

İçine sinmez hep geriye dönersin 

Orada bulursun ozunu kendini affedersin 

Şeytan biraz melek, melek biraz şeytan

Gülümsemezsen yenilenemezsin', 'Özlersin, vakti dolmaz idare edemezsin Her doneme tutunamazsin, söz geçiremezsin Yaşanamayanın kavgasını veremezsin  Gider hayat bazan kenar...', ARRAY['Türk Edebiyatı','Şiir','Murat Öner']::text[], 8.5, '{"poet":"Murat Öner","poet_slug":"murat-oner","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/seytan-biraz-melek-biraz-seytan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gurbette hüzünlü gecer Bayramlar', 'gurbette-huzunlu-gecer-bayramlar-ayse-alioglu-kmgkw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Iste dost bize gene hüzün düstü, 

Bize gurbetin kucaginda ayrilik 

Kaderimize herzaman ki gibi 

Anadan,Babadan ayri kalmak düstü 

Bugün bayram Vatanimda 

Cocuklar civil,civil sokaklarda 

Al Bayragim dalgalaniyor 

mavi gökyüzünde 

Senlik var senlik topragimda 

Gurbette hüzünlü geciyor Bayramlar 

Hüzün icine her zaman gözünün yasini katar 

Yavularimiz öz gecmislerinden cok uzaktalar 

Dedim ya dost hüzünlü kutlanir gurbette bayramlar.... 

                                                           30.08.2005', 'Iste dost bize gene hüzün düstü,  Bize gurbetin kucaginda ayrilik  Kaderimize herzaman ki gibi  Anadan,Babadan ayri kalmak düstü  Bugün bayr...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Alioğlu']::text[], 8.5, '{"poet":"Ayşe Alioğlu","poet_slug":"ayse-alioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/gurbette-huzunlu-gecer-bayramlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönlüm firarda', 'gonlum-firarda-ayse-alioglu-2ftca', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '[center][img src=''http://www.antoloji.com/siir/media/28/www_antoloji_com_580828_719.GIF''width=51 height=28][/center] 

Sormuyorum yikilip giden daglara, 

Neler oldu neler diye.. 

Tufanlar esti yagmurlar yagdi, 

Günül okyanusum dolup tasti.. 

Artik yazgünesi benim icin doguyor.. 

En güzel güller benim icin aciyor. 

Diktigim elma agacim yeseriyor 

Sevgi nehri benim topragimdan geciyor.. 

Firardayim beni kimse tutamaz, 

Rabbim verdi bu cani baskasi alamaz.. 

Ne kedere ne derde yer yok dünymada, 

Kurdum cennetimi yer veremem yikanlara... 

Gec olmadan ögrendim farkli sevmeyi, 

yasaklar koydum bütün engellere.. 

sarildim gönülden var olan degerlere, 

Yüregimde yazgünesi ellerimde bulutlar 

Sol cebimde yarinlarim sag cebimde umutlar 

Firardayim dostlar bir arzunuz mu var? ...

                            27.08.2005', '[center][img src=''http://www.antoloji.com/siir/media/28/www_antoloji_com_580828_719.GIF''width=51 height=28][/center]  Sormuyorum yikilip gid...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Alioğlu']::text[], 8.5, '{"poet":"Ayşe Alioğlu","poet_slug":"ayse-alioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gonlum-firarda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sesin solugun kesildi', 'sesin-solugun-kesildi-ayse-alioglu-22hts', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Rüzgar mi yakalayip götürdü yoksa seni 

Yagmurla yagip doprakla mi bulusacaksin? 

Günes olup sadece aynadan mi isitacaksin? 

Yar senin derdinden bak ne hallere düstüm 

Yandim bittim,kör oldum, yasarkan öldüm 

Senin sevdandan bu hale geldim 

Tutulurdu dilim konusamaz dim 

Ama seni görünce titrerdi yüregim 

Kara sevda denirmis bunun adina 

Kimseler care bulamaz bana 

Uzaktan sevdim uzaktan seni 

Söyleyemedim sana sevdigimi 

Ne kadarda cok isterdim bilsen 

Söylelemeyi sevdigimi 

Ama seni görünce titrerdi yüregim 

Tutulurdu dilim konusamaz dim 

                        12.05.05', 'Rüzgar mi yakalayip götürdü yoksa seni  Yagmurla yagip doprakla mi bulusacaksin?  Günes olup sadece aynadan mi isitacaksin?  Yar senin derdi...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Alioğlu']::text[], 8.5, '{"poet":"Ayşe Alioğlu","poet_slug":"ayse-alioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sesin-solugun-kesildi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tutsak düşlerim', 'tutsak-duslerim-elazigli-mustafa-kaya-u5bwm', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bir gül tomurcuğu sevgilim.

hayat gecemin,

alnımdaki şebnemim.

iki değirmen taşının,

arasında kalan, kuru

bir taneye döndüm,

sensizliğine kanayan ruhum 

ve seni bulamayan gözüm..

ben mi yorgunum

tutsak düşlerim mi..? 

Mustafa kaya

07.10.2005 / üsküdar

www.mustafakaya.net', 'bir gül tomurcuğu sevgilim. hayat gecemin, alnımdaki şebnemim. iki değirmen taşının, arasında kalan, kuru bir taneye döndüm, sensizliğine ka...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/tutsak-duslerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özle Beni', 'ozle-beni-ayse-alioglu-vmqh5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Iyilik canlisi iyi olan sensin 

Yeryüzünde var olan hurisin 

Yüregin kardan temiz lekesiz 

Gül yüzünde acan güllerin eksiksiz 

Felek senden yana olmasada 

Ela gözlerin yaslara bogulsada 

Caresizlik dört bir yani sarsada 

Sevgisizlik denizinde bogulsanda 

Bir gün elbet bir gün devir degisecek 

Bu felek elbet sanada gülecek 

Kutsal sevgi yollarina düsecek 

Yaninda olmasamda senden uzaklarda 

Bir gün gelecegim mutlaka sana 

Bekle sevdicegim yüreginde sevdanla 

Özle beni gelecegim sözüm var sana 

Özlemler ateslerinde yansakta 

Caresizlik kuyularina dalsakta 

Bu acilar tez vakitte son bulcak 

Sevenler sonunda hep kavusacak 

Sen ve ben gibi 

Özle beni sade özle 

Can evinde sakla beni 

Sevdanla bak büyüt beni 

Özle beni cünkü bende 

Özlüyorum seni...........

          08.05.2005', 'Iyilik canlisi iyi olan sensin  Yeryüzünde var olan hurisin  Yüregin kardan temiz lekesiz  Gül yüzünde acan güllerin eksiksiz  Felek senden ...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Alioğlu']::text[], 8.5, '{"poet":"Ayşe Alioğlu","poet_slug":"ayse-alioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/ozle-beni-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Size Havale Ediyorum...', 'size-havale-ediyorum-zulfikar-yapar-kaleli-xv9ze', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'font face=''Comic Sans MS'' color=''black'' size=''0,5''

Gerçek keremine susamış aslı 

Hareket debdebe ileri, geri 

Asalet müzelik şairde yaslı 

Isırgan güzeli, kaktüsün eri 

Baktıkça dövülür hislerin örsü 

Arından terledi önünde kürsü 

“Yepyeni bir ekol” reşidin tersi 

Bu yeni sirkatler onun eseri 

Anladım, asalet bir ile başlar 

Bir’siz kişilikler sıfırda kışlar 

Gönlün aynasıdır, gözdeki yaşlar 

Özünde cücelik, sözünde iri! 

Kahırlı aşk ile bir gülü sunan 

Olamaz mecnunun Leyla’sı inan 

Söz gönülden dile sıçradığı an 

Gönülden ziyade gözlerde yeri 

Kalkanı kaldırdım usulca yerden 

Ardından fareler sıçradı birden 

Mavileri sordum gözleri körden 

Kalbini karartmış gözünün feri 

Mukaddes kervandan kalınca arda 

Hecesi, sözcüğü, dizesi darda 

Dimağlara hitap, güzellik orda 

Aslı Kazanova, sureti peri! 

Çile ektim, keder bitti bağımda 

Bülbül baktım, karga öttü bağımda 

Kına yaktım, duman tüttü bağım

Bu “yarpuz güzeli” olduktan beri

Hırsın pençesinde çıldırmış akıl 

Akıl ki; darası üç aklaşmış kıl 

Ne bir gönle düşer, ne bilir okul 

“Yepyeni bir ekol” onun şiiri! ! ! 

Gurur sarayında ahmaklar yaşar 

Övünce; şımarır, kabarır, şişer 

Dostluk meclisinden aşağı düşer 

Sevgi, saygı ölü, sohbeti diri', 'font face=''Comic Sans MS'' color=''black'' size=''0,5'' Gerçek keremine susamış aslı  Hareket debdebe ileri, geri  Asalet müzelik şairde yaslı  I...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/size-havale-ediyorum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüregimdeki sevdamla', 'yuregimdeki-sevdamla-ayse-alioglu-xv9cl', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Nice zaman oldu ayriyim yardan 

Ey sevdigim söyle nerdesin simdi 

Yollarini gözler oldum güzüm yasiyle 

Yikildi ümütlerim gidemem simdi 

Hasretin yakip kavurur sinemi 

Günler gecmiyor beklerim ölümü 

Sensiz yasamin anlami yok ki 

Perisan halime yanarim simdi 

Gönül dinle beni yarimden ayleme 

Yarali yüregimle ölüme terk etme 

Garip halimle su gurbet elinde 

Yarimin haberini gözlerim simdi 

Yolun düser ise gurbet diyarina 

Sevdigim bir haber gönder bana 

Ecel yolda karsima ciksada 

Düserim yollarina gelirim sana 

Asigim ben sana birakmam seni 

Özlerim senin saz calan ellerini 

Sinemde saklarim senin sevgini 

Yüregimdeki sevdamla 

Gelirim simdi 

                       18.04.05', 'Nice zaman oldu ayriyim yardan  Ey sevdigim söyle nerdesin simdi  Yollarini gözler oldum güzüm yasiyle  Yikildi ümütlerim gidemem simdi  Has...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Alioğlu']::text[], 8.5, '{"poet":"Ayşe Alioğlu","poet_slug":"ayse-alioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/yuregimdeki-sevdamla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çöl', 'col-elazigli-mustafa-kaya-3w31z', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '(“…Allah,günahlardan korunanları sever…tevbe-4..”) 

göz yaşartıcı ve eritici

bir yalnızlık  içindeyim.

ve bu benim  hikayem.

ıssız, korkunç, susuz  ve, 

kimsesiz bir çöldeyim.

ölüm güneşimin doğuşunu

beklemekteyim.

aşk ve iman sardı ruhumu,

elimi kim tutacak..? 

kelebekleri güneşe doğru uçan

bu güzellik ve aşk uçurumunda.

ölümü ve hayatı yaratan Rabb im,

dönüş ancak sanadır ve,

kimse veremez rengini

mehtabımın

senin  çağrından başka..

Mustafa kaya

07.10.2005 / beylerbeyi

www.mustafakaya.net', '(“…Allah,günahlardan korunanları sever…tevbe-4..”)  göz yaşartıcı ve eritici bir yalnızlık  içindeyim. ve bu benim  hikayem. ıssız, korkunç,...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/col-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hafif Bir Işık Sızıyordu', 'hafif-bir-isik-siziyordu-hatice-bediroglu-vx7u1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yüreğim bir koşu tutturdu,

Sana doğru.

Hafif bir ışık sızıyordu,

Mutfak pencerenden.

Fırında pişmiş balık önünde,

Aslan sütü hazır yanında.

Ah! tuzunu da,

Kaçırmışsındır şimdi sen.

Çatalın,

Oynamamış bile yerinden.

Gözlerin takılı balıkta,

Oturuyorsun,

Hiç kıpırdamadan.

Belli...

Lokmalar bensiz,

Geçmiyor boğazından.

www.haticebediroglu.net

-Aşkı Bulan Şiirler- Gündüz Kitabevi Aralık 2005', 'Yüreğim bir koşu tutturdu, Sana doğru. Hafif bir ışık sızıyordu, Mutfak pencerenden. Fırında pişmiş balık önünde, Aslan sütü hazır yanında. ...', ARRAY['Türk Edebiyatı','Şiir','Hatice Bediroğlu']::text[], 8.5, '{"poet":"Hatice Bediroğlu","poet_slug":"hatice-bediroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/hafif-bir-isik-siziyordu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Buhar', 'buhar-elazigli-mustafa-kaya-zqraw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'benim gökyüzümün

bulutları,

kapalı ve dertlidir.

bazen yıldırımlar ve,

