INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarası Sağalmış Bir Sayıklamadır Şiir', 'yarasi-sagalmis-bir-sayiklamadir-siir-melih-coskun-36hpk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yarası sağalmış bir sayıklamadır şiir 

Kıyı kentlerini darmadağın eden 

Büyük fırtınalardan sonra yazılmış.

Anlayamazsın acısını sıcakken

Etine saplanan kurşun yarasının. 

Ölüm bile sonradan yazar kendi öyküsünü. 

Sağalır yavaş yavaş

Açık yaraların

Ve diner başında zonklayıp duran ağrı. 

Kalbin sıkışmadan geçebilirsin

Bir mezarlığın kıyısından. 

Gözlerini kaçırmazsın artık 

Bir çift mavi gözden. 

Dalıp giderken uzaklara

Yanı başında çiçeklendiğini görürsün birden ağaçların 

Derin bir nefes çekersin içine 

Yay gibi gerilir kolların 

Uzatıp  koymak istersin kalbini 

Gökyüzüne güneş yerine

Senin için durduğunu sandığın dünyanın 

Yeniden döndüğünü fark edersin bütün güzelliğiyle.

Yarası sağalmış bir sayıklamadır şiir

Dost mezarlarında 

Kızıl çiçekler açtıktan sonra yazılmış... 

2005', 'Yarası sağalmış bir sayıklamadır şiir  Kıyı kentlerini darmadağın eden  Büyük fırtınalardan sonra yazılmış. Anlayamazsın acısını sıcakken Et...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/yarasi-sagalmis-bir-sayiklamadir-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ö m ü r', 'o-m-u-r-nevzat-erkol-pgfw2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Geldik,

