INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşanan Zelzeleler...', 'yasanan-zelzeleler-alper-kuruk-kfti6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '17  Ağustosta deprem felâketini

Ailecek Gölcük''te gördük biz de yaşadık...

Şimdi vurdu  Pakistan  ve de Çin  Milletini

Yaşanan depremlerde  sanki  yine biz vardık...

Allah merhamet etsin, yaşayan başka anlar

Unutulmuyor asla geçse nice zamanlar...

Felâketi görüp te içinde yaşayanlar

O günlerine döner, o günlerini yaşar...

Bazı öyle olaylar anlatmakla yaşanmaz,

Tarife imkân olmaz onu yaşayan bilir...

İşte tüm felâketler yaşanır,anlatılmaz

Acılarla doludur,yıkan bir aşk gibidir...', '17  Ağustosta deprem felâketini Ailecek Gölcük''te gördük biz de yaşadık... Şimdi vurdu  Pakistan  ve de Çin  Milletini Yaşanan depremlerde  ...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yasanan-zelzeleler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mecburum sana', 'mecburum-sana-yilmaz-ozturk-d0me1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu akşamda sen yoksun yanımda

Dostlarım teselli veriyor bana

Ben seni arıyorum sen yine uzaklarda

Dinmez gözüm yaşı ben mecburum sana

Geçmiyor akşamlar sensiz hayalde

Hiç kalır dertte Mecnun  Leyla bile

Ağlamakla gözüm kör oldu sende

Olmayan sevgili sen varsın hayalimde

Nasıl düştüm ben bu çileye

Hayali sevgili muhtacım hayaline

Ulaşılmazsın bir ışık şifa olur yüreğime

Derman olurmu kutup yıldızı derdime

10:10.2005

P.tesi', 'Bu akşamda sen yoksun yanımda Dostlarım teselli veriyor bana Ben seni arıyorum sen yine uzaklarda Dinmez gözüm yaşı ben mecburum sana Geçmiy...', ARRAY['Türk Edebiyatı','Şiir','Yılmaz Öztürk']::text[], 8.5, '{"poet":"Yılmaz Öztürk","poet_slug":"yilmaz-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/mecburum-sana-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adem Oğlu', 'adem-oglu-mahmut-simsek-lkjqk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bomboş görünen dünyada rabbim ne güzellikler yaratmış.

Rahmet ile donatmış insanları nur ile aydınlatmış.

Sabır ihsan eylemiş,ve insanları çok zeki yaratmış.

Kul,ol ademoğlu,rabbin dünyayı, senin için yaratmış.

Ey ademoğlu dur, bir bak,direksiz duran şu gök,semaya.

Bak, inancın olsun, tapma paraya pula yönel mevlaya.

Sen kuranla yaşa,(ALLAH) ,ın rahmetiyle gel,git oraya.

Kul,ol ademoğlu,rabbin dünyayı, senin için yaratmış.

Denizlerin enginliği ve gecenin mehtabı semaya.

Dağların yüceliği geçit vermeyen bağrı taş yapıya.

Bütün mahlukatlarıyla uydumuz eşsiz cennete benzer.

Kul,ol ademoğlu,rabbin dünyayı, senin için yaratmış.

Bahar gelir, kırlar, bayırlar,ormanlar, yeşile bürünür.

Tabiatta kar suları erir coşar ırmağa dönüşür.

Ağaçlar, taşlar, kuşlar bile zikreder,(Allah)   a, yönelir.

Kul,ol ademoğlu, rabbin dünyayı, senin için yaratmış.

Katmanların hepsi (Allah)   ın kuluna sermayesidir.

Rabbin, imtihan dünyasında, kulunu denemesidir.

Şükürle an, nimetlerden kullan, o, rahman ve rahimdir.

Kul,ol ademoğlu, rabbin dünyayı,senin için yaratmış.', 'Bomboş görünen dünyada rabbim ne güzellikler yaratmış. Rahmet ile donatmış insanları nur ile aydınlatmış. Sabır ihsan eylemiş,ve insanları ç...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Şimşek']::text[], 8.5, '{"poet":"Mahmut Şimşek","poet_slug":"mahmut-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/adem-oglu-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşüm', 'dusum-yusuf-ter-e6imd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İnce bir dekolte 

