INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadınlar', 'kadinlar-mahmut-ulusoy-d4qmp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kadınlar dünyanın çiçekleridir

Bal yapan petekte arıya benzer

Aşk öyle bir şeydir yakar insanı

Asla ey olmayan yaraya benzer

Huridir melektir gençlik zamanı

Bazen coşar akar geçer zamanı

Kadının iyisi değer cihanı

Süslenmiş her renkte halıya benzer

Felek bir gün bu dünyadan ayrılır

Yazık ki MESULİ kefen sarılır

O kadar incedir kopar kırılır

İpekten yapılmış valaya benzer', 'Kadınlar dünyanın çiçekleridir Bal yapan petekte arıya benzer Aşk öyle bir şeydir yakar insanı Asla ey olmayan yaraya benzer Huridir melekti...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Ulusoy']::text[], 8.5, '{"poet":"Mahmut Ulusoy","poet_slug":"mahmut-ulusoy","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kadinlar-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Soru', 'soru-yavuz-unler-34lcg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hepimizin sonudur iki metrelik kuyu,

Kurtulmak istiyorsak bilmeliyiz soruyu!', 'Hepimizin sonudur iki metrelik kuyu, Kurtulmak istiyorsak bilmeliyiz soruyu!...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Ünler']::text[], 8.5, '{"poet":"Yavuz Ünler","poet_slug":"yavuz-unler","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/sonumuz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olmaz mı', 'olmaz-mi-mahmut-ulusoy-qtc01', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bana bak kardeşim tut sen sözümü

Gelip ben fakire çatma olmaz mı

Boşuna düşünüp dalma hülyaya

Yatağın sarılmış yatsan olmaz mı

Durup durup beğenirsin özünü

İki dinle bir de konuş sözünü

Sinirlenme çıkarırlar gözünü

Laf edip aleme atma olmaz mı

İster bir Müslüman ister Ermeni

Severse severim beni seveni

MESULİ elinle çeksen deveni

Götürüp pazara satsan olmaz mı', 'Bana bak kardeşim tut sen sözümü Gelip ben fakire çatma olmaz mı Boşuna düşünüp dalma hülyaya Yatağın sarılmış yatsan olmaz mı Durup durup b...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Ulusoy']::text[], 8.5, '{"poet":"Mahmut Ulusoy","poet_slug":"mahmut-ulusoy","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/olmaz-mi-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mektup', 'mektup-mahmut-ulusoy-5gdi5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Allah''ı seversen kalma bir yanda

Her nerde olursa bulasın mektup

Varırsan bölükte sor çavuşundan

Belki nöbettedir göresin mektup

Girne''nin dağları sıra sıraya

Kocaman Akdeniz girdi araya

Altıncı bölükte baksan alaya

Yavaştan hatırın sorarsın mektup

MESULİ''yim nedir beni ağlatan

Büyüttüm ki oğlum beklesin vatan

Her an koru Murat''ımı yaradan

Ebedi yanında durasın mektup', 'Allah''ı seversen kalma bir yanda Her nerde olursa bulasın mektup Varırsan bölükte sor çavuşundan Belki nöbettedir göresin mektup Girne''nin d...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Ulusoy']::text[], 8.5, '{"poet":"Mahmut Ulusoy","poet_slug":"mahmut-ulusoy","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/mektup-105-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut', 'umut-yavuz-unler-0ysue', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yine battı güneş, yarım kalan umutlarla,

Görünürmü acaba doğacak yıldızlarla? 

Her akşam bakıyorum, karşımdaki trene,

Bakarım sevgi dolu vagonlardan inene.

Gözüm kaydı birden, yağmur yüklü bulutlara,

Boşalttılar yükünü, gürgenlere, dutlara.

Gör bak umudu kaybetmek ne kadarda zormuş,

Yürüdüğüm sevda yolu,pembe değil mormuş.', 'Yine battı güneş, yarım kalan umutlarla, Görünürmü acaba doğacak yıldızlarla?  Her akşam bakıyorum, karşımdaki trene, Bakarım sevgi dolu vag...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Ünler']::text[], 8.5, '{"poet":"Yavuz Ünler","poet_slug":"yavuz-unler","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/umut-210-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oy kurbanam ben sana', 'oy-kurbanam-ben-sana-pinar-koc-qoh2h', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Nasılda mahpushane duvarları gibi çöktü özlemin içime 

Nasıl sindi kokun,küflü soğuk yatağıma! 

Parmaklıklarım ellerin kadar narin ama; 

Nasılda kapatmışsın o ellerini yüzüne,

Ağladığını görmeyeyim diye...

Yazık,

Yazık ki,o ince parmaklarını aşıp,

Gözyaşlarını öpemiyorum...

Kader diyelim,

Sadece kader...

Kavuşmak bir başka baharaymış! 

Ayrılığı koynumda bir yılan gibi beslemişim,

Özlemini yüreğimde korkmadan taşımışım,korkmadan! 

Vuslat demişim ağlayan gecelerimde

Sadece vuslat...

Oy kurbanam ben sana! 

Güneşli günler bizim zannederdim,

Umutlar bizim,yarınlar bizim...

Kendi elimizle geçirmişiz ilmeği boynumuza,

Kendimizi asmışız,defalarca yürek acısıyla...

Gümbürtüleri duyulmuş sonra çatlak seslerin,

Hasretmiş,özlemmiş,

Sevdalanmak,sevmekmiş...

Onlar da ne ki? 

Aşk neymiş ki? 

Kimmiş ki? 

Kim kaybetmiş,kim bulmuş ki? 

Artık yanar yürekler hasret acısıyla; 

Kavuşmakta neymiş ki,belki öte dünyada...

Oy kurbanam ben sana! ...

Sen o engin dağlarından,seller indirme yanaklarına! 

Sen yanma,

Sen ağlama! 

Ben ikimiz yerine,

Yağlı ilmeği geçiririm boynuma...

Güneşli günler seni bekliyor,

Şimdi daha yakın,yakın yaklaştıkça..

 Şimdi gökyüzü daha mavi, 

Yeşiller,daha yeşil....

Olmalı ömrün boyuca...

Oy kurbanam ben sana,

Oy kurbanam....

Nasılda mahpushane duvarları gibi

Çöktü özlemin içime...

Oy kurbanam,canım kurban benim sana.......

                                                                                 13.9.2002       21:15          uğurböceği', 'Nasılda mahpushane duvarları gibi çöktü özlemin içime  Nasıl sindi kokun,küflü soğuk yatağıma!  Parmaklıklarım ellerin kadar narin ama;  Nas...', ARRAY['Türk Edebiyatı','Şiir','Pınar Koç']::text[], 8.5, '{"poet":"Pınar Koç","poet_slug":"pinar-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/oy-kurbanam-ben-sana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İhanet Değil', 'i-hanet-degil-alper-kuruk-ub4pf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir yeşil gözlüye bakıyorsam

Kıskanma sakın

Sevgilim senin de gözlerin yeşil.

Bir sarı saçlıya bakıyorsam

Aklına kötülük gelmesin sevgilim

Senin saçların da sarı.

Bir güzel görünce sevgilim

Dönüp dönüp bakıyorsam

Aşkın kutsallığıyla yemin ederim

İhanet etmiyorum sana

Çünkü sen de güzelsin.

Gördüğüm her güzel kadında

Sana benzer tarafını ararım; 

Yolda,sokakta,köşe başında

Her yerde,her yerde sevgilim

Gördüğüm her kadına bakarım

Gücenme,kıskanma sakın

Ki seni o bakışlarla ararım...', 'Bir yeşil gözlüye bakıyorsam Kıskanma sakın Sevgilim senin de gözlerin yeşil. Bir sarı saçlıya bakıyorsam Aklına kötülük gelmesin sevgilim S...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ihanet-degil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkı Arayanlara', 'aski-arayanlara-alper-kuruk-u9ssj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aşkı bulmak istersen

Ayrılığı tümden yitir,

Aşk,insanı gençleştirir

Izdırabı eskitir.

Aşkı bulmak istersen

Yaş eksilmesin gözlerinden,

Aşık oldun mu bir kez

Gülüp dururken

Ağlayıverirsin

Ağlayıverirsin

İçten...', 'Aşkı bulmak istersen Ayrılığı tümden yitir, Aşk,insanı gençleştirir Izdırabı eskitir. Aşkı bulmak istersen Yaş eksilmesin gözlerinden, Aşık ...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/aski-arayanlara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanlış Hesap', 'yanlis-hesap-emin-nadir-n9vdv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '''''Bir adamın bir ömür boyu sevdiğini,

        Bir şair beş dakika sevsin yeter.''''

       Diyordu bugün okuduğum yazıda.

       Yanlışlık var bu işte.

       Ya bu adam hesap bilmiyor.

       Ya da ben şair değilim! 

       Yetmedi sevmelerim!', '''''Bir adamın bir ömür boyu sevdiğini,         Bir şair beş dakika sevsin yeter.''''        Diyordu bugün okuduğum yazıda.        Yanlışlık var...', ARRAY['Türk Edebiyatı','Şiir','Emin Nadir']::text[], 8.5, '{"poet":"Emin Nadir","poet_slug":"emin-nadir","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/yanlis-hesap-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '**Açtım yüreğimi**', 'actim-yuregimi-mustafa-murat-aydogdu-ipljm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Açtım yüreğimi,geldim kapına; 

Aşkınla yanan gönlüm senindir

Ya bir ümit ver sevgi adına

Ya da yüreğime bir hançer indir 

Açtım yüreğimi geldim kapına; 

İster kahret beni, ister sevindir

Değer vermesende duygularıma

Bilki şu yüreğim, yalnız senindir

Açtım yüeğimi geldin kapına; 

Alay etme sakın, halime gülme

Dilersen bir daha çıkmam yoluna

Yeterki zulmetme şu yüreğime

Açtım yüreğimi geldim kapına

Her nefesimde seni düşünmek

Ölümsüz aşkıma karşılık beklemekse suçum,

Ve mümkün değilken gönlümden adını silmek

Cezam sensizlik olsun

Yalnızlık olsun sonum 

Yalanım yok inan sevgiden yana

Bilirim kısadır her güzel rüya

Sen vermesende sevgini bana

Şu garip yüreğim unutur sanma

Alışır zamanla elbet yanmaya

Açtım yüreğimi; geldim kapına...!', 'Açtım yüreğimi,geldim kapına;  Aşkınla yanan gönlüm senindir Ya bir ümit ver sevgi adına Ya da yüreğime bir hançer indir  Açtım yüreğimi gel...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Murat Aydoğdu']::text[], 8.5, '{"poet":"Mustafa Murat Aydoğdu","poet_slug":"mustafa-murat-aydogdu","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/actim-yuregimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrı Gayrı Can Ne İmiş? !', 'ayri-gayri-can-ne-i-mis-ozan-si-ar-agdasan-fzox6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hepimiz birer kardeşiz

Sen ne imiş, ben ne imiş? 

Biri birimize eşiz...

Siyah-beyaz ten ne imiş? 

Halkım sömürü ağında

Baykuşlar öter bağında

Bilimin uzay çağında

Din kavgası kin ne imiş? ! 

İnsan kendini bilmeli

Dost yaşayıp dost ölmeli

Artık İnsanlık gülmeli

Zulüm, savaş, kan ne imiş? 

Her şeyden evvel insanız

Birer damla su ve kanız

Şiar der tüm kök bir canız

Ayrı-gayrı can ne imiş? ! 

Söz ve Müzik: Ozan ŞİAR Ağdaşan   www.siarcan.com

Yorum: Aşık Şahturna  (Şah Turna)   www.sahturna.com

Almanca çeviri: Şirin Şafak Ağdaşan 

Gençlik Kültür Sanat Dostluk Forumu   www.safak-sirin-agdasan.com

‘Şakıyan Turna- Şahturna’ Kitap Can Yayın', 'Hepimiz birer kardeşiz Sen ne imiş, ben ne imiş?  Biri birimize eşiz... Siyah-beyaz ten ne imiş?  Halkım sömürü ağında Baykuşlar öter bağınd...', ARRAY['Türk Edebiyatı','Şiir','Ozan ŞİAR Ağdaşan']::text[], 8.5, '{"poet":"Ozan ŞİAR Ağdaşan","poet_slug":"ozan-si-ar-agdasan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ayri-gayri-can-ne-imis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yok Mu?', 'yok-mu-alper-kuruk-f4nc1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dertliyim türkümü söyleyen yok mu? 

Hastayım derdimden anlayan yok mu? 

Kimsesiz,sessizce ölüp gidersem

Arkamdan tek kişi ağlayan yok mu? 

Günümü yitirdim,gecem nerede? 

Bir vefasız düşürdü beni bu derde,

Akıl denen bir şey kalmadı serde

Bu aşk delisini anlayan yok mu? 

Başım düşüncede,ayağım yolda

Gözüm bir noktada ne sağda,solda

Ey sevgili birazcık vefakâr ol da 

Demeyim yolumu bekleyenyok mu? 

Gün geçer ben kendimden geçerim

Elbet birgün bu diyardan göçerim,

Hasret şarabını hep ben içerim

Bir kadeh benimle kaldıran yok mu? 

Sözüm kendimedir ele ne diyem

Mısralarım olsun size hediyem,

Gönlümce zenginim ama neyliyem

Bir kefenle ölümü kaldıran yok mu?', 'Dertliyim türkümü söyleyen yok mu?  Hastayım derdimden anlayan yok mu?  Kimsesiz,sessizce ölüp gidersem Arkamdan tek kişi ağlayan yok mu?  G...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yok-mu-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Var Olmanın Yolu', 'var-olmanin-yolu-ozkan-karaca-xyx6d', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Geniş ufukların penceresinden yayılan

Çağlar üstü çağların adresinde yürüyen

Rahmet pınarının şenliğinde serinleyen

Hakkın mührünün damgasında yoğrulan

Hilim ve ilimle bayraklandıran

Zaferle dalgalandıran

Mana mirasıyla insanlığın ihya deryası

Himmet özüyle güneşlenerek

Hikmetlerin aydınlığıyla buharlaşarak

Kuran''ın sözüyle gözlenerek, hallerle buluşturarak

Ufukların altın parıltısına kanat açtıran

Çağların mesafesine adım taşı

Nesillerin istikbaline adım yaşı

Gönüllerin istikametine adım başı

Ruhların istirahatine adımdaş

Mana atmosferinde uçuran

İlim ve hilim donanımında koşturan

Ufukların varlık gaye menzilinde buluşturan:

İslamın hak yolu...

Kalblerin karanlığını söndüren, hakikat yükünde

Ruhların sıkıntısını çöktüren, İrfan yoğunlugunda

Kişiliklerin bulanıklığını toparlıyan, takva yaşantısında

Duyguların balçıklarını pak eden, zikir yaygınlığında

Var olmanın esintisinden

Gönül baharıyla uzanarak

Ruhların yüksekliğinden

Güzelliklere kanatlandıran

Hakikatlerin yoluna kavuşturan

Hayatın anlam ve değerini aşılıyan

Gülistan bahçelerini aralayan:

Var olmanın yolunda: İslam', 'Geniş ufukların penceresinden yayılan Çağlar üstü çağların adresinde yürüyen Rahmet pınarının şenliğinde serinleyen Hakkın mührünün damgasın...', ARRAY['Türk Edebiyatı','Şiir','Özkan Karaca']::text[], 8.5, '{"poet":"Özkan Karaca","poet_slug":"ozkan-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/var-olmanin-yolu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '2001 Yaprak Dökümü', '2001-yaprak-dokumu-burhanettin-akdag-19390', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yaprak Dökümü

Ağır, 

Puslu hazan kokusu sinmiş havaya 

Ümitlerim ihtiyar mı ihtiyar 

Belli belirsiz atarken kalbim 

Eksiliyor hücrelerim 

Vedasız kaçışlarla. 

Sararmış küskün yapraklar 

Son ritmik danslarıyla düşerken toprağa

Fatiha’sı okunuyor kaybolan yılların. 

Son yolculuğuna kanat çırpıyor 

Perişan hayallerim. 

Bakamadım ardıma, 

Korktum. 

Oysa, hayattan ne çok şey beklemiştim

Heyhat! 

Hiçbir şey kalmamış geriye. 

Ağlamak istedim hıçkıra hıçkıra 

Olmadı, 

Kilitlendi gözyaşlarım. 

Bir ara, 

Göçmen kuşlara takıldı gözlerim 

Geriye geriye kanat çırpıyorlar 

İsteksiz, çaresiz, telaşsız.

Onlar bile

Semada yankılanan

Yalnızlığın türküsüne ağlıyorlar.

Yitik yıllarıma yandım 

Ağıt yaktım acılarıma 

Yıllardır dinmeyen kahrıma. 

Buğulandı yüreğim 

Burkuldu sızılarım

Haykıramadım 

Gücüm yok isyana. 

Ve işte, 

Hüzünlü gurub vaktinde

Batarken umutlarım 

Bir yaprak daha düştü yokluğa 

Ömrümden, sorgusuzca. 

(12.06.2001)', 'Yaprak Dökümü Ağır,  Puslu hazan kokusu sinmiş havaya  Ümitlerim ihtiyar mı ihtiyar  Belli belirsiz atarken kalbim  Eksiliyor hücrelerim  Ve...', ARRAY['Türk Edebiyatı','Şiir','Burhanettin Akdağ']::text[], 8.5, '{"poet":"Burhanettin Akdağ","poet_slug":"burhanettin-akdag","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/2001-yaprak-dokumu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saadeti Arıyorum', 'saadeti-ariyorum-alper-kuruk-r1s6s', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Saadeti bir güzel kuş dediler 

Aşk illerinde yaşarmış.

Sevgilerle beslenirmiş hep.

Kafese girmek istemezmiş bir türlü.

Ehli imiş bazıları öyle söylüyor

Yırtıcıymış bazılarının dediğine bakılırsa.

İki kalpten bir kafes yaptırdım ona 

Ehlisine çatarız da

Bizim kafesten hoşlanır belki? 

Arıyorum yoluna düştüm onun

Allah yardımcım olsun...', 'Saadeti bir güzel kuş dediler  Aşk illerinde yaşarmış. Sevgilerle beslenirmiş hep. Kafese girmek istemezmiş bir türlü. Ehli imiş bazıları öy...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/saadeti-ariyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acıkmayayım Mı?', 'acikmayayim-mi-alper-kuruk-wdn43', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sözümü dinleyen yok

Beni söz edense pek çok,

Gözüm düşmana tok

Dosta acıkmayayım mı? 

Günah hep benim eserim

Sevap düşmanlarımınmış,

Cehennemmiş benim yerim

Cennete acıkmayayım mı? 

Çirkin yaraşırmış bana

Sevgi belâymış insana,

Verin o belâyı bana 

Aşka acıkmayayım mı? 

Her şeyciğe karnım toksa

Dünyada bana yâr yoksa,

Bir sen varsın ey güzel kız 

Ben sana acıkmayayım mı?', 'Sözümü dinleyen yok Beni söz edense pek çok, Gözüm düşmana tok Dosta acıkmayayım mı?  Günah hep benim eserim Sevap düşmanlarımınmış, Cehenne...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/acikmayayim-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidemiyorum', 'gidemiyorum-mustafa-murat-aydogdu-f5go6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Alıp başımı gitsem, diyorum buralardan

Uzaklaşsam bütün sevdiklerimden

Sonra hergün ağlasam geride kalanlara

Öyle ki; Yağmur olsam,boşalsam gözlerimden

Alıp başımı gitsem,diyorum buralardan

Henüz bilemediğim herhangi bir diyara

Ve bir daha dönmesem,gittiğim o diyardan

Hiçbir şey anlatmasam mazimi soranlara

Alıp başımı gitsem,diyorum buralardan

Bilsemki,garip anam hakkını helal ede

Bilsemki,beni babam anlayıpta affede

Bilsemki,yüce Rab''bim bana buğuz etmeye

Bir dakika durmazdım,giderdim gurbet ele

Bilsemki,kardeşlerim ağlamaya ardımdan

Bilsemki,üzülmeye sevdiğim hiçbir insan

Sevdiğimde evlendi,bekleyende yok beni

Bir çıkar yol bulsaydım,giderdim gurbet ele

Bende her insan gibi elbet birgün ölürüm

Eğer nasip olursa imanla gömülürüm

Sizlerden tek isteğim,beni merak etmeyin

Bilemki üzüldünüz; Sizsiz hergün ölürüm!', 'Alıp başımı gitsem, diyorum buralardan Uzaklaşsam bütün sevdiklerimden Sonra hergün ağlasam geride kalanlara Öyle ki; Yağmur olsam,boşalsam ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Murat Aydoğdu']::text[], 8.5, '{"poet":"Mustafa Murat Aydoğdu","poet_slug":"mustafa-murat-aydogdu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/gidemiyorum-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İntizar', 'i-ntizar-ahmet-hani-4z7xp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dörd duvardı birde men, 

Sonbahardı birde men.

Bizim tayda ay güneş, 

İntizardı birde men.', 'Dörd duvardı birde men,  Sonbahardı birde men. Bizim tayda ay güneş,  İntizardı birde men....', ARRAY['Türk Edebiyatı','Şiir','Ahmet Hani']::text[], 8.5, '{"poet":"Ahmet Hani","poet_slug":"ahmet-hani","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/intizar-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hatırla beni', 'hatirla-beni-mustafa-murat-aydogdu-q7fat', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gözlerin meçhule dalarsa eğer

Bırakıp gittiğin günü hatırla

Bir gün aşk senide yakarsa eğer

Bir aşk masalını,beni hatırla

Düşlerin kabusa döndüğü anda

Yeşertip yaktığın gülü hatırla

Şu fani dünyada yalnız kalınca

Bir dertli kulu,beni hatırla

Gün gelir seversen bir zalim kulu

O güzel günleri,dünü hatırla

Bırakıp giderse sorma suçunu

Sessizce gittiğin veda anını

İhanet ettiğin,beni hatırla

Gözünden zamansız yaş boşanırsa

Hatırla sevdiğim mutlu günleri

Gönlüne dermansız dertler dolarsa

Hatırla bir tanem,yaktığın beni

Hatırla hain,hatırla beni!', 'Gözlerin meçhule dalarsa eğer Bırakıp gittiğin günü hatırla Bir gün aşk senide yakarsa eğer Bir aşk masalını,beni hatırla Düşlerin kabusa dö...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Murat Aydoğdu']::text[], 8.5, '{"poet":"Mustafa Murat Aydoğdu","poet_slug":"mustafa-murat-aydogdu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/hatirla-beni-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sayıklama', 'sayiklama-ahmet-sureyya-durna-c1fsb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir cümbüş ki gönül gezegenimde,

Anonim halay mı,hora mı bilmem! .

Cinler cirit atar,ifritler oynar,

Bayram mı,düğün mü,töre mi bilmem! .

      Bir cümbüş ki gönül gezegenimde.

Orkestra seansı başlar birazdan,

Resital sunulur,taksim-i sazdan.

Şuh Peri Kızları hoşlanır nazdan,

Raks için peşrev mi,ara mı bilmem! .

      Bir cümbüş ki gönül gezegenimde

Ay tebessüm eder,güneş göz kırpar,

Samanyolu sevincinden el çarpar.

Tüm galaksilerde kutsal tören var,

Burası ütopik yöre mi bilmem! .

      Bir cümbüş ki gönül gezegenimde.

Sonsuzluğun sona erdiği yerde,

İzimi kaybettim başka izlerde.

Esrarlı göklerde,uç denizlerde,

Ruh halim tufan mı,bora mı bilmem! .

      Bir cümbüş ki gönül gezegenimde.

Gördüğüm gerçek mi,hayal mi,düş mü,

Veyahut kabuktan ''öz''e dönüş mü! .

Bir yanıp tutuşma bir göyünüş mü,

Hasılı kriz mi,sara mı bilmem! .

      Bir cümbüş ki gönül gezegenimde.

Yadırgadım içimdeki alemi,

Yoksa bu hal,sihri müdahale mi! .

N e yazmışsa odur,kudret kalemi,

Alın yazım ak mı,kara mı bilmem! .

      Bir cümbüş ki gönül gezegenimde.', 'Bir cümbüş ki gönül gezegenimde, Anonim halay mı,hora mı bilmem! . Cinler cirit atar,ifritler oynar, Bayram mı,düğün mü,töre mi bilmem! .   ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Süreyya Durna']::text[], 8.5, '{"poet":"Ahmet Süreyya Durna","poet_slug":"ahmet-sureyya-durna","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/sayiklama-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geldim Kendime', 'geldim-kendime-cihan-kaya-jf345', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Acıdım acıya, astım sırtıma

Hiç durmadan durdum, geldim kendime…

Sırt, sırt çevirince küstüm sırtıma

Hep kendimi kırdım, geldim kendime…

Ümit kesilince, dert kurban oldu

Hemen kanı bitti, aşk yalan oldu

Al kara olunca yol viran oldu

Karı akla serdim, geldim kendime…

Korkudan ölüyor, ölüm korkuyor

Can alan meleğin zulüm kokuyor

Yaş gözden düşünce, hançer sokuyor

Ruha pusu kurdum, geldim kendime…

Bin dere su verdi, kanmamız gerek 

Aşka su katıldı, inanmaz yürek

Su yolunca taşı, takip et direk

Közü suya sardım, geldim kendime…

Gece dilek tuttum, gerçek saymadı

Baktım gök yüzüne, yıldız kaymadı

Kör talih takıldı, candan caymadı

Şerri, hayra yordum, geldim kendime…

Saçma divan durdu, taktı tabanca

Dert derin basınca geçirdi kanca

Yeminle kötüden kaçarsın anca

Huzura söz verdim, geldim kendime…

Değer ver değene, silmesin değer

Sevgi kayda değer olursa eğer.

Kayıt ederi yok boşaymış meğer

Hiç ileri sürdüm, geldim kendime…

Cihan ümidini, verdi satıra

Derdini katlayıp koydu katıra

Maziyi fırlatıp, kırdım hatıra

Ben murada erdim, geldim kendime…', 'Acıdım acıya, astım sırtıma Hiç durmadan durdum, geldim kendime… Sırt, sırt çevirince küstüm sırtıma Hep kendimi kırdım, geldim kendime… Ümi...', ARRAY['Türk Edebiyatı','Şiir','Cihan Kaya']::text[], 8.5, '{"poet":"Cihan Kaya","poet_slug":"cihan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/geldim-kendime-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Suçlu Ararsan', 'suclu-ararsan-salim-erben-4glba', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Suçlu ben değilim 

Gözlerim 

Suç ortağı seni seven

Kalbim

Davacı  yalnız kalan

Bedenim

İdama giden yol kıyısında

Bırakın tökezlemeyim

Ölümden korkmuyorum da

Seni bensiz bırakmaktan

Korkuyorum

Son isteğim sorarlarsa

Eğer

Bir mikrofon isterim

Sana olan aşkımı

Tüm dünyaya ilan ederim

Unutma ki şimdi sensizliğin 

ertesindeyim

Gönül kapılarımı kapadım

Alışmaya çalışıyorum

Yokluğun içimde büyüdükçe büyür

Bir alışamadım yüreğim le 

Oturup ağlamaya

İki damla yaşı çok gördüler 

Zalımlar bana', 'Suçlu ben değilim  Gözlerim  Suç ortağı seni seven Kalbim Davacı  yalnız kalan Bedenim İdama giden yol kıyısında Bırakın tökezlemeyim Ölümde...', ARRAY['Türk Edebiyatı','Şiir','Salim Erben']::text[], 8.5, '{"poet":"Salim Erben","poet_slug":"salim-erben","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/suclu-ararsan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Gece', 'bir-gece-esat-anik-rb5c5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ümidi elinden bırakma canım,

Mutluluk bizi de bulur bir gece.

Sabırdır menzile erdiren o sır,

Sevenin muradı olur bir gece.

Başka bir talibi olmasa bile,

Bülbülün cefası güledir,güle.

Ne diyor şarkılar,kulak ver hele; 

Sevdanın namesi gelir bir gece.

Sevenin arzulu bakışı olur,

Özlemin yüreği yakışı olur.

Her inişin bir de çıkışı olur; 

Hüzünler geride kalır bir gece.

Âlem gerekmez ki; Özde sen varsan.

Şiirde,türküde,sözde sen varsan.

Olur a! O akşam bizde sen varsan,

Hasretim kolumda ölür bir gece.

Esat ANIK 09.08.2005', 'Ümidi elinden bırakma canım, Mutluluk bizi de bulur bir gece. Sabırdır menzile erdiren o sır, Sevenin muradı olur bir gece. Başka bir talibi...', ARRAY['Türk Edebiyatı','Şiir','Esat Anık']::text[], 8.5, '{"poet":"Esat Anık","poet_slug":"esat-anik","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bir-gece-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül Bence', 'gul-bence-ramazan-ates-kfdnd', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'GÜLBENCE



Gül bence güzel bence,

Gülmelisin gül bence

Gülmek yakışır gence,

Gülmelisin gül bence.

Gülüşün hoşa gider,

Güzel olmasın heder,

Gelmesin elem keder,

Gülmelisin gül bence.

Yüzünde güller açtı,

Kederler senden kaçtı.

Gülüşün neşe saçtı,

Gülmelisin gül bence.

Seni gören şenlenir,

Mutlu olur keyiflenir,

Güzeller gülmelidir,

Gülmelisin gül bence.

Sana duacı Ramazan,

Gül yüzün gülsün her an,

Kalmasın mutsuz olan,

Gül bence güzel bence,

Gülmelisin gül bence

Enschede/20.09.2000', 'GÜLBENCE Gül bence güzel bence, Gülmelisin gül bence Gülmek yakışır gence, Gülmelisin gül bence. Gülüşün hoşa gider, Güzel olmasın heder, Ge...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Ateş']::text[], 8.5, '{"poet":"Ramazan Ateş","poet_slug":"ramazan-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/gul-bence-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senden nefret ettiğim', 'senden-nefret-ettigim-pinar-koc-qb81y', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Senden nefret ettiğim her gün için

Saksımdaki menekşeden 

Bir yaprak kopartacağım.

Kuruyacaksın mor menekşeler gibi,

Solacaksın sende…

Köklerin su almayacak artık

Sararacaksın! 

Yavaş yavaş öldüğünü hissedeceksin.

Kahpe insanlar nasıl ölür bilir misin? 

Tıpkı mor menekşeler gibi…

                                                  15.08.2001

                                                  Çarşamba          22:40', 'Senden nefret ettiğim her gün için Saksımdaki menekşeden  Bir yaprak kopartacağım. Kuruyacaksın mor menekşeler gibi, Solacaksın sende… Kökle...', ARRAY['Türk Edebiyatı','Şiir','Pınar Koç']::text[], 8.5, '{"poet":"Pınar Koç","poet_slug":"pinar-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/senden-nefret-ettigim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Leb-Leb-i', 'leb-leb-i-yasemin-sezer-tulgar-5l3fr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'sağ uç köşesinden başlayıp

sol uç köşesine uzansam

arasından ıslak ıslak salınsam

uzun uzun meltemlerle

üstünden solunsam

dudaklarının

an(ı)  ların tekrarıyla

çorak numarasına yatan

solundan devindiğinde

kalbini ağzına salan

namının her gelişinde

ederi ısırılmak olsa

dudaklarımın

Şuracıkta bir çanak

Leb-leb-i olsak....,

Ah! ! ! 

10 10 05', 'sağ uç köşesinden başlayıp sol uç köşesine uzansam arasından ıslak ıslak salınsam uzun uzun meltemlerle üstünden solunsam dudaklarının an(ı)...', ARRAY['Türk Edebiyatı','Şiir','Yasemin Sezer Tulgar']::text[], 8.5, '{"poet":"Yasemin Sezer Tulgar","poet_slug":"yasemin-sezer-tulgar","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/leb-leb-i-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geceler', 'geceler-ugur-oguz-sahin-ikqk4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sermayeden çalıyor zaman uçup gidiyor seneler

Yamalı bohça yalan ölümüne sevmeler

Bazı şeyleri anlatmaya yetmiyor heceler

Kimine göre sırdaş kimine göre hain geceler', 'Sermayeden çalıyor zaman uçup gidiyor seneler Yamalı bohça yalan ölümüne sevmeler Bazı şeyleri anlatmaya yetmiyor heceler Kimine göre sırdaş...', ARRAY['Türk Edebiyatı','Şiir','Uğur Oğuz Şahin']::text[], 8.5, '{"poet":"Uğur Oğuz Şahin","poet_slug":"ugur-oguz-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/geceler-110-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Perde', 'perde-mehmet-lutfu-aydin-dth3x', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yönetmen sahneye koydu bir oyun

Seyirci parterde, sessiz sedasız

Verildi işaret, başladı ayin

Açıldı ilk perde, sessiz sedasız 

Bu tuhaf sahnede türlü desise

Arlılar düşmekte karlı kasise

Dünya malı sebil, kirli hasise

Verildi bir ara, sessiz sedasız

Baş aktör kapıdan girdi nidayla

Hakikat sırrına erdi Huda’yla

Şerefli bir ömrü sürdü edayla

Kapandı son perde, sessiz sedasız', 'Yönetmen sahneye koydu bir oyun Seyirci parterde, sessiz sedasız Verildi işaret, başladı ayin Açıldı ilk perde, sessiz sedasız  Bu tuhaf sah...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Lütfü Aydın']::text[], 8.5, '{"poet":"Mehmet Lütfü Aydın","poet_slug":"mehmet-lutfu-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/perde-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıpranmak Boş Bir Kağıtta', 'yipranmak-bos-bir-kagitta-erdogan-ergin-odm6a', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'soğuk düşlerin esiriyim kaç gecedir

ellerim soğuk, kaldırım taşları gibi

dizilmişler tüm çığlıklarımın ardına

kendimden başka duyan yok sesimi

göz yaşlarımın esiriyim, 

tutunmuyor şimdi göz pınarlarımda

ağlamak değil benimkisi,

yıpranmak boş bir kağıtta

zümrüdü yakan alev gibi düşüyor

ciğerime,

ciğerimin göz yaşları

o ağlıyor

ben yanıyorum

alevde yanan odun misali

anlatsam, anlar mısınız

küçük ellerinin içinde kaybolan bedenimi

şiir yazıyorum sözde

oysa en güzel besteyi o yapıyor

o söylüyor en güzel türküleri

bir ağlaması düşüyor kalemimin ucuna

yıpranıyorum boş bir kağıtta

düşün şimdi

neyin varsa elinde değerli

çıkar mı şiir,

hastayken sevgili', 'soğuk düşlerin esiriyim kaç gecedir ellerim soğuk, kaldırım taşları gibi dizilmişler tüm çığlıklarımın ardına kendimden başka duyan yok sesi...', ARRAY['Türk Edebiyatı','Şiir','Erdoğan Ergin']::text[], 8.5, '{"poet":"Erdoğan Ergin","poet_slug":"erdogan-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/yipranmak-bos-bir-kagitta-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sanma ki Dönerim', 'sanma-ki-donerim-mehmet-lutfu-aydin-q09w2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Fizan’a yol oldu, çektiğim çile

Üzgünüm, dönemem, çok geç sevdiğim

Diz çöküp önümde, yalvarsan bile

Sanma ki dönerim, çok geç sevdiğim

Sormadın kendine, suç kimde diye

Eğlendin sevenle, aldın da ti’ye

Bir sevdin, bir savdın, bu kapris niye?

Sanma ki dönerim, çok geç sevdiğim 

Çöllerin alazı, gam seli bana

Zemheri ayazı, sam yeli bana

Baykuşun avazı, bam teli bana

Sanma ki dönerim, çok geç sevdiğim

Bakışı ecelim, ey afet kadın 

Canıma can katan, o enfes tadın

Silinmez zihnimden, gizemli adın 

Sanma ki dönerim, çok geç sevdiğim

Yerle gök birleşse, verse el ele

Geceler gündüzler gelse de dile

Gölgeler aslından ayrılsa bile

Sanma ki dönerim, çok geç sevdiğim

Seveni hor görme, gitmez hoşuna

Gizlenir gecenin, kuytu loşuna

Dökülen onca yaş, bence boşuna

Sanma ki dönerim, çok geç sevdiğim', 'Fizan’a yol oldu, çektiğim çile Üzgünüm, dönemem, çok geç sevdiğim Diz çöküp önümde, yalvarsan bile Sanma ki dönerim, çok geç sevdiğim Sorma...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Lütfü Aydın']::text[], 8.5, '{"poet":"Mehmet Lütfü Aydın","poet_slug":"mehmet-lutfu-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sanma-ki-donerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benimde,sevme hakkım varmıdır...', 'benimde-sevme-hakkim-varmidir-zeynep-aydinlioglu-0qeym', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Benimde sevme hakkım varmıdır,? 

Bazen sebepsız gülmeye … 

Bazen hırçınca aglamaya,hakkım varmıdır.? 

Irmakları aşarcasına koşamak, 

Sabah olmuyacakmış gibi, 

geceye kızma hakkım varmıdır.? 

Bazen mehtaba bakıp, 

uzaklara dalmak, 

Gülleri yüregine çekercesine 

koklamak, 

Hasretini agaclara kazıma hakkım varmıdır? . 

Yıldız yıldız olup düşelrimin, 

Hesret çiglerini 

yapraklardan öpme hakkım varmıdır.? 

Yol uzun ömür kısa. 

Sesimdeki yorgunluk. 

gözlerimdeki dalgınlık, 

Bıraz sitemkar,özlemin kavurdugu yürek 

Katmer katmer acı ve özlem. 

Benımde sevme hakkım varmıdır?', 'Benimde sevme hakkım varmıdır,?  Bazen sebepsız gülmeye …  Bazen hırçınca aglamaya,hakkım varmıdır.?  Irmakları aşarcasına koşamak,  Sabah o...', ARRAY['Türk Edebiyatı','Şiir','Zeynep Aydınlıoğlu']::text[], 8.5, '{"poet":"Zeynep Aydınlıoğlu","poet_slug":"zeynep-aydinlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/benimde-sevme-hakkim-varmidir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çiçeklerim Ve Ben', 'ciceklerim-ve-ben-i-lhan-kirbac-spjg1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben gelecek yetiştiririm,

Gelecekte tertemiz bir dünya için.

İlk geldiklerinde pek işlenmemişlerdir,

İşlerim nakkaş gibi nakış nakış.

Ben saf, temiz filizler yetiştiririm,

Ne olur onları kırmayın, incitmeyin.

Gün be gün oya gibi işlerim,

Ne olur onları kirletmeyin.

Ben gelecek yetiştiririm,

Kendileri için, insanlık için.

Ben çiçekler yetiştiririm,

Yasemin çiçekleri gibi mis kokan.

Ben çiçekler yetiştiririm,

Bilim için, yurdum için.

Dünya bahçesinde yer almaları için.

Ne olur onların geleceklerini  mahvetmeyin.

Ben sarmaşıklar yetiştiririm,

Sarılsınlar insanımıza, vatanımıza diye.

Ayrık otuna, ısırgana, 

Yer yok benim bahçemde.

Ve ben gözlerimi kaparken dünyaya,

Son bir kez koklamak için,

Bir demet çiçek getirin başucuma.

Görev yaptığım bahçelerden,

Bitlis''ten, Zonguldak''tan, Tokat''tan,

Isparta''dan, Soma''dan...', 'Ben gelecek yetiştiririm, Gelecekte tertemiz bir dünya için. İlk geldiklerinde pek işlenmemişlerdir, İşlerim nakkaş gibi nakış nakış. Ben sa...', ARRAY['Türk Edebiyatı','Şiir','İlhan Kırbaç']::text[], 8.5, '{"poet":"İlhan Kırbaç","poet_slug":"i-lhan-kirbac","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/ciceklerim-ve-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vasiyetimdir! .', 'vasiyetimdir-ahmet-sureyya-durna-pm8er', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ahmaklardan akıl alma Mehmedim! .

Elin davulunu çalma Mehmedim! .

Atılgan,yürekli adam ol,adam; 

Bostan korkuluğu olma Mehmedim! .', 'Ahmaklardan akıl alma Mehmedim! . Elin davulunu çalma Mehmedim! . Atılgan,yürekli adam ol,adam;  Bostan korkuluğu olma Mehmedim! ....', ARRAY['Türk Edebiyatı','Şiir','Ahmet Süreyya Durna']::text[], 8.5, '{"poet":"Ahmet Süreyya Durna","poet_slug":"ahmet-sureyya-durna","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/vasiyetimdir-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Manifesto', 'manifesto-melih-coskun-njfe2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Şiir değil bu 

Bir yüreğin manifestosu

Delikanlı bir öykünün 

Ömrümüzün tam ortasına çizdiği 

Benzersiz resim.

Aşkın tanımı 

Aşksız zamanlarında

Kansız ve silahsız

Tek kavgası 

Yeniden kurulacak olan 

O masmavi dünyanın. 

Yeryüzüne adanmış 

İmzasız bir yazı 

İnsan olabilmenin 

Kalıbından çıkarılmış,

Adlarını ve isimlerini bilmeden 

Milyonlarca

Milyarlarca

Sevebilmenin 

Kağıtlara dökülmemiş destanı. 

Şiir değil bu 

Bir yüreğin manifestosu 

Dilimde acılarınızdan bana kalan 

İlk ve son şarkı

Şiir değil bu 

Kavganızın en büyük mirası...

2005', 'Şiir değil bu  Bir yüreğin manifestosu Delikanlı bir öykünün  Ömrümüzün tam ortasına çizdiği  Benzersiz resim. Aşkın tanımı  Aşksız zamanlar...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/manifesto-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '03-Aşkı Belalım…', '03-aski-belalim-metin-yildirim-q5d4j', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hüznüne beleyip neşe yönümü, 

Öldürdün giderken aşkı belâlım… 

Dert ile yükleyip her bir günümü, 

Doldurdun giderken aşkı belâlım… 

Hasretin dünyayı verdi ateşe, 

Merhaba demedim, doğan güneşe, 

Binlerce gam keder ufacık döşe, 

Aldırdın giderken aşkı belâlım… 

Gözlerim unuttu, artık uykuyu, 

Bitirmez bu gönül, sana tutkuyu, 

İçimde ecele olan korkuyu, 

Kaldırdın giderken aşkı belâlım… 

Üstüme çekildi, simsiyah bulut, 

Başladı isyanım, bozuldu sükût, 

Vuslatın hayaldir, kalmadı umut, 

Soldurdun giderken, aşkı belâlım… 

Bıraktın özümü, yanan şuleye, 

Döndürdün ardında sadık köleye, 

Perişan hâlimle, bitmez çileye, 

Saldırdın giderken aşkı belâlım…

Hata mı işledim, bilsem suçumu, 

Akıtıp zehrini, yaktın içimi, 

Uğrunda ağaran beyaz saçımı, 

Yoldurdun giderken aşkı belâlım… 

Başımı döndürür, sevdan pervane, 

Yitirdim aklımı, oldum divane, 

Bu aşkın encamı bir tımarhane, 

Çıldırdım giderken aşkı belâlım…

Gittiğin o günü, saydım milâttan, 

Yokluğunda her gün geçtim Sırat’tan, 

Umudum tükendi sensiz hayattan, 

Yıldırdın giderken aşkı belâlım… 

Baharı görmeden döndüm hazana, 

Ölçerim zulmünü, uymaz mizana, 

Bu yorgun bedeni kaynar kazana, 

Daldırdın giderken aşkı belâlım…

Sen diye dünyaya, çekip reddimi, 

Unuttum yolunda, asıl ceddimi, 

Düşmanım olarak bana haddimi, 

Bildirdin giderken aşkı belâlım… 

Şimdi gecelerin oldum sırdaşı, 

Taşlara vururum, çaresiz başı, 

Uykusuz gözümde bunca gözyaşı, 

Buldurdun giderken aşkı belâlım… 

Hayaldir gönlümün artık dileği, 

Bükülmez sanırdım, kırdın bileği, 

Üstüme salıp da kahpe feleği, 

Güldürdün giderken aşkı belâlım… 

Tükendi huzurum, kalmadı rahat, 

Vereyim bu canı, bitsin bu tezat, 

Gelmesin namazım için cemaat, 

Kıldırdın giderken aşkı belâlım… 

Suruna üfledi, sanki İsrafil, 

Ruhumu yitirdim, bedende değil, 

Çıktığın kapıya, koyup Azrail, 

Çaldırdın giderken aşkı belâlım…

www.adinisiirlerkoysun.com

Adını Şiirler Koysun', 'Hüznüne beleyip neşe yönümü,  Öldürdün giderken aşkı belâlım…  Dert ile yükleyip her bir günümü,  Doldurdun giderken aşkı belâlım…  Hasretin...', ARRAY['Türk Edebiyatı','Şiir','Metin Yıldırım']::text[], 8.5, '{"poet":"Metin Yıldırım","poet_slug":"metin-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":58,"source_url":"https://www.antoloji.com/03-aski-belalim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sûr', 's-r-gulay-yildiz-comox', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ve üflendi sûru bizliğin

Ellerinin çekindiği

Tendim ben...

Tenimi verdim dünya rüzgarına

Savurduğu; 

Bencil uykusuydu gecenin

Ve üflendi sûru bizliğin

Yapmacık oyunlardı sahnelenen

Doğaçlama gülüşlerden bile eksik

Tirattım ben...

Repliğimi verdim lanet celladına

Kurduğu o ahlı cümlelerdi dilinin...

Ve üflendi sûru bizliğin

Bilmediğin; 

Duyduğum, ses! 

Karmaşasında herkesin,

.......Bilincindeyken hiçliğin,

...........Kaderimin sorguladığı 

Verilen hesaptım ben', 'Ve üflendi sûru bizliğin Ellerinin çekindiği Tendim ben... Tenimi verdim dünya rüzgarına Savurduğu;  Bencil uykusuydu gecenin Ve üflendi sûr...', ARRAY['Türk Edebiyatı','Şiir','Gülay Yıldız']::text[], 8.5, '{"poet":"Gülay Yıldız","poet_slug":"gulay-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sur-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dehliz', 'dehliz-rahim-tas-ieu6k', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dehlizde yosuna tutunur 

Su insan kokar 

Çıkar kıyılara 

İnsan su kokar 

Kucaklar kum tanelerini 

İnsan toprak kokar 

Örter izlerini çöl fırtınası 

Toprak insan kokar…

11.10.2005', 'Dehlizde yosuna tutunur  Su insan kokar  Çıkar kıyılara  İnsan su kokar  Kucaklar kum tanelerini  İnsan toprak kokar  Örter izlerini çöl fır...', ARRAY['Türk Edebiyatı','Şiir','Rahim TAŞ']::text[], 8.5, '{"poet":"Rahim TAŞ","poet_slug":"rahim-tas","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/dehliz-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Değilmiydin', 'sen-degilmiydin-nazan-i-zmirli-3fa0y', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'tutsakken karanlıklara yüreğim

şafaklara hasret gözlerim

ince bacaklarında taşıdığın gövdende

kanat çırpışlarının,guguklu saatim

bakışlarının; müebbetimin  vazgeçilmezi olacağını

bilirmiydim! 

artık vazgeçilmezimsin gönül  hapsimde

sen değilmiydin

umutlarıma kar yağdığında

taş duvarlar arasında

iki parmaklık arkasında

buzdan camımı tıklayan

sen değilmiydin

sıtmalar tuttuğunda 

umutlar sıkışmış ranzalarda

ter kokan tozlu şiltenin altında

yarınları taşıdığın ak kanatlarınla

inmiş kaşlarımı kaldıran

Nazan İzmirli

1978-şubat-trabzon', 'tutsakken karanlıklara yüreğim şafaklara hasret gözlerim ince bacaklarında taşıdığın gövdende kanat çırpışlarının,guguklu saatim bakışlarını...', ARRAY['Türk Edebiyatı','Şiir','Nazan İzmirli']::text[], 8.5, '{"poet":"Nazan İzmirli","poet_slug":"nazan-i-zmirli","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sen-degilmiydin-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül Davası', 'gonul-davasi-abdullah-yasar-erdogan-20myw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ey gönül dostu; yılmak, yıkılmak yok.

Bu dava uludur, kafana iyice sok.

Acz-ı beşersin, elbet diyeceğin çok,

İlerlemek, gönül davasında gardaş..

Sevdamız bu, burçlarda dalgalanan,

Alperenlerdi Malazgirt’te şahlanan,

Viyana kapılarına aşktı dayandıran,

Şahlanmak, gönül davasında gardaş.

Her karış toprakta, bin destanım,

Bazen Alparslan, bazen Osman’ım.

Hilal gölgesinde coşmakta kanım,

Ulviyet, gönül davasında gardaş.

Fatih’im; güllelerim düşman sinesine,

Sığınmadık, sığınmayız etek gölgesine,

Çıkmışız bu davanın son derekesine,

Durmak yok, gönül davasında gardaş.

Acâib-i dekâik*döner  ümmet üzerinde,

Tuğ-Sancak hapis, işgüzarların elinde,

A’la-yı İlliyyin* iman nuru fevkinde,

Susmak yok, gönül davasında gardaş.

*ACÂİB-İ DEKÂİK: Anlaşılmaz hileler, ince oyunlar. 

*A''LÂ-YI İLLİYYÎN: Cennette en yüksek derece, olgun kişilerin Allah katındaki dereceleri.', 'Ey gönül dostu; yılmak, yıkılmak yok. Bu dava uludur, kafana iyice sok. Acz-ı beşersin, elbet diyeceğin çok, İlerlemek, gönül davasında gard...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Yaşar Erdoğan']::text[], 8.5, '{"poet":"Abdullah Yaşar Erdoğan","poet_slug":"abdullah-yasar-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/gonul-davasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut Varmı', 'umut-varmi-mehmet-can-jsv5q', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'karanlık bekler umutlarla..

güneşi değil elbet..

birazcık aydınlığı..

dalında yaprak bekler..

kasırgayı değil elbet..

hafif bir esintiyi..

kımıldamak adına...

ve buruk yürekler bekler..

kahkahaları değil elbet..

samimi bir gülümsemeyi..

dudaklarda beliren..', 'karanlık bekler umutlarla.. güneşi değil elbet.. birazcık aydınlığı.. dalında yaprak bekler.. kasırgayı değil elbet.. hafif bir esintiyi.. k...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Can']::text[], 8.5, '{"poet":"Mehmet Can","poet_slug":"mehmet-can","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/umut-varmi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki Sancak', 'i-ki-sancak-abdullah-yasar-erdogan-9wk9r', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İki sancak, bir alem; 

İşte budur gönül dünyam.

Anlamasa da zalim kalem,

İlelebettir benim davam.

İki sancağımda burca dikilecek.

Dileğim o ki, ölmeden görmek.

Sancağın biri, gönül sevdam,

Diğeri hayatta varken ölmek.

Ey gönül dağımın, tuğları,

Burca dik sancağı, sal sevdayı.

Bedayı* değilim icraatım yok,

Anlayamadım şu zalim dünyayı.

Ülkümdür, özümdür son sözümdür.

Bakmaz olsa da, gören gönül gözümdür.

Mehmet’te, Ahmet’te o sevdayı gördüm.

Mahşerde kızarmayacaktır bu yüzüm.

Hayatta bedbinlik uzaktır bana.

Yüreğimle girdim bu davama,

Tekrar söylemem gerektir,

Helal getirmem, getirtmem sevdama...

BEDÂYİ'': İcat edilmiş güzel şeyler. Sanat eserleri.', 'İki sancak, bir alem;  İşte budur gönül dünyam. Anlamasa da zalim kalem, İlelebettir benim davam. İki sancağımda burca dikilecek. Dileğim o ...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Yaşar Erdoğan']::text[], 8.5, '{"poet":"Abdullah Yaşar Erdoğan","poet_slug":"abdullah-yasar-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/iki-sancak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Git Diyorum', 'git-diyorum-mehmet-can-20mh3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Git Diyorum.

diyebiliyorum..

kavgaların senin olsun..

kıskançlıkların.

güvensizliklerini beraberinde götür..

aynada baktığın ben değilim..

öfkem sana değil..

bana yüreğinde beyaz sevgiler taşıyan..

yüzünde umutlarla gülücükler açan..

insanlar gelsin..

varsın içinde aşk olmasın..

ama dert de olmasın..', 'Git Diyorum. diyebiliyorum.. kavgaların senin olsun.. kıskançlıkların. güvensizliklerini beraberinde götür.. aynada baktığın ben değilim.. ö...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Can']::text[], 8.5, '{"poet":"Mehmet Can","poet_slug":"mehmet-can","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/git-diyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boş Çevirme', 'bos-cevirme-burhanettin-akdag-9svyf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Darlanıp da geleni

Boş çevirme mecalinden.

_____Hayalleriyle geleni

_____Boş çevirme hülyasından.

Dost bağından geleni

Boş çevirme muhabbetinden.

_____Yaralanıp da geleni

_____Boş çevirme çâresinden.

Yıkılıp da geleni

Boş çevirme omuzundan.

_____Dertleriyle geleni

_____Boş çevirme dermanından.

Sevinciyle geleni

Boş çevirme tebessümünden.

_____Azap çekerek geleni

_____Boş çevirme dualarından.

Hüzünleriyle geleni

Boş çevirme baharından.

_____Derviş olup da geleni

_____Boş çevirme dergâhından.

Sevdasıyla geleni

Boş çevirme gönül tahtından...

(10.10.2005)', 'Darlanıp da geleni Boş çevirme mecalinden. _____Hayalleriyle geleni _____Boş çevirme hülyasından. Dost bağından geleni Boş çevirme muhabbeti...', ARRAY['Türk Edebiyatı','Şiir','Burhanettin Akdağ']::text[], 8.5, '{"poet":"Burhanettin Akdağ","poet_slug":"burhanettin-akdag","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/bos-cevirme-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlıklar', 'yalnizliklar-mehmet-can-bi84p', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yalnızlık gurbetmidir.

gurbet yalnızlıkmıdır..

kalabalık içinde..

teklik yalnızlıkmıdır? 

limansız  gemi..

isimsiz yolculuk..

kaldırım taşları..

yoldaşlık..

yalnızlık

yanlışların bedeli..

her zaman ömürmüdür..

acımasızlık..

karışıklık..

haklı durumda olurken bile..

haksızlık..

revamıdır? 

şiir..

kelimeler..

öfkeler..

düşünceler..

gözyaşları..

yürekte kopan fırtınalar..

içinde yaşarken en büyük savaşı..

gülümsemeler..

akıllı işimidir

herkesmi böyledir..', 'Yalnızlık gurbetmidir. gurbet yalnızlıkmıdır.. kalabalık içinde.. teklik yalnızlıkmıdır?  limansız  gemi.. isimsiz yolculuk.. kaldırım taşla...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Can']::text[], 8.5, '{"poet":"Mehmet Can","poet_slug":"mehmet-can","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/yalnizliklar-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ezdiğimiz Kır Çiçekleri...', 'ezdigimiz-kir-cicekleri-ulug-celik-pqvdy', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'zamanın birinde çok güzel bir dilruba yaşarmış

padişahın kızıymış ve çok güzelmiş

herkes bütün prensler onu istemeye gelirlermiş taa uzaklardan

duyan güzelliğini,

gören güzelliğini dayanamazmış hiç

bizim fakir de görmüş onu bir gün

ve vurulmuş...

bir ahu gözlü zebun etmiş onu kendine

ama kızın biraz burnu kalkık! ..

biraz da kibirliymiş.

burum kıvırırmış her gelen yakışıklı ve zengine...

oysa ki fakir onu çok sevmiş 

ve aldırmadan fakirliğine bir gün 

sarayın bahçesinde açmış sevdasını ahu gözlü güzele

ve ol güzel ona çok gülmüş hem de çok

incinmiş yüreciği

kırılmış gururu

''''ben demiş nice prenslere hayır derken

sen kim oluyorsun be hey ahmak fakir! ..''''demiş

ve bizim fakir dönmüş arkasını

yüreğinde yare vurmuş kendini yollara

ülke ülke

diyar diyar gezmiş senelerce

mecnun olmuş aşkından

ve karşılıksız sevdasından

yeter ki onu bir daha görmeyeyim demiş

içim olmasın yangın yeri

vurmuş yollara senlerce

ve yıllar yıllar sonra dönmüş sevdiğinin

maşukunun yurduna

ve yoldan geçerken birine rastlamış

sormuş dillere destan güzele ne oldu diye

yoldaki adam demiş ki ''''ha o mu? ''''

''''işte şu fakir kulubesinde bir sıska cüce ile evlendi o

onunla o derme çatma evde yaşıyor''''

mazlumun ahı mı tutmuş nedir? 

olamaz demiş aynı kişi olamaz! ..

 o bir padişah kızı neden evlensin çirkin bir cüceyle? 

inanamış ama merak da etmiş hani

varmış kulubenin yanına bahçesinde güller varmış kulubenin

beklemiş gizlenmiş bir yere bakmış o çıkarmı diye

ve...

çirkin cüce çıkmış gerçekten kulübeden ve uzaklaşmış o evden

sonra da ahu gözlü dilruba çıkmış bahçeye

karşısına dikilmiş bizim mecnun

demiş ''''beni hatırladın mı? ''''

kız bakmış bakmış

''''hatırladım'''' demiş gözleri dolarak

''''afedersin'''' ama demiş fakir

''''beni zengin olmadığım 

ve çirkin bellediğin için seçmedin şimdi bu halin nedir? ''''

kız da demiş ona

''''bak demiş şu gül bahçesine var

ve dediğimi yap beni anlayacaksın sen''''

''''olur ''''demiş fakir mecnun

kız demiş ki 

''''şu gül sırasına git ve arkandaki bıraktığın çiçeğe hiç bakmadan 

ve geri dönmeden en güzelini getir bana''''

ve mecnun varmış aynen öyle yapmış

sıra sıra güller derken bir gülü koparacak bakmış daha güzeli var

bari onu vereyim kıza demiş

ve diğeri ve diğeri derken 

en güzelini alayım derken gül sırası bitmiş

en sonda tek bir çiçek kalmış

amma kaktüslü

dikenli bir çiçekmiş geriye kalan

ve arkaya da dönemiyormuş çünkü söz vermiş kıza

neyse onu koparmış getirmiş kıza

kız demiş 

''''o gül bahçesinde bula bula ancak bu dikenli

devetabanı gibi çiçeğimi buldun getirdin bana? ''''

ama demiş ki fakir

''''daha güzeli var daha güzeli var derken

kala kala buna kaldım ben 

ve onu getirdim çünkü demiştin ya bana geri dönmek yok''''

işte demiş kız 

''''bende daha güzeli var daha güzeli var derken kala kala bu sıska,çirkin cüce kaldı bana da...''''

''''anladım''''demiş ''''anladım...''''

siz de anladınız mı kızın dediğini? 

işte güle ulaşmak isterken 

biz de nice kır çiçeğini eziyoruz bilmeden

kala kala ne kalıyor elimizde

bir dikenli kaktüs

gül değil ama

kır çiçeklerini ezmeyelim değil mi? 

çiçeklerin şahıdır gül amma

kır çiçeklerinin ne suçu var? ...', 'zamanın birinde çok güzel bir dilruba yaşarmış padişahın kızıymış ve çok güzelmiş herkes bütün prensler onu istemeye gelirlermiş taa uzaklar...', ARRAY['Türk Edebiyatı','Şiir','Uluğ Çelik']::text[], 8.5, '{"poet":"Uluğ Çelik","poet_slug":"ulug-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":87,"source_url":"https://www.antoloji.com/ezdigimiz-kir-cicekleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yabancı', 'yabanci-mehmet-can-kb72i', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ben yabancı 

ben yalancı 

ben hancı..

içimde sancı..

kimsenin bana

kalmadı inancı..

ben köle..

herkes baş tacı..

doğrular bende..

adım yalancı..

sen söyle bacı

nedir ilacı?', 'ben yabancı  ben yalancı  ben hancı.. içimde sancı.. kimsenin bana kalmadı inancı.. ben köle.. herkes baş tacı.. doğrular bende.. adım yalan...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Can']::text[], 8.5, '{"poet":"Mehmet Can","poet_slug":"mehmet-can","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yabanci-55-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdanın yüzü güzel', 'sevdanin-yuzu-guzel-nazan-i-zmirli-navjw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'buzlu bir camın arkasında

puslu puslu baksada....

rüzgarla ürpererek  dağılan

yağmur taneleriyle  ıslanan

saçların yüzünü dolasada

sevdanın yüzü güzel!', 'buzlu bir camın arkasında puslu puslu baksada.... rüzgarla ürpererek  dağılan yağmur taneleriyle  ıslanan saçların yüzünü dolasada sevdanın ...', ARRAY['Türk Edebiyatı','Şiir','Nazan İzmirli']::text[], 8.5, '{"poet":"Nazan İzmirli","poet_slug":"nazan-i-zmirli","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sevdanin-yuzu-guzel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut ve umutsuzluk', 'umut-ve-umutsuzluk-ercan-akbay-a3q0c', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Umut düşünen beynin boyutlarıdır

  Umutsuzluk düşünemeyenlerin gözyaşıdır

  Umut yeni günde güneşi selamlamaktır

  Umutsuzluk kara bulutlara hep çağrıdır

  Umut başarıya ulaşmanın enerjisidir

  Umutsuzluk tükenmenin habercisidir

  Umut hep çocukların gülüşünde açar

  Umutsuzluk aydınlıklardan izbelere kaçar

  Umut bir dilim ekmek,bir tas çorba

  Umutsuzluk servet içinde yoksul olmaktır

  Umut hep bir şiir

  Hep yarına solumak

  Umutsuzluk akmayan nehir

  Çatlayan dudak

  Zaman tünelinde kaybolmaktır.....

                               GÜNAYDIN GAZETESİ  15.12.1994', 'Umut düşünen beynin boyutlarıdır   Umutsuzluk düşünemeyenlerin gözyaşıdır   Umut yeni günde güneşi selamlamaktır   Umutsuzluk kara bulutlara...', ARRAY['Türk Edebiyatı','Şiir','Ercan Akbay']::text[], 8.5, '{"poet":"Ercan Akbay","poet_slug":"ercan-akbay","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/umut-ve-umutsuzluk-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Farkedilemeyen Yaralarımız', 'farkedilemeyen-yaralarimiz-ulug-celik-tq6iy', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'unutmak

ya da unutulmak mıdır yaralayan insanı? 

yoksa fark edilememekmidir? 

birileri farketsin istiyoruz sanki

acı çeken yüreğimizi

ve sarsın diye bekliyoruz

ama yaralarımızı saramıyoruz kendimizin

çünkü belki benim gibi sırtınızdaki hançer yarasını sarmaya 

elleriniz yetişmiyor

elleriniz kısa kalıyor

saramıyorum ben o yareyi

oluk

oluk

kan akıyor

hissediyorum

ve kanıyorum boyuna...', 'unutmak ya da unutulmak mıdır yaralayan insanı?  yoksa fark edilememekmidir?  birileri farketsin istiyoruz sanki acı çeken yüreğimizi ve sar...', ARRAY['Türk Edebiyatı','Şiir','Uluğ Çelik']::text[], 8.5, '{"poet":"Uluğ Çelik","poet_slug":"ulug-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/farkedilemeyen-yaralarimiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bulursun beni', 'bulursun-beni-i-brahim-kilinc-wo164', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Son günlerde ben hep seni ararım

Dünya gibi için için yanarım

Hem yanarım, hem de titrer donarım

Her dakka bir halde bulursun beni

Cephanesiz bir askerim emrinde

Cepheden cepheye sürersin beni

Bir cepheden kara haberim gelir

Musalla taşında bulursun beni', 'Son günlerde ben hep seni ararım Dünya gibi için için yanarım Hem yanarım, hem de titrer donarım Her dakka bir halde bulursun beni Cephanesi...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Kılınç']::text[], 8.5, '{"poet":"İbrahim Kılınç","poet_slug":"i-brahim-kilinc","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bulursun-beni-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çizmek', 'cizmek-nazan-i-zmirli-oyx93', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'seni çizmek istiyorum,kara kalemimin ucunda

resmetmek seni karalarla aklarla

karalar geceleri,aklar karları

geceler bensizliği,karlar gelinliğimi anlatsın.

karalarım her yanı seni anlatmaktansa

seni çizmek istiyorum, sulu boya fırçamda

resmetmek istiyorum seni mavi, yeşil,sarı,mor dalga dalga

mavi enginliğindir sonsuz ufuklarda

yeşil gözlerindir, her yağmurun ardında

sarı arzularımızdır, ateş kırmızısına dönüşen

mor geleceğimizdir güneşin batışında

karıştırırım renkleri heyecanla 

sulu sulu ıslak bakışlarda

seni çizmek istiyorum,pastel  boyalarda

pekişsin istiyorum duygular yüreklerde

güneşler doğuruyorum 

dolunay çıkıyor karanlık gecelerine

mavi dalgalar,beyaz köpükler kıpır kıpır

rüzgarın sesi gri mavi aşkı anlatır.

günü batırırım,grubun doyamazsın seyrine

arkasından gökyüzünün cümbüşüne

boğarım renkleri birbiri içinde şevki anlatan

seni çizmek istiyorum, tuvalimde kalsın ebediyete

en kalın fırçalarla, en ağır boyalarla

oturttum seni baş köşeye

bakıyorsun bana yan profilde

bakışların yüreğimin derinliklerinde

ellerin ellerimi  avuçlamış  sıkı sıkı

dudakların konuşur gibi,

fırçalarım çizer portrenin son çerçevesini

ve ben hissederim,beni izlediğini

imza köşesinde....

Nazan İzmirli

30.01.03-antalya', 'seni çizmek istiyorum,kara kalemimin ucunda resmetmek seni karalarla aklarla karalar geceleri,aklar karları geceler bensizliği,karlar gelinl...', ARRAY['Türk Edebiyatı','Şiir','Nazan İzmirli']::text[], 8.5, '{"poet":"Nazan İzmirli","poet_slug":"nazan-i-zmirli","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/cizmek-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Gece', 'bu-gece-nazan-i-zmirli-w4jdh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bu gece...

neden bilmem

sensizlik çöktü yine

seslensem duyarmısın,

seni seviyorum hala diye

bu gece

neden bilmem

özlem gemisi geldi yine

yolcusu  yok, sen yok! hasret yüklü diye

bu gece 

neden bilmem

yüreğime  sığmaz oldum

bedenimde alevlere esir, yoluna köle oldum

bu gece

neden bilmem

sesin kulaklarımda çınlar oldu

rüzgarın sesi,denizin sesi,fısıldar

s e n i   s e -v i- y o- r u m   hala diye...........................

10.01.05-antalya', 'bu gece... neden bilmem sensizlik çöktü yine seslensem duyarmısın, seni seviyorum hala diye bu gece neden bilmem özlem gemisi geldi yine yol...', ARRAY['Türk Edebiyatı','Şiir','Nazan İzmirli']::text[], 8.5, '{"poet":"Nazan İzmirli","poet_slug":"nazan-i-zmirli","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/bu-gece-159-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-sibel-demiroglu-qtz7d', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen dikenli gülüm

Sen hayatimin isigi

Sen su aglayan kalbim tarafindan özlenen

Sen rüyalarimda benim olan

Sen beni derinden yaraliyan hancer

Sen bu yalan dünyada tek istedigim ama asla kavusamiyacagim

Sen unutmaya calistigim ama halen deliler gibi sevdigim askim

Sen herseyimi elline verdigim ama karsiliginda bir ihanet aldigim kabusum

Beni unut, bu söylediklerimi unut, yasadigimiz o günleri unut

Unut ki, kalbimdeki o derin yara kapansin ve yeniden yasamaya baslaya bilim

Beni azicikda olsa sevdiysen bir kelime yeter

Hoscakal de ve ebediyen cek git…', 'Sen dikenli gülüm Sen hayatimin isigi Sen su aglayan kalbim tarafindan özlenen Sen rüyalarimda benim olan Sen beni derinden yaraliyan hancer...', ARRAY['Türk Edebiyatı','Şiir','Sibel Demiroglu']::text[], 8.5, '{"poet":"Sibel Demiroglu","poet_slug":"sibel-demiroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sen-653-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fesat', 'fesat-hekim-coskun-500ct', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'seni fesat

ve seni seni

tüm düşüncelerimi işgal edersin

bu da yetmiyormuş gibi çekip gidersin.

son bahar rüzgarına fısıldadığın,

tüm fesatlıklarını duydum.

denizin küçük köpüksüz dalgaları getirdi bana; 

hani sana misilleme yapıp aramadığımı sanmışsın ya,

seni aradım,

uçuşan bir kelebeğe dahi seni sordum; 

ve sana getirsin diye kanatlarından öptüm,

bak inanmazsan sim izleri hala dudaklarımda,

ve hatta 

ve hatta

bir ara öfkesinden olacak denizin,

güçlü bir dalganın ıslattığı bedenim hala nemli.

ve hala seni düşünüyorum,

sen nazlı çiçeğim gibi dalında ve olgunsun.

sende beni seviyormuşsun.

ve hala içinde ukde  kalan; 

kırmızı şarap ve yağmurlu bir bahar akşamı gibi,

ve avuçlarında hissettiğin sıcaklığım,

senin cana yakınlığın.

bak gözlerinde gördüğüm o nem

ve dudaklarının mahzun duruşu 

kilometrelerce uzağımda bana sitemin,

seni fesat seni.

bana özel

ve de çok güzelsin.

bak duran ve hareket eden tüm maddeler,

uzak,

yada yakın tüm cisimler,

ve hatta  bir noktaysan tüm zamanlarımda,

durma gel,

yada gel de,

ben sana geleyim.

www.antoloji.com\hekim_coskun', 'seni fesat ve seni seni tüm düşüncelerimi işgal edersin bu da yetmiyormuş gibi çekip gidersin. son bahar rüzgarına fısıldadığın, tüm fesatlı...', ARRAY['Türk Edebiyatı','Şiir','Hekim Coşkun']::text[], 8.5, '{"poet":"Hekim Coşkun","poet_slug":"hekim-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/fesat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uyandim ben', 'uyandim-ben-sibel-demiroglu-gwyzb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Tanistigimiz o gün hep aklimda

Yanima gelmen, beni büyülemen

Bana gözlerinle seni istiyorum demen

Iste o gün askim vuruldum ben…

Bana seni sevmiyorum, sevmiyecegim dedigin o gün hep aklimda

Hanceri yüregime sapladin, kan kusturdun

Bana gözlerinle seni istemiyorum dedin

Iste o gün acimasiz insan öldüm ben…

Bu beni son görüsün dedigin o gün hep aklimda

Beni yaraladin, boynumu büktün 

Bana gözlerinle gercek yüzünü gösterdin

Iste o gün bittmis en güzel rüyam 

Iste o gün uyandim ben…', 'Tanistigimiz o gün hep aklimda Yanima gelmen, beni büyülemen Bana gözlerinle seni istiyorum demen Iste o gün askim vuruldum ben… Bana seni s...', ARRAY['Türk Edebiyatı','Şiir','Sibel Demiroglu']::text[], 8.5, '{"poet":"Sibel Demiroglu","poet_slug":"sibel-demiroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/uyandim-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'E y K a l b i m! ..', 'e-y-k-a-l-b-i-m-ayse-gul-p5t1m', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Denizde boğulan yağmur

şikayet ediyordu

yağdığı mavi yere

ateşten sözcükler geçerken yüreğimden...

Tutuşuyordu

düne ait ne varsa

hızlı geçen zamanın rüzgarından

bir tek kalbimdi yaralı kurtarabildiğim

yaşamak denilen

bu yangın yerinden...

Ey Kalbim! 

şimdi

iyileşmeyi unutan yaralarınla 

taşıyorum seni.

dağlar yalnızlığını,

rüzgar fırtınayı,

ağaç kırılan dallarını,

toprak depremleri,

anne bebeğini,

yaşam ölümü,

zaman umudu,

_______________taşıdığı gibi...

10/10/005 İst.A.G.Nisan_ca', 'Denizde boğulan yağmur şikayet ediyordu yağdığı mavi yere ateşten sözcükler geçerken yüreğimden... Tutuşuyordu düne ait ne varsa hızlı geçen...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Gül']::text[], 8.5, '{"poet":"Ayşe Gül","poet_slug":"ayse-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/e-y-k-a-l-b-i-m-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anam', 'anam-nazan-i-zmirli-ui5wm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'anam benim, bilmezdim

göçmen kuşu olmadan

hasret sen kokmadan

ayrılıkların  mızrağını

bugün anneler günü

içim buruk gözüm yaşlı

beni dünyaya getiren anam uzaklarda

beni ana yapan yavrum uzaklarda

attım kendimi doğanın kucağına

yeşil çimler,kır çiçekleri

özlem  kokar yaban gülleri

bulutlar ağlamaklı yanlızlığıma

güneş ısıtmaz üşüyen yüreğimi

Dalgalar hasretimi anlatıyor

hırçınca kükrüyor kıyılarda

sakalar çılgınca ötüşüyor yüreğime

devrik bir söğüdün dalında

anam yarim  dört bir yanımda

anam dedi bir ses

ruhumu okşarcasına

elinde bir manisa lalesi

sokuldu yanıma

sevgiye muhtaçcasına...

2002-mayıs-antalya', 'anam benim, bilmezdim göçmen kuşu olmadan hasret sen kokmadan ayrılıkların  mızrağını bugün anneler günü içim buruk gözüm yaşlı beni dünyaya...', ARRAY['Türk Edebiyatı','Şiir','Nazan İzmirli']::text[], 8.5, '{"poet":"Nazan İzmirli","poet_slug":"nazan-i-zmirli","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/anam-61-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Enkaz', 'enkaz-ozan-turk-wntnm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aramanı mı bekliyor

Nedir bu halim

Çıkarıp gazete enkazından

Saatler, günler sonra 

Eski postalımı

Eskiden olduğu gibi

Soğukta,

Yürümeliyim. 

Eskisi gibi değilim ama

Bir ney sesi duysam…

Önce gözlerime şaşırıyorum

Ve sonra

İhtiyar bir kahkaha atıp kendime

Olur, 

Olur, böyle şeyler

Diyorum…', 'Aramanı mı bekliyor Nedir bu halim Çıkarıp gazete enkazından Saatler, günler sonra  Eski postalımı Eskiden olduğu gibi Soğukta, Yürümeliyim....', ARRAY['Türk Edebiyatı','Şiir','Ozan Türk']::text[], 8.5, '{"poet":"Ozan Türk","poet_slug":"ozan-turk","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/enkaz-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarısı Yanmış Yürek', 'yarisi-yanmis-yurek-omer-yildiz-37dzh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen 

Varya sen...

Kaya sırtında

Yosun gibisin.

Düğüm düğüm örmüşsün ruhunu.

Sönmüş,

Küle dönmüşsün.

Bense,

Tutuştum.

Öpülesi dudaklarında

Sevdim sözü mahkumun,

Mahkumuna

Bir buselik af istiyorum...

Umut yok,

Sana af yok desen,

Moğol bozkırlarına

Sürgünede göndersen,

benden

Kurtulamazsın...

Bütün düğümlerini 

İlmik ilmik çözecek,

Tibet yaylarında gezeceğim.

Çin seddinde tutsak edileceğim.

Varşova''da azılı ajanlar peşime düşecek,

İspanya''da rakaseler

Ölümden kurtaracaklar beni,

Paris''te 

Sanatın imbiğinden gececeğim,

Viyanada yakalanacağım.

Asacaklar,

Tuna''ya atacaklar beni.

Balıklara yem olacağım,

Kara Deniz''de

Takalar turolle çekecekler beni

Boğazda

Bir meyhanede

Rakına meze diye geleceğim...

Bir lüferde

Yarısı yanmış yürek

Görürsen

Sakın şaşırma...

Dudakların değdiğinde...

Yeniden dirileceğim...', 'Sen  Varya sen... Kaya sırtında Yosun gibisin. Düğüm düğüm örmüşsün ruhunu. Sönmüş, Küle dönmüşsün. Bense, Tutuştum. Öpülesi dudaklarında Se...', ARRAY['Türk Edebiyatı','Şiir','Ömer Yıldız']::text[], 8.5, '{"poet":"Ömer Yıldız","poet_slug":"omer-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/yarisi-yanmis-yurek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölümsüz Ölümler', 'olumsuz-olumler-nazan-i-zmirli-w2ifl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ölmekten korkardım

bucak bucak kaçardım

kapımızı çalmadan

sevdiklerimi benden almadan

ayrılıkların ölümle geleceğini

hasretin başlangıcı 

kavuşmanın imkansızlığı

umutsuz bir yolculuk olduğunu

ben değildi endişelerim

sevdiğim,sevenlerim,sevmek istediklerim

onları görememek,sesini duyamamak

bir gün onları terkedeceğimi düşünmez

onların beni terkedeceğinden endişe ederdim

anladımki hasretler...

ölümsüzde yaşanır

yüreğini parçalar, parçalar

gözündeki yaşlar içine akarmış

terkeden sevenlerinde olur

terkeden sende olursun

birgün kavuşabilirim sevinci

ile acı çekersin

gel gitller başlar

ayrılıklar  hasretler

ölümsüz ölümler 

ya sevdiklerim beni terketti

ya da ben sevdiklerimi

acımasızca acı çektirdik

sevgi  dolu yüreklere.....nedensizce....

Nazan İzmirli

mayıs-2002-antalya', 'ölmekten korkardım bucak bucak kaçardım kapımızı çalmadan sevdiklerimi benden almadan ayrılıkların ölümle geleceğini hasretin başlangıcı  ka...', ARRAY['Türk Edebiyatı','Şiir','Nazan İzmirli']::text[], 8.5, '{"poet":"Nazan İzmirli","poet_slug":"nazan-i-zmirli","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/olumsuz-olumler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vekil Saldım Şu Meclise', 'vekil-saldim-su-meclise-yusuf-ter-lp6sd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Namaz kılıp, Allah derler.

Helal bilmez, haram yerler.

Meydanlarda, yalan söyler.

Vekil saldım, şu meclise.

Ceplerinde, mühür taşır.

Aşır devlet, malı aşır.

Sol gösterip, sağa düşür.

Vekil saldım, şu meclise.

Yırtık pırtık, takım oldu.

Amerika’dan, oy buldu. 

Yemin bozup, Namaz kıldı.

Vekil saldım, şu meclise.

Derin devlet, ne de derin.

Yollarına, halı serin.

Doymak bilmez, daha verin.

Vekil saldım, şu meclise.

Kat elbise, oturanlar.

Bankaları, batıranlar.

Halkımı aç, yatıranlar.

Vekil saldım, şu meclise.

Yusuf  ayak, sürüyelim.

Şu meclise, yürüyelim.

Pislikleri, kürüyelim.

Vekil saldım, şu meclise.', 'Namaz kılıp, Allah derler. Helal bilmez, haram yerler. Meydanlarda, yalan söyler. Vekil saldım, şu meclise. Ceplerinde, mühür taşır. Aşır de...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ter']::text[], 8.5, '{"poet":"Yusuf Ter","poet_slug":"yusuf-ter","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/vekil-saldim-su-meclise-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Soya Soya', 'soya-soya-nilgun-yuce-2jcqm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İçi dolu boş dünya,

İnsanoğlu soya soya,

...............Ne doğa bıraktılar ne hava..

Ürediler sıra sıra,

Tüketdiler çala çala,

...............Ne doğa bıraktılar ne hava..

Dünya geniş boldu saha,

Sığmadılar dağa taşa,

...............Ne doğa bıraktılar ne hava..

İnsanız diye şiştiler,herşeyi hak bildiler,

Hayvanları ittiler, ya da  pişirip yediler, 

...............Ne doğa bıraktılar ne hava..

Aç gözlülük insan da,

Ye ye doymazlar asla,

...............Ne doğa bıraktıları ne hava..', 'İçi dolu boş dünya, İnsanoğlu soya soya, ...............Ne doğa bıraktılar ne hava.. Ürediler sıra sıra, Tüketdiler çala çala, ................', ARRAY['Türk Edebiyatı','Şiir','Nilgün Yüce']::text[], 8.5, '{"poet":"Nilgün Yüce","poet_slug":"nilgun-yuce","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/soya-soya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'a-Dost dediğin böyledir!', 'a-dost-dedigin-boyledir-mikdat-bal-8862g', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dost öyle bir insan ki, canından can katar dost,

Bunlardan çok yok amma, dost dediğin böyledir! 

Kutsal bilir dostluğu, bencilliği atar dost,

Arkadaşlar çok amma, dost dediğin böyledir! 

Demez asla yapamam, her işini bitirir

Feda eder kendini, seni rahat ettirir

Açlık çeker duyurmaz, yemez seni yedirir

Arkadaşlar çok amma, dost dediğin böyledir! 

İhtiyacın olunca, çağırdın mı yanında

Hem varlık hem yoklukta, seninle her anında

Özür beyan eylemez, derdi varsa onun da

Arkadaşlar çok amma, dost dediğin böyledir! 

Mikdadi der dost budur, hiç karşılık beklemez

Yapılacak ne varsa, ifa eder teklemez

Korur seni her zaman, ağır bir yük yüklemez

Arkadaşlar çok amma, dost dediğin böyledir! 

Ozan Mikdadi', 'Dost öyle bir insan ki, canından can katar dost, Bunlardan çok yok amma, dost dediğin böyledir!  Kutsal bilir dostluğu, bencilliği atar dost...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/a-dost-dedigin-boyledir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidenlere Bakış', 'gidenlere-bakis-omer-yildiz-uwzgv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dağ yarıklarına

Düşmüş 

Gazeller

Dolaşır ayaklarıma 

Ve 

Ölüm 

Yola döşenmiş bir mayındır.

Adresi

Yazılı kurşun 

Çalmadı 

Bu gece de bedenimi 

Sabah güneşini 

Özlesin diye gözlerim.', 'Dağ yarıklarına Düşmüş  Gazeller Dolaşır ayaklarıma  Ve  Ölüm  Yola döşenmiş bir mayındır. Adresi Yazılı kurşun  Çalmadı  Bu gece de bedenim...', ARRAY['Türk Edebiyatı','Şiir','Ömer Yıldız']::text[], 8.5, '{"poet":"Ömer Yıldız","poet_slug":"omer-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gidenlere-bakis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Asik Olmak Senin Neyine', 'asik-olmak-senin-neyine-ayperi-ottekin-basoglu-d7wxl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Zevkli bir aci sevmek, umitlerle baslayan

Bazen beraberliklerde kaybolan.

Acisini hissettigimiz, tadilan zevkler,

Oksanmak istenen duygular

Cok hassas kirilacak gibiler.

Aynaya baksan orada

Mahcubiyetini anlatir sana,

Donup sirtini gitsen seni golge gibi izleyen

Gozlerinin onunden sevgidir, silinmeyen.

Giydigin su elbise bile guler sana

Baksana yasina basina asik olmak senin neyine? 

Eline aldigin su kitap cok eskilerden kalma

Hatirlatir yasini sana.

Yerdeki Yagci Bedir halisi

Yurudukce ustunde guzellesir, bellidir ki

Yillarin eskitemedigi senin gibi

Duvarlar guler haline

Yalnizlik basina mi vurmus, ne? 

Halbuki daha neler var yapacak

Cicekler koklanacak, sevgiler yasanmamis

Henuz seni bekleyen, yasanacak', 'Zevkli bir aci sevmek, umitlerle baslayan Bazen beraberliklerde kaybolan. Acisini hissettigimiz, tadilan zevkler, Oksanmak istenen duygular ...', ARRAY['Türk Edebiyatı','Şiir','Ayperi Ottekin Başoğlu']::text[], 8.5, '{"poet":"Ayperi Ottekin Başoğlu","poet_slug":"ayperi-ottekin-basoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/asik-olmak-senin-neyine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Su içmek istiyorum', 'su-icmek-istiyorum-elazigli-mustafa-kaya-hf8o1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'tatlı bir su içmek

istiyorum.

uykudan uyandırılmış

gibiyim.

faydasız kederlerden,

şımarık ve ağır 

saatlerden,

anlaşılmaz bir suskunluk

içindeyim..

üzücü bir tebessüm

aldım.

gülünç ve acıklı bir

haldeyim.

mavi ve sessiz göklerin

yağmuruna tutuldum…

güneşsiz ruhuma şimdi,

hangi sabahlar gelecek.

ve bir başıma kalmışlığıma

hangi tebessümler inecek.

veya benimkisi,

rüzgara verilmiş bir sevgi

olsa gerek …

Mustafa kaya / istanbul

11.10.2005

www.mustafakaya.net', 'tatlı bir su içmek istiyorum. uykudan uyandırılmış gibiyim. faydasız kederlerden, şımarık ve ağır  saatlerden, anlaşılmaz bir suskunluk için...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/su-icmek-istiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nasihat', 'nasihat-ayperi-ottekin-basoglu-c1n4c', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Unutulacak asksa umut ugramaz kapina

Kalbin hapistir canina

Caresizdir, talihsiz mutluluksa.

Askin sihiri kadersiz kapini caliyorsa

Yetim kalacak duygulari kilitle sikica ruhuna.

Unutulacak asksa huzur uzaktir sana

Belki aylarca belki yillarca.

Bedeli agir duygulari yaklastirma yanina

Unutma sira aska gelince

Unutmak mahzun bir kelime.', 'Unutulacak asksa umut ugramaz kapina Kalbin hapistir canina Caresizdir, talihsiz mutluluksa. Askin sihiri kadersiz kapini caliyorsa Yetim ka...', ARRAY['Türk Edebiyatı','Şiir','Ayperi Ottekin Başoğlu']::text[], 8.5, '{"poet":"Ayperi Ottekin Başoğlu","poet_slug":"ayperi-ottekin-basoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/nasihat-68-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dönüş', 'donus-elazigli-mustafa-kaya-f15nh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '‘’..bizim sizi boş yere bir oyun ve eğlence olarak yarattığımızı ve sizin 

    bize  döndürülüp getirilmeyeceğinizi mi sandınız…’’       nur – 115

kelimelerden başka dostum 

yok.

sessizlik dışında bir söz

söylemeyeceğim.

özgürlüğüm ve

kaderim için.

kalbimde olan derdi

kabullendim .

semavi bir lokma

bildim.

tatlıdır Rabb imin nimeti

ben onu yerim..

bir sela bırakmaz

yakamı

dualara karışır 

gözyaşlarım

O’nun içiniz

O’na döndürüleceğiz…

Mustafa kaya

11.10.2005 / Eminönü

www.mustafakaya.net', '‘’..bizim sizi boş yere bir oyun ve eğlence olarak yarattığımızı ve sizin      bize  döndürülüp getirilmeyeceğinizi mi sandınız…’’       nur...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/donus-45-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gizem', 'gizem-elazigli-mustafa-kaya-p2krf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'gönlümden gülemem 

senin mutluluğun olmadıkça…

gökler,

gecelerde  gizemli.

sessiz ve engin..

sense  ben de.

ruhuma seyhatinden mutluyum

taşıdığım sevgi senin..

Mustafa kaya

11.10.2005 / Üsküdar

www.mustafakaya.net', 'gönlümden gülemem  senin mutluluğun olmadıkça… gökler, gecelerde  gizemli. sessiz ve engin.. sense  ben de. ruhuma seyhatinden mutluyum taşı...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/gizem-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Görkemliydi Gözleri', 'gorkemliydi-gozleri-mehmet-i-mal-p5ynj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Görkemliydi gözleri...

     Yanı başında depreşen koca pavyon neonlarına komşuydu hikayen. Karnın açtı çoğu zaman AMA bir dilim ekmeğe değil küçük bir selama tutunuyordu tüm direncin. Amaçsız kedilerin ayyaş miyavlamaları uyandırdı bir ömür seni. Hiç uyumadın aslında,bir yudum içki içmeden zoraki sızmalarla başlıyordu gecelerin. Bir sevdan bile yoktu,olması da muhtemel değildi aslında. Hayal kurmana bile izin vermemişti hayat. Apartman bodrumundaki rutubet bekçisinden öte bir şey değildin kimileri için 

     Filtresine kadar içerdin hep sigaranı,sararmış parmaklarının mahcupluğu yüzüne vururdu....  Tokalaşamazdın kimseyle....  Umutsuz bekleyişler alırdı öğleden sonralarını, açlık değildi korktuğun AMA ölümden de çekinmiyor değildin hani. Açlıktan ölmek gururunu kırardı epeyce. Derken merhametli bir el yarım kap yemek getirirdi. Utanırdın...... Kafanı sallardın usulca ve koca bir minnetle.

     Doğduğuna isyan etmedin belki AMA hiçbir haz da almıyordun yaşamaktan ve kararsız bir soluk daha alıyordun her geçen saniyede. Menfaat nedir bilmeyen,para nedir görmeyen,zor ve acımasız, asil AMA gösterişsiz bir parıltı gibiydi adımların. Pantolonundaki yamalara inat başın dik yürüyordun hep. İntihar tek çareymişçesine dikiliyordu karşına her doğan günle beraber AMA sen yaşıyordun. İsrarla ve usanmadan,  hayata duyduğun o anlamsız aşk için, sırf bir sonraki günün aydınlığı için, koca bir abide gibiydin,ne titrek ellerin,ne de solgun yüzün  o kahraman direnişine mani değildi. O gün gelipte oturduğun sandalyeyle beraber yere düştüğünde, bir defa daha göremeyeceğimin bilinciyle baktığım bakir gözlerin  Adeta şöyle haykırıyordu: AŞK KOMİK DEĞİLDİR! ! ! En büyük aşkın seni terk ediyordu

Ve ölüyordun Cemil Amca...

                                                                            Mehmet İMAL', 'Görkemliydi gözleri...      Yanı başında depreşen koca pavyon neonlarına komşuydu hikayen. Karnın açtı çoğu zaman AMA bir dilim ekmeğe değil...', ARRAY['Türk Edebiyatı','Şiir','Mehmet İmal']::text[], 8.5, '{"poet":"Mehmet İmal","poet_slug":"mehmet-i-mal","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/gorkemliydi-gozleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sanal aşk', 'sanal-ask-seref-ozturk-usta-ppe77', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sanal aşklar yaşanır 

Aslı yaşanmıyorsa

Söylenecek pek çok söz

En sona geliyorsa

İnan o aşk tükenmiş

İçinde sevda yoksa

Vâr olsa da aşk orda

Meşk''e dönüşmüyorsa

Bitirelim vaktinde

Arkası gelmiyorsa.

(G.G Marguez''e)', 'Sanal aşklar yaşanır  Aslı yaşanmıyorsa Söylenecek pek çok söz En sona geliyorsa İnan o aşk tükenmiş İçinde sevda yoksa Vâr olsa da aşk orda...', ARRAY['Türk Edebiyatı','Şiir','Şeref Öztürk Usta']::text[], 8.5, '{"poet":"Şeref Öztürk Usta","poet_slug":"seref-ozturk-usta","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sanal-ask-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eyvallah usta', 'eyvallah-usta-seref-ozturk-usta-dvkhi', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seni de çok zorladı ertelemek

Bir dosta eyvallah ustam demek

Gönül adamını kırmak olmazdı

Dostluklar bir çırpıda atılamazdı

Bazen aşktan büyük olur dostluklar

Dolmuyor masallarla boşluklar

Zor olsa da

Ankara''nın İstanbul''dan ayrılması

Nadir değil

Dostluklardan aşkların sıyrılması

Saygı büyükmüş sevgiden anladım

Anladım dostluk yüce imiş

Aşk cüceymiş dostluktan

Sevince anladım Dostlukta aşkmış.', 'Seni de çok zorladı ertelemek Bir dosta eyvallah ustam demek Gönül adamını kırmak olmazdı Dostluklar bir çırpıda atılamazdı Bazen aşktan büy...', ARRAY['Türk Edebiyatı','Şiir','Şeref Öztürk Usta']::text[], 8.5, '{"poet":"Şeref Öztürk Usta","poet_slug":"seref-ozturk-usta","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/eyvallah-usta-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olmasa', 'olmasa-seref-ozturk-usta-5xzjz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Silah ustaları işsiz kalsa da 

Barış ustaları gönül çalsa da

Hepimize yetecek güneş

Herkese yetecek aş

Olmasa silah ustaları 

Olmasa dünyada savaş.', 'Silah ustaları işsiz kalsa da  Barış ustaları gönül çalsa da Hepimize yetecek güneş Herkese yetecek aş Olmasa silah ustaları  Olmasa dünyada...', ARRAY['Türk Edebiyatı','Şiir','Şeref Öztürk Usta']::text[], 8.5, '{"poet":"Şeref Öztürk Usta","poet_slug":"seref-ozturk-usta","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/olmasa-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geçi Dünya kimseye de kalmaz her zaman', 'geci-dunya-kimseye-de-kalmaz-her-zaman-halil-colak-uh5wv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Karlı dağlar canan neden öyle yaslıdır

Gönül selam vermez yara küslüdür

Onun için canan derinden de dertlidir

Seven acı çeker yüzü gülmez bir zaman

Güz geldi mi de güllerin sararırda yaprağı

Ecel geldi mi? çağırırda sevdiğimin toprağı

Kader örer insanın başına gelecekte ağları 

Geçi Dünya kimseye de kalmaz her zaman

Halil Çolak 11.10.2005 Ankara', 'Karlı dağlar canan neden öyle yaslıdır Gönül selam vermez yara küslüdür Onun için canan derinden de dertlidir Seven acı çeker yüzü gülmez bi...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/geci-dunya-kimseye-de-kalmaz-her-zaman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilmek', 'bilmek-kemal-cakir-0awvq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kimi bilmez meyvesiz ağaç olduğunu,

Taşlanmak için çatar durur sağa sola; 

Kimi sık satır meyve doludur

Cehaletle dolaşır durur kol kola.', 'Kimi bilmez meyvesiz ağaç olduğunu, Taşlanmak için çatar durur sağa sola;  Kimi sık satır meyve doludur Cehaletle dolaşır durur kol kola....', ARRAY['Türk Edebiyatı','Şiir','Kemal Çakır']::text[], 8.5, '{"poet":"Kemal Çakır","poet_slug":"kemal-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/bilmek-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güle güle.. Şahin Yılmaz''ın ayrılık türküsüne nazire', 'gule-gule-sahin-yilmaz-in-ayrilik-turkusune-nazire-mikdat-bal-2mygr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Niyetlendin uzun yola

Durmadan git, güle güle

Boyun eğme hiç bir kula

Sormadan git güle güle

Gördük nice gidenini

Demediler nedenini

Rahatça git bedenini

Yormadan git güle güle

Elbet yolcu olur her fert

Yollar uzun, tabanlar sert

Başımıza başka bir dert

Sarmadan git güle güle

Beğenmezsen vefamızı

Çekme bizim çefamızı

Gönlümüzü kafamızı

Kırmadan git güle güle

Bakma bizim sözümüze

Taşı atma özümüze

Suçumuzu yüzümüze

Vurmadan git güle güle

Tut Bal’ın nasıhatini

Sakın bozma sıhhatını

Horoz yeter saatini

Kurmadan git güle güle', 'Niyetlendin uzun yola Durmadan git, güle güle Boyun eğme hiç bir kula Sormadan git güle güle Gördük nice gidenini Demediler nedenini Rahatça...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gule-gule-sahin-yilmaz-in-ayrilik-turkusune-nazire-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pencere Kırığı Akşamlar', 'pencere-kirigi-aksamlar-vedat-koparan-aecfv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'yüreğim akıp giderken gece yolcuğundan gün uyanışlarına

bir yanda yalancı palyaço kırmızılığı bir yanda ateş dağlı kızıl yanığı 

bir yanda bembeyaz zamanlar bir yanda griden, karalar 

karalar ki karalar bağlar bu sessiz akan zamanda

gece mavisinde düş gezgini bir yolcu

yoksun koyaklara vuran dalgalar boyunda

ne ses vardı ne nefesler duyuluyordu

sesine ses nefesine nefes arardı 

dışardan istenildiği kadar vurulsa da 

yüreğim o resimdeki gibi tokmaksız bir kapıydı 

içerden açılan bir kardelen düşüydü hasret ışığa 

ta ki sen çıkıp gelene kadar ateş alımı yüzüm

dışarıya pencere kırığı akşamlara bakardım 

bir öfke türküsündeydi bu yalnızlığım

özlem doluydu  uykusuz gözlerim

bir tek  sana yanar  sana sevdam derdim 

gece dolanır ay saçlarında

gezinirdim yıldız düşlerinde 

tutunurdum güneş kirpiklerine 

akardım buz kırığı akşamlarda

hep sana..

-Sevgi

Benim Beni Bildiğim Kadar,Sende Beni Bende Bil O Kadar -

Vedat Koparan 11.10.2005', 'yüreğim akıp giderken gece yolcuğundan gün uyanışlarına bir yanda yalancı palyaço kırmızılığı bir yanda ateş dağlı kızıl yanığı  bir yanda b...', ARRAY['Türk Edebiyatı','Şiir','Vedat Koparan']::text[], 8.5, '{"poet":"Vedat Koparan","poet_slug":"vedat-koparan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/pencere-kirigi-aksamlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O En Güzel Mavi Gülüşüne', 'o-en-guzel-mavi-gulusune-vedat-koparan-omyhh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gül kokulu teninde nazenin akşamlardan

Nil’de uyanmak suda ay yansımasında

Ay suda zamanın dansında canda canan

Sevgiler filiz filiz büyürken gün karaltılarında 

Çoğalırsın uç veren bir defne dalıyla her an 

Efil rüzgara tutunan gece mavisi al yalımda

Kırıklar aydınlanır gün parıltılarıyla 

Anlam bulur seninle yangın zaman

Duruşlarımız aykırı  yolculukta 

Gamzende yağmur sağanağı 

Sevgiler bir pınar akar içime

O en güzel mavi gülüşünü 

Bırakmıştın şimdi hani nerede

Aktım gökkuşağı renkleriyle 

Hayaller ötesine düşlerimle

Gel artık ne olursun bekletme

Tamlansın bu yürek seninle

Ne çok severim deniz seni 

Kaybolur mavinde

Ne çok çekersin beni

Kıyılar boyu giderim ak köpüklerinde

Vedat Koparan 09.10.2005', 'Gül kokulu teninde nazenin akşamlardan Nil’de uyanmak suda ay yansımasında Ay suda zamanın dansında canda canan Sevgiler filiz filiz büyürke...', ARRAY['Türk Edebiyatı','Şiir','Vedat Koparan']::text[], 8.5, '{"poet":"Vedat Koparan","poet_slug":"vedat-koparan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/o-en-guzel-mavi-gulusune-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düet-4-Anlat', 'duet-4-anlat-vedat-koparan-anj8j', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'hele de bana

yok sen sus güvercinler desin

ülkemin

dağlarını

sonsuz gökyüzünde 

kanatlarını çırparken nasıl özgürce uçtuğunu 

göklerin nasıl seviştiğini mavinin telaşında

anlat mesela

insanları 

urbası perperişan yolcunun

benliğinde ki kırıklarda 

gözleri geleceği müjdeleyen

ey ateş

dağlı yüreklerin türkü dilinde 

hala sevmeyi bilen yurdum insanını..

maviş gülüşlü çocukları

mor çiçekli dağlarını anlat

güneşin doğuşuyla aydınlanan 

parıldayan o sapsarı ışıkla

çağlayan Fırat’ı 

dolu dizgin bir rüzgar üzerinde eserken 

hasretin türküsünü söyleyen Dicle’yi 

hep orada kalmışlığımı

anlat bana

bilirsin ne haldedir 

serpmeye gelen balıkların çırpınışını

bilirsin değil mi 

gün batımlarında 

hüzün dağlarına çöken sisi

yalın yapıldak yamaçlarında

ayaklarına dolanan dikenlerin batıp 

kan sızan çıplak ayaklarında

çamur  deryası bir kışa bulanan

ekmeği elinde  ısırırken 

çekilmiş fotoğrafında

savrulurken bebelerin 

geleceğe dair düşleri 

sana ne anlatayım 

bu acılar deryasında

vururken beni 

sen güzelliklere çağlarken 

özlem yüklü bir rüzgar gülüydün 

gurbet kuşlarının kanat çırpışlarında

ben öte yüzün de 

hep ülkem diye sana akan

biliriz ki aslında hep biriz 

uzaklardan yakınlara tamlanan

Bengül Yağıbasan-Vedat Koparan 09.10.2005

sevgili can dostumuz Yaşar Doğan katkıların için çok teşekkürler sevgiler can', 'hele de bana yok sen sus güvercinler desin ülkemin dağlarını sonsuz gökyüzünde  kanatlarını çırparken nasıl özgürce uçtuğunu  göklerin nasıl...', ARRAY['Türk Edebiyatı','Şiir','Vedat Koparan']::text[], 8.5, '{"poet":"Vedat Koparan","poet_slug":"vedat-koparan","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/duet-4-anlat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Yalnızım', 'ben-yalnizim-fatih-kuyucu-8mcny', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gül kurudu 

Gönül kovuldu 

Doğru savruldu

Ben yalnızım

Gülüş saklandı

Günah yaşandı

Duam hep vardı

Ben yalnızım

Gitmek tek çare

Kapanmak secdelere

Yar olmak gecelere 

Ben yalnızım', 'Gül kurudu  Gönül kovuldu  Doğru savruldu Ben yalnızım Gülüş saklandı Günah yaşandı Duam hep vardı Ben yalnızım Gitmek tek çare Kapanmak sec...', ARRAY['Türk Edebiyatı','Şiir','Fatih Kuyucu']::text[], 8.5, '{"poet":"Fatih Kuyucu","poet_slug":"fatih-kuyucu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ben-yalnizim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tabibim benim', 'tabibim-benim-halil-colak-zx0a4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gönül bahçesine sevgi ile gire biliyor musun

Dikende olsa da avuçlayıp tutabiliyor musun

Seni sevmese de karşılıksız seve biliyor musun

İstemeden karşılıksız gönül vere biliyor musun

O zaman dertlerinde dermanısın tabibim  benim



Halil Çolak 11.10.2005 Ankara', 'Gönül bahçesine sevgi ile gire biliyor musun Dikende olsa da avuçlayıp tutabiliyor musun Seni sevmese de karşılıksız seve biliyor musun İste...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/tabibim-benim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karanlık Battaniyesi', 'karanlik-battaniyesi-gulsen-gonenc-4z9zf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kendini güvende hissediyormuş,

karanlık battaniyesini örtünce üzerine.

Isınmak için güneş gerekmez mi, diyorum.

 ''Isınmak isteyen de kim? ! 

 Güneş yağmış içime; ancak böyle soğuyabilirim.''

diyor.

Bunun sadece bir avuntu olduğunu o da biliyor.', 'Kendini güvende hissediyormuş, karanlık battaniyesini örtünce üzerine. Isınmak için güneş gerekmez mi, diyorum.  ''Isınmak isteyen de kim? ! ...', ARRAY['Türk Edebiyatı','Şiir','Gülsen Gönenç']::text[], 8.5, '{"poet":"Gülsen Gönenç","poet_slug":"gulsen-gonenc","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/karanlik-battaniyesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elveda çocukluğum', 'elveda-cocuklugum-neslihan-i-sler-19f3c', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Herşey başladığı yerde son bulur

Nerde duracagını bilmek gerek

Her kaybın telafisi olur

Yarasını sarmak gerek...

Kim başlatmış bilinmez sonunu

Ya dalarla geçen zamanı

Ağlayamayan taş misali..

Bu bir cocuğun serzenişi aslında

Umutları tükenmiş...

Küçüçük yürekten cıt çıkmaz

Şaşkın bakışlarla bakıyor

Zamansız büyümeye zorlanmış,,,

Güvenmiş yitirilmiş...

Denize doğru koşarken 

Duvarlara çarpmış 

Yaralı kuş misali 

Tek kanat kırık 

Yalvaran gözlerle bakıyor

O da büyüyecek hepimiz gibi

Sadece zamanını bekliyor

Belki yaralarını saranda olacak

Ölümün nefesini tatmadan

O masum yüreği...

Sadece elveda demesini öğrenmeli

Bakarken gidenin ardından

Dönebilmeli oda kendi yönüne

Bilmeliki hayat serzenişlerine 

Cevap veremeyecek kadar acımasız

Evrenin domina taşlarından biri olmadan

Hoşçakal 

Hoş kal

Elveda cocukluğum....', 'Herşey başladığı yerde son bulur Nerde duracagını bilmek gerek Her kaybın telafisi olur Yarasını sarmak gerek... Kim başlatmış bilinmez sonu...', ARRAY['Türk Edebiyatı','Şiir','Neslihan İşler']::text[], 8.5, '{"poet":"Neslihan İşler","poet_slug":"neslihan-i-sler","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/elveda-cocuklugum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir damla gözyaşına değmeyen hayatın içinden', 'bir-damla-gozyasina-degmeyen-hayatin-icinden-murat-tali-w6oin', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Büyümeyen düşlerimiz

Yarınlarımız vardı 

Biz

Çocukluğumuzun çocuklarıyla büyüdük

“tüm hayatın toplamı 

bir damla gözyaşına değmiyor”

haklısın

sevinçlerimiz bile acımsıtrak tatlar bıraktı 

toplamın tüm birimlerinde

sağlaması olmayan 

bir yaşamın

bir damla gözyaşı etmeyeceğini bilse

onu toplamak için anneler ve babalar yaratır mıydı 

yaratan 

ahlaksızlığın ve onursuzluğun 

dış tabirlerle kol gezdiği

zaman dilimlerinde 

budalaca teslimiyetler arasında

düşüverdik 

kollarımıza

köpekleşerek süregelen yaşam

açlığın dayatmalarıyla 

ihanete teslim ediyor kendini

ihanet

terk edip gitmenin diğer adı

sebepsiz terk edişlerin sözlüğümüzdeki 

tanımı

yamalı yörüngelerle devredilen günler, geceler, yıllar

eğikliğin yitirdiği mevsimler

gözün görüp

fikrin idrak edemediği anlar

paylaşmanın sevişmeden geçtiği

her sevişmede aşkın

her aşkta sevişmenin olmadığı 

orta oyunlarla yönetilen bir yaşamın

oyuncaklaşan oyuncularıyız

değmiyor bir hayatın toplamı

bir damla gözyaşına

Ederim

Tenimin, tartıdaki ağırlığı

Ruhumu çoktan salıvermiştim

Senin gözünde bir damla yaşa değmeye değil

Kendi yaşamımda bir damla yaş olamamak 

çok koyuyor bana', 'Büyümeyen düşlerimiz Yarınlarımız vardı  Biz Çocukluğumuzun çocuklarıyla büyüdük “tüm hayatın toplamı  bir damla gözyaşına değmiyor” haklısı...', ARRAY['Türk Edebiyatı','Şiir','Murat Tali']::text[], 8.5, '{"poet":"Murat Tali","poet_slug":"murat-tali","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/bir-damla-gozyasina-degmeyen-hayatin-icinden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O gün', 'o-gun-gulsum-bulayir-4079y', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'O gün

yağmur seni ıslatmıştı

Aşkın sa beni

Yüreğimdeki fırtınaya inat

Dilim susmuştu

Dağınık oda da 

Darmadağan duygularımın esiri olmuştum.

Elimi uzatsam dokunacaktım sana 

Ama bir türlü uzatamadım.

Korkular sardı acemi yüreğimi

Adresin yoktu,

Söyle deseler adını veremezdim

Konuşabilsem çok şey söyleyecektim sana

Sırça oda, yasak sokaklarda

Hani iki yabancı gibi yürümüştük ya o ıslak caddelerde

Dokunmamak için sana

Kilit vurmuştum bedenime

Görünmeyen yanım aşıktı sana

ve o görünmeyen yanım acıyor şimdi.', 'O gün yağmur seni ıslatmıştı Aşkın sa beni Yüreğimdeki fırtınaya inat Dilim susmuştu Dağınık oda da  Darmadağan duygularımın esiri olmuştum....', ARRAY['Türk Edebiyatı','Şiir','Gülsüm Bulayır']::text[], 8.5, '{"poet":"Gülsüm Bulayır","poet_slug":"gulsum-bulayir","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/o-gun-44-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarın,', 'yarin-gulsum-bulayir-f84pc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Biliyorum yarın olacak 

ve sen bana beklediğim haberi vereceksin.

Ben de zil zurna sarhoş olacağım mutluluktan

Teninin kokusu burnuma gelecek 

Sıcacık ellerin ellerime kilitlenecek

Kaç gece yada kaç gün sonra bilinmez

Haram geceleri helale çevirdiğim an

Yüreğim acımayacak

Sen benim yolumdaki  bir yolcusun

Senden öte bir yol yok.', 'Biliyorum yarın olacak  ve sen bana beklediğim haberi vereceksin. Ben de zil zurna sarhoş olacağım mutluluktan Teninin kokusu burnuma gelece...', ARRAY['Türk Edebiyatı','Şiir','Gülsüm Bulayır']::text[], 8.5, '{"poet":"Gülsüm Bulayır","poet_slug":"gulsum-bulayir","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yarin-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hal Beyanı! !', 'hal-beyani-saim-bastik-ud1a9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yetmezmi sevdiğim ettiğin cefa

Yitirdim aklımı, DEL oldum şimdi.

Sevgimi söylerdim,binlerce defa

Tutuldu dillerim, LAL oldum şimdi

Hiçbirşey kalmadı benim gözümde

Dövdüm; hal kalmadı inan dizimde

Aşkınla çaldığım dertli sazımda

Vurup,ses vermeyen TEL oldum şimdi.

Gönlüm anlamıyor benim sözümden

Yaş eksik olmuyor artık gözümden

Dert bilmezdim amma,senin yüzünden

Ben,bütün dertlere YOL oldum şimdi.

Mutsuzluğun,adı yoktu lehçemde

Çiçekler açardı gönül bahçemde

Irmaklar akmıyor artık içimde

Kurudum,çatladım, ÇÖL oldum şimdi.

Sevgiliydim,ben hasreti çekilen

Bir türküydüm, ben dillerden dökülen

Atlas idim, türlü libas dikilen

Yollara serilen, ÇUL oldum şimdi.

Sen bir sevsen,ben bin defa severim

Her türlü derdine boyun eğerim

Altın ile ölçülürdü değerim

Artık, geçmez akçe PUL oldum şimdi.

HARÎMİ''ye arattırdın dününü

Gam ile doldurdun her bir gününü

Artık, başkasına dön sen yönünü

Sevdiğim; ben sana EL oldum şimdi.

Saim BASTIK (HARÎMİ)  10/10/2005-Kula', 'Yetmezmi sevdiğim ettiğin cefa Yitirdim aklımı, DEL oldum şimdi. Sevgimi söylerdim,binlerce defa Tutuldu dillerim, LAL oldum şimdi Hiçbirşey...', ARRAY['Türk Edebiyatı','Şiir','Saim Bastık']::text[], 8.5, '{"poet":"Saim Bastık","poet_slug":"saim-bastik","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/hal-beyani-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yolcu', 'yolcu-gulsum-bulayir-t7wyi', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Biliyorum yarın olacak 

ve sen bana beklediğim haberi vereceksin.

Ben de zil zurna sarhoş olacağım mutluluktan

Teninin kokusu burnuma gelecek 

Sıcacık ellerin ellerime kilitlenecek

Kaç gece yada kaç gün sonra bilinmez

Haram geceleri helale çevirdiğim an

Yüreğim acımayacak

Sen benim yolumdaki  bir yolcusun

Senden öte bir yol yok.', 'Biliyorum yarın olacak  ve sen bana beklediğim haberi vereceksin. Ben de zil zurna sarhoş olacağım mutluluktan Teninin kokusu burnuma gelece...', ARRAY['Türk Edebiyatı','Şiir','Gülsüm Bulayır']::text[], 8.5, '{"poet":"Gülsüm Bulayır","poet_slug":"gulsum-bulayir","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yolcu-89-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bakış', 'bakis-hanife-banu-o5ly9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kirpiklerini kaldırıp

Uzandıkları yüreğimden

Öyle bir baktı ki

Deniz üzerinden İstanbul’a

Sandım gözlerine boyandık..

Ansızın 

Kapadı gözlerini

Uyandık', 'Kirpiklerini kaldırıp Uzandıkları yüreğimden Öyle bir baktı ki Deniz üzerinden İstanbul’a Sandım gözlerine boyandık.. Ansızın  Kapadı gözler...', ARRAY['Türk Edebiyatı','Şiir','Hanife Banu']::text[], 8.5, '{"poet":"Hanife Banu","poet_slug":"hanife-banu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bakis-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşünce', 'dusunce-hanife-banu-b0hbk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne zaman seni düşünsem

İstanbul oluyorsun

Nefesin rüzgara karışıyor

Sonum oluyorsun

Bir martı havalanıyor avuçlarından

Şehir hatları vapuru sefer alıyor

Sesin uğulduyor yedi tepede

Katlime ferman buyuruyorsun', 'Ne zaman seni düşünsem İstanbul oluyorsun Nefesin rüzgara karışıyor Sonum oluyorsun Bir martı havalanıyor avuçlarından Şehir hatları vapuru ...', ARRAY['Türk Edebiyatı','Şiir','Hanife Banu']::text[], 8.5, '{"poet":"Hanife Banu","poet_slug":"hanife-banu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/dusunce-47-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zor', 'zor-hanife-banu-g5tl6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kolay olmayacaktı belliydi

Lüzumsuz derecede içten

Anlaşılamayacak kadar birdiler

Ta uzaklarında birbirlerinin

İçiçe bir ömrü tüketmiştiler

Ne yazıkki bitmemiştiler..', 'Kolay olmayacaktı belliydi Lüzumsuz derecede içten Anlaşılamayacak kadar birdiler Ta uzaklarında birbirlerinin İçiçe bir ömrü tüketmiştiler ...', ARRAY['Türk Edebiyatı','Şiir','Hanife Banu']::text[], 8.5, '{"poet":"Hanife Banu","poet_slug":"hanife-banu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/zor-62-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayal Oyunu', 'hayal-oyunu-hanife-banu-4gpoj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bıktım artık bu  hayal oyunundan 

Bak ağlıyorum işte

Ölüm kadar gerçek gözyaşlarım 

Ve içime akanlarda cabası

Sonu gelsin tüm yalanların

Tüm ümitler kendi evlerine gitsin

Çanak çömlek patladı

Herkes çıksın 

Kavgam bitti

Ben de....', 'Bıktım artık bu  hayal oyunundan  Bak ağlıyorum işte Ölüm kadar gerçek gözyaşlarım  Ve içime akanlarda cabası Sonu gelsin tüm yalanların Tüm...', ARRAY['Türk Edebiyatı','Şiir','Hanife Banu']::text[], 8.5, '{"poet":"Hanife Banu","poet_slug":"hanife-banu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/hayal-oyunu-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eylül', 'eylul-hanife-banu-i22b7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sonbaharı sevmiyorum sevgilim

Güz trenlerinin isli vagonlarını 

Seni alıp götüren o rüzgarları

S-e-v-e-m-i-y-o-r-u-m...

Bir eylül daha geldi bak

Tek tek bağlıyorum yaprakları ağaçlara

Her akşam “bir umut”la dinliyorum hava raporlarını

Takvim yapraklarını koparmıyorum

Ne yapsam da

Ne sen ne de Eylül kanmıyorsunuz

Yine gidiyorsun

Gönlüme karakışlar geliyor...

Üşüyorum......', 'Sonbaharı sevmiyorum sevgilim Güz trenlerinin isli vagonlarını  Seni alıp götüren o rüzgarları S-e-v-e-m-i-y-o-r-u-m... Bir eylül daha geldi...', ARRAY['Türk Edebiyatı','Şiir','Hanife Banu']::text[], 8.5, '{"poet":"Hanife Banu","poet_slug":"hanife-banu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/eylul-92-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadirli Özlemi', 'kadirli-ozlemi-i-brahim-ethem-kundakci-ywr6i', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Asırlar gibidir senden uzağım 

	Geçen günlerim hep yıl oldu bana

	Bilmiyorum nasıl dayanacağım

	Sevmediğim yerler gül oldu bana

	Hani gezerdik ya, sende gülerek

	Sohbetler ederdik hep yürüyerek

	Yemyeşil Kadirli hayalleyerek

	Her günüm bir azap geliyor bana

	Nerede Sülemiş, nerede çamlık

	Savrun’un çayına hep hasret kaldık

	Senin hasretinle yandıkca yandık

	O güzel Kadirli Tütüyor bana

	Alacami Özgürlüğün aldı mı? 

	Bülbül Deresine bilbül geldi mi? 

	Acaba Kadirli’m yeşillendi mi? 

	Şu yeşil Erzincan çöl oldu bana

	İbrahim Ethem’im geçmiyor günler

	Hayalde mi kaldı güzel anılar

	Bir söz söyledim ki anlayan anlar

	Kadirli Leyla’dır, özlemdir bana

İbrahim Ethem KUNDAKÇI

    Erzincan /1995

İbrahim Ethem KUNDAKÇI

						    Erzincan /1995', 'Asırlar gibidir senden uzağım  	Geçen günlerim hep yıl oldu bana 	Bilmiyorum nasıl dayanacağım 	Sevmediğim yerler gül oldu bana 	Hani gezerd...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Kundakçı']::text[], 8.5, '{"poet":"İbrahim Ethem Kundakçı","poet_slug":"i-brahim-ethem-kundakci","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/kadirli-ozlemi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sakın', 'sakin-huseyin-erdogan-tfoni', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'gözlerinde kaybettim kendimi

senin yüreğinde unuttum derdimi

damarlarına verdim bütün sevgimi

sakın beni benden alıp da şimdi

sonra darmadağın etme kalbimi

buna dayanamayacağımı biliyorsun değil mi? 

                                  11.10.2005', 'gözlerinde kaybettim kendimi senin yüreğinde unuttum derdimi damarlarına verdim bütün sevgimi sakın beni benden alıp da şimdi sonra darmadağ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sakin-32-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sırlar', 'sirlar-mehmet-coban-oz9ot', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir arkadaşlık gidiyor sessizce 

Arkasında bırakarak anıları

Suskunluk çıldırtır delice

İçinde saklar tüm sırları

İlişkiler kurulunca usulden

Bekleme artık candanlığı

Bir arkadaşlık gidiyor sessizce

Sessizliğin derinliğinde

Kendisiyle hesaplaşmadan

Bir arkadaşlık gidiyor sessizce

Saklı nice sırlar içinde 

Arkadaşıyla hesaplaşmadan', 'Bir arkadaşlık gidiyor sessizce  Arkasında bırakarak anıları Suskunluk çıldırtır delice İçinde saklar tüm sırları İlişkiler kurulunca usulde...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Çoban']::text[], 8.5, '{"poet":"Mehmet Çoban","poet_slug":"mehmet-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sirlar-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sakladım', 'sakladim-mehmet-coban-s5gib', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hayallerimi suya yazdım

Rüzgâra saldım ideallerimi

Kurak bozkırlar gibi hayatım

Engebelerle bozdum dengemi

İstediğimin çoğu olmadı hayatta

Güya kaderi kendi ellerimle yazdım

Sanki emeklerimi buldum sokakta

Değerlerini bir türlü anlayamadım

Güneşli günler bekledim gelecekte

Gelecekleri karanlıklarla kucakladım

Aydınlık yok mu yoksa felekte

Hep insanlık dışı karşılaştıklarım

İnsanı aradım yaratılışın özgürlüğünde

İnsan kanunlarıyla kölelere rastladım

İnsanlık hayallerimi sakladım benliğimde

Zulümden bir türlü ortaya çıkaramadım', 'Hayallerimi suya yazdım Rüzgâra saldım ideallerimi Kurak bozkırlar gibi hayatım Engebelerle bozdum dengemi İstediğimin çoğu olmadı hayatta G...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Çoban']::text[], 8.5, '{"poet":"Mehmet Çoban","poet_slug":"mehmet-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sakladim-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SANTEK - Yakaladım', 'santek-yakaladim-mehmet-coban-dnez4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir gün gözlerimi yakaladım

İçimdeki gerçekleri söylerken

Dilimi dolanırken yakaladım

Laf olsun diye söylediklerinden

Kaçan gözlerim vardı 

Karşısındaki gözlerden

Kalbim gerçeği soramadı

Bildiği çelişkilerden

Bir gün yakaladım gözlerimi dilimi

Her biri başka, başka söylüyor

Yokladım doğru için kalbimi

Bilmiyorum karışık işler diyor

Bir gün eğer yapabilirse içtenlikle

Dinlemesi güzeldir insanın kendisini

Çelişkilerinden kurtulabilmek için

Zaman içinde hatırlarsa geçmişini

Hayal kurar gelecekte güzel günler için

Bir gün eğer anlayabilirse içtenlikle

Asıl olan çelişkilerden kurtulabilmektir

Kalbini, gözünü, dilini eşit tutabilmek için

Korkmadan çekinmeden söyleyebilmektir

Kalbindekileri, gözler ve diliyle çelişmemek için', 'Bir gün gözlerimi yakaladım İçimdeki gerçekleri söylerken Dilimi dolanırken yakaladım Laf olsun diye söylediklerinden Kaçan gözlerim vardı  ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Çoban']::text[], 8.5, '{"poet":"Mehmet Çoban","poet_slug":"mehmet-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/santek-yakaladim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tecrübe', 'tecrube-mehmet-coban-qix18', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dediler ki tecrübe

Yediğin kazıklardır

Hep aklıma gelse de

Aldanmak saflığımdandır

Ders alsaydım hatalarımdan

Kurtulabilseydim saflığımdan

Olur muydu hayatımda kazıklar

Sadece saflık insanı kazıklar

Hâlbuki öğütlerim hep kendime

Şeytan gibi düşün, şeytan olma diye

Tatbikatta gerçekleşen bütün işlerim

Hep düşündüklerimin tersini işlerim

Adam olmam ben bu gidişle

Geçmişim belli geleceğim ah işte

Düşünürüm söylerim hep kendime

Dinletemem bir türlü benliğime', 'Dediler ki tecrübe Yediğin kazıklardır Hep aklıma gelse de Aldanmak saflığımdandır Ders alsaydım hatalarımdan Kurtulabilseydim saflığımdan O...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Çoban']::text[], 8.5, '{"poet":"Mehmet Çoban","poet_slug":"mehmet-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/tecrube-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ateş..', 'ates-mehmet-coban-9eqq9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dediler korkutma ateşle bizi

Ateşten yaratılmış şeytan

Kandırma boşuna bizi

Yakar mı ateş ateşi

Ateşi ateşle sınamak

İnsan aklına sığmazdı 

Doğru olsaydı ansan aklı

Sular boğamazdı 

Sudan yaratılanı

İki hidrojen bir oksijen

Biri yakan, diğeri yanan

Birleşir olur söndüren

Ah bu sırrı anlayabilsen

Bilemezsin gerçekte sen

Ne soğuk, ne sıcaktır

Göremezsin gerçekleri sen

Görmenin yolu inanmaktır

11.07.2005 - İzmir', 'Dediler korkutma ateşle bizi Ateşten yaratılmış şeytan Kandırma boşuna bizi Yakar mı ateş ateşi Ateşi ateşle sınamak İnsan aklına sığmazdı  ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Çoban']::text[], 8.5, '{"poet":"Mehmet Çoban","poet_slug":"mehmet-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ates-38-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SANTEK - Saydılar', 'santek-saydilar-mehmet-coban-5g59o', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Anlatamadım kendimi

Anlamadılar beni

Sarıldım doğruluğa

Uzaktım yalanlara

Doğrularımı yalan

Yanlışlarını doğru saydılar

Sevgimi koydum ortaya

Yıllar, yıllar boyunca

Sevgisizliğin kuraklığında

Umutlarım kaldı havada

Ne dediysem olmadı

Doğrularımı yalan saydılar

Korkularım vardı, geride bıraktığım

Hayatım vardı, hep fedakârlığım

Anlamak istemediler çıkarlarınca

Hep kurban ettiler beni çıkarlarına

Yürümek istiyorum kendi yolumda

Yürüyüşümü çıkarlarına engel saydılar

11.10.2005 - izmir', 'Anlatamadım kendimi Anlamadılar beni Sarıldım doğruluğa Uzaktım yalanlara Doğrularımı yalan Yanlışlarını doğru saydılar Sevgimi koydum ortay...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Çoban']::text[], 8.5, '{"poet":"Mehmet Çoban","poet_slug":"mehmet-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/santek-saydilar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'UB-050 Dünyalarım benim! ..', 'ub-050-dunyalarim-benim-mehmet-coban-wwlyw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Eğer benim gözlerimin

Görüş kapasitesi farklı olsaydı

Daha farklı bir dünyayı görürdüm

Eğer benim kulaklarım

Farklı ses tonlarını duysaydı

Daha farklı bir dünyayı duyardım

Benim dünyam 

Gözlerimin gördüğü

Kulaklarımın duyduğu

Dokunup kokladığım

Bir dünyadır

Bu duygularımın

Değerleri farklı olsaydı

Bana başka bir dünyayı sunardı

Öyleyse benim dünyam ne? 

Gördüğüm, duyduğum dünya mı? 

Görmediğim, duymadığım dünya mı? 

Yoksa içinde bulunduğum

Görsem de duysam da

Görmesem de, duymasam da

Yaşadığım dünya mı? 

Ey seyrettiğim dünya

Göremediğim dünyada ne var

Ey duyabildiğim dünya

Duyamadığım dünyada ne var

Merak etme,

Ucuz değilim ben

Görmediğim dünya inkâr etmem seni

Ben görmediğime de inanırım

Bilirsin inanan benliğimi

Kuramam hayallerimi gördüklerimle

İman ederim hep bütünüyle 

Gördüklerime ve görmediklerime

Kaçamam düşünmenin sorumluluğundan

Kaçarım aklını kullanmayan akılsızlığımdan

Silmek için inancın sorumluluklarını 

Silemem, görmediğim dünyaları

25.07.2005 - İzmir', 'Eğer benim gözlerimin Görüş kapasitesi farklı olsaydı Daha farklı bir dünyayı görürdüm Eğer benim kulaklarım Farklı ses tonlarını duysaydı D...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Çoban']::text[], 8.5, '{"poet":"Mehmet Çoban","poet_slug":"mehmet-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/ub-050-dunyalarim-benim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sanduka - Asrın Hissiyatı Kitabından', 'sanduka-asrin-hissiyati-kitabindan-omer-ekinci-micingirt-bxtie', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yolculuk kardeşim ölümsüz sanma

An gelir tokadı vurur yatırır

Sırt üstü yatmanın sonu muamma.

Hesapsız debdebe nere götürür

Kaygı ve gözyaşı hicran masamda

Çok şeyi unuttum hoş ağlasam da

Yolun bitiminde ne var kasemde

Havf reca bilemem neler getirir

İçim hep ızdırap kahkaha her yan

Şaşarım kendime kendime düşman

İfratta noksanlık tefritte şişman

Ve yeşil sanduka tepemde durur', 'Yolculuk kardeşim ölümsüz sanma An gelir tokadı vurur yatırır Sırt üstü yatmanın sonu muamma. Hesapsız debdebe nere götürür Kaygı ve gözyaşı...', ARRAY['Türk Edebiyatı','Şiir','Ömer Ekinci Micingirt']::text[], 8.5, '{"poet":"Ömer Ekinci Micingirt","poet_slug":"omer-ekinci-micingirt","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sanduka-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutluluk olmaz', 'mutluluk-olmaz-halil-colak-s6n1t', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gönül bahçeleri meyvesiz kalmaz

Bakımlı bahçelerdir viranda olmaz

Allah’a inan gönüllerde kin garaz olmaz

İnanmayan kalplerde mutluluk olmaz

Halil Çolak 11.10.2005 Ankara', 'Gönül bahçeleri meyvesiz kalmaz Bakımlı bahçelerdir viranda olmaz Allah’a inan gönüllerde kin garaz olmaz İnanmayan kalplerde mutluluk olmaz...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/mutluluk-olmaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlayamadım be dostum', 'anlayamadim-be-dostum-suleyman-zaman-ji5ql', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kime yazdın bu dizeleri, anlamdım inan

        Muhabbet ehline böyle mi dalınır be dostum

        Bulunmaz ki dünyada, samimi olan bir ihvan

        Dergahı sineye böyle mi dalınır be dostum? 

        Bütün herkesin bulunur kendince bir duruşu

        Dest verir her zaman ariflerin özgün görüşü

        İlke edindim yaşamda bir menzile erişi

        Sohbet ehline hiç böyle mi girilir be dostum? 

        Kimselere neden geldin, demez konuşan  dilim

        Uzanmaz harama, kötüye hiçbir zaman  elim

        Kırarsam bir canı, akar nehir misali selim

        Didar-ı ihvana böyle mi gelinir  be dostum? 

        Dün bilinmeyenler, bugün bilinen şeyler oldu

        Zahir yanıltır beyini, düşünen özü buldu

        Uzam içinde, zamanı gelen her yaprak soldu

        Doğan ölür, ölen doğar gerçek budur be  dostum

        Taşırım görüşlerimi, açıkça her zemine

        Yönelir  gönlüm, yapılan her sohbetin demine

        Girmesin münkirler, dostlar meclisinin  cemine

        Uyarıcı her cana, minnet duyarım be dostum

      

         Bilinmeyeni araştırıp, bulunur bilinen

        Her bilinenin içinden, çıkar bir bilinmeyen

        Bu anafor içinde, sonsuz olana yönelen

        Yok olanda, var olanda aynı şeydir be dostum

         Zamanım eytişimsel düşünür  her olguları

         Öze yönelik kurar, tüm düşünsel kurguları

         Yıkmak gerekiyor her şeyde ki  önyargıları

          Bilim gerçek olanı belirleyendir, be dostum

                            11.10.2005', 'Kime yazdın bu dizeleri, anlamdım inan         Muhabbet ehline böyle mi dalınır be dostum         Bulunmaz ki dünyada, samimi olan bir ihvan...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Zaman']::text[], 8.5, '{"poet":"Süleyman Zaman","poet_slug":"suleyman-zaman","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/anlayamadim-be-dostum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...Asal Çelişki! ...', 'asal-celiski-naime-erlacin-n9zja', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'akma üstüme ey şiir

kapatmak istiyorum defteri anla! 

yazının düzüne sevdalanmış

vefasız bir âşığım ben

yoruldum

yorulduk! 

siyaha çıkıyor engebeli ufuklar

koro halinde simsiyah oluyoruz

bir adam bıyıklarını boyuyor acı ile

ana rahmine dönüyor bir çocuk

kahroluyoruz 

üstüme gelme ey şiir! 

sana bırakıyorum 

kaos ve karmaşayı

aşkı 

bir uçurumda sahipsiz

etim kıyılıyor defterin kapağında

yoluma gidiyorum ben 

renksiz! 

(10 Ekim 2005)   

......dedim ve sonra yine yazdım!', 'akma üstüme ey şiir kapatmak istiyorum defteri anla!  yazının düzüne sevdalanmış vefasız bir âşığım ben yoruldum yorulduk!  siyaha çıkıyor e...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/asal-celiski-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalbin Ben imdir…', 'kalbin-ben-imdir-efsun-aydin-7tztf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir sarkının notasında ağlarken bize,

Tad almak gerek yaşadığın herandan.

Kalbinde yer vardır belki bana hala da,

Hayranlık uyandırmışımdır da üstelik hani sen de yaa…

Vazgeçmek istediğin noktada durup durup düşünürsen beni…

Ve bensizlik üşütürse içini…

Sen kendi baharını yaşama sevgilim…

Doğru der kalbin sana her zaman…

Çünkü kalbin Benimdir Canım Sevgilim', 'Bir sarkının notasında ağlarken bize, Tad almak gerek yaşadığın herandan. Kalbinde yer vardır belki bana hala da, Hayranlık uyandırmışımdır ...', ARRAY['Türk Edebiyatı','Şiir','Efsun Aydın']::text[], 8.5, '{"poet":"Efsun Aydın","poet_slug":"efsun-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/kalbin-ben-imdir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '…Aşk Yazılası...', 'ask-yazilasi-naime-erlacin-pey48', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'yedi koca ay! 

yummalıyız gözlerimizi artık

karşılarız sonra mayıs çiçeklerini

korunmak için kasım ölümlerinden

buzdan konaklar inşa ederiz 

şubat kuşları içtimaa çıktığında

sesimizin kısıklığıyla dokunuruz onlara

martı es geçeceğiz kesin

mart 

batık kıta! 

bak ki kırpılmış bir mevsimden

belki hızla eskitilmiş takvimden

puhu kuşunu doğururuz yeniden

kalbimizde kenger otları

saçımızda kır bir soğuk

dondurulmuş düşler ülkesinde 

ilk yazı bekleriz

o gün geldiğinde 

kış ağaçlarına doğru 

aşkı yazacağım 

söz! 

buzu delen saray gözlerimizi…

(11 Ekim 2005)', 'yedi koca ay!  yummalıyız gözlerimizi artık karşılarız sonra mayıs çiçeklerini korunmak için kasım ölümlerinden buzdan konaklar inşa ederiz ...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/ask-yazilasi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yorgun Yıllar', 'yorgun-yillar-mehmet-sait-akkus-hphdt', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yüzümüzdeki çizgiler

Gerçek hayat çizgisidir

Bu bire bir yazılanlar

Ömrümüzün aynasıdır

Yaşadığımız günleri

Birer birer anacağız

Gezdiğimiz yerleri

Beraber yad edeceğiz

Yorgunluğudur yılların

Hep duran içimizde

İçtiğimiz o suların

Tadı kaldı dilimizde', 'Yüzümüzdeki çizgiler Gerçek hayat çizgisidir Bu bire bir yazılanlar Ömrümüzün aynasıdır Yaşadığımız günleri Birer birer anacağız Gezdiğimiz ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Sait Akkuş']::text[], 8.5, '{"poet":"Mehmet Sait Akkuş","poet_slug":"mehmet-sait-akkus","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yorgun-yillar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Taş ve Demir Gurbeti', 'tas-ve-demir-gurbeti-ahmet-tevfik-ozan-6aqe7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen, gurbet uykularını bilmezsin

Bölünmüş parça parça geceler boyunca...

Ve bilmezsin, sızısını gurbetin

Sessiz sessiz bir kenara uzanmayınca! ...

Önce ceylan gözlü kızlar gelir

Sonra ihtiyar kadınlar...

Sen ağlamazsın, ağlayamazsın ama

Taş duvar ağlar! ...

‘‘Ak bir yemin üstüne bir damla kandır, Mamak! 

Ve veliler sofrası.. tuzu nur, ekmeği nur! 

Yak, bir günah uğruna binlerce sevabı yak! 

İsm-i Rahim, gün olur: ‘‘Kahhar’’ la bir okunur! 

Katlanır her günü, biçilir; bir ateş kaftan olur! 

Yağar nurani hayaller, gözü yaşlı semadan...

Katleder sükutu çığlık, ekmeği taştan olur.

Kimse bilmez nice ah yükselir, Ankara’dan...

İçten içe yanıyor eşya da, kimse bilmez! 

Lav saçıyor ciğerim, sema bir kızıl yorgan..

Tenim ateş kanıyor; yol,; buz olsa gidilmez! 

Can kelebek ve fakat her çiçek burada kan! ...

Sen gurbet uykularını bilmezsin

Bölünmüş parça parça geceler boyunca...

Ve bilmezsin, sızısını gurbetin

Sessiz sessiz bir kenara uzanmayınca! ...', 'Sen, gurbet uykularını bilmezsin Bölünmüş parça parça geceler boyunca... Ve bilmezsin, sızısını gurbetin Sessiz sessiz bir kenara uzanmayınc...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Tevfik Ozan']::text[], 8.5, '{"poet":"Ahmet Tevfik Ozan","poet_slug":"ahmet-tevfik-ozan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/tas-ve-demir-gurbeti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mapusane Avlusundan Erciyes', 'mapusane-avlusundan-erciyes-ahmet-tevfik-ozan-5k8oe', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Elimde kelepçe, gözlerim donmuş

Döndüm, bulutların arasında Sen! ...

Erciyes, Erciyes; ... ruhuma konmuş

Bir beyaz güvercin, bir buzlu desen...

Ne oldu, diyorum; o soğuk demir

Taş duvar, ateşten çalınmış yorgan..

Kurşundan yontulmuş, beynimde, emir

‘‘Yüreği cehennem taşlara dayan! ...’’

Çaresiz, çağırdım; kar kuşlarını

Ayet-el Kürsi’yle cehennemlere...

Kaleler çaldırmış ar taşlarını 

Gediklerden korlar yağmış evlere...

Dalgalar boğulur, denizler biter

Sükutun donduğu bir mevsim gelir

Yürekte ateşler yakmadan tüter

Ve belki, kopmaya; hüzün incelir...

Elimde kelepçe, gözlerim donmuş

Döndüm, bulutların arasında Sen! ...

Erciyes, Erciyes! ... ruhuma konmuş

Bir beyaz güvercin, bir buzlu desen...', 'Elimde kelepçe, gözlerim donmuş Döndüm, bulutların arasında Sen! ... Erciyes, Erciyes; ... ruhuma konmuş Bir beyaz güvercin, bir buzlu desen...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Tevfik Ozan']::text[], 8.5, '{"poet":"Ahmet Tevfik Ozan","poet_slug":"ahmet-tevfik-ozan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/mapusane-avlusundan-erciyes-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yine Seni Severim', 'yine-seni-severim-efsun-aydin-zsrt8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dun gece cok ağladım ben…

Sen orada oylece uyurken hem de,

En çok da seni düşündüm ben…

Sen yorgun dusup halsizce uzanırken EVim dediğin o yerde,.

Bir de uzun uzun seni izledim ben…

Sen yollarla açsan da aramızı istemeden nedenlice üstelik.

Görmezken bile seni, hissederim ben verilen sevgiyi.

Aslında sensiz bu dünyanın bin beteri var bana…

Tek arkadaşım kalsa da bir kadeh içki ile sigara,

Kaleme kağıda sarılır yine seni içer,

Yine seni içerim Canım Sevgilim.', 'Dun gece cok ağladım ben… Sen orada oylece uyurken hem de, En çok da seni düşündüm ben… Sen yorgun dusup halsizce uzanırken EVim dediğin o y...', ARRAY['Türk Edebiyatı','Şiir','Efsun Aydın']::text[], 8.5, '{"poet":"Efsun Aydın","poet_slug":"efsun-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/yine-seni-severim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mapusane Diliyle Yıldızlar Üzerine', 'mapusane-diliyle-yildizlar-uzerine-ahmet-tevfik-ozan-38kfj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çocukluğumuz, Harput''ta geçti… Karların kalkmasıyla, Buzluk Yaylası’na at, katır sırtında başlayan yolculuğumuz, bizi çocuk gönlümüzün en uzak diyarına taşırdı... Bir gün, uzaktaki bir akrabaya  ziyarete giderken, tren raylarını ve treni ilk kez gördüm… Ufukta kaybolan tren raylarına bakarak ''bunlar, kimleri nerelere götürüyor? ., halbuki herkes bizim gibi evinde, barkında oturmuyor mu? ..''diye kendi kendime sormuştum. Çocuk gönlümde, cevabını (bu trenler, ninemin ''... oğul! ..uzaklaşma, yoksa seni yel aparır” sözlerinde geçen, rüzgârların  insanları kaçırdığı tuhaf ve uzak diyarlara gidiyor...)  şeklinde bulmuştum.

       Nice yıllar sonra ben, yetmişli yıllarda; genç bir tıbbiye talebesi olarak, yine bu raylar üzerinde Ankara''ya gittim. Ninemin ''aman oğlum dikkat yel aparır.''..'' dediği diyarlara...

       Birkaç yıl böyle geçti. Bir renkli fotoğrafa tek renk şeffaf bir jelatin kağıdı geçirirsiniz; renkler kaybolur, kişiler ve eşyalar, evler, bahçelerin üzerine bir gölge düşer; bir tuhaf olur, işte öyle... Anarşi, üniversite ilk yıllarının allı-pullu Ankara''sını böyle tek renkli cehenneme çevirdi.

       Arkasından öğrenci olayları, öğrenci dernekleri ve basın davaları geldi. Kendimizi Ankara Kapalı Cezaevi 1. Kısım 2. koğuşunda, elliye yakın öğrenci arkadaşla birlikle soğuk taş duvarların arasında bulduk.

        Hani masallar vardır: kan emen vampirler, güneş doğup ışıkları vücutlarına değince kül olup dağılırlar..? Bunun gibi,ama tuhaf; bütün cezaevlerinde tutukluları tenlerine Gece değer kül olur dağılırlar(!)   diye  hep Güneş batmadan koğuşlara kapatırlar. Günlerce, aylarca, yıllarca hep böyle! ...

        Bir gün Ankara-Kapalı Cezaevi l. Kısım 2. Koğuşunda inanılmaz bir şey oldu. Gece bir firar ihbarıyla, bütün tutukluları dışarı çıkardılar. Bir yeşil vadide akan, duru bir nehirde yüzmek için vadiye koşan şen-şakrak. çocuklar gibi dışarıya çıktık. Hayret! ...

        Kimimiz davarlara yaslandık, kimimiz yerlere oturduk, kimimiz sırtüstü yattık, uzandık.. Ama hepimiz çığlık çığlık bir sevinçle onları doyasıya seyrettik. ''Aaa  şunlara da bak! .. peki, şunlar hangileri? ... şu hepsinden parlak gibi! ..'' diyerek dostlarımızla bir sarmaş dolaş olmadığımız kaldı.

        Ve  ışıklara boğulmuş bir Ankara Gece''sinde, hiç kimse bizlere yasaklanmış gökyüzünden yıldızlar çaldığımızı anlayamadı! ...

MAPUSHANE DİLİYLE YILDIZLAR ÜZERİNE

Ah, yıldızlar! .. Bizlere ne kadar yakınsınız 

Ve uzak! .. rüyalarda koklanmış; çiçek kadar! 

Ne olur, bir vahanın tavrını takınsanız 

Su vermekle, serçeye; yalnız içecek kadar...

Analar:

Burda, yalnız camlarda bir gölgedir

Duvarları is kokan görüş odalarında...

Duvarlar:

Çığlıkları doğrayan, bir cam hançer

Ve buz gibi bir yılan, serçe yuvalarında...

Sahi, çaylar ne halde? ., koğuş bardaklarında: 

Soğuk satılsa bile yüreklerde ısınmış

Asla kan rengi değil, bizzat sıcak kan mıdır? 

Tavanlara, musluğa, duvarlara  bulaşmış

Yağlı koyu gölgeler

Kaynayan yüreklerde terleyen Zaman mıdır? 

Üzerine cam fanus kapatılmış kelebek

Ne yapsın, çırpındıkça kanatları kırılsa? 

Saniyeler burda hep kor ateşten bir çelenk 

Kaf dağını aşmaya hazır(!)  demirden asa! ..

Ah, yıldızlar! .. Bizlere ne kadar yakınsınız 

Ve uzak... rüyalarda koklanmış çiçek kadar! ..', 'Çocukluğumuz, Harput''ta geçti… Karların kalkmasıyla, Buzluk Yaylası’na at, katır sırtında başlayan yolculuğumuz, bizi çocuk gönlümüzün en uz...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Tevfik Ozan']::text[], 8.5, '{"poet":"Ahmet Tevfik Ozan","poet_slug":"ahmet-tevfik-ozan","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/mapusane-diliyle-yildizlar-uzerine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğum', 'dogum-umit-demir-5luwm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bana hamileyken 

hep bir kızı olsun istermiş canım annem

işte belki bu yüzden 

dünyaya bir genç kızın saf yüreğiyle gelivermem', 'bana hamileyken  hep bir kızı olsun istermiş canım annem işte belki bu yüzden  dünyaya bir genç kızın saf yüreğiyle gelivermem...', ARRAY['Türk Edebiyatı','Şiir','Ümit Demir']::text[], 8.5, '{"poet":"Ümit Demir","poet_slug":"umit-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/dogum-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözyaşı', 'gozyasi-abdurrahman-tepe-ryklq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bazen fırat gibi

Coşar bu gözyaşım

Bazen murat gibi

Taşar bu gözyaşım

Bazen hayellere

Bazen sevdalara

Bazen ağ güllere

Ağlar bu gözyaşım

Bazen de hasrete

Bazen de firkata

Bazen de rahmete

Gelir bu gözyaşım

Bazen bir deryadır

Bazen bir damladır

Bazen bir hülyadır

Söner bu gözyaşım

Bazen bir şivandır

Bazen bir dermandır

Bazen bir fermandır

Okur bu gözyaşım

Bazen bu SAMİHİ

Pek çoktur günahı

Sever hep penahı

Söyler bu gözyaşım', 'Bazen fırat gibi Coşar bu gözyaşım Bazen murat gibi Taşar bu gözyaşım Bazen hayellere Bazen sevdalara Bazen ağ güllere Ağlar bu gözyaşım Baz...', ARRAY['Türk Edebiyatı','Şiir','Abdurrahman Tepe']::text[], 8.5, '{"poet":"Abdurrahman Tepe","poet_slug":"abdurrahman-tepe","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gozyasi-55-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasret Prangası...', 'hasret-prangasi-i-brahim-ethem-bingul-ors7l', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen de hasret prangaları ile kanıyor musun

Ayrılık habersizce yıllara mı mahkûm oldu

Sana koşturduğum saatlere

Günler mi el koydu...

Vuslat hangi baharda esir, biliyor musun

Yüreğin cam kırıklarıyla mı atıyor

Baktığın ama görmediğin oluyor mu

Aldığın nefes alev olup yakıyor mu...

Yokluğun hançeri bağrında eriyor mu

İsmimin geçtiği her cümleye

Benim olma ihtimali ile

Yürek mi kabartıyorsun

Adaklar mı adıyorsun, can mı atıyorsun

Duyabileceğin, bir sağlıklı mutlu haberime...

Dalgakıran oldun aşkıma

Sahilim sensin, hiç kıyar mıyım sana

Dayandım deli tufanlara

Yıkıldım rengini söylemeye tövbe ettiğim

Gözlerinin ayrılığına...

www.iebingul.com', 'Sen de hasret prangaları ile kanıyor musun Ayrılık habersizce yıllara mı mahkûm oldu Sana koşturduğum saatlere Günler mi el koydu... Vuslat ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/hasret-prangasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vatan', 'vatan-enver-topuz-yj9jf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Şu an yaşamamızı sağlayan

Bütün savaşlara dayanan

Herkesin göğüs gerdiği savaşlarda

Sınırları belli toprak parçasına

Üstünden çok imparatorluk geçen

En çok Türkiye’yi seven

Türkiye’yi hep ayakta tutmuş

Atatürk’ün de yardımı olmuş

Askerleri ısıtmış

Evlerini yaratmış

Türkiye’nin atom karıncaları

Vatanı yalnız bırakmamış

Toprağı altın

Evleri gümüş

İnsanların kalpleri temiz

Hepimiz misafir perveriz

Atatürk ve askerleri

Kurtarmış bu memleketi

Vatan sayesinde

Yazdım bu şiiri', 'Şu an yaşamamızı sağlayan Bütün savaşlara dayanan Herkesin göğüs gerdiği savaşlarda Sınırları belli toprak parçasına Üstünden çok imparatorl...', ARRAY['Türk Edebiyatı','Şiir','Enver Topuz']::text[], 8.5, '{"poet":"Enver Topuz","poet_slug":"enver-topuz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/vatan-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gecenin Daveti', 'gecenin-daveti-yildiz-agirman-lq8ak', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Konukların tamamı gelmiş.

Aşk gibi, nefret gibi, öfke, şefkat gibi bir kısmı

kıskançlık, şiddet, sevişmek, isyan gibi diğer kısmı

bitmiş davaların, bitmemiş gürültüleriyle.

Bir köşede de çaresizlik

tek başına, sessiz.

Yokluğun da gelmiş bedeninle.

Beden, geceye egemen.

Bir eksik, bedenini kuşatmış konuklar.

Biri sevmede, diğeri dövmede,

sararken sıcacık biri, gözlerini istemede diğeri

kovarken biri, tutmada diğeri

haz içirmede biri, kırarken zincirleri

Kıpırdamadan biri

keyifle beklemede

ne de olsa,

geceden yalnız gitmeyecek olanı bilmede

koluna taktığı gibi yokluğunu

veda edip geceye, alıp gitmede bilinmeyene

ardından çıkan yangını umursamamada

Ve derler ki,

kırık dökük geceyi sadece sabah görmüştür

konukların kimi, ölmüştür gecede

aşk gibi, inanç gibi, kıskançlık gibi

kimileri kayıplara karışmıştır

ümit gibi, sevişmek gibi, sadakat gibi

Yine derler ki,

çaresizlik hala mutludur yokluğunla

ve çok değişmiştir

hatta adını bile uzun bulup, kısaltmıştır çare gibi

yokluğunu evde bırakıp

başka gecelerin başka davetlerinde

2005/ekim', 'Konukların tamamı gelmiş. Aşk gibi, nefret gibi, öfke, şefkat gibi bir kısmı kıskançlık, şiddet, sevişmek, isyan gibi diğer kısmı bitmiş dav...', ARRAY['Türk Edebiyatı','Şiir','Yıldız Ağırman']::text[], 8.5, '{"poet":"Yıldız Ağırman","poet_slug":"yildiz-agirman","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/gecenin-daveti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aras Nehri', 'aras-nehri-abdurrahman-tepe-9bbis', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kıvrıla kıvrıla akıp gidersin

Akışın ne güzel ey Aras Nehri

Gece gündüz demez coşkun akarsın

Gelişin ne güzel ey Aras Nehri

Bingöl dağlarıdır senin yatağın

Kağızman Tuzluca sevda otağın

Hazar Denizidir en son durağın

Gidişin ne güzel ey Aras Nehri

Neden bulanıksın durulmaz mısın

Kaç bin yıldır akar yorulmaz mısın

Sevda ateşinde kavrulmaz mısın

Yanışın ne güzel ey Aras Nehri

Senin bu rikatın manasız değil

Her kınalı kuzu anasız değil

Can var ise bil ki canansız değil

Duruşun ne güzel ey Aras Nehri

SAMİHİ anlar mı senin dilinden

Çok dert çektik ayrılığın elinden

Var bir haber eyle Revan elinden

Varışın ne güzel ey Aras Nehri', 'Kıvrıla kıvrıla akıp gidersin Akışın ne güzel ey Aras Nehri Gece gündüz demez coşkun akarsın Gelişin ne güzel ey Aras Nehri Bingöl dağlarıdı...', ARRAY['Türk Edebiyatı','Şiir','Abdurrahman Tepe']::text[], 8.5, '{"poet":"Abdurrahman Tepe","poet_slug":"abdurrahman-tepe","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/aras-nehri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tutanak', 'tutanak-yildiz-agirman-d0ab0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dayadım yüreğine silahı

cesur

sordum

''seviyor musun''

cılız

cevapladı

''seviyorum''

titreyen sesle

ölmesi gerekiyordu

öldürdüm

vurdum

işte ''o silahla''

yüreğimi

paramparça', 'Dayadım yüreğine silahı cesur sordum ''seviyor musun'' cılız cevapladı ''seviyorum'' titreyen sesle ölmesi gerekiyordu öldürdüm vurdum işte ''o s...', ARRAY['Türk Edebiyatı','Şiir','Yıldız Ağırman']::text[], 8.5, '{"poet":"Yıldız Ağırman","poet_slug":"yildiz-agirman","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/tutanak-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yuhlar Olsun', 'yuhlar-olsun-abdurrahman-tepe-l84in', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bile bile insanları

Kandırana yuhlar olsun

Haram şeye lokmaları

Bandırana yuhlar olsun

İşini hileyle yapan

Helallara haram katan

Yeminle insan aldatan

Doland’rana yuhlar olsun

Doğru varken yanlış işe

Hikmetsiz bir serzenişe

İhvanını hem teşvişe

Yandırana yuhlar olsun

SAMİHİ gel gafil olma

Çar çur için sefil olma

Yanlış söze mahfil olma

İnand’rana yuhlar olsun', 'Bile bile insanları Kandırana yuhlar olsun Haram şeye lokmaları Bandırana yuhlar olsun İşini hileyle yapan Helallara haram katan Yeminle ins...', ARRAY['Türk Edebiyatı','Şiir','Abdurrahman Tepe']::text[], 8.5, '{"poet":"Abdurrahman Tepe","poet_slug":"abdurrahman-tepe","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yuhlar-olsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'AriF''e TaRiF Ne GeReK...?', 'arif-e-tarif-ne-gerek-mine-ozdemirtas-niijn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Arife tarif ne gerek? 

içimin göçüne el sallayışımdır bu.

Bana dair herşey, 

Bana rağmen 

tutmuşken yolu; 

Sevdanın yerinde 

inatla oturduğu

bilmem ki ne denli  doğru? 

Berrak sularımın git gide 

batakla dolduğunu, 

Bu yüzden 

epeydir soluksuz olduğumu,

o dillere destan gücümün 

dibine vurduğumu,

Ve

Kaygan yosunlarına nasıl 

zorlukla tutunduğumu

Anlatsam...! 

uçurumun kenarında durduğumu

Anlar mı ki eloğlu?', 'Arife tarif ne gerek?  içimin göçüne el sallayışımdır bu. Bana dair herşey,  Bana rağmen  tutmuşken yolu;  Sevdanın yerinde  inatla oturduğu...', ARRAY['Türk Edebiyatı','Şiir','Mine Özdemirtaş']::text[], 8.5, '{"poet":"Mine Özdemirtaş","poet_slug":"mine-ozdemirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/arif-e-tarif-ne-gerek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Belkide sonsuz özgürlüğümsün', 'belkide-sonsuz-ozgurlugumsun-kamil-soylemez-5r158', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen hey derin mavi düşüm

Gönül gözü,tutuşmuşum

Neyin var ki yürekten başka 

Bir ara tutuşup,birara üşümüşsün

Bir de buna aşk sevda diye 

Fikirler, göz yaşları dökmüşüm

Ah benim derin mavi düşüm

Dağlar başı sevgi kuşum

Ömürüm üzerine nurlar düşürmüşüm 

Sen daha çok sevilip

Daha çok büyülenmişimsin

Belkide sonsuz özgürlüğümsün

Çıkıver isterim derin mavi düş sokaklarıma', 'Sen hey derin mavi düşüm Gönül gözü,tutuşmuşum Neyin var ki yürekten başka  Bir ara tutuşup,birara üşümüşsün Bir de buna aşk sevda diye  Fik...', ARRAY['Türk Edebiyatı','Şiir','Kamil Söylemez']::text[], 8.5, '{"poet":"Kamil Söylemez","poet_slug":"kamil-soylemez","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/belkide-sonsuz-ozgurlugumsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Papatya', 'papatya-faik-yildiz-ou7s5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'benim çocukluğumda

papatya; 

ilkbaharda

bizim köy evlerinin

toprak damlarının

saçak uçlarında

birde,

ekin zamanı

ekilmemiş tarlalarda

yetişirdi.

kız çocukları

taç yapardı başlarına,

şimdi ise papatya

sanal dünyada.

ki o papatya

evrenin dışında

ve klavyemin ucunda

san ki var,

sen ki yok

ellerimde papatyalar

rüyamıdır, sanalmıdır, masalmıdır......', 'benim çocukluğumda papatya;  ilkbaharda bizim köy evlerinin toprak damlarının saçak uçlarında birde, ekin zamanı ekilmemiş tarlalarda yetişi...', ARRAY['Türk Edebiyatı','Şiir','Faik Yıldız']::text[], 8.5, '{"poet":"Faik Yıldız","poet_slug":"faik-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/papatya-33-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son İstanbul', 'son-i-stanbul-funda-bahceci-tb3tx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'erinç bir  Yunan müziği eşliğinde

Marmara dalgalarını yatırır,

eski İstanbul''un evleri arasında

demir işlemeli bir balkon uyanır

titrek bir ses geçmişe uzanır

sararmış fotoğraflardan silinmiş yüzü

içinden geldiği gibi açmış kollarını 

tango yapmak istercesine

Son İstanbul''a nispet

davet eder genç kadını

''nisanın mayısa taşındığı günlerde 

tarçın kokusu sarardı  sokakları

yürürken taşlı kaldırımlarda,

gülümserdi gül buketleri

ahşap evlerin açık camlarından içeri.

Yeni gelinleri aşure ayında bir telaş alırdı

önemli miydi bayram ya da seyran

Son İstanbul''a nispet

kapı kapı gezer şeker toplardı çocuklar''

taş sektirmeye gittiğim kıyılar

lale sokağından aldığım pamuk helva

dondurmayı sarıp pamuk helvaya

gezerken sahil boyunca sevgilimle

kısmet güvercini bir mani bile çekmeden nereye

ayrılırken sevgiliden kemancı bu ne neşhe! 

hüzzam bir beste beklenirken,

kağıda kaleme sarılmış

bu şiiri yazmaya geç kalmış yaşım

Son İstanbul''a nispet

SENİ SEVİYORUUUUUUUM…………', 'erinç bir  Yunan müziği eşliğinde Marmara dalgalarını yatırır, eski İstanbul''un evleri arasında demir işlemeli bir balkon uyanır titrek bir ...', ARRAY['Türk Edebiyatı','Şiir','Funda Bahçeci']::text[], 8.5, '{"poet":"Funda Bahçeci","poet_slug":"funda-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/son-istanbul-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gencin Garip Ölümü', 'gencin-garip-olumu-faik-yildiz-fv1ap', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Odunu kesip eşeğe sararken

Beni bulsa yatarken, uyurken

Yanıma gelse sohbete

Ağzımda bir damla kan görünce

Öldüğümü fark etmişti işte

Ne yapabilirdi ki garip bir ölüyü

Yıktı odunu sardı eşeğe

Haber etti köylüye

Yıkayıp üstünü örtmeye

İmam geldi hayırdır diye

Köylüler geldi gariptir diye

Gençler kazdı kabrimi

Oda bizdendir diye

Salâ okundu ince minareden

Dört köşeyi inleten

Koydular dört tahtaya

Yolladılar öbür dünyaya

Zavallı genç dediler

Başka bir şey demediler

Üzerime biraz toprak, taş

Ve bir çakır dikeni

Baş ucuma sivri bir taş

Diktiler zavallı köylüler

Ve bir gün üzerimden

Köstebek dürttüğü diyerek

Birazcık toprağı da teptiler

Ruhuma el-fatiha bile demediler

Garipler böyle ölecekse

Doğmasalar, gelmeseler şu garip dünyaya

El sevdi diye sevmeseler, Şu acımasız hiçte

Olmaz mı, olamaz mı? Tanrım...', 'Odunu kesip eşeğe sararken Beni bulsa yatarken, uyurken Yanıma gelse sohbete Ağzımda bir damla kan görünce Öldüğümü fark etmişti işte Ne yap...', ARRAY['Türk Edebiyatı','Şiir','Faik Yıldız']::text[], 8.5, '{"poet":"Faik Yıldız","poet_slug":"faik-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/gencin-garip-olumu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'HaNi', 'hani-ali-aydogan-lt2zf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hani Gözlerin vardıya takılıp kaldıgım

Ugruna Bir Ömür Adadıgım 

Hani bir Hayalimiz Vardıya SeninLe

Bir OguL Düşlediğimiz Bir Can HayaL Ettigimiz

Hani Yarınalarımız Vardı SeninLe

Ne Oldu KimLer Caldı DüşLerimizi

KimLer Caldı YarınLarımızı Bilmemki

Ayrılmamak İçin Söz Vermiştik MutLuLukLara

Hanmi Bir AŞkımız Vardıya SeninLe Bir Ömür Sürücek

Ne OLdu Aşkımıza Karlı DağLar Ardındamı Kaldı 

Ne ZorLukLara GöGüs Germştik SeninLe Unuttun mu? 

Beraber AgLAdık Beraber gülmüştük

Hani Sevdigim Konusabilsem KeşKe

Derdimi Anlatabilsem Sana KeşKe

Sen Gittin SözLerim DüğümLendi Dilimde

Kim Tutucak Ellerimden ben Kimin GözLerinde Uyuyacağım? 

Kimin DizLerinde Oturup Derdimi AnLatıcam

Gitmek KoLaydı Aya Terkedilmek? 

Ya Giderken Yaşlı GözLerLe Ardından

Dur Bitanem KaL BenimLe Diyememek

Hani KelimeLerLe AnLatamazsın Bazan

Bir BoşLukta Kalırsınya Hani

Şimdi Gittigin YOllarda ÖzLüyorum Seni

Sen Artık Derdimi AnLattığım MısraLArda 

HüzünLü Çalan ŞarkıLarın ÇığLıkLarında Kaldın', 'Hani Gözlerin vardıya takılıp kaldıgım Ugruna Bir Ömür Adadıgım  Hani bir Hayalimiz Vardıya SeninLe Bir OguL Düşlediğimiz Bir Can HayaL Etti...', ARRAY['Türk Edebiyatı','Şiir','Ali Aydogan']::text[], 8.5, '{"poet":"Ali Aydogan","poet_slug":"ali-aydogan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/hani-83-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilinmez', 'bilinmez-neslihan-i-sler-0pnoo', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ay ışır geceler üşür

Yıldızlar bulutlara gizlenir

Gün gözyaşına dönüşür

Sarmalar çaresizliğin

Tenhalaşır sokaklar

Bir ayak sesine hasret bırakır

Pencereye yaslanır 

Gecenin aksine bakar bulursun

Kendini...

An zamanını yitirmiş

Bir yıldız kayar gecenin karanlığına doğru

Kaybolur gider

Ardında sade bir ışık huzmesi 

Kalp unutmaz yıldızın oldugu yeri

Göz görmesede gönül bilir

Yer sabittir 

Herkes birgün aynı yerde

Günün bittiği

Gecenin hüküm sürdüğü

Bilinmezde....

Atilla İlhan''a sevgi ve saygılar...', 'Ay ışır geceler üşür Yıldızlar bulutlara gizlenir Gün gözyaşına dönüşür Sarmalar çaresizliğin Tenhalaşır sokaklar Bir ayak sesine hasret bır...', ARRAY['Türk Edebiyatı','Şiir','Neslihan İşler']::text[], 8.5, '{"poet":"Neslihan İşler","poet_slug":"neslihan-i-sler","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bilinmez-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Atıf-2(Atilla İlhan Anısına)', 'atif-2-atilla-i-lhan-anisina-vedat-koparan-jbmiu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '-An Geldi Mi Usta-

sende ölecek adam mıydın? 

hey koca çınar Atilla ilhan 

böyle mi gidilirdi 

yağmur kaçağı seni gidi 

ne diye verdin şimdi

gözlerimden yüreğime bu hüznü

evet usta 

bir bombada sen patlattın 

güle güle git güle 

bıraktığın anılar yeter mi bize

kaldır başını bak ardında ölü seviciler 

bölüşüyorlar parça parça lime lime 

nasılda timsah göz yaşları içindeler

dedim bir hal var bu işte 

dönerken güne mavisinde

ne çok gülmüştüm bu gece

gün döndü kapkara bir hüzne

hüznümü bıraktım aydınlanan güne 

değiliz dikensiz bir gül bahçesinde 

üşüdü güz çiçeğim üşüdü her yitimde

Vedat Koparan  11.10.2005

saygıyla başımız sağolsun', '-An Geldi Mi Usta- sende ölecek adam mıydın?  hey koca çınar Atilla ilhan  böyle mi gidilirdi  yağmur kaçağı seni gidi  ne diye verdin şimdi...', ARRAY['Türk Edebiyatı','Şiir','Vedat Koparan']::text[], 8.5, '{"poet":"Vedat Koparan","poet_slug":"vedat-koparan","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/atif-2-atilla-ilhan-anisina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Siz Nerelerdeydiniz...', 'siz-nerelerdeydiniz-melek-ayaz-xppad', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Beni karanlıkta vurdular,

Gömdüler gecenin sessizliğine,

Siz nerelerdeydiniz...

Kurtlar kuşlar duydu,

Çalınca o korkunç saat,

Yığıldı karanlık kat kat,

Siz nerelerdeydiniz...

Ne varsa artık yitik,

Gözlerim, ellerim, ayaklarım,

Ben ha varım, ha yokum,

Siz nerelerdeydiniz...', 'Beni karanlıkta vurdular, Gömdüler gecenin sessizliğine, Siz nerelerdeydiniz... Kurtlar kuşlar duydu, Çalınca o korkunç saat, Yığıldı karanl...', ARRAY['Türk Edebiyatı','Şiir','Melek Ayaz']::text[], 8.5, '{"poet":"Melek Ayaz","poet_slug":"melek-ayaz","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/siz-nerelerdeydiniz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sirkeci - Kadıköy', 'sirkeci-kadikoy-omer-kement-gtvl1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Geçmek için karşıdan karşıya,

Yaşlanmış Sirkeci-Kadıköy vapuruna,

İtişerek bindim kalabalık arasında,

Ancak yer bulabildim korkuluklarında.

Öttü yerden bir düdük sesi,

Karşılık verdi bağırdı vapurun sireni.

Aldı sararmış urganı çımacının eli,

Ağırdan yol aldı vapurun kendi.

Usulca baktım karşı kıyıya,

Heybetli göründü Haydarpaşa.

Engin deniz Marmara açıklarda,

Uçan leyleklerin, martıların altında.

Yavaştan giden vapur hızlandı birden.

Deniz arkada şahlandı, köpürdü öfkeden,

Bağırıyordu konçerto gibi içinden.

İrkiliyordu insan denizin heybetinden.

Vapur köpükler arasında giderken,

Yanında denizanaları süzülürken,

Açığında boğaz akıcı ama dingen,

Bir sessizlik sükunet tümden.

Yukarıda hava sankim biraz puslu,

Güneş can yakmıyor duruyor uslu,

Vakit öğleden sonra ikindi sonu,

Emektar vapur daha hızlı gidiyordu.

Hızlandıkça, boğaz kuduruyor, köpükler saçıyordu.

Haşin ama bembeyaz, tertemiz huzur veriyordu.

Hareket edeli beş dakika olmuş, saat onbeşi beş geçiyordu.

Hava puslu, deniz koyu ama berrak, balıklar görünüyordu.

Denizin üzerinde bizi izleyen biri vardı.

O ana kadar hiç farketmemiştim bu ışığı.

Muhteşem bir parlaklık, sanki yakut ışıltısı.

Güneş denize vurdukça artıyor parıltısı.

Önümde gölgem kadar yakamoz oynuyor,

Baktıkça sanki benimle konuşuyor.

Anlattıkça bana; birisini, geçmişimi hatırlatıyor,

Hatırladıkça güzelliğin birden gözönüme geliyor.

 Sanki yanımdasın gözlerimi ayıramıyorum.

Aklım başımdan gitmiş sana bağlanıyorum.

Vapurun sireni, kendine özgü, kalınca irkiliyorum.

Denizde yakutun yanında, inci taneleri görüyorum.

Güneş vurdukça oynaşıyorlar benimle,

Sankim dalga geçiyorlar geçmişimle,

Ama harikulade güzeller senin yerine,

Nur taneleri gibi içiçe oluyorlar benle.

Katılmak istiyorum bende onların arasına.

Atlamak istiyorum boğazın serin sularına.

Kavuşmak, sarılmak istiyorum hayaline, sana.

Takmak istiyorum inci taneleri saçlarına. 

Yaklaştıkça kıyıya sessizlik, gürültü oluyorlar.

Görünüyor dalgakıranlarda leylekler, martılar.

Aralarında uçuyor kah güvercinler, fenere konuyorlar.

Fenerin ampülü yok, sanki yol gösterecek onlar.

Kıyıya varınca artıyor sesler, bağırıyor balıkçılar.

Kirleniyor deniz, mahvediyor herşeyi insanlar.

Kaybetme korkusu sardı beni, bulandıkça sular.

Kendime geldim, hayallerim geçmişim bir anda uçtular.

Vapur hız kesti, denizin köpürtüsü bitti.

Ağırdan giderken deniz duruluverdi.

Coşan duygularımda deniz gibi,

Yaklaştıkça kıyıya diniverdi.

İstemezdim zaten insanların arasında,

Hayalini canlandırmak bu kalabalıkta.

Çünkü kıskanırdım seni onlar arasında,

Sevgisiz, saygısız, kirlenmiş toplumda.

Bu sefer baktım karşı kıyıya, görünüverdi,

Tarihi Topkapı Sarayı, Sultanahmet Camii.

Sağında Beyazıt Kulesi, Süleymaniye Camii.

Gülümsüyordu; dalga geçer gibi, heybetli heybetli.

Bir kısa yolculuk daha sona ermişti.

Ömürden bir yirmi dakika daha geçivermişti.

O kısa zamanda otuz yıl hatıra gelmişti.

En güzel yeri ise senin hayalindi, sevgin idi...

Ö.K. (16.09.02)', 'Geçmek için karşıdan karşıya, Yaşlanmış Sirkeci-Kadıköy vapuruna, İtişerek bindim kalabalık arasında, Ancak yer bulabildim korkuluklarında. ...', ARRAY['Türk Edebiyatı','Şiir','Ömer Kement']::text[], 8.5, '{"poet":"Ömer Kement","poet_slug":"omer-kement","theme":"Türk Şiiri","is_hero":false,"total_lines":73,"source_url":"https://www.antoloji.com/sirkeci-kadikoy-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cevap', 'cevap-omer-kement-pjo1q', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bekleyeceğim büyük bir sabırla.

Dinleyeceğim içimi kemiren merakla.

Belki dilimle söyleyemedim ama,

Onlarca şiirim tercüman oldu bana.

Gözlerinin içine bakarak haykırıyorum! 

Seni seviyoruuum, seni seviyoruuuum...

Anla artık ıstırabımı çıldırıyorum.

Hala senden bir söz duyamıyorum.

Son veremem asla bu sevgime,

İsterim karşılık bulmak sende.

Gelmezse bir yanıt gönlüme,

Gömeceğim sevgimi kalbime.

Gideceğim buralardan, çoook uzaklara...

Sevgimi alıp uçacağım ırak diyarlara.

Bir sevgin, bir ben bu dünyada,

Dönüp dolaşacağım, vade sonuna.

Ö.K. (16.09.02)', 'Bekleyeceğim büyük bir sabırla. Dinleyeceğim içimi kemiren merakla. Belki dilimle söyleyemedim ama, Onlarca şiirim tercüman oldu bana. Gözle...', ARRAY['Türk Edebiyatı','Şiir','Ömer Kement']::text[], 8.5, '{"poet":"Ömer Kement","poet_slug":"omer-kement","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/cevap-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gömlündesin', 'gomlundesin-omer-kement-shkn4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir bakışın, bir gülüşün, bir sözün,

Titretmeye yetiyor bedenimi,

Yerinden oynatıyor kalbimi.

Gözlerin, dudakların, ellerin...

Heyecanlandırıyor nefesin,

Kendimdem geçiyorum,

Düşünemiyorum aklıselim.

Belki yanlış yoldayım...

Alamıyorum kendimi senden,

Sıyrılamıyorum benliğinden,

Uçuruyor beni varlığın,

Götürüyor hayal alemine...

Sanki bir sihir var üzerimde,

Beni bağlayan bir şey ama ne? 

Bir sevgi mi bu, yoksa bir aşk mı? 

Önce bildiğimi sandığım, yanıldığım...

Bağlanmışım ayrılmayasıya,

Bağı kesmem lazım makasla,

Lakin tutamıyorum elimle,

Yok oluyor dokununca.

Mümkün değil bu bağları koparmak.

Bir çırpıda duyguları atmak.

Mümkün değil bu aşkı unutmak.

Bir çırpıda akıllardan çıkarmak.

Seviyorum seni ayrı kalsakda.

Bırakamam seni buluşamasakda.

Silemem seni benim olmazsanda.

Seviyorum seni unutamam asla...

Kalbimin hepsini sana amade ettim.

En değerli hazinem sevgimi verdim.

Dünyanın ucunda olsanda sevgilim,

Benden ayrı değilsin, gönlümdesin.

Ö.K.(19.09.02)', 'Bir bakışın, bir gülüşün, bir sözün, Titretmeye yetiyor bedenimi, Yerinden oynatıyor kalbimi. Gözlerin, dudakların, ellerin... Heyecanlandır...', ARRAY['Türk Edebiyatı','Şiir','Ömer Kement']::text[], 8.5, '{"poet":"Ömer Kement","poet_slug":"omer-kement","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/gomlundesin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hesret', 'hesret-ahmet-hani-6e71q', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ağacdan göye,

Uçanda quşlar,

Göylerde qanad,

Açanda quşlar,

Qefesden çıxıb,

Qaçanda quşlar,

Bulud qızarıb,

Gün batan çağı,

Gözlerin yumub,

El yatan çağı,

Hesretle göye,

Hey baxacağam,

Oturub yolda,

Ağlayacağam

Nisgilli üreyi,

Dağlayacağam

Tanrı''dan bir gün,

Sörüşacağam,

Qaqnadım hanı? 

Qanadım hanı? 

Boğazda haray

Feryadım hanı? 

Bu hesret meni,

Öldürecekdir.

Qanadsız quşa,

Yaşamaq nedir?', 'Ağacdan göye, Uçanda quşlar, Göylerde qanad, Açanda quşlar, Qefesden çıxıb, Qaçanda quşlar, Bulud qızarıb, Gün batan çağı, Gözlerin yumub, E...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Hani']::text[], 8.5, '{"poet":"Ahmet Hani","poet_slug":"ahmet-hani","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/hesret-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Usul...Usul...', 'usul-usul-melek-ayaz-1kjk1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Tutsak gölgedir, bendeki ben...

Yapraklarını savurma, dur rüzgar...

Acılı düşle dolaştığım sokaklarda,

Yaklaşmaktayım sana usul...usul...

Bir ses bölüyor uykumu uzaktan,

Şuramda duruyor geride kalan günlerim.

Ötelerde boşluğa fırlatılan yanlızlığım,

Bir günaydınla uyanıyorsun içimde,

Fakat biliyorum çok uzaklardasın.

Sen çıkıyorsun her kapının ardından,

Bir günaydınla uyanıyorsun içimde,

Eklem yerlerime oturmuş sızınla..

Martıların ağzında yarım kalan türkülerimizi,

Sen anlamadıysan, kimseler anlamaz...

Artık yorgun düştü gölgem, elleme bana,

Bırak oynatma perdeyi...dur,,,

Ipıslak bir düşle kalsın...

Çünkü.............................

Yaklaşmaktayım sana usul...usul...

............................................................

Mutlu bir kuş belleğimizde....

Tüm çabalarımızda yitirdiğimiz.....

............................................................', 'Tutsak gölgedir, bendeki ben... Yapraklarını savurma, dur rüzgar... Acılı düşle dolaştığım sokaklarda, Yaklaşmaktayım sana usul...usul... Bi...', ARRAY['Türk Edebiyatı','Şiir','Melek Ayaz']::text[], 8.5, '{"poet":"Melek Ayaz","poet_slug":"melek-ayaz","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/usul-usul-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '…Bir Ustaya Veda…Attila İlhan’ın Anısına….', 'bir-ustaya-veda-attila-i-lhan-in-anisina-naime-erlacin-hp1mg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'çalımlı bir ateş dansıydın buz üstünde

harlandıkça alevin 

demini aldıkça duygu

sahipsizlikten soruldun usta 

kimsesizlikten

terk edildi yüzün siyahın büyüsüne

sağalmayı unutan kangren ey! 

gizli isyanında 

en yakın yarasın şimdi kendine

bilemedik 

hangi sığınakta döllendin 

nasıl bölündün bin irinli pareye

kayıp gürzüne ağlıyor ayaklarım

okunaksız bir aynayı tashihten suçlu

çözmeye çalıştıkça sırrını dipsiz boşlukların

yoruldun 

yorulduk! 

kırıktı zeminler

kızıl bir cehennem bağışlandı gitmelere

âh’lar alnımızdaki kara lânet

göğsümüzdeki çukurdan derin

biz ki idamlık geçitleri açık tuttuk hep

kapılarda kilit, kilit üstüne

buza nakşolmuş ezgilerde yağmalandık

kimdik 

neydik 

unuttuk

siyaha uluyan dişinin 

rahmine bırak ateşi 

ve git! 

güzel bir doğum olmalısın kendine

uzaktaki kıtanın deli tayları 

mutlaka savuracaktır güneşe yelelerini bir gün

içimizdeki dünya bir gün mutlaka 

zehrini kusacaktır ne olsa

hiç değilse gülümseyerek git 

başımız sağ mı bilemem ama

yine ağıt var yazgımızda... 

(11 Ekim 2005 – Kara Bir Gün)', 'çalımlı bir ateş dansıydın buz üstünde harlandıkça alevin  demini aldıkça duygu sahipsizlikten soruldun usta  kimsesizlikten terk edildi yüz...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/bir-ustaya-veda-attila-ilhan-in-anisina-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sanat!', 'sanat-enes-ates-63zp8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Mazlumlara sanki zindandır hayat,

Isırgan dallara kök salmış bile

İç yakar gülüşler, gülüşler bayat

Muştusu yoktur ki müjdesi olsun

Bir kuru ekmeğe yüklü talimat

Ayağını yere kimler basacak,

Dururken mafyası zebanilerin? 

Kim bulmuş çareyi ki mazlumlar bilsin? 

Hayatları koskoca bir ıstırahat

Yastığı dikenle doldurulmuşsa

Bîhaber olmak mı bizim suçumuz,

Baykuşun gül ile imtizacından...? 

Yücalik kavramı şöylece dursun,

Alçak sayılmaktır tüm gayeleri

Zalimin boynunu kimler kesecek? 

Mazluma yazılsa bir garib şiir

Kanımızı emer bütün kusurat

Aldanmak çaredir yalana amma

Bîçare olmaktır bir yudum zehir

Şu sivri dilimi kimler kesecek

Kesmeden boynumu söz vampirleri? ? ? 

Yaşamak mezalim gerçek muamma

Kim bulmuş doğruyu, onlar bilecek

Doğrusu zalimlik, işte bu SANAT  (! ! ! !) ...', 'Mazlumlara sanki zindandır hayat, Isırgan dallara kök salmış bile İç yakar gülüşler, gülüşler bayat Muştusu yoktur ki müjdesi olsun Bir kuru...', ARRAY['Türk Edebiyatı','Şiir','Enes Ateş']::text[], 8.5, '{"poet":"Enes Ateş","poet_slug":"enes-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sanat-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Helezonik melankoli!', 'helezonik-melankoli-enes-ates-fkj1z', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Anlatamaz bir bilge düşündüğünü

Onun da içinde farklı bir bilge

Anlatmakla meşguldür üşüdüğünü

Ve onun da içinde bir yalnız adam

Gri gülüşüyle masumsa bile

Onur adımları yavaşlatacak

Onun da içinde ukdedir hisler

Ve onunda içinde bir deli adam

Hissetmekle meşguldür gülünçlüğünü

Ardında bir dağ büyüten izci

Asla ulaşamadı masal dağına

Onun da içinde bir bilge gizli

Öldürmekle meşguldür en küçüğünü

Büyüklere dünya dar gelir gibi...! 

En gerçek bilgenin bir içindeki

Kendi muhtevasına ulaşamadı

Bu yüzden onun da en içindeki

Hislerini kimseye anlatamadı

Sonunda bir izci kaldı derinde

Okurken hayâlî bir hikâyeyi

Yırttı attı o büyük masal dağını

Ve şimdi katmer katmer o büyük bilge

Aşarak içindeki çaresizliği,

Buldu hakikî dert ortağını ! ! ! ...', 'Anlatamaz bir bilge düşündüğünü Onun da içinde farklı bir bilge Anlatmakla meşguldür üşüdüğünü Ve onun da içinde bir yalnız adam Gri gülüşüy...', ARRAY['Türk Edebiyatı','Şiir','Enes Ateş']::text[], 8.5, '{"poet":"Enes Ateş","poet_slug":"enes-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/helezonik-melankoli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayak sesleri(3)', 'ayak-sesleri-3-enes-ates-wk9b1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bulamam desem de, 

                                  bulmadığımı

İnkâr eder bir edâ hakim ruhuma

Yüzümü hayata kapadığımı

Anlatmak zor imiş şu gururuma....', 'Bulamam desem de,                                    bulmadığımı İnkâr eder bir edâ hakim ruhuma Yüzümü hayata kapadığımı Anlatmak zor imiş ...', ARRAY['Türk Edebiyatı','Şiir','Enes Ateş']::text[], 8.5, '{"poet":"Enes Ateş","poet_slug":"enes-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ayak-sesleri-3-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bedel...', 'bedel-melek-ayaz-tuxib', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir şeyler söyle bana...Susma öyle...! 

Senin karmaşık dünyanda,

Terk edilmeye alıştım da, bu kadarda değil,

Ansızın değil...Susarak değil...

Cesurca, dürüstçe, açıkça ve mertçe bir gidiş,

Kancıkca değil...

Varsa yalan..Varsa riya,

Ve nemelazımcılık, söyle? ...Kendimi yakayım,

Yürekte fesat, gözde oynaşma,

Bakışlarda kaçışma, tende soğukluk, bileyim, tiksineyim.

Böyle olmaz gidiş, dur ben sana öğreteyim,

Hayır deme...

Ben her defasında başı okşanacak bir it değilim,

Ya da sevildiğini anladığında kuyruk sallayan kedi...

Bir dilim ekmeğe muhtaç dilenci gibi el açan,

Gönül çelen, sömüren, tüketen,

İstemem yan cebime koy edasıyla naz eden,

Ayyaşlar misali umursamaz,

Fahişe ruhlu bir adam değilim...

Dürtüsü kaçamaklarında gizli,

Kızıl saçlı NİL...! 

Sis bulutu içinde rezilce kokan,

Korkak...nankör...acımasız,

Bir bedende iki kişi değilim.

Bir ruh var bende en azından,

Sende olmayan...

Sevdim seni yani anlayacağın.

Sevdim...Sevdiğini zannettim,

Oysa sen,katrana boyanmış peştemala sarıp yüreğini,

Gizledin benden gerçek bedenini,

Gizledin ayıplarla dolu katil ruhunu,

Temiz ruhumu, sevgimi kullandın,

Ömrüm dedim...ömrümü yedin,

Evet bitti değil mi...? 

Bu yani söyleyeceğin,

Arkana bakmadan git,

En azından ben kadar bir bedel olacak,

ÖDEYECEĞİN...

11 Ocak 2005 te kaybettiğim kardeşim Hasan Ayaz ''ın darbe yediği sevgisine kendi kaleminden son seslenişi...', 'Bir şeyler söyle bana...Susma öyle...!  Senin karmaşık dünyanda, Terk edilmeye alıştım da, bu kadarda değil, Ansızın değil...Susarak değil.....', ARRAY['Türk Edebiyatı','Şiir','Melek Ayaz']::text[], 8.5, '{"poet":"Melek Ayaz","poet_slug":"melek-ayaz","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/bedel-38-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'hüzün desenli yamalı bir elbise AYrılık..', 'huzun-desenli-yamali-bir-elbise-ayrilik-dilek-egri-605ls', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'esmer akşam üstlerim vardı

ağlamaklı, yaslı

birde senli sayıklamalar

uyandıran sersem uykusuzlukları...

sonra koşmalar,

sana varmayan hayali kavuşmalar

kendimi delirmiş sandığım anlamsızlıklar...

..............................ve dinmeyen mola sancıları....

acıma yetişmek isteyen sigaralar peş peşe

...............................izmariti her söndürdüğümde

.......................................iki parmağımın zaferi diye

...........................................takındığım saçma bir gülümseme 

izini süremeyecek kadar 

silip süpürülmüş bir aşk

meçhul ve kimliksiz

bulmak istedikçe karışık

şimdi aşk; yamalı bir elbise sırtımda

her sevdadan  bir parça

özlemlerim diz boyu

hüzün dekoltem fazla

/......bi tarafa sen bi tarafa ben 

..............................''v'' yakalı bu ayrılık.../

hovarda rüzgarlarda bağrım üşüdü 

ilmek ilmek ördüğüm sevdam sende kal/mış 

gel ve ört üstümü 

önümüz kış..

11//10/05', 'esmer akşam üstlerim vardı ağlamaklı, yaslı birde senli sayıklamalar uyandıran sersem uykusuzlukları... sonra koşmalar, sana varmayan hayali...', ARRAY['Türk Edebiyatı','Şiir','Dilek Eğri']::text[], 8.5, '{"poet":"Dilek Eğri","poet_slug":"dilek-egri","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/huzun-desenli-yamali-bir-elbise-ayrilik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tükenen Ay Işığıydı Saçlarında', 'tukenen-ay-isigiydi-saclarinda-ahmet-tevfik-ozan-228ow', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kederinden öldü dediler senin için 

Neler neler söylenmedi ardından..

Kan tükürdüğün gecelerden tut da

İçin için ağladığın günlere dek..

Sen ölmedin.. tükenmedi gözlerindeki sevinç

Tükenen ay ışığıydı saçlarında.. 

Saçlarını okşadığım geceler gelir birer birer..

Sabahı unutulmuş gurbet akşamlarında

Okşadığın çiçekler de birer birer öldüler

Sen ölmedin, ölmedin sen, sen ölmedin..

Tükenen ay ışığıydı saçlarında! ..', 'Kederinden öldü dediler senin için  Neler neler söylenmedi ardından.. Kan tükürdüğün gecelerden tut da İçin için ağladığın günlere dek.. Sen...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Tevfik Ozan']::text[], 8.5, '{"poet":"Ahmet Tevfik Ozan","poet_slug":"ahmet-tevfik-ozan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/tukenen-ay-isigiydi-saclarinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mayıs Çiçekleri', 'mayis-cicekleri-ahmet-tevfik-ozan-5a5tj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '‘‘Güneşli bir Mayıs günü, Eyüp Dayı ile Müşadiye’nin duvarı dibine oturduk..Kadın gardiyanın  yanında üç-beş yaşında iki kız, sessizce yanımızdan geçip duvar diplerinde boy atmış çiçekleri, çiçeklerin içinde kaybolarak toplamaya başladı.Ben kadın gardiyanın çocukları zannettim...Anlattılar ki: orda doğmuş. orada büyümüşler! ...’’

Sana Allah günah yazmaz, Küçük Kız! ...

Güvercinler bulutları incitmez! 

Kahbe hançer, kahbeliğin yapsa da

Bilir toprak, haksız yere kan içmez! ... 

Bir karış gökyüzü, bir avuç Güneş..

Burda, sevinçlerin hepsi kırıktır! 

Varsın çaylar soğuk soğuk satılsın

Isıtır yürekler, hepsi yanıktır! ...

Sen çiçeği koparmışsın Küçük Kız! 

Seni kimler koparmışlar, duydun mu? 

Baban Kur’an okuyorken köşede

Ana kucağında hiç uyudun mu? 

Bakma sen kor olup tutuştuğuna

Demir, anasından soğuk doğmuştur! 

Suçu yok Güneş’in, karanlıkların

Güneşi duvarlar burdan kovmuştur! ...



Bileğimde kor halinde bir demir

Kelepçe olsa da bu günah benim! 

Gökyüzünden Allah için bir emir

Yağmadan çekilen bütün ‘‘Ah’’ benim! ...

Sana Allah günah yazmaz Küçük Kız,

Güvercinler bulutları incitmez! 

Kahbe hançer, kahbeliğin yapsa da

Bilir toprak, haksız yere kan içmez! ...', '‘‘Güneşli bir Mayıs günü, Eyüp Dayı ile Müşadiye’nin duvarı dibine oturduk..Kadın gardiyanın  yanında üç-beş yaşında iki kız, sessizce yanım...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Tevfik Ozan']::text[], 8.5, '{"poet":"Ahmet Tevfik Ozan","poet_slug":"ahmet-tevfik-ozan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/mayis-cicekleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Molasız Yolculuk', 'molasiz-yolculuk-gulseren-onay-25ite', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu gün huzursuz ruhum

Hüznün en yoğunu

Süsleyebilir dizelerimi 

Yılgın düştüm 

Yaşamdan 

Nerde 

O eski günler 

İçimi ateşleyen 

O heyecan? 

Mola istedim 

Hakemden 

Dedi ki; 

Molasız yolculuktur 

Yaşam…

11/10/2005/ ANTALYA', 'Bu gün huzursuz ruhum Hüznün en yoğunu Süsleyebilir dizelerimi  Yılgın düştüm  Yaşamdan  Nerde  O eski günler  İçimi ateşleyen  O heyecan?  ...', ARRAY['Türk Edebiyatı','Şiir','Gülseren Onay']::text[], 8.5, '{"poet":"Gülseren Onay","poet_slug":"gulseren-onay","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/molasiz-yolculuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Medine Manzaraları', 'medine-manzaralari-ahmet-tevfik-ozan-y9gry', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Göklerde

Ve görünmez göllerde 

Yaşayan nilüferler 

Canlan sıkıldıkça 

Ansızın, tane tane 

Kayarlar gökyüzünden

Bu yüzden, damlaları 

Yağmurların burada 

Medine''de, bir tuhaf.. 

İri, saydam ve latif...

Farkı yok, bir annenin 

Hasret öpücüğünden..

Mavi:

Bir entaridir.. gök rengi, çıplak tende

Siyah:

Yalnız dişleri beyaz, çıplak tenli bir zenci 

Yaşanan bir romandır burda ''Mavi ve Siyah''

Tüten buhurdanların arkasında bir Tuğra

Bir buhur tüccarının andığı zamandır, O! 

Mescide-i Nebevî''(s.a.v) ye sinmiş bir gül kokusu 

Çöl ufkunda bir hayal.. Abdülhamid Han''dır, O! 

Göklerde

Ve görünmez göllerde

Yaşayan nilüferler...

Mescid-i Nebevî''(s.a.v) ye sinmiş bir gül kokusu..

Çöl ve çiçek.. Rabbim''im Kudret’iyle barışmış 

Buzdan bir saray olmuş, Ravza''da ''âvâre su..''', 'Göklerde Ve görünmez göllerde  Yaşayan nilüferler  Canlan sıkıldıkça  Ansızın, tane tane  Kayarlar gökyüzünden Bu yüzden, damlaları  Yağmurl...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Tevfik Ozan']::text[], 8.5, '{"poet":"Ahmet Tevfik Ozan","poet_slug":"ahmet-tevfik-ozan","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/medine-manzaralari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çakalname', 'cakalname-osman-velioglu-gvqlu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '........................................   Şairlik de, şiir de  alın sizin olsun..

...........................................Ben çakallığıma bakarım...

Ben çakalım, çakallığım tescilli,

Yalakalık mesleğine duçarım.

Lağımlarda beslenirim ezeli,

“Höt” deseler kıçı açık kaçarım.

Sinsiyimdir, kolay kolay görünmem,

Maskaram çok, öz maskeme bürünmem,

Şöhret için kıç yalarım, erinmem,

Yellenseler ben kendimden geçerim.

Bir cübbem var, bir de sarık takarım,

Yılan gibi her meclise akarım,

Karıştırır, kerevete çıkarım,

Keyiflenir, tütünümü içerim.

Kalleşliğin kitabını yazmışım,

Pençe pençe varlığımı kazmışım,

Nışadırım fazla geldi, azmışım,

Kimi görsem salya sümük biçerim.

Bir ustam var kurtla tilki kırması

İkiyüzlü, sahtekârlık arması,

Haz veriyor değerlere sarması,

O os..sa, ben don çözer s.çarım 

Benim gibi bulunmaz bu âlemde,

Dostlarımı silerim tek kalemde,

Efendimin adı zikir dilimde,

Peşi sıra okur, üfler, uçarım.

Şairlikmiş, güldürmeyin geriden,

Fırsat bulsam bal çalarım arıdan,

Bir tebessüm geliverse karıdan

Elimde şey, dağa delik açarım.

Erzincan’ım, can çiçeğim, alınma,

Bir çakalı besledim diye yanma, 

Velioğlu senin çocuğun amma,

Ben çakalım, yediğimi saçarım.', '........................................   Şairlik de, şiir de  alın sizin olsun.. ...........................................Ben çakallığım...', ARRAY['Türk Edebiyatı','Şiir','Osman Velioğlu']::text[], 8.5, '{"poet":"Osman Velioğlu","poet_slug":"osman-velioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/cakalname-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mektup', 'mektup-ahmet-tevfik-ozan-inf78', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Zaman, bir akrep gibi gönlüme aksın diye

Aldılar Anacığım, herşeyimi aldılar! ...

Eritilmiş bir kurşun denizinde herşeyim

Herşeyimi, ansızın alev aldı sandılar! 

Taş duvar, demir kapı, dünyadan kopmuş günler

Asırlık bir hasretle üstüme kapandılar..

‘‘...Ah anam, ah anam, ah iki gözüm

Gün gelir, gün geçer.. Allah büyüktür! 

Her ana taş basar bağrına bir gün.

Vatan borcu, namus borcu bir yüktür…”

Kar’ı düşer, yeşil çimen üstüne 

Şahini yel olur, düşman üstüne

Vatan bu, sevdalar sevdası bir şey

Çilesi gül olur, diken üstüne...

Sabah olur, akşam olur, gün batar

Kubbelerden damla damla nur akar 

Bizim gönlümüzde, üç çifte kayık

Bir batar, bir çıkar, bir yana yatar...

Gün gelir, gün geçer, Allah büyüktür! 

Her ana taş basar bağrına bir gün 

Vatan borcu, namus borcu bir yüktür! ...', 'Zaman, bir akrep gibi gönlüme aksın diye Aldılar Anacığım, herşeyimi aldılar! ... Eritilmiş bir kurşun denizinde herşeyim Herşeyimi, ansızın...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Tevfik Ozan']::text[], 8.5, '{"poet":"Ahmet Tevfik Ozan","poet_slug":"ahmet-tevfik-ozan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/mektup-106-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Namlular Çiçek Açsa', 'namlular-cicek-acsa-derya-aslan-b1yv9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '--------------------

''aşkta yarın yoktur sevgili'' ile başlamıştı şiir, evet yoktu belki oysa yarınlarda ümitle bekledi yüreğim. Ayrılığa o denli alıştıki bu yürek kavuşmaları bilmez olduk.Hesaba katmadığımız kendimizdik belki ''ayrılık'' değildi. 

.......................................................', '-------------------- ''aşkta yarın yoktur sevgili'' ile başlamıştı şiir, evet yoktu belki oysa yarınlarda ümitle bekledi yüreğim. Ayrılığa o d...', ARRAY['Türk Edebiyatı','Şiir','Derya Aslan']::text[], 8.5, '{"poet":"Derya Aslan","poet_slug":"derya-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/namlular-cicek-acsa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mezire''de Üç Şehit İçimizde Kafir Var', 'mezire-de-uc-sehit-i-cimizde-kafir-var-ahmet-tevfik-ozan-b2asb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '- Elhamdü Lillahi Rabbil Alemin...

‘‘- Lor peynürü, galın ekmek, duz getür

Çıh Harpud’un tepesinden buz getür

Şehidime örtü için bez getür

Gız, daliken devrülesin tez getür! ...’’

Ürek durmaz, gan gurumaz ruh ölmez

Buğdalardan başah başah saldurur

Nur-u Muhammed’den fermanımız var! 

Bu can, bin ölümü bile galdurur

Sara Hatun Camii’nde bir ezan 

Meleklerden taçlar gonmuş başına 

Dertler yağmur olsun, dermanımız var! 

Bin otağ gurarız mezar daşına

‘‘Çayda Çıra’’mızda üç alav düştü

Gakkoş, Allah kerim, Mevlam böyükdür! ...

Gandan ala kesmiş, ummanımız var! 

Gakkoş, Allah kerim, Mevlam büyüktür! 

.....................................................................

Mezire: Halk dilinde Elazığ', '- Elhamdü Lillahi Rabbil Alemin... ‘‘- Lor peynürü, galın ekmek, duz getür Çıh Harpud’un tepesinden buz getür Şehidime örtü için bez getür G...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Tevfik Ozan']::text[], 8.5, '{"poet":"Ahmet Tevfik Ozan","poet_slug":"ahmet-tevfik-ozan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/mezire-de-uc-sehit-icimizde-kafir-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üç Ayların İncisi', 'uc-aylarin-i-ncisi-ahmet-tevfik-ozan-lc2h0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'I

Rabbim Üç Aylar’a, Ayca nur vermiş..

Işığın raksı için, Alem’e billur vermiş

Gönlü billur, kılıcı nur, gözü kan 

Türk’ü İslam Bahçesi’ne sur vermiş! ...

II

Gün batmış, gece gitmez; bahtım kara neyleyim? 

Bir değil üç ay için: nice eyvah eyleyim? ! 

Yarabbi; üç ayları, rahmetinle nurlandır:

Bir yeşil rüya gibi, sana destan söyleyim! ...

III

Yarabbi; Kur’anın nuruyla yıka

Turan’ın bir karış toprağını da! ..

Bir nurdan sevinçle al canımızı

Ve yükselt Rüzgarın Bayrağı’nı da! ...', 'I Rabbim Üç Aylar’a, Ayca nur vermiş.. Işığın raksı için, Alem’e billur vermiş Gönlü billur, kılıcı nur, gözü kan  Türk’ü İslam Bahçesi’ne s...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Tevfik Ozan']::text[], 8.5, '{"poet":"Ahmet Tevfik Ozan","poet_slug":"ahmet-tevfik-ozan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/uc-aylarin-incisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Demokrasi Var Özlemin Bağrımızda', 'demokrasi-var-ozlemin-bagrimizda-kamil-soylemez-mw6pf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yüreğimde hüzne dair ne varsa

Ayaz gecelerin ardı sıra kattım

Dilime,dişime ismini rozet 

Suretini gözlerime gül diye taktım

Bir meşale yakıp,yollarına

Geceleri güne kattım

Sevenler takılıp,düşmesin diye

Yüreğimi sokok lambası

Bedenimi hain mermilere siper

Ömrümü sana yaktım

Tüm şüpheli gecelere pranga

İdam sehpalarına güller attım

Siz hey vatanperver  yiğitler

Gözyaşımı sellere kattıp

Meydanlarda türküler,marşlar 

Tiyatrolar yarattım

Olurda bir gün barış topraklarımda

Yok olarak kendi pisliğinde brjuva

Beyaz güvercinler uçuracağım sana

Rahat uyu sen kardeş toprağında

Biz çıktıkmı gerçek insanlık adına

Dönmek yoktur bir daha

Yüreğimizde sevda kardeşlik

Demokrasi var özlemin bağrımızda', 'Yüreğimde hüzne dair ne varsa Ayaz gecelerin ardı sıra kattım Dilime,dişime ismini rozet  Suretini gözlerime gül diye taktım Bir meşale yakı...', ARRAY['Türk Edebiyatı','Şiir','Kamil Söylemez']::text[], 8.5, '{"poet":"Kamil Söylemez","poet_slug":"kamil-soylemez","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/demokrasi-var-ozlemin-bagrimizda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Martının Çığlığı', 'bir-martinin-cigligi-murat-caglar-ak3p3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir çocuktan aldık gülücüğü biz, 

Bir sokak şarkıcısından ağlamayı. 

Hiçbir zaman kocaman bağıramadık. 

Geceyi yırtan sesimiz olmadı bizim. 

Kırılmadı ellerimizde gül dalları mor menekşeler. 

Nergisler de solmadı ellerimizde. 

Sadece kuşların kanadına aşk yazıp kaçıyordu ellerimiz. 

Ellerim ellerini değiyordu susarken. 

Nafile bir kaderin esiri değildi yüreğimiz, 

Esmer bir gecenin umudu. 

Umuttan yana unuttuğumuz bir dünyanın ortasındaydık ikimiz. 

İkimiz vardık, sadece ikimiz. 

Ne esen rüzgardan medet umardık, 

Ne de ay ışığından. 

Bir şiirlerimiz vardı avuçlarımızda. 

Bir de dualarımız dudaklarımızda. 

Gözünde denizin kokusu, ellerinde yüreğim. 

Yüzündeki tatlı pembelik, alıyor gözlerini benden. 

Ellerim ellerini değiyordu susarken. 

Hüzünlenince zor bir akşamın sabahı, 

Gözlerimiz kayardı ufuktan. 

Şarkılar söyleriz; hiç eskimez yüzümüz. 

Bir bahar solar şarkılarda, 

Bir deli rüzgar öper yüzümüzü, 

Çatlak dudaklarımızı bir biz. 

Hiç sevmedik ölümü biz. 

Hiç böyle yalnız da kalmadık. 

Solunca başka bir akşam hiç ağlamadık. 

Kor alev düşse de yanmadık. 

Ayaz vurmazdı yüzümüze. 

Biz güçlüydük. 

Güneşi anlat bana. 

Kanadına aşk yazıp kaçtığımız kuşları. 

Kırılan gül dallarını, 

Açmadan solan son geceyi. 

Esmer bir gece olsun avuçlarımızda. 

Serin bir seher vakti, 

Bir çay içimi dudaklarımızda yine aynı dua, 

Yüreklerimizde yine aynı umut. 

Şarkılar söyleriz aşktan yana, 

Ellerin avuçlarımda. 

Dudaklarımızda demli bir öpücük. 

Koca bir geceden beklediğimiz bir demet yıldız çiçeğiyse, 

Koca bir sabahtan beklediğimiz bir tutam umuttu. 

Hiç sevmedik ölümü biz, 

Hiç böyle yalnız da kalmadık. 

Ne esen rüzgardan medet umardık, 

Ne de ay ışığından. 

Bir şiirlerimiz vardı avuçlarımızda, 

Bir de dualarımız dudaklarımızda. 

Bir bahar solar gözlerinde, 

Bir gün batımı ufuktan, 

Bir martı çığlığı kopar yüreklerimizden 

Ve sonra yıkılışı hayatın umarsız. 

Aklımız almıyordu ölümü. 

Çok küçüktü aklımız ama, 

Koskocamandı yüreğimiz. 

Yumruk kadar da olsa koskocaman. 

Bir çocuktan aldık gülücüğü biz, 

Bir sokak şarkıcısından ağlamayı. 

Ağlasam sen de ağlar mısın bebeğim? 

Anlatsam bir daha dinler misin aşkımı? 

Dinlesem anlatır mısın aşktan? 

İstesem bir parça da bana vermez misin kara topraktan? 

Bir yürek kadardık ikimiz, bir dünya kadardı yüreğimiz. 

Bir çocuğun üşüyen yanaklarının pembeliğinden sor beni.', 'Bir çocuktan aldık gülücüğü biz,  Bir sokak şarkıcısından ağlamayı.  Hiçbir zaman kocaman bağıramadık.  Geceyi yırtan sesimiz olmadı bizim. ...', ARRAY['Türk Edebiyatı','Şiir','Murat Çağlar']::text[], 8.5, '{"poet":"Murat Çağlar","poet_slug":"murat-caglar","theme":"Türk Şiiri","is_hero":false,"total_lines":66,"source_url":"https://www.antoloji.com/bir-martinin-cigligi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Münacaat', 'munacaat-ahmet-tevfik-ozan-78amg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yâ İlahi ve ya Rabbi! .. sema, nur! 

Ne yıldızlar, ne zerreler; habersiz 

İsmin söyler, şanın yazar.. okunur! 

Semavatta, kim demiş ki; deveran 

Ve hareket.. zerrenin bir anlık titremesi 

Senin iznin olmadan gerçekleşsin, ne tuhaf! 

Kayan yıldızlar bile, izninle zaman zaman..

Yıldızlar, rüyalar gibi nazenin 

Işık ışık  bir tebessüm, bir lahza 

Bir şeyler söylüyor gibi gecede.. 

Ah bir gözüm görse, kulağım duysa! 

Ey zemin ve gökleri, yoktan yaratan Rabbim! 

Ufkunda seyyareler, fezanın; nokta nokta.. 

Hayal meyal seçilen uzak şehirler gibi 

Işıklara boğulmuş bir şeyler var, ufukda..

Aksa gözlerimden diyorum, Dünya..

Tenim zerre zerre savrulup uçsa.. 

İşte ölüm geldi, gördüm ve bildim! 

İlk uç nerelerde, bu hâl “SON UÇ''sa? 

Yağmurlar yağarken, kar savururken 

Aç, bitap topraklar ''Hayy'' ismine ram! 

İlk müjde, belki de daha erkenden 

İlk kar çiçekleri.. görmemek, haram! 

Gördüm, bildim artık; gözlerim nemli.. 

Her bahar; karların altında ölü 

Toprak, bir denize nur düşmüş gibi 

Renk renk çiçeklerle rakseder durur.. 

“Hayy'' isıni tecelli eder, örtülü! 

Seyreden gözlerde, bir damla yaştır 

Ve bir salâvattır.. ''Kainat Gülü''..

Bir acaib mahşer, şimdi hayâlde 

Titrek dudaklarda korku ve sükût.. 

Aynı yerde tenler, ruh başka yerde 

Yalnızca. Katında müjde ve umut! 

Günahlar diz boyu, bir ateş gölü 

Dokunduğu her yor erimiş demir.. 

Kor ateşe karşı Rabbimin Gülü 

Bir buzdan sarayın içinde midir? 

Gökler, feza, zemin bir cam kadehte 

Nurunla can bulan kat kat bir deniz.. 

Sahi, eksilen ne en son nefeste? 

Cesetler yerdeyken, bizler nerdeyiz? 

Ey Halik- ı Rahman, Ey Rabb-ı Rahim! 

 Ölü topraklara Nurun düşünce 

Ten bulan ruhların en acizi, biz! ..

Ecel rüzgârının savurduğu toz 

Ak olup saçlara,bir bir düşünce 

Bir düşünce alır, insanı sessiz...

Şu tohumlar, çiçekler.. aslı bir, evveli bir! 

Renk renk ışıklar gibi düşünce kudret eli 

Topraklardan fışkıran bin bir renk, bin bir eda, 

Her biri ayrı dünya.. ne tuhaf.. ne demeli? 

Ey Malik-i Yevmiddin! .. Ey O Gün’ün sahibi! 

Günahım, aczim bildim; belki dünyalar kadar.. 

Varsa bir güzellik ruhumda, senden! 

En gerçek bildiğim dostlar yanımda (!)

Yalnız, mesafemiz rüyalar kadar...

Mümkün mü, mümkün mü! .. Billah inanmam! 

Ezelî ebedî bir Dost, olsun da 

Dostun köleleri, ölümlü olsun! .. 

Dünya da bülbüller güle doysun da 

Nura aşık güller, örtülü olsun! 

İnandım, inandım.. ezel, ebed hak! 

Bildim, ecel; bir tebdil-i mekândır.. 

Ey Kadir-î Kayyûm.. Ey Rabb-i Rahim! 

Rahmetinle, gazabını utandır! ..

Ölüm geldi artık, renkler değişti.. 

Bir billur kadehte Cümle Kainat 

Çalınacak Kapı: Nur-ı Muhammed(s.a.v) 

Çalan  bir zavallı.. günahı kat kat! 

Ağlasam, dövünsem, çırpınıp dursam 

Bir başka  kapı yok..  başka  kapı yok! 

Yoklar denizinde boğulup kalsam 

Bu denizi kuşatmayan,yapı yok! 

Yarabbî Rahmet’in Gazab’ın geçmiş.. 

Bildim, sır; ecelden önce ölmekmiş! 

Yâ ilahi ve ya Rabbî! .. sema, nur! 

Ne yıldızlar, ne zerreler; habersiz 

İsmin söyler, şanın yazar.. okunur', 'Yâ İlahi ve ya Rabbi! .. sema, nur!  Ne yıldızlar, ne zerreler; habersiz  İsmin söyler, şanın yazar.. okunur!  Semavatta, kim demiş ki; deve...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Tevfik Ozan']::text[], 8.5, '{"poet":"Ahmet Tevfik Ozan","poet_slug":"ahmet-tevfik-ozan","theme":"Türk Şiiri","is_hero":false,"total_lines":79,"source_url":"https://www.antoloji.com/munacaat-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neler Neler', 'neler-neler-ahmet-tevfik-ozan-t89h9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Mutluluk,sepetlerden taşacak

Taşlar, toprağa batmayacak..

Her günkü haliyle, genç bir ihtiyar(!) 

Aydınlık yolları arşınlayacak..

Avuçlarımda, Güneş 

Nefeslerimde rüzgar olacak

Tas tas içtiğim sağlık 

Dudaklarımı ıslatacak..

Ağaçlar fışkıracak tepelerden

Otlar eskisinden yeşil olacak 

Bir bereket çökecek ki kadehlere

Hiçbiri dolmadan boşalmayacak', 'Mutluluk,sepetlerden taşacak Taşlar, toprağa batmayacak.. Her günkü haliyle, genç bir ihtiyar(!)  Aydınlık yolları arşınlayacak.. Avuçlarımd...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Tevfik Ozan']::text[], 8.5, '{"poet":"Ahmet Tevfik Ozan","poet_slug":"ahmet-tevfik-ozan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/neler-neler-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağaçlar Ve İnsanlar', 'agaclar-ve-i-nsanlar-alper-kuruk-rvfrl', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kıskanıyorum sizi ağaçlar 

Rahatlığınızdan ötürü,

Aldırdığınız yok hiçbir şeye.

Başınızda kavak yelleri eser bazan

İki inler durursunuz,

Ya bir dalınız kırılır

Ya da birkaç yaprağınız dökülür

Ümidinizi kesmezsiniz yeşermekten.

Kesseler birkaç yerinizden

Aşılandım der geçiştirirsiniz,

Kısacası memnunsunuz hâlinizden.

Biz insanlar öyle değiliz

Kılı kırk yararız biz insanlar.

Başımızda kavak yelleri esse

Fırtına kesiliriz.

Hem bizim aşılar sizinkilere benzemez

Biz; verem,tifo,çiçek,kuduz...aşısı oluruz

Ama tesir etmez aşı bize

Yine ölür,yine delirir,yine kudururuz

Aç kalacak olsak

Birbirimizi yeriz

Kendi kendimizi yeriz düşünceden.

Toprağımızla beslendiğinden

Bir huyun da bize çekmiş olsa gerek

Belki bu huy: yeşermektir,yeşermek...', 'Kıskanıyorum sizi ağaçlar  Rahatlığınızdan ötürü, Aldırdığınız yok hiçbir şeye. Başınızda kavak yelleri eser bazan İki inler durursunuz, Ya ...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/agaclar-ve-insanlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalan Anlattığım Hikaye Yalan', 'yalan-anlattigim-hikaye-yalan-ahmet-tevfik-ozan-0vgut', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Anladım, sevdiğim gözlerin değil

Yalan anlattığım bunca hikaye...

Ne sesin, ne elin, ne dudakların

Hepsi.. hepsi, duvar; bir başka şeye...

Gizli hasretliğim, onlarda şimdi

Saadet denizi onlarmış gibi...

Değil ruh çiçeğim, değil sevgilim

Hepsi yalan gibi birden eskidi! ...

Bir ölsen diyorum, şimdi ansızın

Ellerin çok durmaz avuçlarımda.

Gözlerin kapanır, ışığı söner

Dudağım can bulmaz, dudaklarında! ...

‘‘Yanında kalmak mı? ’’ bu ne kelime? ...

Ölümün taş duvar soğukluğunda! ...

Demek ki, değilmiş güzelliğinin

Kaynağı gözlerin, kor dudakların! ...

Aksine ölümün soğukluğunda

Kalbine bir hançer, aşıklarının! ...

Ey her zamanımın çiçeği, güzel! 

Sevdiğim, sevdiğim hiç sen değilsin! ...

Belki yücelerden bir esrarlı bir el

Sevdiğim, sevdiğim hiç sen değilsin! ...

Ve artık gönlümüz, bir çiçek gibi 

Bir ışık, bir güneş, bir nur aşkıyla

Topraktan, topraktan yana eğilsin! ...', 'Anladım, sevdiğim gözlerin değil Yalan anlattığım bunca hikaye... Ne sesin, ne elin, ne dudakların Hepsi.. hepsi, duvar; bir başka şeye... G...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Tevfik Ozan']::text[], 8.5, '{"poet":"Ahmet Tevfik Ozan","poet_slug":"ahmet-tevfik-ozan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/yalan-anlattigim-hikaye-yalan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saklamak Boşuna', 'saklamak-bosuna-ahmet-tevfik-ozan-qv9u6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gülsen kahkahalarla, ince hüznün bilirim

Dünyamız, aynalarla kaplı bir oda bizim...

Uzaklar yakınlarla, kahkahalar hüzünle

İç içe, anlaşılmaz... ben seni bilmez miyim? 

Günahı hayal meyal görmüşken, dokunmamış

Gözlerimiz ne mümkün, dalarken birleşmesin...

Ve taşmasın arzular, hülyalar gözümüzden

Gözyaşları akarken, yanakta birleşmesin? ..

‘‘Dağlar almış gitmiş başını göğe

Gökler ürkek ürkek vadiye inmiş

Uçurumlar tabanında kalmışım

Etrafımda yollar.. izler, silinmiş! ..’’

Şimdi beyaz yüzün, bir cam kâsede

Dokunsam kırılır, korkusuyla ben

Dalmış gözlerimle seyretmekteyim

Sonu yok rüyanın uykusuyla ben...

Dünyamız, aynalarla kaplı bir oda bizim...

Gülsen kahkahalarla, ince hüznün bilirim.', 'Gülsen kahkahalarla, ince hüznün bilirim Dünyamız, aynalarla kaplı bir oda bizim... Uzaklar yakınlarla, kahkahalar hüzünle İç içe, anlaşılma...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Tevfik Ozan']::text[], 8.5, '{"poet":"Ahmet Tevfik Ozan","poet_slug":"ahmet-tevfik-ozan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/saklamak-bosuna-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Salata', 'salata-ahmet-tevfik-ozan-5icin', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yağmurdan sonra güneş açınca

İçim içime sığmaz olur..

Ellerim ıslak çimenlerde dolaşır

Gözlerim, göklerin maviliğinde..

Ağzımda olmamış elmaların ekşiliği

Çocukluğumu hatırlarım..

Pırıl pırıl bir altın yağmurunda

Hatırlayamadığım, hatıralarım...

Ey, güzel günler için çırpınan insanlar! 

Mutluluğu, altın kaşıklı sofralarda aramayın! ..

Mutluluk, salatanın yeşilliğinde çırpınmakta

Mavi denizlerin derinliğinde...', 'Yağmurdan sonra güneş açınca İçim içime sığmaz olur.. Ellerim ıslak çimenlerde dolaşır Gözlerim, göklerin maviliğinde.. Ağzımda olmamış elma...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Tevfik Ozan']::text[], 8.5, '{"poet":"Ahmet Tevfik Ozan","poet_slug":"ahmet-tevfik-ozan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/salata-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duygunun Kar Kışına', 'duygunun-kar-kisina-huseyin-sigirtmac-fq760', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gözlerim yolda kaldı, sevenlerden haber yok.

Yalnızlıktan kurtulmam, etrafımda insan çok.

Hasretlik yordu beni, yüreği sardı merak.

Elim ermez göz görmez, yar şimdi hayli ırak.

Kiminle eğlenirsin, gayrı tutuş yan gönül.

Aşkla pervane olup efkarınla dön gönül.

Sana mesken olmuyor ne saray ne han gönül.

Elinden zara düştü, figanda bu can gönül.

Güzeller mimar olur harap gönül köşküne.

Bir derde deva değil, kaygı ömre boşuna.

Hasret motif olsa da her günümün başına.

Sığırtmaç tutsak yine duygunun kar kışına.', 'Gözlerim yolda kaldı, sevenlerden haber yok. Yalnızlıktan kurtulmam, etrafımda insan çok. Hasretlik yordu beni, yüreği sardı merak. Elim erm...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sığırtmaç']::text[], 8.5, '{"poet":"Hüseyin Sığırtmaç","poet_slug":"huseyin-sigirtmac","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/duygunun-kar-kisina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yapamadığım', 'yapamadigim-ahmet-tevfik-ozan-tkqbo', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Uzak dağlarını anlatacaktım, memleketimin 

Saçlarını Fırat’ ta yıkayacaktım! 

 İri, siyah gözlerine saatlerce

Sarhoş gibi bakacaktım...

Sen istemedin! ...

Sarhoş gibiysem masalarda, yapayalnız

Ve kör gibiysem geceleri...

Senden yana bakamıyorsam! 

Dudağından bir alev düşmüştür, gözlerime

Sen bilemedin! ...

Dünyam nelerle değişti, anlatamam

Neler duman duman savrulup gitti! 

Ve adına yazdığım şiirleri

Rüzgarlar ağaçlara dinletti...

Sen dinlemedin! ...', 'Uzak dağlarını anlatacaktım, memleketimin  Saçlarını Fırat’ ta yıkayacaktım!   İri, siyah gözlerine saatlerce Sarhoş gibi bakacaktım... Sen ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Tevfik Ozan']::text[], 8.5, '{"poet":"Ahmet Tevfik Ozan","poet_slug":"ahmet-tevfik-ozan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yapamadigim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz Uyanmak', 'sensiz-uyanmak-ahmet-tevfik-ozan-9watm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Uyanmak var ya, sensiz; yataklarda bir bilsen

Sanki gökler, bir kurşun buharıyla omzumda...

Ve ne tuhaf, gözlerim.. gözlerime bir nehir

Bağlansa, dolmayacak bir boşluk var başımda! ..

Aynası gözlerimin, gönlündedir bilirim..

Ruhuna sinmiş derim, dudağımın izleri! ..

Günahı hayal eder; utanır, irkilirim..

Kirletmek bize düşmez, derim; nur denizleri..

Bakma sen gönlüme, sitemi bitmez..

Ne hüznü eksilir, ne sana doyar! 

Bilmez ki, kor ateş hülyalarının

Yağmuru, bilinmez bir başka diyar..

Açılır perdeler, bir gün ansızın 

Bir hülya bitmeden, bir hülya başlar...

Uyanmak var ya, sensiz; yataklarda bir bilsen...', 'Uyanmak var ya, sensiz; yataklarda bir bilsen Sanki gökler, bir kurşun buharıyla omzumda... Ve ne tuhaf, gözlerim.. gözlerime bir nehir Bağl...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Tevfik Ozan']::text[], 8.5, '{"poet":"Ahmet Tevfik Ozan","poet_slug":"ahmet-tevfik-ozan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sensiz-uyanmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sırat Yolunda', 'sirat-yolunda-arzu-gulucudur-96fm6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Soğuk  baharın, yıkıcı ayazında 

Vuruldu gönlüm

Namlunun ucunda ömrüm...

Silahımda tek kurşun! 

Tek nişan...

Tek hiza...

Yerle bir bulut

Gök dibinde yerin...

Günahlarım bir bir şakağımda

Mıh gibi...

Nan gibi...

''Ye''sindeyim...geri dönüşü yok

Yangın yeri mahşer kalabalık...

Ne fayda! 

Yalnızım...

Bir günahım yanıbaşımda

Elim fersiz....

Yüzüm kara

Varamam huzura! 

Söylenecek kelimeleri çoktan tükettim

İnce bir sırat var önümde

Sağım solum yaban

Önüm engel...

Arkam günah...

Sonum çukur...

KURTAR NE OLUR 

KURTAR NE OLUR

Not: Ye''s kelimesi şiirde ''Ölüm anında gelen pişmanlık'' manâsında kullanılmıştır.', 'Soğuk  baharın, yıkıcı ayazında  Vuruldu gönlüm Namlunun ucunda ömrüm... Silahımda tek kurşun!  Tek nişan... Tek hiza... Yerle bir bulut Gök...', ARRAY['Türk Edebiyatı','Şiir','Arzu Gülücüdür']::text[], 8.5, '{"poet":"Arzu Gülücüdür","poet_slug":"arzu-gulucudur","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/sirat-yolunda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sırlar Çiçeği', 'sirlar-cicegi-ahmet-tevfik-ozan-4qsx3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Açsam gözlerimi: ben içindeyim..

Kapatsam gözümü: Dünya içimde! 

Bu sır, kahredecek garip başımı

Her şey, bir şey amma başka biçimde! ...

‘‘La İlahe İlla’llah’’ tır canımda

Kanımda dolaşan sırlar çiçeği! ..

Çiçekler mi aşık etmiş kendine

Yaprak yaprak aşk arayan böceği? ! ...

	‘‘Şehidimsin, bayrağımsın, yüceler

Yücesi yerlerde bir deli rüzgar..

Delerse yüreği, delsin kurşunlar..

Kurşunları, kurşunlayan eller var! ...

Açsam gözlerimi: ben içindeyim..

Kapatsam gözümü: Dünya içimde! 

Bu sır, kahredecek garip başımı

Her şey, bir şey amma başka biçimde! ...', 'Açsam gözlerimi: ben içindeyim.. Kapatsam gözümü: Dünya içimde!  Bu sır, kahredecek garip başımı Her şey, bir şey amma başka biçimde! ... ‘‘...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Tevfik Ozan']::text[], 8.5, '{"poet":"Ahmet Tevfik Ozan","poet_slug":"ahmet-tevfik-ozan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sirlar-cicegi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarım Günlük Bir Saadet', 'yarim-gunluk-bir-saadet-ahmet-tevfik-ozan-0uvd0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben aylarca, şu ranzada; güneş doğunca uyurum

‘‘Güneşle adam asmazlar! ...’’ yarım günlük bir saadet! 

Her gece yatsıyla gelen, bir soğuk şey duyuyorum

‘‘Abdest al, güneşi bekle! ...’’ böyle aylarca devam et! ...

Suçum olsa, biliyorum; öpmez alnımdan melekler

Ve gözyaşlarıma konmaz o nurani kelebekler

Bu soğuk sessizlik te ne? ... Ve niçin ana hasreti? 

Niçin adım kimse bilmez? Hem nereden bilecekler? ! ...

Ses de, sükut da burada; hep ölümü hatırlatır.

Gelsin ‘‘Baş üzre yeri var! ..’’ ve fakat beklemek, bir tuhaf…

Yüreğini şu tavanın, bilmem ki, kimler kanatır? 

Ve niçin ateş perdeler, göz bebeklerimde saf saf? 

‘‘Bir güvercin bir balık nasıl masum ölürse

Nasıl çatlarsa bir nar, cennetten bir tad için

Gelsin Ölüm, Yüceler Yücesi Rabbimiz’den

Yaşanmaz, anlatılmaz bir yeşil murad için! ...’’

Ben aylarca, şu ranzada; güneş doğunca uyurum

‘‘Güneşle adam asmazlar! ...’’ yarım günlük bir saadet! 

Her gece yatsıyla gelen, bir soğuk şey duyuyorum

‘‘Abdest al, güneşi bekle! ...’’ böyle aylarca devam et! ...', 'Ben aylarca, şu ranzada; güneş doğunca uyurum ‘‘Güneşle adam asmazlar! ...’’ yarım günlük bir saadet!  Her gece yatsıyla gelen, bir soğuk şe...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Tevfik Ozan']::text[], 8.5, '{"poet":"Ahmet Tevfik Ozan","poet_slug":"ahmet-tevfik-ozan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yarim-gunluk-bir-saadet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Kuşlar', 'son-kuslar-ahmet-tevfik-ozan-wqzpb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yağacak, belli artık; hüznün ürkek kuşları

Kurtulmuş kurşun gibi, semanın tavanından..

Gözler içmiş olacak, sonu yok yokuşları

Ve toprak, bir pencere; açılmış kucağından! ...

Karanfiller, zambaklar, duru göl, bir şelale...

Bir esrarlı rüya bu, ne içinde toprağın

Ne dışında belli ki; sır, hakikat elele! 

Çiçekleri hakikat, kendi hayal yaprağın...

Taşmıyor ne gariptir; denize doldursa nur

Nur mu deniz içinde, deniz mi nur içinde? 

Balıkların sevinci,  pullarından okunur; 

Gözyaşları gizlenmiş bir esrarlı ‘‘niçin’’de...

‘‘...Evet, ağlasa insan; gözyaşı damla damla 

Sıcak inciler gibi, yanaklardan süzülür..

Gözyaşı, balıkların; kesilmez pınar gibi

Aksa, dursa yıllarca; semaya mı dökülür? ...”

Yağacak, belli artık; hüznün ürkek kuşları

Kurtulmuş kurşun gibi, semanın tavanından..

Gözler içmiş olacak, sonu yok yokuşları

Ve toprak, bir pencere, açılmış kucağından!', 'Yağacak, belli artık; hüznün ürkek kuşları Kurtulmuş kurşun gibi, semanın tavanından.. Gözler içmiş olacak, sonu yok yokuşları Ve toprak, bi...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Tevfik Ozan']::text[], 8.5, '{"poet":"Ahmet Tevfik Ozan","poet_slug":"ahmet-tevfik-ozan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/son-kuslar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sona Doğru', 'sona-dogru-ahmet-tevfik-ozan-m9dko', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Üstad Necip Fazıl’ın 

Aziz hatırasına...

Birşeyler oluyor, belli; ne desem? 

Ne desem; güneşin, yaprağın, ayın

Rengini çalana,.. sade bir sitem! 

Bir tek kapısı yok, bin bir sarayın! ...

Gönlüm, ötelerden bir haber bekler

Kurumuş dudağım, bir söze hasret

Her sabah bir deniz çarpsa yüzüme:

Sanki susuzluğa bir emir: ‘‘....Kahret! ...’’

Sonra nurdan bir pencere, gecede..

Geçebilsem: yeşil-mavi bir çiçek

vaat edilmiş.. O mukaddes hecede:

SON-SUZ-LUK! ... sırrını kimler çözecek? ...

‘‘Dişimle ezdiğim incir tohumu

Ağaç olsa düşse, evimi yıkar! ..

Bu esrarlı bilmeceyle ruhumu 

Bir nura döndürdüm, ateşi yakar! ...’’

Bir şeyler oluyor, belli; ne desem? 

Ne desem; güneşin, yaprağın, ayın

Rengini çalana, sade bir sitem! ..

Bir tek kapısı yok, bin bir sarayın! ...', 'Üstad Necip Fazıl’ın  Aziz hatırasına... Birşeyler oluyor, belli; ne desem?  Ne desem; güneşin, yaprağın, ayın Rengini çalana,.. sade bir si...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Tevfik Ozan']::text[], 8.5, '{"poet":"Ahmet Tevfik Ozan","poet_slug":"ahmet-tevfik-ozan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sona-dogru-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tarih Düşülecek Hira Mektubu', 'tarih-dusulecek-hira-mektubu-ahmet-tevfik-ozan-n1ri2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Zemini, Mekke; Dağ’ın 

Adı: Nur! . Cebel-i Nur! 

Sahilinde Zaman’ın; 

Dalgalar, doksan ikiyi vurur...

Bir gurup vakti, günahkar 

Acz-i mutlak, çaresiz.. 

Hira''ya komşu mekânda 

Bir Garip Şair oturur...

Mevsim-i Hac geçer.. 

Yıl geçer, dalgalar susar

Bir Fatiha öncesi boy atmış 

Bir Eylül günü, sessizce 

Bir yürek durur...

Ve zaman ve mekân; söz ve tefekkür 

Elenir, toz olur, biter, savrulur! 

''İnnâ lillahi ve innâ ileyhî raciun''', 'Zemini, Mekke; Dağ’ın  Adı: Nur! . Cebel-i Nur!  Sahilinde Zaman’ın;  Dalgalar, doksan ikiyi vurur... Bir gurup vakti, günahkar  Acz-i mutla...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Tevfik Ozan']::text[], 8.5, '{"poet":"Ahmet Tevfik Ozan","poet_slug":"ahmet-tevfik-ozan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/tarih-dusulecek-hira-mektubu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Soramadığın', 'soramadigin-ahmet-tevfik-ozan-d23ku', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Haksız yere dövülmüş bir çocuktum, dün gece

İç çeke çeke düştüm, yataklara; ağladım...

Soğuk duvarlar emdi, sıcak göz yaşlarımı

Haksız yere dövülmüş, bir çocuktum dün gece.

Aktı, gözlerimden; aktı, sokaklar..

Şehirler küçüldü, evler büyüdü.

Kapılardan taşdı, öksüz çocuklar.

Deniz, bir yerlerden arza yürüdü...

Uzaklarda, sevda; bir sarı yıldız

Işığını bölük pörçük gönderir...

Baharlara rüya kadar uzağız..

Dert başağı, bir taneye bin verir! ..

‘‘Değer mi, değer mi? ...’’ derken aynalar

‘‘Çizgi çizgi yüzündeki günahın 

Birine, gecenin bu matem hali? ...’’

Anladım, çektiğim hep senin ahın! ...

Aczim günahımı aştı bu gece

Tenim toprak toprak uçuştu gitti

Bir sırlı şaraba dokundu dilim

Şarap mı, gece mi..ömür mü, bitti? ! ...

Belki bin kere mahçup, bir çocuktum dün gece...', 'Haksız yere dövülmüş bir çocuktum, dün gece İç çeke çeke düştüm, yataklara; ağladım... Soğuk duvarlar emdi, sıcak göz yaşlarımı Haksız yere ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Tevfik Ozan']::text[], 8.5, '{"poet":"Ahmet Tevfik Ozan","poet_slug":"ahmet-tevfik-ozan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/soramadigin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şehidin Türküsü', 'sehidin-turkusu-ahmet-tevfik-ozan-sxhq0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir kurşun, bir kurşun, bir kara kurşun...

Şakağımda sıcaklığın duyduğum! ..

Ansızın, dalgası nurdan bir deniz

Ve Allah! ... ‘‘Adına, kurban olduğum! ’’

	‘‘Sarı saçlım yasta mıdır? 

	Rüyaları hasta mıdır? 

	Kan tükürsem, ciğer gelir..

	Zemzem, kurşun tasta mıdır? ! ’’

Türk’üm: deryalara sığmaz bir nehir..

Başım Hak Yolu’na koymuş giderim! 

Taşı cevher, dalgası kan; yürek pare ne çare? 

Dünya sefasına doymuş giderim! ...

Giderim, giderim.. bir Kızıl Elma! 

Nur-ı  Muhammed’(s.a.v) den kokusun almış! ...

Yıkıl bre, sefasına yandığım

Yalan Dünya, üzerinde kim kalmış? ! ...

	‘‘Sarı saçlım yasta mıdır? 

	Rüyaları hasta mıdır? 

	Kan tükürsem, ciğer gelir..

	Zemzem, kurşun tasta mıdır? ! ’’', 'Bir kurşun, bir kurşun, bir kara kurşun... Şakağımda sıcaklığın duyduğum! .. Ansızın, dalgası nurdan bir deniz Ve Allah! ... ‘‘Adına, kurban...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Tevfik Ozan']::text[], 8.5, '{"poet":"Ahmet Tevfik Ozan","poet_slug":"ahmet-tevfik-ozan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sehidin-turkusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Talas''ta Bir Gece', 'talas-ta-bir-gece-ahmet-tevfik-ozan-ptr3o', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Talas’ta, gecenin kucağında ben

Yorgunum, bir asır ayakta durmuş

Gibiyim, gözümde uyku tüterken..

Elimde, hülyalar... çiçeği solmuş..

Atmacalar döne döne alçalır

Ümit serçesinde takat ne gezer? 

Uçuşan tüylerden başka ne kalır? 

Çırpmaya, göklere; kanat ne gezer? 

Sükut, Erciyes’ten süzülür iner..

Atmacalar kursağında yüreğim

Uzanır göklere, korkuyla siner

Kelepçeye perçinlenmiş bileğim..

Beynimde insafsız bir kanlı hançer

Bir tek saniyeyi boşa vermeden 

Bir iner, bir kalkar günü katleder

Tutuşur yatağım, gece gelmeden...

Ve fakat, ecelle bir gün ansızın

Huzur ‘‘tak! .. tak! ..’’ çalar, kapımı sessiz..

Yalın ayağına bakılmaksızın

Sahralara biri düşer, kimsesiz...

Sahralar... kumları, insan kafası

Bir adım binlerce feryat getirir

‘‘Yalnız Nur-i İman dindirir yası

Nur-ı Muhammedi(s.a.v) , azab bitirir...’’

             Talas’ta, gecenin kucağında ben

Yorgunum, bir asır ayakta durmuş

            Gibiyim, gözümde uyku tüterken..

            Elimde, hülyalar... çiçeği solmuş..', 'Talas’ta, gecenin kucağında ben Yorgunum, bir asır ayakta durmuş Gibiyim, gözümde uyku tüterken.. Elimde, hülyalar... çiçeği solmuş.. Atmaca...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Tevfik Ozan']::text[], 8.5, '{"poet":"Ahmet Tevfik Ozan","poet_slug":"ahmet-tevfik-ozan","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/talas-ta-bir-gece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitmek Gerekir Bazen', 'gitmek-gerekir-bazen-volkan-yoruc-ldxo7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gitmek gerekir bazen

Geri dönmeden

Israrla gidercesine

Son bir sözden bile ihmalkar edercesine

Gitmek gerekir bazen

Veda ederken ağlamadan 

Yüreği sızlatmadan

Geriye bakmadan

Sesini dahi duymadan

Gitmek gerekir bazen

Son sözü bile söylemeden

Hep ardında bırakılanlardan olmadan

Hep elvedayı duymadan

Bir kez de geriye dönmeksizin 

Gitmek gerekir ardına bile bakmadan', 'Gitmek gerekir bazen Geri dönmeden Israrla gidercesine Son bir sözden bile ihmalkar edercesine Gitmek gerekir bazen Veda ederken ağlamadan  ...', ARRAY['Türk Edebiyatı','Şiir','Volkan Yoruç']::text[], 8.5, '{"poet":"Volkan Yoruç","poet_slug":"volkan-yoruc","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/gitmek-gerekir-bazen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitme', 'gitme-necati-keceli-kr2zd', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gitme güzel gitme/ hüzün dolar kalbe

    Sensiz kalbim yanar, gözlerim ıslanır

    Terk eder gidersen, ilaç olmaz derde

    Şu ömür son bulur, toprağa yaslanır

    Gitme güzel gitme/ bulut çöker başa

    Sen çeker gidersen, zehir katar aşa

    Ben henüz gelmeden daha on beş yaşa

    Bu aşk sevgi kara toprağa saklanır

    Gitme güzel gitme/ yazık olur bana 

    Beden hasta düşer,dertler girer kana

    Bu sevda içinde, ölüm gelir cana

    Aşkım sevgim kalpte,yanarak aklanır

    Gitme güzel gitme/ göz görmez dünyayı

    Sen yoksan içinde, versen han sarayı

    Cansız bedenim ne yapsın pul parayı

    Senin aşkın için, can olur şahlanır

     Necati KEÇELİ

     ADANA', 'Gitme güzel gitme/ hüzün dolar kalbe     Sensiz kalbim yanar, gözlerim ıslanır     Terk eder gidersen, ilaç olmaz derde     Şu ömür son bulu...', ARRAY['Türk Edebiyatı','Şiir','Necati Keçeli']::text[], 8.5, '{"poet":"Necati Keçeli","poet_slug":"necati-keceli","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/gitme-131-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güz', 'guz-volkan-yoruc-i790i', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Güz bir hüzünden kopan ağrıdır sanki

Erişir yalnız yüreklere

Yapraklar kadar sararmış gönüllerden gelen

Güz bir cevaptır sevgilere

Sağlık olsun unutanlara

Geçmiş olsun unutulanlara

Elbet devrandan eserde geçer yeller

O güz ki bir umuttur sevdalara', 'Güz bir hüzünden kopan ağrıdır sanki Erişir yalnız yüreklere Yapraklar kadar sararmış gönüllerden gelen Güz bir cevaptır sevgilere Sağlık ol...', ARRAY['Türk Edebiyatı','Şiir','Volkan Yoruç']::text[], 8.5, '{"poet":"Volkan Yoruç","poet_slug":"volkan-yoruc","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/guz-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Reşaranî Şiir ve Beyitsiler 41', 'resaran-siir-ve-beyitsiler-41-huseyin-avdic-fns67', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sıra Bize Geliyor

İniyorlar, biniyorlar; 

Gidiyorum birlikte

Yolcuyuz bir yere

Uzay gemisi Dünya ile.

Doğumla binip,

Ölümle iniyorlar.

İniş sırası gelmek üzere,

Birer birer hepimize.

******

Dirilerin Gideceği Yer

Ölüler, diriltilecekleri günü beklerler.

Diriler, bir bir ölüp, mahşer gününe giderler.

******

Okuduk Da Ne Olduk? 

Okuduk okuduk ne olduk? 

Alim olduk, bilgin olduk! 

Bilgin olduk ne olduk? 

Cahillere üstün olduk! 

******

Şeytanın Egemenliğini Yok Et Allah''ım! 

Senin içiniz ya Rab! Bizde Senliği hakim kıl.

Şeytanın egemenliğini de yok et, akim kıl.

Berlin, Ekim 2005.', 'Sıra Bize Geliyor İniyorlar, biniyorlar;  Gidiyorum birlikte Yolcuyuz bir yere Uzay gemisi Dünya ile. Doğumla binip, Ölümle iniyorlar. İniş ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Avdic']::text[], 8.5, '{"poet":"Hüseyin Avdic","poet_slug":"huseyin-avdic","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/resarani-siir-ve-beyitsiler-41-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Yoksun (Attilâ İLHAN''a)', 'sen-yoksun-attil-i-lhan-a-ferit-agca-0spdc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '''Ben sana mecburum bilemezsin'' (*) 

Diye başladı çocukluk aşkım.

Önümde sevdan, aklımda mıh,

Büyüdükçe büyüyor, şiirlerin

İçimde bir çığ.

İstanbul suskun, eskisi değil.

Fatih''te gramofon açık değil.

Sonra başladı sohbetlerimiz,

Konuştukça dinlediğim,

Dinledikçe konuşulan.

Bir ömrü sergileyen.

Şapkaların taşıdığı hayat yükünü,

Seninle sende bütünleşen.

''Ne yapsam, ne tutsam, nereye gitsem

Ben sana mecburum sen yoksun''(*)

                        (*)   Attilâ İLHAN Ben Sana Mecburum şiiri', '''Ben sana mecburum bilemezsin'' (*)  Diye başladı çocukluk aşkım. Önümde sevdan, aklımda mıh, Büyüdükçe büyüyor, şiirlerin İçimde bir çığ. İs...', ARRAY['Türk Edebiyatı','Şiir','Ferit Ağca']::text[], 8.5, '{"poet":"Ferit Ağca","poet_slug":"ferit-agca","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sen-yoksun-attila-ilhan-a-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karar ver.', 'karar-ver-adnan-gordum-es7lc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Karar ver artık; 

Ya varsındır,

Ya yoksundur.

Varmışsın gibi davranıp,

Yokluğunla üzme beni..', 'Karar ver artık;  Ya varsındır, Ya yoksundur. Varmışsın gibi davranıp, Yokluğunla üzme beni.....', ARRAY['Türk Edebiyatı','Şiir','Adnan Gördüm']::text[], 8.5, '{"poet":"Adnan Gördüm","poet_slug":"adnan-gordum","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/karar-ver-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Avucumda Karanlık', 'avucumda-karanlik-nurcemal-ozturk-brk8d', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Avucumda karanlık yüreğimde sen

Yüreğim bana yeter çekilip gitsen

Korkmuyorum artık sensiz kalmaktan

Ha sensiz kalmışım ha yanımda sen.

Varsın gece olsun,doğmasın güneş

Isıtır yüreğimi,yaktığın ateş

Senle geçen günüm sensizliğe eş

Ha sensiz kalmışım ha yanımda sen.

Gündüz urgan olsa geceler düğüm

Sen değilsin düşlerimde gördüğüm

Sen ettin gönlümü böyle kördüğüm

Ha sensiz kalmışım ha yanımda sen.

Yıkılır zannettin yıkılmadım ben

Sensiz gecelerden sıkılmadım ben

Bayram ettim senden ayrıldığım gün

Ha sensiz kalmışım ha yanımda sen.', 'Avucumda karanlık yüreğimde sen Yüreğim bana yeter çekilip gitsen Korkmuyorum artık sensiz kalmaktan Ha sensiz kalmışım ha yanımda sen. Vars...', ARRAY['Türk Edebiyatı','Şiir','Nurcemal Öztürk']::text[], 8.5, '{"poet":"Nurcemal Öztürk","poet_slug":"nurcemal-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/avucumda-karanlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Irakta çocuk olmak', 'irakta-cocuk-olmak-hidayet-onat-8szac', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Umutlarını sıvamış çocuk,

Sıvanmasın akran kanı diye,

Paçalarına,

Yaşamın yaşayan kıyısına

Geçebilmek için

Sıvanmış.

Oynamak istiyor çocuk

“şeker de yiyebilmek”,

Okul yolunda, 

Top oynamak, 

Toza toprağa karışarak, 

Kurşunlara karışmadan 

Umutları...

Çocuk gülüşlere 

Koşmak istiyor çocuk,

Uçurtma yapmak,

Mavi gökyüzünde kırlangıç olmak,

Kanadı kırılmadan

Yüreğinin..

Anasının çığlığını 

Seçiyor çocuk

Kurşun seslerinin içinden.

Umut suskun

Umut işgal altında

Zulüm;  Kaf dağı

Şefkati vurulmuş kadının

Kucağından kurşun geçmiş,

Çocuk ağlıyor, 

Çocuk aç,

Kan akıyor anasının, 

Memelerinden..

Taş atıyor çocuk

Baharına kurşun atana...

......Sevgili Irak bebelerinin kara gözlerinden öpüyorum..', 'Umutlarını sıvamış çocuk, Sıvanmasın akran kanı diye, Paçalarına, Yaşamın yaşayan kıyısına Geçebilmek için Sıvanmış. Oynamak istiyor çocuk “...', ARRAY['Türk Edebiyatı','Şiir','Hidayet Onat']::text[], 8.5, '{"poet":"Hidayet Onat","poet_slug":"hidayet-onat","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/irakta-cocuk-olmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zehir', 'zehir-esra-nour-btzzj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aklıma düştün güzel gözlü yine 

Uykularım bölünür oldu 

gecem günüm seninle

gitmem gidemem bu şehirden 

bu  garip  gönlüm sende

fırtınalar kopuyor gönlümde

adın su gibi dilimde

beni yık öldür bir sözünle 

elinden olunca olunca 

yaşamakda güzel ölümde 

gel desem herşeyi bırakıp 

gelirmiydin güzel gözlü benimle

inan olmazdı senden başkası 

ne gözde ne gönülde nede serde', 'Aklıma düştün güzel gözlü yine  Uykularım bölünür oldu  gecem günüm seninle gitmem gidemem bu şehirden  bu  garip  gönlüm sende fırtınalar k...', ARRAY['Türk Edebiyatı','Şiir','Esra Nour']::text[], 8.5, '{"poet":"Esra Nour","poet_slug":"esra-nour","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/zehir-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karlı Dağ', 'karli-dag-meram-yalinizoglu-r9nv9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ak sakallı,

Nur yüzlü dede gibi.

Dili olsa konuşacak,

Eli olsa saracak dağlar! 

Seviyorum, Özlüyorum O''nu

Yarıya kadar bulanmış

Beyazlara bürünmüş

Karlı dağlar

Bekliyorum, bekleyeceğim O''nu...', 'Ak sakallı, Nur yüzlü dede gibi. Dili olsa konuşacak, Eli olsa saracak dağlar!  Seviyorum, Özlüyorum O''nu Yarıya kadar bulanmış Beyazlara bü...', ARRAY['Türk Edebiyatı','Şiir','Meram Yalınızoğlu']::text[], 8.5, '{"poet":"Meram Yalınızoğlu","poet_slug":"meram-yalinizoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/karli-dag-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mesaj Sevgi', 'mesaj-sevgi-ali-olcars-facp2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'M-analar önemlidir anlatılmak istenen.

E-lem keder çile veya sevgidir iletilmek istenen.

S-abahın değeri gece çökünce bilinir.

A-nlatılan asıl manada gizlidir.

J-andarmalar sokak sokak gezerler.

S-abah akşam suçlu peşine düşerler.

E-trafına bir bak hergün ayrı bir suç işlenir.

V-elhasıl jandarmayla olmaz bu iş kalplerde çözümlenir.

G-ayeli çalışıp insanların kalbine sevgi ekmelisin.

İ-çindeki sevgiyle kötülükleri yok edersin.', 'M-analar önemlidir anlatılmak istenen. E-lem keder çile veya sevgidir iletilmek istenen. S-abahın değeri gece çökünce bilinir. A-nlatılan as...', ARRAY['Türk Edebiyatı','Şiir','Ali Olcars']::text[], 8.5, '{"poet":"Ali Olcars","poet_slug":"ali-olcars","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/mesaj-sevgi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kartlar…', 'kartlar-ahmet-toper-aft94', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kuralını boz son kez

Hayata oyna kartlarını 

Son elde kazanmayı bir dene

Çıkmaz kumarın karanlık masasında

Ağır çekimde sıyırsın yeşil örtüsünü

Kartların…

Bir kartı geçmişe adananlara

Bir kartı geleceğe soyunanlara

Son kartı şu ana dair yaşananlara salla gitsin

Kuralını boz son kez desem de

Sigara dumanına yap hileni

Şu çekilmez hayatın altından bir kart uzat bana

Aman kimse görmesin sırrımızı

Kimse tatmasın zevkimizi

Sadece hayata oyna

Dağıt kartlarını…

Kupa kızı geçmişe adananlara

Maça rua geleceğe kaçanlara

Son as ise şu anda yaşananlara', 'Kuralını boz son kez Hayata oyna kartlarını  Son elde kazanmayı bir dene Çıkmaz kumarın karanlık masasında Ağır çekimde sıyırsın yeşil örtüs...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Toper']::text[], 8.5, '{"poet":"Ahmet Toper","poet_slug":"ahmet-toper","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/kartlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Varsın', 'sen-varsin-meram-yalinizoglu-tu840', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen varsın

                 Yağan her yağmur damlasında

                  Esen her ılık rüzgarda

                  Özlem dolu hüzünlü tüm şarkılarda

Sen varsın Birtanem

Sen varsın

                 Baktığım her noktada

                 Duyduğum her güzel sözde

                 Aldığım her nefeste

Sen varsın Birtanem

Sen varsın

                 Yazılan aşk hikayelerinde

                 Parlayan güneşte

                 Ağaçta ötüşen kuş seslerinde

                 Meyva vermiş ağaçta

Sen varsın Birtanem', 'Sen varsın                  Yağan her yağmur damlasında                   Esen her ılık rüzgarda                   Özlem dolu hüzünlü tüm şa...', ARRAY['Türk Edebiyatı','Şiir','Meram Yalınızoğlu']::text[], 8.5, '{"poet":"Meram Yalınızoğlu","poet_slug":"meram-yalinizoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sen-varsin-45-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönlümde Akşam Oldu', 'gonlumde-aksam-oldu-i-lknur-er-mv477', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gönlümde akşam oldu

Vakitsiz çöktü sensizlik üzerime

Dilim, dilim bölünüyorum 

Parçalanıyor bedenim

Ya hep gel

Ya da sonsuza dek git hayatımdan

Köşe başlarında bekletme beni

Yüreğim ağzımda kapıları gözletme

Ya bileyim ki geleceksin bayramlar edeyim

Ya da bileyim ki yoksun gözlerimi kapılardan çevireyim

Dört duvar içinde sensiz kalan bu canı

Heba edeyim', 'Gönlümde akşam oldu Vakitsiz çöktü sensizlik üzerime Dilim, dilim bölünüyorum  Parçalanıyor bedenim Ya hep gel Ya da sonsuza dek git hayatım...', ARRAY['Türk Edebiyatı','Şiir','İlknur Er']::text[], 8.5, '{"poet":"İlknur Er","poet_slug":"i-lknur-er","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gonlumde-aksam-oldu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizlikte diktiğim çiçekler yeşerdi', 'sensizlikte-diktigim-cicekler-yeserdi-i-lknur-er-joojh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sensizlikte diktiğim çiçekler yeşerdi

Saksılara sığmaz oldu menekşeler

Renk, renk açıyorlar senin için

Geleceğin içlerine doğmuş olsa gerek

Beni de uyandırdılar uykumdan

Yeniden boyadım pencereleri

Yemek takımlarını çıkarttım dolaptan

Sandıktaki kıyafetlerimi havalandırdım

Aynaya baktım birde

Gözlerimdeki ışığa ben bile inanamadım

Yüreğim nasıl susamış heyecana

Takvim yaprağına not ettim 

24 nisanda geleceksin bana

Armağanı olacaksın sonsuz sabrımın

Yüreğimin tek sahibi

Kapılar sonuna kadar açık içeriye hemen gir

Bekleme sakın

Bir an daha dayanamam sensizliğe

Tenine uzanırda dokunamam 

Doyamam sarmalara seni

Mis kokunu kıskanır da menekşeler

Yinede dönüp bakmam yüzlerine

Bilirim onlarda sever seni

Ben gibi 

Bir yaprak daha koparttım takvimden

Sabaha rüyalarımdan çıkacaksın

Kollarıma koşacaksın

Biliyorum', 'Sensizlikte diktiğim çiçekler yeşerdi Saksılara sığmaz oldu menekşeler Renk, renk açıyorlar senin için Geleceğin içlerine doğmuş olsa gerek ...', ARRAY['Türk Edebiyatı','Şiir','İlknur Er']::text[], 8.5, '{"poet":"İlknur Er","poet_slug":"i-lknur-er","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/sensizlikte-diktigim-cicekler-yeserdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Açelya', 'acelya-osman-algin-or2g7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bir

sonbahar yapraklarını süpürüp çekerken elini etiğini şehirden

sen saçınının arkasına benden kalma bir kalp iliştirip gittin

ben gözlerinin iğfal ettiği gözlerimden akan yaşlarla 

kara bir kışa gebe kaldım

iki

kış, asi çocuğu klimatolojinin 

ben acılar mektebinin en çalışkan talebesi

cebimde gönül tahtama atılmış bir yığın çentik

gecenin ısmarladığı yalnızlıkla dertleşe durayım gece tüm acımasızlığıyla parmaklarımın arasından akıp gidiyor

üç

bak yine sen geldin aklıma

bütün çiçekler seni hatırlatıyor bana 

kara verdim bakmayacağım artık

çiçekçi kadınların tezgahlarına

dört

n''olur bakma artık gece renkli kız 

kalmadı gönül imbiğimden sana akacak kan

n''olur git artık git ve sus', 'bir sonbahar yapraklarını süpürüp çekerken elini etiğini şehirden sen saçınının arkasına benden kalma bir kalp iliştirip gittin ben gözlerin...', ARRAY['Türk Edebiyatı','Şiir','Osman Algın']::text[], 8.5, '{"poet":"Osman Algın","poet_slug":"osman-algin","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/acelya-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oluruna Koy Gitsin', 'oluruna-koy-gitsin-alper-kuruk-agwjt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu hayat böyle geçmez

Susamayan su içmez,

Ekmeyen başak biçmez

Oluruna koy gitsin...

Kaderi silemezsin

Ne olur bişlemezsin,

Olsa,önleyemezsin

Oluruna koy gitsin...

Zehiri içemezsin

Ne tatlı diyemezsin,

Bu ömür böyle bitsin 

Oluruna koy gitsin...', 'Bu hayat böyle geçmez Susamayan su içmez, Ekmeyen başak biçmez Oluruna koy gitsin... Kaderi silemezsin Ne olur bişlemezsin, Olsa,önleyemezsi...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/oluruna-koy-gitsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidermisin Gitmezmisin', 'gidermisin-gitmezmisin-hasan-gorgu-18gmz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ay parladı güneş yandı

Gölge siyaha boyandı

Ateş kapıya dayandı

Gidermisin gitmezmisin

Hani nerde hayallerin

Sevdaların sevdiklerin

Nerde gelecek günlerin

Gidermisin gitmezmisin

Varsan çeşmenin başına

Sular kesilmiş şansına

Heyhat çabalar boşuna

Gidermisin gitmezmisin

11.10.2005

Saat 16,40', 'Ay parladı güneş yandı Gölge siyaha boyandı Ateş kapıya dayandı Gidermisin gitmezmisin Hani nerde hayallerin Sevdaların sevdiklerin Nerde ge...', ARRAY['Türk Edebiyatı','Şiir','Hasan Görgü']::text[], 8.5, '{"poet":"Hasan Görgü","poet_slug":"hasan-gorgu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/gidermisin-gitmezmisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'An Gelir Attila İlhan Ölür...', 'an-gelir-attila-i-lhan-olur-bahtiyar-arslan-lv9d4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 've alıp başını

çekip gitti yalnızlığın şairi

mavi bakışlı kız öksüz kaldı

öksüz kaldı bakışları

öksüz kaldı müjganımda damlalar...

ne bileyim dostlar

kanamaya başladı

kanamaya başladı bir kere bu yaralar...

ATTİLA İLHAN ÖLDÜ...

bir cigara sarın 

verin gecenin ağzına

derin derin çeksin dumanını...

ama dağıtmasın efkarını, üflemesin

rüzgara bıraksın külünü

yağmurla örtün ustanın üstünü

ATTİLA İLHAN ÖLDÜ...

tütün alın kaçakçılardan

ellerinizle sarın yarasını gecenin...

çocukları alın yanınıza

secdeye durun şiirlerle...ağlayın...

ATTİLA İLHAN ÖLDÜ...

elbette iki kişiliktir ölüm 

gecenin koynunda ölmüştü birisi...

söküp ciğerimizin yarısını

ölüm, şimdi tamamladı kendisini...

ATTİLA İLHAN ÖLDÜ...

haber salın Mimar Sinan''a

yeni bir kubbe yapsın, Anadolu''nun göbeğine...

selasını okusun Şeh Bedrettin

Ahmet Arif su döksun yüzüne...

ATTİLA İLHAN ÖLDÜ...

ve gece

ve yağmur

ve sehba...

kaldırın çıplak bedenini, PİR SULTAN''nın 

bir beyit okusun, dövsün dizini...

ATTİLA İLHAN ÖLDÜ...

''An gelir Attila İlhan ölür'' demişti, şair

duyun dostlar duyun

...................................ATTİLA İLHAN ÖLDÜ...

............................................................................Kanayın...', 've alıp başını çekip gitti yalnızlığın şairi mavi bakışlı kız öksüz kaldı öksüz kaldı bakışları öksüz kaldı müjganımda damlalar... ne bileyi...', ARRAY['Türk Edebiyatı','Şiir','Bahtiyar Arslan']::text[], 8.5, '{"poet":"Bahtiyar Arslan","poet_slug":"bahtiyar-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/an-gelir-attila-ilhan-olur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlayıpta Gel', 'anlayipta-gel-muhammet-faruk-koca-w659s', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İçimden bir şeyler kopuyor ansızın, 

Kelimelerin kifayetsiz kaldığı anlarda, 

Neydi? Beni sana ansızın zincirleyen, 

Neydi? Beni başı boş sokaklarda gezdiren, 

Yüreğim bile cevap veremez oldu gidişine, 

Her zerremde sen dolusun, 

Her kelimede ismini sayıklıyor dilim, 

Şimdi çok uzaklara gideceksin biliyorum, 

Ben yüreğimi koymuşken yoluna, 

Bir yerim hep eksik kalacak gidişinle, 

Senin gittiğin saatlerde, 

Şarkılar bile bastıramayacak gönül ağrımı, 

Kalbim ha durdu duracak, 

Kim bilir şimdi nerede ne haldesin diye, 

Oysa sen çok uzaklarda olacaksın, 

Bu kalbi yalnız bırakarak 

11.09.05', 'İçimden bir şeyler kopuyor ansızın,  Kelimelerin kifayetsiz kaldığı anlarda,  Neydi? Beni sana ansızın zincirleyen,  Neydi? Beni başı boş so...', ARRAY['Türk Edebiyatı','Şiir','Muhammet Faruk Koca']::text[], 8.5, '{"poet":"Muhammet Faruk Koca","poet_slug":"muhammet-faruk-koca","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/anlayipta-gel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Herşey Çağında Güzel', 'hersey-caginda-guzel-alper-kuruk-0jhgk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ağaç,dağında güzel

Üzüm,bağında güzel

Balık,ağında güzel

Herşey çağında güzel.

Ben,yanağında güzel

Aşk,dudağında güzel

Meşk,kucağında güzel

Herşey çağında güzel.

Aş,çanağında güzel

Od,ocağında güzel

Köşk,konağında güzel

Herşey çağında güzel.

Sana çirkin diyemem

Deyip de küçülemem,

Güzelsin derim lâkin

Herşey çağında güzel...', 'Ağaç,dağında güzel Üzüm,bağında güzel Balık,ağında güzel Herşey çağında güzel. Ben,yanağında güzel Aşk,dudağında güzel Meşk,kucağında güzel ...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hersey-caginda-guzel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eyvah', 'eyvah-mehmet-ayhan-gunaydin-qr8in', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'EYVAH

Dert, tasa, elem, keder.

Dostlar

Üzülme hepsi geçer derler.

Hem.

Dert insanı olgun edip

İyice de pişirirmiş.

Sabır ehli sonunda,

Muradına erermiş.

Bak.

Yunus bile ne demiş.

‘Çiğdik piştik Elhamdülillah’

Dostlar.

Galiba ben fazla piştim.

Dibim tuttu,

Yanıyorum, EYVAH! 

M. Ayhan Günaydın.

     20 Aralık 1993

Dereören / Havran / Balıkesir', 'EYVAH Dert, tasa, elem, keder. Dostlar Üzülme hepsi geçer derler. Hem. Dert insanı olgun edip İyice de pişirirmiş. Sabır ehli sonunda, Murad...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ayhan Günaydın']::text[], 8.5, '{"poet":"Mehmet Ayhan Günaydın","poet_slug":"mehmet-ayhan-gunaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/eyvah-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Çelengi', 'ask-celengi-alper-kuruk-l9qax', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sana ulaşmak için

Akan göz yaşlarıma 

Sicim sicim tutunsam

Kendine çeker misin? 

Karanlık yolarımın

Ucunda yanan ışık

Kaybolma arasında 

Uzanan kollarımın.

Kopmaz,kırılmaz telden

Bin bağla bağlanayım,

Aşka çelenk öreyim

Lâle,zambak ve gülden...', 'Sana ulaşmak için Akan göz yaşlarıma  Sicim sicim tutunsam Kendine çeker misin?  Karanlık yolarımın Ucunda yanan ışık Kaybolma arasında  Uza...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ask-celengi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aç Susuz', 'ac-susuz-serdar-erdemir-njtf6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'saat üç otuz

İçimdeki sana ait

duygular uykusuz.

cigaram 

ateşsiz dumansız.

yüreğim kıyıda bir sandal gibi 

yorgun yolcusuz...

saat üç otuz

bende ki

bu ben uykusuz.

saatim

bozuk, zamansız.

gecelerim 

gökteki yıldızlar gibi 

kayıpsız, hesapsız...

saat üç otuz

bir ben, bir de 

içimde ki sana ait ben

yorgun, uykusuz...

içimde ki sen

bana kalan sen kadar sen

aç susuz...', 'saat üç otuz İçimdeki sana ait duygular uykusuz. cigaram  ateşsiz dumansız. yüreğim kıyıda bir sandal gibi  yorgun yolcusuz... saat üç otuz ...', ARRAY['Türk Edebiyatı','Şiir','Serdar Erdemir']::text[], 8.5, '{"poet":"Serdar Erdemir","poet_slug":"serdar-erdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/ac-susuz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaç Gündür Yoksun', 'kac-gundur-yoksun-serdar-erdemir-om3xz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'kaç gündür yoksun

umutsuz, uykusuzum

gözlerim kan çanağı/

ıpıslak

tek avuntum 

pakette ki son cigaram

kaç gündür yoksun 

cigarasız, yalnızım...

kaç gündür yoksun 

pencere kenarında 

yol gözler oldum..

defalarca 

tanımadığım insanlara/

seni sordum.

kaç gündür yoksun 

pervasız, hesapsızım...

kaç gündür yoksun

evde oturmaktan

hep aynı şeyi yapmaktan

sıkıldım....

bir gece vakti, dışarı çıktım.

kaç gündür yoksun

kayboldum

çocuktum ağladım...

kaç gündür yoksun 

sana ait şiirleri okudum

vazoda ki çiçeğinle konuştum

adamakıllı dertleştik

güldük eğlendik

kaç gündür yoksun 

kimsin sen unuttum...', 'kaç gündür yoksun umutsuz, uykusuzum gözlerim kan çanağı/ ıpıslak tek avuntum  pakette ki son cigaram kaç gündür yoksun  cigarasız, yalnızım...', ARRAY['Türk Edebiyatı','Şiir','Serdar Erdemir']::text[], 8.5, '{"poet":"Serdar Erdemir","poet_slug":"serdar-erdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/kac-gundur-yoksun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İmanlı Ol Yeter', 'i-manli-ol-yeter-alper-kuruk-j9xbt', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne yaptık da dertleri hak,reva gördü Felek

Kötüler kalbur üstü,iyiyi eler elek.

İyi olacak sanma bozuluyor giderek

Çadırın damı göçtü kırıldı orta direk.

Öyle günler geldi ki cezan yok deve yutsan

Kıymetini bilen yok ağzınla da kuş tutsan.

Bin nasihat eden çok, bir nasihat tutan yok

Aç hâlinden ne anlar, açlık görmemiş ki tok? 

Gidişat ortadayken fazla söze ne gerek? 

Ağlanacak acıya bakıyoruz gülerek.

Kuralı koyan koymuş: herşey aslına döner

İnsan reha bulsaydı uçardı Mevlivîler.

Hayat çıplak başladı,yine çıplak bitecek

Gün gelince İsrafil ''sur''unu üfleyecek.

Öyle bir gün gelecek kâr etmez olsa paran

Dostların çekilecek yalnız seninle kalan

Tek desteğin olacak,tek yardımcın o zaman 

Göğsünde taşımışsan eğer bir zerre imân...', 'Ne yaptık da dertleri hak,reva gördü Felek Kötüler kalbur üstü,iyiyi eler elek. İyi olacak sanma bozuluyor giderek Çadırın damı göçtü kırıld...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/imanli-ol-yeter-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saat 01:30', 'saat-01-30-serdar-erdemir-kw444', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'elde bir karakalem

hayalimde sen

resmini çiziyorum

gökyüzüne maviden

saat 01:30

bitiyordu ki resmin

zamansız; 

kırıldı aniden kalemim

yıldızlar kaydı..

yandı gözlerim

saat 01:30

nihayet bitti resmin

solgun bir Tanrıça ya

benziyordu hayalin

göz kırptı bana,

o eşsiz mavi gözlerin

saat 01:30

zaman durgun

resmin solgun

gece suskun

ben mi.? delicesine yorgun

yalnızlıktan korktum

saat 01:30

ne yıldız kaydı,

aniden avuçlarıma

ne de göz kırptı 

gözlerin bir daha

bağışla dalmışım

saat 01:30', 'elde bir karakalem hayalimde sen resmini çiziyorum gökyüzüne maviden saat 01:30 bitiyordu ki resmin zamansız;  kırıldı aniden kalemim yıldız...', ARRAY['Türk Edebiyatı','Şiir','Serdar Erdemir']::text[], 8.5, '{"poet":"Serdar Erdemir","poet_slug":"serdar-erdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/saat-01-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kandil...', 'kandil-hasan-esat-heptunali-zs3w1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'düşler aleminin gece bekçisi

elinde kandil

dolanıp durur

bilinmezliğin loş sokaklarında

üşüşür pervaneler

zaman yok, mekan yok

sadece andır

anın tek sahibi

ve bir de....

aşkı, aşktan öte yaşama dileği...

.........................

üşür apansız

üşür içi

ısıtmaya yetmez

elindeki kandil ateşi....', 'düşler aleminin gece bekçisi elinde kandil dolanıp durur bilinmezliğin loş sokaklarında üşüşür pervaneler zaman yok, mekan yok sadece andır ...', ARRAY['Türk Edebiyatı','Şiir','Hasan Esat Heptunalı']::text[], 8.5, '{"poet":"Hasan Esat Heptunalı","poet_slug":"hasan-esat-heptunali","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kandil-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umuda Yolculuk', 'umuda-yolculuk-serdar-erdemir-2utje', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'düne ait ne varsa;  

sineye çekip

kırık bir sandal içinde/

geçmişe uğurladık.

ayrılığa dayanamadık

aydınlık günlere;  

hasret çekerek ağladık.

bugüne dair ümitlere;  

sisli dağlar ardından

mavi beyaz/

mendiller salladık

ne hikmetse; 

yine ağladık.

ağladık;  

göz yaşlarımız dondu

bembeyaz bir kış gecesinde;  

sagular yükseldi 

yıldızlar ağladı.

özgürlüğe demir almış;  

adını umut koyduğumuz gemi

gelmedi!  

eşref limanı kederlendi

yalnızlığın hüznünde 

dayanamadı;  

gökler ağladı…', 'düne ait ne varsa;   sineye çekip kırık bir sandal içinde/ geçmişe uğurladık. ayrılığa dayanamadık aydınlık günlere;   hasret çekerek ağladı...', ARRAY['Türk Edebiyatı','Şiir','Serdar Erdemir']::text[], 8.5, '{"poet":"Serdar Erdemir","poet_slug":"serdar-erdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/umuda-yolculuk-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki damla', 'i-ki-damla-hasan-esat-heptunali-gj2aj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bir el sallandı

peşim sıra

uğurlar olsun diyen..... 

nereye yolcu ettiğini bilmeden....

bir el ki...

saflığım

temizliğim...

''gülen suratım''

yitip gittiğim...

hoşçakal....

............................

iki damla belirdi....

damladım....', 'bir el sallandı peşim sıra uğurlar olsun diyen.....  nereye yolcu ettiğini bilmeden.... bir el ki... saflığım temizliğim... ''gülen suratım'' ...', ARRAY['Türk Edebiyatı','Şiir','Hasan Esat Heptunalı']::text[], 8.5, '{"poet":"Hasan Esat Heptunalı","poet_slug":"hasan-esat-heptunali","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/iki-damla-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Geldim Anne', 'sana-geldim-anne-serdar-erdemir-nbv30', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ben geldim anne; sana geldim

giderken; 

göz yaşlarınla içime bıraktığın/

son nasihatini yüreğime kilitleyip

yaşayacağım; 

son gecenin iniltisiyle geldim...

büsbütün yılgın

büsbütün yaralı

yüreği kınında.! 

durulmuş,arınmış geldim…

oy yüreğine vurulduğum; 

aç koynunu

yaban kokusuyla geldim.

bu kez yalnız değilim 

babamın haberi olmasın

içimde Allah korkusuyla geldim! 

hava soğuk, al içeri anne

korkma ellerimde ki; 

paslı kelepçelerden! 

masmavi özgürlüğümü sırtlayıp; 

doyasıya sarmaya,

koklamaya geldim…

üşüyorum anne ısıt beni

ürkek bir ceylan yavrusu/ 

yüreğiyle geldim…

titreyen ellerimi al avuçlarına; 

ovuştur 

baldıran acısıyla geldim…

uzat ellerini kurban olduğum

hasretini; 

zindanlarda soluduğum.

gözlerini; 

gecenin ürkekliğinde bulduğum

uzat ellerini sar boynuma

dönüşü olmayan; 

bir yoldan geldim.sana geldim…

gelişim sanadır anne; 

ellerim boş, kelepçeli! 

gözlerim hasretinin nöbetinde

yüreği dopdolu geldim.

sana geldim…

sakıncalı tutkularla

kırılgan umutlarla

bir bana kalan; 

deli başımla

eceli kapıda; bırakıp geldim.

sana geldim anne

yirmi beşlik değil; 

yedinci yaşımla.

çocukluğumla

tek temiz kalan yanımla geldim.

sana geldim…

 ''Ankara''dan Elazığ''a'' 1998', 'ben geldim anne; sana geldim giderken;  göz yaşlarınla içime bıraktığın/ son nasihatini yüreğime kilitleyip yaşayacağım;  son gecenin inilti...', ARRAY['Türk Edebiyatı','Şiir','Serdar Erdemir']::text[], 8.5, '{"poet":"Serdar Erdemir","poet_slug":"serdar-erdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/sana-geldim-anne-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Emmi Sen Nerelisin', 'emmi-sen-nerelisin-serdar-erdemir-c5hak', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'başında siyah şapkası

ağzında ıslak cigarası

yüzünde yıl çıbanı var

ah! Emmi sen nerelisin? 

gözlerinde hasret hüznü

bedeninde acı yüklü

şivesi aşk bülbülü! 

ah! Emmi sen nerelisin? 

nerelisin, nerelisin.

nolur bana söylermisin

ah! Emmi sen nerelisin? 

kızgın güneşte kavrulmuş teni,

buruşmuş yüzü, titriyor eli

sanki olmuş acıların esiri

ah! Emmi sen nerelisin?', 'başında siyah şapkası ağzında ıslak cigarası yüzünde yıl çıbanı var ah! Emmi sen nerelisin?  gözlerinde hasret hüznü bedeninde acı yüklü şiv...', ARRAY['Türk Edebiyatı','Şiir','Serdar Erdemir']::text[], 8.5, '{"poet":"Serdar Erdemir","poet_slug":"serdar-erdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/emmi-sen-nerelisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben – Suyum', 'ben-suyum-kadircan-keskinbora-ch673', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Suya engel olunabilir mi? Akacağı bir noktayı, bir yeri bulacak, oradan akacak, yoluna gidecektir. Set kurulursa, bu sefer birikir, birikir, birikir ve seti yıkıp dağıtarak yine akar. Evet, siz de su gibi iseniz, doğanız gereği akacaksınız. Akacak, akacak ve okyanuslara da ulaşacaksınız. Bütün engellere rağmen...', 'Suya engel olunabilir mi? Akacağı bir noktayı, bir yeri bulacak, oradan akacak, yoluna gidecektir. Set kurulursa, bu sefer birikir, birikir,...', ARRAY['Türk Edebiyatı','Şiir','Kadircan Keskinbora']::text[], 8.5, '{"poet":"Kadircan Keskinbora","poet_slug":"kadircan-keskinbora","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/ben-suyum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yorgun Yolcu ve Lodos Şovalyesi', 'yorgun-yolcu-ve-lodos-sovalyesi-serdar-erdemir-xkmro', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bana Sibiryayı anlat diyorsun

anlatayım dostum,anlatayım hele

sen; beni bana soruyorsun

işte ben beni anlatıyorum dinle

söylesene sen bana Lodos Şövalyesi

harbice kaç masum yürek gördün/ 

yağlı urganda çırpınan 

kaç geceyi yaşadın söyle

toprak yerine kan kokan? 

sen hiç yalnız kaldın mı ömründe

hiç ürktüğün oldu mu aniden

işkence dolu gecelerde/ titreyerek

gece kanlar içinde uyanıp

taptaze çelikten hançerlerle

kaç derin yara gördün, bedeninde

kaya tuzuyla yoğrulu! 

kaç parçanı yitirdin habersiz

Sibiryanın güneşsiz çöllerinde? 

yalınayak sürgün yaşadın mı sen

kilometrelerce aç-açık

Rusyanın keskin soğuğunda

kış ortasında su dolu hücreye

günlerce kapatıldın mı de hele

Rabbine bir kaç an sığındın diye. 

kaç gün yaşadın asil Şövalye söyle

açlıktan ölenlerle aynı hücrede! 

ölülerle konuştuğun oldu mu

yalvarıp özür dilediğin,

pirinç yerine etinden yedin diye! 

miden azap çektir dimi sana? 

insan etinden insanoğlu yedi diye! 

hücre duvarlarına mısra,mısra

işkence sonrası kanınla

asırlarca silinmez yazıyla

yaşadıklarını yazdın mı sen

yazdın mı söyle, yazdın mı? 

söylesene sen küskün Şövalye

utanma 

ayırma gözlerini gözlerimden

saklama gözyaşlarını geceden

bırak aksın yanaklarından/ bırak

ben; gözyaşları mı saklamadım

saklayamadım. 

hiç gün yüzü görmeyip

işkenceden işkenceye girdin mi? 

yıllarca dört duvar ardında: 

tepende votka içip, raks edenlere

içten,içe kin besledin mi sen? 

anlat dedin, anlatıyorum işte

ben; beni anlatıyorum sana.

su yerine, kendi kanını içip

azık yerine, insan eti yiyip

kaç gece yaşadın de hele 

yok, yok insanoğlu ağlama

anlattım işte, ben beni sana.

ben  Kırımlı Sibirya sürgünü

ben  Bektöre, ben Türk çocuğu

Anadolunun bilinmez gururu

ben  yedi göbek Osmanlı torunu

ben,ben işte hayatını sorduğun

kendisini anlatmasını istediğin/

kişiyim

ben Yunusum,ben yorgun yolcu

ben Erdemir, ben Süleyman oğlu

Sibiryada yitirilen canın ruhuyum!', 'bana Sibiryayı anlat diyorsun anlatayım dostum,anlatayım hele sen; beni bana soruyorsun işte ben beni anlatıyorum dinle söylesene sen bana L...', ARRAY['Türk Edebiyatı','Şiir','Serdar Erdemir']::text[], 8.5, '{"poet":"Serdar Erdemir","poet_slug":"serdar-erdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":65,"source_url":"https://www.antoloji.com/yorgun-yolcu-ve-lodos-sovalyesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Depresyon, İt Dalaşı, Çiş Akla Düşünce, Biri Seçim Biri Temenni', 'depresyon-i-t-dalasi-cis-akla-dusunce-biri-secim-biri-temenni-kadircan-keskinbora-tkmov', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Profesyonel uğraşımın günlük pratiği içinde karşılaştığım çeşitli hastalık ve durumların etkisiyle kağıda dökülmüş duygular. Bir de iltihaplara maruz kalıp profesyonel hasta olunca sağlığın değerini, önemli olanın ne olduğunu daha iyi anlıyor insan.', 'Profesyonel uğraşımın günlük pratiği içinde karşılaştığım çeşitli hastalık ve durumların etkisiyle kağıda dökülmüş duygular. Bir de iltihapl...', ARRAY['Türk Edebiyatı','Şiir','Kadircan Keskinbora']::text[], 8.5, '{"poet":"Kadircan Keskinbora","poet_slug":"kadircan-keskinbora","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/depresyon-it-dalasi-cis-akla-dusunce-biri-secim-biri-temenni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiliye Sone', 'sevgiliye-sone-serdar-erdemir-195xu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'heyhat güzelim heyhat

sen gidiyorsun diye

sanma ki; 

yıldızlara karşı/

savaşım son bulacak

sen gidiyorsun ya

içimde ki

endişeyi korkuyu da 

götürüyorsun habersiz

şimdi; 

eskisinden daha fazla 

hırs doluyum

avuçlarımla yolacam yıldızları

gözyaşı oklarımla yaralayacam geceyi

gökyüzünü:

kana bulayacam 

kimbilir bel ki de içimde ki; 

sana ait hislerime yükleyecekler/

bu cinayetin vebalini! 

heyhat güzelim heyhat', 'heyhat güzelim heyhat sen gidiyorsun diye sanma ki;  yıldızlara karşı/ savaşım son bulacak sen gidiyorsun ya içimde ki endişeyi korkuyu da  ...', ARRAY['Türk Edebiyatı','Şiir','Serdar Erdemir']::text[], 8.5, '{"poet":"Serdar Erdemir","poet_slug":"serdar-erdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sevgiliye-sone-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Sigaram', 'son-sigaram-serdar-erdemir-re9a5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'uykusuzluk garip bir tutku bende,

nöbetteyim her gece aynı saatlerde.

mavice bir ölüm rakı kadehlerinde! 

bu tek sigaram, son alışkanlık bende.

gecenin ürkekliği şimdi ellerimde,

eski bir tapınakta attım yerlere.

duman,duman gözyaşları gözlerimde

bu tek sigaram, son alışkanlık bende.

yalnızlık yağmur gibi damla,damla içimde,

ısıttım ıslak yüreğimi kibrit alevinde.

sigaramın dumanıyla tutuştu gece,

bu son sigaram, kurşun gibi beynimde.', 'uykusuzluk garip bir tutku bende, nöbetteyim her gece aynı saatlerde. mavice bir ölüm rakı kadehlerinde!  bu tek sigaram, son alışkanlık ben...', ARRAY['Türk Edebiyatı','Şiir','Serdar Erdemir']::text[], 8.5, '{"poet":"Serdar Erdemir","poet_slug":"serdar-erdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/son-sigaram-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Giga Akro ve Kripto', 'giga-akro-ve-kripto-sair-nimod-sxfhl', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '''yeter artık'' bu son, 

bir gün söküp atacağım, 

seni mavi derinlere. 

''çık'' artık kalbimden, 

yeter bunca yıl beklediğim, 

ben gittim artık benden. 

''gel'' dese de yüreğim, 

istemem kal yerinde, 

belki, sadece özlemek istiyorum seni. 

''3.3.5 + 3.3.4'' 

sözlerime aldırma, 

yüreğimdir doğru söyleyen.', '''yeter artık'' bu son,  bir gün söküp atacağım,  seni mavi derinlere.  ''çık'' artık kalbimden,  yeter bunca yıl beklediğim,  ben gittim artık ...', ARRAY['Türk Edebiyatı','Şiir','Şair Nimod']::text[], 8.5, '{"poet":"Şair Nimod","poet_slug":"sair-nimod","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/giga-akro-ve-kripto-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocukluk Korkum', 'cocukluk-korkum-serdar-erdemir-1fzns', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bir türlü alışamadım

şu kahrolası karanlığa,

çocukluğumdan bu yana 

ışıklar sönünce 

kör döğüşündeyim sanki

her gece ziyaretimde/ 

şekilden, şekile girmiş

alaycı, sinsi ifadeler! 

yalnız değilim artık

duvarda asılı parkam

koca bir yarasa gözümde

kanımı emmek için

fırsat kolluyor.

kafesteki kuşum 

sinmiş karanlığın kuytusuna,

nefes bile almıyor.

gölgeler, gölgeler

kapkara gölgeler

üstüme, üstüme geliyor

başucumda

Azrail  konuk gibi

yüreğim durdu duracak

yumsam gözlerimi

üstüme tüneyip/

boğacaklar beni.

korkuyorum tarifsiz

terler içinde

tir, tir titriyorum.

günün ilk ışıklarına dek

kendimle 

karamsar bir savaştayım

Güneş penceremden 

bir göz-kırpsa

isteksiz dalar giderim

çünkü

aydınlıkta ehemmiyetteyim

ya da ben

öyle sanıyorum,

geceleri uyumaya korkuyorum.

davetsiz misafirler artık gittiler.

yine yalnızım

kafesteki kuşum ötmekte,

geceden kalma

yorgunluğum

uykusuzluğum

çocukluğum 

utancım

ve çocukluk korkum!', 'bir türlü alışamadım şu kahrolası karanlığa, çocukluğumdan bu yana  ışıklar sönünce  kör döğüşündeyim sanki her gece ziyaretimde/  şekilden,...', ARRAY['Türk Edebiyatı','Şiir','Serdar Erdemir']::text[], 8.5, '{"poet":"Serdar Erdemir","poet_slug":"serdar-erdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/cocukluk-korkum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lanetler Olsun', 'lanetler-olsun-serdar-erdemir-g65bv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Beklenmedik bir anda

Seni karşıma çıkaran kadere

Silinmez yazıyla

Alnıma yazan kaleme

Lanetler olsun.

Her dem ahında

Aşkınla yanan yüreğime

Teselli ümidiyle

Albüme dalan gözlerime

Lanetler olsun.

Dertlerle, acılarla

Uykusuz geçen gecelere

Anılara mahkum

Yaşadığımız mutlu günlere

Lanetler olsun.', 'Beklenmedik bir anda Seni karşıma çıkaran kadere Silinmez yazıyla Alnıma yazan kaleme Lanetler olsun. Her dem ahında Aşkınla yanan yüreğime ...', ARRAY['Türk Edebiyatı','Şiir','Serdar Erdemir']::text[], 8.5, '{"poet":"Serdar Erdemir","poet_slug":"serdar-erdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/lanetler-olsun-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hawar', 'hawar-esref-uzulmez-rdvv1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'I

Bir mintana kan damlıyorsa

Bil ki yüreğimdir,namlunun ucunda 

Biliyorum özgürlüktür her yürüyüşün

Ey güneşin kızı! nasıl hawar ederim sessizce bir bilsen 

Hisset yanı başındayım

Kaç mum yakıp söndürdüm

Kaç karanfil bıraktım sessiz çığlıklarına 

Bir bilsen 

Mısraların nasıl namluları susturdu yüreğimde

II

Her savaşçı bir serüvencidir aslında 

Ve naiftir

Her ihtilal bir işgaldir

Çoğalmamış meydanların sessizliğinde 

Sen! gökyüzünü emzir,mavinin çocuklarına

Yazılmamış zamanlarda 

Emzir ki dilsizleşmesin dünya

Belki ansızın sular durulur 

Yüreğin uzanır yamaçlardan

Allahsız patikalarda şiirler kıvrılır

Ve zamanın elleri temizler

Barut kokusundan arta kalanları', 'I Bir mintana kan damlıyorsa Bil ki yüreğimdir,namlunun ucunda  Biliyorum özgürlüktür her yürüyüşün Ey güneşin kızı! nasıl hawar ederim sess...', ARRAY['Türk Edebiyatı','Şiir','Eşref Üzülmez']::text[], 8.5, '{"poet":"Eşref Üzülmez","poet_slug":"esref-uzulmez","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/hawar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçten İçe Ağlamak', 'i-cten-i-ce-aglamak-serdar-erdemir-oozio', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'silahı mermisiz

yüreği sevgisiz

bir yiğit ölüyordu.

içimde ecelsiz! 

gözleri açıktı.

avuçları kapalı

bir yiğit ölüyordu.

içimde manalı! 

ihanetin adı yok.

umutlar sancılanmış

yiğitler vurulunca; 

içten içe ağlarmış', 'silahı mermisiz yüreği sevgisiz bir yiğit ölüyordu. içimde ecelsiz!  gözleri açıktı. avuçları kapalı bir yiğit ölüyordu. içimde manalı!  iha...', ARRAY['Türk Edebiyatı','Şiir','Serdar Erdemir']::text[], 8.5, '{"poet":"Serdar Erdemir","poet_slug":"serdar-erdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/icten-ice-aglamak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül Bağları', 'gonul-baglari-serdar-erdemir-x9aum', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yıpranmış, yıkılmış, tarumar

Viran olmuş gönül bağları..

Hem bakımsız hem de ihmalkâr

Bitap kalmış gönül bağları..

Mevsimsiz hazan vurmuş sanki

Kurumuş tüm sevgi dalları..

Durgun sahipsiz kalmış gibi,

Sade bir han gönül bağları..

Seven her an elem buluyor,

Fayda vermiyor gözyaşları..

Aşk şairi suskun duruyor,

Dilsiz bülbül gönül bağları..', 'Yıpranmış, yıkılmış, tarumar Viran olmuş gönül bağları.. Hem bakımsız hem de ihmalkâr Bitap kalmış gönül bağları.. Mevsimsiz hazan vurmuş sa...', ARRAY['Türk Edebiyatı','Şiir','Serdar Erdemir']::text[], 8.5, '{"poet":"Serdar Erdemir","poet_slug":"serdar-erdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gonul-baglari-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mürekkebim Gözyaşı', 'murekkebim-gozyasi-serdar-erdemir-hid52', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'dün gece; 

esaretten kopmuş,

yüreğinden yaralı...

bir şair sığındı evime

/ sabaha dek,

derinden ağladı.

yorgun gözlerinden,

ıpıslak,masmavi

bir şiir damladı içime 

kıtalara ayrıldı,

mısra, mısra sızlandı…

yeni doğmuş,

bir çocuk tutkusuyla

sindi kalemime

saatlerce kıvrandı.

alfabem yitik,

kelimelerim yaralı; 

cümlelerim kan kusuyor.

öz Türkçem; 

hasta yatağında,

can çekişmekte! 

mürekkebim gözyaşı...', 'dün gece;  esaretten kopmuş, yüreğinden yaralı... bir şair sığındı evime / sabaha dek, derinden ağladı. yorgun gözlerinden, ıpıslak,masmavi ...', ARRAY['Türk Edebiyatı','Şiir','Serdar Erdemir']::text[], 8.5, '{"poet":"Serdar Erdemir","poet_slug":"serdar-erdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/murekkebim-gozyasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Dedikleri', 'ask-dedikleri-serdar-erdemir-ug1l6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'aşk dedikleri

bu olsa gerek gülüm

içimde; 

kanser hücresi gibi/

büyüyorsun.

ateşler içerisindeyim

bedenim veryansın

yüreğimi; 

asi bir ur gibi sarıyorsun.

yaralı bir kuş gibi/

son çırpınışlar.

ruhum işkencede

duygularım âciz

artık bünyem kaldırmıyor

her geçen gün

dayanılmaz acılarla geliyorsun

niyetin ne Allah aşkına

neyin intikamını alıyorsun? 

görmüyor musun gülüm 

çaresiz bir yara gibi/

kanıyorum.

çabalarım yetersiz

geceleri yıldız kayar gibi/

ak saçlarım tel,tel

dökülüyor.

tek bir lokma; 

boğazımdan geçmiyor,

gün geçtikçe eriyorum.

tanıyamıyorum kendimi

suratımda rezilce lekeler

dönüp bakmıyorsun.

söyle gülüm; 

yoksa utanıyor musun!', 'aşk dedikleri bu olsa gerek gülüm içimde;  kanser hücresi gibi/ büyüyorsun. ateşler içerisindeyim bedenim veryansın yüreğimi;  asi bir ur gi...', ARRAY['Türk Edebiyatı','Şiir','Serdar Erdemir']::text[], 8.5, '{"poet":"Serdar Erdemir","poet_slug":"serdar-erdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/ask-dedikleri-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kordonlu Saat', 'kordonlu-saat-serdar-erdemir-fb4qy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'kendisini hiç görmedim

duvarda asılı solgun

siyah beyaz resmiyle/

tanıdım babamı...

çocukluğumdan bu yana 

yokluğuna alışamadım

her gece uyurken

kokusunu duymadığım

bir kez dahi olsa 

beni öperken

nefesini hissetmediğim

duvardaki resmiyle avunduğum/

babamın; 

soğuk hatıratlarıydı

koynumda sakladığım

tütün tabakası ile

çuha kılıflı kordonlu saat...

07.01.2002 

Gece 2:30 Pazartesi', 'kendisini hiç görmedim duvarda asılı solgun siyah beyaz resmiyle/ tanıdım babamı... çocukluğumdan bu yana  yokluğuna alışamadım her gece uyu...', ARRAY['Türk Edebiyatı','Şiir','Serdar Erdemir']::text[], 8.5, '{"poet":"Serdar Erdemir","poet_slug":"serdar-erdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/kordonlu-saat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalancı Uyku', 'yalanci-uyku-serdar-erdemir-ju83n', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'uyumak

uyanmamacasına uyumak

uykularım harap,bitap

yorgun düşlerim

yorgun ümitlerim

her daim aynı rüya

alaca bir at koşar içimde

aydınlıktan karanlığa.

toynak sesleri/

çınlar kulaklarımda! 

uykularım paramparça

delicesine

ölürcesine yorgun.

sabahsızım

dudaklarım kupkuru

kanarcasına susuz

boğazımda ürkek bir hıçkırık

gözlerim,yorgun gözlerim

uykuya hasret gözlerim

sebepsiz, isteksizim

her şeye rağmen umutla/

bakıyorum yarınlara

yeniden güneş doğsun

çiçekler açsın

bardaktan boşanırcasına; 

yağmurlar yağsın.

korkuyorum; 

uyanmak içimden gelmiyor

uyumak 

uyanmamacasına uyumak/

istiyor, sefil gözlerim

yarınsız düşlerim

sabahsız ümitlerim

bir el dokunsun tenime

bir nefes girsin içime

soluksuzum 

...ölüyorum! 

yalancı bir uykudayım

uyandırın beni

hayatın

son demindeyim!', 'uyumak uyanmamacasına uyumak uykularım harap,bitap yorgun düşlerim yorgun ümitlerim her daim aynı rüya alaca bir at koşar içimde aydınlıktan...', ARRAY['Türk Edebiyatı','Şiir','Serdar Erdemir']::text[], 8.5, '{"poet":"Serdar Erdemir","poet_slug":"serdar-erdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/yalanci-uyku-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Utangaç Bir Yürek', 'utangac-bir-yurek-serdar-erdemir-6f4ol', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'yağmurlu bir Beyoğlu akşamında

utangaç bir yürek; 

sinmişti karanlığın kuytusuna.

derin, derin ağlıyordu.

gelip geçenlerden habersiz.

bir kız çocuğu; 

titriyordu elleri avuçlarında,

üşümüş parmaklarına,

nefesini üflüyordu.

bir yuvanın sıcaklığında.

ah! bir açsa avuçlarını,

ah! bir açsa

özgürlük kuşları uçacaktı.

korkuyordu açsa avuçlarını,

habersiz donacaktı.', 'yağmurlu bir Beyoğlu akşamında utangaç bir yürek;  sinmişti karanlığın kuytusuna. derin, derin ağlıyordu. gelip geçenlerden habersiz. bir kı...', ARRAY['Türk Edebiyatı','Şiir','Serdar Erdemir']::text[], 8.5, '{"poet":"Serdar Erdemir","poet_slug":"serdar-erdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/utangac-bir-yurek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Veda Mektubu', 'veda-mektubu-serdar-erdemir-npyag', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'veda ediyorum sadık dostum veda

bu şehre,yıldızlara, geceye ve sana.

tüm iyi dileklerim var; bu son fasılda

duysun cümle alem, duysun tüm dünya

veda ediyorum ey dostum veda

kafesteki kuşuma,sigarama ve aşkıma.

hoşça kal sadık dostum, hoşça kal kanarya.

veda ediyorum küskün arkadaş veda

ana ya, baba ya, eşe,dosta ve umutlarıma

Güneş in doğuşuna şu yağan yağmura

duysun istiyorum, duysun tüm dünya

veda ediyorum ey dostum veda

çocukluğuma, gençliğime, öptüğüm kızlara

gözün aydın yalnızlık, gözün aydın dünya

veda ediyorum asil dostum veda

yaşadığım yıllara, Elazığa, yurduma

n’olur kırılma gidiyorum diye bu gardaşına

duysun istiyorum,duysun artık tüm dünya

veda ediyorum asil dostum veda

davama, özgürlüğüme ve ruhuma

hoşça kal Meryem’ce, hoşça kal ütopyam!', 'veda ediyorum sadık dostum veda bu şehre,yıldızlara, geceye ve sana. tüm iyi dileklerim var; bu son fasılda duysun cümle alem, duysun tüm dü...', ARRAY['Türk Edebiyatı','Şiir','Serdar Erdemir']::text[], 8.5, '{"poet":"Serdar Erdemir","poet_slug":"serdar-erdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/veda-mektubu-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İyi Bilirdik', 'i-yi-bilirdik-yasemin-sezer-tulgar-7jnim', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'adıma yazılan bir 

sözle soluk buz 

tahtına kuruldu 

ünlem ardı nokta 

tek başına 

perişan diyecekti manşet 

ses verecekti do 

yetmişiki punto 

yetersizdi 

doğru an 

lisan sustu 

şiirler damlayacak çorağa 

höl yok 

gök bildiği 

değil artık 

yaş 

varana toprağa bu 

har olacak 

füzen/pelür 

gök/feza 

an 

başka 

şiirler damlıyor 

emildikçe peşi sıra 

hakkı var 

tadı istim 

gür pınar 

marks dinletiyor sözünü 

kafka hoşgeldin 

son nefeste 

son damla 

düşünce 

dillenecek; 

_____Kaç gökten 

___Kaç kurudan 

__Kaç yaştan 

D 

Ü 

Ş 

T 

Ü 

K 

sözleriyle 

_________________İyi bilirdik! 

10.10.05', 'adıma yazılan bir  sözle soluk buz  tahtına kuruldu  ünlem ardı nokta  tek başına  perişan diyecekti manşet  ses verecekti do  yetmişiki pun...', ARRAY['Türk Edebiyatı','Şiir','Yasemin Sezer Tulgar']::text[], 8.5, '{"poet":"Yasemin Sezer Tulgar","poet_slug":"yasemin-sezer-tulgar","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/iyi-bilirdik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Gece Bensiz Uyu', 'bu-gece-bensiz-uyu-serdar-erdemir-iciyq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bu gece bekleme beni, bensiz uyu.

ışıkları söndür

ne olur ne olmaz

kapını kilitli tut

pencereleri kapat.

perdeleri çek

alışmalısın yalnızlığa

kör karanlığa alışmalısın.

şayet uykun kaçarda

uyuyamazsan

yavrumuza sarılda yat

uyu rahat rahat

yavrumuz kâbus görmesin

olur olmaz sayıklama adımı.

dualarla uzan yatağa

-besmelesiz-

uyuma sakın

ört üstünü hava soğuk

kalkamazsın sabaha.

en geç sekizde ayakta ol

at şu ifriti üzerinden

silkinde doğrul.

ben yokum artık bunu kafana koy.

beni sevdiğini biliyorum,

ben de seni seviyorum

lâkin abartma

kahvaltını hazırla

uyandır çocuğunu

bak gözlerinin içine

bak ta kendine gel! 

ölen bedenler

ruhlar hele şairler/ 

asla ölmezler 

benim için ölmemeli

yavrumuz için yaşamalısın.

beni onda

yavrumuzda yaşatmalısın.', 'bu gece bekleme beni, bensiz uyu. ışıkları söndür ne olur ne olmaz kapını kilitli tut pencereleri kapat. perdeleri çek alışmalısın yalnızlığ...', ARRAY['Türk Edebiyatı','Şiir','Serdar Erdemir']::text[], 8.5, '{"poet":"Serdar Erdemir","poet_slug":"serdar-erdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/bu-gece-bensiz-uyu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Seviyorum', 'seni-seviyorum-efsun-aydin-io9h3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bana bugünde bir şiir yazdın güzel yüzlüm,

Bilirim ki üzerime sinen kokuyu kaleme almişsındır kelimelerinde.

En çok da Seni Seviyorum ları serpmişsindir aralara.

Beni ne kadar seviyorsunlarınla cilveleşiyorsundur şimdi sen.

Ve Özledim Aşkım Nolur gelleri biriktiriyorsundur duygularında...

Ben istemez miyim yanında olmayı,

Güzel Yüzünü öpmeyi,

Saçını koklamayı...

Az kaldı Bebeğim...

Gözlerini kapat,uyuyup uyan uyuyup uyan...

Bu çok sürmeyecek ama...

Ben bir bakacaksın ki yanında olacağım...

Hani sen hep dersin yaa bana; 

''''Şiir yazmak hiçbirşey; Sen gel bir de yazanı oku'''' diye...

İşte Gözbebeğim burada okuduklarındır sana duyduklarım.

Seni Seviyorum.', 'Bana bugünde bir şiir yazdın güzel yüzlüm, Bilirim ki üzerime sinen kokuyu kaleme almişsındır kelimelerinde. En çok da Seni Seviyorum ları s...', ARRAY['Türk Edebiyatı','Şiir','Efsun Aydın']::text[], 8.5, '{"poet":"Efsun Aydın","poet_slug":"efsun-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/seni-seviyorum-295-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boyun Eğmedim', 'boyun-egmedim-serdar-erdemir-28rq9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bir gece vakti 

düştüler peşime

üstüme, üstüme geldiler

bir köşe başında

beni ölesiye dövdüler

-sövdüler

içimde ki tertemiz hisleri

karanlık bir dehlizde

kan gölüne gömdüler…

ah! dostum; 

beni bende bitirdiler

yine de yenilmedim 

o çakal sürüsüne 

boyun eğmedim asil dostum

boyun eğmedim

sinsi yılanlar gibi

çullandılar üstüme

bir kaç adi o..çocuğu

kapkara paslı hançerleriyle

içimde ki günahsız kızı; 

kanlar içinde yaraladılar…

doymadılar asil dostum

bir şarap mahzeninde 

yüreğimden damlayan 

o masmavi kanımı 

kana, kana içtiler

yine de yenilmedim

o çakal sürüsüne 

boyun eğmedim asil dostum

boyun eğmedim

o it sürüsüne...', 'bir gece vakti  düştüler peşime üstüme, üstüme geldiler bir köşe başında beni ölesiye dövdüler -sövdüler içimde ki tertemiz hisleri karanlık...', ARRAY['Türk Edebiyatı','Şiir','Serdar Erdemir']::text[], 8.5, '{"poet":"Serdar Erdemir","poet_slug":"serdar-erdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/boyun-egmedim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aldanış', 'aldanis-serdar-erdemir-q72fq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'senden sonra 

seviştiğim tüm kadınlar 

soğuk bana! 

seni ne kadar

aldatsam da

içimde ki pişmanlık

hep aldatır beni! 

kimin koynuna

sen diye girsem

kış ortasındaymışım gibi

soğuk öldürür beni! 

ne mümkün

seninle yeniden sevişmek

teninin sıcaklığıyla

yoğrulmak 

nefesini içimde duymak

ne mümkün

tatlı bir rüyaydı bitti

bitti artık 

ey ömrüm

anı hasretliği kokan kitabı

kapa artık...', 'senden sonra  seviştiğim tüm kadınlar  soğuk bana!  seni ne kadar aldatsam da içimde ki pişmanlık hep aldatır beni!  kimin koynuna sen diye ...', ARRAY['Türk Edebiyatı','Şiir','Serdar Erdemir']::text[], 8.5, '{"poet":"Serdar Erdemir","poet_slug":"serdar-erdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/aldanis-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kan Pıhtısı', 'kan-pihtisi-serdar-erdemir-zle7w', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'elden ne gelir; 

çaresiz yara durmadan kanar! 

gariplikler içinde/

tüm ürkekliğiyle sarı kanarya; 

kapılır gider esen rüzgâra! 

elden ne gelir; 

sigara dumanıyla geceler yanar…

elden ne gelir; 

erişilmez sevgi ufuklar kadar

bedenlerde bir sızı; 

üç hain vurdular günahsız kızı.

kalplerde korku, umutsuz ve yarım

elden ne gelir; 

kirli çakallar lanetiyle yaşar...

elden ne gelir; 

kirlenmiş yarınlara kim bakar

taptaze umutlarda hicran

yine; 

aynı cinsten hayvan ve insan

hani; 

kan pıhtısına vurulmazdı zincir? 

elden ne gelir; 

yaratılan hep geleceğinden kaçar…', 'elden ne gelir;  çaresiz yara durmadan kanar!  gariplikler içinde/ tüm ürkekliğiyle sarı kanarya;  kapılır gider esen rüzgâra!  elden ne gel...', ARRAY['Türk Edebiyatı','Şiir','Serdar Erdemir']::text[], 8.5, '{"poet":"Serdar Erdemir","poet_slug":"serdar-erdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/kan-pihtisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben olacagım', 'ben-olacagim-ali-kilincci-pv4vg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ayrılsanda degişmeyecek hiç birşey

Herzaman yanında ben olacagım.

İster başkasını deli gibi sev 

Alevli aşkında ben olacagım. 

Birsel gibi akar zaman dedigin

Birgün gider güvendigin güzelligin

Rabbın hakkı için yemin etmişim

Ölürken yanında ben olacagım.

Tek dünyalık degil sana özlemim

Herzaman sevgimi ispat ederim

Çünkü kuvvet verdi gözlerin

Mahşerde yanında ben olacagım.', 'Ayrılsanda degişmeyecek hiç birşey Herzaman yanında ben olacagım. İster başkasını deli gibi sev  Alevli aşkında ben olacagım.  Birsel gibi a...', ARRAY['Türk Edebiyatı','Şiir','Ali Kilincci']::text[], 8.5, '{"poet":"Ali Kilincci","poet_slug":"ali-kilincci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ben-olacagim-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arkadaş', 'arkadas-serdar-erdemir-clg5f', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'nedir senin bu hâlin be arkadaş,

sen böyle hepten değişemezsin.

hırçın hâlinden eser kalmamış,

simsiyah gür saçların ağarmış..

hayretlere düşürdün beni arkadaş.

hayret,hayret,hayret be arkadaş

yıllar sonra seni, bir köşede,

yıkılmış bir hâlde mi bulacaktım! 

yüreğinin silahları olan, ellerinde

içki şişelerini mi bulacaktım..

hayret,hayret,hayret be arkadaş.

nerede o arkadaşım, nerede bu avare,

o tanıdığım sen olamazsın.

gururlu dik başın eğilmiş,

kanlı gözlerine yaşlar birikmiş.

hayretlere düşürdün beni be arkadaş.', 'nedir senin bu hâlin be arkadaş, sen böyle hepten değişemezsin. hırçın hâlinden eser kalmamış, simsiyah gür saçların ağarmış.. hayretlere dü...', ARRAY['Türk Edebiyatı','Şiir','Serdar Erdemir']::text[], 8.5, '{"poet":"Serdar Erdemir","poet_slug":"serdar-erdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/arkadas-93-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gökyüzü Ağlıyor', 'gokyuzu-agliyor-serdar-erdemir-0i08p', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'duygularımın yasında

gökyüzü ağlıyor gülüm

masmavi gözlerinden! 

sağanak,sağanak gözyaşı

düşüyor çorak toprağa

bir tohum filizleniyor/

usulca

zemheriye inat!', 'duygularımın yasında gökyüzü ağlıyor gülüm masmavi gözlerinden!  sağanak,sağanak gözyaşı düşüyor çorak toprağa bir tohum filizleniyor/ usulc...', ARRAY['Türk Edebiyatı','Şiir','Serdar Erdemir']::text[], 8.5, '{"poet":"Serdar Erdemir","poet_slug":"serdar-erdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gokyuzu-agliyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur Yağsa', 'yagmur-yagsa-serdar-erdemir-17z6c', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'garip ne zaman yağmur yağsa; 

ıslanıyor gözlerim.

sis bürüse dağ başlarını,

buğulanıyor gözlerim.

isteksiz bir kuş uçsa üzerimden,

ürperiyorum.

ne zaman karanlık olsa içten içe

hep ağlıyorum.

kalemim yazmaya dursun,

hep bir şiirdir; 

kin gibi kusarım! 

sevdiğim gelmesin aklıma.

bir katil gibi.

tetikteyim, ecel gibi sinerim.

tütmeye dursun cigaram.

çaresiz, küser giderim.', 'garip ne zaman yağmur yağsa;  ıslanıyor gözlerim. sis bürüse dağ başlarını, buğulanıyor gözlerim. isteksiz bir kuş uçsa üzerimden, ürperiyor...', ARRAY['Türk Edebiyatı','Şiir','Serdar Erdemir']::text[], 8.5, '{"poet":"Serdar Erdemir","poet_slug":"serdar-erdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yagmur-yagsa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Belada Başım', 'belada-basim-serdar-erdemir-0zc3g', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'hep aynı garip tecelli,belada başım; 

yüreğimin kırık bam teli,vefasız aşkım,

ne yapsam boşuna kâr etmiyor akışım.

yüreğimin sahipsiz kuşu, esire aşkım.

umutsuz bir vaka sebebim yaşım,

sığmıyor bedenime ruhum,belada başım,

hissetmesem de akıyor damla,damla kanım.

hep aynı garip tecelli, kanlı barışım.', 'hep aynı garip tecelli,belada başım;  yüreğimin kırık bam teli,vefasız aşkım, ne yapsam boşuna kâr etmiyor akışım. yüreğimin sahipsiz kuşu, ...', ARRAY['Türk Edebiyatı','Şiir','Serdar Erdemir']::text[], 8.5, '{"poet":"Serdar Erdemir","poet_slug":"serdar-erdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/belada-basim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mavi Tren', 'mavi-tren-serdar-erdemir-s78xk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'özlem ve hasretlik yüklü

mavi bir tren kalkar

kapkara dumanıyla

yüreğimin derinliğinden! 

ciğerlerim isyanda

ürperirim, ürperir gece

nefes alamam saatlerce

daralır, boğulurum

boğar beni gizlice

soğuk rüzgar içten içe!', 'özlem ve hasretlik yüklü mavi bir tren kalkar kapkara dumanıyla yüreğimin derinliğinden!  ciğerlerim isyanda ürperirim, ürperir gece nefes a...', ARRAY['Türk Edebiyatı','Şiir','Serdar Erdemir']::text[], 8.5, '{"poet":"Serdar Erdemir","poet_slug":"serdar-erdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/mavi-tren-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yitik Şehir', 'yitik-sehir-serdar-erdemir-23wwb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'yalvarıyorum dokunmayın

doluyum bugün

doluyum, dopdolu! 

ağlayacak gücüm yok; 

neler duymadı ki kulaklarım

neler görmedi ki

sefil gözlerim.

bir muamma gölündeyim

yalvarıyorum; 

gelin bulun beni

yitik bir şehrin

kızgın çölündeyim…', 'yalvarıyorum dokunmayın doluyum bugün doluyum, dopdolu!  ağlayacak gücüm yok;  neler duymadı ki kulaklarım neler görmedi ki sefil gözlerim. ...', ARRAY['Türk Edebiyatı','Şiir','Serdar Erdemir']::text[], 8.5, '{"poet":"Serdar Erdemir","poet_slug":"serdar-erdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yitik-sehir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçimiz Gidiyor (Atilla İlhan Üstadımızı Uğurlarken)', 'i-cimiz-gidiyor-atilla-i-lhan-ustadimizi-ugurlarken-yavuz-bayram-caliskan-mk1an', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yüreğime adını koydum Üstadım Atilla İlhan,

Açtığım şiir okulunda öğrencilerin okuyor,

Bir nehir gibi uzun da olsa ömür,

Gün gibi gelip geçiyor,

Bir üstat ahirete uçuyor.

Biz sana mecburuz bilirsin,

Seninle yoğruldu şiirlerimiz,

Seninle sevdalandı yüreğimiz,

Toprağa düştüğünde çınar,

Binlerce fidan senin için yarınlara…', 'Yüreğime adını koydum Üstadım Atilla İlhan, Açtığım şiir okulunda öğrencilerin okuyor, Bir nehir gibi uzun da olsa ömür, Gün gibi gelip geçi...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Bayram Çalışkan']::text[], 8.5, '{"poet":"Yavuz Bayram Çalışkan","poet_slug":"yavuz-bayram-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/icimiz-gidiyor-atilla-ilhan-ustadimizi-ugurlarken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haylaz Çocuk', 'haylaz-cocuk-serdar-erdemir-ncn5z', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'gülüm

sen en yaralı yanımsın,

zaafım var sana karşı

ne zaman 

habersiz bir kuş uçsa üzerinde.

haylaz bir çocuğum

eli sapanlı

hedefime taş koymuşum!', 'gülüm sen en yaralı yanımsın, zaafım var sana karşı ne zaman  habersiz bir kuş uçsa üzerinde. haylaz bir çocuğum eli sapanlı hedefime taş ko...', ARRAY['Türk Edebiyatı','Şiir','Serdar Erdemir']::text[], 8.5, '{"poet":"Serdar Erdemir","poet_slug":"serdar-erdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/haylaz-cocuk-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zamansız Akşamlar', 'zamansiz-aksamlar-serdar-erdemir-dmvgl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'korkuyorum bu zamansız,

hain gecelerin karanlığında/

yalnız kalmaktan

sus-pus olmuş üşümüş

bir köşeye sığınmış/ 

olmaktan korkuyorum.

titriyorum ellerim avuçlarımda

nefesimi üflüyorum

parmaklarıma 

damarlarımda son bir çaba/

zamansız akşamlarda

ısınamıyorum.

katran yeşiline boyalı

kabuslar içinde uyanmaktan

saatlerin uykuda olduğu vakitler/

dudaklarım kupkuru

su aramaktan

terler içinde ıslak/

çırılçıplak uyanmaktan

.........korkuyorum! 

bu unutulmuş 

tek başına yalnız/

sıvası dökülmüş odada; 

avuçlarımda kan

saçlarımda hicran kokusuyla

alnımda kızıldan/

soğuk bir busenin bıraktığı

çelikten izle

unutulmaktan korkuyorum.

aslında ben; dilim varmıyor 

bu zamansız akşamlarda,

ölmekten korkuyorum.', 'korkuyorum bu zamansız, hain gecelerin karanlığında/ yalnız kalmaktan sus-pus olmuş üşümüş bir köşeye sığınmış/  olmaktan korkuyorum. titriy...', ARRAY['Türk Edebiyatı','Şiir','Serdar Erdemir']::text[], 8.5, '{"poet":"Serdar Erdemir","poet_slug":"serdar-erdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/zamansiz-aksamlar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karla Karışık', 'karla-karisik-serdar-erdemir-tfn8q', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bir yağmur yağıyordu/

karla karışık

sanki gökten ak yıldız/

kayıyordu.

gözüm İstanbul ağlıyordu.

o güzelim; 

masmavi gözlerinden/

delicesine yaşlar akıyordu.

bir yağmur yağıyordu/

karla karışık

yağmurla barışık

gözüm İstanbul ağlıyordu.

karla karışık', 'bir yağmur yağıyordu/ karla karışık sanki gökten ak yıldız/ kayıyordu. gözüm İstanbul ağlıyordu. o güzelim;  masmavi gözlerinden/ delicesine...', ARRAY['Türk Edebiyatı','Şiir','Serdar Erdemir']::text[], 8.5, '{"poet":"Serdar Erdemir","poet_slug":"serdar-erdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/karla-karisik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçimde bir yerlerde cennet kusurluluğu/', 'i-cimde-bir-yerlerde-cennet-kusurlulugu-asya-gulgun-ozkan-q4cqq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '/// Ölemeyenler ürperir, en çok geceleri………. 



Hayattan kopanlarla birlikte 

Silinip gitti sesimin elvan rengi 

Tükenen nefesimin buğusunda 

Teni yakan rayiha durulup kalmış 

Daha da isterken gecenin derinliğini 

Dilenci bakışın canhıraş çığlığı suspus 

Çıldırasıya özlenen çıplak, narin avuçların 

Uzanıp göğsüme saplandı, habis yangısı 

Epey uzun zaman almış 

Dudaklarımdaki kum yangının sönüşü 

Şimdilerde tutsaklığı şarap susuzluğu... 

İçimdeki kuyuda esen rüzgarlı anlardan birinde 

Soluğumdan buz gibi damlayan ekim akşamı 

Yüzümden sere serpe dökülen ıssızlık 

Saçlarımda niyetini çoktan bozmuş zaman 

Ellerimde abartılı aşklara kesilmiş onca bilet 

Üzerimde sürüldüğüm şehirlerin uykusuzluğu 

Çantamda en gücenik, o en kederli şiir 

Hiçbir şeyin anlamı yok aslında 

Bir şeyler için ölmeli 

Ama ne! 

Sonra; 

Döndüğüm yol ayrımlarının bir yerlerinde 

bulmalılar beni …', '/// Ölemeyenler ürperir, en çok geceleri……….  Hayattan kopanlarla birlikte  Silinip gitti sesimin elvan rengi  Tükenen nefesimin buğusunda  ...', ARRAY['Türk Edebiyatı','Şiir','Asya Gülgün Özkan']::text[], 8.5, '{"poet":"Asya Gülgün Özkan","poet_slug":"asya-gulgun-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/icimde-bir-yerlerde-cennet-kusurlulugu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uyuyamıyorum', 'uyuyamiyorum-serdar-erdemir-vswlu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ahşap bir binanın; 

sıvası dökülmüş odasında.

perdeler örtük,

ışıklar sönük

uyuyorum sanma

uyuyamıyorum.

bu yalnızlık boğacak beni! 

cigaram dudaklarımda

hasretini çekiyorum! 

gözlerim nöbetinde

ben seni yaşıyorum.

gecenin son saatlerinde

bir ürperti düşer içime

yorgunluk alır beni

uyku bürür gözlerimi

senin yaptığın gibi.

hayalinde terk eder beni

sadece; 

gözyaşı kalır bana

iflah olmaz bir yalnızlık çilesi

karanlık aydınlığa gebe

gün doğdu doğacak

uyuyorum sanma

uyuyamıyorum.

bu yalnızlık boğacak beni!', 'ahşap bir binanın;  sıvası dökülmüş odasında. perdeler örtük, ışıklar sönük uyuyorum sanma uyuyamıyorum. bu yalnızlık boğacak beni!  cigaram...', ARRAY['Türk Edebiyatı','Şiir','Serdar Erdemir']::text[], 8.5, '{"poet":"Serdar Erdemir","poet_slug":"serdar-erdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/uyuyamiyorum-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Feryat', 'feryat-abdulkadir-i-lyas-1j4q1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kara bulutlar belirmiş bir bir kaplıyor arşı 

İnsanlık uyuyor hala gaflet sarmış dört bir yanı

Yarını düşünen yok hesaplar bugüne kurulmuş

Mazi rafa kaldırılmış duygulara gem vurulmuş

Yaratan çoktan unutulmuş yaratılanlar biçare

Adeta tersine dönmüş dünya zina içki kumarhane

Kızımın iffeti paspas olmuş kafirin ayağına

Öğüt veren atam yok gören taş basmış bağrına

Camiler ağlıyorken meyhanelerde bayram var

Susmuş adeta duyulmuyor minaremde ezanlar

Ölen ölmüş kalan kalmış umrunda değil kimsenin 

Akıllardan silinmişmiş birgün kesilecek sesim

Vakit çok geç olmadan uyan artık bu uykudan

Çalışıp mutlak kazanırsın göç etmeden dünyadan...

                                                                        (2004)', 'Kara bulutlar belirmiş bir bir kaplıyor arşı  İnsanlık uyuyor hala gaflet sarmış dört bir yanı Yarını düşünen yok hesaplar bugüne kurulmuş M...', ARRAY['Türk Edebiyatı','Şiir','Abdulkadir İlyas']::text[], 8.5, '{"poet":"Abdulkadir İlyas","poet_slug":"abdulkadir-i-lyas","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/feryat-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lala', 'lala-ahmet-hani-k7lim', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dağda derirdim lala, 

birden dedi ay bala, 

bir gün mende senintek, 

burda derirdim lala!', 'Dağda derirdim lala,  birden dedi ay bala,  bir gün mende senintek,  burda derirdim lala!...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Hani']::text[], 8.5, '{"poet":"Ahmet Hani","poet_slug":"ahmet-hani","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/lala-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ve Artık Yoksun', 've-artik-yoksun-deniz-ali-karadag-et3vu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ve artık yoksun...

Sadece; 

Bedenin yok,

Oval omuzların,

Dikkat çekecek kadar

Olmayan

Küçük

Ve yükselip alçalan göğsün yok,

Ve denizin mavisi

Sürmelerin yok,

Ve dalgaları

Hatırlatan saçların yok.

İçinde kaybolan

Kaybettiren

Zamanı durduran

Gözlerin yok…

Ama sen olmazsan

İnan

Hiç kimse yok…', 'Ve artık yoksun... Sadece;  Bedenin yok, Oval omuzların, Dikkat çekecek kadar Olmayan Küçük Ve yükselip alçalan göğsün yok, Ve denizin mavis...', ARRAY['Türk Edebiyatı','Şiir','Deniz Ali Karadağ']::text[], 8.5, '{"poet":"Deniz Ali Karadağ","poet_slug":"deniz-ali-karadag","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/ve-artik-yoksun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acıtıyorsun', 'acitiyorsun-deniz-ali-karadag-gh4ea', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Acıtıyorsun

Acıktırıyorsun

Her geçen zamanda

İnadına

Hep sen

oluyorsun

Gözlerimi; 

Her kırpıp açtığımda

Bir tedirginlik

ve

Kaybetmek korkan

Yüreğim...

Ve ürkek bakışların

Ve öne düşen boynun

Ve sevgi çukurun

İnadına hep aklımda

Ve tenin

Gelincik gibi

Pürüzsüz

Tenine

Dokunamamak

Saramamak

Acıtıyor...

Acıveriyor', 'Acıtıyorsun Acıktırıyorsun Her geçen zamanda İnadına Hep sen oluyorsun Gözlerimi;  Her kırpıp açtığımda Bir tedirginlik ve Kaybetmek korkan ...', ARRAY['Türk Edebiyatı','Şiir','Deniz Ali Karadağ']::text[], 8.5, '{"poet":"Deniz Ali Karadağ","poet_slug":"deniz-ali-karadag","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/acitiyorsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Meçhulün Güncesinden Notlar..!', 'bir-mechulun-guncesinden-notlar-turgut-baki-ebr0z', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'eskici tezgahından aldığım 

karakaplı defterin ilk sayfasında

 devrik harflerle şöyle yazılmıştı; 

“ kendine bile meçhul bir adamım ben…”

ve sonra şöyle devam etmişti satırlar; 

hayır...

alışamadım  hala, 

ihanetler ağır geliyor.

ağır geliyor dost bellediklerimin diri diri mezara gömüşleri beni

lime lime  çürürken 

beni ben eden, bende ne varsa

inançlarım, 

alay edercesine inançsızlıklarımla raks ediyor

önce beynim,

sonra yüreğim yabancılaşıyor bana

beni ilk terk edense; umutlarım…

kendimle hesaplaşacağım anı bekliyorum ama

sorgu melekleri gelmedi daha

yaşarken kendimi işe yaramaz biri olduğuma inandırmaya çalışmakla geçiyor 

yalnız dakikalarım…

ama dakikalar,

bana kalan şu küçük zaman diliminde 

kalbim ve beynim arasındaki upuzun yolu geçebilmeme yetmiyor…

nerden aktığı belli olmayan bir kan var dudağımda

ve dudağımda nerden gelip konmuşsa bir kuşun gözyaşı! 

şimdi tüm bunların benimle işi ne? 

yoksa şahitlik etmek için mi buradalar

yeniden dirilişime…

dışarısı günlük mü? 

yoksa gece mi

sonbahar yağmurları yağıyor mu hala? 

nedense üşüyorum

ama soğuk değil

var mıdır haberi halimden sevdiklerimin

ya göz yaşı döken kimse 

var mıdır ardımdan? 

ya inandıklarım

inandığım ve uğruna tükenişi yeğlediğim onca şey? 

onca şey sahipsiz ve öksüz mü kalacaklar şimdi? 

güzel günler görmek artık imkansız mı yurdum insanlarına? 

biliyorum 

ben hiç bir şeydim 

ve hep 

hiç olmayı yeğledim

inandıklarımın 

ve umut ettiklerimin bir gün var olabilmesi adına…

yine de böyle mi olmalıydı? 

onca yaşanan 

hiç olarak mı kalmalıydı? 

oysa ben 

savaş meydanlarında tükenmek isterdim

ve son nefesi 

zafere giden yolda 

bir tebesümle vermeliydim...

dost ellerden

bedenime saplanmış hançerlerin 

ihanet  zehiriyle değil…

diyerek bitiyordu ilk sayfa…', 'eskici tezgahından aldığım  karakaplı defterin ilk sayfasında  devrik harflerle şöyle yazılmıştı;  “ kendine bile meçhul bir adamım ben…” ve...', ARRAY['Türk Edebiyatı','Şiir','Turgut Baki']::text[], 8.5, '{"poet":"Turgut Baki","poet_slug":"turgut-baki","theme":"Türk Şiiri","is_hero":false,"total_lines":58,"source_url":"https://www.antoloji.com/bir-mechulun-guncesinden-notlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölü Aşklar Derneği Lokal Açılışı/Komedi', 'olu-asklar-dernegi-lokal-acilisi-komedi-mehmet-akif-gulhan-msgr1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Telefonun bir ucunda Ayşenur var

-Derneğin açılışı var gelir misin? 

-Açılış mı? gelmem mi hiç,gelirim tabii

Hani size bu derneğin tekne gezisini yazmıştım ya,

bu o hikayenin devamı olacak kaçırılır mı hiç

-Ne zaman

-Salı günü saat 19.30 da Taksim de

-Neresinde

- Miss Taksim lokalinde

-Tamam prenses gelirim(rumuzu  “kurbağa prenses “ya) 

Küçükken çok yaramaz bir çocuktum,olmadık şaklabanlıklar,

yaramazlıklar yapardım,rahmetli anneannem; 

-Oğlum rahat dur” şeytan arkana  parmak mı atıyor derdi

Bu kurbağa prenses rumuzuna öyle kafayı taktım ki; 

Tekne gezisine gittiğimizde “aa prenses ne kadar güzelsin,ben seni 

kurbağa göreceğimi zannediyordum,kim öptü seni” diyecektim

Şeytan devamlı parmak durumunda ya ondan,

ama diyemedim,yanımda hanım vardı,fırsatta olmadı

Belki bu defa derim

Salı günü oldu hazırlanacağım ama,aklıma bir şüphe düştü

Bir erenlerin sağı solu belli olmaz bir de bu şair milletinin

Telefon açtım

-Prenses yola çıkıyorum,bir değişiklik yok değil mi

-Aaa sen bilmiyor musun,toplantı iptal oldu

-Ne, aaa, eeee

-Hani ramazanın ilk günü ya,ilk iftar,hani çoluk çocuk hep beraber felan

-Sağlık olsun,ne olacak şimdi? 

-Cumartesi günü aynı saatte aynı yerde tamam mı? 

-Tamam prenses

Cumartesi günü,giyindim kuşandım,çıktım yola,ben Küçükyalı’da oturuyorum

taksim dolmuşları Bostancıda,yürüye yürüye gittim,yollar inşaat halinde 

iski boru döşüyor,yollarda besili keklik gibi zıplıyorum,hopluyorum

neyse dolmuşa zor attım kendimi,biraz nefes aldım,şükür

Dolmuş doldu dolacak,iftar zamanı gelmeden,

herkes gideceği yere varmak için sabırsızlanıyor

Her dolmuşa binen yolcuya şükran ile bakılıyor,dolunca gidilecek ya

Şeytan rahat durmuyor,yine içime kurt düştü,ya yine iptal olduysa toplantı

Telefona sarılıyorum; 

-Prenses toplantı durumu ne? geliyorum

-Gelmeee! toplantı iptal

-Ne iptal mi? ne oldu yine ya 

-Toplantıyı iptal ettik pazartesi günü,lokalde kendi yerimizde açılış yapacağız

Dolmuştan iniyorum mecburen,o sırada son yolcu gelmesin mi

ben iniyorum o biniyor,suratıma garip garip bakıyor

Bütün yolcular bana öfkeyle bakıyor

kahya,şoför beni öldürecek gibi bakıyor,

Kulaklarım çınlamaya başlıyor,bu tansiyondan değil muhakkak ki

her halde bütün sülalem nasibini alıyor bu çınlamadan

Eh be prenses,yaktın beni,alacağın olsun,

yine hoplaya hoplaya seke seke eve dönüyorum

Pazartesi iptal yok şükür,

üç saat evvelden yola çıkıyorum,

yollar felaket, İstanbul yolları şantiyeye dönmüş vaziyette

Şoförün insan üstü gayreti ile varıyoruz nihayet Taksim’e

sora sora, el yordamı, göz yordamı buluyorum adresi

-Merhabalarrr

-Ooo merhaba hoş geldin

Ayşenur ve Nisan hanım var içeride iki tane de beyefendi

-Merhaba ben Mehmet Akif 

-Merhaba ben Mustafa Kemal

-Merhaba ben …….

İsmini hatırlamıyorum,ben hafıza özürlüyüm,kendi yazdığım şiirleri bile hafızamda tutamam

Sadece bir dörtlüğüm var hafızam da o da

Neredesin ey bekri

Doldur bade-i tası barkı

Geçiyor diye dövünme ömrüm

Geçen eşref vakti

Sadece bu aklımda herhalde çok kısa diye

Harıl harıl çalışıyorlar,hazırlık yapıyorlar toplantı için

Tabaklar çanaklar,kolalar, çay paketleri hepsi ortada

Ayşenur

-Ben tuvaleti temizledim diyor

Ötekiler 

-Biz de temizledik,bizde temizledik diyorlar

-Dört defa tuvalet temizlenir mi kardeşim diyorum içimden ”bırakan ne bırakmışsa”

Bana o sıkışıklık arasında bir kahve ikram ediyorlar

-Ben sana dargınım prenses diyorum

Şaşkınlıkla

-Aaa neden 

-Ya! senden bir fıkra istedim tam ramazanlık fıkra yazmışsın bana 

Gülüyor

-Hakikaten öyle oldu

-Hani sen bir tane edepli fıkra biliyordun,zaten onu da teknede anlatmadın mı? 

Prenses’de cevap hazır

-Bunu yeni öğrendiiim

Prenses hemen atılıyor,diğerlerine dönüp

-Bakın size de anlatayım

Sınıfa yeni din hocası gelmiş,çocuklarla tanışıyormuş

-Yavrum senin adın ne? 

-Fatih öğretmenim

-Ne güzel,oku bakalım o zaman bize Fatiha suresini

Çocuk okumuş

-Senin adın ne kızım? 

-Kevser öğretmenim

-Ne güzel, sende oku bakalım Kevser suresini

Çocuk okumuş

Arkalardan bir çocuğun saklanmaya çalıştığını görmüş,yanına gitmiş

-Senin adın ne bakalım

-Yasin öğretmenim ama siz Süphaneke diyebilirsiniz demiş

Ötekiler gülmedi herhalde anlamadılar,ben zaten biliyordum, bende gülmedim

Sanki prensesin umurunda

Hazırlıklar bitmek üzere

-Pasta pasta nerede arkadaşlar

Açılışta pasta kesilecek,üzerine “Ölü aşklar derneği” yazdırdık, diyorlar

-Açalım mı pastayı? 

-Açalım hazır olsun

Pastayı dikkatlice açıyorlar bozulmasın diye

Murphy kanunlarına göre,biliyorsunuzdur muhakkak, korktuğunuz başınıza gelir

-Ya Ayşenur bunu yazısı bozulmuş

-Hadi ya inanmam

-Vallahi bak,ölü bozulmuş,derneği de bozulmuş

Beylerden birisine enişte diyorlar,enişte öne atılıyor

-Ben düzeltirim şimdi onu

-Yaşa be enişte! 

Düzeltiyor yazıyı ölüyü siliyor derneği de siliyor,aşkların anlamı yok,lar’ı da siliyor

kalıyor dımdızlak Aşk

-Düzelttim sadece aşk kaldı

Şeytan yine rahat bırakmıyor beni

-Buna da şükür ya ölü kalsaydı

Üyeler yavaş yavaş geliyor,kibar beyler nazik hanımlar,

hepsi çok şık giyinmişler,sanki baloya gelir gibi

Allah’tan takım elbisemi giymişim 

hanımda sağ olsun bembeyaz bir gömlek ütülemiş,

zaten topu topu bir takım elbisem var. 

Hani derler ya hem düğüne hem cenazeye giyiyorum diye işte öyle,

ama elime bir şemsiye almışım yağmur yağar diye

hani o uzun olanlardan katlanmayanlardan,İngiliz aristokratları gibiyim

Sahi aristokratlar şemsiyeyi sapından mı tutar ortasından mı,ben ortasından tutuyorum da 

Toplantı başlıyor,Ayşenur başkan, söz alıyor

-Vallahi arkadaşlar burayı bulabildik ancak,burayı kiraladık

başka yerlere de baktık ama,çok üst katlardaydı baktığımız yerler, minare gibi

çık Allah çık bitmiyordu,bir yere daha baktık orada da satanist’ler varmış daha evvel 

kiracı olarak(satanist kiracınız olduğunu düşünebiliyor musunuz)   içerde mumyalar vardı küçük küçük,birde ağır bir koku

-Kedi kesmişlerdir orada

Bu sözü kim söyleyebilir,tabii ki ben

-Arkadaşlar proje üretelim

-Pastayı ne zaman keseceğiz

-Önce boya arkadaşlar

-Müzik dersi verebiliriz

-Ünlüleri getirelim

-Ben Bedri’yi getiririm

-Bizim Bedri’yi mi,Baykam yani

-Arkadaşım oğlum o

-Tablo satarız burada

-Pastayı ne zaman keseceğiz? 

-Proje diyorum arkadaşlar, millet üçyüzbin euro alıyormuş

-Bize vermezler

-Pastayı ne zaman keseceğiz? 

-Ahmet Selçuğu da çağıralım

-Bırak şunu ya küsüm ben ona

-Önce dekor arkadaşlar

-Duvarları boyatalım

-Ressam arkadaş boyasın işte

-Pastayı ne zaman keseceğiz? 

-Çallıyı getirelim

-Çallı ölmedi mi ya? 

-Bizim arkadaş süs eşyası yapıyor onlardan da satarız

-Ya! pastayı diyorum

-? ? ? ? ? 

-Yani ne zaman keseceğiz? 

-Beyazı getirelim

-Tamam bak! Ben onu getiririm, tanıyorum beni kırmaz

-Programı yüklü o gelmez,film,dizi falan

-O beyaz değil be kardeşim

-Beyaz hoca, Zekeriya  Beyaz

-Ne o, oruç nasıl bozulur onu mu soracaksın? 

-Proje arkadaşlar üçyüzbin euro Allah Allah

-Çay beşyüz olsun

-Yok daha neler

-İkiyüz elli

-Tamam üçyüz olsun

-Kutu olsun

-Kimin kutusu var

-Ya pasta arkadaşlar ya- ne zaman keseceğiz? 

-Eksik ne var? 

-Çaycı var

-Çaycı tutamayız

-Hayır çay makinesi diyorum

-Adam tutalım buraya

-Olmaz lan karı atar buraya,başımız belaya girer

-Bu sokakta mafya var mı abi

-Soba alalım

-Elektrikli olsun kim uğraşacak

-Yağlı

-Ne yağlısı kardeşim

-Radyatör

-Ne diyorsun ya? 

-Ben yağlı radyatör getireyim bir tane

-Yağ dediniz de aklıma geldi pastayı ne zaman keseceğiz

-Kesin kardeşim şu pastayı ya

Pasta kesildi nihayet,afiyetle yendi,ha bak aşk yazan yeri kim yedi bilmiyorum

Proje mi? ne projesi? 

Karar mı? 

Ha! karar, bir daha ki toplantıya,acelesi ne

Yalınız yağlı radyatörü ben getiriyorum haberiniz olsun

Mehmet Akif Gülhan  11.10.2005 Saat 19.10', 'Telefonun bir ucunda Ayşenur var -Derneğin açılışı var gelir misin?  -Açılış mı? gelmem mi hiç,gelirim tabii Hani size bu derneğin tekne gez...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif Gülhan']::text[], 8.5, '{"poet":"Mehmet Akif Gülhan","poet_slug":"mehmet-akif-gulhan","theme":"Türk Şiiri","is_hero":false,"total_lines":196,"source_url":"https://www.antoloji.com/olu-asklar-dernegi-lokal-acilisi-komedi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'An Gelir', 'an-gelir-yusuf-ter-2gebs', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'an gelir 

paldır küldür yıkılır bulutlar 

gökyüzünde anlaşılmaz bir heybet 

o eski heyecan ölür 

an gelir biter muhabbet 

çalgılar susar heves kalmaz 

şatârâbân ölür 



şarabın gazabından kork 

çünkü fena kırmızıdır 

kan tutar / tutan ölür 

sokaklar kuşatılmış 

karakollar taranır 

yağmurda bir militan ölür 



an gelir 

ömrünün hırsızıdır 

her ölen pişman ölür 

hep yanlış anlaşılmıştır 

hayalleri yasaklanmış 

an gelir şimşek yalar 

masmavi dehşetiyle siyaset meydanını 

direkler çatırdar yalnızlıktan 

sehpada pir sultan ölür 



son umut kırılmıştır 

kaf dağı''nın ardındaki 

ne selam artık ne sabah 

kimseler bilmez nerdeler 

namlı masal sevdalıları 

evvel zaman içinde 

kalbur saman ölür 

kubbelerde uğuldar bâkî 

çeşmelerden akar sinan 

an gelir 

-lâ ilâhe illallah- 

kanunî süleyman ölür 



görünmez bir mezarlıktır zaman 

şairler dolaşır saf saf 

tenhalarında şiir söyleyerek 

kim duysa / korkudan ölür 

-tahrip gücü yüksek- 

saatlı bir bombadır patlar 

an gelir 

attilâ ilhan ölür

Attila İlhan', 'an gelir  paldır küldür yıkılır bulutlar  gökyüzünde anlaşılmaz bir heybet  o eski heyecan ölür  an gelir biter muhabbet  çalgılar susar hev...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ter']::text[], 8.5, '{"poet":"Yusuf Ter","poet_slug":"yusuf-ter","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/an-gelir-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Izmir', 'izmir-seref-kaya-xjq4u', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Izmir im sana bakiyorum

Sende Balcova yi  buluyorum

Sanma sana kiziyorum

Balcovada ilk ask imi ariyorum

Neden rüyalarimda hep seni görüyorum

Bir Karsiyaka bir Kordonda geziyorum

Fuar i dolasiyorum Tilkilik te kokiric yiyorum

Basmahane den Halkaliya tren le gidiyorum

Aziziye den Ballikuyu ya yayan cikiyorum

Gürcesme nin isiklari piril piril Zekiye yi unutamiyorum

Kadife kaleden Izmir im seni seyrediyorum

Esrefpasa Havra sokagi Kestanepazarina iniyorum

Agora dan ikicesmelik yoluyla pazar yerine geliyorum

Yagnelerde kirtikoz teyzeden salyangoz dolmasi istiyorum

Ah ücyol um Halilrifat a dogru yürüyorum

Nerede Susuz dede beton yiginlarindan göremiyorum

Gümrük ten Kemeralti na gencligimi anarak giriyorum

Sanli gecmisim Konak im  camii mi saat imi seyrediyorum

Nerde yasaklar kizlisesi önünde polisleri göremiyorum

Inan ilk askim seni hala kahverengi formanla hayalliyorum

Babamin bizler icin calistigi askeri hastane önünde duruyorum

Bonsuvar da kazandibi yiyor Asansör de kahve iciyorum

Karatas im hamamlar kokaryalim özlüyorum

Kelköy dü adi ückuyular oldu simdide Fahrettin altay diyorlum

Ikiz tepelerden Balcova ya variyorum

Ilk askim neden sana hala kavusamiyorum     

                                                                              seref kaya 25.09.05 Frankfurt/m', 'Izmir im sana bakiyorum Sende Balcova yi  buluyorum Sanma sana kiziyorum Balcovada ilk ask imi ariyorum Neden rüyalarimda hep seni görüyorum...', ARRAY['Türk Edebiyatı','Şiir','Şeref Kaya']::text[], 8.5, '{"poet":"Şeref Kaya","poet_slug":"seref-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/izmir-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bağ Bozumu', 'bag-bozumu-ozkan-ozdogan-vlki1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kırılır camda güneş,

çoğalır yorgun yüzümde

bağbozumu günlerin yanıkları..

Bulutlar göçer gider,

şarap renginde gölgeler

gelir tüner gözlerimde.

Turna sürüleri canhıraş yakarır da,

bir yudum tazelik için

peşimsıra ağartır havayı; 

bir küserim kendimle

çözülür dilim bir barışırım,i

anlaşılmaz yine derdim

avunurum kendimle..', 'Kırılır camda güneş, çoğalır yorgun yüzümde bağbozumu günlerin yanıkları.. Bulutlar göçer gider, şarap renginde gölgeler gelir tüner gözleri...', ARRAY['Türk Edebiyatı','Şiir','Özkan Özdoğan']::text[], 8.5, '{"poet":"Özkan Özdoğan","poet_slug":"ozkan-ozdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bag-bozumu-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yoksa Bir Gelen Mi Var Kaçtığım Şehre', 'yoksa-bir-gelen-mi-var-kactigim-sehre-ahmet-nural-ozturk-oj6zi', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yüreğimde bir kıpırdama var bu akşam 

Nasıl söylesem nasıl anlatsam

Bir yolculuk mu var yoksa geldiğim yere

Yoksa bir gelen mi var kaçtığım şehre

Bilemiyorum...', 'Yüreğimde bir kıpırdama var bu akşam  Nasıl söylesem nasıl anlatsam Bir yolculuk mu var yoksa geldiğim yere Yoksa bir gelen mi var kaçtığım ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Nural Öztürk']::text[], 8.5, '{"poet":"Ahmet Nural Öztürk","poet_slug":"ahmet-nural-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/yoksa-bir-gelen-mi-var-kactigim-sehre-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hecan / c a n kesikleri...', 'hecan-c-a-n-kesikleri-zafer-zengin-etnika-nzkbh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '.

.

durmadı

dağınıklığın ardından

beklenti çubukları kırıldı

ve açız dedikçe

hep yemeye

yemeğe hepler konup

tabaklarımıza sürüldü

.

bilinmez

kim keser adaleyi dibinden

kurusun güz

ve yaz güzün peşine

sarnıcı yıkık sular 

dibe düşsün

beklensin

biten günün dili

bir şarkı

yanımızdan geçip giden

iç okurken

ve anlatırken ağlamak

üstüne sigara yakıp

dumanını bağlamak

ölmüş çocuklardan

şarkılar dinlemek

öyle çok bana

kopar sızıyı ‘bağlama

.

ciddiye alma ölümü

fermanı gün dönümü

.

yanlış anla bizi

düşürme ateşine

kaç yanılgı koyduk da ''cebimize

çerez yapmadık ''bebelere

varsın

gitmeye hevesli

misafir kalsın

.

kalanlar ansın

her canı ‘biz sansın

he can...

.

rahat değilim

lirik epik

pastoral ve kartpostal

ne düşürsem taciz

uzun beklemelere kalıyor haciz

ve sidik yarışları sanıp

kulvarlar üzerinde

çakışıyor bulvarlar

hecan...

.

oysa; 

sokakta kapılırdı köşeler

beni su

deniz bir zaman

bir kadın sakinleştirsin

kızgınım her an

hecan...

.

yola düşürdüm kendimi

gidemediğim aklımda

ıslık çalan kayalar

ve denizin ninnisini

bırakıp ardımda ''geldim

el’de attım ''yalnızlığa

hecan...

.

canlı olsun şiir

konuşsun

dinlesin

gülsün çayın yanında

tütün çeksin ''ölsün mesela

dar ağacı kursun ''bir yerde

dizenin iç’ine bittiği

gömleği bir imge

yaftası dilde kalsın

sesle çırpılsın

illa masum olsun

çocuk illa

hecan...

.

dalga kırandan sonra

uğradı liman yıkan

yola anlattı ‘durdu zaman

kıyısından döndüm

boyum kadar turkuaz

kum karışır terime

kapıkaya gölge

tırmanır 

bin basamak önümde

git de

ölümü bıraktım ''gittim

gelmişken denize

hecan...

14 09 2005

.', '. . durmadı dağınıklığın ardından beklenti çubukları kırıldı ve açız dedikçe hep yemeye yemeğe hepler konup tabaklarımıza sürüldü . bilinmez...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":99,"source_url":"https://www.antoloji.com/hecan-c-a-n-kesikleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üstat: Necip Fazıl Kısakürek', 'ustat-necip-fazil-kisakurek-ozkan-karaca-krnzs', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Düşüncelerinin sellerinde, duygularının taşkınlığında

    İnsanlığın: zihin bulanıklığını, fikir sulanıklığını

    Çile yüklü kalbine doldurarak

    Aydınlık boyasını yapıştırarak

    Fikir bereketi ile açarak

    Değişimin öncüsü, gelişimin sözcüsü olan

    Çağının değerler üstü değeri bulunan

    Şairler sultanı: Necip Fazıl kısakürek

                Müteffekkir soluğuyla ikmal sıvayıcısı

                Ulvi ağahıyla ikbal sulayıcısı

                Selim hasletiyle inkişaf habercisi

                Dillerle kaplanan, dualarla yankılanan

                Üstat: Necip Fazıl

     Zamanın kıskacında; 

     Nesillerin buhramını söndüren

     Ruhların sancısını çöktüren

     Gönüllerin bağrında filizler meydana getiren

     Zihinlerde dalgalanan, fikirlerde yaygınlanan

                  Fikri ve ilimi genişlikle alim

                  Duygu ve düşüncelerle salim

                  Yumuşak gönül ve yüksek ruhla halim

                  Güzelliklere buluşturmasıyla hakim

      Vuslat kimliğinin zerafetinde

      gönül genişliğinin zirvesinde

      Var olmanın geçiş yolunda

      Zamanın kültürende araç, 

      Asırların sanatında amaç olan

      

                    Şiir ekolunda yoğrulan

                    Fikir dinanizminde yükselen

                    Ufukların altın yıldızlarının parçası

                    Şairlerin biriciği, kelamların diriliği

                    Mutmain kanatlarıyla güzeliklere ulaştıran

                    Necip Fazıl Kısakürek', 'Düşüncelerinin sellerinde, duygularının taşkınlığında     İnsanlığın: zihin bulanıklığını, fikir sulanıklığını     Çile yüklü kalbine doldur...', ARRAY['Türk Edebiyatı','Şiir','Özkan Karaca']::text[], 8.5, '{"poet":"Özkan Karaca","poet_slug":"ozkan-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/ustat-necip-fazil-kisakurek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Yolculuk Mu Var Yoksa Geldiğim Yere', 'bir-yolculuk-mu-var-yoksa-geldigim-yere-ahmet-nural-ozturk-5yjv8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yüreğimde bir kıpırdama var bu akşam 

Nasıl söylesem nasıl anlatsam

Bir yolculuk mu var yoksa geldiğim yere

Yoksa bir gelen mi var kaçtığım şehre

Bilemiyorum...', 'Yüreğimde bir kıpırdama var bu akşam  Nasıl söylesem nasıl anlatsam Bir yolculuk mu var yoksa geldiğim yere Yoksa bir gelen mi var kaçtığım ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Nural Öztürk']::text[], 8.5, '{"poet":"Ahmet Nural Öztürk","poet_slug":"ahmet-nural-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/bir-yolculuk-mu-var-yoksa-geldigim-yere-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özleminle', 'ozleminle-mehmet-aslan-70961', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Göremedim, senin gülen yüzünü,

Duyamadım, senin tatlı sözünü,

Özledim, senin badem gözünü,

Çözemedim, senin sırlı özünü.

Hasretinle, beni yetim bıraktın,

Özleminle, beni hep yaktın,

Hayalinle, beni çok yaşattın,

Gidişinle, beni şoka uğrattın.

Anlayamazsın,  seni nasıl bekledim,

Bilemezsin, seni çok özledim,

Düşünemezsin, seni niye sevdim,

Gidemezsin, seni beklerken bittim.

Düşünme, benim niye yandığımı,

Duyma, benim nasıl ağladığımı,

Bilme, benim niçin kandığımı,

Görme, benim nasıl yıkıldığımı.', 'Göremedim, senin gülen yüzünü, Duyamadım, senin tatlı sözünü, Özledim, senin badem gözünü, Çözemedim, senin sırlı özünü. Hasretinle, beni ye...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Aslan']::text[], 8.5, '{"poet":"Mehmet Aslan","poet_slug":"mehmet-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ozleminle-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlamıyorsun Sevgimden', 'anlamiyorsun-sevgimden-mehmet-aslan-jfk7h', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu gece yine her geceki gibi,

Seni yazıyorum mısralarımda.

Yarında her günkü gibi,

Bekleyeceğim yanaklarımda.

Cesaretin varsa eğer,

Bir öpücük kondur yeter.

Sende seviyorsan eğer,

İki sihirli kelime yeter.

Ne gezer o cesaret sende,

Söyleyemiyorsun bile derdini.

Pranga mahkumusun esaret sende,

Anlatamıyorsun bir türlü sevgini.

Sende anlamıyorsun sevgimden,

Dururken Tanrı’nın bakire kulları,

Rahatsız mı oldun sevgimden,

Uygun gördün bana dulları.', 'Bu gece yine her geceki gibi, Seni yazıyorum mısralarımda. Yarında her günkü gibi, Bekleyeceğim yanaklarımda. Cesaretin varsa eğer, Bir öpüc...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Aslan']::text[], 8.5, '{"poet":"Mehmet Aslan","poet_slug":"mehmet-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/anlamiyorsun-sevgimden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılıklardan Dönüyorum', 'ayriliklardan-donuyorum-akay-s-q7gdv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ayrılıklardan dönüyorum

göz ucumda duruyor izleri

sakin gecenin kıyısında durmuşum

Kulağımda fırtına sesleri

zaman nasılsa eskitiyor diye

ayrılık hep aynı yerde açar yarayı

biten her aşkın ardından

görürüz aynı manzarayı

hiç acıtmıyor artık

yüzümün ıslanması çocukluktan

bir çaresi bulunur elbet

kim ölmüş yalnızlıktan

ayrılıklardan geliyorum

gömleğimde kan izi

beni böyle bıraktınız diye

bir gün unutacağım hepinizi', 'ayrılıklardan dönüyorum göz ucumda duruyor izleri sakin gecenin kıyısında durmuşum Kulağımda fırtına sesleri zaman nasılsa eskitiyor diye ay...', ARRAY['Türk Edebiyatı','Şiir','Akay S']::text[], 8.5, '{"poet":"Akay S","poet_slug":"akay-s","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ayriliklardan-donuyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğmak Meydan Okumaktır', 'dogmak-meydan-okumaktir-metin-yalti-m0dus', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir çocuğun 

Dünyaya gelirken ağlaması

Ne doğumun sancısından

Ne de dünyaya gelmenin pişmanlığındandır

Onların ağlaması

Kendi dillerince 

Dünyaya merhaba deyip

Ölüme meydan okumasındandır

2005', 'Bir çocuğun  Dünyaya gelirken ağlaması Ne doğumun sancısından Ne de dünyaya gelmenin pişmanlığındandır Onların ağlaması Kendi dillerince  Dü...', ARRAY['Türk Edebiyatı','Şiir','Metin Yaltı']::text[], 8.5, '{"poet":"Metin Yaltı","poet_slug":"metin-yalti","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/dogmak-meydan-okumaktir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnanmışız Seraba', 'i-nanmisiz-seraba-mehmet-aslan-2g4u2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ateş yürümüş kor olmuş, sarmış bacayı,

Elimde değil, kaptırmışız bir kere paçayı,

Erimiş bitmişiz, unutmuşuz sıcak çorbayı  çayı,

Yutmuşuz balık gibi, çıkaramıyoruz kancayı.

Sevgi diye sarılmışız, bunca yıl hep ızdıraba,

Gerçek sanmışız rüyayı, inanmışız seraba,

Neden diye sordum, çektim kendimi hesaba,

Veremedim hesabı, gömdüm bir şişe şaraba.

Bir gün sende, kapılırsan kaderin cilvesine,

O zaman anlarsın, alışırsın hayatın sillesine,

Kahve gibi, bittiğinde bakarsın telvesine,

Geçmişe bakar, hasret kalırsın onun sevgisine.

Seni bilmem ama, ben sevdalıyım,

Her zamanki gibi, senden de yaralıyım,

Sen gidersin ben kalırım,  buralıyım,

Feleğe dargınım, çünkü kaderi karalıyım.

Hiç üzülme, çaresizlik bendedir,

Anlayışlı olursan, çözümü sendedir,

Bunun adı, karşılıksız sevmedir,

Satırlarım seni değil, kendimi yermedir.', 'Ateş yürümüş kor olmuş, sarmış bacayı, Elimde değil, kaptırmışız bir kere paçayı, Erimiş bitmişiz, unutmuşuz sıcak çorbayı  çayı, Yutmuşuz b...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Aslan']::text[], 8.5, '{"poet":"Mehmet Aslan","poet_slug":"mehmet-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/inanmisiz-seraba-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiç Vuruldunmu', 'hic-vuruldunmu-mehmet-aslan-miw7q', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çok acılar çektim, geçmişten yaralıyım,

Akıllanmadım, elimde değil sana sevdalıyım,

Sevdim bir kere, mutlaka sana sunmalıyım,

Sende seviyorsan eğer, senden duymalıyım.

Söyleyemiyorum sana sevdiğimi, şiirlere yazıyorum,

Yazdığımı okumazsın, şiir sevmediğini biliyorum,

Sevdireceğim sana bu sanatı, bunun için uğraşıyorum,

Beni sevmeni çok istiyorum, bunu senden bekliyorum.

Sevgi kapanı nedir bilir misin, hiç tutuldun mu,

Acılar çektin mi, sevgi hamuruyla yoğruldun mu,

Feryat ettin mi hiç, aşk yağıyla kavruldun mu,

Peşinden koştun mu hiç, benim gibi yoruldun mu.', 'Çok acılar çektim, geçmişten yaralıyım, Akıllanmadım, elimde değil sana sevdalıyım, Sevdim bir kere, mutlaka sana sunmalıyım, Sende seviyors...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Aslan']::text[], 8.5, '{"poet":"Mehmet Aslan","poet_slug":"mehmet-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hic-vuruldunmu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Varmısın Benimle', 'varmisin-benimle-mehmet-aslan-ux6d1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Seni görmek demek, benim için dünyalar,

Özlemini gidermiyor, benim için rüyalar,

Hasretimi arttırıyor, dinlediğim bütün şarkılar,

Gördüğüm zaman da yetmiyor, engelliyor kurallar.

Vuruldum sana, fakat ne var sende  bilemiyorum,

Karşılıksız da olsa, bir türlü aklımdan silemiyorum,

Çok istiyorum, fakat sana bir türlü söyleyemiyorum,

Aklıma geldikçe, kahrımdan kendime gelemiyorum.

Belki sende seviyorsundur, bana söyleyemiyorsun,

Taştan kalbin vardır belkide, beni hiç sevmiyorsun,

Kararsızsındır ikilemdesindir belki, belli etmiyorsun,

Belkide hiç yaşamamışsın sen, sevgi nedir bilmiyorsun.

Sevgi iki türlüdür; bir geyiği, birde gerçeği vardır,

Geyiği çabuk ve acı biter sonu her zaman hüsrandır,

Gerçeği huzurdur ömür boyu mutluluk ve kutsaldır,

Benimki gerçek sevgidir ömür boyu, sonu nikahtır.

Seviyorsan belli et, haydi söyle, varmısın benimle,

Konuşalım, tanışalım, anlatalım, anlaşalım seninle,

Dünyalar benim olur, bana vereceğin sıcak kalbinle,

Sana sevgim çok ciddidir burada yazıyorum yeminle.', 'Seni görmek demek, benim için dünyalar, Özlemini gidermiyor, benim için rüyalar, Hasretimi arttırıyor, dinlediğim bütün şarkılar, Gördüğüm z...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Aslan']::text[], 8.5, '{"poet":"Mehmet Aslan","poet_slug":"mehmet-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/varmisin-benimle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaçış Yok', 'kacis-yok-nafiz-caglar-yasar-vsnnp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gözlerin gözlerimden kaçıyor ama 

Gönlümdeki alevden kaçış yok 

Adımlarımdan soluk oluk kaçarsın ama 

Kadere hikmetten sual olmaz kaçış yok 

Gülüşün benzer nadide bir güle 

Ben şimdi boynu bükük lale 

Çok naz beni usandırıyor ama 

Kaçış yok beni anacaksın tenimle 

Oyunumun yeni yorgunluğunda 

Bozkırın taze susuzluğunda 

Döktüğüm çeşm-i ahuzarımda 

Kaçış yok sen her an biraz daha 

Bu hikaye ne Mecnun ne Kerem 

Daha da yüce kıskanır Adem 

Sen gidersin biliyorum ama ben 

Kaçış yok düşemem ahu gözlerinden', 'Gözlerin gözlerimden kaçıyor ama  Gönlümdeki alevden kaçış yok  Adımlarımdan soluk oluk kaçarsın ama  Kadere hikmetten sual olmaz kaçış yok ...', ARRAY['Türk Edebiyatı','Şiir','Nafiz Çağlar Yaşar']::text[], 8.5, '{"poet":"Nafiz Çağlar Yaşar","poet_slug":"nafiz-caglar-yasar","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kacis-yok-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ab -ı Hayatımsın Atam', 'ab-i-hayatimsin-atam-alper-kuruk-f36z2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '10 Kasımla başlayacak benim her yılım

Ağlayacağım,ağlayacağım güler gibi,

10 Kasım dökülürken ağzımdan

Titreyecek dudaklarım tiril tiril

Sanki MUSTAFA KEMAL der gibi.

Okşasın diye saçlarımı

Terkedeceğim rüzgârlara,

Hür eser bu toprakta yeller

MUSTAFA KEMAL eser gibi.

Yaşlı kirpiklerim arasından gözlerim

Dalar ölüm karanlığına

Seçer birini ölümsüzler içinden

MUSTAFA KEMAL''i seçer gibi.

Sessizliğe açılmış kulaklarım

Süzer sessizlikten tek ses

Bitmeyen bir âhenkle duyarım

MUSTAFA KEMAL''i duyar gibi.

Koklarım,koklarım hür havayı

Bir canlılık dolar ciğerlerime

MUSTAFA KEMAL dolar gibi.

MUSTAFA KEMAL emrediyor başımda

Emrediyor büyük kumandan

Ben dimdik duracağım yanı başında

Ölmeyen nefer gibi.

Yılda bir gündür 10 Kasım

Üzüntü orduları için sefer gibi,

Eyvah! gitti elden başbuğ

Düştü başlarımız önümüze

Düştü fethedilmiş kaleler gibi.

10 Kasımla başlayacak benim her yılım

Ağlayacağım,ağlayacağım güler gibi,

Noel Baba,benim bu yılbaşlarımda

Beni sevindirmek istersen

İstemem ben oyuncak filan

Onları çocuklara at bacalarından

Bana tek MUSTAFA KEMAL''imi ver

Ben MUSTAFA KEMAL''imi isterim

Yaşamağı ister gibi.

Ab -ı hayatımsın Ata''m

İçerim fikirlerini tekrar tekrar içerim

Ben sana kanamam,ben sana doyamam...', '10 Kasımla başlayacak benim her yılım Ağlayacağım,ağlayacağım güler gibi, 10 Kasım dökülürken ağzımdan Titreyecek dudaklarım tiril tiril San...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/ab-i-hayatimsin-atam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Yürek Benim', 'bu-yurek-benim-hasan-kutsal-eker-on7ui', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Benim kapına gelen

Benim bu kör karanlıkta

Bir yürek bıraktım kor gibi yanan

Benim tutuşan isyankâr çılgın

Benim kapının zilini çalan

Sağır bir sessizlik içinde boğulan

Umursamaz bir sevginin kıskacında

Çığlıklarımı duyuyor musun

Varılamamış uzaklarda çaresiz

Çırpınan bir çift kırık kanat

Benim mutsuzluğum biliyor musun

Sana varan tüm yollarım kesilmiş

Yönsüz, pusulasız bir deli adam

Sana koşuyor, yelkenleri param parça

Bir teknede, umutsuz ama yılmadan

Meydan okuyor tüm zamanlara

Duymuyor yıkılan umutların sesini

Direnen bir yüreği var tüm olmazlara

Savaşının  en yoğun anında

Düşüyor fırtınanın gözüne

Yalancı düşlerinin verdiği

Umutlar üretiyor, iyimser

Biri var çıkıp geliyor ansızın

Bayram yerine dönüyor yüreğim', 'Benim kapına gelen Benim bu kör karanlıkta Bir yürek bıraktım kor gibi yanan Benim tutuşan isyankâr çılgın Benim kapının zilini çalan Sağır ...', ARRAY['Türk Edebiyatı','Şiir','Hasan Kutsal Eker']::text[], 8.5, '{"poet":"Hasan Kutsal Eker","poet_slug":"hasan-kutsal-eker","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bu-yurek-benim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uğultulu (Attila İlhan''ın anısıan)', 'ugultulu-attila-i-lhan-in-anisian-yusuf-ter-b1o7z', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gök  görmeye  iner  aşağıya

Palazlanır  rüzgar toprak ile kucaklaşır

Deniz kabarır  balıklar kıyıya yanaşır 

Kurumuş ağaç dik durur 

Meydan okur güneşe

Attila ilhan  nar kırmızı 

Bahçelerde gül kokusu verir 

Memleketin unutulmuş 

Yorgun ustalara çığ düşer

Korkulu rüyalara 

Ustamızdan bir şiir iner

‘’An Gelir,,Attila İlhan yeniden doğar…

Yusuf Ter  11.10.05

Saat 20:18 İsviçre 

Not: Sevgili  Abimiz   Büyüğümüz   Attila İlhan''ın  anısına   yazmış olduğum şiiri  paylaşım adına paylaşıyorum  Ailesine sabır  dostlarımızada başımız sağolsun...', 'Gök  görmeye  iner  aşağıya Palazlanır  rüzgar toprak ile kucaklaşır Deniz kabarır  balıklar kıyıya yanaşır  Kurumuş ağaç dik durur  Meydan ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ter']::text[], 8.5, '{"poet":"Yusuf Ter","poet_slug":"yusuf-ter","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ugultulu-attila-ilhan-in-anisian-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah Şu Kadın', 'ah-su-kadin-yakup-icik-c77ry', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ah..var ya şu kadın

Hazzını sokuyor damağıma

Deli desem deli değil

Bilmemki

Beni deli ediyor

Az sonra yanağımda gülücüğü

Öpmeden izi kalıyor kıpkızıl

Ah..şu kadın

Beni baştan çıkartmak mı ne niyeti

Direncimi kırıyor

Allı pullu bakışları

Dokunmadan her yerimi okşuyor

Mos-mor bedenim sanki

Sorsam mı ki, derdi ne

Utanıyorum

Soramıyorum ki

Ah..şu kadın var ya...', 'Ah..var ya şu kadın Hazzını sokuyor damağıma Deli desem deli değil Bilmemki Beni deli ediyor Az sonra yanağımda gülücüğü Öpmeden izi kalıyor...', ARRAY['Türk Edebiyatı','Şiir','Yakup Icik']::text[], 8.5, '{"poet":"Yakup Icik","poet_slug":"yakup-icik","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ah-su-kadin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Postacılar', 'postacilar-yakup-icik-4vjqg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Eskiden

Bir zarf dolusu

Sevinc getirirlerdi postacilar

Simdi

Elem, keder, dert getiriyorlar

Bir zarf icinde Postacilar! (*)', 'Eskiden Bir zarf dolusu Sevinc getirirlerdi postacilar Simdi Elem, keder, dert getiriyorlar Bir zarf icinde Postacilar! (*)...', ARRAY['Türk Edebiyatı','Şiir','Yakup Icik']::text[], 8.5, '{"poet":"Yakup Icik","poet_slug":"yakup-icik","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/postacilar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neredesin?', 'neredesin-hilal-ozdemir-mqa02', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen yoksun şimdi ufkumda

İnliyor acılar çaresizce 

Bir balık tutumu hayat

Afedersiniz

Ne alırdınız? 

Bir sorumluk

Bir yudumluk belki

Çoğu boşa geçmiş zamanların

Hangisi geri gelirki? 

Tutmak istesen tutamazsın

Kopmak istesen kopamazsın

Maziden

Çeker alır seni 

Götürür eskilere

Çoğu boş zamanlara

Ya dopdolu geçenlere

Seninle

Götürür mü dersin

İşte yine inliyor nağmeler

Seni terennüm ediyor arsızca

Dön artık boş geçen zamanlara inat

Doldursun ufkumu gölgen

Sonra sen

Ellerin ellerime değmesede olur

Az yaklaş yanıma

Gözlerin gözlerimde kalsn

Sonra ne varsa sönsün alemde

Bir nefes alımı hayat

Senin yanında oılduktan sonra

Teşekkür ederim bir şey almıyorum

Hayatımı sana adıyorum...

   (05.10.2005)

        İstanbul', 'Sen yoksun şimdi ufkumda İnliyor acılar çaresizce  Bir balık tutumu hayat Afedersiniz Ne alırdınız?  Bir sorumluk Bir yudumluk belki Çoğu bo...', ARRAY['Türk Edebiyatı','Şiir','Hilal Özdemir']::text[], 8.5, '{"poet":"Hilal Özdemir","poet_slug":"hilal-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/neredesin-78-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdalar kanatlanmış.', 'sevdalar-kanatlanmis-i-shak-ozlu-mvlia', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kimi şerbet ister yangına kimi şarap,

Sönmeyince gözlerinde tüter bir serap.

Ya benim deli gönlüm seni görmek ister,

Görmeyince gecem zindan gündüzüm harap.

Gündüzün bekçisi güneş kavuştu ay''a,

Geçiyor biçare ömrüm gün saya saya.

Sevdalar kanatlanmış uçuyor semada,

Kanadı kırık çaresizim kaldım yaya.

Yoluna gurbet ellerde yad olduğum yar,

Bahar geldi güz geçti hasretim dağlarca.

Vuslat yolunda gönlümüze düşmeden kar,

Yaban değilsem kalbine haydi durma sar.', 'Kimi şerbet ister yangına kimi şarap, Sönmeyince gözlerinde tüter bir serap. Ya benim deli gönlüm seni görmek ister, Görmeyince gecem zindan...', ARRAY['Türk Edebiyatı','Şiir','İshak Özlü']::text[], 8.5, '{"poet":"İshak Özlü","poet_slug":"i-shak-ozlu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sevdalar-kanatlanmis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beddua 2', 'beddua-2-huseyin-sibic-53zfr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Öyle dertlere düş ki canından bık,

Kötü adından utan,şanından bık,

Düşte bir namerde her anından bık,

Öyle kahrol ki, ölmek iste,ölme...

Rezil ol her söylediğin sözünden,

Kahır eksik olmasın hiç yüzünden,

Sızıların hiç dinmesin gözünden,

Kanlı yaş ağla, silmek iste,silme...

Canın çıkmasın,şu dünyadan cay da,

Derdine ne çare bul,ne de fayda,

Bana ettiğinden nedamet duy da,

Felç ol,yürüme, gelmek iste,gelme...

Bir bilseydin aşka can ektiğimi,

Her acılara kefen diktiğimi,

Senin uğruna neler çektiğimi,

Düşün,düşün de bilmek iste,bilme...

Ömrünce yaslı kal,mutluluk görme,

Her derde erde mutluluğa erme,

Dilerim gözyaşından eksik verme,

Her zaman ağla, gülmek iste,gülme...

(09.10.2005)', 'Öyle dertlere düş ki canından bık, Kötü adından utan,şanından bık, Düşte bir namerde her anından bık, Öyle kahrol ki, ölmek iste,ölme... Rez...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sıbıç']::text[], 8.5, '{"poet":"Hüseyin Sıbıç","poet_slug":"huseyin-sibic","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/beddua-2-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'An Gelir*', 'an-gelir-umut-gul-h506w', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '''Ben sana mucburum bilemezsin''

                   Attila İlhan

Adını mih gibi çakmıştın beynimize

Sevda dolu dizelerle,

Bilesinki öksüz koydun bizleri

Büyük üsdat gidişinle....

Nice savdalar yaşattın bize

Nice miraslar bıraktın

Başında eksiltmediğin kasketinle

Nice mecburiyetler

An gelir Attila İlhan Gelir

An gelir bir şair ölür

Bakarsın Umut Gül de yok olur

İşte öyle bir an gelir....

Saygıyla................', '''Ben sana mucburum bilemezsin''                    Attila İlhan Adını mih gibi çakmıştın beynimize Sevda dolu dizelerle, Bilesinki öksüz koyd...', ARRAY['Türk Edebiyatı','Şiir','Umut Gül']::text[], 8.5, '{"poet":"Umut Gül","poet_slug":"umut-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/an-gelir-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aspirin Gibisin', 'aspirin-gibisin-yakup-icik-kooxa', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aspirin gibisin be kadın.

Az acımıtırak.

Birazda ekşimsi.

Bütün ağrılarımı dindiriyorsun..

Ne zaman başlarsa bir sızı yüreğimde

Ya da can sıkıntım.

Ya da bedenimin her hangi bir yerinde

Tek yaptığım,

Seni düşlemek

Geçirtiyorsun! 

Sahi ya be kadın! 

Senin hiç ağrıların olmaz mı? 

Göğsünde bir yerlerde.

Yada başın ağrımaz mi? 

İnan sen benim tek ilacımsın.

Aspirin gibisin kadın!', 'Aspirin gibisin be kadın. Az acımıtırak. Birazda ekşimsi. Bütün ağrılarımı dindiriyorsun.. Ne zaman başlarsa bir sızı yüreğimde Ya da can sı...', ARRAY['Türk Edebiyatı','Şiir','Yakup Icik']::text[], 8.5, '{"poet":"Yakup Icik","poet_slug":"yakup-icik","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/aspirin-gibisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Önümden Çekil Geleceğimi Göremiyorum!', 'onumden-cekil-gelecegimi-goremiyorum-caglar-demir-cj98c', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kaç yemin ettim kimbilir

seni unutmak üzerine

Kaç mevsim geçti

sensizlikle yüzyüze

Oysa

Hiçbir sehir,

hiçbir yemin

hiçbirmevsim

hiçbir sabah

bana seni unutturmuyor

Hep sil baştan benim filmim

Bir çift esmer göz hep yanı başımda

Dönüyorum dolaşıyorum sen

Bir bilsen

Artık hükmedemiyorum

bedenime sensizliği

N''lur

Önümden çekil 

geleceğimi göremiyorum...', 'Kaç yemin ettim kimbilir seni unutmak üzerine Kaç mevsim geçti sensizlikle yüzyüze Oysa Hiçbir sehir, hiçbir yemin hiçbirmevsim hiçbir sabah...', ARRAY['Türk Edebiyatı','Şiir','Çağlar Demir']::text[], 8.5, '{"poet":"Çağlar Demir","poet_slug":"caglar-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/onumden-cekil-gelecegimi-goremiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman ve Zamantı', 'zaman-ve-zamanti-yakup-icik-a9um0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Zamanmı, durulacak zaman degil

Bak Zamantı (*)         ırmagına

Duruyor mu hiç.. akıyor.

Zamanının kiymetini biliyorda!', 'Zamanmı, durulacak zaman degil Bak Zamantı (*)         ırmagına Duruyor mu hiç.. akıyor. Zamanının kiymetini biliyorda!...', ARRAY['Türk Edebiyatı','Şiir','Yakup Icik']::text[], 8.5, '{"poet":"Yakup Icik","poet_slug":"yakup-icik","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/zaman-ve-zamanti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Memleketimsin', 'memleketimsin-pinar-koc-ntbwb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Memleket hasreti çekiyorum.

Güneş bir başka doğar 

Benim memleketimde! 

Güneş bir başka batar...

Bahar bir başka,

Yaz bir başkadır,

Ağaçları bir başka filizlenir

Nisan yağmurlarıyla...

Yıldızları bir başka parlar

Sabahlara dek...

Havası bir başkadır

Benim memleketimin,

Suyu bir başka...

İnsanları sıcak kanlıdır oldum olası! 

Goncaları bir başka kokar

Memleketimin,

Yeşilleri bir başka...

İŞTE SEN

MEMLEKETİMSİN...

                                                       2001    UĞURBÖCEĞİ', 'Memleket hasreti çekiyorum. Güneş bir başka doğar  Benim memleketimde!  Güneş bir başka batar... Bahar bir başka, Yaz bir başkadır, Ağaçları...', ARRAY['Türk Edebiyatı','Şiir','Pınar Koç']::text[], 8.5, '{"poet":"Pınar Koç","poet_slug":"pinar-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/memleketimsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yöneticiler', 'yoneticiler-yakup-icik-hq0vc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kırk yıldır aynı senfoni / dinlediğim

Okumuş diye / saygı ile eğildiğim

Poliktikacılar..Siyasetçiler..ilim-bilim adamları

ve aydınlar

inan bıktım sizlerden

Plağın bir yüzü daha var

Lütfen çevirinde dinleyim.', 'Kırk yıldır aynı senfoni / dinlediğim Okumuş diye / saygı ile eğildiğim Poliktikacılar..Siyasetçiler..ilim-bilim adamları ve aydınlar inan b...', ARRAY['Türk Edebiyatı','Şiir','Yakup Icik']::text[], 8.5, '{"poet":"Yakup Icik","poet_slug":"yakup-icik","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/yoneticiler-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küçük önemsizlikler', 'kucuk-onemsizlikler-pinar-koc-izlzp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dışarıda ramazan davulcusu,

Ve odamdaki ilaç kokusu…

Yaşamımızın küçük ve önemli parçaları…

Sessiz bir koridor,

Hafifçe duyulan acı iniltileri…

Sabaha kadar yanmakta olan lambalar tepemde…

Elimde kağıdım,kalemim,

Yerle birleşmekten hiç kurtulamayan

Ayakkabılarımın içindeki yorgun ayaklarım…

Ve gözlerim..! 

Ve uykusuz,ve yorgun,

Ve hayalet gözlerim…

Kapanmak bilmeyen gözlerim…

Yaşamımın küçük ve önemli parçaları…

Masamda radyom,

Ağzına kadar dolu bir kül tablası,

Bir bitmek bilmeyen flaster,

Yarısı boş bir bardak,

Anahtarlar,

Sigara paketleri başucumda,

Ve defterim kalemim bir köşede…

Ve acı iniltileri ve gözlerim,

Ve yorgun ayaklarım…

Yaşamımın küçük ve önemli parçaları…

Ve içimde kocaman bir özlem,

Hepsini bir anda silen….. 

                                                  08.12.2001      01:20', 'Dışarıda ramazan davulcusu, Ve odamdaki ilaç kokusu… Yaşamımızın küçük ve önemli parçaları… Sessiz bir koridor, Hafifçe duyulan acı iniltile...', ARRAY['Türk Edebiyatı','Şiir','Pınar Koç']::text[], 8.5, '{"poet":"Pınar Koç","poet_slug":"pinar-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/kucuk-onemsizlikler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah Felek', 'ah-felek-yavuz-agir-2ivee', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ah felek,zalım felek

Gel etme eğleme

Şu gönlüme eziyet eyleme

Bir kötüye düşürüp te söyletme

Uslanki sefan olsun

Süslenki güzel olsun

Vursun davullar,çalsın zurnalar

Oynaki ocağın tütsün

Düğünün düğün olsun..

Ah felek,şaşkın felek

Gel etme eyleme

Beni yolumdan eyleme

Şu garip halim bakıpta gülme

Dillere düşürüp eğlenme

Uslanki yüzün olsun

Sevgiye sefan olsun

Vursun davullar,çalsın zurnalar

Oynaki ocağın tütsün

Düğünün düğün olsun....', 'Ah felek,zalım felek Gel etme eğleme Şu gönlüme eziyet eyleme Bir kötüye düşürüp te söyletme Uslanki sefan olsun Süslenki güzel olsun Vursun...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Ağır']::text[], 8.5, '{"poet":"Yavuz Ağır","poet_slug":"yavuz-agir","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/ah-felek-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkmı-dişmi?', 'askmi-dismi-pinar-koc-5ucvu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir diş ağrısı mıydı sadece

Beynimi zonklatan, 

Yoksa ümitsiz bir aşk mıydı

Çaresizliğin derinlerinde fırtınalar kopartan! 

Fark eder mi? 

Yoksa kardeş miydi

Çaresizliğim ve ağrıyan dişim... 

Hangisini doktora götürmeliydin? 

Kim yok ederdi bu iki acıyı birden? 

İkisi de başımı ağrıtıyor, 

İkisi de uyutmuyordu kızıl sabahlara dek...

Dişime mi yanayım yoksa aşkıma mı?        

Hangi beyin kabul ederdi,hangi mantık? 

Dişimin ağrısı kalbime,

Kalbimin ağrısı dişime vuruyordu.

Hangisini çektirsem daha mutlu olurdum,

Veya hangisi ömür boyu çekilirdi...

Hangisi daha az ağlatırdı beni

Veya hangisi tez elden öldürürdü...

Bir diş ağrısı mıydı sadece

Beynimi zonklatan; 

Yoksa çaresiz bir aşk mıydı,

Ümitsizliğin derinlerinde

Fırtınalar kopartan…

                                                                    13.9.2002       21:39', 'Bir diş ağrısı mıydı sadece Beynimi zonklatan,  Yoksa ümitsiz bir aşk mıydı Çaresizliğin derinlerinde fırtınalar kopartan!  Fark eder mi?  Y...', ARRAY['Türk Edebiyatı','Şiir','Pınar Koç']::text[], 8.5, '{"poet":"Pınar Koç","poet_slug":"pinar-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/askmi-dismi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Annem ve Çerçevem', 'annem-ve-cercevem-yakup-icik-9sww5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ben gurbetime giderken

annem duvara asmış beni,

çerçevemin camından öpüp

...gittiğimin akşamı

dantelden sırmalarla süslemiş asılı kenarlarımı

gurbete gidişime çok içerlemiş

boş boş bakışlarımın çerçevemin camından odaya

yüreklenmiş annem karşıma geçip, ağlamış.

her namazının sonunda

duvardaki asılı çerçevenin camındaki bana dualarını yollamış! 

benim habersizliğimi bildiğinden

geldiğim günü okuyayım diye,

nazar muskaları gibi yazmış!', 'ben gurbetime giderken annem duvara asmış beni, çerçevemin camından öpüp ...gittiğimin akşamı dantelden sırmalarla süslemiş asılı kenarlarım...', ARRAY['Türk Edebiyatı','Şiir','Yakup Icik']::text[], 8.5, '{"poet":"Yakup Icik","poet_slug":"yakup-icik","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/annem-ve-cercevem-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstimboT', 'i-stimbot-asima-azra-q4yds', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Zordur fırtınada kalmış istimbot durumu

kurtarmaya çalışıp paçasını batacaktır 

ve hafifleyecektir denize gömüp suçunu…

İnandırıcı bulmamalı suskunluğunu

bu boyun büküş riya ürünü olacaktır

ve çarmıhta söyleyecekleri ağız oyunu!', 'Zordur fırtınada kalmış istimbot durumu kurtarmaya çalışıp paçasını batacaktır  ve hafifleyecektir denize gömüp suçunu… İnandırıcı bulmamalı...', ARRAY['Türk Edebiyatı','Şiir','Asima Azra']::text[], 8.5, '{"poet":"Asima Azra","poet_slug":"asima-azra","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/istimbot-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Hükmü Var', 'ne-hukmu-var-omer-yildiz-r05mo', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen

      Yokken

             Ağaran tanın 

                           Ne hükmü var? ...

Aydınlansa da günüm,

                          Ruhum

                                 Karanlıkta....

Kul geçmez 

             Toprağı

                    Sıla tutmuşsun...

                                Sılaya varmaz, 

                                          Çiğnenmez yolların 

                                                             Ne hükmü var? ...

Aşık değilsen,

               Gülmüyorsa yüzün...

                            İçinde doğan güneş

                                       Aydınlatmıyorsa

                                                   Sevdiklerini,

El ele dolaşmıyorsan,

                                Sarılmıyorsan,

                                       Koklaşmıyorsan...

Mehtapta,

         Sahilde

            Yakamozlar 

                          yoksa. 

 Kulağına

        Uaşan

            bir türkü

                 İçindeki

                    Boşlukta kalıyorsa,

Sevmenin, 

          Yaşamanın

                      Ölmenin,

 Yada

       Benim olmanın 

                       Ne hükmü var? ...', 'Sen       Yokken              Ağaran tanın                             Ne hükmü var? ... Aydınlansa da günüm,                           Ruhu...', ARRAY['Türk Edebiyatı','Şiir','Ömer Yıldız']::text[], 8.5, '{"poet":"Ömer Yıldız","poet_slug":"omer-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/ne-hukmu-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dua', 'dua-bahaettin-karakoc-27y4r', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Allah’ım, yıldızlara ağız ver, dil ver; 

Benimle konuşsunlar...

Göz kırpıp durmasınlar uzaklardan

Akşam çayında

Şeker gibi eriyip tükenmesinler bardağımda

Hepsini tanımak,

Hepsiyle konuşmak istiyorum.

Allah’ım, güneşe göz, kirpik ve kaş ver 

Kendi ateşiyle kendini pişirmesin... 

Gücünü biliyorum, gururunu da 

Bir de yüreği olsun 

Ve de şarkılara yatkın bir dili, 

Sesini duymak istiyorum.

Allah’ım, dağları uykuyla tanıştır,

Benim gibi düş görsünler, hayâl kursunlar

Dört mevsim güzeldir bütün dağlar

Bir de konuşsalar, şiir yazsalar

Bir dilleri var da ben mi anlamıyorum

Allah’ım, dağlarla konuşmayı nasip et bana

Rızanla eş değer bilişmek istiyorum.

Allah’ım, denizlere cemalinle yansı

Sevgiyi tanısın kıyılarla öpüşürken

Her can

Hem nigarı tanısın hem de nigarendeyi

Gökteki galaksilerle doldur içimi

Dinimle tatlandır yeryüzünü

Dilimle kanatlandır diller coğrafyasında

Her yere ulaşmak istiyorum.

Allah’ım, dualarımı bereketlendir

Ve hep gülümse...

Beni duyduğunu biliyorum.

Bahaeddin KARAKOÇ', 'Allah’ım, yıldızlara ağız ver, dil ver;  Benimle konuşsunlar... Göz kırpıp durmasınlar uzaklardan Akşam çayında Şeker gibi eriyip tükenmesin...', ARRAY['Türk Edebiyatı','Şiir','Bahaettin Karakoç']::text[], 8.5, '{"poet":"Bahaettin Karakoç","poet_slug":"bahaettin-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/dua-123-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ak Ellerim', 'ak-ellerim-bahaettin-karakoc-rl8n9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Beş vakte yeşeren kutsal orman

Yaprak yaprak ellerim

Yapışmış aşk atının gök yelesine

Pamuk sularında ak-pâk ellerim…

Öylesine insan ve Müslüman ki

Öylesine dost, öylesine can ki

Ve öylesine yakın ki

Allah’a, adak ellerim…

Her sabah kaktığımda turfanda

İki esrik ak kuğudur abdest sularında

Kelle sökmeye başlar iman tarlamda

Başak başak ellerim…

Yalan yok, korku yok, kin yok

Döküldü dünyanın ham cümbüşüne

Sonsuza kol atmanın düşleri

Bayrak bayrak ellerim…

Anaç keklik gibi kızgın yatanda

Yüreğimin üstüne üstüne

Besmele göynüğüdür Kur’ân tutanda

Sanki tutmaz öper, dudak ellerim…

Beş vakte yeşeren kutsal orman

Dal budak yaprak ellerim

Vığıl vığıl ışıklarla konuşur

Cümle kötülükten uzak ellerim…

Bahaeddin KARAKOÇ  (Ay Şafağı Çok Çiçek- Beyan Yay.  İstanbul / 1998)', 'Beş vakte yeşeren kutsal orman Yaprak yaprak ellerim Yapışmış aşk atının gök yelesine Pamuk sularında ak-pâk ellerim… Öylesine insan ve Müsl...', ARRAY['Türk Edebiyatı','Şiir','Bahaettin Karakoç']::text[], 8.5, '{"poet":"Bahaettin Karakoç","poet_slug":"bahaettin-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ak-ellerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzaklardan sor bana', 'uzaklardan-sor-bana-vedat-okkar-vsj07', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seni nasıl severim, uzaklardan sor bana 

Hasretim olma gel yanıma 

Kucaklarım seni ben kollarımla doya, doya 

Gelmesende yanıma, uzaklardan gül bana 

Bir bakışın senin, canıma can katar 

Bu kalpte senin yüreğin yatar 

Yanağımdaki öpüşlerin artar 

Gelmesende yanıma, uzaklardan gül bana 

Üç senede beklerim yeter ki benim olasın 

Bu derdime benim ancak sen derman olasın 

Yeterki bebeğim sen mutlu olasın 

Gelmesende yanıma, uzaklardan gül bana.', 'Seni nasıl severim, uzaklardan sor bana  Hasretim olma gel yanıma  Kucaklarım seni ben kollarımla doya, doya  Gelmesende yanıma, uzaklardan ...', ARRAY['Türk Edebiyatı','Şiir','Vedat Okkar']::text[], 8.5, '{"poet":"Vedat Okkar","poet_slug":"vedat-okkar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/uzaklardan-sor-bana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sabah', 'sabah-vedat-okkar-ehl99', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dize gelir yanlızlıklar, Umutla baktığında 

Yok olsun acılar, bu günün sabahında 

Dertlerimiz bitecek,mutluluğumuz sürecek 

Yok olsun acılar, bu günün sabahında 

Yüzümde gülcükler olsun isterim 

Sevgilim artık geri gelsin isterim 

Seninle mutlu bir yuva düşleri 

Yok olsun acılar, bu günün sabahında 

Sevgilim bana dostum diyor 

Seninle çok iyi arkadaş oluruz diyor 

İnsan sevdiğinle dost kalamıyor 

Yok olsun acılar, bu günün sabahında.', 'Dize gelir yanlızlıklar, Umutla baktığında  Yok olsun acılar, bu günün sabahında  Dertlerimiz bitecek,mutluluğumuz sürecek  Yok olsun acılar...', ARRAY['Türk Edebiyatı','Şiir','Vedat Okkar']::text[], 8.5, '{"poet":"Vedat Okkar","poet_slug":"vedat-okkar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sabah-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Şiir', 'son-siir-vedat-okkar-3tf9e', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hangi şair anlatabilmiş derdini, 

Hangi şair ölmemiş kahrından.. 

Şiirlerim bile bile yabancı artık; 

İçimdeki çocuğu küstürdüler, 

Hangi şiire demir atsam, 

Son şiirimde. 

Hangi keder arınmış günahlarından, 

Hangi ayrılık hafifletmiş ölümleri; 

Kendimden çıktım artık, 

İçimdeki çocuğa arıyorum, 

Kalabalık ortamlara koşuyorum; 

Bir tanıdık arıyorum, elini tutacak.. 

Bütün yüzler yabancı, son şiirimde. 

Şimdi kaybolmuş bir şehre döküyorum küllerimi, 

Ne tutan kaldı, ne ağlayan bir tek senden başka; 

Vurdular beni, yaraladılar; 

Aldılar beni, ellerimi; 

Sahipsiz bıraktılar son şiirimde! ... 

Ne gökte ay gülümsüyor 

Ne deniz kokusu havada. 

Ne de yıldızlar parıldıyor. 

İşte son şiirimi yazdığım bu akşam da.', 'Hangi şair anlatabilmiş derdini,  Hangi şair ölmemiş kahrından..  Şiirlerim bile bile yabancı artık;  İçimdeki çocuğu küstürdüler,  Hangi şi...', ARRAY['Türk Edebiyatı','Şiir','Vedat Okkar']::text[], 8.5, '{"poet":"Vedat Okkar","poet_slug":"vedat-okkar","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/son-siir-33-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kafana göre', 'kafana-gore-vedat-okkar-0kwcn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir hayat ki? 

İçi,nde yanlız ben 

ve....... 

Beni sevenlerden anlıyanlardan oluşan bir dünya 

Kimse anlamıyor beni bu dünyada 

Çektiğim acıları dertleri anlamıyorlar 

Hergün göz yaşı döktüğümü 

Acılarla kendimi yediğimi biliyorlar 

Bıktım 

Beni ağlatanlardan 

Beni anlamıyanlardan bıktım 

Beni sevenler bile anlamıyorlar beni 

Ailem bir yandan 

Eller bir yandan 

Her gün yiyiyorlar beni 

Güzel geçen bir günüm olmadı 

Hep ağladım hep sızlandım yaşadığım şu günlerde 

Yaşayamadım dilediğim gibi şu dünyada 

Bence hayat deymez hiç bir şeye 

Yaşamak istiyorsan arkadaş 

Takılacaksın kafana göre.', 'Bir hayat ki?  İçi,nde yanlız ben  ve.......  Beni sevenlerden anlıyanlardan oluşan bir dünya  Kimse anlamıyor beni bu dünyada  Çektiğim acı...', ARRAY['Türk Edebiyatı','Şiir','Vedat Okkar']::text[], 8.5, '{"poet":"Vedat Okkar","poet_slug":"vedat-okkar","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/kafana-gore-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Al canımı razıyım öyle git', 'al-canimi-raziyim-oyle-git-vedat-okkar-34m9t', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kırmızı gülleri yoluna serdim 

Ben seni görünce kendimden geçtim 

Vedo derki; seni yürekten sevdim 

Gideceksen al canımı öyle git 

Hatasız kul olurmu söyle güzelim 

Ben senin yokluğunu bile özlerim 

Kalbimin atışı, gözümün nuru 

Gideceksen alcanımı öyle git 

Canımı almassan çıkmaz bu beden senden 

Ölsemde vazgeçemem ben senin gibi güzelden 

Gidersen bir gün bu elden 

Al canımı razıyım öyle git.', 'Kırmızı gülleri yoluna serdim  Ben seni görünce kendimden geçtim  Vedo derki; seni yürekten sevdim  Gideceksen al canımı öyle git  Hatasız k...', ARRAY['Türk Edebiyatı','Şiir','Vedat Okkar']::text[], 8.5, '{"poet":"Vedat Okkar","poet_slug":"vedat-okkar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/al-canimi-raziyim-oyle-git-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Attila İlhan''a', 'attila-i-lhan-a-ulug-celik-7zqnm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '‘Bir ustayı kaybettik bugün

Yitirdik onu Sisler Bulvarın’da

Kelimeler oyuncağıydı onun

İmgeler parmaklarında hala…’

                                 Uluğ Çelik

ATTİLA İLHAN ‘A

Biz sana mecburuz bilemezsin,

Adını mıh gibi aklımızda tutuyoruz.

Büyüdükçe büyüyor gözlerimiz. 

Biz sana mecburduk bilemezsin, 

İçimizi  seninle ısıtıyoruz…

İçimizde keder 

Uzak bir telefonda ağlıyor

Yağmurlu genç kadınlar…

Aysel gitti mi  başından sen ona göreydin? 

Ölümün birden olacak seziyordun 

Ne kötüydün, ne  karanlık,ne de çirkin

Şimdi elimizde var hüzün…

 Elinden tutamadık düşecektin yoksa

Yağmur seni götürdü şimdi uzaklara.

Şenlik dağıldı bir acı yel kaldı bahçede yalnız,

O mahur beste çalar  Müjgan''la biz ağlaşırız

Sisler bulvarı''nda seni kaybettik

Sisler bulvarı''ndan geçmediin bugün

Sisler bulvarı öksüz biz öksüzüz

Karanlıkta sana doğru uzanmış ellerimiz

Gözlerimiz gözlerini arıyor durmadan 

Nerdesin? 

Geceleyin ışıkları söndürdüğümüz zaman 

Senin şiir kitaplarından sızan aydınlık,

Elinde uyuyakaldığı heyecanlı roman,

Zeynep’le  bekliyoruz mutlaka geleceksin,

Başladığın filmi birlikte bitireceksin.

Görünmez bir mezarlıktı zaman 

Şairler dolaşıyor saf saf 

Tenhalarında şiir söyleyerek 

kim duysa / korkudan öldü

-tahrip gücü yüksek- 

Saatlı bir bomba patladı 

An geldi

Attilâ İlhan öldü…

11/10/2005

Saat:23:48

Erzurum', '‘Bir ustayı kaybettik bugün Yitirdik onu Sisler Bulvarın’da Kelimeler oyuncağıydı onun İmgeler parmaklarında hala…’                         ...', ARRAY['Türk Edebiyatı','Şiir','Uluğ Çelik']::text[], 8.5, '{"poet":"Uluğ Çelik","poet_slug":"ulug-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/attila-ilhan-a-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unuturum desem', 'unuturum-desem-vedat-okkar-35wty', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Unuturum desem, bitsin desem, 

Varya o gözlerin bitirir beni. 

Bitsin desem, bırak desem, 

Teninin kokusu burnuma geldiği an varya bitirir beni 

Sen varya sen, sonsuzluğa giden güneş ışığım gibi, 

Yanımda olduğun zaman, bedenimi, canımı, ruhumu aydınlatan. 

Sen varya sen, sevdiğimi tamamlayan 

Beni benimle bütünleyen, 

Ama bir tanem sen varya sen, 

Nefesimsin,canımsın, hayat kaynağımsın. 

Senin yatacak yerin yok 

Ya ben desem 

Benimde kalacak yerim yok 

Sen varya sen, sonsuzluğa giden bir bulut, ışığım gibi 

Sen varya sen, geceleri rüyama giren bir peri gibi, ruhuma girer aydınlatırsın beni.', 'Unuturum desem, bitsin desem,  Varya o gözlerin bitirir beni.  Bitsin desem, bırak desem,  Teninin kokusu burnuma geldiği an varya bitirir b...', ARRAY['Türk Edebiyatı','Şiir','Vedat Okkar']::text[], 8.5, '{"poet":"Vedat Okkar","poet_slug":"vedat-okkar","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/unuturum-desem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şair''in Ölümü..', 'sair-in-olumu-omer-golge-1n2kr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yürek kaleminin mürekkebi tükenmiş

Akıl kağıdına yazamamakta..

İmgeler öksüzce boyun bükerek

Ağlaşmaktalar bomboş odanda

Sen aşkın ve kavgaların şairi

Belki seyretmektesin şimdi..

Geride bıraktıklarını bir uzak ufukta

Devrilen her çınar boşluk bırakır

Sonsuzu kuşatan şu izafi zamanda

Fakat emin ol usta.....

Zamanda  çaresiz kalır

Aşkla sulanıp kavganla büyümüş

Şiirlerin karşısında

Sana elveda diyemiyorum

Biliyorum hep karşıma çıkacaksın

Aşk,özgürlük ve onur adına saplandığım

Her çıkmaz sokakta..........', 'Yürek kaleminin mürekkebi tükenmiş Akıl kağıdına yazamamakta.. İmgeler öksüzce boyun bükerek Ağlaşmaktalar bomboş odanda Sen aşkın ve kavgal...', ARRAY['Türk Edebiyatı','Şiir','Ömer Gölge']::text[], 8.5, '{"poet":"Ömer Gölge","poet_slug":"omer-golge","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sair-in-olumu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kış ve Yaz', 'kis-ve-yaz-vedat-okkar-s1ige', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Mutluluğun içinde buluştuk biz ikimiz 

Adı son derece güzel, mutluluktu bildiğimiz 

Sevginin adı tutsak, gözleride bilmediğim bir yasak 

Anlayamadığım bir ızdırap 

Kaderim beni kenetledi 

Oldu ya işte bir kış, birde yaz.', 'Mutluluğun içinde buluştuk biz ikimiz  Adı son derece güzel, mutluluktu bildiğimiz  Sevginin adı tutsak, gözleride bilmediğim bir yasak  Anl...', ARRAY['Türk Edebiyatı','Şiir','Vedat Okkar']::text[], 8.5, '{"poet":"Vedat Okkar","poet_slug":"vedat-okkar","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/kis-ve-yaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dedikodu', 'dedikodu-vedat-okkar-4t4ng', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ayaklanmış gece kuşları 

Balkonda dedikodu yaparlar 

Ne kadar çok anlatacak olayları 

Bazen sahuru bile unuturlar 

Sanki bütün konuşmuyolar da 

Ne istiyolar akşamlardan 

Hayriye kız, Sevtab''ın oğlu Mine''nin kızıyla geziyomuş 

Sanene! 

Duydum duydum hatta geçende Mine kızını iki gün eve kapamış 

Aaaa inanmıyorum demek ondan göremedim ben onları 

Bırakın artık bu olayları 

Kim kimle nerde sizene 

Herkez kendinden sorumlu değilmidir 

Onlarında Anneleri, Babaları yokmudur. 

Dedikoducu toplumlar yaratmıyalım 

Eğitimci öğretici toplum olalım 

Çocuklara yardımlara koşturalım 

Okumayı aşıyalım 

Gece kuşu olmayalım 

Varlığımızın farkına varıp, güzlliklerle dolalım arkadaşlar', 'Ayaklanmış gece kuşları  Balkonda dedikodu yaparlar  Ne kadar çok anlatacak olayları  Bazen sahuru bile unuturlar  Sanki bütün konuşmuyolar ...', ARRAY['Türk Edebiyatı','Şiir','Vedat Okkar']::text[], 8.5, '{"poet":"Vedat Okkar","poet_slug":"vedat-okkar","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/dedikodu-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur', 'yagmur-vedat-okkar-tpwx5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bugün yağmur yağmıyor. 

Elerime düşen güneş 

Bugün ateş yakmıyor 

Yüreğime düşen sen 

Duyuyor musun kalbimden yükselenleri? 

Kalbinin derinliğinden hissediyormusun 

Mavi bir gökyüzü sana yükseliyor benden 

Gülümseyen karbeyaz bulutlar arasından 

Açtım seni görünce yüreğimi sonuna kadar 

Renk renk çiçekler yolluyorum 

Kulağına en güzel aşk şarkılarını fısıldıyorum. 

Duysun cümle alem bu şarkıları 

Seni benden alamaz karanlıklar, çünkü mavi bir gökyüzü yolladım 

Yazıyorum iki cümle kadere, göğe, heryere 

Aşkım ben seni çok seviyorum diye...', 'Bugün yağmur yağmıyor.  Elerime düşen güneş  Bugün ateş yakmıyor  Yüreğime düşen sen  Duyuyor musun kalbimden yükselenleri?  Kalbinin derinl...', ARRAY['Türk Edebiyatı','Şiir','Vedat Okkar']::text[], 8.5, '{"poet":"Vedat Okkar","poet_slug":"vedat-okkar","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yagmur-223-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece ve Ben', 'gece-ve-ben-vedat-okkar-qsdi4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gece soğuk oluyor 

Ama içim sıcak 

Dışarda fırtına öncesi sessizlik 

İçimdeki mutlulukla bu işide dengeledik 

Ağaçlar yapraklarını döküyor sonbahar geldi 

Kalbimin mutluluğu artıyor sevgilim yoksa gerimi geldi 

Gece karanlıkları benden uzaklaştı 

Benim gönlümün ışığı yolumu aydınlattı 

Sabah güneşi sıcak beni yakmadı 

Çünkü o bir gülüşüyle kalbi mi yaktı 

İşte iki oda bir salon benim kalbim 

Işığımsın,sıcağımsın canıma can katasın sevdiğim...', 'Gece soğuk oluyor  Ama içim sıcak  Dışarda fırtına öncesi sessizlik  İçimdeki mutlulukla bu işide dengeledik  Ağaçlar yapraklarını döküyor s...', ARRAY['Türk Edebiyatı','Şiir','Vedat Okkar']::text[], 8.5, '{"poet":"Vedat Okkar","poet_slug":"vedat-okkar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gece-ve-ben-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Atilla İLHAN''a', 'atilla-i-lhan-a-vedat-okkar-4um3a', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Havalar soğuk, ağaçlar üşüyor 

Gönüller buruk, Şairler ölüyor 

Cıvıl cıvıl kuşlar yuvasından çıkmıyor 

Bir sonbahar sabahında 

Yağmur bugün ağlar gibi yağıyordu 

Bende aldım nasibimi damlalardan 

Gönlüm yağmur gibi yağmaya başladı 

Bir sonbahar sabahında 

Yinede içimde bir umut var 

Yeni şairler doğacak diye 

Seslerini duyurucak diye 

Hakkımız koruyacak diye 

Duyurmalıyız sesimizi özgürce, sevgi ile mutlu geleceğe 

(Nur içinde yat ATİLLA İLHAN benden sana olsun bu şiirim)', 'Havalar soğuk, ağaçlar üşüyor  Gönüller buruk, Şairler ölüyor  Cıvıl cıvıl kuşlar yuvasından çıkmıyor  Bir sonbahar sabahında  Yağmur bugün ...', ARRAY['Türk Edebiyatı','Şiir','Vedat Okkar']::text[], 8.5, '{"poet":"Vedat Okkar","poet_slug":"vedat-okkar","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/atilla-ilhan-a-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Teker Teker', 'teker-teker-vedat-okkar-khmz8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Biri biter diğerini yakarım günleri. 

ucu ucuna, 

birer birer tükenen. 

Biri biter diğerini yakarım geleceği. 

ardı ardına, 

yenisini bekleyen. 

Biri biter diğerini yakarım dostlukların 

teker teker, 

hep yalandan dostluklar, gerçeği bulmak adına. 

Biri biter diğerini yakarım umutların 

ucu ucuna 

umutlarım tükenmeden.', 'Biri biter diğerini yakarım günleri.  ucu ucuna,  birer birer tükenen.  Biri biter diğerini yakarım geleceği.  ardı ardına,  yenisini bekley...', ARRAY['Türk Edebiyatı','Şiir','Vedat Okkar']::text[], 8.5, '{"poet":"Vedat Okkar","poet_slug":"vedat-okkar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/teker-teker-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öğüt', 'ogut-abdulkadir-i-lyas-y1iuf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Btan gün doğar derler 

Yeter ki batmaya görsün

Bakan göz görür derler

Yeter ki bakmaya görsün...

Acı veren olur beter 

Daim haktan yanasın

Yanan yandı gayrı yeter 

Bir gün sen de yanarsın...

Diller susup yaşlar diner

Kutlu güne herkes kansın

Bir buseyle hasret biter 

Gözler gülmeye kansın...

Günler geçip devran döner

Ruhun bembeyaz karsın

Ölümü heran ol bekler

Dünden bugüne kalan karsın...

                                         (2005)', 'Btan gün doğar derler  Yeter ki batmaya görsün Bakan göz görür derler Yeter ki bakmaya görsün... Acı veren olur beter  Daim haktan yanasın Y...', ARRAY['Türk Edebiyatı','Şiir','Abdulkadir İlyas']::text[], 8.5, '{"poet":"Abdulkadir İlyas","poet_slug":"abdulkadir-i-lyas","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ogut-39-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ya Mevlam Hep Sana', 'ya-mevlam-hep-sana-nilgun-yuce-v7ok9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Öyle bir sevdaki anlatılabilse,

Yol sana doğru hiç geçilmez,

Mutlak olacak bunun sonu,

Çanlar çalacak,coşku dolu.

Ya Mevlam hep sana,

..................Hep sana doğru...

Kuluz kusur eyleriz

Doğduk yanlışı seçeriz

Mubarek günlerde eğiliriz,

Kurtar diye dua ederiz,

Ya Mevlam hep sana,

..................Hep sana doğru...

Kul sıkışmazsa,seni bilmez,

Hikmetin de sır bitmez,

Hak  adına alıp da Küp için,

Kurban kesilmez,

Ya mevlam hep sana,

..................Hep sana doğru...

Can beden de bitse de,

Ruh huzura  gelse de

Düşünmeden bunca sene,

Korka korka amel de,

Ya Mevlam hep sana 

..................Hep sana doğru...

Yaradan,Yaşatan sendin

Kimine  kötü.kimine  iyi,

Yaşamı da  sen verdin,

Varsa böyle   teslimiyet,

Ya Mevlam hep sana,

..................Hep sana doğru..

Kusurum vardır mutlaka,

Suyum ekmeğim aşımda,

Rızkımı hep verdin  bana,

Şükür olsun sunduklarına,

Ya Mevlam hep sana,

..................Hep sana doğru....', 'Öyle bir sevdaki anlatılabilse, Yol sana doğru hiç geçilmez, Mutlak olacak bunun sonu, Çanlar çalacak,coşku dolu. Ya Mevlam hep sana, .........', ARRAY['Türk Edebiyatı','Şiir','Nilgün Yüce']::text[], 8.5, '{"poet":"Nilgün Yüce","poet_slug":"nilgun-yuce","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/ya-mevlam-hep-sana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarhoşa', 'sarhosa-abdulkadir-i-lyas-wvzdt', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sormadan hiçneden niçin 

İçip her akşam hep senin için

İçin için ağlar yüreğin 

Aklım sende senin için...

Kararmadan hep dışın için

Son kadehi de iç benim için

Herkese içsen ömür yetmez 

Aç gözlerini yaradan için....

                                     (2005)', 'Sormadan hiçneden niçin  İçip her akşam hep senin için İçin için ağlar yüreğin  Aklım sende senin için... Kararmadan hep dışın için Son kade...', ARRAY['Türk Edebiyatı','Şiir','Abdulkadir İlyas']::text[], 8.5, '{"poet":"Abdulkadir İlyas","poet_slug":"abdulkadir-i-lyas","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sarhosa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korku', 'korku-gorkem-kizir-7gand', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sessiz çığlıklarımda boğuluyorum,

Dört duvar karanlık

Bir ışık görse koşacak yürek

Yalnızlığım kendimden büyük

Nefrete dönük yüreğim

İntikam hissi ile boğuluyorum

Acımasızların toprağında ceza

çekmek için yürüyorum', 'Sessiz çığlıklarımda boğuluyorum, Dört duvar karanlık Bir ışık görse koşacak yürek Yalnızlığım kendimden büyük Nefrete dönük yüreğim İntikam...', ARRAY['Türk Edebiyatı','Şiir','Görkem Kizir']::text[], 8.5, '{"poet":"Görkem Kizir","poet_slug":"gorkem-kizir","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/korku-97-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yok Olduk', 'yok-olduk-hande-yilmaz-fx30f', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'haykırmak, ağlamak ya da susmak

ne farkederdiki

bugün dün olmadıktan sonra

ölmek neyi değiştirirdi

ardı sıra ölümlerin öznel yıpratışlarında

günlerin her biri sen olsa

ne fayda...

ben o günlere varamadıktan sonra!', 'haykırmak, ağlamak ya da susmak ne farkederdiki bugün dün olmadıktan sonra ölmek neyi değiştirirdi ardı sıra ölümlerin öznel yıpratışlarında...', ARRAY['Türk Edebiyatı','Şiir','Hande Yılmaz']::text[], 8.5, '{"poet":"Hande Yılmaz","poet_slug":"hande-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yok-olduk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık Şarkıları', 'ayrilik-sarkilari-timur-i-likan-letz4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ayrılık şarkıları söylerim senin için

Aşkınla yanıyor yüreğim hep için için

Beni ansızın bırakıp gittin söyle niçin

Kederler, gamlar, hüzünler  şimdi benim için

Benim sensiz bir günüm bile geçmezdi canım

Sen çekip gidince hep eksik kaldı bir yanım

Birer birer yitip gitti bütün hülyâlarım

Bir tek senin için yağmur gibi gözyaşlarım

Seven yüreğim artık yaslı, gülmüyor yüzüm

Yollarda seni arıyor yaşlı iki gözüm

Senin tekrar bana geri dönmendir tek çözüm

Seni çok seviyorum aşkım budur son sözüm

(11 Ekim 2005/ İstanbul)', 'Ayrılık şarkıları söylerim senin için Aşkınla yanıyor yüreğim hep için için Beni ansızın bırakıp gittin söyle niçin Kederler, gamlar, hüzünl...', ARRAY['Türk Edebiyatı','Şiir','Timur İlikan']::text[], 8.5, '{"poet":"Timur İlikan","poet_slug":"timur-i-likan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ayrilik-sarkilari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hapislik', 'hapislik-hande-yilmaz-ex98f', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'kalamayanların kal''asından bile erken

vardığım sonların

bir sana varamayışının

kahrındayım bugün...

susup susup

haykıramayışlarımın sıcağında,

bir garip deryada

sarhoşum bugün...

tümlüğümden kopup sıçradığım

bütün mevzuların

kaybolmuşluğa verdiği sıkıntılardan ötürü

maphusum bugün; 

adını koyamadığım yaşları barındıran! ! !', 'kalamayanların kal''asından bile erken vardığım sonların bir sana varamayışının kahrındayım bugün... susup susup haykıramayışlarımın sıcağınd...', ARRAY['Türk Edebiyatı','Şiir','Hande Yılmaz']::text[], 8.5, '{"poet":"Hande Yılmaz","poet_slug":"hande-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/hapislik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamak', 'yasamak-omer-yildiz-bcq6k', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yaşamak,

Eğer

Bir yarışsa,

Yarışım 

Kendi kendimle...

Komşunun tavuğu 

Yine tavuktur 

Gözümde...', 'Yaşamak, Eğer Bir yarışsa, Yarışım  Kendi kendimle... Komşunun tavuğu  Yine tavuktur  Gözümde......', ARRAY['Türk Edebiyatı','Şiir','Ömer Yıldız']::text[], 8.5, '{"poet":"Ömer Yıldız","poet_slug":"omer-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yasamak-162-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yamalı pantolon', 'yamali-pantolon-elazigli-mustafa-kaya-17vys', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ruhumda

geçmeyen izlere

rastladım

yokluğa ve acılara

hepsi güzeldi

bugünlere taşıdı beni

kasım ayında doğmuşum

güz yıldızlarını

saya saya..

sarılmayan,

kanayan dizlerim vardı 

oyunlardan.

yamalı pantolonlardı

çocukluğum.

bilmediğim 

bir ağacın tepesiydi

son vurduğum kuşun yeri

sapan taşı isabet etti

koynumda sakladım

suçlarımı hem

hayallerimi

susuz bıraktım 

kendimi

şehirlerde nişan tahtası

yaptılar.

ruhumda

olmaması gereken yaralar

kapanmadı

geçmişime doğru akan

bir nehirde yıkandıkça

çoğaldı...

12.10.2005 / istanbul

Mustafa kaya

www.mustafakaya.net', 'ruhumda geçmeyen izlere rastladım yokluğa ve acılara hepsi güzeldi bugünlere taşıdı beni kasım ayında doğmuşum güz yıldızlarını saya saya.. ...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/yamali-pantolon-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ovçu', 'ovcu-ahmet-hani-73kdn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Pisdi yolun ay ovçu,

sinsin qolun ay ovçu.

Maral ile dolubdur,

sağın,solun ay ovçu.', 'Pisdi yolun ay ovçu, sinsin qolun ay ovçu. Maral ile dolubdur, sağın,solun ay ovçu....', ARRAY['Türk Edebiyatı','Şiir','Ahmet Hani']::text[], 8.5, '{"poet":"Ahmet Hani","poet_slug":"ahmet-hani","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ovcu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Satır araları', 'satir-aralari-elazigli-mustafa-kaya-3vnkd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'buruşmuş kağıtlar içinde satır arası birkaç güzel söze rastladım hüznümü 

yapayalnızlığımı karakalem yazmış,yüreğim üşümüş sokaklar hınca hınç

başkent caddeleri dar geliyor,sonbahar sonu kış başlangıcı insanlar kısa

bir sahte güzelliğin,mana fırlatan şuhluğu kenti dolduruyor çirkinlikler

deli dolu kafalara rastladım,aldırmadan yürüdüm boş ver denmeli mi

sıkışık arabalar,çığırtkan dolmuşlar,içimde biri mi var rahat değilim

konuş benimle dilsiz olma sırası değil,bir kaç söz  senden duysun 

sal gökyüzüne söyleyeceklerini,yarınlar adına sahtelik kalem mi

bazı yazılar vardı duvar olmuş küfür dolu kirli insan fikirleri çok

baştan sona hayasızlık, kabalık şarkı olmuş çıkmış öyle sahte 

bakma yazılanlara hakikat farklı,bekliyor ezanlar yeter ki duy

insanlar duysun, ıslak sokaklara yaygın yağmurlar üzerinde

bir daha sevmek mi? erişemediğim bir duygu nankör bir an

çocukları korkutuyor silahlar  kaçışlarımı yazamadım daha, 

medeniyet aldatmacası var kazıyamadım aşkımı bir ağaca 

sevgisiz çamur suratlılar  çığlık atıyor  dışarıdaki güneşe

çalıntıymış  bunca söz halkın emeği,  yıllarca kendileri

yapmadıkları kalmadı, belli,  çirkinlikleri  sözlerinden

eğlence artıkları sohbetleri halka zarar ziyan yüzsüz

yalanı  sevdirenlere  yuh, kuş yuvalarını bozdular, 

meraktan tut elimi hissedeyim hiç olmazsa sen

bu şehirde beni anla,kas katı değil kalbime bak

uçurtma uçurmak istedi içimde bir çocuk var

bahar kelebeklerini ürküttü insan  rüzgarlar 

karşı çıktım batıla kovalandı bu ayaklarım, 

gözyaşı,açlık,ve  savaşlar  çoğaldı durdu 

umursamaz bir dünya insanı mı olduk 

taştan şehirlerin taş bakışlı adamları

yonttular, bir kaç güzel insan  vardı 

ülke gelişiyor ıslık çalıyor  orada

iç ve dış ihanet durmuyor inatla

tuzak  kurdular  herkes  gördü

tarih unutmayacak yükselişi

hangi insan güzel, kim kirli

ot  biter  gibi   hain kimler

iflas eşiğinde  devletler

mutsuz insan yığınları

kahpe  rant   dünyası

çocukları acı korkuttu

rüyaları cinayet dolu

düşleri mavi  olsun

büyüsün çocuklar

bir hayalim vardı

barıştan  yana

bir  kaç   söz

içimde yaşar

nicedir azar

sevgi eksik

güler yüz

nerede? 

unuttu

insan

aşkı

dur

ma

a....

Mustafa kaya 

1983 / Ankara

www.mustafakaya.net', 'buruşmuş kağıtlar içinde satır arası birkaç güzel söze rastladım hüznümü  yapayalnızlığımı karakalem yazmış,yüreğim üşümüş sokaklar hınca hı...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":59,"source_url":"https://www.antoloji.com/satir-aralari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Galaksi', 'galaksi-elazigli-mustafa-kaya-akouq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '(‘’…O gün göğü yazı tomarlarını dürer gibi toplarız…’’.enbiya-104) 

galaksileri keşfe çıktım

bir çiçekti dünya

yarıp toprağını açan

karanlıklarda..

bir düş gördüm,

daha güzeldi renkleri

çiçeklerin..

ve daha mutluydu

insanların yüzleri 

selam dı sözleri..

Mustafa kaya

12.10.2005 / tuzla

www.mustafakaya.net', '(‘’…O gün göğü yazı tomarlarını dürer gibi toplarız…’’.enbiya-104)  galaksileri keşfe çıktım bir çiçekti dünya yarıp toprağını açan karanlık...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/galaksi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonbahar da bitiyor mu?', 'sonbahar-da-bitiyor-mu-ayse-gul-77brq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Lacivert gecenin

bahçesinde

bir

Gül ağacı

sonsuz  zamanların kısıyında...

Son yaprağını

d

...ö

...... k

..........e

...........r

.........k

......e

.......n

G ü l

ter döküyor

ölüm kokuyor...

Son Bahar

da

